    /// <summary>
    /// 相机自检 + 滚动步代价。
    ///
    /// 验两件事：
    ///   ① **正确性**：偏移之后，同一块画布内容必须出现在屏幕上偏移后的位置，
    ///      而**文档里的坐标一个都不变**——这是"滚动只改一个数、不动对象数据"的直接证据。
    ///   ② **代价**：滚动一步 = 整屏重画（第一步的已知边界）。按"一屏量级"与
    ///      "累积量级"分别量，就知道现在能扛到多少。
    /// </summary>
    private void CameraTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 相机自检 ===");
        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"    {name,-20}{(ok ? "PASS" : "FAIL")}  {detail}");
        }

        Doc.Clear();
        Doc.ClearHistory();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }

        float cx = _virtualX + 900, cy = _virtualY + 700;
        var s = new Stroke
        {
            Tool = Tool.Pen, Kind = StrokeKind.Freehand,
            Color = new Color4(1f, 0f, 1f, 1f), Width = 20f * DpiScale,   // 品红，好数像素
        };
        s.AddPoint(cx - 200, cy, 1f, 0);
        s.AddPoint(cx + 200, cy, 1f, 0);
        Doc.AddStroke(s);
        Doc.InvalidateAll();
        SettleFrames(400);

        int before = ScreenProbe.CountMagenta((int)cx - 60, (int)cy - 60, 120, 120);
        Check("偏移前在画布坐标处", before > 200, $"{before} 像素");

        float shift = 600f;
        ViewOffsetY = -shift;                        // 往下滚：内容上移
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = ViewOffsetY; }
        Doc.InvalidateAll();
        SettleFrames(400);

        int afterOld = ScreenProbe.CountMagenta((int)cx - 60, (int)cy - 60, 120, 120);
        int afterNew = ScreenProbe.CountMagenta((int)cx - 60, (int)(cy - shift) - 60, 120, 120);
        Check("原屏幕位置已清空", afterOld < 40, $"{afterOld} 像素");
        Check("墨到了偏移后的位置", afterNew > 200, $"{afterNew} 像素");
        Check("文档坐标未变", Math.Abs(s.Bounds.MinY - cy) < 0.01f,
              $"Bounds.MinY={s.Bounds.MinY:F1}");

        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        Doc.InvalidateAll();
        SettleFrames(400);
        int back = ScreenProbe.CountMagenta((int)cx - 60, (int)cy - 60, 120, 120);
        Check("滚回去仍在原位", back > 200, $"{back} 像素");
        Console.WriteLine($"  {(fail == 0 ? "PASS" : "FAIL")}：相机只改一个数，对象数据不动");

        ScrollBench();

        ViewOffsetY = 0f;
        Doc.Clear();
        Doc.ClearHistory();
        _quit = true;
    }

    /// <summary>
    /// 滚动代价：**走真实的滚轮路径**（HandleWheel），一格渲染一帧。
    ///
    /// 两条纪律：
    ///   · 不直接给 ViewOffsetY 赋值——那样绕开了 HandleWheel 的算术，上一轮
    ///     就是因此漏掉了"滚轮符号写反"这个 bug（还是用户报的）。
    ///   · 内容**铺开 8 屏**，不是塞在一屏里。真实板书是纵向累积的，塞一屏
    ///     是"满屏"的极端形状，衡量不了分块缓存要解决的"累积量"问题。
    ///
    /// 看三个数：每格平均帧耗时、最慢一格、以及这一格光栅化了几块。
    /// 分块缓存成立的标志是：**帧耗时与文档总量基本无关**——新露出来的
    /// 只有那么一小条，和文档里已经有多少笔没关系。
    /// </summary>
    private void ScrollBench()
    {
        Console.WriteLine();
        Console.WriteLine("=== 滚动代价（真实滚轮路径，一格 = 144 物理像素）===");
        Console.WriteLine("  内容铺开 8 屏（≈一节板书的量级），从顶部往下滚 12 格 ≈ 一屏");
        Console.WriteLine("    文档笔数 | 每格平均 | 最慢一格 | 一格光栅 | 最慢一格光栅 | 新光栅块 | 判断");
        Console.WriteLine("  -----------|----------|----------|----------|--------------|----------|------");

        // 和 WheelTest 用同一套构造方式：delta 放在 wParam 的高 16 位。
        static IntPtr Wheel(int delta) => new((long)(ushort)(short)delta << 16);
        const int steps = 12;

        foreach (int n in new[] { 1000, 5000, 10000 })
        {
            Doc.Clear();
            Doc.ClearHistory();
            ViewOffsetY = 0f;
            foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
            GenerateStrokesSpread(n, 8);
            SettleFrames(600);                       // 先把首屏画出来

            double total = 0, worst = 0, raster = 0, worstRaster = 0;
            int newTiles = 0;
            for (int k = 0; k < steps; k++)
            {
                HandleWheel(Wheel(-120));            // 往下滚一格
                NowMs = _clock.Elapsed.TotalMilliseconds;
                RenderAll();                         // 只渲染这一格

                var w0 = _windows[0];
                total += w0.LastRecordMs;
                raster += w0.LastRebuildMs;
                if (w0.LastRecordMs > worst) worst = w0.LastRecordMs;
                if (w0.LastRebuildMs > worstRaster) worstRaster = w0.LastRebuildMs;
                newTiles += w0.LastPatchCount;
            }

            string note = worst < 16.7 ? "不掉帧" : worst < 33 ? "偶掉一帧" : "会卡";
            Console.WriteLine($"  {n,9} | {total / steps,6:F2} ms | {worst,6:F2} ms | {raster / steps,6:F2} ms | {worstRaster,10:F2} ms | {newTiles,8} | {note}");
        }

        Console.WriteLine("  注：老做法（整层重画）的对照值：一屏量级 20ms，5000 笔 41ms，10000 笔 82ms。");
        Console.WriteLine("      现在滚一格的代价只和「新露出来的那一小条」有关，与文档总量无关。");
    }

    /// <summary>
    /// 把滚动条摆出来给人看：写满三屏内容，滚到中间，让滚动条处在"刚滚动过"的
    /// 露面状态，然后挂着不动由外部截图。
    /// </summary>
    private void ScrollShowcase()
    {
        Doc.Clear();
        Doc.ClearHistory();

        // 写满三屏：每屏几行，跨度超过一屏，滚动条才有比例可算
        for (int screen = 0; screen < 3; screen++)
        {
            for (int row = 0; row < 6; row++)
            {
                float y = _virtualY + screen * _virtualH + 250 + row * 240;
                var s = new Stroke
                {
                    Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                    Color = new Color4(0.11f, 0.12f, 0.15f, 1f), Width = 6f,
                };
                for (int i = 0; i <= 40; i++)
                {
                    float t = i / 40f;
                    s.AddPoint(_virtualX + 300 + t * 1200, y + MathF.Sin(t * 9f) * 30f, 0.5f, i * 8);
                }
                Doc.AddStroke(s);
            }
        }

        // 滚到中间，并让滚动条处于"刚滚动过"的状态（真实滚动会自己设这个时刻）
        ViewOffsetY = -_virtualH * 1.0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = ViewOffsetY; }
        ScrollBarActiveAtMs = NowMs;              // 相当于刚刚滚过
        Doc.InvalidateAll();
        SettleFrames(700);
        Console.WriteLine("滚动条已摆好（刚滚动过的状态），等外部截图");
    }

    /// <summary>
    /// 滚轮**算术**的自检。
    ///
    /// 这条是补课的：之前所有滚动测试都直接给 ViewOffsetY 赋值，
    /// **从没走过 HandleWheel 里那段加减**，于是"符号写反、往下滚永远滚不动"
    /// 这个 bug 一直没被测出来——还是用户报的。
    ///
    /// 直接构造 WM_MOUSEWHEEL 的 wParam（高 16 位是 delta）喂进去：
    ///   往下滚 delta = -120，ViewOffsetY 必须**变负**（内容上移）
    ///   往上滚到顶，必须夹在 0，不能越过
    /// </summary>
    private void WheelTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 滚轮算术自检 ===");
        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"    {name,-22}{(ok ? "PASS" : "FAIL")}  {detail}");
        }

        Doc.Clear();
        Doc.ClearHistory();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }

        // delta 放在 wParam 的高 16 位（低 16 位是按键状态，这里给 0）
        IntPtr Wheel(int delta) => new((long)(ushort)(short)delta << 16);
        float step = 72f * DpiScale;

        HandleWheel(Wheel(-120));
        Check("往下滚一格应向下", ViewOffsetY < -1f, $"ViewOffsetY={ViewOffsetY:F0}（应为 -{step:F0}）");
        Check("一格正好一个步长", Math.Abs(ViewOffsetY + step) < 0.6f, $"{ViewOffsetY:F0}");

        HandleWheel(Wheel(-120));
        HandleWheel(Wheel(-120));
        Check("连滚三格累加", Math.Abs(ViewOffsetY + step * 3f) < 1.2f, $"{ViewOffsetY:F0}");

        HandleWheel(Wheel(120));
        Check("往上滚一格回升", Math.Abs(ViewOffsetY + step * 2f) < 1.2f, $"{ViewOffsetY:F0}");

        for (int i = 0; i < 8; i++) HandleWheel(Wheel(120));
        Check("滚到顶夹在 0，不越过", Math.Abs(ViewOffsetY) < 0.01f, $"{ViewOffsetY:F0}");

        Console.WriteLine();
        Console.WriteLine($"  {(fail == 0 ? "PASS" : "FAIL")}：滚轮方向与夹取都正确");
        Doc.Clear();
        Doc.ClearHistory();
        _quit = true;
    }

    /// <summary>
    /// **白板底纹（方格 / 横线）自检**——用户 2026-09-17 要的，参考 InkClass。
    ///
    /// 判据是**数屏幕上的线**（不是看代码里那个开关）：
    ///   · 取一条横排像素 → 数"非板色"的段数 = 横着穿过几条**竖线**；
    ///   · 取一条竖排像素 → 段数 = 穿过几条**横线**。
    /// 于是：无底纹两个都是 0；横线只有横的；方格两个都有；间距变小线会变多。
    /// 最后再量一次**代价**：底纹是烘进分块缓存的，所以只有"换底纹那一下"要整层重铺，
    /// 之后每帧都不花钱——两个数都要报出来。
    /// </summary>
    private void PatternTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 白板底纹自检（方格 / 横线）===");
        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-30} {detail}");
        }

        Doc.Clear();
        Doc.ClearHistory();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        BoardOn = true;
        BoardColor = InkPalette.BoardPresets[0].Color;     // 白板（浅色）
        SetBoardPatternFromUi(0, 40f);
        SettleFrames(400);

        // 取屏幕正中偏右下的一块（避开 HUD 和面板），看里面的线
        int px = (int)(_virtualX + _virtualW * 0.35f), py = (int)(_virtualY + _virtualH * 0.35f);
        const int W = 400, H = 400;

        // 一条横排 / 一条竖排：数"和板色不一样"的连续段数
        (int vLines, int hLines) CountLines()
        {
            var buf = ScreenProbe.CaptureRegion(px, py, W, H);
            if (buf.Length < W * H * 4) return (-1, -1);
            int Row(int y)                      // 固定 y 扫一行 → 竖线
            {
                int runs = 0, o = (y * W) * 4;
                bool inLine = false;
                for (int x = 0; x < W; x++)
                {
                    int i = o + x * 4;
                    bool lit = buf[i] < 240 || buf[i + 1] < 240 || buf[i + 2] < 240;
                    if (lit && !inLine) runs++;
                    inLine = lit;
                }
                return runs;
            }
            int Col(int x)                      // 固定 x 扫一列 → 横线
            {
                int runs = 0;
                bool inLine = false;
                for (int y = 0; y < H; y++)
                {
                    int i = (y * W + x) * 4;
                    bool lit = buf[i] < 240 || buf[i + 1] < 240 || buf[i + 2] < 240;
                    if (lit && !inLine) runs++;
                    inLine = lit;
                }
                return runs;
            }
            // 多取几条取中位数（怕某一条正好压在线上）
            var vs = new List<int>(); var hs = new List<int>();
            for (int k = 1; k <= 5; k++) { vs.Add(Row(H * k / 6)); hs.Add(Col(W * k / 6)); }
            vs.Sort(); hs.Sort();
            return (vs[vs.Count / 2], hs[hs.Count / 2]);
        }

        var (v0, h0) = CountLines();
        Check("无底纹：屏幕上一根线都没有", v0 == 0 && h0 == 0, $"竖线 {v0} 条 / 横线 {h0} 条");

        SetBoardPatternFromUi(2, 40f);                     // 横线
        SettleFrames(400);
        var (v2, h2) = CountLines();
        Check("横线：只有横的、没有竖的", v2 == 0 && h2 >= 2, $"竖线 {v2} 条 / 横线 {h2} 条");

        SetBoardPatternFromUi(1, 40f);                     // 方格
        SettleFrames(400);
        var (v1, h1) = CountLines();
        Check("方格：横竖都有", v1 >= 2 && h1 >= 2, $"竖线 {v1} 条 / 横线 {h1} 条");

        SetBoardPatternFromUi(2, 64f);                     // 粗间距
        SettleFrames(400);
        var (_, h64) = CountLines();
        SetBoardPatternFromUi(2, 24f);                     // 细间距
        SettleFrames(400);
        var (_, h24) = CountLines();
        Check("间距生效：细间距的线明显更多", h24 > h64 && h64 >= 1,
              $"24 逻辑像素 → {h24} 条，64 → {h64} 条");

        // ---- 代价：只有"换底纹那一下"要整层重铺，之后每帧都不花钱 ----
        double Measure(bool patternOn, int rounds = 8)
        {
            double total = 0;
            for (int i = 0; i < rounds; i++)
            {
                Doc.InvalidateAll();                        // 逼一次整层重铺
                NowMs = _clock.Elapsed.TotalMilliseconds;
                RenderAll();
                total += _windows[0].LastRebuildMs;
            }
            return total / rounds;
        }

        SetBoardPatternFromUi(1, 40f); SettleFrames(300);
        double withPattern = Measure(true);
        // 再量一次"什么都不用重铺"的那一帧：底纹烘在缓存里，这应该是 0
        RenderAll();
        double idleRebuild = _windows[0].LastRebuildMs;

        SetBoardPatternFromUi(0, 40f); SettleFrames(300);
        double withoutPattern = Measure(false);

        Console.WriteLine($"    [性能] 整层重铺一格：有底纹 {withPattern:F2} ms，无底纹 {withoutPattern:F2} ms"
                        + $"（差 {withPattern - withoutPattern:F2} ms）");
        Console.WriteLine($"    [性能] 底纹画好之后的空闲帧：分块光栅 {idleRebuild:F2} ms（应为 0）");
        Check("底纹画好之后，空闲帧不再重铺分块", idleRebuild < 0.05,
              $"空闲帧分块光栅 {idleRebuild:F2} ms");
        Check("整层重铺的代价在可接受范围（< 8 ms）", withPattern < 8.0,
              $"有底纹 {withPattern:F2} ms（这是**换底纹那一下**的一次性代价，不是每帧）");

        // ---- 白板透明度（用户 2026-09-17："隐约看见下面的题目，但是书写有干净"）----
        {
            (byte R, byte G, byte B) ScreenPixel(int x, int y)
            {
                var buf = ScreenProbe.CaptureRegion(x, y, 1, 1);
                return buf.Length < 4 ? ((byte)0, (byte)0, (byte)0) : (buf[2], buf[1], buf[0]);
            }

            int ox = (int)(_virtualX + _virtualW * 0.55f), oy = (int)(_virtualY + _virtualH * 0.75f);
            BoardColor = InkPalette.BoardPresets[2].Color;      // 黑板（深色）：和桌面（浅色）差得远，好判
            SetBoardPatternFromUi(0, 40f);

            SetBoardOpacityFromUi(1f);
            SettleFrames(400);
            var solid = ScreenPixel(ox, oy);
            var wantBoard = InkPalette.BoardPresets[2].Color;
            Check("不透明度 1.0：屏幕上就是板色本身（实心板）",
                  Math.Abs(solid.R - wantBoard.R * 255) < 6 && Math.Abs(solid.G - wantBoard.G * 255) < 6
                  && Math.Abs(solid.B - wantBoard.B * 255) < 6,
                  $"实测 ({solid.R},{solid.G},{solid.B})，板色 ({(int)(wantBoard.R * 255)},{(int)(wantBoard.G * 255)},{(int)(wantBoard.B * 255)})");

            SetBoardOpacityFromUi(0.5f);
            SettleFrames(400);
            var half = ScreenPixel(ox, oy);
            Check("不透明度 0.5：板面变浅（下面的东西透出来了）",
                  half.R > solid.R + 20 || half.G > solid.G + 20 || half.B > solid.B + 20,
                  $"实心 ({solid.R},{solid.G},{solid.B}) → 半透 ({half.R},{half.G},{half.B})");

            // **书写仍然干净**：板面半透明时，笔迹像素还是纯的（不跟着变淡）
            var mag = new Stroke
            {
                Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 30f * DpiScale,
            };
            mag.AddPoint(ox - 100, oy + 160, 1f, 0);
            mag.AddPoint(ox + 100, oy + 160, 1f, 1);
            Doc.AddStroke(mag);
            SettleFrames(400);
            var inkPixel = ScreenPixel(ox, oy + 160);
            Check("板面半透明时，写上去的墨**仍然是实的**（不跟着变淡）",
                  inkPixel.R > 240 && inkPixel.G < 20 && inkPixel.B > 240,
                  $"墨色 ({inkPixel.R},{inkPixel.G},{inkPixel.B})（应为纯品红 255,0,255）");

            // 收尾：回到白板 + 实心 + 无底纹
            Doc.Clear();
            Doc.ClearHistory();
            BoardColor = InkPalette.BoardPresets[0].Color;
            SetBoardOpacityFromUi(1f);
            SettleFrames(250);
        }

        // 底纹不是笔迹：切底纹不该动文档
        var s = new Stroke
        {
            Tool = Tool.Pen, Kind = StrokeKind.Freehand,
            Color = new Color4(0f, 0f, 0f, 1f), Width = 6f,
        };
        s.AddPoint(_virtualX + 500, _virtualY + 500, 1f, 0);
        s.AddPoint(_virtualX + 900, _virtualY + 560, 1f, 1);
        Doc.AddStroke(s);
        SettleFrames(200);
        int before = Doc.Strokes.Count;
        SetBoardPatternFromUi(2, 40f);
        Check("换底纹不动文档（底纹不是笔迹）",
              Doc.Strokes.Count == before && Doc.UndoDepth == 1,
              $"笔画 {before} → {Doc.Strokes.Count}，撤销栈 {Doc.UndoDepth}（还是 1，底纹不进撤销）");

        Console.WriteLine();
        Console.WriteLine(fail == 0
            ? "  PASS：方格/横线/间距都对，而且底纹是烘进缓存的（只在换的时候花一次钱）"
            : $"  FAIL：{fail} 项不对（{pass} 项通过）");

        Doc.Clear();
        Doc.ClearHistory();
        BoardOn = false;
        SetBoardPatternFromUi(0, 40f);
        _quit = true;
    }

    /// <summary>
    /// **激光笔自检**（2026-09-27）。用户那天要的是 ClassIn 那个叫「**拖拽激光笔**」的工具：
    /// "只要我一直写，它就不会消失；等我停止写，过几秒以后它就会消失"。
    ///
    /// 盯五件事（前三件正是**和旧行为不一样**的地方）：
    ///   ① **写过整条不缩**：一直写，最早那个点必须还在
    ///      （旧行为是 600ms 的滑动窗口，写着写着开头就一直在丢）；
    ///   ② **松手后停留 2 秒**再整体淡出（旧行为是每个点自己 600ms 过期）；
    ///   ③ **多条并存**：抬手再写一条，前一条还在淡出，不能被顶掉；
    ///   ④ **粗细滑条真的管用**：量屏幕上那条红带有多宽
    ///      （旧的那个滑条只管落点那个圆点，轨迹宽度是写死的 13 / 6）；
    ///   ⑤ 老规矩：它**不是笔迹**（不进文档、不进撤销）。
    ///
    /// ⚠ 底一定要用**白板**量：这正是把加法混合换成 SourceOver 的原因——
    ///   加法只加亮，"红 + 白 = 白"，在浅底上整条轨迹会看不见（量出来就是 0 个像素）。
    /// </summary>
    private void LaserTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 激光笔自检（拖尾寿命 / 多条并存 / 粗细 / 不进文档）===");
        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-36} {detail}");
        }

        Doc.Clear();
        Doc.ClearHistory();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        // **不挂界面**：这一条量的、拍的都只有激光（内容层），挂上面板反而会让
        // 抓屏图里多出一颗面板球（见下面出图那一段）。
        BoardOn = true;
        BoardColor = InkPalette.BoardPresets[0].Color;     // 白板（浅底）
        SettleFrames(400);

        Tool = Tool.Laser;
        Laser.Clear();
        // 把落点藏起来（别让它混进"数红像素"那一条里）
        PointerInside = false;

        // ---- ① 一直写：整条留着，最早那个点不许被淘汰 ----
        float bx = _virtualX + _virtualW * 0.30f, by = _virtualY + _virtualH * 0.40f;
        double t0 = NowMs;
        Laser.Begin(bx, by, t0, LaserWidthLogical);
        float firstX = Laser.Strokes[0].Points[0].X;
        for (int i = 1; i <= 200; i++)
            // 每一步横着走 6 像素（远大于采样门槛 2.5），所以 200 个点应该一个不少
            Laser.Add(bx + i * 6f, by + MathF.Sin(i * 0.12f) * 40f, t0 + i * 16.0);

        int pts = Laser.Strokes.Count > 0 ? Laser.Strokes[0].Points.Count : 0;
        Check("一直写：整条都留着（201 个点一个不少）", pts == 201, $"点数 {pts}（期望 201）");
        Check("最老那个点还在（旧行为是 600ms 窗口，开头一直在丢）",
              Laser.Strokes.Count > 0
              && MathF.Abs(Laser.Strokes[0].Points[0].X - firstX) < 0.01f
              && Laser.Strokes[0].Points.Count > 1,
              $"首点 x {Laser.Strokes[0].Points[0].X:F1}（写下时 {firstX:F1}）");

        // ---- ② 松手：先停 2 秒（一点不淡），之后才开始淡，再淡完就没 ----
        double rel = t0 + 200 * 16.0;
        Laser.Release(rel);
        Laser.Prune(rel + 1000);
        Check("松手 1 秒：还在，而且**一点没淡**",
              Laser.Strokes.Count == 1 && Laser.Strokes[0].Fade == 0f,
              $"条数 {Laser.Strokes.Count}，Fade {(Laser.Strokes.Count > 0 ? Laser.Strokes[0].Fade : -1f):F2}");

        Laser.Prune(rel + LaserTrail.HoldMs + LaserTrail.FadeMs * 0.5);
        Check("过了停留期：开始淡（Fade 在 0 和 1 之间）",
              Laser.Strokes.Count == 1 && Laser.Strokes[0].Fade > 0.2f && Laser.Strokes[0].Fade < 0.95f,
              $"Fade {(Laser.Strokes.Count > 0 ? Laser.Strokes[0].Fade : -1f):F2}（期望 0.5 上下）");

        Laser.Prune(rel + LaserTrail.HoldMs + LaserTrail.FadeMs + 50);
        Check($"停留 {LaserTrail.HoldMs / 1000:F0} 秒 ＋ 淡出 {LaserTrail.FadeMs / 1000:F1} 秒之后：没了",
              Laser.Strokes.Count == 0, $"条数 {Laser.Strokes.Count}");

        // ---- ③ 多条并存 ＋ **整批共用一个计时**（用户 2026-09-27 报的那个 bug）----
        //
        // 用户原话："我第一笔写完写第二笔，第二笔写完写第三笔，只要它还在写，
        // 第一笔就不会消失。等最后写完以后，它们才会一起消失，是这个逻辑。"
        // 以前是**每条各算各的**（`Stroke.ReleasedAtMs`），第 1 条抬手早，
        // 于是第 2 条还在写的时候它就已经到点淡掉了——下面第二条断言量的就是它。
        Laser.Clear();
        double t3 = NowMs;
        Laser.Begin(bx, by, t3, LaserWidthLogical);
        Laser.Add(bx + 120f, by, t3 + 16);
        Laser.Release(t3 + 32);                        // 第 1 条：抬手了，正在停留
        Laser.Begin(bx, by + 240f, t3 + 120, LaserWidthLogical);   // 第 2 条：新起一条（还没抬手）
        Laser.Add(bx + 120f, by + 240f, t3 + 136);
        Check("抬手再写一条：**两条并存**（前一条还在停留，没被顶掉）",
              Laser.Strokes.Count == 2, $"条数 {Laser.Strokes.Count}（期望 2）");

        double t3b = t3 + 120;                          // 第 2 条按下那一刻
        Laser.Prune(t3b + LaserTrail.HoldMs * 3);       // 时间推到"第 1 条抬手后 6 秒"
        Check("第 2 条还在写：第 1 条**一点都没淡**（整批共用一个计时）",
              Laser.Strokes.Count == 2 && Laser.Strokes[0].Fade == 0f,
              $"条数 {Laser.Strokes.Count}，第 1 条 Fade {(Laser.Strokes.Count > 0 ? Laser.Strokes[0].Fade : -1f):F2}（期望 0）");

        Laser.Release(t3b + LaserTrail.HoldMs * 3);     // 最后一条也抬手 → 整批开始计时
        Laser.Prune(t3b + LaserTrail.HoldMs * 3 + LaserTrail.HoldMs + LaserTrail.FadeMs * 0.5);
        Check("最后一条抬手后：两条**一起**淡（Fade 一模一样）",
              Laser.Strokes.Count == 2
              && MathF.Abs(Laser.Strokes[0].Fade - Laser.Strokes[1].Fade) < 0.01f
              && Laser.Strokes[0].Fade > 0.2f && Laser.Strokes[0].Fade < 0.95f,
              $"两条 Fade {(Laser.Strokes.Count == 2 ? $"{Laser.Strokes[0].Fade:F2} / {Laser.Strokes[1].Fade:F2}" : "—")}（期望 0.5 上下且相等）");

        Laser.Prune(t3b + LaserTrail.HoldMs * 4 + LaserTrail.FadeMs + 50);
        Check("再等一下：两条**一起**没", Laser.Strokes.Count == 0, $"条数 {Laser.Strokes.Count}");

        // ---- ④ 粗细滑条真的管用：量屏幕上那条红带多宽 ----
        float lx0 = _virtualX + _virtualW * 0.28f, lx1 = _virtualX + _virtualW * 0.72f;
        float ly = _virtualY + _virtualH * 0.62f;
        int BandPixels(float logicalWidth)
        {
            SetWidthFromUi(logicalWidth);              // 走的就是拖那个滑条那条路
            Laser.Clear();
            double tn = NowMs;
            Laser.Begin(lx0, ly, tn, logicalWidth);
            for (float x = lx0 + 4f; x <= lx1; x += 4f) Laser.Add(x, ly, tn);
            Laser.Release(tn);
            SettleFrames(220);                         // 画上去（还在停留期，不会淡）
            // 在带子正中间竖着数"偏红"的像素（红边、柔光都算；中间那道白芯不算）
            int cxp = (int)((lx0 + lx1) * 0.5f);
            var buf = ScreenProbe.CaptureRegion(cxp, (int)ly - 90, 1, 180);
            int cnt = 0;
            for (int i = 0; i + 3 < buf.Length; i += 4)
            {
                int b = buf[i], g = buf[i + 1], r = buf[i + 2];
                if (b < 250 && r > g + 30 && r > b + 30) cnt++;
            }
            return cnt;
        }

        int thin = BandPixels(8f);                     // 现在这 3 档：8 / 14 / 22
        int thick = BandPixels(22f);
        Check("白板上看得见（加法混合会量出 0）", thin > 2, $"粗 8 时红带 {thin} 像素高");
        Check("粗细滑条**真的管用**（22 明显比 8 宽）",
              thick > thin * 1.8, $"粗 8 → {thin} 像素，粗 22 → {thick} 像素");

        // ---- ⑤ 不是笔迹 ----
        int strokesBefore = Doc.Strokes.Count, undoBefore = Doc.UndoDepth;
        Laser.Clear();
        double t5 = NowMs;
        Laser.Begin(lx0, ly, t5, LaserWidthLogical);
        Laser.Add(lx0 + 200f, ly + 60f, t5 + 16);
        Laser.Release(t5 + 32);
        SettleFrames(150);
        Check("激光轨迹**不是笔迹**（不进文档、不进撤销）",
              Doc.Strokes.Count == strokesBefore && Doc.UndoDepth == undoBefore,
              $"笔画 {strokesBefore} → {Doc.Strokes.Count}，撤销栈 {undoBefore} → {Doc.UndoDepth}");

        // ---- ⑥ 真按一遍鼠标：按下 → 拖 → 抬手（走引擎那条真路）----
        //
        // ⚠ 上面五条都是**直接调 `Laser` 那几个方法**，等于"我自己造了个对象、字段自己填"
        //   ——接线（`OnPointerDown → Begin`、`OnPointerUp → EndStroke → Release`）根本没测到。
        //   而这一轮最容易错的恰恰是接线：漏一个 `Release`，轨迹就永远"还在写"、永不淡出。
        Tool = Tool.Laser;
        SettleFrames(150);
        Laser.Clear();
        int mx = (int)(_virtualX + _virtualW * 0.30f), my = (int)(_virtualY + _virtualH * 0.28f);
        SendMouse(mx, my, 0);                              SettleFrames(60);
        SendMouse(mx, my, Native.MOUSEEVENTF_LEFTDOWN);    SettleFrames(60);
        for (int i = 1; i <= 20; i++)
        {
            SendMouse(mx + i * 12, my + i * 3, 0);
            SettleFrames(20);
        }
        SettleFrames(100);
        int livePts = Laser.Writing != null ? Laser.Writing.Points.Count : 0;
        Check("真按着鼠标拖：轨迹在长（说明按下那条接线通了）",
              livePts > 5, $"点数 {livePts}（期望 > 5）");

        SendMouse(mx + 240, my + 60, Native.MOUSEEVENTF_LEFTUP);
        SettleFrames(250);
        Check("真抬手：不再\"还在写\"了，进入停留期（说明抬手那条接线通了）",
              Laser.Writing == null && Laser.Strokes.Count >= 1 && Laser.Strokes[^1].Fade == 0f,
              $"正在写 = {(Laser.Writing == null ? "无（对）" : "还在写（错）")}，条数 {Laser.Strokes.Count}");

        // ---- 出图：摆样好不好看，自检判不了（摆三笔不同粗细，给人看）----
        Laser.Clear();
        double tg = NowMs;
        for (int k = 0; k < 3; k++)
        {
            float gw = k == 0 ? 8f : k == 1 ? 15f : 22f;   // 细 / 中 / 粗三档，给人看粗细范围
            SetWidthFromUi(gw);
            float sy = _virtualY + _virtualH * (0.30f + k * 0.18f);
            Laser.Begin(_virtualX + _virtualW * 0.16f, sy + 40f, tg, gw);
            for (int i = 1; i <= 60; i++)
                Laser.Add(_virtualX + _virtualW * (0.16f + i * 0.011f), sy - i * 1.1f, tg + i * 8.0);
            Laser.Release(tg + 16);
        }
        Laser.Prune(NowMs);            // 都在停留期，一个都不会掉
        SettleFrames(300);
        // ⚠ **不能用 `OffscreenShot`**：那条路只画**界面层**（面板），
        //   而激光画在**内容层**上（`Overlay.DrawLaser`）——出出来的图里只有面板、
        //   一条轨迹都没有（第一版就是这么白出一张的，看图才发现）。
        //   所以这里走"自己抓屏"，和 `--pixeleraseshow` 同一条路。
        int capX = (int)_virtualX, capY = (int)_virtualY;
        int capW = (int)_virtualW, capH = (int)_virtualH;
        bool shotOk = ScreenProbe.SaveBmp("reports/laser-trail.png", capX, capY, capW, capH);
        Console.WriteLine(shotOk
            ? "  已出图 reports/laser-trail.png（三笔不同粗细，白色底，自己抓屏）"
            : "  出图失败");

        Console.WriteLine();
        Console.WriteLine(fail == 0
            ? "  PASS：拖尾一直写不缩、松手停 2 秒再整体淡出（整批一起）、多条并存、粗细真的管用、而且不是笔迹"
            : $"  FAIL：{fail} 项不对（{pass} 项通过）");

        Laser.Clear();
        Doc.Clear();
        Doc.ClearHistory();
        BoardOn = false;
        SetWidthFromUi(8f);            // 激光的默认档（见 Engine.LaserWidthPresets）
        Tool = Tool.Pen;
        _quit = true;
    }

    /// <summary>
    /// **导出（选中的内容 → 透明底 PNG）自检**。
    ///
    /// 用户 2026-09-17 定：只导选中的、透明底、弹"另存为"、**同时进剪贴板**。
    /// 这里不走对话框（对话框在自检里会卡住），直接写到临时文件，其余流程一模一样。
    ///
    /// 关键是**把 PNG 解回来验像素**：PNG 要的是直通 alpha，而我们渲染出来的是
    /// 预乘 alpha——不还原就发灰（半透明荧光笔最明显），而这条错误光看"文件写出来了"
    /// 是发现不了的。所以这里自己解 IDAT（inflate ＋ 去 filter 字节）抽像素比。
    /// </summary>
    private void IoTest(string keepPath = null)
    {
        Console.WriteLine();
        Console.WriteLine("=== 导出自检（选中 → PNG 透明底 / JPEG 白底；不碰剪贴板）===");
        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-34} {detail}");
        }

        string path = keepPath ?? Path.Combine(Path.GetTempPath(), "inkteach-iotest.png");
        if (keepPath == null) { try { File.Delete(path); } catch { } }

        Doc.Clear();
        Doc.ClearHistory();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        SettleFrames(200);

        // ① 没选中 → 不导出、也不该留下文件
        bool ok0 = ExportSelectionToPathForTest(path);
        Check("没选中时不导出、不写文件", !ok0 && !File.Exists(path),
              $"返回 {ok0}，文件在 = {File.Exists(path)}");

        // ② 一笔实心笔 ＋ 一笔半透明荧光笔，全选中
        var red = new Color4(0.95f, 0.18f, 0.18f, 1f);
        var yellow = new Color4(0.98f, 0.82f, 0.12f, 1f);
        var pen = new Stroke
        {
            Tool = Tool.Pen, Kind = StrokeKind.Freehand,
            Color = red, Width = 20f * DpiScale,
        };
        for (int i = 0; i <= 20; i++) pen.AddPoint(600 + i * 10, 400, 1f, i * 8);
        Doc.AddStroke(pen);

        var hlColor = InkPalette.ToHighlighter(yellow);
        var hl = new Stroke
        {
            Tool = Tool.Highlighter, Kind = StrokeKind.Freehand,
            Color = hlColor, Width = 40f * DpiScale,
        };
        for (int i = 0; i <= 20; i++) hl.AddPoint(600 + i * 10, 500, 1f, i * 8);
        Doc.AddStroke(hl);
        Doc.SelectOnly(new[] { pen, hl });
        Tool = Tool.Marquee;
        SettleFrames(300);

        // 先在剪贴板上放一个"标记"（一条蓝色笔迹）：导出之后它必须**原样还在**——
        // 用户 2026-09-17 明确："导出不用进剪贴板，因为我们有复制功能"。
        var marker = new Stroke
        {
            Tool = Tool.Pen, Kind = StrokeKind.Freehand,
            Color = new Color4(0f, 0f, 1f, 1f), Width = 5f,
        };
        marker.AddPoint(10, 10, 1f, 0); marker.AddPoint(20, 20, 1f, 1);
        ClipboardInk.Set(ClipboardInk.Serialize(new[] { marker }), null, 0, 0);

        bool ok = ExportSelectionToPathForTest(path);
        Check("导出返回成功", ok, $"返回 {ok}");
        if (!ok || !File.Exists(path))
        {
            Console.WriteLine($"  FAIL: 文件没写出来，后面几项没法验（{fail} 项失败）");
            _quit = true;
            return;
        }

        var png = File.ReadAllBytes(path);
        Check("文件非空", png.Length > 100, $"{png.Length} 字节");
        Check("PNG 签名正确",
              png.Length > 8 && png[0] == 0x89 && png[1] == 0x50 && png[2] == 0x4E && png[3] == 0x47,
              $"{png[0]:X2} {png[1]:X2} {png[2]:X2} {png[3]:X2}");

        // ③ 解回像素：走 chunks → 拼 IDAT → inflate → 去每行的 filter 字节
        int iw = 0, ih = 0;
        var idat = new MemoryStream();
        int p = 8;
        while (p + 8 <= png.Length)
        {
            int len = (png[p] << 24) | (png[p + 1] << 16) | (png[p + 2] << 8) | png[p + 3];
            string type = "" + (char)png[p + 4] + (char)png[p + 5] + (char)png[p + 6] + (char)png[p + 7];
            int dataAt = p + 8;
            if (type == "IHDR")
            {
                iw = (png[dataAt] << 24) | (png[dataAt + 1] << 16) | (png[dataAt + 2] << 8) | png[dataAt + 3];
                ih = (png[dataAt + 4] << 24) | (png[dataAt + 5] << 16) | (png[dataAt + 6] << 8) | png[dataAt + 7];
            }
            else if (type == "IDAT") idat.Write(png, dataAt, len);
            p = dataAt + len + 4;
        }

        var box = EditRegion.Of(new[] { pen, hl }).Inflate(4f * DpiScale);
        int wantW = (int)MathF.Ceiling(box.MaxX - box.MinX);
        int wantH = (int)MathF.Ceiling(box.MaxY - box.MinY);
        Check("IHDR 的宽高 = 选区像素尺寸", iw == wantW && ih == wantH,
              $"图 {iw}×{ih}，选区 {wantW}×{wantH}");

        // inflate：zlib 头 2 字节 ＋ 尾部 adler32 4 字节，中间是裸 deflate
        var z = idat.ToArray();
        byte[] raw;
        using (var ms = new MemoryStream(z, 2, z.Length - 6))
        using (var inf = new System.IO.Compression.DeflateStream(ms, System.IO.Compression.CompressionMode.Decompress))
        using (var outMs = new MemoryStream())
        {
            inf.CopyTo(outMs);
            raw = outMs.ToArray();
        }
        Check("IDAT 能解回原始像素（每行 1 个 filter 字节）",
              raw.Length >= ih * (1 + iw * 4), $"{raw.Length} 字节（应为 {ih * (1 + iw * 4)}）");

        (byte R, byte G, byte B, byte A) PixelAt(float canvasX, float canvasY)
        {
            int x = Math.Clamp((int)(canvasX - box.MinX), 0, iw - 1);
            int y = Math.Clamp((int)(canvasY - box.MinY), 0, ih - 1);
            int o = y * (1 + iw * 4) + 1 + x * 4;
            return (raw[o], raw[o + 1], raw[o + 2], raw[o + 3]);
        }

        var px = PixelAt(700, 400);           // 红笔的中心
        Check("实心笔：不透明、颜色就是笔色",
              px.A == 255
              && Math.Abs(px.R - red.R * 255) < 6 && Math.Abs(px.G - red.G * 255) < 6
              && Math.Abs(px.B - red.B * 255) < 6,
              $"RGBA = {px.R},{px.G},{px.B},{px.A}（应为 {(int)(red.R * 255)},{(int)(red.G * 255)},{(int)(red.B * 255)},255）");

        var hp = PixelAt(700, 500);           // 荧光笔的中心
        int wantA = (int)(hlColor.A * 255);
        Check("荧光笔：半透明（没被压成不透明）",
              hp.A > 20 && hp.A < 250, $"alpha = {hp.A}（应为 {wantA} 上下）");
        // 预乘 → 直通没做对的话，这里会明显偏暗（R 会从 ~250 掉到 ~80）
        Check("荧光笔：颜色是**直通 alpha**（预乘没还原就会发灰）",
              Math.Abs(hp.R - yellow.R * 255) < 12 && Math.Abs(hp.G - yellow.G * 255) < 12
              && Math.Abs(hp.B - yellow.B * 255) < 12,
              $"RGB = {hp.R},{hp.G},{hp.B}（应为 {(int)(yellow.R * 255)},{(int)(yellow.G * 255)},{(int)(yellow.B * 255)}）");

        var blank = PixelAt(300, 300);        // 选区左上角那块（没有墨）
        Check("空白处：完全透明（透明底）", blank.A == 0 && blank.R == 0 && blank.G == 0 && blank.B == 0,
              $"RGBA = {blank.R},{blank.G},{blank.B},{blank.A}");

        // ④ 剪贴板：导出**不许动它**（用户 2026-09-17："导出不用进剪贴板，我们有复制功能"）。
        // 判据：导出前放一条"标记"笔迹，导出之后读回来还得是那一条（1 个，不是选中的 2 个）。
        bool clip = ClipboardInk.TryGetObjects(out var back);
        Check("导出**不动剪贴板**（复制那条路各管各的）",
              clip && back != null && back.Count == 1,
              clip ? $"读回 {back?.Count} 个对象（应为 1 = 导出前放的那条标记）"
                   : "剪贴板里没有对象（不该）");

        // ⑤ 另一种格式：**JPEG（白底）**——用户 2026-09-17："导出功能增加 jpg 格式，
        //    然后让用户知道 png 是透明底、jpg 是白底"。格式差别写在文件类型那一行，
        //    这里验的是"真按 JPG 编码了、而且透明处是白的（不是黑的）"。
        string jpgPath = System.IO.Path.ChangeExtension(path, ".jpg");
        try { File.Delete(jpgPath); } catch { }
        bool okJpg = ExportSelectionToPathForTest(jpgPath);
        Check("导出成 .jpg：返回成功、文件存在", okJpg && File.Exists(jpgPath),
              $"返回 {okJpg}，文件在 = {File.Exists(jpgPath)}");
        if (File.Exists(jpgPath))
        {
            var jpg = File.ReadAllBytes(jpgPath);
            Check("是真正的 JPEG（FF D8 FF 开头）",
                  jpg.Length > 4 && jpg[0] == 0xFF && jpg[1] == 0xD8 && jpg[2] == 0xFF,
                  $"{jpg[0]:X2} {jpg[1]:X2} {jpg[2]:X2}，{jpg.Length / 1024.0:F0} KB");
            // 解码回来验像素：GDI+ 解、和我们编码用的不是同一段代码
            try
            {
                using var bmp = new System.Drawing.Bitmap(jpgPath);
                Check("JPEG 尺寸 = 选区像素尺寸", bmp.Width == wantW && bmp.Height == wantH,
                      $"{bmp.Width}×{bmp.Height}，选区 {wantW}×{wantH}");
                // 空白处（原来透明）必须是**白**的——JPEG 没有透明通道，
                // 不合成白底的话那里会是黑块（很多程序都踩过）
                var blankPx = bmp.GetPixel(20, 20);
                Check("原来透明的地方变成**白底**（不是黑块）",
                      blankPx.R > 235 && blankPx.G > 235 && blankPx.B > 235,
                      $"({blankPx.R},{blankPx.G},{blankPx.B})");
                // 笔迹颜色还在（JPEG 有损，给宽一点的容差）
                var penPx = bmp.GetPixel(Math.Clamp((int)(700 - box.MinX), 0, bmp.Width - 1),
                                         Math.Clamp((int)(400 - box.MinY), 0, bmp.Height - 1));
                Check("笔迹颜色还在（有损压缩，允许偏差）",
                      Math.Abs(penPx.R - red.R * 255) < 40 && penPx.G < 110 && penPx.B < 110,
                      $"({penPx.R},{penPx.G},{penPx.B})，原笔色 ({(int)(red.R * 255)},{(int)(red.G * 255)},{(int)(red.B * 255)})");
            }
            catch (Exception ex) { Check("JPEG 能被别的解码器读出来", false, ex.Message); }
            try { File.Delete(jpgPath); } catch { }
        }

        // ⑥ **PNG 白底**（第 3 条）：无损 + 白底。
        //    给"深色模板"用的——透明底的黑色笔迹贴到深色 PPT 上会看不见。
        //    注意它和第 1 条**同一个扩展名**，差别只在"选了哪一条"，
        //    所以这里必须传 filterIndex=3，不能靠扩展名区分。
        {
            string whiteP = Path.Combine(Path.GetTempPath(), "inkteach-iotest-white.png");
            try { File.Delete(whiteP); } catch { }
            bool okW = ExportSelectionToPathForTest(whiteP, 3);
            Check("导出成「PNG 白底」（第 3 条）：文件存在", okW && File.Exists(whiteP), $"返回 {okW}");
            if (File.Exists(whiteP))
            {
                var bytes = File.ReadAllBytes(whiteP);
                Check("还是 PNG 签名（同一条扩展名，两个选择）",
                      bytes.Length > 8 && bytes[0] == 0x89 && bytes[3] == 0x47,
                      $"{bytes[0]:X2} {bytes[1]:X2} {bytes[2]:X2} {bytes[3]:X2}");
                try
                {
                    using var bmp = new System.Drawing.Bitmap(whiteP);
                    var blankPx = bmp.GetPixel(20, 20);
                    Check("空白处是**白底**（透明底那条这里是全透明）",
                          blankPx.R > 250 && blankPx.G > 250 && blankPx.B > 250 && blankPx.A == 255,
                          $"({blankPx.R},{blankPx.G},{blankPx.B},a={blankPx.A})");
                    var penPx = bmp.GetPixel(Math.Clamp((int)(700 - box.MinX), 0, bmp.Width - 1),
                                             Math.Clamp((int)(400 - box.MinY), 0, bmp.Height - 1));
                    Check("笔迹颜色**一个不差**（无损，不是 JPEG 那种有损）",
                          Math.Abs(penPx.R - red.R * 255) < 4
                          && Math.Abs(penPx.G - red.G * 255) < 4
                          && Math.Abs(penPx.B - red.B * 255) < 4,
                          $"({penPx.R},{penPx.G},{penPx.B})");
                }
                catch (Exception ex) { Check("白底 PNG 能被别的解码器读出来", false, ex.Message); }
                try { File.Delete(whiteP); } catch { }
            }
        }

        // ⑦ **BMP 白底**（第 4 条）：老软件也打得开的无损位图。
        //    自己写的编码器，所以逐字段验：签名、宽高、位深、以及**像素真的是白的和白底**。
        {
            string bmpPath = Path.Combine(Path.GetTempPath(), "inkteach-iotest.bmp");
            try { File.Delete(bmpPath); } catch { }
            bool okB = ExportSelectionToPathForTest(bmpPath, 4);
            Check("导出成 .bmp：返回成功、文件存在", okB && File.Exists(bmpPath),
                  $"返回 {okB}，文件在 = {File.Exists(bmpPath)}");
            if (File.Exists(bmpPath))
            {
                var b = File.ReadAllBytes(bmpPath);
                int bw = b[18] | (b[19] << 8) | (b[20] << 16) | (b[21] << 24);
                int bh = b[22] | (b[23] << 8) | (b[24] << 16) | (b[25] << 24);
                int bits = b[28] | (b[29] << 8);
                int off = b[10] | (b[11] << 8) | (b[12] << 16) | (b[13] << 24);
                Check("BMP 文件头：'BM' + 宽高 + 24 位",
                      b[0] == (byte)'B' && b[1] == (byte)'M' && bw == wantW && bh == wantH && bits == 24,
                      $"{(char)b[0]}{(char)b[1]}，{bw}×{bh}，{bits} 位，像素起点 {off}，{b.Length / 1024.0:F0} KB");

                // **用别的解码器读**（GDI+），不自己解——自己解只能证明"我写的我自己读得懂"，
                // 证不了这个文件在别的程序里对不对（和上面 JPEG 那条同一个道理）。
                try
                {
                    using var bmpImg = new System.Drawing.Bitmap(bmpPath);
                    Check("GDI+ 也读得出来（尺寸对）",
                          bmpImg.Width == wantW && bmpImg.Height == wantH,
                          $"{bmpImg.Width}×{bmpImg.Height}");
                    var blankPx = bmpImg.GetPixel(20, 20);
                    Check("空白处是**白底**（不是黑块、不是透明）",
                          blankPx.R > 250 && blankPx.G > 250 && blankPx.B > 250,
                          $"({blankPx.R},{blankPx.G},{blankPx.B})");
                    var penPx = bmpImg.GetPixel(Math.Clamp((int)(700 - box.MinX), 0, bmpImg.Width - 1),
                                                Math.Clamp((int)(400 - box.MinY), 0, bmpImg.Height - 1));
                    Check("笔迹颜色**一个不差**（无损）",
                          Math.Abs(penPx.R - red.R * 255) < 4
                          && Math.Abs(penPx.G - red.G * 255) < 4
                          && Math.Abs(penPx.B - red.B * 255) < 4,
                          $"({penPx.R},{penPx.G},{penPx.B})");
                    // 反过来：**上下不能颠倒**（BMP 是自下而上存的，写反了图是扣着的）
                    var topRow = bmpImg.GetPixel(Math.Clamp((int)(700 - box.MinX), 0, bmpImg.Width - 1), 1);
                    Check("上下没写反（最上一行是空白，不是笔迹）",
                          topRow.R > 250 && topRow.G > 250 && topRow.B > 250,
                          $"最上一行 ({topRow.R},{topRow.G},{topRow.B})");
                }
                catch (Exception ex) { Check("BMP 能被别的解码器读出来", false, ex.Message); }
                try { File.Delete(bmpPath); } catch { }
            }
        }

        Console.WriteLine();
        Console.WriteLine(fail == 0
            ? "  PASS：四种格式都对（PNG 透明底 / JPEG 白底 / PNG 白底 / BMP 白底，逐像素验过），而且没碰剪贴板"
            : $"  FAIL：{fail} 项不对（{pass} 项通过）");
        Console.WriteLine($"  文件：{path}（{png.Length} 字节）");

        // 给了路径就留着（人工核对 / 拿别的解码器验它）
        if (keepPath == null) { try { File.Delete(path); } catch { } }
        Doc.Clear();
        Doc.ClearHistory();
        _quit = true;
    }

    /// <summary>
    /// `--ppttest`：**PPT 模式自检**（用户 2026-09-26 拍板"参考 InkClass 原味"）。
    ///
    /// 用**假页码源**驱动（`PptFakeSource`）——我这边没有 PowerPoint 环境，
    /// 产品那条 COM 连接由用户在装了 PPT / WPS 的机器上跑 `--pptprobe` 确认。
    /// 假源和真源走的是**同一份状态机**（`StepPpt` → `ApplyPptState`），
    /// 所以这里验过的"进放映 / 翻页 / 存取 / 退出恢复"在真机上就是同一段代码。
    ///
    /// 验的九件事（对应参考来的语义 + 我们的两处适配）：
    ///   ① 进放映 = 切到 PPT 页，桌面批注**看不见**（完全隔离）；
    ///   ② 每页一套内容：翻页看不到别页、翻回来原样；
    ///   ③ **页内照样能滚动**，而且每页记住自己滚到哪（用户要的"我依然支持向下滚动"）；
    ///   ④ 清空只清本页（InkClass 的语义）；撤销栈也是每页一套；
    ///   ⑤ 翻页时**先存上一页**（防一节课中途崩了丢东西）；
    ///   ⑥ 退出放映 = 逐页写盘 + 回桌面页（桌面批注原样回来）；
    ///   ⑦ 再进放映 = 从盘里读回（模拟"关软件再打开、下一节课接着讲"）；
    ///   ⑧ 界面按钮那条路：命令走 PPT（`fake.NextCalls` 涨），页跟着变；
    ///   ⑨ 没有 PPT / 连不上时一个字都不发生（没装 Office 的机器上零症状）。
    /// </summary>
    private void PptTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== PPT 模式自检（假页码源驱动）===");

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-34} {detail}");
        }

        // 自检**绝不碰用户真实的 PPT 批注**：把根目录指到临时目录（同 Recovery 的套路）。
        PptStore.RootOverride = Path.Combine(Path.GetTempPath(), "inkteach-ppttest");
        try { if (Directory.Exists(PptStore.RootOverride)) Directory.Delete(PptStore.RootOverride, true); } catch { }

        // 干净起手：只有 0 号桌面页、相机归零
        Doc.ResetToSinglePage();
        Doc.ClearHistory();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        Doc.InvalidateAll();
        SettleFrames(150);

        var fake = new PptFakeSource();
        AttachPptSource(fake, watch: false);
        void Step() { StepPpt(); SettleFrames(50); }
        IntPtr Wheel(int delta) => new((long)(ushort)(short)delta << 16);
        int penSeq = 0;
        void MakePen(float x, float y)
        {
            var s = new Stroke
            {
                Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                Color = new Color4(0.12f, 0.13f, 0.16f, 1f), Width = 8f,
            };
            s.AddPoint(x, y, 1f, 0);
            s.AddPoint(x + 160f, y + 30f, 1f, 8);
            int seq = penSeq++;
            s.AddPoint(x + 240f, y + (seq % 3) * 20f, 1f, 16);   // 让每笔略有不同
            Doc.AddStroke(s);
        }

        // 桌面批注：进放映前写 3 笔（它们必须"进得去、出得来"）
        for (int i = 0; i < 3; i++) MakePen(300 + i * 70, 320);
        SettleFrames(100);
        Check("桌面页起手 3 笔", Doc.Strokes.Count == 3, $"{Doc.Strokes.Count} 条");

        // ---- ① 进放映 ----
        fake.Showing = true; fake.Slide = 1; fake.SlideId = 256; fake.Total = 3;
        Step();
        Check("进放映：进入 PPT 模式", PptMode, $"PptMode={PptMode}");
        Check("进放映：切到第 1 页（键 = SlideID）", Doc.PageKey == 256, $"页键 {Doc.PageKey}");
        Check("进放映：桌面批注**看不见了**（完全隔离）", Doc.Strokes.Count == 0, $"{Doc.Strokes.Count} 条");

        // ---- ② 每页一套 + 页内滚动 ----
        MakePen(400, 420);
        MakePen(520, 420);
        Check("第 1 页写了 2 笔", Doc.Strokes.Count == 2, $"{Doc.Strokes.Count} 条");

        HandleWheel(Wheel(-120));
        SettleFrames(120);
        float scrolled = ViewOffsetY;
        Check("PPT 页内**照样能滚动**（用户要的那条）", scrolled < -1f, $"相机 {scrolled:F0}");

        fake.Slide = 2; fake.SlideId = 257;
        Step();
        Check("翻到第 2 页", Doc.PageKey == 257, $"页键 {Doc.PageKey}");
        Check("第 2 页是**空的**（隔离的另一半）", Doc.Strokes.Count == 0, $"{Doc.Strokes.Count} 条");
        Check("翻到没去过的页：相机归零", Math.Abs(ViewOffsetY) < 0.01f, $"相机 {ViewOffsetY:F2}");
        MakePen(600, 520);

        fake.Slide = 1; fake.SlideId = 256;
        Step();
        Check("翻回第 1 页：2 笔都在", Doc.Strokes.Count == 2, $"{Doc.Strokes.Count} 条");
        Check("翻回第 1 页：**滚到哪还记得**",
              Math.Abs(ViewOffsetY - scrolled) < 2f, $"相机 {ViewOffsetY:F0}（原来 {scrolled:F0}）");
        Check("页面条数字（界面显示 n/N 用）",
              PptSlide == 1 && PptTotal == 3, $"{PptSlide}/{PptTotal}");

        // ---- ④ 清空只清本页 ----
        ClearFromUi();
        SettleFrames(150);
        Check("清空：只清第 1 页", Doc.Strokes.Count == 0, $"{Doc.Strokes.Count} 条");
        fake.Slide = 2; fake.SlideId = 257;
        Step();
        Check("清空：第 2 页那 1 笔**还在**", Doc.Strokes.Count == 1, $"{Doc.Strokes.Count} 条");

        // ---- 撤销栈每页一套（参考 InkClass 的 TimeMachineHistories[页]）----
        UndoFromUi();
        SettleFrames(100);
        Check("撤销：第 2 页撤得掉自己那笔", Doc.Strokes.Count == 0, $"{Doc.Strokes.Count} 条");
        RedoFromUi();
        SettleFrames(100);
        Check("重做：又回来了", Doc.Strokes.Count == 1, $"{Doc.Strokes.Count} 条");

        // 回到第 1 页补 2 笔（给"退出放映写盘"准备内容）
        fake.Slide = 1; fake.SlideId = 256;
        Step();
        MakePen(700, 460);
        MakePen(760, 500);
        int page1Count = Doc.Strokes.Count;
        Check("第 1 页补到 2 笔（清空后重写）", page1Count == 2, $"{page1Count} 条");

        // ---- ⑥ 退出放映：写盘 + 回桌面 ----
        fake.Showing = false;
        Step();
        Check("退出放映：退出 PPT 模式", !PptMode, $"PptMode={PptMode}");
        Check("退出放映：回到 0 号页", Doc.PageKey == 0, $"页键 {Doc.PageKey}");
        Check("退出放映：桌面 3 笔**原样回来**", Doc.Strokes.Count == 3, $"{Doc.Strokes.Count} 条");

        var savedKeys = PptStore.ListPageKeys(fake.Key);
        savedKeys.Sort();
        Check("退出放映：两页都写了盘（且不含桌面页）",
              savedKeys.Count == 2 && savedKeys[0] == 256 && savedKeys[1] == 257,
              $"盘上 {savedKeys.Count} 页：{string.Join(",", savedKeys)}");
        Check("退出放映：Position 记了页码", PptStore.LoadPosition(fake.Key) == 1,
              $"记的是 {PptStore.LoadPosition(fake.Key)}");

        // ---- ⑨ 没有 PPT 时：一个字都不发生 ----
        // ⚠ 顺序有讲究：下面 ⑦ 会 `ResetToSinglePage` **模拟"关掉软件"**——那一句
        // 会把内存里的页全丢掉（**包括桌面页**；桌面批注靠自动存档那条路持久化，
        // 不归 PPT 模式管），所以"桌面批注还在吗"这一条必须排在它之前。
        fake.Showing = false; fake.Connected = false;
        Step();
        Check("连不上 PPT：退出 PPT 模式、回桌面页", !PptMode && Doc.PageKey == 0,
              $"PptMode={PptMode}，页键 {Doc.PageKey}");
        Check("连不上 PPT：桌面批注还在（没被谁清掉）", Doc.Strokes.Count == 3, $"{Doc.Strokes.Count} 条");
        fake.Connected = true;
        Step();

        // ---- ⑦ 再进放映：从盘里读回（模拟关掉软件再打开）----
        Doc.ResetToSinglePage();                    // 内存里的页全丢掉
        Check("（模拟关软件：内存里一页都不剩）",
              Doc.Strokes.Count == 0 && Doc.PageKey == 0, $"页键 {Doc.PageKey}");
        fake.Showing = true; fake.Slide = 1; fake.SlideId = 256;
        Step();
        Check("再进放映：第 1 页从盘里读回来（2 笔）", Doc.Strokes.Count == 2, $"{Doc.Strokes.Count} 条");
        fake.Slide = 2; fake.SlideId = 257;
        Step();
        Check("再进放映：第 2 页也读回来（1 笔）", Doc.Strokes.Count == 1, $"{Doc.Strokes.Count} 条");

        // ---- ⑧ 界面按钮那条路：命令走 PPT、页跟着变 ----
        int nextBefore = fake.NextCalls;
        PptNextFromUi();
        Step();
        Check("点界面“下一页”：命令交给 PPT（NextCalls +1）",
              fake.NextCalls == nextBefore + 1, $"NextCalls={fake.NextCalls}");
        Check("点了“下一页”之后页跟着变（第 3 页）", Doc.PageKey == 258, $"页键 {Doc.PageKey}");
        Check("到末页再点“下一页”不越界（PPT 自己夹住）",
              fake.Slide == 3, $"PPT 第 {fake.Slide} 页");

        // ---- ⑧.5 PPT 控件条（PptBar）：用户 2026-09-26 定的最终形态 ----
        //      一条、默认屏幕左下角、可拖可记；点箭头翻页、点页码弹页号面板、
        //      长按不动松手弹菜单、长按后拖挪位置。
        {
            float screenW = _virtualW, screenBottom = _virtualY + _virtualH;

            // 尺寸：**高度跟主界面那条走**、**中区是黄金矩形**。这两条断言是"同一个数写在
            // 两处"的那道保险：`PptBar.BarH` 在引擎里、`Tokens.BarHeight` 在界面里，
            // 改了一个忘了另一个，这里当场红（同 `--shapebandtest` 盯"加图形漏自检"的思路）。
            Check("PPT 条的高 = 主界面那条的高",
                  Math.Abs(PptBar.BarH - InkUi.Tokens.BarHeight) < 0.01f,
                  $"PptBar.BarH={PptBar.BarH}，Tokens.BarHeight={InkUi.Tokens.BarHeight}");
            float midW = PptBar.BarW - PptBar.ArrowW * 2f;
            Check("中区（页码格）是黄金矩形",
                  Math.Abs(midW / PptBar.BarH - 1.618f) < 0.02f,
                  $"中区 {midW:F0} ÷ 高 {PptBar.BarH} = {midW / PptBar.BarH:F3}（黄金比 1.618）");

            // 默认位置：**屏幕左下角**（用户："因为 PPT 本来的工具就在这里"）。
            // 先清干净：上一次自检可能把位置留在临时配置里了（不清的话这一条会飘）。
            SetUiPref("pptBarX", null);
            SetUiPref("pptBarY", null);
            ResetPptBarPosForTest();
            var bar = PptBarRect();
            float defX = _virtualX + PptBar.EdgeMargin * DpiScale;
            float defY = screenBottom - PptBar.EdgeMargin * DpiScale - PptBar.BarH * DpiScale;
            Check("默认位置 = 屏幕左下角、整条在屏幕里",
                  Math.Abs(bar.MinX - defX) < 1f && Math.Abs(bar.MinY - defY) < 1f
                  && bar.MaxX <= _virtualX + screenW && bar.MaxY <= screenBottom,
                  $"条 x {bar.MinX:F0}..{bar.MaxX:F0}，y {bar.MinY:F0}..{bar.MaxY:F0}");

            // 点右端 ▶ = 下一页（命令给 PPT）
            int nextBefore2 = fake.NextCalls;
            float arX = bar.MaxX - PptBar.ArrowW * DpiScale * 0.5f;
            float arY = (bar.MinY + bar.MaxY) * 0.5f;
            bool ate = PptBarPointerDown(arX, arY);
            Step();
            Check("点右端 ▶：这一下归它、命令给 PPT",
                  ate && fake.NextCalls == nextBefore2 + 1, $"吃掉={ate}，NextCalls={fake.NextCalls}");

            // 点页码格 → 弹页号面板。
            // 先把页数设成 12（面板铺成 2 行）：3 页时面板只有一行、点"第 5 格"根本不在面板里，
            // 那样测的是"点面板外"——**用例要挑有代表性的输入**（这坑自检当场踩了一次）。
            fake.Total = 12;
            Step();
            float midX = (bar.MinX + bar.MaxX) * 0.5f, midY = (bar.MinY + bar.MaxY) * 0.5f;
            PptBarPointerDown(midX, midY);
            PptBarPointerUp(midX, midY);
            Check("点页码：弹出页号面板", PptPagePanelOpen, $"面板={PptPagePanelOpen}");
            PptPanelRect(out var panel);
            Check("面板长在条的上方、在屏幕里",
                  panel.MaxY <= bar.MinY + 0.5f && panel.MinY >= _virtualY
                  && panel.MaxX <= _virtualX + screenW,
                  $"面板 y {panel.MinY:F0}..{panel.MaxY:F0}，条顶 {bar.MinY:F0}");

            // 点面板里第 5 格 → 跳到第 5 页、面板收起
            int gotoBefore = fake.GotoCalls;
            PptPanelCellRectAt(4, out var cell5);
            Check("第 5 格落在面板里（页数够、格子才排得下）",
                  panel.Contains((cell5.MinX + cell5.MaxX) * 0.5f, (cell5.MinY + cell5.MaxY) * 0.5f),
                  $"格中心 ({(cell5.MinX + cell5.MaxX) * 0.5f:F0},{(cell5.MinY + cell5.MaxY) * 0.5f:F0})，面板 {panel.MinX:F0}..{panel.MaxX:F0}");
            bool ateCell = PptBarPointerDown((cell5.MinX + cell5.MaxX) * 0.5f,
                                             (cell5.MinY + cell5.MaxY) * 0.5f);
            Step();
            Check("点面板第 5 格：跳页命令给 PPT、面板收起",
                  ateCell && fake.GotoCalls == gotoBefore + 1 && fake.GotoTarget == 5 && !PptPagePanelOpen,
                  $"GotoCalls={fake.GotoCalls}，跳到第 {fake.GotoTarget} 页，面板={PptPagePanelOpen}");

            // ---- 页号面板：**每一个格子的悬停都要准**（用户 2026-09-27 报的）----
            // 原话："PPT 的悬停页码好像不是那么准确……后面的页码还落在外面。"
            // 逐格量两件事（不靠眼睛）：
            //   ① 整格在面板矩形里（画得出来、也点得到）；
            //   ② 悬停能命中它自己（hover == 200+i，绘制的高亮就是照这个比对的）。
            // 用 75 页（8 行）压：行数一多，"后面的行"最容易暴露坐标算错。
            // 面板走**真实入口**打开（点页码 → 松手），不直接改状态（那个属性是只读的）。
            fake.Total = 75;
            Step();
            bar = PptBarRect();
            midX = (bar.MinX + bar.MaxX) * 0.5f; midY = (bar.MinY + bar.MaxY) * 0.5f;
            PptBarPointerDown(midX, midY);
            PptBarPointerUp(midX, midY);
            Check("（准备）75 页时页号面板已打开", PptPagePanelOpen, $"面板={PptPagePanelOpen}");
            PptPanelRect(out var panel75);
            int cellsBad = 0; string firstBadCell = "（全部命中）";
            for (int i = 0; i < 75; i++)
            {
                PptPanelCellRectAt(i, out var c);
                bool inPanel = panel75.Contains(c.MinX, c.MinY) && panel75.Contains(c.MaxX, c.MaxY);
                PptBarPointerMove((c.MinX + c.MaxX) * 0.5f, (c.MinY + c.MaxY) * 0.5f);
                bool hot = PptBarHover == 200 + i;
                if (!inPanel || !hot)
                {
                    cellsBad++;
                    if (cellsBad == 1)
                        firstBadCell = $"第 {i + 1} 格：在面板内={inPanel}、悬停命中={hot}"
                                     + $"，格 ({c.MinX:F0},{c.MinY:F0})-({c.MaxX:F0},{c.MaxY:F0})"
                                     + $"，面板 ({panel75.MinX:F0},{panel75.MinY:F0})-({panel75.MaxX:F0},{panel75.MaxY:F0})";
                }
            }
            Check("页号面板 · 75 页逐格：都在面板内、悬停都能命中",
                  cellsBad == 0, $"坏格 {cellsBad} 个；{firstBadCell}");

            // —— 页数多到"面板顶到屏幕顶"时，面板底部会**压到条上** ——
            // 那时悬停判定必须**面板优先**（与按下分派 PptBarPointerDown 同一个顺序：
            // 菜单 → 面板 → 条）。原来悬停这边是"条优先"——两处顺序不一致，
            // 表现就是"格子明明看得见、悬停不亮，按下去却真跳页"。
            // 用户 2026-09-27 报的"悬停页码不准确"最可能就是这个。
            fake.Total = 400;
            Step();
            bar = PptBarRect();
            midX = (bar.MinX + bar.MaxX) * 0.5f; midY = (bar.MinY + bar.MaxY) * 0.5f;
            PptBarPointerDown(midX, midY);
            PptBarPointerUp(midX, midY);
            PptPanelRect(out var panelBig);
            Check("大页数（400 页）：面板被夹顶、确实压到条上（构造出了问题现场）",
                  panelBig.MaxY > bar.MinY + 0.5f,
                  $"面板底 {panelBig.MaxY:F0}，条顶 {bar.MinY:F0}（面板高 {panelBig.MaxY - panelBig.MinY:F0}）");
            int clash = -1;
            for (int i = 0; i < 400; i++)
            {
                PptPanelCellRectAt(i, out var c);
                float ccx = (c.MinX + c.MaxX) * 0.5f, ccy = (c.MinY + c.MaxY) * 0.5f;
                if (bar.Contains(ccx, ccy)) { clash = i; break; }   // 格子中心落在条上 = 冲突点
            }
            if (clash >= 0)
            {
                PptPanelCellRectAt(clash, out var cc);
                PptBarPointerMove((cc.MinX + cc.MaxX) * 0.5f, (cc.MinY + cc.MaxY) * 0.5f);
                Check($"重叠区里第 {clash + 1} 格：悬停命中**面板**（不是条）",
                      PptBarHover == 200 + clash,
                      $"hover={PptBarHover}（期望 {200 + clash}；条 zone 最大 {(int)PptBarZone.Page} 一档）");
            }
            else
            {
                Check("大页数：没有格子中心落在条上（这次构造不出冲突点）", true, "跳过");
            }
            PptBarPointerDown(_virtualX + 6f, _virtualY + 6f);   // 点别处：把面板收起来（真实路径）
            Check("（收尾）点别处后面板已收起", !PptPagePanelOpen, $"面板={PptPagePanelOpen}");
            fake.Total = 12;
            Step();

            // 长按（不动）→ **到点直接弹菜单**（不用等松手）
            bar = PptBarRect();
            midX = (bar.MinX + bar.MaxX) * 0.5f; midY = (bar.MinY + bar.MaxY) * 0.5f;
            PptBarPointerDown(midX, midY);
            SettleFrames(750);                     // 长按阈值 600ms
            Check("长按 600ms：**到点就弹菜单**（不用等松手）", PptMenuOpen, $"菜单={PptMenuOpen}");
            PptBarPointerUp(midX, midY);           // 松手不该又弹一次面板
            Check("松手：不会再弹出页号面板（这一次已经被长按消费掉了）",
                  !PptPagePanelOpen, $"面板={PptPagePanelOpen}");
            PptBarPointerDown(_virtualX + 6f, _virtualY + 6f);   // 点别处收起来
            Check("点别处：菜单收起", !PptMenuOpen, $"菜单={PptMenuOpen}");

            // **按下就移** → 直接拖动（用户 2026-09-26："点中页码那一块直接拖动就能走"）
            bar = PptBarRect();
            float gx = (bar.MinX + bar.MaxX) * 0.5f, gy = (bar.MinY + bar.MaxY) * 0.5f;
            PptBarPointerDown(gx, gy);
            PptBarPointerMove(gx + 240f, gy - 320f);      // 一步就过阈值，**不用等 600ms**
            Check("按下就移（不用长按）：直接进入拖动", PptBarDragging, $"拖动={PptBarDragging}");
            PptBarPointerUp(gx + 240f, gy - 320f);
            var barMoved = PptBarRect();
            Check("松手：条真的挪了位置、且不是在拖了",
                  Math.Abs(barMoved.MinX - bar.MinX) > 100f && !PptBarDragging,
                  $"x {bar.MinX:F0} → {barMoved.MinX:F0}，y {bar.MinY:F0} → {barMoved.MinY:F0}");
            Check("松手：位置**存进了偏好**（重启还在）",
                  GetUiPref("pptBarX") != null && GetUiPref("pptBarY") != null,
                  $"pptBarX={GetUiPref("pptBarX")}，pptBarY={GetUiPref("pptBarY")}");

            // 模拟"关掉软件再打开"：退出放映（清内存位置）→ 再进放映（EnterPptMode 会读回）
            float keptX = barMoved.MinX, keptY = barMoved.MinY;
            fake.Showing = false; Step();                    // 退出放映
            ResetPptBarPosForTest();                         // 内存里的位置清掉（重启后就是这状态）
            fake.Showing = true; fake.Slide = 1; fake.SlideId = 256; Step();   // 再进放映
            var barBack = PptBarRect();
            Check("再进放映：位置从盘里读回来（重启还在这个位置）",
                  Math.Abs(barBack.MinX - keptX) < 2f && Math.Abs(barBack.MinY - keptY) < 2f,
                  $"记的是 ({keptX:F0},{keptY:F0})，读回来 ({barBack.MinX:F0},{barBack.MinY:F0})");

            // 拖到屏幕外：必须被夹住（**拖出去找不回来**是这个功能最坏的失败模式）
            bar = PptBarRect();
            gx = (bar.MinX + bar.MaxX) * 0.5f; gy = (bar.MinY + bar.MaxY) * 0.5f;
            PptBarPointerDown(gx, gy);
            PptBarPointerMove(_virtualX - 5000f, screenBottom + 5000f);   // 拼命往屏幕外拖（按下就移）
            PptBarPointerUp(_virtualX - 5000f, screenBottom + 5000f);
            var bc = PptBarRect();
            Check("拖到屏幕外：被夹住、整条还在屏幕里",
                  bc.MinX >= _virtualX && bc.MinY >= _virtualY
                  && bc.MaxX <= _virtualX + screenW && bc.MaxY <= screenBottom,
                  $"条 x {bc.MinX:F0}..{bc.MaxX:F0}，y {bc.MinY:F0}..{bc.MaxY:F0}");

            // ---- **拖起来了就不许再弹长按菜单**（用户 2026-09-27 报的）----
            // 原话："我在拖动 PPT 页码那块的时候，它好像还会弹出'结束放映'的菜单。"
            // 病根：进入拖动时没清长按计时器，600ms 一到 `StepPptBar` 照样弹菜单。
            // 这里复现的就是那条时间线：按下 → 拖起来（计时器该被清）→ 等满 600ms。
            bar = PptBarRect();
            gx = (bar.MinX + bar.MaxX) * 0.5f; gy = (bar.MinY + bar.MaxY) * 0.5f;
            PptBarPointerDown(gx, gy);
            PptBarPointerMove(gx + 30f, gy - 12f);        // 慢慢拖起来（过阈值）
            SettleFrames(750);                            // 过 600ms：这一步以前会弹菜单
            Check("拖动中过 600ms：**不弹菜单**（拖和长按是互斥的两条路）",
                  !PptMenuOpen, $"菜单={PptMenuOpen}，拖动={PptBarDragging}");
            PptBarPointerUp(gx + 30f, gy - 12f);
            Check("松手：拖动正常结束、条挪过去了",
                  !PptBarDragging && Math.Abs(PptBarRect().MinX - bar.MinX) > 20f,
                  $"拖动={PptBarDragging}，x {bar.MinX:F0} → {PptBarRect().MinX:F0}");

            // ---- PPT 浮层（条 / 菜单 / 页号面板）上的光标：一律箭头 ----
            // 与图库面板同型的洞（"一块是界面就是界面"，见 Engine.PointerOnDrawnChrome）：
            // 以前悬停在条上时顶着的是工具光标（框选=十字、笔=斜笔），笔/激光/橡皮的
            // 落点反馈还会画到条上面。判据已收进 PointerOnDrawnChrome（含 PptBarContains）。
            {
                var keepTool = Tool;
                float keepPx = PointerX, keepPy = PointerY;
                bar = PptBarRect();
                midX = (bar.MinX + bar.MaxX) * 0.5f; midY = (bar.MinY + bar.MaxY) * 0.5f;
                Tool = Tool.Marquee;                        // 框选：画布上是十字，最容易暴露
                PointerX = midX; PointerY = midY;
                ScreenToCanvas(ref PointerX, ref PointerY); // 光标判定用画布坐标
                Check("PPT 条上：光标是箭头（不是十字）",
                      ComputeCursorKind() == CursorKind.Default,
                      $"光标={Cursors.Name(ComputeCursorKind())}");
                Check("PPT 条上：落点反馈不画（不顶着圆环）",
                      DrawnCursor == ToolCursorShape.None, $"DrawnCursor={DrawnCursor}");
                Tool = keepTool;
                PointerX = keepPx; PointerY = keepPy;
            }

            // ---- 菜单：**只有长按这一条路**（「⋮」2026-09-27 删掉了）；三项逐项点一遍 ----
            // （"加一项漏一处"是这个仓库的老毛病，见 架构-分层与规则.md 五-7）
            bar = PptBarRect();
            midX = (bar.MinX + bar.MaxX) * 0.5f; midY = (bar.MinY + bar.MaxY) * 0.5f;
            Check("菜单就三项、一律六字（用户重新起名之后正好齐齐的）",
                  PptMenuItemCount == 3 && PptMenuItemText(0) == "自动保存墨迹"
                  && PptMenuItemText(1) == "清空所有墨迹" && PptMenuItemText(2) == "结束本次放映",
                  $"{PptMenuItemText(0)} / {PptMenuItemText(1)} / {PptMenuItemText(2)}");

            // ① 长按页码格 = 开菜单（**现在唯一的入口**，不用瞄小点）
            PptBarPointerDown(midX, midY);
            SettleFrames(750);
            PptBarPointerUp(midX, midY);
            Check("长按页码格松手：菜单打开", PptMenuOpen, $"菜单={PptMenuOpen}");

            // ② 菜单开着时**再点页码格 = 收起**（原来这是"再点 ⋮"那条路，不能鬼打墙）
            PptBarPointerDown(midX, midY);
            Check("菜单开着再点页码格：收起（不鬼打墙）", !PptMenuOpen, $"菜单={PptMenuOpen}");

            // ---- 穿透开着时，条仍然归我们 ----
            // 用户 2026-09-27 问的"穿透模式下 PPT 翻页起不起作用"，两层都要验：
            //   · 引擎的分派：`PptBarPointerDown` 排在 `if (PassThrough) return;` **之前**，
            //     所以点 ▶ 照样翻页、这一下不会被让给下层；
            //   · 系统的命中测试：穿透用的是 **WS_EX_TRANSPARENT**，它让系统**跳过命中测试**
            //     ——覆盖层那条 WM_NCHITTEST 豁免根本执行不到（这就是用户实测"不管用"的原因）。
            //     修法是照面板那套**再开一块接输入小窗**，下面几条量它的矩形。
            bar = PptBarRect();
            float rx = bar.MaxX - PptBar.ArrowW * DpiScale * 0.5f;
            float ry = (bar.MinY + bar.MaxY) * 0.5f;
            SetPassThroughFromUi(true);
            Check("穿透开着：条那一块仍算「我们的地盘」（NCHITTEST 不会让出去）",
                  PptBarContains(rx, ry), $"条内点 ({rx:F0},{ry:F0})");
            int nx = fake.NextCalls;
            bool ateP = PptBarPointerDown(rx, ry);
            Step();
            Check("穿透开着：点 ▶ 照样翻页、这一下没被让给下层",
                  ateP && fake.NextCalls == nx + 1, $"吃掉={ateP}，NextCalls={fake.NextCalls}");

            // **接输入小窗**（穿透下条能点的真正原因）：
            //   ① 只覆盖"条 ∪ 菜单 ∪ 页号面板"，一像素都不多（多出来的地方会挡住下层程序）；
            //   ② 关掉穿透 / 退出放映**必须收掉**（留着就成了屏幕上一块看不见的挡板）。
            Check("穿透 + 放映：条的接输入小窗已经铺上", PptInputWindowShown, $"铺上={PptInputWindowShown}");
            {
                PptInputWindowRect(out var win);
                Check("接输入小窗就贴在条上（不越界、也不是整屏）",
                      Math.Abs(win.MinX - bar.MinX) < 1.5f && Math.Abs(win.MinY - bar.MinY) < 1.5f
                      && Math.Abs(win.MaxX - bar.MaxX) < 1.5f && Math.Abs(win.MaxY - bar.MaxY) < 1.5f,
                      $"窗 ({win.MinX:F0},{win.MinY:F0})-({win.MaxX:F0},{win.MaxY:F0})，"
                      + $"条 ({bar.MinX:F0},{bar.MinY:F0})-({bar.MaxX:F0},{bar.MaxY:F0})");

                // 打开页号面板：窗要**变高**把面板也罩住（不然面板看得见、点不动）
                PptBarPointerDown((bar.MinX + bar.MaxX) * 0.5f, (bar.MinY + bar.MaxY) * 0.5f);
                PptBarPointerUp((bar.MinX + bar.MaxX) * 0.5f, (bar.MinY + bar.MaxY) * 0.5f);
                Check("（准备）页号面板已打开", PptPagePanelOpen, $"面板={PptPagePanelOpen}");
                Step();
                PptPanelRect(out var panelNow);
                PptInputWindowRect(out var win2);
                Check("面板开着时：小窗跟着长高（面板那几格也点得中）",
                      win2.MinY <= panelNow.MinY + 1.5f && win2.MaxY >= bar.MaxY - 1.5f,
                      $"窗顶 {win2.MinY:F0} ≤ 面板顶 {panelNow.MinY:F0}，窗底 {win2.MaxY:F0} ≥ 条底 {bar.MaxY:F0}");
                PptBarPointerDown(_virtualX + 6f, _virtualY + 6f);   // 点别处：收面板（真实路径）
                Step();
            }
            SetPassThroughFromUi(false);
            Step();
            Check("关掉穿透：接输入小窗立刻收掉（不留看不见的挡板）",
                  !PptInputWindowShown, $"铺上={PptInputWindowShown}");

            // 穿透那两条点了一下 ▶（顺手把开着的菜单收起了），这里重新开起来给 ③④ 用
            PptBarPointerDown(midX, midY);
            SettleFrames(750);
            PptBarPointerUp(midX, midY);

            // ③ 「墨迹保存」（开关）：点一下翻状态、**菜单留着**（要让老师看见"开 → 关"）
            bool saveBefore = PptAutoSaveOn;
            PptMenuItemRectAt(0, out var mi0);
            PptBarPointerDown((mi0.MinX + mi0.MaxX) * 0.5f, (mi0.MinY + mi0.MaxY) * 0.5f);
            Check("点「墨迹保存」：状态翻过来、菜单留着",
                  PptAutoSaveOn == !saveBefore && PptMenuOpen,
                  $"{saveBefore} → {PptAutoSaveOn}，菜单={PptMenuOpen}");
            Check("关掉后偏好里记的是 \"0\"（默认开 → 只记差异）",
                  PptAutoSaveOn || GetUiPref("pptAutoSave") == "0",
                  $"pptAutoSave={GetUiPref("pptAutoSave") ?? "(空 = 开)"}");

            // ④ 「墨迹清空」（两段确认）：**第一下不执行**
            int diskBefore = PptStore.ListPageKeys(fake.Key).Count;
            PptMenuItemRectAt(1, out var mi1);
            PptBarPointerDown((mi1.MinX + mi1.MaxX) * 0.5f, (mi1.MinY + mi1.MaxY) * 0.5f);
            Check("点「墨迹清空」第一下：进入等确认、文字变「再点确认」、**还没清**",
                  PptClearConfirm && PptMenuOpen && PptMenuItemText(1) == "再点确认"
                  && PptStore.ListPageKeys(fake.Key).Count == diskBefore,
                  $"等确认={PptClearConfirm}，文字={PptMenuItemText(1)}，盘上还是 {diskBefore} 页");

            // 把自动保存打开，好验证"清空是连盘一起清的"（关着的话盘上本来就该原样）
            PptMenuItemRectAt(0, out var mi0b);
            PptBarPointerDown((mi0b.MinX + mi0b.MaxX) * 0.5f, (mi0b.MinY + mi0b.MaxY) * 0.5f);

            // 第二下：真清
            PptMenuItemRectAt(1, out var mi1b);
            PptBarPointerDown((mi1b.MinX + mi1b.MaxX) * 0.5f, (mi1b.MinY + mi1b.MaxY) * 0.5f);
            Step();
            Check("点第二下：清空执行、菜单收起、等确认状态放掉",
                  !PptClearConfirm && !PptMenuOpen, $"等确认={PptClearConfirm}，菜单={PptMenuOpen}");
            Check("清空后：**盘上这份 PPT 的批注文件真没了**（显式删盘，不靠写空内容）",
                  PptStore.ListPageKeys(fake.Key).Count == 0,
                  $"清空前 {diskBefore} 页 → 现在 {PptStore.ListPageKeys(fake.Key).Count} 页");
            Check("清空后：内存里也是空的", Doc.Strokes.Count == 0, $"{Doc.Strokes.Count} 条");

            // ⑤ 清空完再进一次放映：**不能复活**（这是"清空到底有没有用"的唯一判据）
            fake.Showing = false; Step();
            fake.Showing = true; fake.Slide = 1; fake.SlideId = 256; Step();
            Check("清空后再进放映：**不复活**", Doc.Strokes.Count == 0, $"{Doc.Strokes.Count} 条");

            // ⑥ 引导：**每次进放映都提示一遍**（用户 2026-09-27 定）——
            //    「⋮」删掉之后菜单只剩长按一条路，"只提示一次"会让老师第二次课就想不起来。
            //    强断言：先把"已经提示过"这个偏好**写死**（老逻辑下它就不会再出现了），
            //    再进放映——引导**照样出现**，说明这行偏好已经不再管这事。
            SetUiPref("pptHint", "1");
            fake.Showing = false; Step();
            fake.Showing = true; Step();
            Check("进放映：冒出一行引导（告诉老师长按能呼出菜单）", PptHintVisible, $"提示={PptHintVisible}");
            SettleFrames(1700);            // 1.5 秒后应该自己消失（不挡讲课）
            Check("1.5 秒后引导自己消失", !PptHintVisible, $"提示={PptHintVisible}");
            fake.Showing = false; Step();
            fake.Showing = true; Step();
            Check("第二次进放映：**照样提示**（不是只提示一次）", PptHintVisible, $"提示={PptHintVisible}");
            PptHintSuppressForTest();      // 压下去，别挡着后面⑦的菜单

            // ⑦ 「结束放映」（最后一项，它会把放映退掉，所以排在最后）
            bar = PptBarRect();
            midX = (bar.MinX + bar.MaxX) * 0.5f; midY = (bar.MinY + bar.MaxY) * 0.5f;
            PptBarPointerDown(midX, midY);
            SettleFrames(750);
            PptBarPointerUp(midX, midY);
            int exitBefore = fake.ExitCalls;
            PptMenuItemRectAt(2, out var mi2);
            PptBarPointerDown((mi2.MinX + mi2.MaxX) * 0.5f, (mi2.MinY + mi2.MaxY) * 0.5f);
            Step();
            Check("点「结束放映」：命令给 PPT、菜单收起",
                  fake.ExitCalls == exitBefore + 1 && !PptMenuOpen,
                  $"ExitCalls={fake.ExitCalls}，菜单={PptMenuOpen}");
            Check("退出放映后：条不再命中（它是放映时才有的）",
                  !PptMode && !PptBarContains(bar.MinX + 10f, bar.MinY + 10f),
                  $"PptMode={PptMode}");
        }

        // ---- 兜底：读不到 SlideID 时用负页码当键（参考 Ultra 的 GetStrokeCacheKey）----
        fake.Connected = true; fake.Showing = true; fake.Slide = 2; fake.SlideId = 0;
        Step();
        Check("读不到 SlideID：用负页码兜底当页键", Doc.PageKey == -2, $"页键 {Doc.PageKey}");
        fake.Showing = false; fake.SlideId = 0;
        Step();

        Console.WriteLine();
        Console.WriteLine(fail == 0
            ? "  PASS：PPT 模式正确（隔离 / 页内滚动 / 清空只清本页 / 退出写盘 / 再进读回 / 按钮走 PPT）"
            : $"  FAIL：{fail} 项不对（{pass} 项通过）");

        try { Directory.Delete(PptStore.RootOverride, true); } catch { }
        PptStore.RootOverride = null;

        // 收尾：把文档清干净、退出（自检宿主跑完就结束，别留着一块盖在桌面上的窗口）。
        Doc.ResetToSinglePage();
        Doc.ClearHistory();
        _quit = true;
    }

    /// <summary>
    /// `--pptshow <图>`：**PPT 控件条的摆样**——用假源进入 PPT 模式，把它画出来再截一张。
    /// 加 `--panel` 出"点页码弹出的页号面板"，加 `--menu` 出"长按弹出的菜单"。
    ///
    /// 为什么要单开一条：排版好不好看**自检判不了**（几何全对也一样难看），
    /// 所以项目里界面（`--panelshow`）、浮层（`--selshowcase`）、旋转标签
    /// （`--rotateshow`）都各有一条这样的出图命令（见 README 的"出图"一节）。
    /// </summary>
    private void PptShow(string path)
    {
        if (path == null)
        {
            Console.WriteLine("  用法：--pptshow <图.bmp> [--panel] [--menu]");
            _quit = true;
            return;
        }

        // 颜色与投影是界面推给引擎的（见 IUiHost.SetFloatingTheme）——
        // 不挂界面拿到的是 UiTheme.Default 那套兜底，出的图就不是产品里的样子。
        SetUiFactory(() => new InkUi.FullUi());

        var fake = new PptFakeSource { Showing = true, Slide = 3, SlideId = 258, Total = 12, Key = "摆样" };
        AttachPptSource(fake, watch: false);
        var argv = Environment.GetCommandLineArgs();

        ResetPptBarPosForTest();            // 从默认位置（左下角）起，出的图才是"第一眼"的样子
        StepPpt();
        SettleFrames(150);
        // 引导那一行字**每次进放映都会出现**（2026-09-27 起），而它和菜单长在同一处、
        // 会互相压着看不清——所以除了专门出它的 `--hint`，其余出图一律把它按下去。
        // ⚠ 必须压在 `StepPpt()` **之后**：进放映那一刻它才被点起来，压早了没用。
        if (!argv.Contains("--hint")) PptHintSuppressForTest();

        var bar = PptBarRect();
        float midX = (bar.MinX + bar.MaxX) * 0.5f;
        float midY = (bar.MinY + bar.MaxY) * 0.5f;

        if (argv.Contains("--menu"))
        {
            PptBarPointerDown(midX, midY);
            SettleFrames(750);              // 长按阈值 600ms
            PptBarPointerUp(midX, midY);
        }
        else if (argv.Contains("--panel"))
        {
            PptBarPointerDown(midX, midY);
            PptBarPointerUp(midX, midY);
        }
        else
        {
            // 悬停在**页码格**上：它才是条上的主角（点它跳页），顺便把悬停高亮出进图里
            // ——用户 2026-09-26 指出过"页码那里没有悬停指示"，这条图就是给那件事看的。
            PptBarPointerMove(midX, midY);
        }
        SettleFrames(200);

        // 截图范围 = 这一刻要拍的东西（条 ∪ 面板 ∪ 菜单 ∪ 首次引导）
        var box = PptBarRect();
        if (PptPagePanelOpen) { PptPanelRect(out var p); box.Add(p.MinX, p.MinY); box.Add(p.MaxX, p.MaxY); }
        if (PptMenuOpen || PptHintVisible) { PptMenuRect(out var m); box.Add(m.MinX, m.MinY); box.Add(m.MaxX, m.MaxY); }
        float pad = 24f;
        int sx = (int)Math.Max(_virtualX, box.MinX - pad);
        int sy = (int)Math.Max(_virtualY, box.MinY - pad);
        int sw = (int)Math.Min(_virtualX + _virtualW - sx, box.MaxX - box.MinX + pad * 2);
        int sh = (int)Math.Min(_virtualY + _virtualH - sy, box.MaxY - box.MinY + pad * 2);
        bool ok = ScreenProbe.SaveBmp(path, sx, sy, sw, sh);
        Console.WriteLine(ok ? $"  已保存 {path}（{sw}×{sh}）" : "  截屏失败");
        _quit = true;
    }

    /// <summary>
    /// `--pptprobe [秒]`：**真机连接探针**（用户在自己的机器上跑一次就知道通不通）。
    ///
    /// 为什么只能这样验：我这边没有 PowerPoint / WPS 环境，产品那条 COM 连接
    /// 没法在自检里跑（自检也不该去碰它——`StartPptLink` 在自检模式下直接返回）。
    /// 这条命令每秒问一次"现在连上谁了、在不在放映、第几页"，把答案打出来。
    ///
    /// 用法（老师的机器上）：
    ///   ① 跑 `InkTeach.exe --pptprobe 20`；
    ///   ② 趁这 20 秒打开一个 PPT，按 F5 放映、翻两页（WPS 演示也一样试一次）；
    ///   ③ 看输出：放映中应当从 False 变 True、页码跟着翻页变、SlideID 是个大整数。
    /// 三条都对 = 连接层在这台机器上没问题（WPS 也照这条走，它就是给国产办公套件铺的路）。
    /// </summary>
    private void PptProbe(double seconds)
    {
        Console.WriteLine();
        Console.WriteLine("=== PPT 连接探针 ===");
        Console.WriteLine($"  接下来 {seconds:F0} 秒里，请去打开一个 PPT 并按 F5 放映、翻两页；");
        Console.WriteLine("  WPS 演示也一样试一次（这条探针就是用来分清哪家的 Office 能连上的）。");
        Console.WriteLine();

        var src = new PptComSource();
        int connectedSamples = 0, showingSamples = 0;
        double t0 = NowMs;
        string lastLine = "";
        while (NowMs - t0 < seconds * 1000)
        {
            var s = src.Poll();
            if (s.Connected) connectedSamples++;
            if (s.Showing) showingSamples++;
            string line = $"  连上={s.Connected}  放映中={s.Showing}  第 {s.Slide}/{s.Total} 页  "
                        + $"SlideID={s.SlideId}  标识={s.Key}";
            if (line != lastLine) { Console.WriteLine(line); lastLine = line; }
            SettleFrames(200);
        }

        Console.WriteLine();
        Console.WriteLine(showingSamples > 0
            ? $"  PASS：读到过放映状态（{showingSamples} 次采样在放映中）——连接层在这台机器上可用"
            : connectedSamples > 0
                ? $"  半通：连上了演示文稿（{connectedSamples} 次采样），但没读到放映状态——请确认按了 F5 全屏放映"
                : "  不通：一次都没连上（没装桌面 Office / WPS、没有打开的演示文稿，或 COM 被安全软件挡住）");
        _quit = true;
    }

    /// <summary>
    /// **整屏翻页自检（一屏 = 一页）**。取向与出处见 [调研-白板翻页.md]。
    ///
    /// 关键是盯着"**没有新概念**"这件事：桌面/白板这一侧**不做** OneNote 那种
    /// "每页一个文档"——它还是**同一张连续的长纸**，只让相机按整屏跳。
    /// 所以这一套用例全在验：
    ///   · 页高 = 视口高，翻一屏 = 相机正好走一屏（翻完不留半行字）；
    ///   · **翻页前后，文档里没有一个坐标发生变化**（只有相机动）——这是"没做分页"的证据；
    ///   · 到顶就停、往下永远还有一屏（无限纸的红利）；
    ///   · 滚轮仍然是细粒度（翻页不该把滚轮改成"一格一屏"）；
    ///   · 翻完屏幕上真的换了内容（屏幕取点，和 --cameratest 同一套手法）。
    ///
    /// ⚠ 2026-09-26 起要分清**两条路**：这里是**桌面/白板这一侧**（连续长纸、永不隔离）；
    /// PPT 放映那一侧的"每页一套、完全隔离"是另一条路，由 `--ppttest` 钉
    /// （同一份 `FlipPage`/相机代码，但切的是"页槽"，见 Model.cs 的 PageSlot）。
    /// </summary>
    private void PageTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 整屏翻页自检（一屏 = 一页）===");

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-30} {detail}");
        }

        Doc.Clear();
        Doc.ClearHistory();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        Doc.InvalidateAll();
        SettleFrames(250);

        float pageH = _virtualH;                       // 物理像素：页高 = 视口高

        // ---- ① 页高 ----
        Check("页高 = 视口高", Math.Abs(PageHeightCanvas - _virtualH) < 0.01f,
              $"页高 {PageHeightCanvas:F0}，视口高 {_virtualH}");
        Check("第 1 屏的页顶 = 虚拟桌面顶",
              Math.Abs(PageTopCanvas - _virtualY) < 0.01f,
              $"页顶 {PageTopCanvas:F0}，桌面顶 {_virtualY}");

        // ---- ② 翻一屏 = 相机正好走一屏 ----
        Check("起手在第 1 屏、且不能再往上翻",
              ScreenIndex == 1 && !CanFlipPageUp,
              $"屏号 {ScreenIndex}，能上翻 = {CanFlipPageUp}");

        bool went = FlipPage(true);
        SettleFrames(400);                             // 等完那 167ms 的缓动
        Check("往下翻返回 true", went, $"返回 {went}");
        Check("翻一屏 = 相机正好走一屏", Math.Abs(ViewOffsetY + pageH) < 0.6f,
              $"相机 {ViewOffsetY:F1}（应为 {-pageH:F0}）");
        Check("翻完在第 2 屏", ScreenIndex == 2, $"屏号 {ScreenIndex}");
        Check("到第 2 屏后就能往上翻了", CanFlipPageUp, $"能上翻 = {CanFlipPageUp}");

        // ---- ③ 往下永远还有一屏（连翻 6 次都成）----
        int flipped = 1;
        for (int i = 0; i < 6; i++)
        {
            if (!FlipPage(true)) break;
            flipped++;
            SettleFrames(250);
        }
        Check("下一屏永远可用（连翻 6 次都成）", flipped == 7,
              $"成功 {flipped} 次，屏号 {ScreenIndex}");

        // ---- ④ 回来；到顶后再上翻必须"什么都不做" ----
        for (int i = 0; i < 10 && CanFlipPageUp; i++) { FlipPage(false); SettleFrames(250); }
        Check("连翻回顶：相机夹在 0，不越过", Math.Abs(ViewOffsetY) < 0.01f,
              $"相机 {ViewOffsetY:F2}");
        bool upAtTop = FlipPage(false);
        SettleFrames(200);
        Check("到顶了再上翻：返回 false 且相机不动",
              !upAtTop && Math.Abs(ViewOffsetY) < 0.01f,
              $"返回 {upAtTop}，相机 {ViewOffsetY:F2}");

        // ---- ⑤ 翻页前后，文档里一个坐标都不变（证明"没做分页"）----
        // 铺开三屏、每屏三行——量级对齐一节真实板书。
        Doc.Clear();
        Doc.ClearHistory();
        for (int screen = 0; screen < 3; screen++)
            for (int row = 0; row < 3; row++)
            {
                var s = new Stroke
                {
                    Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                    Color = new Color4(0.12f, 0.13f, 0.16f, 1f), Width = 6f,
                };
                float y = _virtualY + screen * _virtualH + 200f + row * 260f;
                for (int i = 0; i <= 20; i++)
                    s.AddPoint(_virtualX + 240f + i * 55f, y + (i % 4) * 8f, 1f, i * 8);
                Doc.AddStroke(s);
            }
        Doc.InvalidateAll();
        SettleFrames(200);

        string Dump()
        {
            var sb = new System.Text.StringBuilder();
            foreach (var s in Doc.Strokes)
            {
                sb.Append((int)s.Tool).Append('/').Append((int)s.Kind).Append(':');
                foreach (var p in s.Points)
                    sb.Append(p.X.ToString("F3")).Append(',').Append(p.Y.ToString("F3")).Append(';');
                sb.Append('|');
            }
            return sb.ToString();
        }

        string coords0 = Dump();
        int strokes0 = Doc.Strokes.Count;
        FlipPage(true); SettleFrames(300);
        FlipPage(true); SettleFrames(300);
        FlipPage(false); SettleFrames(300);
        FlipPage(true); SettleFrames(300);
        string coords1 = Dump();
        Check("翻来翻去：对象数没变", Doc.Strokes.Count == strokes0,
              $"{strokes0} → {Doc.Strokes.Count} 条");
        Check("翻来翻去：**每一个坐标都没变**", coords1 == coords0,
              coords1 == coords0 ? $"{coords0.Length} 字符逐字符一致（只有相机动）"
                                 : "有坐标被改动了 —— 翻页不该碰文档");

        // ---- ⑥ 滚轮仍是细粒度（一格 72 逻辑像素，不是一格一屏）----
        IntPtr Wheel(int delta) => new((long)(ushort)(short)delta << 16);
        for (int i = 0; i < 12 && CanFlipPageUp; i++) { FlipPage(false); SettleFrames(250); }
        SettleFrames(150);
        float camBefore = ViewOffsetY;
        HandleWheel(Wheel(-120));
        SettleFrames(120);
        float wheelStep = 72f * DpiScale;
        Check("滚轮还是细粒度（一格 72 逻辑像素）",
              Math.Abs(ViewOffsetY - camBefore + wheelStep) < 1.2f,
              $"走了一格 = {camBefore - ViewOffsetY:F0} 物理像素（应为 {wheelStep:F0}，一屏是 {pageH:F0}）");
        HandleWheel(Wheel(120));                       // 滚回去
        SettleFrames(120);

        // ---- ⑦ 翻完屏幕上真的换了内容（屏幕取点）----
        // 先放一笔**第 1 屏**的洋红墨：它必须看得见——既当判据，也当"取屏可用"的探针。
        Doc.Clear();
        Doc.ClearHistory();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        // 两笔**故意放在不同的屏幕高度**，这样"没翻动"和"翻动了"才有区别：
        //   第 1 屏那笔 → 相机为 0 时在屏幕 y=400；翻下去之后跑到屏幕外（负号），
        //   第 2 屏那笔 → 相机为 0 时在屏幕外，翻下去之后出现在屏幕 y=1000。
        // （第一版把两笔放在**同一个屏幕位置**，结果"翻没翻"取到的像素数一模一样，
        //   即使相机根本没动也会通过——这种"测不出区别"的用例比没有还坏。）
        float px = _virtualX + 900f;
        float y1 = _virtualY + 400f;                 // 第 1 屏
        float y2 = _virtualY + _virtualH + 1000f;    // 第 2 屏，翻下去之后落在屏幕 y=1000
        foreach (float cy in new[] { y1, y2 })
        {
            var s = new Stroke
            {
                Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 26f * DpiScale,
            };
            s.AddPoint(px - 220f, cy, 1f, 0);
            s.AddPoint(px + 220f, cy, 1f, 1);
            Doc.AddStroke(s);
        }
        Doc.InvalidateAll();
        SettleFrames(400);

        int BandAt(float screenY) => ScreenProbe.CountMagenta((int)px - 260, (int)screenY - 40, 520, 80);
        float homeProbeY = _virtualY + 400f, secondProbeY = _virtualY + 1000f;

        int probe = BandAt(homeProbeY);
        if (probe < 300)
        {
            // 锁屏 / 远程桌面 / 别的窗口盖住时取不到像素：这条只能跳过，不能算失败。
            Console.WriteLine($"  [跳过] 第一屏的墨自己都没取到（{probe} 像素）——"
                            + "屏幕取点这时候不可用（锁屏 / 远程 / 被盖住），这一条不判红绿");
        }
        else
        {
            int secondBefore = BandAt(secondProbeY);
            Check("相机为 0 时：第 2 屏那笔不该在屏幕上", secondBefore < 40,
                  $"{secondBefore} 像素（第 2 屏那笔此时在屏幕外）");

            FlipPage(true);
            SettleFrames(400);
            int firstAfter = BandAt(homeProbeY);
            int secondAfter = BandAt(secondProbeY);
            Check("翻下去：第 1 屏那笔离开屏幕", firstAfter < 40,
                  $"{firstAfter} 像素（原来 400 处那笔现在在屏幕外）");
            Check("翻下去：第 2 屏那笔出现在屏幕上", secondAfter > 300,
                  $"{secondAfter} 像素（落在屏幕 1000 处）");

            FlipPage(false);
            SettleFrames(400);
            int backHome = BandAt(homeProbeY);
            Check("翻回来：第 1 屏那笔还在原处", backHome > 300, $"{backHome} 像素");
        }

        Console.WriteLine();
        Console.WriteLine(fail == 0
            ? "  PASS：整屏翻页正确（页高 = 视口高、只动相机、到顶就停、往下无限、滚轮仍是细粒度）"
            : $"  FAIL：{fail} 项不对（{pass} 项通过）");

        // ---- ⑧ 清空之后**留在原地**（用户 2026-09-17 问："如果我的焦点在第 12 页，
        //        点击清空以后要不要回到第一页？"）----
        //
        // 结论：**不回**。清空是"这一屏重新来"，不是"回到开头"：
        // 老师在第 12 屏写完一题、点清空，就是要在**这一屏**接着写下一题；
        // 把相机弹回去等于让他再翻十几次，而且下一次落笔的位置也错了
        // （我们一直守"点下去的东西别动"，锚点、按钮位置都按它办）。
        // 真想从头看，点"上一屏"或拖右缘滚动条就行。
        //
        // 这一条要**钉在自检里**，因为"清空之后镜子一照全变"这种事很容易被以后某次
        // 改动带歪（比如"顺手把相机归零"）。
        {
            Doc.Clear();
            Doc.ClearHistory();
            ViewOffsetY = 0f;
            foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
            Doc.InvalidateAll();
            SettleFrames(250);

            FlipPage(true); SettleFrames(300);
            FlipPage(true); SettleFrames(300);
            int pageKept = ScreenIndex;
            float camKept = ViewOffsetY;

            for (int i = 0; i < 3; i++)
            {
                var st = new Stroke
                {
                    Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                    Color = new Color4(0f, 0f, 0f, 1f), Width = 8f,
                };
                st.AddPoint(600 + i * 60, 300 + i * 40, 1f, 0);
                st.AddPoint(900 + i * 60, 340 + i * 40, 1f, 1);
                Doc.AddStroke(st);
            }
            SettleFrames(250);
            ClearFromUi();
            SettleFrames(400);

            Check("清空之后：**还停在第 3 屏**，相机一动不动",
                  ScreenIndex == pageKept && MathF.Abs(ViewOffsetY - camKept) < 0.5f,
                  $"屏号 {pageKept} → {ScreenIndex}，相机 {camKept:F0} → {ViewOffsetY:F0}"
                  + $"（文档 {Doc.Strokes.Count} 笔）");
            Check("清空之后：还能接着在这一屏写",
                  Doc.Strokes.Count == 0,
                  $"笔画 {Doc.Strokes.Count}");
        }

        Doc.Clear();
        Doc.ClearHistory();
        ViewOffsetY = 0f;
        _quit = true;
    }

    /// <summary>
    /// **坐标不变量测试**——随机相机偏移下反复验同一句话：
    ///
    ///   在画布 P 处写一笔 → 屏幕上 P+相机 处必须有墨。
    ///
    /// 为什么要有它：前面三个 bug（滚下去写的看不见 / 滚完写不了 / 闪一下就没了）
    /// 都是"画布坐标和窗口坐标混用"，而且每个都是**用户碰出来的**。
    /// 一个一个追太慢，这条测试把它们一次性网住：
    /// 它走的是**真实交互路径**（AddStroke 不调 InvalidateAll → DrawOnlyPatch），
    /// 并且随机换相机偏移——偏移一大，任何忘了换算的地方都会露馅。
    ///
    /// 这一类测试行业里叫"不变量测试"（invariant／属性测试）：不写死具体场景，
    /// 只断言"无论参数取什么值，这条性质都必须成立"。
    /// </summary>
    private void CoordTest(int rounds)
    {
        Console.WriteLine();
        Console.WriteLine($"=== 坐标不变量测试（{rounds} 个随机相机偏移）===");
        Console.WriteLine("    偏移 |     期望处 |   未偏移处 | 结果");
        Console.WriteLine("  -------|------------|------------|------");

        int pass = 0, fail = 0;
        var detail = new List<string>();
        var rnd = new Random(20260913);

        for (int k = 0; k < rounds; k++)
        {
            Doc.Clear();
            Doc.ClearHistory();

            float shift = -(float)(rnd.NextDouble() * 3000.0 + 150.0);   // 往下滚 150~3150
            ViewOffsetY = shift;
            foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = shift; }
            Doc.InvalidateAll();
            SettleFrames(150);

            // 挑一个**屏幕可见**的位置，反推它对应的画布坐标（就是输入路径做的事）
            float sx = _virtualX + 600f + (float)rnd.NextDouble() * 700f;
            float sy = _virtualY + 300f + (float)rnd.NextDouble() * 700f;
            float cx = sx, cy = sy;
            ScreenToCanvas(ref cx, ref cy);

            var s = new Stroke
            {
                Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 24f * DpiScale,
            };
            s.AddPoint(cx - 150f, cy, 1f, 0);
            s.AddPoint(cx + 150f, cy, 1f, 0);
            Doc.AddStroke(s);              // 真实路径，别加 InvalidateAll
            SettleFrames(200);

            int atExpected = ScreenProbe.CountMagenta((int)sx - 90, (int)sy - 90, 180, 180);
            int atRaw = ScreenProbe.CountMagenta((int)sx - 90, (int)(sy - shift) - 90, 180, 180);
            bool ok = atExpected > 300;

            if (!ok && detail.Count < 3)
                Console.WriteLine($"      [诊断] 补画块数 {_windows[0].LastAppendedTiles}"
                                + $" 累计补画 {_windows[0].TotalAppendedTiles}"
                                + $" 未命中补画 {_windows[0].LastAppendMissed}"
                                + $" err={_windows[0].LastError}"
                                + $" 文档 {Doc.Strokes.Count} 条 画布 y={cy:F0}");

            if (ok) pass++; else { fail++; detail.Add($"偏移{shift:F0}：期望处 {atExpected} 像素（应 >300），画布 y={cy:F0}"); }
            if (k < 12 || !ok)
                Console.WriteLine($"  {shift,6:F0} | {atExpected,10} | {atRaw,10} | {(ok ? "PASS" : "FAIL")}");
        }

        Console.WriteLine();
        Console.WriteLine($"  {pass}/{rounds} 通过");
        foreach (var d in detail) Console.WriteLine("    " + d);
        Console.WriteLine(fail == 0
            ? "  PASS：随机偏移下，画布上写在哪、屏幕上就该出现在哪 —— 全都成立"
            : $"  FAIL：{fail} 个偏移下不成立 —— 坐标换算有遗漏");

        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        Doc.Clear();
        Doc.ClearHistory();
        _quit = true;
    }

    /// <summary>
    /// 滚下去还能不能写。
    ///
    /// 做法：在三个滚动位置（顶部 / 往下三屏）各在**当下的屏幕位置**写一笔，
    /// 然后回到顶部，验证只有第一笔在视野里、后两笔确实留在了下面。
    ///
    /// 这同时回答"滚动要不要下限"：数据上**不设限**才是对的（老师往下写不完），
    /// 真正要解决的是"怎么回来"——无限往下滚而没有回顶部的办法，老师会迷路。
    /// </summary>
    private void ScrollWriteTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 滚下去还能不能写 ===");
        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"    {name,-24}{(ok ? "PASS" : "FAIL")}  {detail}");
        }

        Doc.Clear();
        Doc.ClearHistory();

        float px = _virtualX + 900, py = _virtualY + 700;      // 屏幕上的固定位置
        float[] offsets = { 0f, -1800f, -5400f };              // 顶部 / 一屏 / 三屏
        var writtenCanvasY = new List<float>();

        for (int i = 0; i < offsets.Length; i++)
        {
            ViewOffsetY = offsets[i];
            foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = ViewOffsetY; }

            // 输入路径做的事：屏幕坐标 -> 画布坐标
            float cx = px, cy = py;
            ScreenToCanvas(ref cx, ref cy);
            writtenCanvasY.Add(cy);

            var s = new Stroke
            {
                Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 20f * DpiScale,
            };
            s.AddPoint(cx - 200, cy, 1f, 0);
            s.AddPoint(cx + 200, cy, 1f, 0);
            Doc.AddStroke(s);      // 真实交互路径：不调 InvalidateAll，
                                    // 走"脏区 → 标脏分块 → 只重画碰到的那几块"
            SettleFrames(350);

            int seen = ScreenProbe.CountMagenta((int)px - 60, (int)py - 60, 120, 120);
            Check($"滚动 {offsets[i],7:F0} 处能写", seen > 200,
                  $"画布 y={cy:F0}，屏幕上有 {seen} 像素");
            if (seen <= 200)
            {
                // 诊断：墨到底画到哪去了？沿屏幕竖着扫几条带子。
                Console.Write("      竖扫结果：");
                for (int band = 0; band < 6; band++)
                {
                    int yy = _virtualY + band * 300;
                    int n2 = ScreenProbe.CountMagenta((int)px - 200, yy, 400, 300);
                    Console.Write($"y={band * 300,4}→{n2,5}  ");
                }
                Console.WriteLine();
            }
        }

        Check("三笔记录在三个不同的画布位置",
              writtenCanvasY.Distinct().Count() == 3, string.Join(", ", writtenCanvasY.Select(v => v.ToString("F0"))));

        // 回到顶部：只有第一笔应该在视野里
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        Doc.InvalidateAll();
        SettleFrames(400);

        int first = ScreenProbe.CountMagenta((int)px - 60, (int)py - 60, 120, 120);
        Check("回顶部：第一笔仍在原位", first > 200, $"{first} 像素");

        int below = ScreenProbe.CountMagenta((int)px - 60, (int)py + 900, 120, 300);
        Check("回顶部：后两笔在视野外", below < 40, $"屏幕下方 {below} 像素（应为 0）");

        Console.WriteLine();
        Console.WriteLine($"  {(fail == 0 ? "PASS" : "FAIL")}：滚到哪儿都能写，写下的内容留在那个画布位置");
        Console.WriteLine();

        // 死锁回归：**空文档也必须能往下滚一屏**。
        // 之前只取"内容 ∪ 视口"时，空文档画布恰好一屏、下边界为 0，
        // 往下滚立刻被夹回去；而滚不动就写不到下面去 —— 死锁。
        Doc.Clear();
        Doc.ClearHistory();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        var empty = CanvasExtent;
        Check("空文档也能往下滚一屏",
              empty.MaxY - ViewportCanvas.MinY >= _virtualH * 2f,
              $"画布高 {empty.MaxY - empty.MinY:F0}px（一屏 {_virtualH}px）");
        Check("空文档不许往上滚过头", CanvasExtent.MinY <= ViewportCanvas.MinY + 0.5f,
              $"画布顶 {empty.MinY:F0}");
        Console.WriteLine();
        Console.WriteLine("  关于下限：数据层不设限才是对的（往下写不完）。");
        Console.WriteLine("  缺的不是下限，是**回顶部的办法**（滚动条 / 一键回顶）。");
        Console.WriteLine("  现在的实现只夹住了上边界（不许滚过内容顶部），下方不设限。");

        ViewOffsetY = 0f;
        Doc.Clear();
        Doc.ClearHistory();
        _quit = true;
    }

    private static double Median(List<double> v)
    {
        var s = v.OrderBy(x => x).ToList();
        return s.Count == 0 ? 0 : s[s.Count / 2];
    }

    /// <summary>
    /// 显存已用量（MB）。
    ///
    /// 注意：**别去解析 GpuMb() 返回的字符串**——那是"154/7396 MB"这种给人看的
    /// 格式，TryParse 会失败并静默返回 0（第一版就是这么错的，整列显示 0）。
    /// 要数就直接问同一个 API 要数。
    ///
    /// 为什么这项重要：核显的显存**是从系统内存里分的**，在 4GB 教室机上它和
    /// 进程内存抢的是同一块。--memory 报告里一万笔时显存 154MB，比点数据
    /// （3.9MB）大两个数量级——真正的大头很可能在这里。
    /// </summary>
    private static double GpuUsedMb()
    {
        try
        {
            if (Gfx.Adapter3 == null) return 0;
            var info = Gfx.Adapter3.QueryVideoMemoryInfo(0, Vortice.DXGI.MemorySegmentGroup.Local);
            return info.CurrentUsage / 1048576.0;
        }
        catch { return 0; }
    }

    /// <summary>
    /// 指数复制压力测验：画一笔，然后反复"全选 + 复制"（每次翻倍），
    /// 每轮打印对象数与内存。就是用户按 Ctrl+A / Ctrl+D 那个动作的等价脚本。
    ///
    /// 它能回答两件事：
    ///   · 内存随对象数量怎么涨 —— 换算成"每条多少 KB"
    ///   · 涨到多少开始变慢 —— 看每轮耗时（含一次完整的绘制）
    ///
    /// 这也是**和 WPF 版做同一个动作做对照**用的脚本。
    /// </summary>
    private void DupTest(int rounds)
    {
        Doc.Clear();
        Doc.ClearHistory();

        var s = new Stroke
        {
            Tool = Tool.Pen, Kind = StrokeKind.Freehand,
            Color = new Color4(0.9f, 0.2f, 0.2f, 1f),
            Width = 4f,
        };
        for (int i = 0; i < 20; i++) s.AddPoint(400 + i * 6f, 500 + MathF.Sin(i * 0.3f) * 40f, 0.5f, i);
        Doc.AddStroke(s);
        SettleFrames(150);

        Console.WriteLine();
        Console.WriteLine("=== 指数复制压力（Ctrl+A + Ctrl+D 的等价动作）===");
        Console.WriteLine("   轮次 |   对象数 |   工作集 |  私有   | 本轮耗时 | 每对象");
        Console.WriteLine("  ------|----------|----------|---------|----------|--------");

        double baseMb = WorkingSetMb();
        var clock = Stopwatch.StartNew();
        for (int r = 1; r <= rounds; r++)
        {
            double t0 = clock.Elapsed.TotalMilliseconds;

            Doc.Selected.Clear();
            foreach (var st in Doc.Strokes) Doc.Selected.Add(st);   // = Ctrl+A
            bool ok = Doc.DuplicateSelected();                       // = Ctrl+D
            _dirty = true;
            SettleFrames(30);

            double dt = clock.Elapsed.TotalMilliseconds - t0;
            double ws = WorkingSetMb();
            int count = Doc.Strokes.Count;
            Console.WriteLine($"  {r,6} | {count,8} | {ws,6:F0} MB | {PrivateMb(),5:F0} MB | "
                            + $"{dt,6:F0} ms | {(ws - baseMb) / Math.Max(1, count) * 1024:F1} KB");
            if (!ok)
            {
                Console.WriteLine("  到上限被拒绝——护栏生效，程序仍然可响应");
                break;
            }
        }
        _quit = true;
    }

    /// <summary>
    /// 选中与变换的性能自检：走**真实的拖动路径**（SetTransformLive → 内容层
    /// 区域修补），量每步要花多久。
    ///
    /// 两个关键设计：
    ///   ① **用窗口里的计数器，不用墙钟。** 墙钟会把 Present 的垂直同步等待算进去
    ///      （60Hz 屏幕上每帧 16ms），量到的是显示器刷新率，不是我们的开销。
    ///   ② **看最长的一步，不看平均。** 卡顿感来自长帧，平均值会把它们抹平。
    /// </summary>
    /// <summary>
    /// 板书长跑：模拟老师连续写字（默认 20 分钟、每秒 6 笔）。
    ///
    /// 和其它压测的区别：**按真实节奏生成真实形状的笔画**——一行一行往下写，
    /// 写满一屏就往下滚，每写一笔渲染一帧。输出是一条"笔画数 → 每帧代价"
    /// 的曲线：卡不卡、从多少笔开始卡，看曲线比看平均值有用。
    ///
    /// 参照点：2 屏写满约 400 笔（本机 2880x1800、每行 12 笔、每屏 16 行）；
    /// 20 分钟 × 6 笔/秒 = 7200 笔，大约 18 屏。
    /// </summary>
    private void WriteTest(double minutes, double strokesPerSecond)
    {
        int total = (int)Math.Round(minutes * 60 * strokesPerSecond);
        Console.WriteLine();
        Console.WriteLine($"=== 板书长跑（{minutes:F0} 分钟 × {strokesPerSecond:F0} 笔/秒 = {total} 笔）===");
        Console.WriteLine($"  本机 DPI 缩放 {DpiScale:F2}，逻辑屏 {_virtualW / DpiScale:F0}x{_virtualH / DpiScale:F0}");
        Console.WriteLine();
        Console.WriteLine("    笔画 |     点数 |  提交MB |  工作集 |    显存(已用/预算) |  记录均 | 记录最差 |  上屏均 | 分块光栅 | 几何存活 | 已释放");
        Console.WriteLine("  -------|----------|---------|---------|--------------------|---------|----------|---------|----------|----------|--------");

        Doc.Clear();
        Doc.ClearHistory();

        // 一行一行往下写。**坐标一律用画布坐标**：板书是往下长的，
        // 写满一屏把视图跟着往下带——这才是老师的真实动作。
        // （第一版这里写的是屏幕坐标，结果写出去的字其实在视野外，
        //   量出来的内存和耗时全都偏小，属于"测了个假的"。）
        float dpi = DpiScale;
        float marginX = _virtualX + 160f * dpi;
        float rightX = _virtualX + _virtualW - 160f * dpi;
        float lineH = 120f * dpi;
        if (DenseWrite)
        {
            // 密集模式：所有笔画都写在一小块区域里（对应"同一页墨迹很多"）。
            // 这样每块（tile）里会挤进成百上千条笔画，正好量出"块内条数 → 每帧代价"。
            marginX = _virtualX + _virtualW * 0.25f;
            rightX = marginX + 900f * dpi;
            lineH = 14f * dpi;
            Console.WriteLine($"  密集模式：所有笔画挤在 {rightX - marginX:F0}×{_virtualH * 0.6f:F0} 像素内，行距 {lineH:F0}");
        }
        float x = marginX;
        float y = _virtualY + 260f * dpi;
        var rnd = new Random(20260913);

        double recSum = 0, presSum = 0, rebSum = 0, recWorst = 0;
        int n = 0, sinceReport = 0;
        var clock = Stopwatch.StartNew();

        for (int i = 0; i < total; i++)
        {
            // 一笔"字"：一小段起伏的折线，40~140 个点（真实手写的量级）
            var s = new Stroke
            {
                Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                Color = PenColor, Width = 3.2f * dpi,
            };
            int pts = 40 + rnd.Next(100);
            float px = x, py = y + (float)(rnd.NextDouble() - 0.5) * 24f;
            float ang = 0f;
            for (int k = 0; k < pts; k++)
            {
                ang += (float)((rnd.NextDouble() - 0.5) * 0.9);
                px += 2.2f * dpi * MathF.Cos(ang) + 1.6f * dpi;
                py += 2.2f * dpi * MathF.Sin(ang);
                s.AddPoint(px, py, 0.5f + (float)rnd.NextDouble() * 0.5f, NowMs);
            }
            Doc.AddStroke(s);
            n++;
            sinceReport++;

            x = px + 14f * dpi;
            if (x > rightX)
            {
                x = marginX;
                y += lineH;
                // 视图跟着笔尖走：让正在写的这行固定在屏幕下方 72% 处。
                float wantTop = y - _virtualH * 0.72f;
                ViewOffsetY = _virtualY - wantTop;
                ClampViewOffset();
            }

            NowMs = _clock.Elapsed.TotalMilliseconds;
            RenderAll();

            double rec = _windows[0].LastRecordMs;
            recSum += rec; presSum += _windows[0].LastPresentMs; rebSum += _windows[0].LastRebuildMs;
            if (rec > recWorst) recWorst = rec;

            if (sinceReport >= 250 || i == total - 1)
            {
                sinceReport = 0;
                Console.WriteLine($"  {n,6} | {Doc.TotalPoints,8} | {Mem.Priv(),7:F0} | {Mem.Ws(),7:F0} |"
                                + $" {GpuMb(),18} | {recSum / n,7:F2} | {recWorst,8:F2} | {presSum / n,7:F2} | {rebSum / n,8:F2}"
                                + $" | {Stroke.LiveGeometries,8} | {Stroke.ReleasedGeometries,6}"
                                + $" | 块 {_windows[0].LastTileCount}/{_windows[0].LastTileVisible}"
                                + $"(预算 {_windows[0].LastTileBudget})");
            }
        }

        clock.Stop();
        Console.WriteLine();
        Console.WriteLine($"  合计 {n} 笔 / {Doc.TotalPoints} 点，墙钟 {clock.Elapsed.TotalSeconds:F0}s");
        Console.WriteLine($"  记录耗时 均值 {recSum / n:F2} ms，最差 {recWorst:F2} ms（超 16.7ms 就是掉帧）");
        Console.WriteLine($"  提交 {Mem.Priv():F0} MB，工作集 {Mem.Ws():F0} MB，显存 {GpuMb()}");

        // 收尾再量两件真实操作：整屏重画、滚一屏
        Doc.Dirty.MarkFull();
        NowMs = _clock.Elapsed.TotalMilliseconds;
        RenderAll();
        Console.WriteLine($"  整屏重画（MarkFull）: 记录 {_windows[0].LastRecordMs:F1} ms，分块光栅 {_windows[0].LastRebuildMs:F1} ms");

        // 这一项才是"细分缓存"的用武之地：把同一屏反复重画（拖动、来回滚动都属于这类）。
        // 缓存策略三档（全留 / 只留细分 / 全丢）在这里会拉开差距。
        double repaintSum = 0;
        const int repaints = 20;
        for (int i = 0; i < repaints; i++)
        {
            Doc.Dirty.MarkFull();
            NowMs = _clock.Elapsed.TotalMilliseconds;
            RenderAll();
            repaintSum += _windows[0].LastRecordMs;
        }
        Console.WriteLine($"  整屏连续重画 ×{repaints}: 平均记录 {repaintSum / repaints:F2} ms"
                        + $"（几何缓存存活 {Stroke.LiveGeometries}）");

        var sw = Stopwatch.StartNew();
        ViewOffsetY -= _virtualH;
        ClampViewOffset();
        NowMs = _clock.Elapsed.TotalMilliseconds;
        RenderAll();
        sw.Stop();
        Console.WriteLine($"  滚一屏: 记录 {_windows[0].LastRecordMs:F1} ms（含贴图），墙钟 {sw.Elapsed.TotalMilliseconds:F1} ms");
        Console.WriteLine($"  撤销栈: {Doc.UndoDepth} 步，仍引用 {Doc.HistoryStrokes} 条笔画；几何存活 {Stroke.LiveGeometries} 个");
        int withGeo = 0;
        foreach (var st in Doc.Strokes) if (st.Geometry != null) withGeo++;
        Console.WriteLine($"  直接数一遍：{Doc.Strokes.Count} 条笔画里有 {withGeo} 条挂着几何（其余是没画过、或几何已释放）");

        // 收尾：清空 + 强制回收，看这些内存在"文档数据"和"引擎池"之间怎么分。
        Doc.Clear();
        Doc.ClearHistory();
        RenderAll();
        GCSettings.LargeObjectHeapCompactionMode = GCLargeObjectHeapCompactionMode.CompactOnce;
        GC.Collect(2, GCCollectionMode.Aggressive, blocking: true, compacting: true);
        GC.WaitForPendingFinalizers();
        GC.Collect(2, GCCollectionMode.Aggressive, blocking: true, compacting: true);
        Mem.TrimWorkingSet();
        Console.WriteLine($"  清空 + 回收之后：提交 {Mem.Priv():F0} MB，工作集 {Mem.Ws():F0} MB，显存 {GpuMb()}，几何存活 {Stroke.LiveGeometries}");
        Gfx.TrimVideoMemory();
        Console.WriteLine($"  再 Trim 显存之后：提交 {Mem.Priv():F0} MB，工作集 {Mem.Ws():F0} MB，显存 {GpuMb()}");
        _quit = true;
    }

    /// <summary>
    /// 内存生命周期：一条一条问清"删掉之后内存去哪了"。
    ///
    /// 每个阶段都量提交大小 / 工作集 / 显存，并报告撤销栈此刻还引用着多少条笔画。
    /// 这样"是不是撤销的原因"就有一个数字答案，而不是靠猜。
    /// </summary>
    /// <summary>
    /// **"只补画新笔画"这条快路径的正确性自检。**
    ///
    /// 它省掉的是"整块重画"，而整块重画恰好也是唯一能擦掉旧墨的机会——
    /// 一旦判断错了（比如结构变了还去补画），屏幕上就会留下早该消失的墨，
    /// 这是那种"平时看不出来、演示时突然出现"的 bug。所以这里每一步都用
    /// **屏幕像素数**来判，不看内部状态：
    ///   新写的在 → 旧的还在 → 擦了就没了 → 撤销又回来 → 移走两边都对 → 清空全没。
    /// </summary>
    private void AppendPathTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 补画快路径正确性（只补画新笔画，不重画整块）===");

        int pass = 0, fail = 0;
        void Check(string what, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {what,-30} {detail}");
        }

        int ax = _virtualX + 600, ay = _virtualY + 380, aw = 520, ah = 200;
        int bx = _virtualX + 600, by = _virtualY + 860;

        Doc.Clear();
        Doc.ClearHistory();
        Tool = Tool.Pen;
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        RenderAll();
        SettleFrames(250);

        int baseA = ScreenProbe.CountMagenta(ax, ay, aw, ah);
        int baseB = ScreenProbe.CountMagenta(bx, by, aw, ah);
        Check("环境干净（背景没有洋红）", baseA + baseB < 100, $"A {baseA} / B {baseB} 像素");

        void AddLine(float cx, float cy)
        {
            var s = new Stroke
            {
                Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 20f * DpiScale,
            };
            s.AddPoint(cx - 160f * DpiScale, cy, 1f, 0);
            s.AddPoint(cx, cy, 1f, 0);
            s.AddPoint(cx + 160f * DpiScale, cy, 1f, 0);
            Doc.AddStroke(s);
            SettleFrames(250);
        }

        AddLine(ax + aw * 0.5f, ay + ah * 0.5f);
        Check("写入第一笔（走补画路径）>", ScreenProbe.CountMagenta(ax, ay, aw, ah) > 300,
            $"A {ScreenProbe.CountMagenta(ax, ay, aw, ah)} 像素");

        AddLine(bx + aw * 0.5f, by + ah * 0.5f);
        int afterB_A = ScreenProbe.CountMagenta(ax, ay, aw, ah);
        int afterB_B = ScreenProbe.CountMagenta(bx, by, aw, ah);
        Check("再写第二笔，第一笔没被弄丢", afterB_A > 300 && afterB_B > 300,
            $"A {afterB_A} / B {afterB_B} 像素");

        // 擦掉 A：这是"结构变化"，必须整块重画（补画清单要作废）
        Doc.BeginErase();
        Doc.EraseAt(ax + aw * 0.5f, ay + ah * 0.5f, 120f * DpiScale);
        Doc.EndErase();
        SettleFrames(300);
        int erasedA = ScreenProbe.CountMagenta(ax, ay, aw, ah);
        int erasedB = ScreenProbe.CountMagenta(bx, by, aw, ah);
        Check("擦掉 A：A 没了、B 还在", erasedA < 100 && erasedB > 300, $"A {erasedA} / B {erasedB} 像素");

        Doc.Undo();
        SettleFrames(300);
        int undoA = ScreenProbe.CountMagenta(ax, ay, aw, ah);
        int undoB = ScreenProbe.CountMagenta(bx, by, aw, ah);
        Check("撤销：A 回来、B 不受影响", undoA > 300 && undoB > 300, $"A {undoA} / B {undoB} 像素");

        // 撤销"新增"：把刚写的那一笔撤掉，它必须立刻从屏幕上消失
        AddLine(_virtualX + 1700, _virtualY + 1300);
        SettleFrames(250);
        int cxr = _virtualX + 1500, cyr = _virtualY + 1200, cwr = 520, chr = 200;
        int addC = ScreenProbe.CountMagenta(cxr, cyr, cwr, chr);
        Doc.Undo();
        SettleFrames(300);
        int undoAdd = ScreenProbe.CountMagenta(cxr, cyr, cwr, chr);
        Check("撤销刚写的一笔：屏幕上也要消失", addC > 300 && undoAdd < 100, $"写后 {addC} / 撤销后 {undoAdd}");

        // 全选整体移动：老位置要擦干净、新位置要出现
        Doc.Selected.Clear();
        foreach (var st in Doc.Strokes) Doc.Selected.Add(st);
        Doc.ApplyTransform(Matrix3x2.CreateTranslation(0, 260f * DpiScale));
        SettleFrames(350);
        int movedOldA = ScreenProbe.CountMagenta(ax, ay, aw, ah);
        int movedNewB = ScreenProbe.CountMagenta(bx - _virtualX + _virtualX, by, aw, ah);
        Check("整体下移：老位置擦干净、新位置有墨", movedOldA < 100 && movedNewB > 300,
            $"老位置 {movedOldA} / 新位置 {movedNewB}");

        Doc.Clear();
        SettleFrames(350);
        int cleared = ScreenProbe.CountMagenta(ax, ay, aw, ah) + ScreenProbe.CountMagenta(bx, by, aw, ah);
        Check("清空：屏幕上全都没有了", cleared < 150, $"残留 {cleared} 像素");

        Console.WriteLine();
        Console.WriteLine($"  合计 {pass + fail} 项：通过 {pass}，失败 {fail}");
        Console.WriteLine();
        _quit = true;
    }

    private void MemLifeTest(int strokes)
    {
        Console.WriteLine();
        Console.WriteLine($"=== 内存生命周期（{strokes} 笔）===");

        void Row(string what)
            => Console.WriteLine($"  {what,-22} 提交 {Mem.Priv(),7:F1} MB | 工作集 {Mem.Ws(),7:F1} MB | 显存 {GpuMb(),18}"
                               + $" | 文档 {Doc.Strokes.Count,7} 笔 | 撤销栈持有 {Doc.HistoryStrokes,7} 笔"
                               + $" | 几何存活 {Stroke.LiveGeometries,7}");

        void Reclaim()
        {
            // 文档说的标准组合：先让 GC 收干净（含 LOH 压缩），再让 Windows
            // 把回收过的页面从工作集里踢出去。
            GCSettings.LargeObjectHeapCompactionMode = GCLargeObjectHeapCompactionMode.CompactOnce;
            GC.Collect(2, GCCollectionMode.Aggressive, blocking: true, compacting: true);
            GC.WaitForPendingFinalizers();
            GC.Collect(2, GCCollectionMode.Aggressive, blocking: true, compacting: true);
            Mem.TrimWorkingSet();
        }

        void ReclaimAll()
        {
            Reclaim();
            bool trimmed = Gfx.TrimVideoMemory();      // 把驱动内部缓存也还回去
            Mem.TrimWorkingSet();
            Console.WriteLine($"  （显存 Trim 调用 {(trimmed ? "成功" : "失败")}）");
        }

        Doc.Clear();
        Doc.ClearHistory();
        RenderAll();
        Reclaim();
        Row("0. 空文档");

        GenerateStrokes(strokes);
        Reclaim();
        Row("1a. 只建笔画数据（没画）");
        RenderAll();
        Reclaim();
        Row("1. 生成之后");

        // = Ctrl+A + Delete：删除是"移进撤销栈"，不是消失
        Doc.Selected.Clear();
        foreach (var st in Doc.Strokes) Doc.Selected.Add(st);
        Doc.DeleteSelected();
        RenderAll();
        Row("2. 删除（未回收）");

        Reclaim();
        Row("3. 删除 + 强制回收");

        ReclaimAll();
        Row("3b. 再 Trim 显存");

        Doc.ClearHistory();
        Reclaim();
        Row("4. 再清空撤销栈");

        // 对照：走"清空"这条路
        GenerateStrokes(strokes);
        RenderAll();
        Doc.Clear();
        RenderAll();
        Reclaim();
        Row("5. 清空(Clear)+回收");

        Doc.ClearHistory();
        Reclaim();
        Row("6. 清空 + 清空撤销栈");

        ReclaimAll();
        Row("6b. 再 Trim 显存");

        Console.WriteLine();
        Console.WriteLine("  说明：'提交大小'才是真实占用；工作集（任务管理器那一列）会被系统随时收回。");
        Console.WriteLine("        '撤销栈持有' = 被删/被清空的笔画还挂在撤销栈里等着还原。");
        _quit = true;
    }

    private void SelBenchTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 选中与变换性能 ===");
        Console.WriteLine();
        Console.WriteLine("  ① 老做法：每帧改模型（SetTransformLive）→ 内容层按脏区修补");
        Console.WriteLine("  画布里  | 变换 | 修补均 | 修补最长 | 每帧记录均 | 每帧最长");
        Console.WriteLine("  --------|------|--------|----------|------------|--------");

        foreach (int total in new[] { 0, 1000, 10000 })
        {
            Doc.Clear();
            Doc.ClearHistory();
            if (total > 0) GenerateStrokes(total);
            SettleFrames(150);

            // 模拟真实用法：用户框选**一小撮**（20 个），而不是把一万笔全选中
            Doc.Selected.Clear();
            int pick = Math.Min(20, Doc.Strokes.Count);
            for (int i = 0; i < pick; i++) Doc.Selected.Add(Doc.Strokes[i]);

            var targets = Doc.Selected.ToArray();
            const int steps = 30;
            double patchSum = 0, recordSum = 0, patchMax = 0, recordMax = 0;
            var w = _windows[0];

            for (int k = 0; k < steps; k++)
            {
                var m = Matrix3x2.CreateTranslation(6f, 3f);
                foreach (var s in targets)
                {
                    Doc.Dirty.Add(s.PaddedBounds);          // 旧位置
                    Doc.SetTransformLive(s, s.Transform * m);
                    Doc.Dirty.Add(s.PaddedBounds);          // 新位置
                }
                _dirty = true;
                SettleFrames(10);

                double p = w.LastPatchMs, r = w.LastRecordMs;
                patchSum += p; recordSum += r;
                if (p > patchMax) patchMax = p;
                if (r > recordMax) recordMax = r;
            }

            Console.WriteLine($"  {total,7} | {targets.Length,4} | {patchSum / steps,6:F2} | "
                            + $"{patchMax,8:F2} | {recordSum / steps,10:F2} | {recordMax,8:F2}");
        }

        Console.WriteLine();
        Console.WriteLine("  判据：修补耗时**不该**随画布里已有笔画数明显增长——区域修补只处理");
        Console.WriteLine("  脏区内的对象，跟总数无关。若明显增长，说明退化成了整层重建。");

        // ---- ② 现在的拖动路径（方案 B：拖动预览）---------------------------
        //
        // 同一批对象、同样的拖动，走**真实的手势路径**：按住 → 每步挪一点 → 松手。
        // 这一条要盯的是两个数：
        //   · 内容层每帧重画的块数 —— 方案 B 之后应当是 **0**（模型不动、块全有效）；
        //   · 每帧记录耗时 —— 老做法那个"散布全屏 19ms"是否真的掉下来。
        Console.WriteLine();
        Console.WriteLine("  ② 现在的拖动（方案 B：拖动预览，内容层不动）");
        Console.WriteLine("  画布里  | 变换 | 起手一次重画 | 拖动中重画 | 拖动中补丁均 | 每帧记录均 | 每帧最长");
        Console.WriteLine("  --------|------|--------------|------------|--------------|------------|--------");
        foreach (int total in new[] { 1000, 10000 })
        {
            Doc.Clear();
            Doc.ClearHistory();
            if (total > 0) GenerateStrokes(total);
            SettleFrames(150);

            // 刻意挑**散布全屏**的 20 条（和老做法那张表同一个场景）
            Doc.Selected.Clear();
            int pick = Math.Min(20, Doc.Strokes.Count);
            int stride = Math.Max(1, Doc.Strokes.Count / Math.Max(1, pick));
            for (int i = 0; i < pick; i++)
                Doc.Selected.Add(Doc.Strokes[Math.Min(Doc.Strokes.Count - 1, i * stride)]);

            var fr = SelectionHandles.FrameOf(Doc.Selected);
            var aabb = fr.CanvasAabb;
            float px = (aabb.MinX + aabb.MaxX) * 0.5f, py = (aabb.MinY + aabb.MaxY) * 0.5f;
            bool took = SelectionGestureForTest(px, py);

            var w = _windows[0];
            const int steps = 30;
            double patchSum = 0, recordSum = 0, recordMax = 0, patchMax = 0;
            double tilesSum = 0; int tilesMax = 0;
            int startTiles = 0; double startPatchMs = 0;
            for (int k = 0; k < steps; k++)
            {
                UpdateSelectionGestureForTest(px + 6f * (k + 1), py + 3f * (k + 1));
                SettleFrames(10);
                recordMax = Math.Max(recordMax, w.LastRecordMs);
                if (k == 0)
                {
                    // 第 0 步 = **起手那一下**：把这一批从内容层摘出去，那些块要重画一次。
                    // 这一笔是一次性的，不能混进"拖动中每帧"的均值里（混进去会把它算成
                    // 每个拖动帧的代价，看着像没优化）。
                    startTiles = w.LastPatchCount;
                    startPatchMs = w.LastPatchMs;
                    continue;
                }
                patchSum += w.LastPatchMs; recordSum += w.LastRecordMs;
                patchMax = Math.Max(patchMax, w.LastPatchMs);
                tilesSum += w.LastPatchCount;
                tilesMax = Math.Max(tilesMax, w.LastPatchCount);
            }
            EndSelectionGestureForTest();
            SettleFrames(60);
            int steadySteps = steps - 1;

            Console.WriteLine($"  {total,7} | {pick,4} | {startTiles,7} 块/{startPatchMs,5:F1}ms | "
                            + $"{tilesSum / steadySteps,7:F1} 块 | {patchSum / steadySteps,9:F2} ms | "
                            + $"{recordSum / steadySteps,8:F2} ms | {recordMax,8:F2} ms"
                            + (took ? "" : "   （！手势没接住）"));
            Console.WriteLine($"          （拖动中内容层重画的块：均 {tilesSum / steadySteps:F1}、最多 {tilesMax}"
                            + $"，应当是 0；起手那一下 {startTiles} 块是一次性的）");
        }
        Console.WriteLine();
        Console.WriteLine("  判据：②的\"内容层重画块/帧\"应当是 0（模型不动，只画浮动层预览），");
        Console.WriteLine("        每帧耗时应当与\"选中的这几条\"成正比，而不是与\"走过的面积\"成正比。");
        Doc.Clear();
        Doc.ClearHistory();
        _quit = true;
    }

    /// <summary>
    /// 拖动预览的渲染核对：把选中对象用**实时变换**（SetTransformLive，
    /// 就是拖动中走的那条路径）挪走并挂着不动，由外部截图。
    ///
    /// 验的是"内容层会不会跟着修补"。之前漏了 bump 版本号，表现就是
    /// 蓝框跟着走、墨迹停在原地——截图上一眼能看出来：修好的话墨迹在框里，
    /// 没修的话墨迹还留在原来的地方，跟框分了家。
    /// </summary>
    private void SelDragShowcase()
    {
        SelShowcase();                       // 先摆好两条笔迹和选中框

        var sel = Doc.Selected.ToArray();
        var sb = EditRegion.Of(sel);
        var c = new Vector2((sb.MinX + sb.MaxX) * 0.5f, (sb.MinY + sb.MaxY) * 0.5f);
        var m = Matrix3x2.CreateScale(1.25f, 1.25f, c) * Matrix3x2.CreateTranslation(120f, -60f);

        // 完全照 UpdateSelDrag 的做法：标脏旧位置 → 实时改变换 → 标脏新位置
        foreach (var s in sel)
        {
            Doc.Dirty.Add(s.PaddedBounds);
            Doc.SetTransformLive(s, s.Transform * m);
            Doc.Dirty.Add(s.PaddedBounds);
        }

        SettleFrames(700);
        Console.WriteLine("已用实时变换挪走，等外部截图（这个模式不会自己退出）");
    }

    /// <summary>
    /// **截图取景框**的离屏出图：摆几笔背景墨 → 把取景框摆在中间 → 拍下来。
    ///
    /// 看的是两件自检读不出来的事：**框和角标的粗细在 2 倍屏上顺不顺眼**，
    /// 以及拖动中那个**尺寸读数胶囊**跟框的距离、字的大小合不合适。
    /// </summary>
    /// <summary>
    /// **导出对话框探针**：真的弹一次系统"另存为"，同时由一个后台线程去点它的
    /// "保存类型"下拉，并把每一步截下来。
    ///
    /// 为什么要专门做它：这里出过两次问题（"选不到 jpg"、"对话框被自己的下拉盖住"），
    /// 而**这些问题只能靠真机 + 看图判断**——系统对话框是另一个窗口类，
    /// 我们的自检（合成输入 + 数像素）碰不到它的内部控件。探针把"找窗口 →
    /// 点下拉 → 截图 → 关掉"这套动作固定下来，改一次就能再验一次。
    ///
    /// 用法：`--dialogprobe [前缀]`，产出 `<前缀>-1-打开时.bmp`、`-2-点下拉后.bmp`。
    /// </summary>
    private void DialogProbe(string prefix)
    {
        BoardOn = true;
        Tool = Tool.Marquee;
        Doc.Clear();
        Doc.ClearHistory();
        // 几条横线铺在屏幕中间：对话框会压在上面，正好看"框和墨谁在上面"
        for (int i = 0; i < 5; i++)
        {
            var s = new Stroke
            {
                Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                Color = new Color4(0.85f, 0.15f, 0.15f, 1f), Width = 8f * DpiScale,
            };
            float y = _virtualY + _virtualH * 0.35f + i * 90f * DpiScale;
            s.AddPoint(_virtualX + _virtualW * 0.15f, y, 1f, i * 4);
            s.AddPoint(_virtualX + _virtualW * 0.85f, y, 1f, i * 4 + 2);
            Doc.AddStroke(s);
        }
        Doc.SelectOnly(Doc.Strokes.ToArray());
        SettleFrames(700);

        var t = new Thread(() => DialogProbeThread(prefix)) { IsBackground = true };
        t.Start();

        ExportDialogEnabled = true;
        ExportSelection(1);                 // 阻塞在系统对话框里，后台线程在操作它
        Console.WriteLine("dialogprobe：对话框已关闭（走的是取消那条路）");

        // 走了 `--save` 的话，这里验"真的写出来了"（写完就删，不留垃圾）
        if (DialogProbeCheckExport && LastExportPath != null)
        {
            var fi = new FileInfo(LastExportPath);
            Console.WriteLine(fi.Exists && fi.Length > 0
                ? $"dialogprobe：**文件真的写出来了** {LastExportPath}（{fi.Length} 字节，"
                  + $"类型第 {LastExportFilterIndex} 条）——对话框那条链是通的"
                : $"dialogprobe：**没写出来** {LastExportPath}");
            try { fi.Delete(); } catch { }
            Console.WriteLine("dialogprobe：测试文件已删掉");
            DialogProbeCheckExport = false;
        }
        _quit = true;
    }

    private static bool DialogProbeCheckExport;

    private static IntPtr ProbeFindDialog()
    {
        IntPtr found = IntPtr.Zero;
        uint me = (uint)Environment.ProcessId;
        var sb = new System.Text.StringBuilder(64);
        Native.EnumWindows((h, _) =>
        {
            Native.GetWindowThreadProcessId(h, out uint pid);
            if (pid != me) return true;
            Native.GetClassNameW(h, sb, sb.Capacity);
            if (sb.ToString() != "#32770") return true;
            found = h;
            return false;
        }, IntPtr.Zero);
        return found;
    }

    private static string ProbeClassName(IntPtr h)
    {
        var sb = new System.Text.StringBuilder(256);
        Native.GetClassNameW(h, sb, sb.Capacity);
        return sb.ToString();
    }

    private void DialogProbeThread(string prefix)
    {
        IntPtr dlg = IntPtr.Zero;
        for (int i = 0; i < 120 && dlg == IntPtr.Zero; i++)
        {
            Thread.Sleep(100);
            dlg = ProbeFindDialog();
        }
        if (dlg == IntPtr.Zero) { Console.WriteLine("dialogprobe：6 秒内没等到对话框"); return; }

        Native.GetWindowRect(dlg, out var r);
        Console.WriteLine($"dialogprobe：对话框 {dlg} 在 ({r.Left},{r.Top})，{r.Width}×{r.Height}");

        // 等 1.2 秒：让看门线程把它顶到最前、也让对话框把自己的子控件建完
        // （第一次探针在"刚找到"就查子窗口，一个 ComboBox 都没查到）。
        Thread.Sleep(1200);
        Native.GetWindowRect(dlg, out r);
        ShotRegion(prefix + "-0-全屏.bmp", 0, 0, 2880, 1800);
        ShotRegion(prefix + "-1-打开时.bmp", r.Left - 30, r.Top - 30, r.Width + 60, r.Height + 60);

        // 我们覆盖层这会儿在对话框上面还是下面？看两个点上的最上层窗口是谁。
        int midX = (r.Left + r.Right) / 2, midY = (r.Top + r.Bottom) / 2;
        IntPtr atMid = Native.WindowFromPoint(new Native.POINT { X = midX, Y = midY });
        Console.WriteLine($"dialogprobe：对话框正中那一点最上层 = {atMid}（{ProbeClassName(atMid)}）"
                        + $"；我们的覆盖层 = {_windows[0].Hwnd}（{ProbeClassName(_windows[0].Hwnd)}）");

        // 子控件清单：看对话框里到底有什么（第一次没找到 ComboBox）
        int n = 0;
        Native.EnumChildWindows(dlg, (h, _) =>
        {
            if (n++ < 40)
            {
                Native.GetWindowRect(h, out var cr0);
                Console.WriteLine($"    子窗口 {ProbeClassName(h),-20} ({cr0.Left},{cr0.Top})-({cr0.Right},{cr0.Bottom})");
            }
            return true;
        }, IntPtr.Zero);

        // "保存类型"那个下拉：它和"文件名"是同一类控件（都是 ComboBox），
        // **"保存类型"是下面那个**（文件名在上）。第一版取了第一个 → 点到了文件名框。
        // 所以这里取**位置最靠下的那一个**。
        IntPtr combo = IntPtr.Zero;
        string comboClass = "";
        int bestTop = int.MinValue;
        Native.EnumChildWindows(dlg, (h, _) =>
        {
            string cls = ProbeClassName(h);
            if (cls != "ComboBox" && cls != "ComboBoxEx32") return true;
            Native.GetWindowRect(h, out var cr0);
            if (cr0.Top <= bestTop) return true;
            bestTop = cr0.Top; combo = h; comboClass = cls;
            return true;
        }, IntPtr.Zero);

        if (combo == IntPtr.Zero)
        {
            Console.WriteLine("dialogprobe：没找到文件类型下拉（子窗口里没有 ComboBox）");
        }
        else
        {
            Native.GetWindowRect(combo, out var cr);
            // 子窗口的矩形**大多数时候是屏幕坐标**（对话框移到 (779,330) 之后，
            // 它也跟着报 (1042,1088)）。但对话框还在 (0,0) 时两种读法长得一模一样，
            // 分不清——所以这里按"在不在对话框矩形里"判一下，不在就补上对话框原点。
            int ox = 0, oy = 0;
            bool insideDlg = cr.Left >= r.Left && cr.Top >= r.Top
                          && cr.Right <= r.Right && cr.Bottom <= r.Bottom;
            if (!insideDlg) { ox = r.Left; oy = r.Top; }
            int cx = ox + cr.Right - 14, cy = oy + (cr.Top + cr.Bottom) / 2;
            Console.WriteLine($"dialogprobe：下拉 {comboClass} 读到 ({cr.Left},{cr.Top})-({cr.Right},{cr.Bottom})，"
                            + $"对话框 ({r.Left},{r.Top})-({r.Right},{r.Bottom})，"
                            + $"{(insideDlg ? "按屏幕坐标" : "按相对坐标＋原点")} → 点 ({cx},{cy})");

            // **先看一眼：这个点上是谁的窗口**（我们覆盖层是置顶的，很可能抢走这一下）
            IntPtr over = Native.WindowFromPoint(new Native.POINT { X = cx, Y = cy });
            Console.WriteLine($"dialogprobe：那一点上最上层的窗口 = {over}（{ProbeClassName(over)}）"
                            + $"，我们的覆盖层 = {_windows[0].Hwnd}");

            SendMouse(cx, cy, 0);
            Thread.Sleep(60);
            SendMouse(cx, cy, Native.MOUSEEVENTF_LEFTDOWN);
            Thread.Sleep(50);
            SendMouse(cx, cy, Native.MOUSEEVENTF_LEFTUP);
            // **连着拍三张**：判"点开就收回去"这种毛病，得看它是没开、还是开了一下又被关掉。
            int sx = ox + cr.Left - 30, sy = oy + cr.Bottom - 40;
            int sw = Math.Max(cr.Width + 60, 400), sh = 460;
            Thread.Sleep(150);
            ShotRegion(prefix + "-2a-点后150ms.bmp", sx, sy, sw, sh);
            Thread.Sleep(250);
            ShotRegion(prefix + "-2b-点后400ms.bmp", sx, sy, sw, sh);
            Thread.Sleep(500);
            ShotRegion(prefix + "-2c-点后900ms.bmp", sx, sy, sw, sh);

            // 下拉里**第二项就是 JPEG**（PNG 在上、JPEG 在下，每项约 30 物理像素）。
            // 点它一下，看文件名后缀会不会跟着变成 .jpg——这就是用户要的那条路。
            int jx = ox + cr.Left + 200, jy = oy + cr.Bottom + 45;
            SendMouse(jx, jy, 0);
            Thread.Sleep(60);
            SendMouse(jx, jy, Native.MOUSEEVENTF_LEFTDOWN);
            Thread.Sleep(50);
            SendMouse(jx, jy, Native.MOUSEEVENTF_LEFTUP);
            Thread.Sleep(500);
            ShotRegion(prefix + "-3-选了JPG.bmp", sx, sy, sw, sh);

            // `--save`：一路走到底——把文件名改成临时路径，点"保存"，
            // 看我们的代码是不是真的把图写出来了（写完由主线程验证并删掉）。
            if (Environment.GetCommandLineArgs().Contains("--save"))
            {
                DialogProbeCheckExport = true;
                IntPtr saveBtn = IntPtr.Zero;
                int leftMost = int.MaxValue;
                Native.EnumChildWindows(dlg, (h, _) =>
                {
                    string cls = ProbeClassName(h);
                    Native.GetWindowRect(h, out var hr);
                    if (cls == "Button" && hr.Top > r.Top + r.Height * 3 / 4 && hr.Left < leftMost)
                    {
                        leftMost = hr.Left;                                 // 下半部分最左边那个 = 保存
                        saveBtn = h;
                    }
                    return true;
                }, IntPtr.Zero);

                if (saveBtn != IntPtr.Zero)
                {
                    Native.GetWindowRect(saveBtn, out var br);
                    int bx = (br.Left + br.Right) / 2, by = (br.Top + br.Bottom) / 2;
                    Console.WriteLine($"dialogprobe：点「保存」({bx},{by})");
                    SendMouse(bx, by, 0);
                    Thread.Sleep(60);
                    SendMouse(bx, by, Native.MOUSEEVENTF_LEFTDOWN);
                    Thread.Sleep(50);
                    SendMouse(bx, by, Native.MOUSEEVENTF_LEFTUP);
                    return;                       // 让它自己去保存、关框，别再补 WM_CLOSE
                }
            }
        }

        Thread.Sleep(300);
        Native.PostMessage(dlg, 0x0010 /*WM_CLOSE*/, IntPtr.Zero, IntPtr.Zero);
    }

    private static void ShotRegion(string path, int x, int y, int w, int h)
    {
        bool ok = ScreenProbe.SaveBmp(path, x, y, w, h);
        Console.WriteLine(ok ? $"  出图 {System.IO.Path.GetFullPath(path)}（CWD = {Environment.CurrentDirectory}）"
                             : $"  出图失败 {path}");
    }

    private void CaptureShow(string path)
    {
        SetUiFactory(() => new InkUi.FullUi());
        BoardOn = true;                     // 白底，不然框压在桌面上看不清
        Doc.Clear();
        Doc.ClearHistory();

        float cx = VirtualScreen.MinX + 700, top = VirtualScreen.MinY + 300;
        var s = new Stroke
        {
            Tool = Tool.Pen, Kind = StrokeKind.Freehand,
            Color = new Color4(0.11f, 0.12f, 0.15f, 1f), Width = 5f * DpiScale,
        };
        for (int i = 0; i <= 60; i++)
        {
            float t = i / 60f;
            s.AddPoint(cx - 300 + t * 620, top + 120 + MathF.Sin(t * 6f) * 60f, 0.5f, i * 8);
        }
        Doc.AddStroke(s);

        // 取景区：**故意取一块不是整数的尺寸**（520×300 逻辑像素），读数才有看头
        CaptureActive = true;
        CapMinX = cx - 260; CapMinY = top;
        CapMaxX = cx + 260; CapMaxY = top + 300 * DpiScale;

        var r = new RectF { MinX = CapMinX, MinY = CapMinY, MaxX = CapMaxX, MaxY = CapMaxY };
        // 读数画在框左下角外侧，脏区那一套逻辑和抓屏时一致，所以这里也把它算进去
        r.Add(new RectF
        {
            MinX = r.MinX, MinY = r.MaxY,
            MaxX = r.MinX + 110f * DpiScale, MaxY = r.MaxY + 40f * DpiScale,
        });
        if (!OffscreenFloatingShot(path, r.Inflate(20f))) Console.WriteLine("出图失败");
        CaptureActive = false;
        _quit = true;
    }

    /// <summary>
    /// 编辑命令自检：复制 / 删除 / 翻转 / 旋转，外加操作条的命中判定。
    ///
    /// 这四个动作是操作条按钮直接调的，但按钮没法自动点（要合成鼠标事件），
    /// 所以这里直接验它们背后的命令，把**撤销语义**一并验掉——
    /// 一步操作必须正好对应一条撤销记录，多一条少一条都是 bug。
    /// </summary>
    private void EditTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 编辑命令自检（复制 / 删除 / 翻转 / 旋转）===");

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"    {name,-24}{(ok ? "PASS" : "FAIL")}  {detail}");
        }

        Stroke Make(float x)
        {
            var s = new Stroke
            {
                Tool = Tool.Pen, Kind = StrokeKind.Freehand, Width = 4f,
                Color = new Color4(0.9f, 0.2f, 0.2f, 1f),
            };
            for (int i = 0; i < 20; i++) s.AddPoint(x + i * 3f, 500 + i * 2f, 0.5f, i);
            return s;
        }
        float Width(Stroke s) => s.WorldBounds.MaxX - s.WorldBounds.MinX;
        float Height(Stroke s) => s.WorldBounds.MaxY - s.WorldBounds.MinY;

        Doc.Clear();
        Doc.ClearHistory();
        var a = Make(300); Doc.AddStroke(a);
        var b = Make(600); Doc.AddStroke(b);

        // ---- 复制 ----
        Doc.Selected.Clear(); Doc.Selected.Add(a); Doc.Selected.Add(b);
        int n0 = Doc.Strokes.Count, d0 = Doc.UndoDepth;
        Doc.DuplicateSelected(30, 30);
        Check("复制新增对象", Doc.Strokes.Count == n0 + 2, $"{n0} -> {Doc.Strokes.Count}");
        Check("复制只记一步", Doc.UndoDepth == d0 + 1, $"{d0} -> {Doc.UndoDepth}");
        Check("选中切到副本", Doc.Selected.Count == 2 && !ReferenceEquals(Doc.Selected[0], a), "");
        Check("副本是新身份", Doc.Selected[0].Id != a.Id, $"{a.Id} -> {Doc.Selected[0].Id}");
        Doc.Undo();
        Check("撤销复制", Doc.Strokes.Count == n0, $"{Doc.Strokes.Count}");

        // ---- 翻转 ----
        Doc.Selected.Clear(); Doc.Selected.Add(a);
        var wb = a.WorldBounds;
        Doc.ApplyTransform(SelectionHandles.MirrorMatrix(wb, horizontal: true));
        Check("左右翻转：包围盒不变",
              Math.Abs(a.WorldBounds.MinX - wb.MinX) < 0.5f && Math.Abs(Width(a) - (wb.MaxX - wb.MinX)) < 0.5f, "");
        Check("翻转后行列式为负", a.Transform.M11 * a.Transform.M22 - a.Transform.M12 * a.Transform.M21 < 0f, "");
        Doc.Undo();
        Check("撤销翻转回原位", Math.Abs(a.WorldBounds.MinX - wb.MinX) < 0.05f,
              $"MinX {a.WorldBounds.MinX:F2} vs {wb.MinX:F2}");

        // ---- 旋转 90°：宽高应该互换 ----
        var wb2 = a.WorldBounds;
        var c = new Vector2((wb2.MinX + wb2.MaxX) * 0.5f, (wb2.MinY + wb2.MaxY) * 0.5f);
        Doc.ApplyTransform(Matrix3x2.CreateRotation(MathF.PI / 2f, c));
        Check("旋转 90°：宽高互换",
              Math.Abs(Width(a) - (wb2.MaxY - wb2.MinY)) < 0.5f
              && Math.Abs(Height(a) - (wb2.MaxX - wb2.MinX)) < 0.5f,
              $"{Width(a):F1}×{Height(a):F1}");
        Doc.Undo();

        // ---- 删除 ----
        Doc.Selected.Clear(); Doc.Selected.Add(a);
        int n1 = Doc.Strokes.Count;
        Doc.DeleteSelected();
        Check("删除选中", Doc.Strokes.Count == n1 - 1 && Doc.Selected.Count == 0, $"{n1} -> {Doc.Strokes.Count}");
        Doc.Undo();
        Check("撤销删除", Doc.Strokes.Count == n1, $"{Doc.Strokes.Count}");

        // ---- 操作条命中 ----
        Doc.Selected.Clear(); Doc.Selected.Add(a); Doc.Selected.Add(b);
        var sb = EditRegion.Of(Doc.Selected);
        float dpi = DpiScale;
        var bar = SelectionHandles.BarRect(sb, dpi, ViewportCanvas);
        Check("操作条在选中框下方", bar.MinY > sb.MaxY, $"间距 {bar.MinY - sb.MaxY:F0}px");

        bool allHit = true; string bad = "";
        for (int i = 0; i < SelectionHandles.BarButtonCount; i++)
        {
            var r = SelectionHandles.BarButtonRect(i, sb, dpi, ViewportCanvas);
            int got = SelectionHandles.BarButtonAt((r.MinX + r.MaxX) * 0.5f, (r.MinY + r.MaxY) * 0.5f,
                                                   sb, dpi, ViewportCanvas);
            if (got != i) { allHit = false; bad = $"第{i}个按钮命中到 {got}"; }
        }
        Check("每个按钮都能点中", allHit, bad);
        Check("框外不误判",
              SelectionHandles.BarButtonAt(bar.MinX - 30, bar.MinY + 5, sb, dpi, ViewportCanvas) == -1, "");

        // ---- 导出：**点一下直接走导出，不再开自己的格式面板** ----
        //
        // 曾经这里点"导出"会先开一层我们自己的两格面板（PNG 透明底 / JPG 白底），
        // 那是为了绕开"系统对话框的下拉点不开"。真因（覆盖层每秒抢一次置顶）修掉之后，
        // 用户 2026-09-17 说"那下面这两个图标就没有用了吧，用户都可以自己保存图片了"——
        // 删掉。现在格式在**系统对话框**的类型栏里选（见 ExportFormats，四种都写明了优势）。
        //
        // 自检里对话框是关着的（`ExportDialogEnabled = false`），所以这里只能验
        // "那一下真的走到了导出这条路"（计数器）＋"没有把任何面板打开"。
        {
            int before = ExportAttempts;
            RunBarActionForTest((int)SelBarButton.Export);
            Check("点「导出」直接走导出（不再开格式面板）",
                  ExportAttempts == before + 1 && SelPanelOpen == SelPanel.None,
                  $"试了 {before} → {ExportAttempts} 次，面板 = {SelPanelOpen}");

            // 四种格式的"扩展名 → 编码器 + 底色"这套规则是纯逻辑，这里一并钉住：
            // 尤其是**有损/无透明通道的格式绝不给透明通道**（否则透明处会变黑块）。
            Check("格式表：四条，扩展名各就各位",
                  ExportFormats.Count == 4
                  && ExportFormats.ExtensionFor(1) == ".png"
                  && ExportFormats.ExtensionFor(2) == ".jpg"
                  && ExportFormats.ExtensionFor(3) == ".png"
                  && ExportFormats.ExtensionFor(4) == ".bmp",
                  string.Join(" / ", Enumerable.Range(1, ExportFormats.Count)
                                                .Select(i => ExportFormats.ExtensionFor(i))));
            Check("格式表：四种类型的名字里都写明了优势（不是光一个格式名）",
                  ExportFormats.Filter.Contains("贴课件首选")
                  && ExportFormats.Filter.Contains("好发微信邮件")
                  && ExportFormats.Filter.Contains("深色模板上不露底")
                  && ExportFormats.Filter.Contains("老软件也能打开"),
                  "四条都带说明");

            // **记住上次选的那一条**（常用 JPG 的老师不用每次去下拉里找）。
            // 存的是"类型栏的第几条"，读的时候越界/坏值一律回到第 1 条。
            var saved = GetUiPref("exportFormat");
            SetUiPref("exportFormat", null);
            int def0 = ExportDefaultFilterIndex();
            SetUiPref("exportFormat", "3");
            int def3 = ExportDefaultFilterIndex();
            SetUiPref("exportFormat", "99");
            int defBad = ExportDefaultFilterIndex();
            SetUiPref("exportFormat", saved);
            Check("记住上次的格式：没存过→第 1 条、存过→照存、坏值→回到第 1 条",
                  def0 == 1 && def3 == 3 && defBad == 1,
                  $"默认 {def0}，存 3 → {def3}，存 99 → {defBad}");
        }

        Console.WriteLine();
        Console.WriteLine(fail == 0 ? "  PASS: 编辑命令与操作条命中都正确" : $"  FAIL: {fail} 项不对");
        _quit = true;
    }

    /// <summary>
    /// 把选中框和手柄摆出来给人看。跟 --beautifyshowcase 一个路子：
    /// 画好挂着不动，由外部截图，用来肉眼核对观感（不是自动判定）。
    /// </summary>
    private void SelShowcase(string path = null)
    {
        BoardOn = true;                 // 白底，不然手柄压在桌面上看不清
        Doc.Clear();
        Doc.ClearHistory();

        // **必须挂上界面**：操作条/小面板的颜色与投影是界面推给引擎的
        // （见 IUiHost.SetFloatingTheme）——不挂界面拿到的是 UiTheme.Default 那套兜底，
        // 出的图就不是产品里看到的样子。
        // 注意顺序：**偏好要先设**，SetUiFactory 是立刻挂载的（挂载时就会读偏好）。
        // --dark：深色那档也出一张（浮层的深色是这一轮新加的）
        if (Environment.GetCommandLineArgs().Contains("--dark")) SetUiPref("dark", "1");
        SetUiFactory(() => new InkUi.FullUi());

        float cx = VirtualScreen.MinX + 720;
        float top = VirtualScreen.MinY + 300;

        // 一条自由笔迹
        var free = new Stroke
        {
            Tool = Tool.Pen, Kind = StrokeKind.Freehand,
            Color = new Color4(0.11f, 0.12f, 0.15f, 1f), Width = 6f,
        };
        for (int i = 0; i <= 80; i++)
        {
            float t = i / 80f;
            free.AddPoint(cx - 320 + t * 640, top + 80 + MathF.Sin(t * 7f) * 70f, 0.5f, i * 8);
        }
        Doc.AddStroke(free);

        // 一个带旋转 + 非等比缩放的矩形：用来核对"变换参与选中框"这件事
        var rect = new Stroke
        {
            Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
            Color = new Color4(0.95f, 0.18f, 0.18f, 1f), Width = 6f,
        };
        rect.AddPoint(cx - 260, top + 350, 1f, 0);
        rect.AddPoint(cx + 260, top + 520, 1f, 0);
        var center = new Vector2(cx, top + 435);
        rect.Transform = Matrix3x2.CreateRotation(0.14f, center)
                      * Matrix3x2.CreateScale(1.3f, 0.85f, center);
        Doc.AddStroke(rect);

        // 一条**很宽**的荧光笔：用来看选中框有没有把墨圈住。
        // 框按中心线算的话，这条 64 像素宽的带子上会压着四条边——一眼就能看出来。
        var wide = new Stroke
        {
            Tool = Tool.Highlighter, Kind = StrokeKind.Freehand,
            Color = HighlighterCurrent, Width = 32f * DpiScale,
        };
        wide.AddPoint(cx - 420, top + 690, 0.5f, 0);
        wide.AddPoint(cx + 420, top + 690, 0.5f, 1);
        Doc.AddStroke(wide);

        Doc.Selected.Clear();
        foreach (var s in Doc.Strokes) Doc.Selected.Add(s);
        Doc.InvalidateAll();
        SettleFrames(800);

        if (path == null)
        {
            Console.WriteLine("选中框已摆好，等外部截图（这个模式不会自己退出）");
            return;
        }

        // 出图（离屏，锁屏/远程也能出）：范围 = 选中框 ∪ 操作条，再留一圈给投影。
        // 操作条挂在框下方（SelectionHandles.BarRect 算的就是那个位置），
        // 所以把它一起并进来，否则出图会把操作条切掉一半。
        var aabb = SelectionHandles.FrameOf(Doc.Selected).CanvasAabb;
        var bar = SelectionHandles.BarRect(aabb, DpiScale, ViewportCanvas);
        var region = new RectF
        {
            MinX = MathF.Min(aabb.MinX, bar.MinX), MinY = MathF.Min(aabb.MinY, bar.MinY),
            MaxX = MathF.Max(aabb.MaxX, bar.MaxX), MaxY = MathF.Max(aabb.MaxY, bar.MaxY),
        };
        if (!OffscreenFloatingShot(path, region.Inflate(30f))) Console.WriteLine("出图失败");
        _quit = true;
    }

    /// <summary>
    /// 选中手柄自检：位置、命中、以及每个手柄拖出来的是什么矩阵。
    ///
    /// 为什么要专门测：变换矩阵错了是那种"看着能动、但缩放之后再撤销
    /// 回不到原样"的问题，肉眼基本发现不了，而且会累积误差。
    /// </summary>
    private void HandleTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 选中手柄自检（位置 / 命中 / 变换矩阵）===");

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"    {name,-22}{(ok ? "PASS" : "FAIL")}  {detail}");
        }

        float dpi = DpiScale;
        var b = new RectF { MinX = 400, MinY = 300, MaxX = 800, MaxY = 600 };
        float cx = (b.MinX + b.MaxX) * 0.5f;

        // ---- 位置 ----
        var tl = SelectionHandles.Position(SelHandle.TopLeft, b, dpi);
        var top = SelectionHandles.Position(SelHandle.Top, b, dpi);
        var rot = SelectionHandles.Position(SelHandle.Rotate, b, dpi);
        Check("左上角位置", Math.Abs(tl.X - b.MinX) < 0.01f && Math.Abs(tl.Y - b.MinY) < 0.01f,
              $"({tl.X:F0},{tl.Y:F0})");
        Check("上边中点位置", Math.Abs(top.X - cx) < 0.01f && Math.Abs(top.Y - b.MinY) < 0.01f, "");
        Check("旋转手柄在上方外侧",
              Math.Abs(rot.X - cx) < 0.01f && rot.Y < b.MinY - 20f,
              $"离上边 {b.MinY - rot.Y:F0}px");

        // ---- 命中 ----
        Check("点上四角命中", SelectionHandles.HitTest(tl.X, tl.Y, b, dpi) == SelHandle.TopLeft, "");
        Check("旋转手柄命中", SelectionHandles.HitTest(rot.X, rot.Y, b, dpi) == SelHandle.Rotate, "");
        float far = SelectionHandles.HitRadiusLogical * dpi * 1.6f;
        Check("偏离太远不命中",
              SelectionHandles.HitTest(tl.X - far, tl.Y, b, dpi) == SelHandle.None, $"偏 {far:F0}px");
        Check("极简模式不认边中点",
              SelectionHandles.HitTest(top.X, top.Y, b, dpi, includeEdgeHandles: false) == SelHandle.None, "");

        // ---- 四角拖动：锚点不动，被拖的角跟手 ----
        var br = SelectionHandles.Position(SelHandle.BottomRight, b, dpi);
        // 目标点取在"锚点 → 被拖的角"的延长线上：四角现在是**等比**缩放，
        // 只有沿对角线拖，被拖的角才会精确落在目标点上。
        // （不在对角线上时等比缩放也能用，只是角落不到指针那儿——这是等比的
        //   固有性质，不是 bug。）
        var target = new Vector2(b.MinX * 2f - b.MaxX, b.MinY * 2f - b.MaxY);
        var m = SelectionHandles.DragMatrix(SelHandle.TopLeft, b, tl, target, dpi, false, false);
        var anchorAfter = Vector2.Transform(br, m);
        Check("锚点（对角）不动",
              Math.Abs(anchorAfter.X - br.X) < 0.05f && Math.Abs(anchorAfter.Y - br.Y) < 0.05f,
              $"({anchorAfter.X:F1},{anchorAfter.Y:F1})");
        var cornerAfter = Vector2.Transform(tl, m);
        Check("被拖的角跟到目标点",
              Math.Abs(cornerAfter.X - target.X) < 0.05f && Math.Abs(cornerAfter.Y - target.Y) < 0.05f,
              $"({cornerAfter.X:F1},{cornerAfter.Y:F1}) 目标 ({target.X:F1},{target.Y:F1})");
        Check("四角是等比", MathF.Abs(m.M11 - m.M22) < 1e-4f, $"sx={m.M11:F3} sy={m.M22:F3}");

        // ---- 边中点：只动一个轴（这就是"左右拉伸 / 上下拉伸"）----
        var right = SelectionHandles.Position(SelHandle.Right, b, dpi);
        var mEdge = SelectionHandles.DragMatrix(SelHandle.Right, b, right,
                                                new Vector2(right.X + 200, right.Y + 999), dpi, false, false);
        Check("右边中点只拉伸 X", MathF.Abs(mEdge.M22 - 1f) < 1e-4f && mEdge.M11 > 1.49f,
              $"sx={mEdge.M11:F2} sy={mEdge.M22:F2}（Y 的拖动被忽略）");

        // ---- 拖过头：夹住，不翻转 ----
        var wayPast = new Vector2(br.X + 600, br.Y + 600);
        var mOver = SelectionHandles.DragMatrix(SelHandle.TopLeft, b, tl, wayPast, dpi, false, false);
        Check("拖过头不翻转（夹住）",
              mOver.M11 > 0f && mOver.M22 > 0f && MathF.Abs(mOver.M11 - SelectionHandles.MinScale) < 1e-3f,
              $"sx={mOver.M11:F3} sy={mOver.M22:F3}，下限 {SelectionHandles.MinScale}");

        // ---- Shift 等比 ----
        var mUni = SelectionHandles.DragMatrix(SelHandle.TopLeft, b, tl,
                                               new Vector2(b.MinX - 300, b.MinY - 80), dpi, true, false);
        Check("Shift 等比", MathF.Abs(mUni.M11 - mUni.M22) < 1e-4f, $"sx={mUni.M11:F3} sy={mUni.M22:F3}");

        // ---- 旋转：绕选区中心转，长度不变 ----
        var center = new Vector2(cx, (b.MinY + b.MaxY) * 0.5f);
        var mRot = SelectionHandles.DragMatrix(SelHandle.Rotate, b, top,
                                               new Vector2(center.X + 100, center.Y), dpi, false, false);
        var rotated = Vector2.Transform(tl, mRot);
        float r0 = Vector2.Distance(tl, center);
        float r1 = Vector2.Distance(rotated, center);
        Check("旋转保持半径", Math.Abs(r0 - r1) < 0.05f, $"{r0:F1} -> {r1:F1}");

        // ---- 旋转吸附 ----
        var mSnap = SelectionHandles.DragMatrix(SelHandle.Rotate, b, top,
                                                new Vector2(center.X + 100, center.Y + 7), dpi, false, true);
        var v0 = Vector2.Normalize(top - center);
        var v1 = Vector2.Normalize(Vector2.Transform(top, mSnap) - center);
        float deg = MathF.Acos(Math.Clamp(Vector2.Dot(v0, v1), -1f, 1f)) * 180f / MathF.PI;
        Check("Shift 旋转吸附到 15°", Math.Abs(deg % 15f) < 0.5f || Math.Abs(deg % 15f - 15f) < 0.5f,
              $"转了 {deg:F1}°");

        // ---- 镜像：只能从矩阵入口来 ----
        var mMir = SelectionHandles.MirrorMatrix(b, horizontal: true);
        var mirroredLeft = Vector2.Transform(tl, mMir);
        Check("左右镜像对称", Math.Abs(mirroredLeft.X - b.MaxX) < 0.01f
                           && Math.Abs(mirroredLeft.Y - b.MinY) < 0.01f,
              $"左上角 -> ({mirroredLeft.X:F1},{mirroredLeft.Y:F1})");
        Check("镜像矩阵行列式为负", mMir.M11 * mMir.M22 - mMir.M12 * mMir.M21 < 0f, "");

        Console.WriteLine();
        Console.WriteLine(fail == 0 ? "  PASS: 手柄位置、命中与变换矩阵都正确" : $"  FAIL: {fail} 项不对");
        _quit = true;
    }

    /// <summary>
    /// 键位自检：默认表、解析、冲突检测、落盘读回、真机注册、批注内真按一次键。
    ///
    /// 为什么值得单独写一条：键位是"用户的设置"，出错的方式特别隐蔽——
    /// 键被别的程序占了（按下去没反应）、改键撞了车（按下去触发另一件事）、
    /// 配置文件写坏了（下次启动直接崩）。这三类都在这里验。
    /// </summary>
    private void KeyTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 键位自检（表 / 冲突 / 落盘 / 真机注册）===");
        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"    {name,-30}{(ok ? "PASS" : "FAIL")}  {detail}");
        }

        // ---- 1. 默认表 ----
        var map = KeyMap.Default();
        var problems = map.Validate();
        Check("默认表内部没有矛盾", problems.Count == 0,
              problems.Count == 0 ? "无" : string.Join("；", problems));

        int nGlobal = map.For(KeyScope.Global).Count();
        int nAnno = map.For(KeyScope.Annotation).Count();
        // 条数**不再写死**：加一个工具就会多一条，写死只会让这条自检天天报假警
        // （"22 项通过、1 项不对"里那一项就是它）。真正的不变量是下面两条：
        // 全局一律带修饰键、编辑类动作不在全局。这里只保证两档都非空、
        // 且每一条都真的绑上了键。
        Check("作用域划分：两档都非空且每条都有键",
              nGlobal > 0 && nAnno > 0 && map.Bindings.All(b => b.Chord.IsValid),
              $"全局 {nGlobal} 条，批注内 {nAnno} 条");
        Check("全局键一律带修饰键（不会抢走正常打字）",
              map.For(KeyScope.Global).All(b => b.Chord.HasModifier), "");
        Check("编辑类动作只在批注内（没有全局 Ctrl+Z 这种）",
              !map.For(KeyScope.Global).Any(b => b.Action == KeyAction.Redo
                    || b.Action == KeyAction.SelectAll || b.Action == KeyAction.DeleteSelected
                    || b.Action == KeyAction.NudgeLeft), "");

        // **全局只留最最常用的那几个**（用户 2026-09-19："除了最最最常用的功能需要全局热键以外，
        // 其他的通通换成应用内快捷键就行了"）。判据取自 `KeyBindings.GlobalAllowed`
        // ——那份名单是**产品的规则**，不是自检自己写的一份：两边各写一份早晚会分叉
        // （这条仓库里踩过三次）。这里只负责"表里不许出现名单之外的动作"。
        var allowedGlobal = new HashSet<KeyAction>(KeyMap.GlobalAllowedActions);
        var stray = map.For(KeyScope.Global).Select(b => b.Action).Where(a => !allowedGlobal.Contains(a)).ToList();
        Check("全局里没有那 5 个之外的动作",
              stray.Count == 0,
              stray.Count == 0
                  ? $"全局 {nGlobal} 条，全是：{string.Join(" / ", allowedGlobal.Select(KeyMap.Describe))}"
                  : "多出来：" + string.Join("、", stray.Select(KeyMap.Describe)));

        // 图形**一个键都没有**（用户 2026-09-19："图形不需要加快捷键，通通取消掉"）。
        // 查法是对着"退役的那五个组合"查，不是查动作名——动作枚举里已经没有图形那几个了，
        // 查名字等于什么都没查。
        foreach (var (name, vk) in new[] { ("O", 'O'), ("T", 'T'), ("G", 'G'), ("F", 'F'), ("N", 'N') })
        {
            var c = new KeyChord(KeyChord.ModCtrl | KeyChord.ModAlt, vk);
            Check($"退役的图形键 Ctrl+Alt+{name} 不在任何作用域里",
                  map.Bindings.All(b => !b.Chord.Equals(c)), "");
        }

        // ---- 2. 按键解析 ----
        bool ok1 = KeyChord.TryParse("ctrl+alt+p", out var c1, out _);
        Check("解析 Ctrl+Alt+P（大小写不敏感）", ok1 && c1.ToString() == "Ctrl+Alt+P", c1.ToString());
        bool ok2 = KeyChord.TryParse("Delete", out var c2, out _);
        Check("解析 Delete", ok2 && c2.Vk == 0x2E, $"VK={c2.Vk:X2}");
        bool ok3 = KeyChord.TryParse("Shift+Left", out var c3, out _);
        Check("解析 Shift+Left", ok3 && c3.Vk == 0x25 && (c3.Modifiers & KeyChord.ModShift) != 0,
              c3.ToString());
        bool ok4 = KeyChord.TryParse("Ctrl+月亮", out _, out string err4);
        Check("认不出的键名要报错（不是静默忽略）", !ok4 && err4 != null, err4);
        bool ok5 = KeyChord.TryParse("Ctrl+", out _, out string err5);
        Check("只有修饰键要报错", !ok5 && err5 != null, err5);

        // ---- 3. 冲突检测 ----
        // 样本用**穿透模式开关**：它是全局里必留的那几条之一（2026-09-29 全局只剩
        // 穿透/键盘模式/退出，笔和橡皮都降到批注内了——拿 ToolPen 当样本会以
        // "这个作用域里没有这个动作"直接失败，冲突检测那一条就成了假通过）。
        KeyChord.TryParse("Ctrl+Alt+X", out var takenChord, out _);     // 被"退出"占着
        bool taken = map.TrySet(KeyScope.Global, KeyAction.TogglePassThrough, takenChord, out string errTaken);
        Check("撞了别人的键要拒绝并说清是谁", !taken && errTaken != null
              && errTaken.Contains("退出"), errTaken);

        KeyChord.TryParse("F5", out var noMod, out _);
        bool bare = map.TrySet(KeyScope.Global, KeyAction.TogglePassThrough, noMod, out string errBare);
        Check("全局热键没有修饰键要拒绝", !bare && errBare != null, errBare);

        KeyChord.TryParse("Ctrl+Alt+F5", out var free, out _);
        bool moved = map.TrySet(KeyScope.Global, KeyAction.TogglePassThrough, free, out string errMove);
        Check("没冲突就能改，并标记成脏",
              moved && map.Dirty && map.Find(KeyScope.Global, KeyAction.TogglePassThrough).Chord.Equals(free),
              $"穿透 → {map.Find(KeyScope.Global, KeyAction.TogglePassThrough).Chord}");

        map.ResetToDefault(KeyScope.Global, KeyAction.TogglePassThrough);
        Check("能恢复默认键", map.Find(KeyScope.Global, KeyAction.TogglePassThrough).Chord.ToString() == "Ctrl+Alt+P",
              map.Find(KeyScope.Global, KeyAction.TogglePassThrough).Chord.ToString());

        // ---- 4. 落盘 / 读回 / 坏文件 ----
        string cfg = Path.Combine(Path.GetTempPath(), "inkteach-keytest.json");
        InkSettings.PathOverride = cfg;
        try
        {
            KeyChord.TryParse("Ctrl+Alt+F12", out var f12, out _);
            map.TrySet(KeyScope.Global, KeyAction.Quit, f12, out _);
            InkSettings.Save(map);
            Check("写盘后文件真的存在", File.Exists(cfg), cfg);

            var reloaded = KeyMap.Default();
            var warns = InkSettings.Load(reloaded);
            Check("读回无警告，且改动生效",
                  warns.Count == 0 && reloaded.Find(KeyScope.Global, KeyAction.Quit).Chord.Equals(f12),
                  warns.Count == 0 ? $"退出键 → {reloaded.Find(KeyScope.Global, KeyAction.Quit).Chord}"
                                   : string.Join("；", warns));
            Check("没改过的项仍是默认值（只写差异）",
                  reloaded.Find(KeyScope.Global, KeyAction.TogglePassThrough).Chord.ToString() == "Ctrl+Alt+P", "");
            Check("只写差异：文件里应当只有 1 条", File.ReadAllText(cfg).Split('\n')
                  .Count(l => l.Contains("\"Global.")) == 1, "");

            File.WriteAllText(cfg, "{ \"keys\": { \"Global.Quit\": \"Ctrl+Alt+\" } }");
            var broken = KeyMap.Default();
            var warns2 = InkSettings.Load(broken);
            Check("键名写坏了：报警告 + 用默认值 + 不抛异常",
                  warns2.Count > 0 && broken.Find(KeyScope.Global, KeyAction.Quit).Chord.ToString() == "Ctrl+Alt+X",
                  warns2.Count > 0 ? warns2[0] : "没有警告（不该）");

            File.WriteAllText(cfg, "这不是 JSON，只是一段乱码");
            var garbage = KeyMap.Default();
            var warns3 = InkSettings.Load(garbage);
            Check("整个文件是垃圾：报警告 + 仍能启动",
                  warns3.Count > 0 && garbage.Validate().Count == 0,
                  warns3.Count > 0 ? warns3[0] : "没有警告（不该）");
        }
        finally
        {
            try { File.Delete(cfg); } catch { }
            InkSettings.PathOverride = null;
        }

        // ---- 5. 真机注册结果 ----
        Check("全局热键注册数量与表一致", HotkeysRegistered == nGlobal,
              $"{HotkeysRegistered}/{nGlobal} 注册成功"
              + (Keys.GlobalFailures.Count > 0 ? "；失败：" + string.Join("；", Keys.GlobalFailures) : ""));

        // ---- 6. 快捷键总表：文档不许落后于代码 ----
        //
        // 用户的要求是"同一个功能的不同快捷键都要记录全，以后每次修改都记录"。
        // 光靠自觉迟早会漏，所以这里把**代码里的每一条绑定**拿去文档里查：
        // 要求**键和动作名出现在同一行**——只要求"这两个字符串各自出现过"太弱了
        // （把键换了但忘了改文档，照样能通过）。
        // 拿**默认表**去核对，不是拿这一轮被测试改过的 map：文档记的是程序**出厂默认键**，
        // 用户自己改的键活在 settings.json 里（上面刚验过落盘读回）。用 map 去比，
        // 会把"测试里临时改成 Ctrl+Alt+F12"当成文档缺一条——这条假失败刚踩到。
        var docCheck = CheckHotkeyDoc(KeyMap.Default());
        Check("快捷键总表.md 覆盖了每一条绑定（键 + 动作名同一行）", docCheck.ok, docCheck.detail);

        // ---- 6. 动作路由：id ↔ 动作 ↔ 键 一一对应 ----
        bool routingOk = true;
        string routingDetail = "";
        int i2 = 0;
        foreach (var b in Keys.For(KeyScope.Global))
        {
            i2++;
            if (ActionForHotkeyId(i2) != b.Action)
            {
                routingOk = false;
                routingDetail = $"第 {i2} 个：期望 {b.Action}，实际 {ActionForHotkeyId(i2)}";
                break;
            }
        }
        Check("WM_HOTKEY 的 id 能正确反查到动作", routingOk,
              routingOk ? $"{i2} 条全部对上" : routingDetail);

        // ---- 7. 批注内真按一次键（走窗口消息 → 键盘模式 → 动作）----
        Doc.Clear();
        Doc.ClearHistory();
        for (int i = 0; i < 3; i++)
        {
            var s = new Stroke { Tool = Tool.Pen, Color = new Color4(0f, 0f, 0f, 1f), Width = 6f * DpiScale };
            for (int k = 0; k <= 20; k++) s.AddPoint(600 + k * 20, 400 + i * 120, 1f, NowMs);
            Doc.AddStroke(s);
        }
        bool wasKeyboardMode = KeyboardMode;
        if (!wasKeyboardMode) SetKeyboardMode(true);
        SelectAll();
        int before = Doc.Strokes.Count;

        // Delete 在默认表里是"删除选中"（批注内、无修饰键，所以能直接合成）
        Native.PostMessage(_windows[0].Hwnd, (uint)Native.WM_KEYDOWN, new IntPtr(0x2E), IntPtr.Zero);
        SettleFrames(200);
        int afterDelete = Doc.Strokes.Count;
        Check("批注内按 Delete 真的删掉了选中",
              before == 3 && afterDelete == 0, $"{before} 笔 → {afterDelete} 笔");

        Doc.Undo();
        SettleFrames(150);
        Check("这一步能撤销回来", Doc.Strokes.Count == 3, $"撤销后 {Doc.Strokes.Count} 笔");
        if (!wasKeyboardMode) SetKeyboardMode(false);

        Console.WriteLine();
        Console.WriteLine("  当前键位表：");
        Console.Write(Keys.ToText());
        if (Keys.GlobalFailures.Count > 0)
            foreach (var f in Keys.GlobalFailures) Console.WriteLine("    ！" + f);

        Console.WriteLine();
        Console.WriteLine(fail == 0
            ? "  PASS: 键位表、冲突检测、落盘读回、真机注册与批注内按键都正确"
            : $"  FAIL: {fail} 项不对（{pass} 项通过）");

        Doc.Clear();
        Doc.ClearHistory();
        _quit = true;
    }

    /// <summary>
    /// 核对"快捷键总表.md"有没有落后于代码。
    ///
    /// 规则（用户定的）：同一个功能的所有键都要列全，每次改键都要记录。
    /// 这里只机器可判的那一半：**代码里每一条绑定，都要能在文档里找到
    /// "键 + 动作名"同一行**。文档不在（比如在别的目录跑）就跳过，
    /// 只提示不判失败——那是环境问题，不是键位表的问题。
    /// </summary>
    private (bool ok, string detail) CheckHotkeyDoc(KeyMap map)
    {
        const string docPath = "快捷键总表.md";
        if (!File.Exists(docPath))
            return (true, $"{docPath} 不在当前目录，这一项跳过");

        var lines = File.ReadAllText(docPath).Split('\n');
        var missing = new List<string>();
        foreach (var b in map.Bindings)
        {
            string chord = b.Chord.ToString();
            string name = KeyMap.Describe(b.Action);
            bool found = lines.Any(l => l.Contains(chord) && l.Contains(name));
            if (!found) missing.Add($"{b.Scope} {chord} {name}");
        }

        return (missing.Count == 0,
                missing.Count == 0
                    ? $"共 {map.Bindings.Count} 条，全部查得到"
                    : "缺：" + string.Join("；", missing.Take(6))
                      + (missing.Count > 6 ? $" 等 {missing.Count} 条" : ""));
    }

    /// <summary>
    /// 落点反馈摆样：把指针停在屏幕中央、按指定工具把落点反馈挂出来，等外部截图。
    /// 目的和 --rotateshow 一样——光标这类东西只有看在图上才算验过。
    /// </summary>
    private void CursorShowcase(string tool, float widthLogical)
    {
        Doc.Clear();
        Doc.ClearHistory();
        Tool = tool switch
        {
            "highlighter" or "hl" => Tool.Highlighter,
            "laser" => Tool.Laser,
            "eraser" => Tool.Eraser,
            "pixeleraser" or "blockeraser" => Tool.PixelEraser,
            "capture" or "screenshot" => Tool.Capture,      // 截图：看自绘的取景框落点
            _ => Tool.Pen,
        };
        if (widthLogical > 0f)
        {
            if (Tool == Tool.Highlighter) HighlighterWidthLogical = widthLogical;
            else if (Tool == Tool.Laser) LaserWidthLogical = widthLogical;
            else if (Tool == Tool.Eraser) EraserRadiusLogical = widthLogical;
            else if (Tool == Tool.PixelEraser) PixelEraserWidthLogical = widthLogical;
            else PenWidthLogical = widthLogical;
        }

        PassThrough = false;
        PointerInside = true;
        _drawing = false;
        LastPointerType = showcasePenDevice ? Native.PT_PEN : Native.PT_MOUSE;
        PointerX = _virtualX + _virtualW * 0.5f;
        PointerY = _virtualY + _virtualH * 0.5f;
        ShowHud = false;
        _dirty = true;
        SettleFrames(600);
        string size = Tool == Tool.PixelEraser
            ? $"矩形 {PixelEraserWidthLogical:F0}×{PixelEraserHeightLogical:F0} 逻辑像素"
              + $"（高:宽 = {GoldenRatio:F3}）"
            : $"宽 {CurrentToolWidthLogical} 逻辑像素（外圈 {CursorOuterRadius:F0}px）";
        Console.WriteLine($"落点反馈已摆好：{Tool} {size}"
                        + $"（{DrawnCursor}，脏区 {DrawnCursorRadius:F0}px）");
        Console.WriteLine("cursor showcase ready");
    }

    private bool showcasePenDevice = false;

    /// <summary>
    /// 像素橡皮摆样（--pixeleraseshow）：画几条"板书"，用竖着的黄金比矩形抹一下，
    /// **自己抓屏**存两张图——擦之前（带落点）和擦之后（落点挪开）。
    ///
    /// 为什么不靠外部截图工具：自检已经能抓屏了（ScreenProbe），摆样自己存图少一步人工。
    /// 落点在第二张里必须挪开——矩形正压在切口上，就看不出"一笔被切成了两段"。
    /// </summary>
    private void PixelEraserShowcase()
    {
        Doc.Clear();
        Doc.ClearHistory();
        float cx = _virtualX + _virtualW * 0.5f;
        float cy = _virtualY + _virtualH * 0.5f;
        float dpi = DpiScale;

        // 三条横墨（笔迹，会被切成两段）、一条荧光笔（同样会被切）、
        // 一个矩形（图形，轮廓被碰到时整条删）。三种对象一屏看全。
        // 墨水的位置要落在橡皮的竖边范围（±半高）里——落在外面就看不出"擦掉了一整条"。
        foreach (float dy in new[] { -120f, -60f, 0f })
        {
            var s = new Stroke
            {
                Tool = Tool.Pen, Color = new Color4(0.10f, 0.11f, 0.13f, 1f), Width = 8f * dpi,
            };
            for (int i = 0; i <= 120; i++)
                s.AddPoint(cx - 520 + i * 9f, cy + dy + MathF.Sin(i * 0.32f) * 6f, 0.9f, i);
            Doc.AddStroke(s);
        }
        var hl = new Stroke
        {
            Tool = Tool.Highlighter, Color = new Color4(1f, 0.84f, 0.16f, 1f), Width = 26f * dpi,
        };
        for (int i = 0; i <= 60; i++) hl.AddPoint(cx - 440 + i * 15f, cy + 110, 1f, i);
        Doc.AddStroke(hl);

        var box = new Stroke
        {
            Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
            Color = new Color4(0.9f, 0.2f, 0.2f, 1f), Width = 5f * dpi,
        };
        box.AddPoint(cx + 40, cy - 250, 1f, 0);       // 左边压在橡皮里（橡皮半宽 = 93 物理像素）
        box.AddPoint(cx + 280, cy + 250, 1f, 0);
        Doc.AddStroke(box);

        // **多段图形**（长方体 12 条棱、圆柱 5 笔）——2026-09-20 修的那两类：
        // 擦一刀之后外形逐笔不变：被挡的棱 / 被挡的半圈熔完**还是细虚线**，
        // 段与段之间也**不会连出假线**。都摆在橡皮的竖直带里，好看出"确实切了一刀"。
        var cub = new Stroke
        {
            Tool = Tool.Cuboid, Kind = StrokeKind.Cuboid,
            Color = new Color4(0.15f, 0.45f, 0.9f, 1f), Width = 5f * dpi,
        };
        cub.SetCuboidFront(cx - 40, cy + 40, cx + 180, cy + 240);
        cub.SetCuboidDepth(cx + 20, cy - 20);         // 深度 = |40 − (−20)| = 60
        Doc.AddStroke(cub);

        var cyl = new Stroke
        {
            Tool = Tool.Cylinder, Kind = StrokeKind.Cylinder,
            Color = new Color4(0.15f, 0.45f, 0.9f, 1f), Width = 5f * dpi,
        };
        cyl.SetSolidBox(cx - 320, cy - 300, cx - 80, cy + 60);   // 右边那条母线压在橡皮里
        Doc.AddStroke(cyl);

        Tool = Tool.PixelEraser;
        PassThrough = false;
        ShowHud = false;
        PointerInside = true;
        LastPointerType = Native.PT_MOUSE;
        PointerX = cx; PointerY = cy;
        Doc.InvalidateAll();
        SettleFrames(600);

        int w = (int)(PixelEraserWidthLogical * dpi * 4.6f);
        int h = (int)(PixelEraserHeightLogical * dpi * 3.6f);
        int x0 = (int)cx - w / 2, y0 = (int)cy - h / 2;

        string shot1 = Path.Combine("reports", "像素橡皮-1-落点与擦之前.bmp");
        ScreenProbe.SaveBmp(shot1, x0, y0, w, h);
        Console.WriteLine($"已存 {Path.GetFullPath(shot1)}");
        Console.WriteLine($"  落点：{(int)PixelEraserWidthLogical}×{(int)PixelEraserHeightLogical} 逻辑像素"
                        + $"（{PixelEraserWidthLogical * dpi:F0}×{PixelEraserHeightLogical * dpi:F0} 物理像素）");

        int before = Doc.Strokes.Count;
        Doc.BeginEraseRect();
        Doc.EraseRectAt(cx, cy, PixelEraserHalfWidthPx, PixelEraserHalfHeightPx);
        Doc.EndErase();

        // 落点挪开再拍：矩形正压在切口上就看不出切成了什么样。
        PointerX = _virtualX + 120; PointerY = _virtualY + _virtualH - 120;
        SettleFrames(600);

        string shot2 = Path.Combine("reports", "像素橡皮-2-擦之后.bmp");
        ScreenProbe.SaveBmp(shot2, x0, y0, w, h);
        Console.WriteLine($"已存 {Path.GetFullPath(shot2)}");
        Console.WriteLine($"  擦之前 {before} 条 → 擦之后 {Doc.Strokes.Count} 条"
                        + "（三条横墨 + 荧光笔各切成两截；矩形熔成笔迹后再切；"
                        + "长方体、圆柱熔成**一条棱一段**——虚线棱 / 虚线半圈还是虚线，"
                        + "段与段之间没有假线）");
        for (int i = 0; i < Doc.Strokes.Count; i++)
        {
            var s = Doc.Strokes[i];
            Console.WriteLine($"    #{i} {s.Kind,-9} 点 {s.Points.Count,4} 擦除区间 {s.Erased.Count} 段"
                            + $" 剩余 {s.RemainingRuns().Count} 段"
                            + $"  x {s.Bounds.MinX:F0}..{s.Bounds.MaxX:F0}"
                            + $"  y {s.Bounds.MinY:F0}..{s.Bounds.MaxY:F0}");
        }
        Console.WriteLine("pixel eraser showcase done");
        _quit = true;
    }

    /// <summary>
    /// 旋转标签摆样：选中一个对象、把框转到指定角度、把度数标签挂出来不动，
    /// 由外部截图人工核对（位置、可读性、吸附变色）。这个模式不会自己退出。
    /// </summary>
    private void RotateShowcase(float deg)
    {
        Doc.Clear();
        Doc.ClearHistory();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }

        float sx = _virtualX + _virtualW * 0.5f, sy = _virtualY + _virtualH * 0.55f;
        var stroke = new Stroke
        {
            Tool = Tool.Pen, Kind = StrokeKind.Freehand,
            Color = PenColor, Width = 8f * DpiScale,
        };
        for (int i = 0; i <= 48; i++)
        {
            float a = i / 48f * MathF.PI * 2f;
            stroke.AddPoint(sx + MathF.Cos(a) * 170f * DpiScale,
                            sy + MathF.Sin(a) * 120f * DpiScale, 0.9f, i * 8);
        }
        Doc.AddStroke(stroke);
        Doc.Selected.Clear();
        Doc.Selected.Add(stroke);
        Tool = Tool.Marquee;

        // 真的转过去：框和标签都跟着转，截图才是"正在转"的样子
        var m = Matrix3x2.CreateRotation(deg * MathF.PI / 180f, new Vector2(sx, sy));
        Doc.SetTransformLive(stroke, m);
        Doc.SetTransformLive(stroke, m);
        _dirty = true;
        SettleFrames(300);

        SelRotating = true;
        SelRotationDegrees = deg;
        SelRotationSnapped = Math.Abs(deg % 90f) < 0.5f;
        _dirty = true;
        SettleFrames(700);
        Console.WriteLine($"旋转标签已摆好：{SelectionHandles.FormatDegrees(deg)}"
                        + (SelRotationSnapped ? "（吸附态）" : "（自由态）"));
        Console.WriteLine("rotate showcase ready");
    }

    /// <summary>
    /// 旋转度数 + 吸附自检。
    ///
    /// 分两段：
    ///   A. **数学层**：读数、三种吸附模式（软吸附 90° / Shift 硬网格 15° / Alt 自由）、
    ///      边界值，以及"读数与矩阵自洽"（用独立的 atan2 再量一遍矩阵转过的角度）。
    ///   B. **真机层**：合成鼠标按在旋转手柄上拖，然后**数屏幕像素**确认度数标签
    ///      真的画出来了、"吸住"时真的变色、松手后真的消失。
    ///
    /// 为什么非要 B：标签是画在浮动层上的，进没进每帧脏区、双缓冲会不会把它留在
    /// 屏幕上，只有看像素才知道。选中框那一套 UI 就踩过"漏算脏区 → 残影"的坑。
    /// </summary>
    private void RotateTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 旋转度数 / 吸附自检 ===");
        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"    {name,-28}{(ok ? "PASS" : "FAIL")}  {detail}");
        }

        // ================= A. 数学层 =================
        var b = new RectF { MinX = 600, MinY = 500, MaxX = 1000, MaxY = 800 };
        var center = new Vector2((b.MinX + b.MaxX) * 0.5f, (b.MinY + b.MaxY) * 0.5f);
        const float radius = 260f;
        // 起点固定在正上方（屏幕上的 -90°），目标点 = 起点绕中心转 deg 度
        Vector2 At(float deg)
        {
            float rad = (-90f + deg) * MathF.PI / 180f;
            return new Vector2(center.X + radius * MathF.Cos(rad), center.Y + radius * MathF.Sin(rad));
        }
        var from = At(0f);

        (float deg, bool snapped) Probe(float deg, bool shift = false, bool alt = false)
            => (SelectionHandles.RotationDeltaDegrees(center, from, At(deg), shift, alt, out bool s), s);

        void Case(string name, float target, float want, bool wantSnap,
                  bool shift = false, bool alt = false)
        {
            var (got, snapped) = Probe(target, shift, alt);
            bool ok = Math.Abs(got - want) < 0.05f && snapped == wantSnap;
            Check(name, ok, $"转 {target:F1}° → {got:F1}°{(snapped ? "（吸附）" : "（自由）")}"
                          + $"，期望 {want:F1}°{(wantSnap ? "（吸附）" : "（自由）")}");
        }

        // 注意 `target` 是**指针在屏幕上顺时针转的角度**（见 At），`want` 是标签上的数。
        // 用户 2026-09-15 定：**逆时针为正、顺时针为负**——所以顺时针 88° 读数是 -90°。
        Case("正对网格：吸附", 0f, 0f, true);
        Case("容差内：吸到 0°", 2f, 0f, true);
        Case("容差外：保持自由（顺时针 → 负）", 5f, -5f, false);
        Case("普通角度：保持自由", 43f, -43f, false);
        Case("容差内：吸到 90°", 88f, -90f, true);
        Case("容差内：吸到 -90°", -89f, 90f, true);
        Case("容差外：保持自由（90 附近）", 95f, -95f, false);
        Case("半个整角：自由", 45f, -45f, false);
        Case("整角 180°：吸附", 180f, -180f, true);
        // 半圈这个点天生有歧义：屏幕 -180° 的最短增量既可以是 +180 也可以是 -180，
        // 实现取"归一化后再取负" → -180。真正的转圈由拖动中的**逐帧累积**决定（见 C 段）。
        Case("半圈的临界点：取 -180°", -180f, -180f, true);
        Case("Shift：硬网格 15°", 20f, -15f, true, shift: true);
        Case("Shift：吸到 0°", 7f, 0f, true, shift: true);
        Case("Alt：完全自由", 2f, -2f, false, alt: true);
        Case("Shift+Alt：Shift 优先", 20f, -15f, true, shift: true, alt: true);

        // **不设上限**（用户 2026-09-15 定）：吸附规则原样，但角度不绕回。
        // 转两圈多一点点 = 738°，就该原样写 738°，而不是 18°。
        Check("吸附：738° 不绕回", Math.Abs(SelectionHandles.SnapRotationDegrees(738f, false, false, out _) - 738f) < 0.01f,
              $"738° → {SelectionHandles.SnapRotationDegrees(738f, false, false, out _):F0}°");
        Check("吸附：722° 吸到 720°（整圈的整数倍照样认）",
              Math.Abs(SelectionHandles.SnapRotationDegrees(722f, false, false, out bool s722) - 720f) < 0.01f && s722,
              $"722° → {SelectionHandles.SnapRotationDegrees(722f, false, false, out _):F0}°");
        Check("吸附：-725° 保持自由（离 -720° 差 5°）",
              Math.Abs(SelectionHandles.SnapRotationDegrees(-725f, false, false, out bool s725) + 725f) < 0.01f && !s725,
              $"-725° → {SelectionHandles.SnapRotationDegrees(-725f, false, false, out _):F0}°");

        // 读数与矩阵必须自洽：矩阵转过的角度（独立用 atan2 量）要等于读数
        foreach (float target in new[] { 0f, 43f, 88f, -137f, 179f })
        {
            var (deg, _) = Probe(target);
            var m = SelectionHandles.DragMatrix(SelHandle.Rotate, b, from, At(target), 1f, false, false);
            var moved = Vector2.Transform(from, m);
            float measured = MathF.Atan2(moved.Y - center.Y, moved.X - center.X)
                           * 180f / MathF.PI + 90f;         // 起点在 -90°，所以加回来
            // 量出来的是**屏幕坐标**（顺时针为正）；读数那套是逆时针为正，取负号对齐
            measured = -SelectionHandles.NormalizeDegrees(measured);
            var pivotAfter = Vector2.Transform(center, m);
            Check($"拖动 {target,5:F0}°：读数与矩阵一致",
                  Math.Abs(measured - deg) < 0.2f
                  && Math.Abs(pivotAfter.X - center.X) < 0.05f
                  && Math.Abs(pivotAfter.Y - center.Y) < 0.05f,
                  $"读数 {deg:F1}°，矩阵量出 {measured:F1}°，轴心偏移 "
                  + $"{Vector2.Distance(pivotAfter, center):F3}px");
        }

        Check("标签文案不留 -0°", SelectionHandles.FormatDegrees(-0.4f) == "0°",
              $"{-0.4f:F1}° → {SelectionHandles.FormatDegrees(-0.4f)}");
        Check("标签文案取整", SelectionHandles.FormatDegrees(89.6f) == "90°",
              $"89.6° → {SelectionHandles.FormatDegrees(89.6f)}");
        Check("标签文案带符号", SelectionHandles.FormatDegrees(-45f) == "-45°",
              $"-45° → {SelectionHandles.FormatDegrees(-45f)}");
        Check("标签文案不绕回（转两圈就写 740°）", SelectionHandles.FormatDegrees(740f) == "740°",
              $"740° → {SelectionHandles.FormatDegrees(740f)}");
        Check("标签文案不绕回（倒着转就写 -1234°）", SelectionHandles.FormatDegrees(-1234f) == "-1234°",
              $"-1234° → {SelectionHandles.FormatDegrees(-1234f)}");

        // ================= B. 真机层 =================
        Doc.Clear();
        Doc.ClearHistory();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }

        // **白板打底**：这一节靠"数屏幕上的强调色像素"判断标签画没画、在哪儿，
        // 而批注模式下面板是全透明的——桌面上的东西会被算进来。2026-09-17 实测：
        // 桌面换了一批窗口之后，这三条一下全红（"标签位置是干净的"量到 3421 像素），
        // 而代码一个字没改。铺一层不透明白板，量到的就全是我们的墨。
        BoardOn = true;

        float sx = _virtualX + _virtualW * 0.5f, sy = _virtualY + _virtualH * 0.5f;
        var stroke = new Stroke
        {
            Tool = Tool.Pen, Kind = StrokeKind.Freehand,
            Color = new Color4(1f, 0f, 1f, 1f), Width = 12f * DpiScale,
        };
        // 画个圈：选区足够大，手柄到轴心的半径才够长，角度才好量准
        for (int i = 0; i <= 48; i++)
        {
            float a = i / 48f * MathF.PI * 2f;
            stroke.AddPoint(sx + MathF.Cos(a) * 180f * DpiScale,
                            sy + MathF.Sin(a) * 180f * DpiScale, 0.9f, i * 8);
        }
        Doc.AddStroke(stroke);
        Doc.Selected.Clear();
        Doc.Selected.Add(stroke);
        Tool = Tool.Marquee;
        SettleFrames(400);

        var frame = SelectionHandles.FrameOf(Doc.Selected);
        float dpi = DpiScale;
        var grip = SelectionHandles.CanvasPosition(SelHandle.Rotate, frame, dpi);
        var pivot = new Vector2((frame.CanvasAabb.MinX + frame.CanvasAabb.MaxX) * 0.5f,
                                (frame.CanvasAabb.MinY + frame.CanvasAabb.MaxY) * 0.5f);
        float arm = Vector2.Distance(grip, pivot);
        Vector2 GripAt(float deg)
        {
            float rad = (-90f + deg) * MathF.PI / 180f;
            return new Vector2(pivot.X + arm * MathF.Cos(rad), pivot.Y + arm * MathF.Sin(rad));
        }

        // 探针窗：**当前**旋转手柄上方那一块（标签就画在那儿），刻意不覆盖选中框本身。
        // 必须每一步都重算手柄位置——手柄是跟着框转的，拖动之后标签早就不在原来的地方了。
        int probeW = (int)(150f * dpi), probeH = (int)(120f * dpi);
        int AccentCount()
        {
            // 用**实时框**：拖动中模型到松手才动（方案 B），拿模型里的框去算手柄位置，
            // 探针窗会停在按下那一刻的老地方，而标签早跟着内容转走了。
            var f = LiveSelectionFrame;
            var h = SelectionHandles.CanvasPosition(SelHandle.Rotate, f, dpi);
            return ScreenProbe.CountNear((int)(h.X - probeW * 0.5f), (int)(h.Y - probeH),
                                         probeW, probeH, 0, 120, 212, 40);
        }

        int beforeDraw = AccentCount();
        Check("没拖之前，标签位置是干净的", beforeDraw < 800, $"{beforeDraw} 像素");

        // 按下旋转手柄，拖到 92°（容差内 → 应该吸到 90°）
        SendMouse((int)grip.X, (int)grip.Y, Native.MOUSEEVENTF_LEFTDOWN);
        var to92 = GripAt(92f);
        SendMouse((int)to92.X, (int)to92.Y, 0);
        SettleFrames(260);

        Check("拖动中标记为旋转", SelRotating, $"SelRotating={SelRotating}");
        // 指针**顺时针**拖了 92°（GripAt 的角度是屏幕坐标），标签该写 -90°——逆转为正、顺转为负
        Check("读数 ≈ -90°（顺时针为负）", Math.Abs(SelRotationDegrees + 90f) < 1f, $"{SelRotationDegrees:F1}°");
        Check("顺时针 92° 被吸到 -90°", SelRotationSnapped, $"snapped={SelRotationSnapped}");
        int snappedPixels = AccentCount();
        Check("吸住时标签上屏（强调色填充）", snappedPixels > 1500, $"{snappedPixels} 像素");

        // 再拖到 43°（容差外 → 不吸）
        var to43 = GripAt(43f);
        SendMouse((int)to43.X, (int)to43.Y, 0);
        SettleFrames(260);
        Check("顺时针 43° 保持自由（-43°）", !SelRotationSnapped && Math.Abs(SelRotationDegrees + 43f) < 1f,
              $"{SelRotationDegrees:F1}°，snapped={SelRotationSnapped}");
        int freePixels = AccentCount();
        Check("没吸住时标签是白底（强调色像素少）", freePixels < 800, $"{freePixels} 像素");

        // 松手：标签必须消失，且一次拖拽只留一条撤销记录
        SendMouse((int)to43.X, (int)to43.Y, Native.MOUSEEVENTF_LEFTUP);
        SettleFrames(320);
        Check("松手后不再标记旋转", !SelRotating, $"SelRotating={SelRotating}");
        int afterRelease = AccentCount();
        Check("松手后标签从屏幕上消失", afterRelease < 800, $"{afterRelease} 像素（拖动前 {beforeDraw}）");

        var rotated = Doc.Strokes[0].Transform;
        Check("对象真的被转了（不是只显示个标签）",
              Math.Abs(rotated.M11 - 1f) > 0.01f || Math.Abs(rotated.M12) > 0.01f,
              $"M11={rotated.M11:F3} M12={rotated.M12:F3}");

        Doc.Undo();
        SettleFrames(200);
        var back = Doc.Strokes.Count > 0 ? Doc.Strokes[0].Transform : Matrix3x2.Identity;
        Check("一次拖拽 = 一步撤销，撤销后回原位",
              Math.Abs(back.M11 - 1f) < 1e-4f && Math.Abs(back.M12) < 1e-4f
              && Math.Abs(back.M21) < 1e-4f && Math.Abs(back.M22 - 1f) < 1e-4f,
              $"撤销后 M11={back.M11:F4} M12={back.M12:F4}");

        // ================= C. 方向 + 不设上限（用户 2026-09-15 定的）=================
        //
        // 两条都要测：只有"逆时针为正"和"顺时针为负"**成对**出现，才证明符号是对的
        // （只测一条的话，符号写反了也看不出来）。
        // 再往同一方向一直转，看读数会不会在 ±180° 处**绕回**——绕回就说明还是在量
        // "起点到当前点的夹角"，而不是"这一拖一共转了多少"。
        {
            // 圆形选区：绕自己转不改变轴心和半径，角度才好量准
            Stroke NewRound()
            {
                Doc.Clear();
                Doc.ClearHistory();
                var s2 = new Stroke
                {
                    Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                    Color = new Color4(1f, 0f, 1f, 1f), Width = 12f * DpiScale,
                };
                for (int i = 0; i <= 48; i++)
                {
                    float a = i / 48f * MathF.PI * 2f;
                    s2.AddPoint(sx + MathF.Cos(a) * 180f * DpiScale,
                                sy + MathF.Sin(a) * 180f * DpiScale, 0.9f, i * 8);
                }
                Doc.AddStroke(s2);
                Doc.Selected.Clear();
                Doc.Selected.Add(s2);
                Tool = Tool.Marquee;
                SettleFrames(300);
                return s2;
            }

            // 从当前位置的旋转手柄开始，按一串"屏幕角度增量"拖过去（单位：度，顺时针为正）
            float Spin(Stroke s2, params float[] clockwiseSteps)
            {
                var f2 = SelectionHandles.FrameOf(Doc.Selected);
                var grip2 = SelectionHandles.CanvasPosition(SelHandle.Rotate, f2, DpiScale);
                var pivot2 = new Vector2((f2.CanvasAabb.MinX + f2.CanvasAabb.MaxX) * 0.5f,
                                         (f2.CanvasAabb.MinY + f2.CanvasAabb.MaxY) * 0.5f);
                float arm2 = Vector2.Distance(grip2, pivot2);
                float a0 = MathF.Atan2(grip2.Y - pivot2.Y, grip2.X - pivot2.X);

                SendMouse((int)grip2.X, (int)grip2.Y, Native.MOUSEEVENTF_LEFTDOWN);
                SettleFrames(90);
                float travel = 0f;
                foreach (float step in clockwiseSteps)
                {
                    // 传进来的是**增量**：一路加着走，才能真的"转了 200°"。
                    // （第一版写成 `a0 + step` 当绝对角用，两步都落在同一个点上，
                    //  指针没动就没有消息，读数自然只有最后一步——自检当场抓到。）
                    travel += step;
                    float rad = a0 + travel * MathF.PI / 180f;
                    SendMouse((int)(pivot2.X + arm2 * MathF.Cos(rad)),
                              (int)(pivot2.Y + arm2 * MathF.Sin(rad)), 0);
                    SettleFrames(90);
                }
                return SelRotationDegrees;
            }

            // 拖动中"对象现在是什么变换"要问**合成后**的那个矩阵：方案 B 里
            // 模型到松手才动，拖动中的实时位移活在预览矩阵里（对象自己的变换 × 预览矩阵，
            // 和渲染时左乘的完全是同一个式子）。松手后再问 s.Transform 就是它本身。
            Matrix3x2 Live(Stroke s2) => DragPreviewActive
                ? s2.Transform * DragPreviewMatrix : s2.Transform;

            // ① 逆时针 90°：读数为**正**，而且矩阵真的往逆时针转了
            //    （屏幕坐标里逆时针 90° → CreateRotation(-90°) → M12 = -1）
            var spinCcw = NewRound();
            float ccwRead = Spin(spinCcw, -90f);
            Check("逆时针拖 90° → 读数 +90°（逆转为正）",
                  Math.Abs(ccwRead - 90f) < 1.5f, $"读数 {ccwRead:F1}°");
            var liveCcw = Live(spinCcw);
            Check("读数的符号和几何一致（逆时针转出来 M12≈-1）",
                  Math.Abs(liveCcw.M12 + 1f) < 0.05f && Math.Abs(liveCcw.M11) < 0.05f,
                  $"M11={liveCcw.M11:F3} M12={liveCcw.M12:F3}");
            // 方案 B 的契约：拖动中模型**一个字都不动**（动静全在预览里，松手才提交）。
            // 少了这条，将来有人"顺手"把 SetTransformLive 加回去就没人拦得住 ——
            // 而那就是每帧重画走过的面积、19ms/帧 的那条老路。
            Check("拖动中模型不动（只在预览里位移，松手才提交）",
                  DragPreviewActive && spinCcw.Transform.Equals(Matrix3x2.Identity),
                  $"预览={DragPreviewActive}，模型 M11={spinCcw.Transform.M11:F3} M12={spinCcw.Transform.M12:F3}");
            SendMouse(0, 0, Native.MOUSEEVENTF_LEFTUP);
            SettleFrames(200);

            // ② 顺时针 90°：读数为**负**
            var spinCw = NewRound();
            float cwRead = Spin(spinCw, 90f);
            Check("顺时针拖 90° → 读数 -90°（顺转为负）",
                  Math.Abs(cwRead + 90f) < 1.5f, $"读数 {cwRead:F1}°");
            SendMouse(0, 0, Native.MOUSEEVENTF_LEFTUP);
            SettleFrames(200);

            // ③ 不设上限：同一拖里一路逆时针转 200°，读数必须 > 180°，不许绕回 -160°
            var spinLong = NewRound();
            float longRead = Spin(spinLong, -90f, -90f, -20f);
            Check("同一拖转 200° → 读数 ≈ +200°（不绕回）",
                  longRead > 190f && longRead < 210f,
                  $"读数 {longRead:F1}°（绕回的话会是 -160° 左右）");
            var liveLong = Live(spinLong);
            Check("转 200° 的对象真的转了 200°（矩阵能和读数对上）",
                  Math.Abs(liveLong.M11 - MathF.Cos(200f * MathF.PI / 180f)) < 0.05f
                  && Math.Abs(liveLong.M12 + MathF.Sin(200f * MathF.PI / 180f)) < 0.05f,
                  $"M11={liveLong.M11:F3}（期望 {MathF.Cos(200f * MathF.PI / 180f):F3}）");
            SendMouse(0, 0, Native.MOUSEEVENTF_LEFTUP);
            SettleFrames(200);

            // ④ 翻转过的对象：框坐标和屏幕是"反手"的（行列式为负），
            //    读数仍然要以**眼睛看到的方向**为准——屏幕上逆时针拖，就该是正数。
            var spinMirror = NewRound();
            Doc.ApplyTransform(SelectionHandles.MirrorMatrix(spinMirror.WorldInkBounds, horizontal: true));
            SettleFrames(250);
            bool leftHanded = SelectionHandles.IsMirrored(spinMirror.Transform);
            float mirrorRead = Spin(spinMirror, -90f);      // 屏幕上逆时针 90°
            string mirrorNote = leftHanded ? "已镜像（行列式为负）" : "没镜像成（行列式为正）";
            Check("翻转过的对象：屏幕上逆时针拖 → 读数仍为正",
                  leftHanded && mirrorRead > 0f,
                  $"{mirrorNote}，读数 {mirrorRead:F1}°");
            SendMouse(0, 0, Native.MOUSEEVENTF_LEFTUP);
            SettleFrames(200);
        }

        Console.WriteLine();
        Console.WriteLine(fail == 0
            ? "  PASS: 度数读数、三种吸附模式、矩阵自洽与标签上屏都正确"
            : $"  FAIL: {fail} 项不对（{pass} 项通过）");

        Doc.Clear();
        Doc.ClearHistory();
        _quit = true;
    }

    /// <summary>
    /// 变换命令自检。
    ///
    /// 它要证明的是整个对象模型的**核心论断**：改变换不碰几何。
    /// 具体就是三件事——几何版本号不变（GPU 缓存不用重建）、
    /// 包围盒和空间索引跟着走、撤销能精确回到原样。
    /// </summary>
    private void TransformTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 变换命令自检（改矩阵，不碰几何）===");

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"    {name,-22}{(ok ? "PASS" : "FAIL")}  {detail}");
        }

        Doc.Clear();
        Doc.ClearHistory();

        var s = new Stroke
        {
            Tool = Tool.Pen, Kind = StrokeKind.Freehand,
            Color = new Color4(1f, 0f, 0f, 1f), Width = 4f,
        };
        for (int i = 0; i < 60; i++)
            s.AddPoint(200 + i * 5f, 300 + MathF.Sin(i * 0.2f) * 40f, 0.5f, i * 8);
        Doc.AddStroke(s);

        int revisionBefore = s.Revision;
        var boundsBefore = s.WorldBounds;
        float widthBefore = boundsBefore.MaxX - boundsBefore.MinX;

        Doc.Selected.Clear();
        Doc.Selected.Add(s);

        // 以画的起点为中心放大两倍——非等比也不影响这套机制
        var center = new Vector2(boundsBefore.MinX, boundsBefore.MinY);
        int depthBefore = Doc.UndoDepth;
        bool applied = Doc.ApplyTransform(Matrix3x2.CreateScale(2f, 2f, center));
        Check("命令已提交", applied && Doc.UndoDepth == depthBefore + 1,
              $"撤销深度 {depthBefore} -> {Doc.UndoDepth}");

        // ★ 这条是整个设计的要害：几何没有重建
        Check("几何版本号未变", s.Revision == revisionBefore,
              $"Revision {revisionBefore} -> {s.Revision}（GPU 缓存不用重建）");

        var boundsAfter = s.WorldBounds;
        float widthAfter = boundsAfter.MaxX - boundsAfter.MinX;
        Check("包围盒按倍数变大", Math.Abs(widthAfter - widthBefore * 2f) < 0.5f,
              $"{widthBefore:F0} -> {widthAfter:F0} px");

        // 空间索引必须跟着走：在新位置查得到
        var probe = new RectF
        {
            MinX = center.X - 1, MinY = center.Y - 1,
            MaxX = center.X + 1, MaxY = center.Y + 1,
        };
        var hits = new List<Stroke>();
        Doc.QueryGrid(probe, hits);
        Check("空间索引已更新", hits.Contains(s), $"新位置查到 {hits.Count} 个");

        Doc.Undo();
        var boundsUndone = s.WorldBounds;
        bool restored = Math.Abs(boundsUndone.MinX - boundsBefore.MinX) < 0.01f
                     && Math.Abs(boundsUndone.MaxX - boundsBefore.MaxX) < 0.01f
                     && Math.Abs(boundsUndone.MinY - boundsBefore.MinY) < 0.01f
                     && Math.Abs(boundsUndone.MaxY - boundsBefore.MaxY) < 0.01f;
        Check("撤销精确回原位", restored,
              $"({boundsUndone.MinX:F2},{boundsUndone.MinY:F2})-({boundsUndone.MaxX:F2},{boundsUndone.MaxY:F2})");

        Doc.Redo();
        Check("重做又回到放大后", Math.Abs((s.WorldBounds.MaxX - s.WorldBounds.MinX) - widthAfter) < 0.5f, "");

        Console.WriteLine();
        Console.WriteLine(fail == 0 ? "  PASS: 变换只改矩阵，几何与缓存未受影响" : $"  FAIL: {fail} 项不对");
        _quit = true;
    }

    /// <summary>
    /// 保存 / 加载往返自检。
    ///
    /// 验的是"存下去的和读回来的完全一样"。这条比看起来重要：序列化是
    /// **唯一会碰全部字段**的代码，任何一个字段忘了写、或者顺序写错，
    /// 表现都是"用户存了一学期的批注打不开"，而且开发时很难发现。
    /// </summary>
    private void SaveTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 保存 / 加载往返自检 ===");

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"    {name,-22}{(ok ? "PASS" : "FAIL")}  {detail}");
        }

        Doc.Clear();
        Doc.ClearHistory();

        // 自由笔迹：带压感、带时间戳
        var freehand = new Stroke
        {
            Tool = Tool.Pen, Kind = StrokeKind.Freehand,
            Color = new Color4(0.95f, 0.18f, 0.18f, 1f),
            Width = 6f,
        };
        for (int i = 0; i < 40; i++)
            freehand.AddPoint(100 + i * 7f, 200 + MathF.Sin(i * 0.3f) * 30f,
                              0.2f + 0.6f * (i / 40f), 1000 + i * 8.5);
        Doc.AddStroke(freehand);

        // 顺手用像素橡皮在这条笔迹上擦掉一小段：**存档必须把擦除区间一起带上**，
        // 否则"存一次再打开"会把擦掉的墨又画回来（v4 新增的那段就是它）。
        Doc.BeginEraseRect();
        Doc.EraseRectAt(100 + 14 * 7f, 200, 12f, 12f);
        Doc.EndErase();
        bool erasedSaved = freehand.Erased.Count > 0;

        // 图形：带非等比缩放 + 旋转（最容易在序列化里被写错的东西）
        var rect = new Stroke
        {
            Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
            Color = new Color4(0.13f, 0.45f, 0.90f, 0.8f),
            Width = 12f,
            Transform = Matrix3x2.CreateRotation(0.5f)
                      * Matrix3x2.CreateScale(1.5f, 0.75f)
                      * Matrix3x2.CreateTranslation(300f, 120f),
        };
        rect.AddPoint(10, 20, 1f, 5000);
        rect.AddPoint(210, 160, 1f, 5000);
        Doc.AddStroke(rect);

        int before = Doc.Strokes.Count;
        int maxId = 0;
        foreach (var s in Doc.Strokes) maxId = Math.Max(maxId, s.Id);

        var bytes = InkSerializer.Save(Doc);
        Check("格式头可识别", InkSerializer.LooksLikeInk(bytes), $"{bytes.Length} 字节");
        Check("每对象体积合理", bytes.Length / Math.Max(1, before) < 4000,
              $"{bytes.Length / Math.Max(1, before)} 字节/对象");

        var target = new InkDocument();
        InkSerializer.LoadInto(target, bytes);

        Check("对象数量", target.Strokes.Count == before, $"{target.Strokes.Count}");
        Check("加载后撤销栈为空", target.UndoDepth == 0, $"{target.UndoDepth}");

        bool allEqual = target.Strokes.Count == before;
        string diff = "";
        for (int i = 0; allEqual && i < before; i++)
        {
            var a = Doc.Strokes[i];
            var b = target.Strokes[i];
            bool eq = a.Id == b.Id && a.Tool == b.Tool && a.Kind == b.Kind
                   && a.Color.R == b.Color.R && a.Color.G == b.Color.G
                   && a.Color.B == b.Color.B && a.Color.A == b.Color.A
                   && a.Width == b.Width
                   && a.Transform.Equals(b.Transform)
                   && a.Points.Count == b.Points.Count
                   && a.Erased.Count == b.Erased.Count;
            for (int k = 0; eq && k < a.Erased.Count; k++)
                if (a.Erased[k] != b.Erased[k]) eq = false;
            if (eq)
            {
                for (int k = 0; k < a.Points.Count; k++)
                {
                    var p = a.Points[k];
                    var q = b.Points[k];
                    // 时间戳是"绝对量 + float 偏移"，会有浮点截断，给 0.05ms 容差。
                    if (p.X != q.X || p.Y != q.Y || p.P != q.P || Math.Abs(p.T - q.T) > 0.05)
                    { eq = false; diff = $"对象{i} 第{k}点"; break; }
                }
            }
            else diff = $"对象{i} 的字段";
            allEqual = eq;
        }
        Check("逐字段一致", allEqual, allEqual ? "含变换、颜色、压感、时间" : diff);
        Check("擦除区间也一起存了", erasedSaved && allEqual,
              erasedSaved ? "存前有区间、读回后一致（否则擦掉的墨会画回来）"
                          : "这一轮没造出擦除区间，等于没验");

        var probe = new Stroke { Tool = Tool.Pen, Width = 3f };
        probe.AddPoint(0, 0, 1f, 0);
        target.AddStroke(probe);
        Check("新对象 id 不撞车", probe.Id > maxId, $"新 {probe.Id} > 旧最大 {maxId}");

        bool threw = false;
        try { InkSerializer.LoadInto(new InkDocument(), new byte[] { 1, 2, 3, 4, 5, 6, 7, 8, 9 }); }
        catch (InvalidDataException) { threw = true; }
        Check("乱数据抛异常", threw, "");

        var truncated = new byte[bytes.Length / 2];
        Array.Copy(bytes, truncated, truncated.Length);
        var keep = new InkDocument();
        threw = false;
        try { InkSerializer.LoadInto(keep, truncated); } catch (Exception) { threw = true; }
        Check("截断数据抛异常", threw, "");
        Check("失败时文档未被动过", keep.Strokes.Count == 0, $"{keep.Strokes.Count} 个对象");

        // ---- 老文件兼容：v2（每条笔画多一个"笔锋预设"字节）必须还能打开 ----
        // 手写美化删掉之后，那个字节不再写、不再读；**但读老文件时必须读掉它**，
        // 否则后面的变换、点数据全部错位——用户存了一学期的批注会全部打不开。
        // 这个字节就在"宽度"和"变换"之间，写错了表现是"能打开但东西是乱的"，
        // 比打不开更难查，所以专门造一个 v2 文件来验。
        var v2 = new MemoryStream();
        using (var w = new BinaryWriter(v2, System.Text.Encoding.UTF8, leaveOpen: true))
        {
            w.Write(new byte[] { (byte)'I', (byte)'N', (byte)'K', (byte)'B' });
            w.Write(2);                     // 版本 2：每条笔画带预设字节
            w.Write(0);                     // flags
            w.Write(1);                     // 一块画布
            w.Write((byte)0);               // Blank
            w.Write(0f); w.Write(0f); w.Write(0f); w.Write(0f);
            w.Write("");
            w.Write(1);                     // 一个对象
            w.Write(42);                    // id
            w.Write((byte)Tool.Pen);
            w.Write((byte)StrokeKind.Freehand);
            w.Write(0.95f); w.Write(0.18f); w.Write(0.18f); w.Write(1f);
            w.Write(7.5f);                  // 宽度
            w.Write((byte)1);               // ← 已废弃的"笔锋预设"字节（v2 才有）
            w.Write(1f); w.Write(0f); w.Write(0f); w.Write(1f); w.Write(100f); w.Write(200f);
            w.Write(2);                     // 两个点
            w.Write(0.0);                   // 第一个点的时间戳
            w.Write(10f); w.Write(20f); w.Write(0.5f); w.Write(0f);
            w.Write(30f); w.Write(40f); w.Write(0.5f); w.Write(8f);
            w.Write((byte)0);               // 无图像
        }
        var old = new InkDocument();
        bool oldOk = true; string oldNote = "";
        try { InkSerializer.LoadInto(old, v2.ToArray()); }
        catch (Exception ex) { oldOk = false; oldNote = ex.GetType().Name; }
        var os = old.Strokes.Count > 0 ? old.Strokes[0] : null;
        Check("v2 老文件能打开", oldOk && os != null && os.Points.Count == 2, oldNote);
        Check("v2 老文件字段不错位",
            os != null && Math.Abs(os.Width - 7.5f) < 1e-4f
            && Math.Abs(os.Points[1].X - 30f) < 1e-4f && Math.Abs(os.Points[1].Y - 40f) < 1e-4f
            && Math.Abs(os.Transform.M31 - 100f) < 1e-4f,
            os == null ? "没读到对象"
                       : $"宽 {os.Width}、第二个点 ({os.Points[1].X},{os.Points[1].Y})、"
                         + $"平移 ({os.Transform.M31},{os.Transform.M32})");

        Console.WriteLine();
        Console.WriteLine(fail == 0 ? "  PASS: 保存/加载往返正确" : $"  FAIL: {fail} 项不对");
        _quit = true;
    }

    /// <summary>
    /// 图形命中测试自检。
    ///
    /// 验的是"图形走精确命中、自由笔迹走中心线距离"这条分岔有没有走对。
    /// 关键在于：**图形画的是描边轮廓，中间是空的**——用"点到中心线的距离"
    /// 去判定，会把"点在矩形正中央"也当成命中，那是错的。
    /// </summary>
    private void ShapeTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 图形命中测试（描边轮廓，中间是空的）===");

        float cx = _virtualX + 900, cy = _virtualY + 700;
        float halfW = 8f * DpiScale;          // 半笔宽（物理像素）
        var rect = new Stroke
        {
            Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
            Color = new Color4(1f, 0f, 1f, 1f), Width = halfW * 2f,
        };
        rect.AddPoint(cx - 200, cy - 150, 1f, NowMs);
        rect.AddPoint(cx + 200, cy + 150, 1f, NowMs);

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"    {name,-22}{(ok ? "PASS" : "FAIL")}  {detail}");
        }

        Check("边上命中", rect.HitTestExact(cx, cy - 150), "");
        Check("正中央不命中", !rect.HitTestExact(cx, cy), "轮廓中间是空的");
        Check("远处不命中", !rect.HitTestExact(cx + 900, cy + 900), "");

        float off = halfW + 20f;   // 离中心线比半笔宽还远
        Check("容差外不命中", !rect.HitTestExact(cx, cy - 150 + off), $"偏移 {off:F0}px");
        Check("容差内命中", rect.HitTestExact(cx, cy - 150 + off, off + 5f), $"容差 {off + 5f:F0}px");

        var saved = rect.Transform;
        rect.Transform = rect.Transform * Matrix3x2.CreateTranslation(400, 0);
        Check("平移后原位置不命中", !rect.HitTestExact(cx, cy - 150), "");
        Check("平移后新位置命中", rect.HitTestExact(cx + 400, cy - 150), "变换必须参与命中");
        rect.Transform = saved;

        Doc.Clear();
        Doc.AddStroke(rect);
        int removed = Doc.EraseAt(cx, cy, 10f * DpiScale);
        Check("擦正中央不误删", removed == 0, $"删了 {removed} 个");
        removed = Doc.EraseAt(cx, cy - 150, 10f * DpiScale);
        Check("擦边上应删除", removed == 1, $"删了 {removed} 个");

        Console.WriteLine();
        Console.WriteLine(fail == 0 ? "  PASS: 图形命中判定正确" : $"  FAIL: {fail} 项不对");
        _quit = true;
    }

    /// <summary>
    /// 图形工具第一轮（直线先行）自检。六段，前两段走**真机输入**，中间一段是纯数学，
    /// 后面三段走"选择手势"的内部入口（自检里一直是这么驱动手柄的）。
    ///
    ///   A. 接线画图入口：四种工具各拖一次 → Kind 对、两端正好落在按下点 / 松手点、
    ///      一次拖拽 = 一步撤销、撤销一次就干净；
    ///   B. 拖动太短不产生对象（点一下、挪两个像素各一条）；
    ///   C. 画线吸附（数学层）：软吸附 0/30/45/60/90 ±3°、Shift 15° 网格、Alt 自由，
    ///      以及"吸附时绕起点转、保持长度"；顺带把 α 的五个读数钉死；
    ///   D. 拖端点（真机层）：模型在拖动中一个字不改、内容层一帧不重画、
    ///      长度与倾斜角按预期变、Revision 真的变了、一步撤销、α 标签真的上屏；
    ///   E. 旋转过的直线拖端点：端点仍落在指针位置（走 Transform⁻¹ 那条路）。
    /// </summary>
    /// <summary>
    /// 自检 `--librarytest`：**图库（我的图形）**——"选中 → 存入 → 面板 → 落笔插入 → 整理删除"
    /// 整条链真机跑一遍（用户 2026-09-22 要的"图像收藏"，口径见 计划-图形工具.md §41）。
    ///
    /// 为什么每一段都走真机而不是直接调 API：这条链上有四处"看得见的东西"——
    ///   ① 操作条上那颗图标**画在哪儿、点得中吗**（几何与命中同源，`--handletest` 的教训）；
    ///   ② 上带最后那一段「图库」**点得开面板吗**（它是一段"动作"，不进工具表）；
    ///   ③ 面板里的缩略图**真的画出来了吗**——只断言条目数的话，
    ///      "存进去了、格子却是空的"照样绿，所以这里数屏幕像素；
    ///   ④ 落笔插入：**落在按下的地方**、插入后是**选中的**、**一步撤销**。
    ///
    /// ⚠ 图库目录用 <see cref="ShapeLibrary.DirOverride"/> 指到临时目录——
    /// **绝不动用户真正的收藏**（同 `InkSettings.PathOverride` 那条规矩）。
    /// </summary>
    private void LibraryTest(string shotPath)
    {
        Console.WriteLine("===== 图库（我的图形）：存入 → 面板 → 落笔插入 → 整理删除 =====");
        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-34} {detail}");
        }

        string dir = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "inkteach-library-test");
        try { if (System.IO.Directory.Exists(dir)) System.IO.Directory.Delete(dir, true); } catch { }
        ShapeLibrary.DirOverride = dir;

        // 界面要挂上：图库的两个入口（操作条那颗图标要靠界面推上来的主题画、
        // 上带最后那一段是界面画并命中）都在界面上。
        SetUiFactory(() => new InkUi.FullUi());
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }

        var ui = CurrentUi as InkUi.FullUi;
        if (ui == null)
        {
            Console.WriteLine("  没有界面，跳过（图库两个入口都在界面上）");
            Console.WriteLine($"  结果: {pass} 项通过, {fail} 项失败");
            ShapeLibrary.DirOverride = null;
            _quit = true;
            return;
        }

        // 面板刚挂上是**收起态（一个球）**：先点一下球展开，不然后面点"图形"那一格
        // 点的是球（点球＝展开），段一个都点不到 —— ShapeBandTest 第一次跑全红就是这个原因。
        if (!ui.ExpandedForTest)
        {
            var bb = ui.QueryBounds();
            ClickPhys((bb.MinX + bb.MaxX) * 0.5f * DpiScale,
                      (bb.MinY + bb.MaxY) * 0.5f * DpiScale);
            SettleFrames(300);
        }
        Check("面板点球展开了（不然上带那一段点不到）", ui.ExpandedForTest,
              $"ExpandedForTest={ui.ExpandedForTest}");

        void DragPhys(float x0, float y0, float x1, float y1, int holdFrames = 200)
        {
            SendMouse((int)x0, (int)y0, 0);                                 SettleFrames(60);
            SendMouse((int)x0, (int)y0, Native.MOUSEEVENTF_LEFTDOWN);       SettleFrames(60);
            SendMouse((int)((x0 + x1) * 0.5f), (int)((y0 + y1) * 0.5f), 0); SettleFrames(40);
            SendMouse((int)x1, (int)y1, 0);                                 SettleFrames(40);
            SendMouse((int)x1, (int)y1, Native.MOUSEEVENTF_LEFTUP);         SettleFrames(holdFrames);
        }
        void ClickPhys(float x, float y)
        {
            SendMouse((int)x, (int)y, 0);                            SettleFrames(80);
            SendMouse((int)x, (int)y, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
            SendMouse((int)x, (int)y, Native.MOUSEEVENTF_LEFTUP);    SettleFrames(320);
        }

        Doc.Clear();
        Doc.ClearHistory();
        CurrentColor = new Color4(1f, 0f, 1f, 1f);      // 品红：屏幕判据靠它数
        SetToolFromUi(Tool.Rectangle);

        // ---- A. 画一个矩形，把它存进图库 ----
        float ax = _virtualX + 600, ay = _virtualY + 900;
        DragPhys(ax, ay, ax + 320f, ay + 220f);
        Check("A：矩形画出来了，而且是自动选中状态",
              Doc.Strokes.Count == 1 && Doc.Selected.Count == 1,
              $"对象 {Doc.Strokes.Count} 个，选中 {Doc.Selected.Count} 个");

        // 刚画完是"收起来"那一态（见 §40），要先把条摊开才点得到图标。
        {
            var f = SelectionHandles.FrameOf(Doc.Selected);
            var dot = SelectionHandles.BarCollapsedRect(f.CanvasAabb, DpiScale, ViewportCanvas);
            ClickPhys((dot.MinX + dot.MaxX) * 0.5f, (dot.MinY + dot.MaxY) * 0.5f);
            Check("A：点圆钮把操作条摊开了", !BarDrawnCollapsed,
                  $"BarDrawnCollapsed={BarDrawnCollapsed}");
        }

        // 点「图库」那一格：**走真机的命中**（几何和绘制同源，不是直接调动作）。
        var frame0 = SelectionHandles.FrameOf(Doc.Selected);
        var libCell = SelectionHandles.BarButtonRect((int)SelBarButton.Library, frame0.CanvasAabb,
                                                     DpiScale, ViewportCanvas);
        Check("A：操作条上那颗「图库」在屏幕里（没被夹出去）",
              libCell.MinX > 0 && libCell.MaxY < _virtualY + _virtualH,
              $"格子 ({libCell.MinX:F0},{libCell.MinY:F0})-({libCell.MaxX:F0},{libCell.MaxY:F0})");
        ClickPhys((libCell.MinX + libCell.MaxX) * 0.5f, (libCell.MinY + libCell.MaxY) * 0.5f);
        var entries = ShapeLibrary.List();
        Check("A：存进图库了（目录里多出一个条目，里面就是刚画的那个矩形）",
              entries.Count == 1 && entries[0].Strokes.Count == 1
              && entries[0].Strokes[0].Kind == StrokeKind.Rectangle,
              $"条目 {entries.Count} 个" + (entries.Count > 0
                  ? $"，第一个里有 {entries[0].Strokes.Count} 个对象"
                  : ""));

        // ---- B. 从上带最后那一段「图库」打开面板（真机点段）----
        {
            var cell = ui.CellRectForTest(8);
            ClickPhys((cell.MinX + cell.MaxX) * 0.5f * DpiScale, (cell.MinY + cell.MaxY) * 0.5f * DpiScale);
            // 上带只在指针停在面板上时张开：合成鼠标偶尔丢移动，给三次机会（同 ShapeBandTest）。
            for (int attempt = 0; attempt < 3 && !ui.RailOpenForTest; attempt++)
            {
                var bar = ui.BarRectForTest;
                SendMouse((int)((bar.MinX + bar.MaxX) * 0.5f * DpiScale),
                          (int)((bar.MinY + bar.MaxY) * 0.5f * DpiScale) - attempt, 0);
                SettleFrames(350);
            }
            int segCount = ui.BandSegmentCountForTest;
            Check("B：图形那一格多了最后一段（工具段 ＋ 图库）",
                  segCount == 23, $"现在 {segCount} 段（22 个图形 ＋ 1 段图库）");
            var seg = ui.SegmentRectForTest(segCount - 1);
            ClickPhys((seg.MinX + seg.MaxX) * 0.5f * DpiScale,
                      (seg.MinY + seg.MaxY) * 0.5f * DpiScale);
            Check("B：点那一段 → 图库面板开了，而且读到了那个条目",
                  LibraryPanelOpen && LibraryEntries.Count == 1,
                  $"面板 {LibraryPanelOpen}，条目 {LibraryEntries.Count} 个");
        }

        // ---- C. 面板里的缩略图真的画出来了吗（数屏幕像素）----
        {
            var panel = LibraryPanelRectNow();
            var cell = LibraryLayout.CellRect(panel, DpiScale, 0);
            int pix = ScreenProbe.CountMagenta((int)cell.MinX, (int)cell.MinY,
                                               (int)(cell.MaxX - cell.MinX),
                                               (int)(cell.MaxY - cell.MinY));
            Check("C：格子里真的画着那个矩形的缩略图（品红像素）", pix > 30, $"{pix} 像素");

            // 出图（给了路径才出）：面板长什么样只能看——标题行、格子、悬停、
            // 空态文案、整理角标这些"排版对不对"的判据不在断言里。
            if (!string.IsNullOrEmpty(shotPath))
            {
                if (OffscreenFloatingShot(shotPath, panel.Inflate(16f)))
                    Console.WriteLine($"  已出图：{shotPath}");
                else Console.WriteLine("  出图失败");
            }
        }

        // ---- D. 点第一格 → 进"落笔插入"态；再到画布上按一下 → 落在那儿 ----
        {
            var panel = LibraryPanelRectNow();
            var cell = LibraryLayout.CellRect(panel, DpiScale, 0);
            ClickPhys((cell.MinX + cell.MaxX) * 0.5f, (cell.MinY + cell.MaxY) * 0.5f);
            Check("D：点格子 = 准备插入，面板自己收起来了",
                  LibraryInsertArmed && !LibraryPanelOpen,
                  $"待插入 {LibraryInsertArmed}，面板 {LibraryPanelOpen}");

            // 落点：画布右侧空地。**按下的地方 = 插入内容的包围盒左上角**。
            float px = ax + 520f, py = ay - 380f;
            ClickPhys(px, py);
            Check("D：按下就插进来了（对象数 +1）", Doc.Strokes.Count == 2,
                  $"对象 {Doc.Strokes.Count} 个（期望 2）");
            var placed = Doc.Strokes[1];
            var box = EditRegion.Of(new[] { placed });
            var srcBox = EditRegion.Of(new[] { Doc.Strokes[0] });
            Check("D：包围盒左上角正好落在按下的地方、大小和原件一样",
                  MathF.Abs(box.MinX - px) < 3f && MathF.Abs(box.MinY - py) < 3f
                  && MathF.Abs((box.MaxX - box.MinX) - (srcBox.MaxX - srcBox.MinX)) < 0.5f
                  && MathF.Abs((box.MaxY - box.MinY) - (srcBox.MaxY - srcBox.MinY)) < 0.5f,
                  $"落点 ({px:F0},{py:F0})，实际 ({box.MinX:F0},{box.MinY:F0})，"
                  + $"尺寸 {box.MaxX - box.MinX:F1}×{box.MaxY - box.MinY:F1}"
                  + $"（原件 {srcBox.MaxX - srcBox.MinX:F1}×{srcBox.MaxY - srcBox.MinY:F1}）");
            Check("D：插入之后是选中的（能直接拖走）",
                  Doc.Selected.Count == 1 && Doc.Selected[0] == placed,
                  $"选中 {Doc.Selected.Count} 个");
        }

        // ---- E. 一步撤销 + 整理模式删条目 ----
        Doc.Undo();
        SettleFrames(150);
        Check("E：插入是**一步**撤销（退回插入前）", Doc.Strokes.Count == 1,
              $"撤销后对象 {Doc.Strokes.Count} 个（期望 1）");

        {
            Doc.Selected.Clear();
            OpenLibraryPanel();
            SettleFrames(120);
            var panel = LibraryPanelRectNow();
            ClickPhys((LibraryLayout.EditRect(panel, DpiScale).MinX
                       + LibraryLayout.EditRect(panel, DpiScale).MaxX) * 0.5f,
                      (LibraryLayout.EditRect(panel, DpiScale).MinY
                       + LibraryLayout.EditRect(panel, DpiScale).MaxY) * 0.5f);
            Check("E：点「整理」进了整理模式（触摸屏删格子的入口）", LibraryEditMode,
                  $"LibraryEditMode={LibraryEditMode}");

            var cell = LibraryLayout.CellRect(panel, DpiScale, 0);
            var badge = LibraryLayout.BadgeRect(cell, DpiScale);
            ClickPhys((badge.MinX + badge.MaxX) * 0.5f, (badge.MinY + badge.MaxY) * 0.5f);
            Check("E：点红 ✕ 把条目删了（目录里也真没了）",
                  LibraryEntries.Count == 0 && ShapeLibrary.List().Count == 0,
                  $"面板里 {LibraryEntries.Count} 个，目录里 {ShapeLibrary.List().Count} 个");
        }

        CloseLibraryPanel();
        ShapeLibrary.DirOverride = null;      // 收尾：还回真实目录
        try { if (System.IO.Directory.Exists(dir)) System.IO.Directory.Delete(dir, true); } catch { }
        Console.WriteLine(fail == 0
            ? $"  PASS: 图库（存入 / 面板 / 落笔插入 / 整理删除）都对（{pass} 项）"
            : $"  FAIL: {fail} 项不对（{pass} 项通过）");
        _quit = true;
    }

    private void ShapeToolTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 图形工具自检（画图入口 / 吸附 / 端点编辑）===");
        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"    {name,-34}{(ok ? "PASS" : "FAIL")}  {detail}");
        }

        // **白板打底**：后面有几条判据要数屏幕上的强调色像素，透明批注下桌面上
        // 什么颜色都可能出现（这一条在旋转自检里踩过）。板色取深灰，和强调色分得开。
        BoardOn = true;
        BoardColor = new Color4(0.10f, 0.10f, 0.12f, 1f);
        ViewOffsetY = 0f;                    // 屏幕坐标 == 画布坐标，抓屏和算位置都好对
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        CurrentColor = new Color4(1f, 0f, 1f, 1f);   // 品红：几条像素判据要靠它数
        Doc.Clear();
        Doc.ClearHistory();

        Vector2 Pt(InkEngine.InkPoint p) => new Vector2(p.X, p.Y);

        // ================= A. 四种工具各拖一次 =================
        Console.WriteLine("  -- A. 画图入口（四种工具，真机输入）--");
        var tools = new (Tool tool, StrokeKind kind)[]
        {
            (Tool.Line, StrokeKind.Line), (Tool.Rectangle, StrokeKind.Rectangle),
            (Tool.Ellipse, StrokeKind.Ellipse), (Tool.Arrow, StrokeKind.Arrow),
        };
        foreach (var (tool, kind) in tools)
        {
            Doc.Clear();
            Doc.ClearHistory();
            SetToolFromUi(tool);

            // 方向刻意取 α ≈ 22.8°：离软吸附那几条（0/30/45/60/90）都超过 3°，
            // 于是"松手点"就是最终端点，判据才干净。想验吸附在 C 段。
            float ax = _virtualX + 600, ay = _virtualY + 900;
            float bx = ax + 380, by = ay - 160;

            SendMouse((int)ax, (int)ay, 0);                             SettleFrames(60);
            SendMouse((int)ax, (int)ay, Native.MOUSEEVENTF_LEFTDOWN);   SettleFrames(60);
            for (int i = 1; i <= 5; i++)
            {
                SendMouse((int)(ax + (bx - ax) * i / 5f), (int)(ay + (by - ay) * i / 5f), 0);
                SettleFrames(25);
            }
            SendMouse((int)bx, (int)by, Native.MOUSEEVENTF_LEFTUP);     SettleFrames(220);

            string tag = tool.ToString();
            var s = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
            Check($"{tag}：拖出一个对象", s != null, $"对象数 {Doc.Strokes.Count}");
            if (s == null) continue;

            Check($"{tag}：Kind 正确", s.Kind == kind, $"Kind={s.Kind}（期望 {kind}）");
            Check($"{tag}：控制点只有两个（图形由两端定义）", s.Points.Count == 2, $"点数 {s.Points.Count}");
            Check($"{tag}：起点落在按下点",
                  Vector2.Distance(Pt(s.Points[0]), new Vector2(ax, ay)) < 2f,
                  $"起点 ({Pt(s.Points[0]).X:F0},{Pt(s.Points[0]).Y:F0}) 期望 ({ax:F0},{ay:F0})");
            Check($"{tag}：终点落在松手点",
                  Vector2.Distance(Pt(s.Points[^1]), new Vector2(bx, by)) < 2f,
                  $"终点 ({Pt(s.Points[^1]).X:F0},{Pt(s.Points[^1]).Y:F0}) 期望 ({bx:F0},{by:F0})");
            Check($"{tag}：一次拖拽 = 一步撤销", Doc.UndoDepth == 1, $"撤销栈 {Doc.UndoDepth} 步");
            if (tool == Tool.Line)
            {
                // 画出来还得真的**上屏**（预览与提交后的几何是同一条，不该有跳变）
                var mid = new Vector2((ax + bx) * 0.5f, (ay + by) * 0.5f);
                int onScreen = ScreenProbe.CountMagenta((int)mid.X - 30, (int)mid.Y - 30, 60, 60);
                Check($"{tag}：画出来的线真的上了屏", onScreen > 100, $"线上取一块 {onScreen} 像素");
            }
            Doc.Undo();
            SettleFrames(150);
            Check($"{tag}：撤销一次就干净", Doc.Strokes.Count == 0 && Doc.UndoDepth == 0,
                  $"撤销后对象 {Doc.Strokes.Count} 个，撤销栈 {Doc.UndoDepth} 步");
        }

        // ================= A2. 画完自动选中 ＋ 那个框只"收起来"，别的都不变 =================
        //
        // 用户 2026-09-22 定的三条：
        //   ① 图形一成型就**自动出现选中框**（"方便调整和拖动"）；
        //   ② "点击了其他地方，这个选中框就取消"——取消完这一笔还得**照常画得出来**
        //     （计划-图形工具.md 第 8 条："紧接着落笔不被遮罩吃掉"）；
        //   ③ 上手之后补的：**刚画完把操作条收起来（一颗圆钮）**，点一下才摊开成整条——
        //     但"**只要收缩，其他的都不变**"（拖动 / 拉手柄 / 点条一律和框选工具下一样）。
        //     原话后半句是他抓出来的 bug："它好像不能拖动位置，只能拉伸缩放"。
        //
        // 下面按顺序真拖一遍（走真机输入，不直接调内部函数）。
        Console.WriteLine("  -- A2. 画完自动选中：收起那颗圆钮 / 框里照常能拖 / 框外接着画 --");
        Doc.Clear();
        Doc.ClearHistory();
        CurrentColor = new Color4(1f, 0f, 1f, 1f);      // 品红：屏幕判据靠它数
        SetToolFromUi(Tool.Rectangle);

        void DragPhys(float x0, float y0, float x1, float y1, int holdFrames = 200)
        {
            SendMouse((int)x0, (int)y0, 0);                                 SettleFrames(60);
            SendMouse((int)x0, (int)y0, Native.MOUSEEVENTF_LEFTDOWN);       SettleFrames(60);
            SendMouse((int)((x0 + x1) * 0.5f), (int)((y0 + y1) * 0.5f), 0); SettleFrames(40);
            SendMouse((int)x1, (int)y1, 0);                                 SettleFrames(40);
            SendMouse((int)x1, (int)y1, Native.MOUSEEVENTF_LEFTUP);         SettleFrames(holdFrames);
        }

        void ClickPhys(float x, float y)
        {
            SendMouse((int)x, (int)y, 0);                            SettleFrames(80);
            SendMouse((int)x, (int)y, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
            SendMouse((int)x, (int)y, Native.MOUSEEVENTF_LEFTUP);    SettleFrames(320);
        }

        float a2x = _virtualX + 500, a2y = _virtualY + 700;      // 第 1 个矩形的左上角
        const float a2w = 420f, a2h = 300f;
        DragPhys(a2x, a2y, a2x + a2w, a2y + a2h);

        var r1 = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
        Check("A2：拖出矩形成型", r1 != null && r1.Kind == StrokeKind.Rectangle,
              $"对象 {Doc.Strokes.Count} 个，Kind {(r1 == null ? "（一个都没有）" : r1.Kind.ToString())}");
        Check("A2：成型那一刻它就**自动选中**了",
              r1 != null && Doc.Selected.Count == 1 && Doc.Selected[0] == r1,
              $"选中 {Doc.Selected.Count} 个");
        // 工具**不换成框选**：手里还是矩形，"接着画下一个"才是常态（换工具会把上带也掰走）。
        Check("A2：工具还是矩形（没被换成框选）",
              Host.State.Tool == Tool.Rectangle, $"当前工具 {Host.State.Tool}");
        // **刚画完是"收起来"那一档**：只挂一颗圆钮，不是一整条九格（用户上手之后定的）。
        Check("A2：刚画完那个框是**收起来**的形态（一颗圆钮，不是一整条）",
              AutoSelCollapsed && BarDrawnCollapsed, $"AutoSelCollapsed={AutoSelCollapsed}");

        // 框＋手柄真的画到屏幕上了：数选中框上边那条线（强调色）的像素。
        // 只判模型的话，"选中了、但框没上屏"这种毛病（脏区没盖住）看不出来。
        var r1Box = r1.WorldInkBounds;
        {
            float probeX = (r1Box.MinX + r1Box.MaxX) * 0.5f - 30f;
            float probeY = r1Box.MinY - 10f;
            int boxPix = ScreenProbe.CountNear((int)probeX, (int)probeY, 60, 26, 0, 120, 212, 60);
            Check("A2：选中框真的上了屏（框上边那一段的强调色像素）", boxPix > 150,
                  $"框上边取一块 {boxPix} 像素");
        }

        // ② **按在框里那块空白**（不在墨上）：该是"拖它走"——和框选工具下**一模一样**。
        //    用户 2026-09-22 上手报的就是这一条："它好像不能拖动位置，只能拉伸缩放"。
        //    从框的正中间开始拖：那儿离八个手柄都远（这个框 420×300，离最近的手柄也有 150 像素
        //    以上，而手柄命中半径是 14 逻辑像素），而且**不在墨上**（矩形正中间是空的）——
        //    所以除了"框里能拖"这一条，没有别的路能走通。
        float inX = (r1Box.MinX + r1Box.MaxX) * 0.5f, inY = (r1Box.MinY + r1Box.MaxY) * 0.5f;
        DragPhys(inX, inY, inX + 140f, inY + 60f);
        Check("A2：按在框里＝拖它走（不是在框里又画一个）", Doc.Strokes.Count == 1,
              $"对象 {Doc.Strokes.Count} 个（期望 1）");
        var moved1 = r1.WorldInkBounds;
        float dx1 = (moved1.MinX + moved1.MaxX) * 0.5f - (r1Box.MinX + r1Box.MaxX) * 0.5f;
        Check("A2：它真的跟着挪了（整体平移，形状没被拉变形）",
              MathF.Abs(dx1 - 140f) < 8f
              && MathF.Abs((moved1.MaxX - moved1.MinX) - (r1Box.MaxX - r1Box.MinX)) < 2f,
              $"框心横移 {dx1:F0}（期望 140），宽 {r1Box.MaxX - r1Box.MinX:F0} → {moved1.MaxX - moved1.MinX:F0}");
        Doc.Undo();
        SettleFrames(150);
        Check("A2：这一次拖动是一步撤销",
              Doc.Strokes.Count == 1 && MathF.Abs(r1.WorldInkBounds.MinX - r1Box.MinX) < 1f,
              $"撤销后对象 {Doc.Strokes.Count} 个，框左上角 {r1.WorldInkBounds.MinX:F0}（期望 {r1Box.MinX:F0}）");

        // ③ 按在**框外**（这里正好是"原来那条操作条的地盘"）：该是"收起这个框、这一笔照常画"
        //    ——用户 2026-09-22 定的口径："点击了其他地方，这个选中框就取消"。
        //    ⚠ 这一条同时守着 `--shapebandtest` A3 段踩出来的那个坑：整条操作条原来就挂在
        //    图形正下方，老师想在下面接着画时会被它吃掉（跑出来的是"点了条上的某一格"）。
        //    现在刚画完只挂一颗圆钮，整条要**点开圆钮**才出来，所以那片地方是空的。
        {
            var bar2 = SelectionHandles.BarRect(r1Box, DpiScale, ViewportCanvas);
            // 圆钮在**框的正下方、居中**（`BarCollapsedRect`），所以从条的**左端**按下去
            // ——那头离圆钮 150 像素以上，测的就是"整条不在"这件事本身。
            float bx2 = bar2.MinX + 30f, by2 = (bar2.MinY + bar2.MaxY) * 0.5f;
            Check("A2：那一刻那颗圆钮确实离这儿很远（不然这条测的是圆钮）",
                  Math.Abs(bx2 - (bar2.MinX + bar2.MaxX) * 0.5f) > 100f,
                  $"按点 x={bx2:F0}，圆钮中心 x={(bar2.MinX + bar2.MaxX) * 0.5f:F0}");
            DragPhys(bx2, by2, bx2 + 300f, by2 + 200f);
            Check("A2：按在框外＝收起框、接着画（整条没摊开、也没被它吃掉）",
                  Doc.Strokes.Count == 2,
                  $"对象 {Doc.Strokes.Count} 个（期望 2：第 1 个 ＋ 框外新画的）");
            var r1BoxNow = Doc.Strokes[0].WorldInkBounds;
            Check("A2：第 1 个矩形**没被拖走**",
                  MathF.Abs(r1BoxNow.MinX - r1Box.MinX) < 1f && MathF.Abs(r1BoxNow.MinY - r1Box.MinY) < 1f,
                  $"左上角 ({r1Box.MinX:F0},{r1Box.MinY:F0}) → ({r1BoxNow.MinX:F0},{r1BoxNow.MinY:F0})");
            Check("A2：新画的这个又被自动选中、又是收起那一态",
                  Doc.Selected.Count == 1 && Doc.Selected[0] == Doc.Strokes[1] && AutoSelCollapsed,
                  $"选中 {Doc.Selected.Count} 个，AutoSelCollapsed={AutoSelCollapsed}");
        }

        // ④ **点一下那颗圆钮** → 摊开成整条操作条（行为一个字都不变，只是"条"长得完整了）。
        {
            var f = SelectionHandles.FrameOf(Doc.Selected);
            var dot = SelectionHandles.BarCollapsedRect(f.CanvasAabb, DpiScale, ViewportCanvas);
            ClickPhys((dot.MinX + dot.MaxX) * 0.5f, (dot.MinY + dot.MaxY) * 0.5f);
            Check("A2：点一下圆钮 → 摊开成整条（不再是收起的）",
                  !AutoSelCollapsed && !BarDrawnCollapsed && SelectionBarShown,
                  $"AutoSelCollapsed={AutoSelCollapsed}，SelectionBarShown={SelectionBarShown}");
        }

        // ⑤ 每个新框都从**收起**开始；不点圆钮、直接点「选择」工具也一样摊开
        //    （`SwitchTool` 对"换到框选"本来就不清选区，那儿顺手把"刚画完"这一档也清掉）。
        {
            Doc.Selected.Clear();                            // 清干净，下一步那一笔落点要确定
            SettleFrames(60);
            // 落在**第 1 个矩形右边那块空地**上：离前面两个框都远，按下会不会被谁挡住没有歧义。
            DragPhys(a2x + 520f, a2y + 40f, a2x + 780f, a2y + 220f);   // 再画一个，让它自动选中
            Check("A2：新画的这个又是「收起来」那一态（每个新框都从收起开始）",
                  Doc.Strokes.Count == 3 && AutoSelCollapsed && Doc.Selected.Count == 1,
                  $"对象 {Doc.Strokes.Count} 个，AutoSelCollapsed={AutoSelCollapsed}");
            SetToolFromUi(Tool.Marquee);
            SettleFrames(120);
            Check("A2：点一下「选择」工具 → 选区还在、整条操作条出来（不点圆钮也行）",
                  Doc.Selected.Count == 1 && SelectionBarShown && !BarDrawnCollapsed,
                  $"选中 {Doc.Selected.Count} 个，SelectionBarShown={SelectionBarShown}");
        }

        // ================= B. 拖动太短不产生对象 =================
        Console.WriteLine("  -- B. 拖动太短（误点）不产生对象 --");
        Doc.Clear();
        Doc.ClearHistory();
        SetToolFromUi(Tool.Line);
        CurrentColor = new Color4(1f, 0f, 1f, 1f);      // 品红：屏幕上好不好数
        float px = _virtualX + 700, py = _virtualY + 1100;

        SendMouse((int)px, (int)py, 0);                             SettleFrames(60);
        SendMouse((int)px, (int)py, Native.MOUSEEVENTF_LEFTDOWN);   SettleFrames(60);
        SendMouse((int)px, (int)py, Native.MOUSEEVENTF_LEFTUP);     SettleFrames(200);
        Check("点一下不产生对象", Doc.Strokes.Count == 0 && Doc.UndoDepth == 0,
              $"对象 {Doc.Strokes.Count} 个，撤销 {Doc.UndoDepth} 步（都不该有）");

        // 2 物理像素：100% 缩放下是 2 逻辑像素，200% 下是 1 —— 两种情况都短于 4
        SendMouse((int)px, (int)py, Native.MOUSEEVENTF_LEFTDOWN);   SettleFrames(60);
        SendMouse((int)px + 2, (int)py + 2, 0);                     SettleFrames(100);
        SendMouse((int)px + 2, (int)py + 2, Native.MOUSEEVENTF_LEFTUP); SettleFrames(200);
        Check("挪 2 物理像素也不产生对象（短于 4 逻辑像素）",
              Doc.Strokes.Count == 0 && Doc.UndoDepth == 0,
              $"对象 {Doc.Strokes.Count} 个，撤销 {Doc.UndoDepth} 步（都不该有）");

        // 连"屏幕上有没有留下杂物"一起验：拖动预览是每帧画在浮动层上的，
        // 不提交的时候必须连预览一起消失（这里数的是屏幕像素，不是模型）。
        int residue = ScreenProbe.CountMagenta((int)px - 60, (int)py - 60, 120, 120);
        Check("拖动太短：屏幕上也没留下墨（不许留杂物）", residue == 0, $"{residue} 像素");

        // ================= C. 吸附（数学层）=================
        Console.WriteLine("  -- C. 画线吸附与倾斜角（数学层）--");
        var origin = new Vector2(1000f, 1000f);
        // 目标点：从 origin 出发、方向角 α = deg、长度 len。
        // （α 的定义就是本段要验的东西，所以下面另有一组**写死坐标**的读数判据。）
        Vector2 At(float deg, float len)
            => new Vector2(origin.X + len * MathF.Cos(-deg * MathF.PI / 180f),
                           origin.Y + len * MathF.Sin(-deg * MathF.PI / 180f));

        void SnapCase(string name, float target, float want, bool wantSnap,
                      bool shift = false, bool alt = false)
        {
            var e = SelectionHandles.SnapEndPoint(origin, At(target, 300f), shift, alt, out bool snapped);
            float got = SelectionHandles.InclinationDegrees(origin, e);
            float len = Vector2.Distance(origin, e);
            bool ok = Math.Abs(got - want) < 0.05f && snapped == wantSnap && Math.Abs(len - 300f) < 0.05f;
            Check(name, ok, $"{target:F1}° → {got:F1}°{(snapped ? "（吸附）" : "（自由）")}"
                          + $"，长度 {len:F1}（期望 300）"
                          + $"，期望 {want:F1}°{(wantSnap ? "（吸附）" : "（自由）")}");
        }

        // 容差 2026-09-18 从 ±3° 收紧到 ±1°，所以"31.5° 吸到 30°"这类旧判据已经不对了：
        // 现在要 30.5° 才吸、31.5° 必须**不吸**（用户就是要能画出 26.5°/31.5° 这种角）。
        SnapCase("软吸附：正对 45°", 45f, 45f, true);
        SnapCase("软吸附：容差内吸到 30°（30.5°）", 30.5f, 30f, true);
        SnapCase("软吸附：容差边界内（30.9°）", 30.9f, 30f, true);
        SnapCase("软吸附：容差边界外（31.1° 不吸）", 31.1f, 31.1f, false);
        SnapCase("软吸附：旧容差下会吸、现在不吸（31.5°）", 31.5f, 31.5f, false);
        SnapCase("软吸附：容差内吸到 0°（水平）", 0.5f, 0f, true);
        // 0° 与 180° 是同一条线：判距离必须是**环形**的（这条以前是错的，179.5° 吸不到 0°）
        SnapCase("软吸附：179.5° 吸到 180≡0°（环形距离）", 179.5f, 0f, true);
        SnapCase("软吸附：容差内吸到 60°", 60.5f, 60f, true);
        SnapCase("软吸附：容差内吸到 90°（竖直）", 89.5f, 90f, true);
        SnapCase("软吸附：容差内吸到 120°（新增）", 120.5f, 120f, true);
        SnapCase("软吸附：容差内吸到 135°（新增）", 135.5f, 135f, true);
        SnapCase("软吸附：容差内吸到 150°（新增）", 150.5f, 150f, true);
        SnapCase("软吸附：容差外保持自由（25°）", 25f, 25f, false);
        SnapCase("软吸附：容差外保持自由（38°）", 38f, 38f, false);
        SnapCase("Shift：15° 硬网格（37° → 30°）", 37f, 30f, true, shift: true);
        SnapCase("Shift：吸到 60°", 58f, 60f, true, shift: true);
        SnapCase("Shift：15° 网格照旧覆盖特殊角（92° → 90°）", 92f, 90f, true, shift: true);
        SnapCase("Alt：完全自由（44° 不吸 45°）", 44f, 44f, false, alt: true);
        SnapCase("Shift+Alt：Shift 优先", 37f, 30f, true, shift: true, alt: true);

        // 环形距离/最短角差是这一轮新加的，单独钉两条（旋转吸附要用它把"吸到的角"
        // 换算成"这一拖还得转多少度"）。
        Check("环形距离：179.5° 离 0° 是 0.5°（不是 179.5°）",
              Math.Abs(SelectionHandles.InclinationDistance(179.5f, 0f) - 0.5f) < 1e-3f,
              $"算出 {SelectionHandles.InclinationDistance(179.5f, 0f):F3}°");
        Check("最短角差：从 179.5° 到 0° 是 +0.5°（不是 -179.5°）",
              Math.Abs(SelectionHandles.InclinationShortestDelta(179.5f, 0f) - 0.5f) < 1e-3f,
              $"算出 {SelectionHandles.InclinationShortestDelta(179.5f, 0f):F3}°");

        // ---- 展开角（可以超过 180°、也可以是负数）的吸附：特殊角按 180° 周期 ----
        // 单选直线拖旋转柄读的就是这种数（用户 2026-09-18 澄清："可以无限转下去"）。
        // 这里的判据只看"吸完落在哪个数上"——不能折回 [0,180)，否则 405 会被印成 45。
        void ExpSnapCase(string name, float deg, float want, bool wantSnap,
                         bool shift = false, bool alt = false)
        {
            float got = SelectionHandles.SnapExpandedInclinationDegrees(deg, shift, alt, out bool snapped);
            Check(name, Math.Abs(got - want) < 0.01f && snapped == wantSnap,
                  $"{deg:F1}° → {got:F1}°{(snapped ? "（吸附）" : "（自由）")}"
                  + $"，期望 {want:F1}°{(wantSnap ? "（吸附）" : "（自由）")}");
        }
        ExpSnapCase("展开吸附：405° 就是特殊角（45° + 一整圈）", 405f, 405f, true);
        ExpSnapCase("展开吸附：404.5° 吸到 405°（±1° 内）", 404.5f, 405f, true);
        ExpSnapCase("展开吸附：406.5° 不吸（±1° 外）", 406.5f, 406.5f, false);
        ExpSnapCase("展开吸附：765.4° 吸到 765°（45° + 两圈）", 765.4f, 765f, true);
        ExpSnapCase("展开吸附：−135.4° 吸到 −135°（负方向那一圈）", -135.4f, -135f, true);
        ExpSnapCase("展开吸附：−180.6° 吸到 −180°（0° 的负方向）", -180.6f, -180f, true);
        ExpSnapCase("展开吸附：−355° 保持自由（45° − 400°，离特殊角 5°）", -355f, -355f, false);
        ExpSnapCase("展开吸附：Shift 的 15° 网格也按 180° 周期（407° → 405°）", 407f, 405f, true, shift: true);
        ExpSnapCase("展开吸附：Alt 完全自由（405.5° 不吸）", 405.5f, 405.5f, false, alt: true);
        Check("展开角文案：405° / −135° 都是纯数字一位小数（不带 α =）",
              SelectionHandles.FormatSignedDegrees(405f) == "405.0°"
              && SelectionHandles.FormatSignedDegrees(-135.4f) == "-135.4°"
              && SelectionHandles.FormatSignedDegrees(45f) == "45.0°"
              && SelectionHandles.FormatSignedDegrees(-0.02f) == "0.0°",
              $"405° → \"{SelectionHandles.FormatSignedDegrees(405f)}\"，"
              + $"−135.4° → \"{SelectionHandles.FormatSignedDegrees(-135.4f)}\"，"
              + $"−0.02° → \"{SelectionHandles.FormatSignedDegrees(-0.02f)}\"");

        // α 的五条读数：**写死坐标**，不借上面的 At（否则等于自己证自己）。
        void InclCase(string name, Vector2 a, Vector2 b, float want)
        {
            float got = SelectionHandles.InclinationDegrees(a, b);
            Check(name, Math.Abs(got - want) < 0.05f, $"{got:F2}°（期望 {want:F2}°）");
        }
        InclCase("α：水平 = 0°", new Vector2(0, 0), new Vector2(300, 0), 0f);
        InclCase("α：斜率 0.5 上升 = 26.57°", new Vector2(0, 0), new Vector2(200, -100), 26.565f);
        InclCase("α：竖直 = 90°", new Vector2(0, 0), new Vector2(0, 300), 90f);
        InclCase("α：斜率 -1 下降 = 135°", new Vector2(0, 0), new Vector2(300, 300), 135f);
        InclCase("α：差 1° 到水平 = 179°", new Vector2(0, 0), new Vector2(-300, -5.2365f), 179f);
        Check("α：反向量是同一条线（读数不变）",
              Math.Abs(SelectionHandles.InclinationDegrees(new Vector2(300, 300), new Vector2(0, 0)) - 135f) < 0.05f,
              "180° 与 0° 是同一条水平线，读数必须折在 [0,180)");
        Check("α：文案格式", SelectionHandles.FormatInclination(30.04f) == "α = 30.0°",
              $"30.04° → \"{SelectionHandles.FormatInclination(30.04f)}\"");
        Check("α：水平线不会印成 -0.0（α 按定义非负）",
              SelectionHandles.FormatInclination(
                  SelectionHandles.InclinationDegrees(new Vector2(0, 0), new Vector2(300, 0))) == "α = 0.0°",
              $"水平线 → \"{SelectionHandles.FormatInclination(SelectionHandles.InclinationDegrees(new Vector2(0, 0), new Vector2(300, 0)))}\"");

        // ================= D. 拖端点（真机层）=================
        Console.WriteLine("  -- D. 拖端点（快路 / 读数 / 撤销）--");
        Doc.Clear();
        Doc.ClearHistory();
        Tool = Tool.Marquee;
        float lx = _virtualX + 700, ly = _virtualY + 1000;
        var line = new Stroke
        {
            Tool = Tool.Line, Kind = StrokeKind.Line,
            Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
        };
        line.AddPoint(lx, ly, 1f, 0);             // 水平：α = 0°
        line.AddPoint(lx + 600f, ly, 1f, 0);
        Doc.AddStroke(line);
        Doc.SelectOnly(new[] { line });
        SettleFrames(300);

        var pA = SelectionHandles.EndpointCanvasPosition(line, 0);
        var pB = SelectionHandles.EndpointCanvasPosition(line, 1);
        int revBefore = line.Revision;
        int undoBefore = Doc.UndoDepth;          // 加这条线本身也算一步，所以比"净增 1"

        // 目标：绕 pB 转、长度 620、**原始**方向 30.5°（容差 ±1° 内 → 该吸到 30°）。
        // 屏幕方向角 θ = 149.5°（左偏下）——拖的是左边那个端点，不能把它甩到右边去。
        const float wantLen = 620f;
        float theta = 149.5f * MathF.PI / 180f;
        var raw = new Vector2(pB.X + wantLen * MathF.Cos(theta), pB.Y + wantLen * MathF.Sin(theta));

        bool took = SelectionGestureForTest(pA.X, pA.Y);
        Check("按在端点手柄上被接住（不是整体拖动）",
              took && VertexDragging, $"接住={took}，VertexDragging={VertexDragging}");

        SettleFrames(60);
        int patchAtBegin = _windows[0].LastPatchCount;   // 起手那一下要重画一次（把这条从内容层摘掉）
        UpdateSelectionGestureForTest(raw.X, raw.Y);
        SettleFrames(90);

        Check("拖动中：模型一个字没改（走的是快路）",
              Math.Abs(line.Points[0].X - lx) < 0.01f && Math.Abs(line.Points[1].X - (lx + 600f)) < 0.01f
              && line.Revision == revBefore,
              $"端点 ({line.Points[0].X:F1},{line.Points[0].Y:F1})，Revision {revBefore} → {line.Revision}");
        Check("拖动中：内容层一帧都不重画（方案 B）",
              _windows[0].LastPatchCount == 0,
              $"上一帧光栅化分块 {_windows[0].LastPatchCount} 块（起手那一下是 {patchAtBegin} 块）");
        // 旧位置那一段（离固定端很远，ghost 根本没走到那儿）**不许还有墨**：
        // 拖端点复用了"把这条从内容层摘出去"的机制，于是"拖动预览"这条路也可能顺手把它
        // 按单位矩阵再画一遍——屏幕上就成了"旧线不动 + 新线跟着指针"两条线（2026-09-18 抓到）。
        int staleInk = ScreenProbe.CountMagenta((int)(lx - 30f), (int)(ly - 30f), 230, 60);
        Check("拖动中：旧位置不许还留着那条线（预览与临时几何只能画一个）",
              staleInk == 0, $"{staleInk} 像素（这一段在临时几何之外，正确时应为 0）");
        Check("拖动中：α 被吸到 30°（软吸附）",
              VertexInclinationSnapped && VertexReadout == VertexReadoutKind.Inclination
              && Math.Abs(VertexReadoutValue - 30f) < 0.5f,
              $"α = {VertexReadoutValue:F1}°，吸住={VertexInclinationSnapped}");

        var anchor = VertexPreviewCanvasPoint;
        int labelPixels = ScreenProbe.CountNear(
            (int)(anchor.X - 70f * DpiScale), (int)(anchor.Y - 60f * DpiScale),
            (int)(140f * DpiScale), (int)(60f * DpiScale), 0, 120, 212, 40);
        // 两条边界一起判：太少 = 标签没画出来；太多 = 画得比胶囊还大
        // （字号用错单位就会这样：Dpi=192 拿去当缩放倍数，字会糊满整个画面）。
        Check("拖动中：倾斜角读数真的上屏（吸住 → 强调色胶囊）",
              labelPixels > 1200 && labelPixels < 20000,
              $"{labelPixels} 像素（探针窗一半面积是 {140 * DpiScale * 60 * DpiScale / 2:F0}）");

        EndSelectionGestureForTest();
        SettleFrames(250);

        Check("松手后：读数标签消失（不再拖端点）", !VertexDragging, $"VertexDragging={VertexDragging}");
        var pA2 = SelectionHandles.EndpointCanvasPosition(line, 0);
        float len2 = Vector2.Distance(pB, pA2);
        Check("松手后：长度保持 620（吸附只改方向、不改长短）",
              Math.Abs(len2 - wantLen) < 2f, $"长度 {len2:F1}（期望 {wantLen:F0}）");
        Check("松手后：倾斜角 ≈ 30°",
              Math.Abs(SelectionHandles.InclinationDegrees(pB, pA2) - 30f) < 0.5f,
              $"α = {SelectionHandles.InclinationDegrees(pB, pA2):F2}°");
        Check("松手后：另一个端点没动",
              Vector2.Distance(SelectionHandles.EndpointCanvasPosition(line, 1), pB) < 0.5f,
              $"另一端点 {Vector2.Distance(SelectionHandles.EndpointCanvasPosition(line, 1), pB):F2}px");
        Check("松手后：Revision 变了（几何缓存真的失效）",
              line.Revision > revBefore, $"Revision {revBefore} → {line.Revision}");
        Check("松手后：一次拖拽只多了**一步**撤销（净增 1）",
              Doc.UndoDepth == undoBefore + 1,
              $"撤销栈 {undoBefore} → {Doc.UndoDepth} 步（拖动中的预览不该进撤销栈）");

        Doc.Undo();
        SettleFrames(200);
        Check("撤销后：端点回到原位",
              Vector2.Distance(SelectionHandles.EndpointCanvasPosition(line, 0), pA) < 0.5f,
              $"端点 {SelectionHandles.EndpointCanvasPosition(line, 0)} 期望 {pA}");

        // ---- D2. 只点一下端点手柄（不移动）：线不许从屏幕上消失 ----
        //
        // 这条防的是快路的一个副作用：起手那一下这条线已经从内容层摘出去了，
        // 一点没动的时候如果不再标一次脏，屏幕上那块就永远是"没有这条线"。
        Doc.Clear();
        Doc.ClearHistory();
        var tap = new Stroke
        {
            Tool = Tool.Line, Kind = StrokeKind.Line,
            Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
        };
        tap.AddPoint(lx, ly, 1f, 0);
        tap.AddPoint(lx + 600f, ly, 1f, 0);
        Doc.AddStroke(tap);
        Doc.SelectOnly(new[] { tap });
        SettleFrames(300);
        var tapBox = tap.PaddedBounds.Inflate(6f);
        int inkBefore = ScreenProbe.CountMagenta((int)tapBox.MinX, (int)tapBox.MinY,
                                                 (int)(tapBox.MaxX - tapBox.MinX),
                                                 (int)(tapBox.MaxY - tapBox.MinY));
        var tapA = SelectionHandles.EndpointCanvasPosition(tap, 0);
        bool tookTap = SelectionGestureForTest(tapA.X, tapA.Y);
        SettleFrames(120);
        EndSelectionGestureForTest();
        SettleFrames(250);
        int inkAfter = ScreenProbe.CountMagenta((int)tapBox.MinX, (int)tapBox.MinY,
                                                (int)(tapBox.MaxX - tapBox.MinX),
                                                (int)(tapBox.MaxY - tapBox.MinY));
        Check("点一下端点手柄（不移动）：线还在屏幕上、也没多一条撤销",
              tookTap && !VertexDragging && inkAfter > inkBefore / 2 && Doc.UndoDepth == 1,
              $"接住={tookTap}，墨 {inkBefore} → {inkAfter} 像素，撤销栈 {Doc.UndoDepth} 步");

        // ---- D3. 拖端点中的框：与静止态**同一口径**（每边不再多 2 像素）----
        //
        // 这一处只差 2 像素，肉眼看不出来，所以**只看数字**（用户 2026-09-19 要求）。
        // 用一条**转过 30° 的斜线**：旧口径（把整体框矩形转过去再取外接）会虚胖一大圈，
        // 两种口径的差别在这里才看得清（用水平长线的话差 6 像素，等于没验到）。
        Console.WriteLine("  -- D3. 拖端点中的框：与静止态同一口径 --");
        {
            bool SameBox(in RectF a, in RectF b, float tol = 0.01f)
                => MathF.Abs(a.MinX - b.MinX) < tol && MathF.Abs(a.MinY - b.MinY) < tol
                && MathF.Abs(a.MaxX - b.MaxX) < tol && MathF.Abs(a.MaxY - b.MaxY) < tol;
            string Size(in RectF r) => $"{r.MaxX - r.MinX:F0}×{r.MaxY - r.MinY:F0}";

            Doc.Clear();
            Doc.ClearHistory();
            Tool = Tool.Marquee;
            var vb = new Stroke
            {
                Tool = Tool.Line, Kind = StrokeKind.Line,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
            };
            vb.AddPoint(lx, ly, 1f, 0);                        // 45° 斜线
            vb.AddPoint(lx + 600f, ly - 600f, 1f, 0);
            vb.Transform = SelectionHandles.RotateMatrix(30f, new Vector2(lx + 300f, ly - 300f));
            Doc.AddStroke(vb);
            Doc.SelectOnly(new[] { vb });
            SettleFrames(300);

            var vb0 = SelectionHandles.EndpointCanvasPosition(vb, 0);
            var vb1 = SelectionHandles.EndpointCanvasPosition(vb, 1);
            var stillBox = SelectionHandles.FrameOf(Doc.Selected).Local;
            Check("D3：这条线是转过角度的（α = 45° + 30° = 75°）",
                  MathF.Abs(SelectionHandles.InclinationDegrees(vb0, vb1) - 75f) < 0.5f,
                  $"α = {SelectionHandles.InclinationDegrees(vb0, vb1):F2}°，静止框 {Size(stillBox)}");

            // ① 按在端点上但**不移动**：框必须和静止态逐边相等（改前这里每边多 2 像素）
            bool took3 = SelectionGestureForTest(vb0.X, vb0.Y);
            SettleFrames(60);
            var pressBox = LiveSelectionFrame.Local;
            Check("D3：按下不移动时，框与静止态逐边相等（每边不再多 2 像素）",
                  took3 && VertexDragging && SameBox(pressBox, stillBox),
                  $"按下 {Size(pressBox)} / 静止 {Size(stillBox)}"
                  + $"（旧口径会是 {Size(stillBox)} + 4 那种）");

            // ② 拖到某处：框 = 按预览端点现算的墨迹框（端点外接 + 半笔宽），≤0.5 像素
            var target3 = new Vector2(vb1.X - 320f, vb1.Y + 430f);
            UpdateSelectionGestureForTest(target3.X, target3.Y);
            SettleFrames(80);
            var previewEnd = VertexPreviewCanvasPoint;
            var wantInk = RectF.Empty;
            wantInk.Add(previewEnd.X, previewEnd.Y);
            wantInk.Add(vb1.X, vb1.Y);
            wantInk = wantInk.Inflate(vb.Width * 0.5f);
            var dragBox = LiveSelectionFrame.Local;
            Check("D3：拖动中的框 = 按预览端点现算的墨迹框（≤0.5 像素）",
                  SameBox(dragBox, wantInk, 0.5f),
                  $"拖动 {Size(dragBox)} / 现算 {Size(wantInk)}"
                  + $"（脏区口径 PaddedBoundsOf 会是 {Size(Stroke.PaddedBoundsOf(VertexPreviewPoints, vb.Transform, vb.Width))}）");
            Check("D3：拖动中模型仍然没动（快路）",
                  Math.Abs(vb.Points[0].X - lx) < 0.01f && Math.Abs(vb.Points[1].Y - (ly - 600f)) < 0.01f,
                  $"模型端点 ({vb.Points[0].X:F0},{vb.Points[0].Y:F0})-({vb.Points[1].X:F0},{vb.Points[1].Y:F0})");

            // ③ 松手：框前后逐边相等（不再"缩一下"），提交的几何就是刚才预览的那个端点
            EndSelectionGestureForTest();
            SettleFrames(200);
            var afterBox = SelectionHandles.FrameOf(Doc.Selected).Local;
            Check("D3：松手前后框逐边相等（不再缩一下）",
                  SameBox(dragBox, afterBox, 0.5f),
                  $"松手前 {Size(dragBox)} / 松手后 {Size(afterBox)}");
            Check("D3：松手后提交的几何 = 刚才预览的端点（≤1 像素）",
                  Vector2.Distance(SelectionHandles.EndpointCanvasPosition(vb, 0), previewEnd) < 1f,
                  $"提交 {SelectionHandles.EndpointCanvasPosition(vb, 0)} / 预览 {previewEnd}");
        }

        // ================= E. 旋转过的直线：端点仍落在指针位置 =================
        Console.WriteLine("  -- E. 旋转过的直线拖端点（Transform⁻¹ 那条路）--");
        Doc.Clear();
        Doc.ClearHistory();
        var rot = new Stroke
        {
            Tool = Tool.Line, Kind = StrokeKind.Line,
            Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
        };
        rot.AddPoint(lx, ly, 1f, 0);
        rot.AddPoint(lx + 600f, ly + 300f, 1f, 0);
        var rotCenter = new Vector2(lx + 300f, ly + 150f);
        rot.Transform = Matrix3x2.CreateRotation(-37f * MathF.PI / 180f, rotCenter);
        Doc.AddStroke(rot);
        Doc.SelectOnly(new[] { rot });
        SettleFrames(300);

        var eA = SelectionHandles.EndpointCanvasPosition(rot, 0);
        var eB = SelectionHandles.EndpointCanvasPosition(rot, 1);
        // 原始方向 17°：离最近的吸附方向（0° / 30°）都超过 1°（现在的容差），
        // 所以预览 = 指针，判据干净。
        float eTheta = -17f * MathF.PI / 180f;
        var rawE = new Vector2(eB.X + 520f * MathF.Cos(eTheta), eB.Y + 520f * MathF.Sin(eTheta));

        bool tookE = SelectionGestureForTest(eA.X, eA.Y);
        UpdateSelectionGestureForTest(rawE.X, rawE.Y);
        SettleFrames(90);
        Check("旋转过的直线：拖动中也就地预览（模型没动）",
              tookE && VertexDragging && Math.Abs(rot.Points[0].X - lx) < 0.01f,
              $"接住={tookE}，模型起点 ({rot.Points[0].X:F1},{rot.Points[0].Y:F1})");
        EndSelectionGestureForTest();
        SettleFrames(250);

        var eA2 = SelectionHandles.EndpointCanvasPosition(rot, 0);
        Check("旋转过的直线：拖完端点落在指针位置",
              Vector2.Distance(eA2, rawE) < 1.5f,
              $"端点 {eA2}，指针 {rawE}，差 {Vector2.Distance(eA2, rawE):F2}px");
        Check("旋转过的直线：另一端不动",
              Vector2.Distance(SelectionHandles.EndpointCanvasPosition(rot, 1), eB) < 0.5f,
              $"差 {Vector2.Distance(SelectionHandles.EndpointCanvasPosition(rot, 1), eB):F2}px");
        Doc.Undo();
        SettleFrames(150);
        Check("旋转过的直线：撤销回原位",
              Vector2.Distance(SelectionHandles.EndpointCanvasPosition(rot, 0), eA) < 0.5f,
              $"端点 {SelectionHandles.EndpointCanvasPosition(rot, 0)} 期望 {eA}");

        // ================= F. 画线过程中也显示 α（真机层）=================
        //
        // 用户 2026-09-18 四条之一："画直线的时候也要显示倾斜角 α"。
        // 这条要**数屏幕像素**（不能只判状态）：标签是画在浮动层上的，
        // 进没进每帧脏区、会不会被裁掉，只有看像素才知道。
        Console.WriteLine("  -- F. 画线过程中的 α 读数（真机层）--");
        Doc.Clear();
        Doc.ClearHistory();
        SetToolFromUi(Tool.Line);
        float dx0 = _virtualX + 700, dy0 = _virtualY + 1200;
        // 原始方向 45.5°（容差 ±1° 内 → 该吸到 45°）、长度 500
        float dTheta = -45.5f * MathF.PI / 180f;
        var dEnd = new Vector2(dx0 + 500f * MathF.Cos(dTheta), dy0 + 500f * MathF.Sin(dTheta));

        // 读数标签贴在"正在拖的那一端"上方（盒子高 30 逻辑 + 一段间距）：
        // 探针窗按它取，取小一点，别把线本身的像素算进来。
        int ShapeLabelPixels(Vector2 anchor)
            => ScreenProbe.CountNear((int)(anchor.X - 70f * DpiScale), (int)(anchor.Y - 60f * DpiScale),
                                     (int)(140f * DpiScale), (int)(60f * DpiScale), 0, 120, 212, 40);

        SendMouse((int)dx0, (int)dy0, 0);                             SettleFrames(60);
        SendMouse((int)dx0, (int)dy0, Native.MOUSEEVENTF_LEFTDOWN);   SettleFrames(60);
        SendMouse((int)dEnd.X, (int)dEnd.Y, 0);                       SettleFrames(200);

        Check("画线中：引擎报出「正在画有倾斜角的图形」并给了 α",
              ShapeInclinationActive && ShapeInclinationSnapped
              && Math.Abs(ShapeInclinationDegrees - 45f) < 0.5f,
              $"active={ShapeInclinationActive}，α = {ShapeInclinationDegrees:F1}°，吸住={ShapeInclinationSnapped}");
        int drawPixels = ShapeLabelPixels(ShapeInclinationAnchor);
        Check("画线中：α 读数真的上了屏（吸住 → 强调色胶囊）",
              drawPixels > 1200 && drawPixels < 20000,
              $"{drawPixels} 像素（探针窗一半面积是 {140 * DpiScale * 60 * DpiScale / 2:F0}）");

        // 再拖到 26.5°（离特殊角都超过 1° → 自由态）：读数该跟着变、胶囊该变回白底
        var dFree = new Vector2(dx0 + 500f * MathF.Cos(-26.565f * MathF.PI / 180f),
                                dy0 + 500f * MathF.Sin(-26.565f * MathF.PI / 180f));
        SendMouse((int)dFree.X, (int)dFree.Y, 0);                     SettleFrames(200);
        Check("画线中：拖到 26.5° 就是 26.5°（不再被吸到 30°）",
              !ShapeInclinationSnapped && Math.Abs(ShapeInclinationDegrees - 26.565f) < 0.5f,
              $"α = {ShapeInclinationDegrees:F2}°，吸住={ShapeInclinationSnapped}");
        int freeLabelPixels = ShapeLabelPixels(ShapeInclinationAnchor);
        Check("画线中：没吸住时胶囊是白底（强调色像素变少）",
              freeLabelPixels < drawPixels / 2, $"{drawPixels} → {freeLabelPixels} 像素");

        SendMouse((int)dFree.X, (int)dFree.Y, Native.MOUSEEVENTF_LEFTUP); SettleFrames(250);
        Check("松手后：画线读数消失、也没留下杂物（那条线还在）",
              !ShapeInclinationActive && ShapeLabelPixels(ShapeInclinationAnchor) < 800,
              $"active={ShapeInclinationActive}，探针里强调色 {ShapeLabelPixels(ShapeInclinationAnchor)} 像素");

        // ================= G. 单选直线拖旋转柄：读数是 α（不是 Δ）=================
        //
        // 用户 2026-09-18 的原话："那个旋转手柄使用直线水平为 0° 为依据，如果是这个直线初始
        // 是倾斜的，那它就要有对应的角度。按照高中数学，在 0~180° 里面，然后在这个度数上
        // 接着开始旋转。" —— 所以要判两件事：读数**接着它原有的 α** 变，并且**不是** Δ。
        Console.WriteLine("  -- G. 单选直线旋转读 α / 其它对象读 Δ（真机层）--");
        Doc.Clear();
        Doc.ClearHistory();
        Tool = Tool.Marquee;
        // 一条初始就倾斜的直线：α = atan2(218, 600) ≈ 19.96°
        var spinLine = new Stroke
        {
            Tool = Tool.Line, Kind = StrokeKind.Line,
            Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
        };
        spinLine.AddPoint(lx, ly, 1f, 0);
        spinLine.AddPoint(lx + 600f, ly - 218f, 1f, 0);
        Doc.AddStroke(spinLine);
        Doc.SelectOnly(new[] { spinLine });
        SettleFrames(300);
        float a0 = SelectionHandles.InclinationDegrees(
            SelectionHandles.EndpointCanvasPosition(spinLine, 0),
            SelectionHandles.EndpointCanvasPosition(spinLine, 1));

        // 绕选区中心把旋转柄的指针**屏幕逆时针**拖若干步（每一步都是"从这个位置直接到那个位置"，
        // 所以累积角是精确的步进和；分步是为了能走出"一整圈"这种大角度）。
        void SpinSteps(float[] ccwSteps, out bool took)
        {
            var f = SelectionHandles.FrameOf(Doc.Selected);
            var pv = new Vector2((f.CanvasAabb.MinX + f.CanvasAabb.MaxX) * 0.5f,
                                 (f.CanvasAabb.MinY + f.CanvasAabb.MaxY) * 0.5f);
            var grip = SelectionHandles.CanvasPosition(SelHandle.Rotate, f, DpiScale);
            float arm = Vector2.Distance(grip, pv);
            float a = MathF.Atan2(grip.Y - pv.Y, grip.X - pv.X);
            took = SelectionGestureForTest(grip.X, grip.Y);
            float travel = 0f;
            foreach (float step in ccwSteps)
            {
                // 传进来的是**增量**：一路加着走，才能真的"转了一整圈"。
                travel += step;
                // 屏幕坐标里 y 朝下：角度**减小**才是视觉上的逆时针（和 --rotatetest 的 Spin 同一套）
                float rad = a - travel * MathF.PI / 180f;
                UpdateSelectionGestureForTest(pv.X + arm * MathF.Cos(rad), pv.Y + arm * MathF.Sin(rad));
                SettleFrames(70);
            }
        }

        void GrabRotate(float ccwDeg, out bool took) => SpinSteps(new[] { ccwDeg }, out took);

        GrabRotate(24.5f, out bool tookSpin);
        Check("单选直线：旋转中标记为「读 α₀+Δ」而不是 Δ",
              tookSpin && SelRotating && SelRotationReadsInclination,
              $"接住={tookSpin}，SelRotating={SelRotating}，读数走 α₀+Δ={SelRotationReadsInclination}");
        Check("单选直线：读数 = 这条线按下时的 α 接着转（19.96° + 24.5° → 吸到 45°）",
              Math.Abs(SelRotationInclination - 45f) < 0.1f,
              $"读数 {SelRotationInclination:F2}°（按下时 α={a0:F2}°），Δ 是 {SelRotationDegrees:F2}°");
        Check("单选直线：读数 = 它原有的 α 接着变（≈ 按下时 α + 转过的角），而且不是 Δ",
              Math.Abs(SelRotationInclination - (a0 + SelRotationDegrees)) < 0.2f
              && Math.Abs(SelRotationInclination - SelRotationDegrees) > a0 - 5f,
              $"按下时 α={a0:F2}°，Δ={SelRotationDegrees:F2}° → 读数 {SelRotationInclination:F2}°"
              + $"（要是读 Δ 就该是 {SelRotationDegrees:F2}°）");
        Check("单选直线：吸到特殊角（45°）", SelRotationSnapped, $"吸住={SelRotationSnapped}");

        // 屏幕上真的画了那颗胶囊（文案是 α 那一句，宽度和 Δ 那句不同）
        {
            var f = SelectionHandles.FrameOf(Doc.Selected);
            var grip = SelectionHandles.CanvasPosition(SelHandle.Rotate, f, DpiScale);
            int rotLabel = ScreenProbe.CountNear((int)(grip.X - 80f * DpiScale), (int)(grip.Y - 90f * DpiScale),
                                                 (int)(160f * DpiScale), (int)(80f * DpiScale), 0, 120, 212, 40);
            Check("单选直线：旋转标签真的上屏（吸住 → 强调色胶囊）",
                  rotLabel > 1200 && rotLabel < 20000, $"{rotLabel} 像素");
        }
        EndSelectionGestureForTest();
        SettleFrames(200);
        Check("松手：这次旋转提交成一步撤销，且直线真的转到 45° 附近",
              Doc.UndoDepth == 2 && Math.Abs(SelectionHandles.InclinationDegrees(
                  SelectionHandles.EndpointCanvasPosition(spinLine, 0),
                  SelectionHandles.EndpointCanvasPosition(spinLine, 1)) - 45f) < 0.5f,
              $"撤销栈 {Doc.UndoDepth} 步（1=加线 2=旋转），"
              + $"线现在是 {SelectionHandles.InclinationDegrees(SelectionHandles.EndpointCanvasPosition(spinLine, 0), SelectionHandles.EndpointCanvasPosition(spinLine, 1)):F2}°");
        Doc.Undo();
        SettleFrames(150);

        // ---- 「可以无限转下去」那一组（用户 2026-09-18 澄清）----
        //
        // 从一条 α₀ = 45° 的线起手：
        //   · 逆时针转一整圈 → 读数 405.0°（不是折回 45°）；
        //   · 顺时针转 400°  → 读数 −355.0°。
        // 中间还插一条"读数变化量 = 视觉转角"的核对（读数 135° 时线本身也真的在 135°，
        // 说明吸完的角同时用在矩阵和标签上）。
        float LineInclination(Stroke s2) => SelectionHandles.InclinationDegrees(
            SelectionHandles.EndpointCanvasPosition(s2, 0),
            SelectionHandles.EndpointCanvasPosition(s2, 1));

        // 拖动中"这条线现在是什么姿态"要问**合成后**的矩阵：方案 B 里模型到松手才动，
        // 实时姿态活在预览矩阵里（和 --rotatetest 的 Live() 同一个式子）。
        float LiveInclination(Stroke s2)
        {
            var m = DragPreviewActive ? s2.Transform * DragPreviewMatrix : s2.Transform;
            var a = Vector2.Transform(new Vector2(s2.Points[0].X, s2.Points[0].Y), m);
            var b = Vector2.Transform(new Vector2(s2.Points[^1].X, s2.Points[^1].Y), m);
            return SelectionHandles.InclinationDegrees(a, b);
        }

        Stroke MakeFortyFiveLine()
        {
            var s2 = new Stroke
            {
                Tool = Tool.Line, Kind = StrokeKind.Line,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
            };
            s2.AddPoint(lx, ly, 1f, 0);
            s2.AddPoint(lx + 520f, ly - 520f, 1f, 0);     // α = 45°
            return s2;
        }

        Doc.Clear();
        Doc.ClearHistory();
        var fullTurn = MakeFortyFiveLine();
        Doc.AddStroke(fullTurn);
        Doc.SelectOnly(new[] { fullTurn });
        SettleFrames(300);
        Check("无上限组：起手这条线是 45°", Math.Abs(LineInclination(fullTurn) - 45f) < 0.01f,
              $"α₀ = {LineInclination(fullTurn):F2}°");

        var fTurn = SelectionHandles.FrameOf(Doc.Selected);
        var pvTurn = new Vector2((fTurn.CanvasAabb.MinX + fTurn.CanvasAabb.MaxX) * 0.5f,
                                 (fTurn.CanvasAabb.MinY + fTurn.CanvasAabb.MaxY) * 0.5f);
        var gripTurn = SelectionHandles.CanvasPosition(SelHandle.Rotate, fTurn, DpiScale);
        float armTurn = Vector2.Distance(gripTurn, pvTurn);
        float aTurn0 = MathF.Atan2(gripTurn.Y - pvTurn.Y, gripTurn.X - pvTurn.X);
        bool tookTurn = SelectionGestureForTest(gripTurn.X, gripTurn.Y);
        float travelTurn = 0f;
        void TurnStep(float ccw)
        {
            travelTurn += ccw;               // 正数 = 屏幕逆时针（rad = a0 − 转过的角）
            float rad = aTurn0 - travelTurn * MathF.PI / 180f;
            UpdateSelectionGestureForTest(pvTurn.X + armTurn * MathF.Cos(rad),
                                          pvTurn.Y + armTurn * MathF.Sin(rad));
            SettleFrames(70);
        }

        TurnStep(90f);
        Check("无上限组：逆时针 90° → 读数 45+90 = 135.0°（读数变化量 = 视觉转角）",
              tookTurn && Math.Abs(SelRotationInclination - 135f) < 0.5f
              && Math.Abs(LiveInclination(fullTurn) - 135f) < 0.5f,
              $"读数 {SelRotationInclination:F2}°，线的实时姿态 {LiveInclination(fullTurn):F2}°"
              + $"（模型此刻还没动，仍是 {LineInclination(fullTurn):F2}°）");
        TurnStep(90f);
        TurnStep(90f);
        TurnStep(90f);
        Check("无上限组：再转三步共**一整圈** → 读数 405.0°（不是 45.0°）",
              Math.Abs(SelRotationInclination - 405f) < 0.5f,
              $"读数 {SelRotationInclination:F2}°（折回的话会是 {SelRotationInclination - 360f:F2}° 那种小数字）");
        Check("无上限组：转到 405° 时仍然吸得住特殊角（180° 周期）",
              SelRotationSnapped, $"吸住={SelRotationSnapped}，读数 {SelRotationInclination:F2}°");
        EndSelectionGestureForTest();
        SettleFrames(200);
        Check("无上限组：松手后线真的转了一整圈（视觉上回到 45°）",
              Math.Abs(LineInclination(fullTurn) - 45f) < 0.5f,
              $"线现在 {LineInclination(fullTurn):F2}°");
        Doc.Undo();
        SettleFrames(150);

        // 顺时针转 400°：读数 −355.0°（负方向同样无下限）
        Doc.Clear();
        Doc.ClearHistory();
        var negTurn = MakeFortyFiveLine();
        Doc.AddStroke(negTurn);
        Doc.SelectOnly(new[] { negTurn });
        SettleFrames(300);
        var fNeg = SelectionHandles.FrameOf(Doc.Selected);
        var pvNeg = new Vector2((fNeg.CanvasAabb.MinX + fNeg.CanvasAabb.MaxX) * 0.5f,
                                (fNeg.CanvasAabb.MinY + fNeg.CanvasAabb.MaxY) * 0.5f);
        var gripNeg = SelectionHandles.CanvasPosition(SelHandle.Rotate, fNeg, DpiScale);
        float armNeg = Vector2.Distance(gripNeg, pvNeg);
        float aNeg0 = MathF.Atan2(gripNeg.Y - pvNeg.Y, gripNeg.X - pvNeg.X);
        float travelNeg = 0f;
        void NegStep(float cw)
        {
            travelNeg += cw;                 // 顺时针量：屏幕上的方向角**增大**
            float rad = aNeg0 + travelNeg * MathF.PI / 180f;
            UpdateSelectionGestureForTest(pvNeg.X + armNeg * MathF.Cos(rad),
                                          pvNeg.Y + armNeg * MathF.Sin(rad));
            SettleFrames(70);
        }
        bool tookNeg = SelectionGestureForTest(gripNeg.X, gripNeg.Y);   // 先按下旋转柄
        for (int i = 0; i < 4; i++) NegStep(90f);      // 顺时针 360°
        NegStep(40f);                                   // 再 40° → 共 400°
        Check("无上限组：顺时针转 400° → 读数 −355.0°（负方向也没有下限）",
              tookNeg && Math.Abs(SelRotationInclination + 355f) < 0.5f,
              $"接住={tookNeg}，读数 {SelRotationInclination:F2}°（期望 −355.0°）");
        EndSelectionGestureForTest();
        SettleFrames(200);
        Doc.Undo();
        SettleFrames(150);

        // —— 单选图形（矩形）：读数走**姿态角**（规格 9.7；在这之前它读 Δ）——
        // 吸 0/90、矩阵与标签同角这些真机细节在下面的 G2 段，这里只钉"走哪一档"。
        Doc.Clear();
        Doc.ClearHistory();
        var spinRect = new Stroke
        {
            Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
            Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
        };
        spinRect.AddPoint(lx, ly, 1f, 0);
        spinRect.AddPoint(lx + 600f, ly - 400f, 1f, 0);
        Doc.AddStroke(spinRect);
        Doc.SelectOnly(new[] { spinRect });
        SettleFrames(300);
        GrabRotate(24.5f, out bool tookRect);
        Check("矩形：旋转读数走**姿态角**（不读 α、也不读 Δ）",
              tookRect && SelRotating && SelRotationReadsPose && !SelRotationReadsInclination,
              $"接住={tookRect}，读姿态={SelRotationReadsPose}，读α={SelRotationReadsInclination}，"
              + $"读数 {SelRotationPose:F2}°（Δ 是 {SelRotationDegrees:F2}°）");
        Check("矩形：姿态角读数 = 0 + 24.5 → 24.5°（离 0/90 都远，不吸）",
              !SelRotationSnapped && MathF.Abs(SelRotationPose - 24.5f) < 1.5f,
              $"读数 {SelRotationPose:F2}°，吸住={SelRotationSnapped}");
        // 多选（两条线）：也应该退回 Δ（"单选一个图形 / 单选直线"才读那两个角）
        EndSelectionGestureForTest();
        SettleFrames(150);
        Doc.Clear();
        Doc.ClearHistory();
        var m1 = new Stroke { Tool = Tool.Line, Kind = StrokeKind.Line,
                              Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale };
        m1.AddPoint(lx, ly, 1f, 0);
        m1.AddPoint(lx + 600f, ly - 218f, 1f, 0);
        var m2 = new Stroke { Tool = Tool.Line, Kind = StrokeKind.Line,
                              Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale };
        m2.AddPoint(lx, ly + 300f, 1f, 0);
        m2.AddPoint(lx + 600f, ly + 82f, 1f, 0);
        Doc.AddStroke(m1);
        Doc.AddStroke(m2);
        Doc.SelectOnly(new[] { m1, m2 });
        SettleFrames(300);
        GrabRotate(24.5f, out bool tookMulti);
        Check("多选两条直线：旋转读数也退回 Δ（只有单选直线才读 α）",
              tookMulti && SelRotating && !SelRotationReadsInclination && !SelRotationReadsPose
              && Math.Abs(SelRotationDegrees - 24.5f) < 1.5f,
              $"接住={tookMulti}，读α={SelRotationReadsInclination}，读数 {SelRotationDegrees:F2}°");
        EndSelectionGestureForTest();
        SettleFrames(150);

        // ================= G2. 姿态角（图形）：提取 / 吸附 0-90 / 矩阵与标签同角 =================
        //
        // 规格 9.7：单选一个图形（矩形 / 椭圆 / 三角形 / 平行四边形）拖旋转柄时，
        // 读数从"转了多少 Δ"改成"**图形相对水平的姿态角**"（0° = 正的、90° = 竖的），
        // 软吸附 0/90（±1°）。用户要的用途写在规格里：将来手写识别出来的椭圆 / 矩形可能是
        // 歪的，**看着读数拖到 0° 就转正了**。
        Console.WriteLine("  -- G2. 姿态角（提取 / 吸附 / 矩阵与标签同角）--");
        {
            // 独立量一遍姿态角：把局部 x 轴过变换、自己 atan2、自己折进 [0,180)。
            // **不走被测的那条路**（PoseAngleDegrees），判据才有意义。
            float IndependentPose(Matrix3x2 m)
            {
                var o = Vector2.Transform(Vector2.Zero, m);
                var v = Vector2.Transform(Vector2.UnitX, m) - o;
                float a = -MathF.Atan2(v.Y, v.X) * 180f / MathF.PI;
                a %= 180f;
                if (a < 0f) a += 180f;
                return a;
            }
            // 拖动中"这个图形现在什么姿态"要问**合成后**的矩阵（方案 B：模型到松手才动）。
            float LivePose(Stroke s) => IndependentPose(
                DragPreviewActive ? s.Transform * DragPreviewMatrix : s.Transform);

            var pc = new Vector2(lx + 300f, ly - 150f);
            foreach (float deg in new[] { 0f, 12.5f, 137.4f, 271f })
            {
                var m = SelectionHandles.RotateMatrix(deg, pc);
                float got = SelectionHandles.PoseAngleDegrees(m);
                Check($"姿态角·提取：转 {deg:F1}° 的图形",
                      MathF.Abs(got - IndependentPose(m)) < 0.1f,
                      $"读数 {got:F2}°，独立算 {IndependentPose(m):F2}°（折在 [0,180)）");
            }
            // 镜像 / 翻转：折进 [0,180) 之后与"正反"无关（图形没有正反）。
            // 左右翻转一个正着的矩形，它照样是"水平的" → 读 0.0°。
            var flipH = SelectionHandles.RotateMatrix(0f, pc) * Matrix3x2.CreateScale(-1f, 1f, pc);
            Check("姿态角·提取：左右翻转过的矩形照样读 0.0°",
                  SelectionHandles.IsMirrored(flipH)
                  && SelectionHandles.InclinationDistance(
                         SelectionHandles.PoseAngleDegrees(flipH), 0f) < 0.01f,
                  $"读 {SelectionHandles.PoseAngleDegrees(flipH):F2}°（行列式为负 = 已镜像，"
                  + $"独立算 {IndependentPose(flipH):F2}°）");
            foreach (float deg in new[] { 0f, 30f, 95f })
            {
                var mm = SelectionHandles.RotateMatrix(deg, pc)
                       * Matrix3x2.CreateScale(1f, -1f, pc);        // 上下翻转
                float got = SelectionHandles.PoseAngleDegrees(mm);
                Check($"姿态角·提取：上下翻转 + 转 {deg:F1}°",
                      SelectionHandles.IsMirrored(mm)
                      && got >= 0f && got < 180f
                      && MathF.Abs(got - IndependentPose(mm)) < 0.1f,
                      $"读 {got:F2}°，独立算 {IndependentPose(mm):F2}°，镜像={SelectionHandles.IsMirrored(mm)}");
            }

            // 吸附口径：**只有 0/90 两条，±1°**（和直线同一套容差；直线是八个特殊角）。
            float F0(float d, bool shift, bool alt, out bool sn)
                => SelectionHandles.SnapPoseDegrees(d, shift, alt, out sn);
            Check("姿态角·吸附：0.6° 吸到 0°（±1° 内）",
                  MathF.Abs(F0(0.6f, false, false, out bool p1) - 0f) < 0.01f && p1, "0.6° → 0.0°");
            Check("姿态角·吸附：1.3° **不吸**（容差外，和直线同一个 ±1°）",
                  MathF.Abs(F0(1.3f, false, false, out bool p2) - 1.3f) < 0.01f && !p2, "1.3° → 留自由");
            Check("姿态角·吸附：89.4° 吸到 90°",
                  MathF.Abs(F0(89.4f, false, false, out bool p3) - 90f) < 0.01f && p3, "89.4° → 90.0°");
            Check("姿态角·吸附：91.4° 不吸（容差外）",
                  MathF.Abs(F0(91.4f, false, false, out bool p4) - 91.4f) < 0.01f && !p4, "91.4° → 留自由");
            // 折过的那一版在环上算：179.5° 离 0° 只有 0.5°，所以吸到的是 **0°**（同一条水平线）。
            Check("姿态角·吸附：179.5° 吸到 0°（环形：离 0° 只有 0.5°）",
                  MathF.Abs(F0(179.5f, false, false, out bool p5) - 0f) < 0.01f && p5, "179.5° → 0.0°");
            Check("姿态角·吸附：45° 不吸（它不在 0/90 这两条上）",
                  MathF.Abs(F0(45f, false, false, out bool p6) - 45f) < 0.01f && !p6, "45° → 留自由");
            Check("姿态角·吸附：Shift = 15° 硬网格",
                  MathF.Abs(F0(12.6f, true, false, out bool p7) - 15f) < 0.01f && p7, "12.6° → 15°");
            Check("姿态角·吸附：Alt = 完全自由",
                  MathF.Abs(F0(0.2f, false, true, out bool p8) - 0.2f) < 0.01f && !p8, "0.2° → 留自由");
            // 引擎里用的是**展开值**那一版（"按下时的角 + 累积角"）：连续角上吸才不会翻 180°。
            Check("姿态角·吸附（展开值）：179.6° → 180.0°（不是翻成 0°）",
                  MathF.Abs(SelectionHandles.SnapExpandedPoseDegrees(179.6f, false, false, out bool p9)
                            - 180f) < 0.01f && p9,
                  "179.6° → 180.0°（拿折过的值去吸会得到 0.0° —— 那等于把图形翻过来 180°）");
            Check("姿态角·吸附（展开值）：-0.4° → 0.0°（顺时针转过来的那一点点）",
                  MathF.Abs(SelectionHandles.SnapExpandedPoseDegrees(-0.4f, false, false, out bool p10)
                            - 0f) < 0.01f && p10,
                  "-0.4° → 0.0°");

            // ---- 真机①：一个**转过 8° 的矩形**拖旋转柄 → 吸到 0°（水平）----
            Doc.Clear();
            Doc.ClearHistory();
            Tool = Tool.Marquee;
            var poseRect = new Stroke
            {
                Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
            };
            poseRect.AddPoint(lx, ly, 1f, 0);
            poseRect.AddPoint(lx + 600f, ly + 400f, 1f, 0);
            poseRect.Transform = SelectionHandles.RotateMatrix(8f, new Vector2(lx + 300f, ly + 200f));
            Doc.AddStroke(poseRect);
            Doc.SelectOnly(new[] { poseRect });
            SettleFrames(300);
            Check("姿态角·真机：这个矩形一开始是歪的（姿态 8.0°）",
                  MathF.Abs(SelectionHandles.PoseAngleDegrees(poseRect.Transform) - 8f) < 0.05f,
                  $"姿态 {SelectionHandles.PoseAngleDegrees(poseRect.Transform):F3}°");
            GrabRotate(-8.4f, out bool tookPose);     // 屏幕上顺时针 8.4°：姿态 8° → -0.4（±1° 内 → 吸到 0）
            Check("姿态角·真机：拖旋转柄 → 走姿态角这一档",
                  tookPose && SelRotating && SelRotationReadsPose && !SelRotationReadsInclination,
                  $"接住={tookPose}，读姿态={SelRotationReadsPose}，读α={SelRotationReadsInclination}");
            Check("姿态角·真机：吸到 0°（水平）", SelRotationSnapped,
                  $"吸住={SelRotationSnapped}，读数 {SelRotationPose:F3}°");
            Check("姿态角·真机：读数就是 0.0°（吸住时写的是吸到的那条线，不是 180.0°）",
                  MathF.Abs(SelRotationPose - 0f) < 0.01f,
                  $"读数 {SelRotationPose:F4}°");
            Check("姿态角·真机：**矩阵与标签是同一个角**（拿实时变换反推）",
                  SelectionHandles.InclinationDistance(SelRotationPose, LivePose(poseRect)) < 0.01f
                  && SelectionHandles.InclinationDistance(LivePose(poseRect), 0f) < 0.01f,
                  $"标签 {SelRotationPose:F4}°，实时矩阵反推 {LivePose(poseRect):F4}°");
            EndSelectionGestureForTest();
            SettleFrames(220);
            Check("姿态角·真机：松手真的落到水平（对象姿态 ≈ 0°，一步撤销）",
                  SelectionHandles.InclinationDistance(
                      SelectionHandles.PoseAngleDegrees(poseRect.Transform), 0f) < 0.05f,
                  $"落定姿态 {SelectionHandles.PoseAngleDegrees(poseRect.Transform):F3}°，撤销栈 {Doc.UndoDepth} 步");
            Doc.Undo();
            SettleFrames(150);

            // ---- 真机②：一个**转过 52° 的椭圆**拖旋转柄 → 吸到 90°（竖的）----
            // 这正是用户提这个需求的初衷：识别出来的椭圆是歪的，想把它"转正"。
            Doc.Clear();
            Doc.ClearHistory();
            var poseEll = new Stroke
            {
                Tool = Tool.Ellipse, Kind = StrokeKind.Ellipse,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
            };
            var ellCenter = new Vector2(lx + 300f, ly);
            poseEll.AddPoint(ellCenter.X, ellCenter.Y, 1f, 0);          // 中心
            poseEll.AddPoint(ellCenter.X + 320f, ellCenter.Y + 140f, 1f, 0);   // 外角点（a=320, b=140）
            poseEll.Transform = SelectionHandles.RotateMatrix(52f, ellCenter);
            Doc.AddStroke(poseEll);
            Doc.SelectOnly(new[] { poseEll });
            SettleFrames(300);
            Check("姿态角·真机：歪椭圆一开始的姿态 ≈ 52.0°",
                  MathF.Abs(SelectionHandles.PoseAngleDegrees(poseEll.Transform) - 52f) < 0.05f,
                  $"姿态 {SelectionHandles.PoseAngleDegrees(poseEll.Transform):F3}°");
            GrabRotate(38.4f, out bool tookEll);      // 屏幕上逆时针 38.4°：52 → 90.4（±1° 内 → 吸到 90）
            Check("姿态角·真机：歪椭圆拖到 90° 附近吸住（竖的）",
                  tookEll && SelRotating && SelRotationReadsPose && SelRotationSnapped
                  && MathF.Abs(SelRotationPose - 90f) < 0.01f,
                  $"读数 {SelRotationPose:F4}°，吸住={SelRotationSnapped}");
            EndSelectionGestureForTest();
            SettleFrames(220);
            Check("姿态角·真机：松手后椭圆真的竖起来了（姿态 ≈ 90°）",
                  SelectionHandles.InclinationDistance(
                      SelectionHandles.PoseAngleDegrees(poseEll.Transform), 90f) < 0.05f,
                  $"落定姿态 {SelectionHandles.PoseAngleDegrees(poseEll.Transform):F3}°");
            Doc.Undo();
            SettleFrames(150);

            // ---- 镜像过的图形：读数仍然以**眼睛看到的**为准（和矩阵同一个角）----
            Doc.Clear();
            Doc.ClearHistory();
            var mirRect = new Stroke
            {
                Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
            };
            mirRect.AddPoint(lx, ly, 1f, 0);
            mirRect.AddPoint(lx + 500f, ly - 300f, 1f, 0);
            Doc.AddStroke(mirRect);
            Doc.SelectOnly(new[] { mirRect });
            SettleFrames(200);
            Doc.ApplyTransform(SelectionHandles.MirrorMatrix(mirRect.WorldInkBounds, horizontal: true));
            SettleFrames(250);
            bool mirrored = SelectionHandles.IsMirrored(mirRect.Transform);
            // 镜像过的图形"本地转 +1°"在屏幕上是 -1°：要转到 90° 得**顺时针**拖 90.4°
            // （这正是引擎里那个 sgn 符号存在的理由，自检把这条走一遍）。
            GrabRotate(-90.4f, out bool tookMir);
            Check("姿态角·真机：镜像过的图形也能吸（0/90 那一档照样生效）",
                  tookMir && mirrored && SelRotating && SelRotationReadsPose && SelRotationSnapped
                  && SelectionHandles.InclinationDistance(SelRotationPose, 90f) < 0.01f,
                  $"镜像={mirrored}，吸住={SelRotationSnapped}，读数 {SelRotationPose:F3}°");
            Check("姿态角·真机：镜像 + 拖过 → 标签与实时矩阵**仍是同一个角**",
                  SelectionHandles.InclinationDistance(SelRotationPose, LivePose(mirRect)) < 0.01f,
                  $"标签 {SelRotationPose:F4}°，实时矩阵反推 {LivePose(mirRect):F4}°");
            EndSelectionGestureForTest();
            SettleFrames(150);

            // ---- 直线仍然读 α（不是姿态角）；圆连姿态角这一档都进不去 ----
            var sl = new Stroke
            {
                Tool = Tool.Line, Kind = StrokeKind.Line,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
            };
            sl.AddPoint(lx, ly, 1f, 0);
            sl.AddPoint(lx + 600f, ly - 218f, 1f, 0);        // α ≈ 19.96°
            Doc.Clear();
            Doc.ClearHistory();
            Doc.AddStroke(sl);
            Doc.SelectOnly(new[] { sl });
            SettleFrames(300);
            GrabRotate(10.4f, out bool tookLine);
            Check("直线：仍然读倾斜角 α（不读姿态角）",
                  tookLine && SelRotating && SelRotationReadsInclination && !SelRotationReadsPose
                  && MathF.Abs(SelRotationInclination - 30f) < 0.2f,
                  $"读α={SelRotationReadsInclination}，读姿态={SelRotationReadsPose}，"
                  + $"读数 {SelRotationInclination:F2}°（α₀≈19.96 + 10.4 → 吸到 30）");
            EndSelectionGestureForTest();
            SettleFrames(150);

            var circ = new Stroke
            {
                Tool = Tool.Circle, Kind = StrokeKind.Circle,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
            };
            circ.AddPoint(lx + 200f, ly, 1f, 0);
            circ.AddPoint(lx + 420f, ly, 1f, 0);            // 半径 220
            Doc.Clear();
            Doc.ClearHistory();
            Doc.AddStroke(circ);
            Doc.SelectOnly(new[] { circ });
            SettleFrames(250);
            var cFrame = SelectionHandles.FrameOf(Doc.Selected);
            var cGrip = SelectionHandles.CanvasPosition(SelHandle.Rotate, cFrame, DpiScale);
            bool circlePoseOk = !SelectionHandles.PoseEditable(Doc.Selected, out _)
                                && !SelectionHandles.RotateHandleVisible(circ)
                                && SelectionHandles.HitTest(cGrip.X, cGrip.Y, Doc.Selected, cFrame, DpiScale)
                                   != SelHandle.Rotate;
            bool circleCaught = SelectionGestureForTest(cGrip.X, cGrip.Y);
            bool circleRotating = SelRotating;
            EndSelectionGestureForTest();
            SettleFrames(120);
            Check("圆：没有姿态角读数（连旋转柄都不给，那个位置按下去也接不住旋转）",
                  circlePoseOk && !circleRotating,
                  $"PoseEditable={SelectionHandles.PoseEditable(Doc.Selected, out _)}，"
                  + $"旋转柄可见={SelectionHandles.RotateHandleVisible(circ)}，"
                  + $"在那个位置按下接住旋转={circleCaught && circleRotating}");
            SettleFrames(120);

            // ---- 图像 / 笔迹 / 多选：仍然读转过的 Δ，而且**通用旋转的 ±3° 口径一个字没改** ----
            Doc.Clear();
            Doc.ClearHistory();
            var scribble = new Stroke
            {
                Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 12f * DpiScale,
            };
            for (int i = 0; i <= 40; i++)
                scribble.AddPoint(lx + i * 12f, ly + MathF.Sin(i * 0.3f) * 60f, 0.9f, i * 8);
            Doc.AddStroke(scribble);
            Doc.SelectOnly(new[] { scribble });
            SettleFrames(250);
            GrabRotate(24.5f, out bool tookFree);
            Check("笔迹：旋转读数仍然是 Δ（不是姿态角）",
                  tookFree && SelRotating && !SelRotationReadsPose && !SelRotationReadsInclination
                  && Math.Abs(SelRotationDegrees - 24.5f) < 1.5f,
                  $"读姿态={SelRotationReadsPose}，缺口 {SelRotationDegrees:F2}°");
            EndSelectionGestureForTest();
            SettleFrames(150);

            Doc.Clear();
            Doc.ClearHistory();
            var pic = Doc.AddImage(MakeTestImage(300, 200), lx, ly - 100f, 1f);
            Doc.SelectOnly(new[] { pic });
            SettleFrames(250);
            GrabRotate(24.5f, out bool tookImg);
            Check("图像：旋转读数仍然是 Δ（不是姿态角）",
                  tookImg && SelRotating && !SelRotationReadsPose && !SelRotationReadsInclination
                  && Math.Abs(SelRotationDegrees - 24.5f) < 1.5f,
                  $"读姿态={SelRotationReadsPose}，读数 {SelRotationDegrees:F2}°"
                  + $"（PoseEditable={SelectionHandles.PoseEditable(Doc.Selected, out _)}）");
            EndSelectionGestureForTest();
            SettleFrames(150);

            // 多选两个**图形**（都是"会读姿态角"的种类）：单选才读姿态，多选一律退回 Δ。
            Doc.Clear();
            Doc.ClearHistory();
            var mr1 = new Stroke { Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
                                   Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale };
            mr1.AddPoint(lx, ly, 1f, 0);
            mr1.AddPoint(lx + 300f, ly - 200f, 1f, 0);
            var mr2 = new Stroke { Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
                                   Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale };
            mr2.AddPoint(lx + 400f, ly, 1f, 0);
            mr2.AddPoint(lx + 700f, ly - 200f, 1f, 0);
            Doc.AddStroke(mr1);
            Doc.AddStroke(mr2);
            Doc.SelectOnly(new[] { mr1, mr2 });
            SettleFrames(300);
            GrabRotate(24.5f, out bool tookTwoShapes);
            Check("多选两个矩形：读数退回 Δ（姿态角只认单选）",
                  tookTwoShapes && SelRotating && !SelRotationReadsPose && !SelRotationReadsInclination
                  && Math.Abs(SelRotationDegrees - 24.5f) < 1.5f,
                  $"读姿态={SelRotationReadsPose}，读数 {SelRotationDegrees:F2}°");
            EndSelectionGestureForTest();
            SettleFrames(150);

            // 通用旋转那一档的容差**必须一个字没改**：±3°，且只吸 90° 的整数倍。
            Check("通用旋转：92° 吸到 90°（±3° 内，保持现在的行为）",
                  MathF.Abs(SelectionHandles.SnapRotationDegrees(92f, false, false, out bool g1) - 90f) < 0.01f
                  && g1, "92° → 90°");
            Check("通用旋转：94° **不吸**（±3° 外，口径没被这一轮改窄）",
                  MathF.Abs(SelectionHandles.SnapRotationDegrees(94f, false, false, out bool g2) - 94f) < 0.01f
                  && !g2, $"94° → 留自由（容差常量 = {SelectionHandles.RotationSoftSnapToleranceDegrees}）");
            Check("通用旋转：45° 不吸（它只吸 90° 的整数倍，不是直线的八个特殊角）",
                  MathF.Abs(SelectionHandles.SnapRotationDegrees(45f, false, false, out bool g3) - 45f) < 0.01f
                  && !g3, "45° → 留自由");
        }

        // ================= H. 直线/箭头的选中框：紧框（端点口径）=================
        //
        // 旧口径 `TransformRect(InkBounds, Transform)` = "先取局部 AABB、整体转过去、
        // 再取外接矩形"。直线的局部 AABB 四个角**根本不在线上**，所以一转就虚胖
        // （2026-09-18 实测：转过 31.5° 的直线框 962×838，线自己只有 490×837）。
        // 新口径 = 端点（箭头还要加两个翅膀尖）过变换后取外接，再外扩半笔宽。
        //
        // 这里的"旧口径"是**自检自己现算一遍**的（不调被测实现）——判据才有意义。
        Console.WriteLine("  -- H. 直线/箭头选中框：紧框（端点口径）--");
        {
            RectF CornersBox(in RectF r, in Matrix3x2 m)
            {
                var box = RectF.Empty;
                foreach (var c in new[]
                {
                    new Vector2(r.MinX, r.MinY), new Vector2(r.MaxX, r.MinY),
                    new Vector2(r.MaxX, r.MaxY), new Vector2(r.MinX, r.MaxY),
                })
                {
                    var q = Vector2.Transform(c, m);
                    box.Add(q.X, q.Y);
                }
                return box;
            }
            RectF LocalInkBox(Stroke s2)
            {
                var r = RectF.Empty;
                float hw = s2.Width * 0.5f;
                foreach (var p in s2.Points) { r.Add(p.X - hw, p.Y - hw); r.Add(p.X + hw, p.Y + hw); }
                return r;
            }
            string Size(in RectF r) => $"{r.MaxX - r.MinX:F0}×{r.MaxY - r.MinY:F0}";
            bool Same(in RectF a, in RectF b, float tol = 0.01f)
                => MathF.Abs(a.MinX - b.MinX) < tol && MathF.Abs(a.MinY - b.MinY) < tol
                && MathF.Abs(a.MaxX - b.MaxX) < tol && MathF.Abs(a.MaxY - b.MaxY) < tol;

            // ---- 一条 **45° 斜线**，四个姿态：0°（没转过）/ 30° / 60° / 90° ----
            //
            // 为什么用斜线而不是水平线：虚胖的幅度取决于"局部 AABB 的长短边之比 + 转了多大"。
            // 一条水平长线（900×16）转 30° 时旧口径只胖 6 像素——判据会"看着过了但其实没验到"。
            // 斜线的局部框是 608×608，一转就是 830×830 这种，虚胖一眼可见。
            // 注：**不可能**要求四个姿态"都比旧口径小一大截"——90° 这种角度旧口径本来就接近
            // （正方形框转 90° 还是它自己），所以硬判据是"≈ 按定义现算的端点外接"，
            // 旧口径的值打印出来作对照，另有一条专门判"明显小"（45° 斜线转 30° 那一档）。
            var slant = new Func<Stroke>(() =>
            {
                var s2 = new Stroke
                {
                    Tool = Tool.Line, Kind = StrokeKind.Line,
                    Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
                };
                s2.AddPoint(lx, ly, 1f, 0);
                s2.AddPoint(lx + 600f, ly - 600f, 1f, 0);      // 45° 斜线
                return s2;
            });
            foreach (float deg in new[] { 0f, 30f, 60f, 90f })
            {
                var s2 = slant();
                if (deg != 0f)
                    s2.Transform = SelectionHandles.RotateMatrix(deg, new Vector2(lx + 300f, ly - 300f));

                var oldBox = CornersBox(LocalInkBox(s2), s2.Transform);   // 旧口径（自检自己算）
                var got = s2.WorldInkBounds;
                var e0 = SelectionHandles.EndpointCanvasPosition(s2, 0);
                var e1 = SelectionHandles.EndpointCanvasPosition(s2, 1);
                var want = RectF.Empty;
                want.Add(e0.X, e0.Y);
                want.Add(e1.X, e1.Y);
                want = want.Inflate(s2.Width * 0.5f);

                if (deg == 0f)
                {
                    // 没转过：新口径与旧口径**一字不差**（这条是"不改坏"的保险）
                    Check("没转过的直线：框值与旧口径一字不差", Same(got, oldBox),
                          $"新 {Size(got)} / 旧 {Size(oldBox)}");
                }
                else
                {
                    Check($"转 {deg:F0}° 的斜线：框 ≈ 端点外接 + 半笔宽（≤1 像素）",
                          Same(got, want, 1f),
                          $"框 {Size(got)}，按定义现算 {Size(want)}"
                          + $"（旧口径 {Size(oldBox)} 作对照）");
                }
            }
            {
                // 专门判"明显小"：45° 斜线转 30° —— 旧口径约 830×830，新口径约 230×830
                var s2 = slant();
                s2.Transform = SelectionHandles.RotateMatrix(30f, new Vector2(lx + 300f, ly - 300f));
                var oldBox = CornersBox(LocalInkBox(s2), s2.Transform);
                var got = s2.WorldInkBounds;
                Check("转 30° 的斜线：框比旧口径小了 500 像素以上（虚胖被去掉）",
                      (got.MaxX - got.MinX) < (oldBox.MaxX - oldBox.MinX) - 500f,
                      $"新 {Size(got)} ／ 旧 {Size(oldBox)}");
            }

            // ---- 上一轮那个现场那组数（同一条线、同一个角）----
            {
                var s2 = new Stroke
                {
                    Tool = Tool.Line, Kind = StrokeKind.Line,
                    Color = new Color4(0.11f, 0.12f, 0.15f, 1f), Width = 6f,
                };
                s2.AddPoint(1020f, 1120f, 1f, 0);
                s2.AddPoint(1860f, 680f, 1f, 0);
                var center2 = new Vector2(1440f, 900f);
                s2.Transform = SelectionHandles.RotateMatrix(31.5f, center2);   // → α ≈ 59.15°
                var oldBox = CornersBox(LocalInkBox(s2), s2.Transform);
                var got = s2.WorldInkBounds;
                var e0 = SelectionHandles.EndpointCanvasPosition(s2, 0);
                var e1 = SelectionHandles.EndpointCanvasPosition(s2, 1);
                var want = RectF.Empty;
                want.Add(e0.X, e0.Y);
                want.Add(e1.X, e1.Y);
                want = want.Inflate(s2.Width * 0.5f);
                Check("上一轮那个现场（转 31.5° 的直线）：框从 962×838 收到 ≈ 490×838",
                      Same(got, want, 1f) && (got.MaxX - got.MinX) < 550f,
                      $"新 {Size(got)} ／ 旧 {Size(oldBox)}（上一轮实测：962×838 vs 线自己 490×837）");
                // 导出 / 剪贴板给外部那张图的裁切范围就是 PaddedBounds —— 它跟着这条口径一起收紧
                var pb = s2.PaddedBounds;
                var pbOld = CornersBox(LocalInkBox(s2), s2.Transform).Inflate(s2.Width * 0.5f + 2f);
                Check("导出/剪贴板的裁切范围（PaddedBounds）也跟着收紧",
                      (pb.MaxX - pb.MinX) < 550f,
                      $"新 {Size(pb)} ／ 旧 {Size(pbOld)}");
            }

            // ---- 箭头：框必须包住头部的两个翅膀尖（它们不在两端之间）----
            {
                var ar = new Stroke
                {
                    Tool = Tool.Arrow, Kind = StrokeKind.Arrow,
                    Color = new Color4(1f, 0f, 1f, 1f), Width = 6f * DpiScale,
                };
                ar.AddPoint(lx, ly, 1f, 0);
                ar.AddPoint(lx + 900f, ly, 1f, 0);
                ar.Transform = SelectionHandles.RotateMatrix(45f, new Vector2(lx + 450f, ly));
                var ea = SelectionHandles.EndpointCanvasPosition(ar, 0);
                var eb = SelectionHandles.EndpointCanvasPosition(ar, 1);
                // 头部几何按"渲染那一份的公式"独立复算：head = clamp(len*0.28,10,48)、spread = head*0.45
                float dx = eb.X - ea.X, dy = eb.Y - ea.Y;
                float len = MathF.Sqrt(dx * dx + dy * dy);
                dx /= len; dy /= len;
                float head = Math.Clamp(len * 0.28f, 10f, 48f);
                var root = new Vector2(eb.X - dx * head, eb.Y - dy * head);
                var nrm = new Vector2(-dy, dx);
                float spread = head * 0.45f;
                var want = RectF.Empty;
                foreach (var p in new[] { ea, eb, root + nrm * spread, root - nrm * spread })
                    want.Add(p.X, p.Y);
                want = want.Inflate(ar.Width * 0.5f);
                var got = ar.WorldInkBounds;
                Check("转 45° 的箭头：框包住两端点 + 两个翅膀尖（≤1 像素）",
                      Same(got, want, 1f), $"框 {Size(got)}，含翅膀现算 {Size(want)}");
            }

            // ---- 不变的：矩形 / 图像（各转 30°）----
            // 注：**椭圆不在这一组**了——2026-09-19 起它和圆一样走"参数化紧框"
            // （见下面 J 段：椭圆局部是参数曲线，把它的外框矩形转过去再取外接会虚胖）。
            foreach (var (tool, kind, tag) in new[]
            {
                (Tool.Rectangle, StrokeKind.Rectangle, "矩形"),
            })
            {
                var s2 = new Stroke
                {
                    Tool = tool, Kind = kind,
                    Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
                };
                s2.AddPoint(lx, ly, 1f, 0);
                s2.AddPoint(lx + 600f, ly - 400f, 1f, 0);
                s2.Transform = SelectionHandles.RotateMatrix(30f, new Vector2(lx + 300f, ly - 200f));
                var oldBox = CornersBox(LocalInkBox(s2), s2.Transform);
                Check($"{tag}（转过 30°）：框值与旧口径一字不差",
                      Same(s2.WorldInkBounds, oldBox),
                      $"新 {Size(s2.WorldInkBounds)} / 旧 {Size(oldBox)}");
            }
            var img = Doc.AddImage(MakeTestImage(400, 300), lx, ly, 1f / DpiScale);
            img.Transform = SelectionHandles.RotateMatrix(30f,
                new Vector2(lx + 200f, ly + 150f));
            var imgOld = CornersBox(LocalInkBox(img), img.Transform);
            Check("图像（转过 30°）：框值与旧口径一字不差",
                  Same(img.WorldInkBounds, imgOld),
                  $"新 {Size(img.WorldInkBounds)} / 旧 {Size(imgOld)}");
            Doc.RemoveStroke(img);
        }

        // ================= I. 圆：画法 / 手柄 / 紧框 / 命中 =================
        //
        // 规格是 计划-图形工具.md 9.2：存"圆心 + 圆周点"、按下=圆心拖=半径、
        // 手柄只有圆心（平移）与圆周点（改半径）、**不给旋转柄**、紧框 = 圆心 ± r。
        Console.WriteLine("  -- I. 圆 --");
        {
            bool Near(float a, float b, float tol) => MathF.Abs(a - b) <= tol;

            // ---- 画一个圆（真机：按下拖出半径）----
            Doc.Clear();
            Doc.ClearHistory();
            SetToolFromUi(Tool.Circle);
            float ccx = _virtualX + 800, ccy = _virtualY + 800;
            float cRadius = 180f;                      // 物理像素：拖这么远就是半径
            SendMouse((int)ccx, (int)ccy, 0);                            SettleFrames(60);
            SendMouse((int)ccx, (int)ccy, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
            for (int i = 1; i <= 4; i++)
            {
                SendMouse((int)(ccx + cRadius * i / 4f), (int)ccy, 0);
                SettleFrames(30);
            }
            SendMouse((int)(ccx + cRadius), (int)ccy, Native.MOUSEEVENTF_LEFTUP); SettleFrames(220);

            var circle = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
            Check("圆：拖出一个圆对象", circle != null && circle.Kind == StrokeKind.Circle,
                  circle == null ? "没有对象" : $"Kind={circle.Kind}");
            if (circle != null)
            {
                Check("圆：圆心 = 按下的点（±1 像素）",
                      Near(circle.ShapeCenterLocal.X, ccx, 1f) && Near(circle.ShapeCenterLocal.Y, ccy, 1f),
                      $"圆心 ({circle.ShapeCenterLocal.X:F1},{circle.ShapeCenterLocal.Y:F1})"
                      + $" 期望 ({ccx:F0},{ccy:F0})");
                Check("圆：半径 = 拖动的距离（±1 像素）",
                      Near(circle.CircleRadiusLocal, cRadius, 1f),
                      $"半径 {circle.CircleRadiusLocal:F1} 期望 {cRadius:F0}");
                Check("圆：一次拖拽 = 一步撤销", Doc.UndoDepth == 1, $"撤销栈 {Doc.UndoDepth} 步");
                Doc.Undo();
                SettleFrames(120);
                Check("圆：撤销一次就干净", Doc.Strokes.Count == 0, $"对象 {Doc.Strokes.Count} 个");
            }

            // ---- 造一个已知的圆，验手柄 / 紧框 / 命中 ----
            Doc.Clear();
            Doc.ClearHistory();
            Tool = Tool.Marquee;
            var c2 = new Stroke
            {
                Tool = Tool.Circle, Kind = StrokeKind.Circle,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
            };
            c2.AddPoint(ccx, ccy, 1f, 0);            // 圆心
            c2.AddPoint(ccx + 240f, ccy, 1f, 0);     // 圆周点（半径 240）
            Doc.AddStroke(c2);
            Doc.SelectOnly(new[] { c2 });
            SettleFrames(250);

            // 紧框 = 圆心 ± r（＋半笔宽）
            var wantCircle = new RectF
            {
                MinX = ccx - 240f - c2.Width * 0.5f, MinY = ccy - 240f - c2.Width * 0.5f,
                MaxX = ccx + 240f + c2.Width * 0.5f, MaxY = ccy + 240f + c2.Width * 0.5f,
            };
            var gotCircle = c2.WorldInkBounds;
            Check("圆：紧框 = 圆心 ± r（＋半笔宽，±1 像素）",
                  MathF.Abs(gotCircle.MinX - wantCircle.MinX) < 1f
                  && MathF.Abs(gotCircle.MinY - wantCircle.MinY) < 1f
                  && MathF.Abs(gotCircle.MaxX - wantCircle.MaxX) < 1f
                  && MathF.Abs(gotCircle.MaxY - wantCircle.MaxY) < 1f,
                  $"框 {gotCircle.MaxX - gotCircle.MinX:F0}×{gotCircle.MaxY - gotCircle.MinY:F0}"
                  + $"（直径 480 + 笔宽 {c2.Width:F0}）");

            // 命中：圆周上算命中、**圆心处不算**（只认描边，不认内部）
            Check("圆：圆周上命中、圆心处不命中（只认描边）",
                  c2.HitTestExact(ccx + 240f, ccy) && !c2.HitTestExact(ccx, ccy),
                  $"圈上 {c2.HitTestExact(ccx + 240f, ccy)}，圆心 {c2.HitTestExact(ccx, ccy)}");

            // 手柄：两个（圆心 + 圆周点）、**没有旋转柄**
            Span<ShapeHandle> cHandles = stackalloc ShapeHandle[5];
            int cn = SelectionHandles.ShapeHandlesOf(c2, cHandles);
            Check("圆：手柄是两个（圆心 + 圆周点）",
                  cn == 2 && cHandles[0] == ShapeHandle.Anchor && cHandles[1] == ShapeHandle.Rim,
                  $"手柄数 {cn}");
            // 旋转柄的位置上按一下：**必须是 None**（圆的旋转柄连命中都不做）
            var cFrame = SelectionHandles.FrameOf(Doc.Selected);
            var cRotGrip = SelectionHandles.CanvasPosition(SelHandle.Rotate, cFrame, DpiScale);
            var circleRotateHit = SelectionHandles.HitTest(cRotGrip.X, cRotGrip.Y, Doc.Selected, cFrame, DpiScale);
            Check("圆：不给旋转柄（画也不画、点也点不到）",
                  !SelectionHandles.RotateHandleVisible(c2) && circleRotateHit == SelHandle.None,
                  $"可见={SelectionHandles.RotateHandleVisible(c2)}，命中={circleRotateHit}");

            // ---- 拖圆心 = 平移（半径逐位不变；几何一个点都不动）----
            float rBefore = c2.CircleRadiusLocal;
            // 圆心位移在**画布坐标**上比：几何点（局部坐标）本来就不动，动的是变换矩阵。
            var cx0 = SelectionHandles.ShapeHandleCanvasPosition(c2, ShapeHandle.Anchor);
            string ptsBefore = $"{c2.Points[0].X},{c2.Points[0].Y}|{c2.Points[1].X},{c2.Points[1].Y}";
            bool tookCenter = SelectionGestureForTest(cx0.X, cx0.Y);
            UpdateSelectionGestureForTest(cx0.X + 300f, cx0.Y + 150f);
            SettleFrames(80);
            bool geomUntouched = ptsBefore == $"{c2.Points[0].X},{c2.Points[0].Y}|{c2.Points[1].X},{c2.Points[1].Y}";
            Check("圆：拖圆心 = 整体平移（走的是变换，几何一个点不动）",
                  tookCenter && geomUntouched,
                  $"接住={tookCenter}，几何原样={geomUntouched}（若走改几何这条路这里就会变）");
            EndSelectionGestureForTest();
            SettleFrames(180);
            var cx1 = SelectionHandles.ShapeHandleCanvasPosition(c2, ShapeHandle.Anchor);
            Check("圆：平移后半径逐位不变、圆心在画布上正好挪了 (300,150)",
                  c2.CircleRadiusLocal == rBefore
                  && Near(cx1.X - cx0.X, 300f, 1f) && Near(cx1.Y - cx0.Y, 150f, 1f),
                  $"半径 {rBefore:F3} → {c2.CircleRadiusLocal:F3}，"
                  + $"圆心画布位移 ({cx1.X - cx0.X:F1},{cx1.Y - cx0.Y:F1})");

            // ---- 拖圆周点 = 只改半径（圆心逐位不变）----
            Doc.Undo();   // 把平移撤掉，回到干净的圆
            SettleFrames(150);
            int cRevBefore = c2.Revision;
            var rimPoint = SelectionHandles.ShapeHandleCanvasPosition(c2, ShapeHandle.Rim);
            // 圆心在局部坐标里的值（拖圆周点不该动它）；下一段那个"圆心逐位不变"要拿它比。
            float cxBefore = c2.Points[0].X;
            float cyBefore = c2.Points[0].Y;
            bool tookRim = SelectionGestureForTest(rimPoint.X, rimPoint.Y);
            UpdateSelectionGestureForTest(rimPoint.X + 120f, rimPoint.Y);
            SettleFrames(80);
            Check("圆：拖圆周点时模型没动（Revision 不变、快路）",
                  c2.Revision == cRevBefore && VertexDragging,
                  $"Revision {cRevBefore} → {c2.Revision}，拖元素中={VertexDragging}");
            Check("圆：拖动中内容层一帧都不重画", _windows[0].LastPatchCount == 0,
                  $"上一帧光栅化分块 {_windows[0].LastPatchCount} 块");
            Check("圆：读数给的是 r 和 d = 2r",
                  VertexReadout == VertexReadoutKind.Radius
                  && Near(VertexReadoutSecondary, VertexReadoutValue * 2f, 0.01f),
                  $"读数 r={VertexReadoutValue:F1} d={VertexReadoutSecondary:F1}");
            EndSelectionGestureForTest();
            SettleFrames(200);
            Check("圆：拖圆周点 = 只改半径（圆心逐位不变）",
                  c2.Points[0].X == cxBefore && c2.Points[0].Y == cyBefore
                  && Near(c2.CircleRadiusLocal, 360f, 1.5f) && c2.Revision > cRevBefore,
                  $"圆心 ({c2.Points[0].X:F1},{c2.Points[0].Y:F1})，半径 {c2.CircleRadiusLocal:F1}（期望 ≈360）");
            Doc.Undo();
            SettleFrames(150);
        }

        // ================= J. 椭圆：画法变更 / 四个轴端点 / 紧框公式 =================
        //
        // 规格是 9.3：存"中心 + 外角点"、**按下=中心拖=同时定两条半轴**（2026-09-19 改，
        // 以前是"拖外框对角"）、手柄 = 中心 + 四个轴端点 + 旋转柄（**不给四个角**）、
        // 紧框 = 旋转后的参数化外接、a/b 各有最小值。
        Console.WriteLine("  -- J. 椭圆 --");
        {
            bool Near(float a, float b, float tol) => MathF.Abs(a - b) <= tol;

            // ---- 画一个椭圆（真机：按下=中心，横纵一起定半轴）----
            Doc.Clear();
            Doc.ClearHistory();
            SetToolFromUi(Tool.Ellipse);
            float ecx = _virtualX + 800, ecy = _virtualY + 700;
            float wa = 220f, wb = 140f;
            SendMouse((int)ecx, (int)ecy, 0);                            SettleFrames(60);
            SendMouse((int)ecx, (int)ecy, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
            for (int i = 1; i <= 4; i++)
            {
                SendMouse((int)(ecx + wa * i / 4f), (int)(ecy + wb * i / 4f), 0);
                SettleFrames(30);
            }
            SendMouse((int)(ecx + wa), (int)(ecy + wb), Native.MOUSEEVENTF_LEFTUP); SettleFrames(220);

            var ell = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
            Check("椭圆：拖出一个椭圆对象", ell != null && ell.Kind == StrokeKind.Ellipse,
                  ell == null ? "没有对象" : $"Kind={ell.Kind}");
            if (ell != null)
            {
                Check("椭圆：中心 = 按下的点（±1 像素）",
                      Near(ell.ShapeCenterLocal.X, ecx, 1f) && Near(ell.ShapeCenterLocal.Y, ecy, 1f),
                      $"中心 ({ell.ShapeCenterLocal.X:F1},{ell.ShapeCenterLocal.Y:F1})"
                      + $" 期望 ({ecx:F0},{ecy:F0})");
                Check("椭圆：a / b = 拖动的横向 / 纵向距离（±1 像素）",
                      Near(ell.SemiAxisALocal, wa, 1f) && Near(ell.SemiAxisBLocal, wb, 1f),
                      $"a={ell.SemiAxisALocal:F1} b={ell.SemiAxisBLocal:F1} 期望 {wa:F0}/{wb:F0}");
                Check("椭圆：一次拖拽 = 一步撤销", Doc.UndoDepth == 1, $"撤销栈 {Doc.UndoDepth} 步");
                Doc.Undo();
                SettleFrames(120);
            }

            // ---- 造一个已知的椭圆：手柄 / 只改一条半轴 / 最小值 / 紧框 ----
            Doc.Clear();
            Doc.ClearHistory();
            Tool = Tool.Marquee;
            var e2 = new Stroke
            {
                Tool = Tool.Ellipse, Kind = StrokeKind.Ellipse,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
            };
            e2.AddPoint(lx, ly, 1f, 0);              // 中心
            e2.AddPoint(lx + 240f, ly + 120f, 1f, 0); // 外角点 → a=240, b=120
            Doc.AddStroke(e2);
            Doc.SelectOnly(new[] { e2 });
            SettleFrames(250);

            Span<ShapeHandle> eHandles = stackalloc ShapeHandle[5];
            int en = SelectionHandles.ShapeHandlesOf(e2, eHandles);
            Check("椭圆：手柄是**两个**（右端点管 a、上端点管 b）",
                  en == 2 && eHandles[0] == ShapeHandle.AxisRight && eHandles[1] == ShapeHandle.AxisTop
                  && SelectionHandles.HandleOf(e2, SelHandle.EndpointB) == ShapeHandle.None,
                  $"手柄数 {en}，外角点手柄={SelectionHandles.HandleOf(e2, SelHandle.EndpointB)}");
            Check("椭圆：精简掉的三个（中心 + 左端点 + 下端点）**一个都不发**",
                  SelectionHandles.HandleOf(e2, SelHandle.Left) == ShapeHandle.None
                  && SelectionHandles.HandleOf(e2, SelHandle.Bottom) == ShapeHandle.None
                  && !SelectionHandles.IsAnchorMove(e2, ShapeHandle.Anchor),
                  $"左={SelectionHandles.HandleOf(e2, SelHandle.Left)}"
                  + $"，下={SelectionHandles.HandleOf(e2, SelHandle.Bottom)}"
                  + $"，中心算平移={SelectionHandles.IsAnchorMove(e2, ShapeHandle.Anchor)}");
            Check("椭圆：给旋转柄（和圆不同）", SelectionHandles.RotateHandleVisible(e2),
                  $"可见={SelectionHandles.RotateHandleVisible(e2)}");

            // 拖右轴端点：只改 a，b 逐位不变
            float bBefore = e2.SemiAxisBLocal;
            var rightPt = SelectionHandles.ShapeHandleCanvasPosition(e2, ShapeHandle.AxisRight);
            bool tookAxis = SelectionGestureForTest(rightPt.X, rightPt.Y);
            UpdateSelectionGestureForTest(rightPt.X + 160f, rightPt.Y);
            SettleFrames(80);
            Check("椭圆：拖轴端点时的读数是 a（不是 α）",
                  VertexReadout == VertexReadoutKind.AxisA,
                  $"读数类型={VertexReadout}，值 {VertexReadoutValue:F1}");
            EndSelectionGestureForTest();
            SettleFrames(200);
            Check("椭圆：拖右轴端点只改 a（b 逐位不变）",
                  tookAxis && Near(e2.SemiAxisALocal, 400f, 1.5f) && e2.SemiAxisBLocal == bBefore,
                  $"a={e2.SemiAxisALocal:F1}（期望 ≈400），b {bBefore:F3} → {e2.SemiAxisBLocal:F3}");
            Doc.Undo();
            SettleFrames(150);

            // 拖上轴端点：只改 b，a 逐位不变
            float aBefore = e2.SemiAxisALocal;
            var topPt = SelectionHandles.ShapeHandleCanvasPosition(e2, ShapeHandle.AxisTop);
            SelectionGestureForTest(topPt.X, topPt.Y);
            UpdateSelectionGestureForTest(topPt.X, topPt.Y - 90f);
            SettleFrames(80);
            Check("椭圆：拖上轴端点时的读数是 b",
                  VertexReadout == VertexReadoutKind.AxisB, $"读数类型={VertexReadout}");
            EndSelectionGestureForTest();
            SettleFrames(200);
            Check("椭圆：拖上轴端点只改 b（a 逐位不变）",
                  Near(e2.SemiAxisBLocal, 210f, 1.5f) && e2.SemiAxisALocal == aBefore,
                  $"b={e2.SemiAxisBLocal:F1}（期望 ≈210），a {aBefore:F3} → {e2.SemiAxisALocal:F3}");
            Doc.Undo();
            SettleFrames(150);

            // 最小值边界：把右轴端点一路拖过中心，a 不许小于 4 逻辑像素
            var rightPt2 = SelectionHandles.ShapeHandleCanvasPosition(e2, ShapeHandle.AxisRight);
            SelectionGestureForTest(rightPt2.X, rightPt2.Y);
            UpdateSelectionGestureForTest(lx - 500f, rightPt2.Y);   // 拖到中心左侧老远
            SettleFrames(80);
            EndSelectionGestureForTest();
            SettleFrames(200);
            Check("椭圆：a 有最小值（拖过中心也不许退化成线段）",
                  Near(e2.SemiAxisALocal, ShapeMinAxisLogical * DpiScale, 0.01f),
                  $"a={e2.SemiAxisALocal:F2} 期望 {ShapeMinAxisLogical * DpiScale:F2}"
                  + $"（{ShapeMinAxisLogical:F0} 逻辑像素 × dpi {DpiScale}）");
            Doc.Undo();
            SettleFrames(150);

            // ---- 旋转 30° 后的紧框 = 参数化外接公式 ----
            var eRot = new Stroke
            {
                Tool = Tool.Ellipse, Kind = StrokeKind.Ellipse,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
            };
            eRot.AddPoint(lx, ly, 1f, 0);
            eRot.AddPoint(lx + 240f, ly + 120f, 1f, 0);
            eRot.Transform = SelectionHandles.RotateMatrix(30f, new Vector2(lx, ly));
            float th = 30f * MathF.PI / 180f;
            float ha = 240f, hb = 120f;
            // 规格 9.3 给的公式（自检自己算，不调被测实现）
            float ex = MathF.Sqrt(MathF.Pow(ha * MathF.Cos(th), 2) + MathF.Pow(hb * MathF.Sin(th), 2));
            float ey = MathF.Sqrt(MathF.Pow(ha * MathF.Sin(th), 2) + MathF.Pow(hb * MathF.Cos(th), 2));
            var gotE = eRot.WorldInkBounds;
            Check("椭圆：转过 30° 的紧框 = √((a·cosθ)²+(b·sinθ)²) 那两条公式（±1 像素）",
                  Near(gotE.MaxX - gotE.MinX, 2f * ex + eRot.Width, 1f)
                  && Near(gotE.MaxY - gotE.MinY, 2f * ey + eRot.Width, 1f),
                  $"框 {gotE.MaxX - gotE.MinX:F1}×{gotE.MaxY - gotE.MinY:F1}"
                  + $"，公式算 {2f * ex + eRot.Width:F1}×{2f * ey + eRot.Width:F1}");

            // 拖中心 = 平移（a / b 逐位不变）
            Doc.AddStroke(eRot);
            Doc.SelectOnly(new[] { eRot });
            SettleFrames(200);
            float ea = eRot.SemiAxisALocal, eb = eRot.SemiAxisBLocal;
            // 位移要在**画布坐标**上比：这条椭圆转过 30°，局部位移和屏幕位移不是一个方向。
            var eCenterBefore = SelectionHandles.ShapeHandleCanvasPosition(eRot, ShapeHandle.Anchor);
            var eCenter = eCenterBefore;
            SelectionGestureForTest(eCenter.X, eCenter.Y);
            UpdateSelectionGestureForTest(eCenter.X + 200f, eCenter.Y - 120f);
            SettleFrames(80);
            EndSelectionGestureForTest();
            SettleFrames(200);
            var eCenterAfter = SelectionHandles.ShapeHandleCanvasPosition(eRot, ShapeHandle.Anchor);
            Check("椭圆：拖中心 = 平移（a / b 逐位不变，而且真的挪了）",
                  eRot.SemiAxisALocal == ea && eRot.SemiAxisBLocal == eb
                  && Near(eCenterAfter.X - eCenterBefore.X, 200f, 1f)
                  && Near(eCenterAfter.Y - eCenterBefore.Y, -120f, 1f),
                  $"a {ea:F3} → {eRot.SemiAxisALocal:F3}，b {eb:F3} → {eRot.SemiAxisBLocal:F3}，"
                  + $"中心画布位移 ({eCenterAfter.X - eCenterBefore.X:F1},"
                  + $"{eCenterAfter.Y - eCenterBefore.Y:F1})");
        }

        // ================= K. 三角形：画法 / 三个顶点手柄 / 紧框 / 命中 =================
        //
        // 规格 9.4：`Points` = 三个顶点（**上中 / 下左 / 下右**）、一按一拖出来的是
        // "底边水平、左右对称"的三角形、手柄 = 三个顶点 + 旋转柄、紧框 = 三顶点外接、
        // 命中只认边（和矩形 / 椭圆一致）。
        Console.WriteLine("  -- K. 三角形 --");
        {
            bool Near(float a, float b, float tol) => MathF.Abs(a - b) <= tol;

            // ---- 画一个三角形（真机：按下外框左上角 → 拖到右下角）----
            Doc.Clear();
            Doc.ClearHistory();
            SetToolFromUi(Tool.Triangle);
            float tax = _virtualX + 700, tay = _virtualY + 500;
            float tbx = tax + 400, tby = tay + 300;
            SendMouse((int)tax, (int)tay, 0);                            SettleFrames(60);
            SendMouse((int)tax, (int)tay, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
            for (int i = 1; i <= 4; i++)
            {
                SendMouse((int)(tax + (tbx - tax) * i / 4f), (int)(tay + (tby - tay) * i / 4f), 0);
                SettleFrames(30);
            }
            SendMouse((int)tbx, (int)tby, Native.MOUSEEVENTF_LEFTUP);    SettleFrames(220);

            var tri = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
            Check("三角形：拖出一个三角形对象", tri != null && tri.Kind == StrokeKind.Triangle,
                  tri == null ? "没有对象" : $"Kind={tri.Kind}");
            if (tri != null)
            {
                float mid = (tax + tbx) * 0.5f;
                Check("三角形：控制点是**三个**（顶点，不是外框对角）",
                      tri.Points.Count == 3, $"点数 {tri.Points.Count}");
                Check("三角形：三个顶点 = 上中 / 下左 / 下右（±1 像素）",
                      Near(Pt(tri.Points[0]).X, mid, 1f) && Near(Pt(tri.Points[0]).Y, tay, 1f)
                      && Near(Pt(tri.Points[1]).X, tax, 1f) && Near(Pt(tri.Points[1]).Y, tby, 1f)
                      && Near(Pt(tri.Points[2]).X, tbx, 1f) && Near(Pt(tri.Points[2]).Y, tby, 1f),
                      $"上中 ({Pt(tri.Points[0]).X:F1},{Pt(tri.Points[0]).Y:F1})"
                      + $" 下左 ({Pt(tri.Points[1]).X:F1},{Pt(tri.Points[1]).Y:F1})"
                      + $" 下右 ({Pt(tri.Points[2]).X:F1},{Pt(tri.Points[2]).Y:F1})"
                      + $" 期望 ({mid:F0},{tay:F0})/({tax:F0},{tby:F0})/({tbx:F0},{tby:F0})");
                Check("三角形：一次拖拽 = 一步撤销", Doc.UndoDepth == 1, $"撤销栈 {Doc.UndoDepth} 步");
                Doc.Undo();
                SettleFrames(120);
                Check("三角形：撤销一次就干净", Doc.Strokes.Count == 0, $"对象 {Doc.Strokes.Count} 个");
            }

            // ---- 造一个已知的三角形：手柄 / 紧框 / 命中 / 拖顶点 ----
            Doc.Clear();
            Doc.ClearHistory();
            Tool = Tool.Marquee;
            var t2 = new Stroke
            {
                Tool = Tool.Triangle, Kind = StrokeKind.Triangle,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
            };
            t2.AddPoint(lx + 300f, ly - 240f, 1f, 0);     // 上中
            t2.AddPoint(lx, ly, 1f, 0);                   // 下左
            t2.AddPoint(lx + 600f, ly, 1f, 0);            // 下右
            Doc.AddStroke(t2);
            Doc.SelectOnly(new[] { t2 });
            SettleFrames(250);

            Span<ShapeHandle> tHandles = stackalloc ShapeHandle[5];
            int tn = SelectionHandles.ShapeHandlesOf(t2, tHandles);
            Check("三角形：手柄是三个顶点（+ 旋转柄），没有八向缩放柄",
                  tn == 3 && tHandles[0] == ShapeHandle.Vertex0
                  && tHandles[1] == ShapeHandle.Vertex1 && tHandles[2] == ShapeHandle.Vertex2
                  && SelectionHandles.RotateHandleVisible(t2)
                  && SelectionHandles.HandleOf(t2, SelHandle.EndpointB) == ShapeHandle.None,
                  $"手柄数 {tn}，旋转柄={SelectionHandles.RotateHandleVisible(t2)}，"
                  + $"EndpointB→{SelectionHandles.HandleOf(t2, SelHandle.EndpointB)}");

            var tFrame = SelectionHandles.FrameOf(Doc.Selected);
            var tRot = SelectionHandles.CanvasPosition(SelHandle.Rotate, tFrame, DpiScale);
            Check("三角形：三个顶点都点得到、旋转柄也点得到",
                  SelectionHandles.HitTest(lx + 300f, ly - 240f, Doc.Selected, tFrame, DpiScale)
                      == SelHandle.VertexA
                  && SelectionHandles.HitTest(lx, ly, Doc.Selected, tFrame, DpiScale) == SelHandle.VertexB
                  && SelectionHandles.HitTest(lx + 600f, ly, Doc.Selected, tFrame, DpiScale)
                      == SelHandle.VertexC
                  && SelectionHandles.HitTest(tRot.X, tRot.Y, Doc.Selected, tFrame, DpiScale)
                      == SelHandle.Rotate,
                  "上中→VertexA，下左→VertexB，下右→VertexC");

            // 紧框 = 三个顶点的外接（＋半笔宽），**不是**"外框转过去再取外接"
            float hw = t2.Width * 0.5f;
            var wantTri = new RectF
            {
                MinX = lx - hw, MinY = ly - 240f - hw,
                MaxX = lx + 600f + hw, MaxY = ly + hw,
            };
            var gotTri = t2.WorldInkBounds;
            Check("三角形：紧框 = 三个顶点的外接（＋半笔宽，±0.5 像素）",
                  Near(gotTri.MinX, wantTri.MinX, 0.5f) && Near(gotTri.MinY, wantTri.MinY, 0.5f)
                  && Near(gotTri.MaxX, wantTri.MaxX, 0.5f) && Near(gotTri.MaxY, wantTri.MaxY, 0.5f),
                  $"框 ({gotTri.MinX:F1},{gotTri.MinY:F1})-({gotTri.MaxX:F1},{gotTri.MaxY:F1})"
                  + $" 期望 ({wantTri.MinX:F1},{wantTri.MinY:F1})-({wantTri.MaxX:F1},{wantTri.MaxY:F1})");

            // 命中：边上命中、**内部不命中**（只认描边，和矩形 / 椭圆一致）
            var edgeMid = new Vector2((lx + 300f + lx) * 0.5f, (ly - 240f + ly) * 0.5f);   // 左上那条边的中点
            var centroid = new Vector2((lx + 300f + lx + lx + 600f) / 3f,
                                       (ly - 240f + ly + ly) / 3f);
            Check("三角形：边上命中、内部不命中（只认描边）",
                  t2.HitTestExact(edgeMid.X, edgeMid.Y) && !t2.HitTestExact(centroid.X, centroid.Y),
                  $"边上 {t2.HitTestExact(edgeMid.X, edgeMid.Y)}，"
                  + $"重心 {t2.HitTestExact(centroid.X, centroid.Y)}");

            // ---- 拖一个顶点：只动它、走快路、一步撤销 ----
            var tApex = SelectionHandles.ShapeHandleCanvasPosition(t2, ShapeHandle.Vertex0);
            float p1x = t2.Points[1].X, p1y = t2.Points[1].Y;
            float p2x = t2.Points[2].X, p2y = t2.Points[2].Y;
            float p0x = t2.Points[0].X, p0y = t2.Points[0].Y;
            int tRev = t2.Revision, tUndo = Doc.UndoDepth;
            // 目标位置刻意挑成"离等腰 / 等边 / 直角都很远"：这一条只验拖动本身，
            // 吸附留给 M 段（两个行为混在一起，红了也不知道是谁的错）。
            var tApexTo = new Vector2(lx + 140f, ly - 620f);
            bool tookApex = SelectionGestureForTest(tApex.X, tApex.Y);
            UpdateSelectionGestureForTest(tApexTo.X, tApexTo.Y);
            SettleFrames(80);
            Check("三角形：拖顶点时模型没动（Revision 不变、走快路）",
                  t2.Revision == tRev && VertexDragging,
                  $"Revision {tRev} → {t2.Revision}，拖元素中={VertexDragging}");
            Check("三角形：拖动中内容层一帧都不重画", _windows[0].LastPatchCount == 0,
                  $"上一帧光栅化分块 {_windows[0].LastPatchCount} 块");
            Check("三角形：这一拖没吸（目标离三种约束都远）",
                  ShapeSnapKind == ShapeSnapKind.None, $"吸到={ShapeSnapKind}");
            EndSelectionGestureForTest();
            SettleFrames(200);
            Check("三角形：拖一个顶点只动它（另两个顶点**逐位**不变）",
                  tookApex
                  && t2.Points[1].X == p1x && t2.Points[1].Y == p1y
                  && t2.Points[2].X == p2x && t2.Points[2].Y == p2y
                  && Near(Pt(t2.Points[0]).X, tApexTo.X, 1f)
                  && Near(Pt(t2.Points[0]).Y, tApexTo.Y, 1f),
                  $"顶点0 ({Pt(t2.Points[0]).X:F1},{Pt(t2.Points[0]).Y:F1}) 期望 ({tApexTo.X:F0},{tApexTo.Y:F0})，"
                  + $"顶点1 ({t2.Points[1].X:F1},{t2.Points[1].Y:F1})，"
                  + $"顶点2 ({t2.Points[2].X:F1},{t2.Points[2].Y:F1})");
            Check("三角形：一次拖顶点 = 一步撤销",
                  Doc.UndoDepth == tUndo + 1, $"撤销栈 {tUndo} → {Doc.UndoDepth} 步");
            Doc.Undo();
            SettleFrames(150);
            Check("三角形：撤销把那个顶点放回原位（逐位）",
                  t2.Points[0].X == p0x && t2.Points[0].Y == p0y,
                  $"顶点0 ({t2.Points[0].X:F3},{t2.Points[0].Y:F3}) "
                  + $"期望 ({p0x:F3},{p0y:F3})");
        }

        // ================= L. 平行四边形：三个顶点 / 第四个现推 / 紧框 / 命中 =================
        //
        // 规格 9.5：`Points` = 三个顶点，**第四个 = 第2 + 第3 − 第1**（自动推导、不存）、
        // 一按一拖出来的是"底边水平、上边右移 1/4 宽"、手柄只有三个（第四个角不给）、
        // 紧框 = **四个顶点**的外接。
        Console.WriteLine("  -- L. 平行四边形 --");
        {
            bool Near(float a, float b, float tol) => MathF.Abs(a - b) <= tol;

            // ---- 画一个平行四边形（真机）----
            Doc.Clear();
            Doc.ClearHistory();
            SetToolFromUi(Tool.Parallelogram);
            float pax = _virtualX + 700, pay = _virtualY + 500;
            float pbx = pax + 400, pby = pay + 300;
            float pw = pbx - pax;
            SendMouse((int)pax, (int)pay, 0);                            SettleFrames(60);
            SendMouse((int)pax, (int)pay, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
            for (int i = 1; i <= 4; i++)
            {
                SendMouse((int)(pax + (pbx - pax) * i / 4f), (int)(pay + (pby - pay) * i / 4f), 0);
                SettleFrames(30);
            }
            SendMouse((int)pbx, (int)pby, Native.MOUSEEVENTF_LEFTUP);    SettleFrames(220);

            var par = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
            Check("平行四边形：拖出一个平行四边形对象",
                  par != null && par.Kind == StrokeKind.Parallelogram,
                  par == null ? "没有对象" : $"Kind={par.Kind}");
            if (par != null)
            {
                Check("平行四边形：控制点是**三个**（第四个不存）",
                      par.Points.Count == 3, $"点数 {par.Points.Count}");
                Check("平行四边形：三个顶点 = 底左 / 底右 / 顶左（上边右移 1/4 宽，±1 像素）",
                      Near(Pt(par.Points[0]).X, pax, 1f) && Near(Pt(par.Points[0]).Y, pby, 1f)
                      && Near(Pt(par.Points[1]).X, pbx - pw * 0.25f, 1f)
                      && Near(Pt(par.Points[1]).Y, pby, 1f)
                      && Near(Pt(par.Points[2]).X, pax + pw * 0.25f, 1f)
                      && Near(Pt(par.Points[2]).Y, pay, 1f),
                      $"底左 ({Pt(par.Points[0]).X:F1},{Pt(par.Points[0]).Y:F1})"
                      + $" 底右 ({Pt(par.Points[1]).X:F1},{Pt(par.Points[1]).Y:F1})"
                      + $" 顶左 ({Pt(par.Points[2]).X:F1},{Pt(par.Points[2]).Y:F1})"
                      + $" 期望 ({pax:F0},{pby:F0})/({pbx - pw * 0.25f:F0},{pby:F0})/({pax + pw * 0.25f:F0},{pay:F0})");
                // 第四个顶点：**两条路各算一遍**（公式 / 外框右上角），两条都得对上
                var f4 = par.ParallelogramFourthLocal();
                Check("平行四边形：第四点逐位 = 第2 + 第3 − 第1（并且正好是外框右上角）",
                      f4.X == par.Points[1].X + par.Points[2].X - par.Points[0].X
                      && f4.Y == par.Points[1].Y + par.Points[2].Y - par.Points[0].Y
                      && Near(f4.X, pbx, 1f) && Near(f4.Y, pay, 1f),
                      $"第四点 ({f4.X:F1},{f4.Y:F1})，外框右上角 ({pbx:F0},{pay:F0})");
                Check("平行四边形：一次拖拽 = 一步撤销", Doc.UndoDepth == 1, $"撤销栈 {Doc.UndoDepth} 步");
                Doc.Undo();
                SettleFrames(120);
                Check("平行四边形：撤销一次就干净", Doc.Strokes.Count == 0, $"对象 {Doc.Strokes.Count} 个");
            }

            // ---- 造一个已知的平行四边形：手柄 / 第四个角没有手柄 / 紧框 / 命中 ----
            Doc.Clear();
            Doc.ClearHistory();
            Tool = Tool.Marquee;
            var q2 = new Stroke
            {
                Tool = Tool.Parallelogram, Kind = StrokeKind.Parallelogram,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
            };
            q2.AddPoint(lx, ly, 1f, 0);                 // 底左
            q2.AddPoint(lx + 300f, ly, 1f, 0);          // 底右
            q2.AddPoint(lx + 75f, ly - 200f, 1f, 0);    // 顶左
            Doc.AddStroke(q2);
            Doc.SelectOnly(new[] { q2 });
            SettleFrames(250);

            Span<ShapeHandle> qHandles = stackalloc ShapeHandle[5];
            int qn = SelectionHandles.ShapeHandlesOf(q2, qHandles);
            var q4 = q2.ParallelogramFourthLocal();
            var qFrame = SelectionHandles.FrameOf(Doc.Selected);
            var qRot = SelectionHandles.CanvasPosition(SelHandle.Rotate, qFrame, DpiScale);
            Check("平行四边形：手柄只有三个（第四个角不给手柄，用户定）",
                  qn == 3 && qHandles[0] == ShapeHandle.Vertex0
                  && qHandles[1] == ShapeHandle.Vertex1 && qHandles[2] == ShapeHandle.Vertex2
                  && SelectionHandles.HitTest(q4.X, q4.Y, Doc.Selected, qFrame, DpiScale)
                      == SelHandle.None,
                  $"手柄数 {qn}，在第四点 ({q4.X:F0},{q4.Y:F0}) 上按一下 → "
                  + $"{SelectionHandles.HitTest(q4.X, q4.Y, Doc.Selected, qFrame, DpiScale)}（期望 None）");
            Check("平行四边形：给旋转柄", SelectionHandles.RotateHandleVisible(q2)
                  && SelectionHandles.HitTest(qRot.X, qRot.Y, Doc.Selected, qFrame, DpiScale)
                      == SelHandle.Rotate,
                  $"旋转柄={SelectionHandles.RotateHandleVisible(q2)}");

            // 紧框 = **四个顶点**的外接（＋半笔宽）：第四个点在右上，少了它框会小一截
            float qhw = q2.Width * 0.5f;
            var wantQ = new RectF
            {
                MinX = lx - qhw, MinY = ly - 200f - qhw,
                MaxX = lx + 375f + qhw, MaxY = ly + qhw,
            };
            var gotQ = q2.WorldInkBounds;
            Check("平行四边形：紧框 = **四个顶点**的外接（含推导出来的那个，±0.5 像素）",
                  Near(gotQ.MinX, wantQ.MinX, 0.5f) && Near(gotQ.MinY, wantQ.MinY, 0.5f)
                  && Near(gotQ.MaxX, wantQ.MaxX, 0.5f) && Near(gotQ.MaxY, wantQ.MaxY, 0.5f),
                  $"框 ({gotQ.MinX:F1},{gotQ.MinY:F1})-({gotQ.MaxX:F1},{gotQ.MaxY:F1})"
                  + $" 期望 ({wantQ.MinX:F1},{wantQ.MinY:F1})-({wantQ.MaxX:F1},{wantQ.MaxY:F1})"
                  + $"（右上那个角就是第四点 {q4.X:F0},{q4.Y:F0}）");

            var qEdgeMid = new Vector2(lx + 150f, ly);                 // 底边中点
            var qInside = new Vector2((lx + lx + 300f + lx + 75f + q4.X) / 4f,
                                      (ly + ly + ly - 200f + q4.Y) / 4f);
            Check("平行四边形：边上命中、内部不命中（只认描边）",
                  q2.HitTestExact(qEdgeMid.X, qEdgeMid.Y) && !q2.HitTestExact(qInside.X, qInside.Y),
                  $"底边中点 {q2.HitTestExact(qEdgeMid.X, qEdgeMid.Y)}，"
                  + $"内部 {q2.HitTestExact(qInside.X, qInside.Y)}");

            // ---- 拖一个顶点：只动它，第四个角**仍逐位等于公式** ----
            var qV1 = SelectionHandles.ShapeHandleCanvasPosition(q2, ShapeHandle.Vertex1);
            float q0x = q2.Points[0].X, q0y = q2.Points[0].Y;
            float q2x = q2.Points[2].X, q2y = q2.Points[2].Y;
            int qRev = q2.Revision, qUndo = Doc.UndoDepth;
            var qV1To = new Vector2(lx + 380f, ly + 30f);   // 离菱形 / 矩形都远（见 M 段的摆位账）
            bool tookQ = SelectionGestureForTest(qV1.X, qV1.Y);
            UpdateSelectionGestureForTest(qV1To.X, qV1To.Y);
            SettleFrames(80);
            Check("平行四边形：拖顶点时模型没动（Revision 不变、走快路）",
                  q2.Revision == qRev && VertexDragging,
                  $"Revision {qRev} → {q2.Revision}，拖元素中={VertexDragging}");
            Check("平行四边形：拖动中内容层一帧都不重画", _windows[0].LastPatchCount == 0,
                  $"上一帧光栅化分块 {_windows[0].LastPatchCount} 块");
            EndSelectionGestureForTest();
            SettleFrames(200);
            var q4After = q2.ParallelogramFourthLocal();
            Check("平行四边形：拖任一顶点后，第四个顶点仍**逐位**等于公式",
                  tookQ && q2.Points.Count == 3
                  && q4After.X == q2.Points[1].X + q2.Points[2].X - q2.Points[0].X
                  && q4After.Y == q2.Points[1].Y + q2.Points[2].Y - q2.Points[0].Y
                  && q4After.X == q4.X + (q2.Points[1].X - (lx + 300f))
                  && q4After.Y == q4.Y + (q2.Points[1].Y - ly),
                  $"第四个点 ({q4.X:F1},{q4.Y:F1}) → ({q4After.X:F1},{q4After.Y:F1})"
                  + $"（右下角挪了 ({q2.Points[1].X - (lx + 300f):F1},{q2.Points[1].Y - ly:F1})，"
                  + $"第四点跟着平移了同样的量）");
            Check("平行四边形：拖一个顶点只动它（另两个逐位不变）",
                  q2.Points[0].X == q0x && q2.Points[0].Y == q0y
                  && q2.Points[2].X == q2x && q2.Points[2].Y == q2y
                  && Near(q2.Points[1].X, qV1To.X, 1f) && Near(q2.Points[1].Y, qV1To.Y, 1f),
                  $"底右 ({q2.Points[1].X:F1},{q2.Points[1].Y:F1}) 期望 ({qV1To.X:F0},{qV1To.Y:F0})，"
                  + $"底左 ({q2.Points[0].X:F1},{q2.Points[0].Y:F1})，"
                  + $"顶左 ({q2.Points[2].X:F1},{q2.Points[2].Y:F1})");
            Check("平行四边形：一次拖顶点 = 一步撤销", Doc.UndoDepth == qUndo + 1,
                  $"撤销栈 {qUndo} → {Doc.UndoDepth} 步");
            Doc.Undo();
            SettleFrames(150);
        }

        // ================= L2. 读数：三角形三个内角 / 平行四边形两个夹角（规格 9.7）=================
        //
        // **两个图形都只在"拖顶点时"显示**（三角形原来"选中就显示"，用户 2026-09-20 定：
        // "应该在拖动的时候再显示角度，要不然看起来也乱"），拖的时候实时更新。
        // **不再显示"内角和"那一行**（用户 2026-09-19 定：显示和太乱），所以为它服务的
        // 0.1° 配平也撤了——三个角**各自独立**取值，没有谁为了凑 180.0 被动过 0.1°。
        //
        // 这一节顺带把"**绘制与脏区同源**"验掉：浮动层是**按脏区裁剪**画的，所以
        //   · 标签上屏了 ⟹ 那块脏区确实算上了它；
        //   · 松手之后同一块探针窗必须干净 ⟹ 消失那一帧也被算到了（不留残影）。
        // 探针数的是角标胶囊的**底色**（默认主题 Panel 盖在深色白板上 ≈ (236,236,239)）。
        Console.WriteLine("  -- L2. 三角形内角 / 平行四边形夹角（读数）--");
        {
            bool Near(float a, float b, float t) => MathF.Abs(a - b) <= t;
            Span<Vector2> av = stackalloc Vector2[4];
            Span<float> ad = stackalloc float[3];
            int PanelPixels(int x, int y, int w, int h)
                => ScreenProbe.CountNear(x, y, w, h, 236, 236, 239, 26);
            // 两颗角标的探针窗：左顶点取它左边一截、右顶点取它右边一截（角标就挂在那儿）
            int LeftPill(float vx, float vy) => PanelPixels((int)(vx - 90f * DpiScale),
                (int)(vy - 14f * DpiScale), (int)(60f * DpiScale), (int)(28f * DpiScale));
            int RightPill(float vx, float vy) => PanelPixels((int)(vx + 30f * DpiScale),
                (int)(vy - 14f * DpiScale), (int)(60f * DpiScale), (int)(28f * DpiScale));

            // ---- 数学层：一个**已知角度**的 30/60/90 三角形 ----
            // 顶点0 = 直角，顶点1 处 30°，顶点2 处 60°（高 = 600·tan30° ≈ 346.41）。
            var T0 = new Vector2(lx, ly);
            var T1 = new Vector2(lx + 600f, ly);
            var T2 = new Vector2(lx, ly - 346.4102f);
            Span<Vector2> tri3 = stackalloc Vector2[3];
            tri3[0] = T0; tri3[1] = T1; tri3[2] = T2;
            Span<float> triDeg = stackalloc float[3];
            int triN = SelectionHandles.PolygonAngles(StrokeKind.Triangle, tri3, triDeg);
            Check("内角·数学层：30/60/90 的三角形 → 读数 90 / 30 / 60（±0.1°）",
                  triN == 3 && Near(triDeg[0], 90f, 0.1f) && Near(triDeg[1], 30f, 0.1f)
                  && Near(triDeg[2], 60f, 0.1f),
                  $"读数 {triDeg[0]:F2}° / {triDeg[1]:F2}° / {triDeg[2]:F2}°");
            // **配平撤掉了**（用户 2026-09-19 定：不再显示那一行"内角和"）：每个角都必须是
            // "那个角本身"，不许为了凑一行 180.0 被动过 0.1°。用一个**真值不在 0.1° 网格上**
            // 的三角形盯住它——配平过的话，三个数会变成 0.1° 的整数倍，这里当场不等。
            var S0 = new Vector2(0f, 0f);
            var S1 = new Vector2(300f, 0f);
            var S2 = new Vector2(-120f, 211.36f);          // 故意摆歪：三个角都不是整齐数
            Span<Vector2> triV = stackalloc Vector2[3];
            triV[0] = S0; triV[1] = S1; triV[2] = S2;
            Span<float> triRaw = stackalloc float[3];
            int triRawN = SelectionHandles.PolygonAngles(StrokeKind.Triangle, triV, triRaw);
            float e0 = SelectionHandles.AngleBetweenDegrees(S1 - S0, S2 - S0);
            float e1 = SelectionHandles.AngleBetweenDegrees(S2 - S1, S0 - S1);
            float e2 = SelectionHandles.AngleBetweenDegrees(S0 - S2, S1 - S2);
            Check("内角·数学层：每个角都取**它自己**（独立算一遍，逐位一致 = 没配平）",
                  triRawN == 3 && triRaw[0] == e0 && triRaw[1] == e1 && triRaw[2] == e2,
                  $"{triRaw[0]:F4} / {triRaw[1]:F4} / {triRaw[2]:F4}"
                  + $" vs 独立算 {e0:F4} / {e1:F4} / {e2:F4}");
            Check("内角·数学层：三个角之和 = 180（三角形的性质，不是凑出来的，±0.01°）",
                  Near(triRaw[0] + triRaw[1] + triRaw[2], 180f, 0.01f),
                  $"和 = {triRaw[0] + triRaw[1] + triRaw[2]:F4}°");

            // ---- 数学层：平行四边形两个夹角（互补）----
            Span<Vector2> par4 = stackalloc Vector2[4];
            par4[0] = new Vector2(lx, ly);
            par4[1] = new Vector2(lx + 400f, ly);
            par4[2] = new Vector2(lx + 100f, ly - 260f);
            par4[3] = Stroke.ParallelogramFourth(par4[0], par4[1], par4[2]);
            Span<float> parDeg = stackalloc float[2];
            int parN = SelectionHandles.PolygonAngles(StrokeKind.Parallelogram, par4, parDeg);
            float w0 = SelectionHandles.AngleBetweenDegrees(par4[1] - par4[0], par4[2] - par4[0]);
            float w1 = SelectionHandles.AngleBetweenDegrees(par4[0] - par4[1], par4[3] - par4[1]);
            Check("夹角·数学层：两个角 = 那两条边张成的角（独立算一遍，±0.01°）",
                  parN == 2 && Near(parDeg[0], w0, 0.01f) && Near(parDeg[1], w1, 0.01f),
                  $"读数 {parDeg[0]:F2}° / {parDeg[1]:F2}°，独立算 {w0:F2}° / {w1:F2}°");
            Check("夹角·数学层：两个数互补（和 = 180 ±0.1°）",
                  Near(parDeg[0] + parDeg[1], 180f, 0.1f),
                  $"{parDeg[0]:F2} + {parDeg[1]:F2} = {parDeg[0] + parDeg[1]:F3}");

            // ---- 真机：三角形**也改成"只在拖顶点时显示"**（用户 2026-09-20 定）----
            //
            // 用户原话："三角形应该在拖动的时候再显示角度，要不然看起来也乱。"
            // 在那之前它是"一选中就挂三颗角标"，静止摆着也一直显示。
            // 所以这一节四条按顺序钉住：
            //   ① 静止选中 → 一个角都不显示、屏幕上也没有角标；
            //   ② **按住顶点**（还没移动）→ 三个角立刻出来，而且是这个三角形的真值 90/30/60；
            //   ③ 继续拖 → 读数实时变；④ 松手 → 立刻收回去、不留残影；
            //   ⑤ 一次拖顶点仍然只是一步撤销。
            Doc.Clear();
            Doc.ClearHistory();
            Tool = Tool.Marquee;
            var rt = new Stroke
            {
                Tool = Tool.Triangle, Kind = StrokeKind.Triangle,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
            };
            rt.AddPoint(T0.X, T0.Y, 1f, 0);
            rt.AddPoint(T1.X, T1.Y, 1f, 0);
            rt.AddPoint(T2.X, T2.Y, 1f, 0);
            Doc.AddStroke(rt);
            Doc.SelectOnly(new[] { rt });
            SettleFrames(360);

            // ① 静止选中：读数一个都没有，三颗角标也都不在屏幕上
            Check("内角·真机：**选中静止时一个角都不显示**（用户 2026-09-20 定：拖动时才显示）",
                  FillAngleReadout(av, ad) == 0, $"读数个数 {FillAngleReadout(av, ad)}");
            int idleLeft0 = LeftPill(T0.X, T0.Y);
            int idleRight = RightPill(T1.X, T1.Y);
            int idleLeft2 = LeftPill(T2.X, T2.Y);
            Check("内角·真机：静止选中时三颗角标都不在屏幕上（不是\"画了但看不见\"）",
                  idleLeft0 < 30 && idleRight < 30 && idleLeft2 < 30,
                  $"左下 {idleLeft0} 像素、右 {idleRight} 像素、上 {idleLeft2} 像素");

            // ② 按住上顶点、**先别挪**：按住那一刻三个角就该出来
            var triApex = SelectionHandles.ShapeHandleCanvasPosition(rt, ShapeHandle.Vertex2);
            bool tookTri = SelectionGestureForTest(triApex.X, triApex.Y);
            SettleFrames(160);
            int rn = FillAngleReadout(av, ad);
            Check("内角·真机：**按住顶点就显示**三个内角（90 / 30 / 60，±0.1°）",
                  tookTri && VertexDragging && rn == 3
                  && Near(ad[0], 90f, 0.1f) && Near(ad[1], 30f, 0.1f) && Near(ad[2], 60f, 0.1f),
                  $"接住={tookTri}，拖元素中={VertexDragging}，"
                  + $"读数 {ad[0]:F2} / {ad[1]:F2} / {ad[2]:F2}");
            // 三颗角标：左下的角挂在它左边、右边的角挂在它右边、上面的角也挂左边
            //（左右由"顶点在形心的哪一侧"决定，见 FillAnglePills）。
            int triLeft0 = LeftPill(T0.X, T0.Y);
            int triRight = RightPill(T1.X, T1.Y);
            int triLeft2 = LeftPill(T2.X, T2.Y);
            // **形心那一块正是以前印"内角和"那一行的地方**（用户 2026-09-19 定：不显示了）。
            // 所以这里反过来量：它必须是干净的——这一条盯住"那行真的没了"。
            var triCentroid = new Vector2((T0.X + T1.X + T2.X) / 3f, (T0.Y + T1.Y + T2.Y) / 3f);
            int triCenter = PanelPixels((int)(triCentroid.X - 60f * DpiScale),
                (int)(triCentroid.Y - 14f * DpiScale), (int)(120f * DpiScale), (int)(28f * DpiScale));
            Check("内角·真机：三颗角标都上了屏（脏区确实把每一颗都算上了）",
                  triLeft0 > 150 && triRight > 150 && triLeft2 > 150,
                  $"左下 {triLeft0} 像素、右 {triRight} 像素、上 {triLeft2} 像素");
            Check("内角·真机：形心那一块**没有**\"内角和\"那一行（用户 2026-09-19 定）",
                  triCenter < 30, $"形心窗口 {triCenter} 像素（期望 <30）");

            // ③ 继续拖 → 读数实时变（每个角各自独立，谁都不为凑和被动过）
            float b0 = ad[0], b1 = ad[1], b2 = ad[2];
            var triApexTo = new Vector2(T2.X + 260f, T2.Y - 140f);
            UpdateSelectionGestureForTest(triApexTo.X, triApexTo.Y);
            SettleFrames(140);
            int dn = FillAngleReadout(av, ad);
            Check("内角·真机：拖顶点时读数**实时变**（还是三个）",
                  VertexDragging && dn == 3
                  && (MathF.Abs(ad[0] - b0) > 1f || MathF.Abs(ad[1] - b1) > 1f
                      || MathF.Abs(ad[2] - b2) > 1f),
                  $"{b0:F1}/{b1:F1}/{b2:F1} → {ad[0]:F1}/{ad[1]:F1}/{ad[2]:F1}");
            Check("内角·真机：拖完三个角仍是各自独立的值（和 = 180 是三角形的性质，±0.02°）",
                  Near(ad[0] + ad[1] + ad[2], 180f, 0.02f), $"和 = {ad[0] + ad[1] + ad[2]:F4}°");
            // 拖动中把整块都探一遍：角标跟着顶点走，走过的路上不许有残留
            var dragBox = RectF.Empty;
            dragBox.Add(T0.X, T0.Y);
            dragBox.Add(T2.X - 60f, T2.Y - 60f);
            dragBox.Add(triApexTo.X + 160f, triApexTo.Y + 60f);
            dragBox.Add(T1.X + 160f, T1.Y + 60f);
            int dragResidue = PanelPixels((int)dragBox.MinX, (int)dragBox.MinY,
                                          (int)(dragBox.MaxX - dragBox.MinX),
                                          (int)(dragBox.MaxY - dragBox.MinY));
            Check("内角·真机：拖动中整块探针里的胶囊像素 = 那几颗角标（没有额外的残影）",
                  dragResidue > 300, $"整块里 {dragResidue} 像素（三颗角标）");

            // ④ 松手 = 角标立刻收回去（这一条正是这次改动的核心）
            EndSelectionGestureForTest();
            SettleFrames(260);
            Check("内角·真机：**松手就不显示**（读数个数 = 0）",
                  !VertexDragging && FillAngleReadout(av, ad) == 0,
                  $"拖元素中={VertexDragging}，读数个数 {FillAngleReadout(av, ad)}");
            int goneLeft0 = LeftPill(T0.X, T0.Y);      // 这两个角没被拖，还在原位
            int goneRight = RightPill(T1.X, T1.Y);
            Check("内角·真机：松手后角标真的从屏幕消失（不留残影）",
                  goneLeft0 < 30 && goneRight < 30,
                  $"还剩 左下 {goneLeft0} 像素、右 {goneRight} 像素");

            // ⑤ 一次拖顶点 = 一步撤销
            Check("内角·真机：一次拖顶点 = 一步撤销",
                  Doc.UndoDepth >= 2, $"撤销栈 {Doc.UndoDepth} 步");
            Doc.Undo();
            SettleFrames(150);

            // ---- 真机：平行四边形只**拖顶点时**显示两个夹角 ----
            Doc.Clear();
            Doc.ClearHistory();
            var rp = new Stroke
            {
                Tool = Tool.Parallelogram, Kind = StrokeKind.Parallelogram,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
            };
            rp.AddPoint(par4[0].X, par4[0].Y, 1f, 0);
            rp.AddPoint(par4[1].X, par4[1].Y, 1f, 0);
            rp.AddPoint(par4[2].X, par4[2].Y, 1f, 0);
            Doc.AddStroke(rp);
            Doc.SelectOnly(new[] { rp });
            SettleFrames(320);
            Check("夹角·真机：**选中静止时两个角都不显示**（规格只要求拖顶点时显示）",
                  FillAngleReadout(av, ad) == 0, $"读数个数 {FillAngleReadout(av, ad)}");
            var qv1 = SelectionHandles.ShapeHandleCanvasPosition(rp, ShapeHandle.Vertex1);
            bool tookQ1 = SelectionGestureForTest(qv1.X, qv1.Y);
            UpdateSelectionGestureForTest(qv1.X + 45f, qv1.Y + 30f);
            SettleFrames(120);
            int qn = FillAngleReadout(av, ad);
            float q0 = SelectionHandles.AngleBetweenDegrees(av[1] - av[0], av[2] - av[0]);
            float q1 = SelectionHandles.AngleBetweenDegrees(av[0] - av[1], av[3] - av[1]);
            Check("夹角·真机：拖顶点时出现**两个**角，且 = 那两条边张成的角（±0.01°）",
                  tookQ1 && VertexDragging && qn == 2
                  && Near(ad[0], q0, 0.01f) && Near(ad[1], q1, 0.01f),
                  $"读数 {ad[0]:F2}° / {ad[1]:F2}°，独立算 {q0:F2}° / {q1:F2}°");
            Check("夹角·真机：两个数互补（和 = 180 ±0.1°）",
                  Near(ad[0] + ad[1], 180f, 0.1f), $"{ad[0]:F2} + {ad[1]:F2} = {ad[0] + ad[1]:F3}");
            int qLeft = LeftPill(av[0].X, av[0].Y);
            int qRight = RightPill(av[1].X, av[1].Y);
            Check("夹角·真机：两颗角标都上了屏（贴在被拖顶点之外的左右两侧）",
                  qLeft > 150 && qRight > 150, $"左 {qLeft} 像素，右 {qRight} 像素");
            EndSelectionGestureForTest();
            SettleFrames(360);
            int qLeftGone = LeftPill(par4[0].X, par4[0].Y);
            int qRightGone = RightPill(par4[1].X, par4[1].Y);
            Check("夹角·真机：松手后两颗角标都消失（不留残影）",
                  FillAngleReadout(av, ad) == 0 && qLeftGone < 30 && qRightGone < 30,
                  $"读数个数 {FillAngleReadout(av, ad)}，左 {qLeftGone} 像素，右 {qRightGone} 像素");
            Doc.Undo();
            SettleFrames(150);
        }

        // ================= M. 一族"特殊形状"吸附（规格 9.6）=================
        //
        // 三角形 → 等腰 / 等边 / 直角；矩形 → 正方形；椭圆 → 正圆；平行四边形 → 菱形 / 矩形。
        // 每种约束都验三档：**正例**、**容差边界（刚好在外面的不吸）**、**Alt 自由**；
        // 外加"整体移动 / 旋转时不会吸"。
        //
        // 两条腿都验：数学层直接调权威函数（容差边界与 Alt 只能在这一层验——Alt 要真按
        // 键盘，注入不了），真机层真拖一次手柄、证明它确实接在那条路上。
        // 摆位一律按**容差的比例**（tol = 2 逻辑像素 × dpi），这样在任何 DPI 的机器上语义一样。
        Console.WriteLine("  -- M. 一族\"特殊形状\"吸附 --");
        {
            bool Near(float a, float b, float t) => MathF.Abs(a - b) <= t;
            float tol = SelectionHandles.ShapeSnapLengthToleranceLogical * DpiScale;
            float angTol = SelectionHandles.ShapeSnapAngleToleranceDegrees;

            // 三角形的两个固定顶点：底边水平、长 200（被拖的第三个点另行给）
            var A = new Vector2(lx, ly);
            var B = new Vector2(lx + 200f, ly);
            float midX = lx + 100f;
            float D(Vector2 p, Vector2 q) => Vector2.Distance(p, q);

            // ---- 三角形 · 等腰 ----
            var isoV = new Vector2(midX + tol * 0.25f, ly - 150f);
            float isoDiff = MathF.Abs(D(isoV, A) - D(isoV, B));
            var isoGot = SelectionHandles.SnapPolygonVertex(StrokeKind.Triangle, 0, isoV, A, B,
                                                            isoV, tol, false, out var isoSnap);
            Check("三角形·等腰：两边长差在容差内 → 修正到中垂线上（两腰**精确**相等）",
                  isoSnap == ShapeSnapKind.Isosceles && Near(isoGot.X, midX, 0.01f)
                  && Near(isoGot.Y, isoV.Y, 0.01f) && Near(D(isoGot, A), D(isoGot, B), 1e-3f),
                  $"摆位时两边差 {isoDiff:F2}（容差 {tol:F1}）→ 吸到「{SelectionHandles.ShapeSnapLabel(isoSnap)}」，"
                  + $"顶点 ({isoGot.X:F2},{isoGot.Y:F2}) 期望 x={midX:F2}，"
                  + $"两腰 {D(isoGot, A):F4} / {D(isoGot, B):F4}");

            var isoV2 = new Vector2(midX + tol * 1.5f, ly - 150f);
            float isoDiff2 = MathF.Abs(D(isoV2, A) - D(isoV2, B));
            var isoGot2 = SelectionHandles.SnapPolygonVertex(StrokeKind.Triangle, 0, isoV2, A, B,
                                                             isoV2, tol, false, out var isoSnap2);
            Check("三角形·等腰：差得**刚好在容差外** → 不吸（手柄不粘手）",
                  isoDiff2 > tol && isoDiff2 < tol * 2f
                  && isoSnap2 == ShapeSnapKind.None && isoGot2 == isoV2,
                  $"两边差 {isoDiff2:F2} > 容差 {tol:F1} → 吸到={isoSnap2}，"
                  + $"顶点原样 ({isoGot2.X:F2},{isoGot2.Y:F2})");

            var isoAlt = SelectionHandles.SnapPolygonVertex(StrokeKind.Triangle, 0, isoV, A, B,
                                                            isoV, tol, true, out var isoSnap3);
            Check("三角形·等腰：**Alt 一律自由**（同样的位置，不吸）",
                  isoSnap3 == ShapeSnapKind.None && isoAlt == isoV,
                  $"Alt 下吸到={isoSnap3}，顶点原样 ({isoAlt.X:F2},{isoAlt.Y:F2})");

            // ---- 三角形 · 等边 ----
            var eqH = 100f * MathF.Sqrt(3f);                       // 边长 200 的正三角形的高
            var eqV = new Vector2(midX + tol * 0.25f, ly - eqH);
            var eqGot = SelectionHandles.SnapPolygonVertex(StrokeKind.Triangle, 0, eqV, A, B,
                                                           eqV, tol, false, out var eqSnap);
            Check("三角形·等边：三边都在容差内 → 修正成**精确**正三角形",
                  eqSnap == ShapeSnapKind.Equilateral
                  && Near(eqGot.X, midX, 0.01f) && Near(eqGot.Y, ly - eqH, 0.01f)
                  && Near(D(eqGot, A), 200f, 1e-3f) && Near(D(eqGot, B), 200f, 1e-3f)
                  && Near(D(A, B), 200f, 1e-3f),
                  $"摆位：三边 {D(eqV, A):F2} / {D(eqV, B):F2} / {D(A, B):F2}（容差 {tol:F1}）"
                  + $"→ 吸到「{SelectionHandles.ShapeSnapLabel(eqSnap)}」，"
                  + $"修正后三边 {D(eqGot, A):F4} / {D(eqGot, B):F4} / {D(A, B):F4}");
            // 等边一定也满足"两腰相等"：优先级必须是等边（反了会把好形状改成只等腰）
            Check("三角形·等边 优先于 等腰（同一个位置不会报成等腰）",
                  eqSnap == ShapeSnapKind.Equilateral, $"吸到={eqSnap}");

            // 等边的容差边界：把顶点沿底边挪出去，让两条斜边一条超差、一条欠差
            // （等边要求**三条边**都在容差内，所以挪 2 倍容差就出界了）
            var eqV2 = new Vector2(midX + tol * 2f, ly - eqH);
            float eqDev = MathF.Max(MathF.Abs(D(eqV2, A) - 200f), MathF.Abs(D(eqV2, B) - 200f));
            var eqGot2 = SelectionHandles.SnapPolygonVertex(StrokeKind.Triangle, 0, eqV2, A, B,
                                                            eqV2, tol, false, out var eqSnap2);
            Check("三角形·等边：三边差得**刚好在容差外** → 不吸",
                  eqDev > tol && eqDev < tol * 2f && eqSnap2 == ShapeSnapKind.None && eqGot2 == eqV2,
                  $"摆位：离 200 最远的那条边差 {eqDev:F2}（容差 {tol:F1}）→ 吸到={eqSnap2}，顶点原样");
            var eqAlt = SelectionHandles.SnapPolygonVertex(StrokeKind.Triangle, 0, eqV, A, B,
                                                           eqV, tol, true, out var eqSnap3);
            Check("三角形·等边：**Alt 一律自由**",
                  eqSnap3 == ShapeSnapKind.None && eqAlt == eqV,
                  $"Alt 下吸到={eqSnap3}，顶点原样");

            // ---- 三角形 · 直角（被拖的那个角）----
            // 直角顶点在以 AB 为直径的圆上（泰勒斯）：取 60° 那个位置，
            // 它**不在**中垂线上（所以不会先被等腰抢走）
            var rtV = new Vector2(midX + 50f, ly - 100f * MathF.Sin(60f * MathF.PI / 180f));
            float rtAng = SelectionHandles.AngleBetweenDegrees(A - rtV, B - rtV);
            var rtGot = SelectionHandles.SnapPolygonVertex(StrokeKind.Triangle, 0, rtV, A, B,
                                                           rtV, tol, false, out var rtSnap);
            float rtAngAfter = SelectionHandles.AngleBetweenDegrees(A - rtGot, B - rtGot);
            Check("三角形·直角：内角在 1° 内 → 修正到**恰好 90°**（被拖的那个角）",
                  rtSnap == ShapeSnapKind.RightAngle && MathF.Abs(rtAngAfter - 90f) < 1e-3f,
                  $"摆位时内角 {rtAng:F4}°（容差 {angTol:F0}°）→ 吸到「"
                  + $"{SelectionHandles.ShapeSnapLabel(rtSnap)}」，修正后 {rtAngAfter:F4}°，"
                  + $"顶点挪了 {D(rtGot, rtV):F4} 像素");
            // 容差边界：沿半径缩到 98%（同一条射线上），内角变成 ~91.3°（刚好在 1° 外）
            var rtV2 = new Vector2(midX + 49f, ly - 98f * MathF.Sin(60f * MathF.PI / 180f));
            float rtAng2 = SelectionHandles.AngleBetweenDegrees(A - rtV2, B - rtV2);
            float rtDiff2 = MathF.Abs(D(rtV2, A) - D(rtV2, B));
            var rtGot2 = SelectionHandles.SnapPolygonVertex(StrokeKind.Triangle, 0, rtV2, A, B,
                                                            rtV2, tol, false, out var rtSnap2);
            Check("三角形·直角：内角差得**刚好在容差外**（约 91.3°）→ 不吸",
                  MathF.Abs(rtAng2 - 90f) > angTol && MathF.Abs(rtAng2 - 90f) < angTol * 2f
                  && rtDiff2 > tol        // 顺带确认：也没被等腰抢走
                  && rtSnap2 == ShapeSnapKind.None && rtGot2 == rtV2,
                  $"摆位时内角 {rtAng2:F4}°（离 90° 差 {MathF.Abs(rtAng2 - 90f):F3}° > {angTol:F0}°），"
                  + $"两边差 {rtDiff2:F2} > 容差 {tol:F1} → 吸到={rtSnap2}，顶点原样");
            var rtAlt = SelectionHandles.SnapPolygonVertex(StrokeKind.Triangle, 0, rtV, A, B,
                                                           rtV, tol, true, out var rtSnap3);
            Check("三角形·直角：**Alt 一律自由**",
                  rtSnap3 == ShapeSnapKind.None && rtAlt == rtV,
                  $"Alt 下吸到={rtSnap3}，顶点原样");

            // ---- 三角形 · 直角（**固定的**那个角）----
            // 角在底左（A）上：被拖的点要落在"过 A 且垂直于 AB"的直线上
            var rtF = new Vector2(lx + tol * 0.1f, ly - 100f);
            float rtAngA = SelectionHandles.AngleBetweenDegrees(rtF - A, B - A);
            var rtFGot = SelectionHandles.SnapPolygonVertex(StrokeKind.Triangle, 0, rtF, A, B,
                                                            rtF, tol, false, out var rtFSnap);
            float rtAngA2 = SelectionHandles.AngleBetweenDegrees(rtFGot - A, B - A);
            Check("三角形·直角：直角在**另一个（固定的）顶点**上也能修（修正只动被拖的点）",
                  rtFSnap == ShapeSnapKind.RightAngle && Near(rtFGot.X, A.X, 0.01f)
                  && MathF.Abs(rtAngA2 - 90f) < 1e-3f,
                  $"摆位时 A 处内角 {rtAngA:F4}° → 吸到「{SelectionHandles.ShapeSnapLabel(rtFSnap)}」，"
                  + $"修正后 {rtAngA2:F4}°，被拖的点 ({rtFGot.X:F2},{rtFGot.Y:F2}) 期望 x={A.X:F2}");

            // ---- 椭圆 · 正圆 ----
            bool eSnap;
            float eIn = SelectionHandles.SnapEllipseAxis(200f + tol * 0.5f, 200f, tol, false, out eSnap);
            Check("椭圆·正圆：|a − b| 在容差内 → 被拖的那条半轴取成另一条（a、b **逐位**相等）",
                  eSnap && eIn == 200f,
                  $"a = 200 + {tol * 0.5f:F1} → 修正成 {eIn:F1}（期望正好 200），吸住={eSnap}");
            bool eSnap2;
            float eOut = SelectionHandles.SnapEllipseAxis(200f + tol * 1.5f, 200f, tol, false, out eSnap2);
            Check("椭圆·正圆：差得刚好在容差外 → 不吸",
                  !eSnap2 && eOut == 200f + tol * 1.5f,
                  $"a = 200 + {tol * 1.5f:F1}（容差 {tol:F1}）→ 不吸，a 保持 {eOut:F2}");
            bool eSnap3;
            float eAlt = SelectionHandles.SnapEllipseAxis(200f + tol * 0.25f, 200f, tol, true, out eSnap3);
            Check("椭圆·正圆：**Alt 一律自由**",
                  !eSnap3 && eAlt == 200f + tol * 0.25f,
                  $"Alt 下 a 保持 {eAlt:F2}，吸住={eSnap3}");

            // ---- 平行四边形 · 菱形 ----
            var P0 = new Vector2(lx, ly);
            var P2 = new Vector2(lx + 60f, ly - 200f);
            float lv = D(P2, P0);                                   // 另一条邻边的长
            var rhV = new Vector2(P0.X + lv + tol * 0.2f, ly);
            var rhGot = SelectionHandles.SnapPolygonVertex(StrokeKind.Parallelogram, 1, P0, rhV, P2,
                                                           rhV, tol, false, out var rhSnap);
            Check("平行四边形·菱形：邻边差在容差内 → 修正到**精确**相等",
                  rhSnap == ShapeSnapKind.Rhombus && Near(rhGot.X, P0.X + lv, 0.01f)
                  && rhGot.Y == ly && Near(D(rhGot, P0), lv, 1e-3f),
                  $"另一条邻边长 {lv:F3}，摆位差 {MathF.Abs(D(rhV, P0) - lv):F2}（容差 {tol:F1}）"
                  + $"→ 吸到「{SelectionHandles.ShapeSnapLabel(rhSnap)}」，"
                  + $"修正后 ({rhGot.X:F3},{rhGot.Y:F3})，邻边 {D(rhGot, P0):F4} / {lv:F4}");

            var rhV2 = new Vector2(P0.X + lv + tol * 1.5f, ly);
            float rhDiff2 = MathF.Abs(D(rhV2, P0) - lv);
            var rhGot2 = SelectionHandles.SnapPolygonVertex(StrokeKind.Parallelogram, 1, P0, rhV2, P2,
                                                            rhV2, tol, false, out var rhSnap2);
            Check("平行四边形·菱形：差得刚好在容差外 → 不吸",
                  rhDiff2 > tol && rhDiff2 < tol * 2f && rhSnap2 == ShapeSnapKind.None && rhGot2 == rhV2,
                  $"邻边差 {rhDiff2:F2} > 容差 {tol:F1} → 吸到={rhSnap2}，顶点原样");
            var rhAlt = SelectionHandles.SnapPolygonVertex(StrokeKind.Parallelogram, 1, P0, rhV, P2,
                                                           rhV, tol, true, out var rhSnap3);
            Check("平行四边形·菱形：**Alt 一律自由**",
                  rhSnap3 == ShapeSnapKind.None && rhAlt == rhV,
                  $"Alt 下吸到={rhSnap3}，顶点原样");

            // ---- 平行四边形 · 矩形（邻边垂直）----
            var raP1 = new Vector2(lx + 200f, ly);
            var raV = new Vector2(lx + tol * 0.1f, ly - 150f);
            float raAng = SelectionHandles.AngleBetweenDegrees(raV - P0, raP1 - P0);
            var raGot = SelectionHandles.SnapPolygonVertex(StrokeKind.Parallelogram, 2, P0, raP1, raV,
                                                           raV, tol, false, out var raSnap);
            float raAngAfter = SelectionHandles.AngleBetweenDegrees(raGot - P0, raP1 - P0);
            Check("平行四边形·矩形：夹角在 1° 内 → 修正到**恰好 90°**",
                  raSnap == ShapeSnapKind.Rectangle && Near(raGot.X, P0.X, 0.01f)
                  && MathF.Abs(raAngAfter - 90f) < 1e-3f,
                  $"摆位时夹角 {raAng:F4}°（容差 {angTol:F0}°）→ 吸到「"
                  + $"{SelectionHandles.ShapeSnapLabel(raSnap)}」，修正后 {raAngAfter:F4}°");

            var raV2 = new Vector2(lx + 3f, ly - 150f);      // 3 像素 → 夹角离 90° 约 1.15°（容差外）
            float raAng2 = SelectionHandles.AngleBetweenDegrees(raV2 - P0, raP1 - P0);
            var raGot2 = SelectionHandles.SnapPolygonVertex(StrokeKind.Parallelogram, 2, P0, raP1, raV2,
                                                            raV2, tol, false, out var raSnap2);
            Check("平行四边形·矩形：夹角刚好在容差外（约 88.85°）→ 不吸",
                  MathF.Abs(raAng2 - 90f) > angTol && raSnap2 == ShapeSnapKind.None && raGot2 == raV2,
                  $"夹角 {raAng2:F4}°，离 90° 差 {MathF.Abs(raAng2 - 90f):F3}° > {angTol:F0}° → "
                  + $"吸到={raSnap2}，顶点原样");
            var raAlt = SelectionHandles.SnapPolygonVertex(StrokeKind.Parallelogram, 2, P0, raP1, raV,
                                                           raV, tol, true, out var raSnap3);
            Check("平行四边形·矩形：**Alt 一律自由**",
                  raSnap3 == ShapeSnapKind.None && raAlt == raV,
                  $"Alt 下吸到={raSnap3}，顶点原样");

            // ---- 矩形 · 正方形（拖四角：改的是矩阵，不是点）----
            {
                var rSq = new Stroke
                {
                    Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
                    Color = new Color4(1f, 0f, 1f, 1f), Width = 4f * DpiScale,
                };
                rSq.AddPoint(lx, ly, 1f, 0);
                rSq.AddPoint(lx + 300f, ly + 300f + tol * 0.5f, 1f, 0);   // 两边差 = tol/2
                var sqSel = new[] { rSq };
                var sqFrame = SelectionHandles.FrameOf(sqSel);
                float sqW = sqFrame.Local.MaxX - sqFrame.Local.MinX;
                float sqH = sqFrame.Local.MaxY - sqFrame.Local.MinY;
                var sqAnchor = SelectionHandles.CanvasPosition(SelHandle.TopLeft, sqFrame, DpiScale);
                var sqCorner = SelectionHandles.CanvasPosition(SelHandle.BottomRight, sqFrame, DpiScale);
                var sqTo = sqAnchor + (sqCorner - sqAnchor) * 2f;          // 拖到两倍大

                bool sqOk = SelectionHandles.TrySnapSquareCorner(sqSel, SelHandle.BottomRight, sqFrame,
                                                                 sqTo, DpiScale, false, out var sqM);
                var s0 = Vector2.Transform(new Vector2(sqFrame.Local.MinX, sqFrame.Local.MinY), sqM);
                var s1 = Vector2.Transform(new Vector2(sqFrame.Local.MaxX, sqFrame.Local.MaxY), sqM);
                Check("矩形·正方形：两边差在容差内 → 拖四角时修正成**精确**正方形",
                      sqOk && Near(s1.X - s0.X, s1.Y - s0.Y, 0.01f) && (s1.X - s0.X) > 500f,
                      $"原框 {sqW:F2}×{sqH:F2}（差 {MathF.Abs(sqW - sqH):F2}，容差 {tol:F1}）→ "
                      + $"结果 {s1.X - s0.X:F3}×{s1.Y - s0.Y:F2}，吸住={sqOk}");

                // 对照：**不吸**的那条路（通用 DragMatrix）会保持原来的**比值**
                // （四角是等比缩放，两条边同比放大，所以"差"会跟着变大、"比值"不变）
                var plainM = SelectionHandles.DragMatrix(SelHandle.BottomRight, sqFrame,
                                                         sqTo, sqTo, DpiScale, false, false, true);
                var p0 = Vector2.Transform(new Vector2(sqFrame.Local.MinX, sqFrame.Local.MinY), plainM);
                var p1 = Vector2.Transform(new Vector2(sqFrame.Local.MaxX, sqFrame.Local.MaxY), plainM);
                Check("矩形·正方形：不吸的时候**比值**一个数都不改（对照）",
                      Near((p1.X - p0.X) / (p1.Y - p0.Y), sqW / sqH, 1e-4f),
                      $"通用换算的结果 {p1.X - p0.X:F2}×{p1.Y - p0.Y:F2}"
                      + $"（比值 {(p1.X - p0.X) / (p1.Y - p0.Y):F5} / 原比值 {sqW / sqH:F5}，"
                      + $"两边差被同比放大成 {MathF.Abs((p1.X - p0.X) - (p1.Y - p0.Y)):F2}"
                      + $"= 原差值 {MathF.Abs(sqW - sqH):F2} × 缩放倍数）");

                var rOut = new Stroke
                {
                    Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
                    Color = new Color4(1f, 0f, 1f, 1f), Width = 4f * DpiScale,
                };
                rOut.AddPoint(lx, ly, 1f, 0);
                rOut.AddPoint(lx + 300f, ly + 300f + tol * 1.5f, 1f, 0);
                var outSel = new[] { rOut };
                var outFrame = SelectionHandles.FrameOf(outSel);
                var outAnchor = SelectionHandles.CanvasPosition(SelHandle.TopLeft, outFrame, DpiScale);
                var outCorner = SelectionHandles.CanvasPosition(SelHandle.BottomRight, outFrame, DpiScale);
                var outTo = outAnchor + (outCorner - outAnchor) * 2f;
                Check("矩形·正方形：两边差**刚好在容差外** → 不吸",
                      !SelectionHandles.TrySnapSquareCorner(outSel, SelHandle.BottomRight, outFrame,
                                                            outTo, DpiScale, false, out _),
                      $"原框 {outFrame.Local.MaxX - outFrame.Local.MinX:F2}"
                      + $"×{outFrame.Local.MaxY - outFrame.Local.MinY:F2}"
                      + $"（差 {outFrame.Local.MaxY - outFrame.Local.MinY - (outFrame.Local.MaxX - outFrame.Local.MinX):F2}"
                      + $" > 容差 {tol:F1}）");
                Check("矩形·正方形：**Alt 一律自由**",
                      !SelectionHandles.TrySnapSquareCorner(sqSel, SelHandle.BottomRight, sqFrame,
                                                            sqTo, DpiScale, true, out _),
                      "Alt 下同样的摆位不吸");
                // 转过的矩形：选中框是它的外接正矩形（虚胖），沿屏幕轴缩放和它自己的边长
                // 没有简单关系 —— 明确不吸（宁可不给，也不给一个解释不清的行为）
                var rRot = new Stroke
                {
                    Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
                    Color = new Color4(1f, 0f, 1f, 1f), Width = 4f * DpiScale,
                };
                rRot.AddPoint(lx, ly, 1f, 0);
                rRot.AddPoint(lx + 300f, ly + 300f + tol * 0.5f, 1f, 0);
                rRot.Transform = SelectionHandles.RotateMatrix(30f, new Vector2(lx, ly));
                var rotSel = new[] { rRot };
                var rotFrame = SelectionHandles.FrameOf(rotSel);
                var rotAnchor = SelectionHandles.CanvasPosition(SelHandle.TopLeft, rotFrame, DpiScale);
                var rotCorner = SelectionHandles.CanvasPosition(SelHandle.BottomRight, rotFrame, DpiScale);
                Check("矩形·正方形：**转过的**矩形不吸（范围写清楚）",
                      !SelectionHandles.TrySnapSquareCorner(rotSel, SelHandle.BottomRight, rotFrame,
                                                            rotAnchor + (rotCorner - rotAnchor) * 2f,
                                                            DpiScale, false, out _),
                      "转过 30°：沿屏幕轴缩放 ≠ 沿它自己两条边缩放，所以不吸");
            }

            // ============ 真机层：吸住时接在那条路上，而且提交的几何**精确**满足约束 ============
            // ---- 三角形拖顶点（真机）：等腰 ----
            Doc.Clear();
            Doc.ClearHistory();
            Tool = Tool.Marquee;
            float mA = lx, mB = lx + 200f, mY = ly;
            var mTri = new Stroke
            {
                Tool = Tool.Triangle, Kind = StrokeKind.Triangle,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 6f * DpiScale,
            };
            mTri.AddPoint(midX + tol * 0.25f, mY - 150f, 1f, 0);
            mTri.AddPoint(mA, mY, 1f, 0);
            mTri.AddPoint(mB, mY, 1f, 0);
            Doc.AddStroke(mTri);
            Doc.SelectOnly(new[] { mTri });
            SettleFrames(250);
            var mTriApex = SelectionHandles.ShapeHandleCanvasPosition(mTri, ShapeHandle.Vertex0);
            var mTriTo = new Vector2(midX + tol * 0.25f, mY - 400f);   // 还在容差内 → 会吸
            SelectionGestureForTest(mTriApex.X, mTriApex.Y);
            UpdateSelectionGestureForTest(mTriTo.X, mTriTo.Y);
            SettleFrames(80);
            Check("吸附（真机）：拖三角形的顶点、吸住时胶囊说得出「等腰」",
                  ShapeSnapKind == ShapeSnapKind.Isosceles
                  && SelectionHandles.ShapeSnapLabel(ShapeSnapKind) == "等腰"
                  && VertexDragging,
                  $"吸到={ShapeSnapKind}（「{SelectionHandles.ShapeSnapLabel(ShapeSnapKind)}」），"
                  + $"拖元素中={VertexDragging}");
            EndSelectionGestureForTest();
            SettleFrames(200);
            var mA2 = new Vector2(mTri.Points[1].X, mTri.Points[1].Y);
            var mB2 = new Vector2(mTri.Points[2].X, mTri.Points[2].Y);
            var mApex = new Vector2(mTri.Points[0].X, mTri.Points[0].Y);
            Check("吸附（真机）：提交的几何**精确**满足约束（两腰逐位相等）",
                  mApex.X == midX && D(mApex, mA2) == D(mApex, mB2),
                  $"顶点 ({mApex.X:F3},{mApex.Y:F3}) 期望 x={midX:F3}（指针本来在 "
                  + $"{mTriTo.X:F3}，被吸回来了），两腰 {D(mApex, mA2):F6} / {D(mApex, mB2):F6}");

            // ---- 椭圆拖轴端点（真机）：正圆 ----
            Doc.Clear();
            Doc.ClearHistory();
            float eCx = lx + 300f, eCy = ly - 300f;
            float eB0 = 200f + tol * 0.5f;             // b 比 a 大半个容差
            var mEll = new Stroke
            {
                Tool = Tool.Ellipse, Kind = StrokeKind.Ellipse,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 6f * DpiScale,
            };
            mEll.AddPoint(eCx, eCy, 1f, 0);
            // a 一开始**故意离 b 很远**（差了整整 100）：那样这一次拖动才有足够长的行程
            // （短于"点选容差"的拖动会被当成"点了一下"，不提交几何）。
            // 拖到最后一步时 a 落在 b 的容差里 → 才吸。
            mEll.AddPoint(eCx + 100f, eCy + eB0, 1f, 0);      // a = 100、b = eB0
            Doc.AddStroke(mEll);
            Doc.SelectOnly(new[] { mEll });
            SettleFrames(250);
            var mRim = SelectionHandles.ShapeHandleCanvasPosition(mEll, ShapeHandle.AxisRight);
            SelectionGestureForTest(mRim.X, mRim.Y);
            UpdateSelectionGestureForTest(eCx + eB0 + tol * 0.5f, eCy);   // 拖到 |a − b| = tol/2
            SettleFrames(80);
            Check("吸附（真机）：拖椭圆的轴端点、吸住时胶囊说得出「正圆」",
                  ShapeSnapKind == ShapeSnapKind.Circle
                  && SelectionHandles.ShapeSnapLabel(ShapeSnapKind) == "正圆",
                  $"吸到={ShapeSnapKind}（「{SelectionHandles.ShapeSnapLabel(ShapeSnapKind)}」）");
            EndSelectionGestureForTest();
            SettleFrames(200);
            Check("吸附（真机）：提交的几何是**正圆**（a、b 逐位相等）",
                  mEll.SemiAxisALocal == mEll.SemiAxisBLocal && mEll.SemiAxisALocal == eB0,
                  $"a={mEll.SemiAxisALocal:F6} b={mEll.SemiAxisBLocal:F6}（期望都等于 {eB0:F6}）");

            // ---- 矩形拖四角（真机）：正方形 ----
            Doc.Clear();
            Doc.ClearHistory();
            var mRect = new Stroke
            {
                Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 4f * DpiScale,
            };
            mRect.AddPoint(lx, ly, 1f, 0);
            mRect.AddPoint(lx + 300f, ly + 300f + tol * 0.5f, 1f, 0);
            Doc.AddStroke(mRect);
            Doc.SelectOnly(new[] { mRect });
            SettleFrames(250);
            var mFrame = SelectionHandles.FrameOf(Doc.Selected);
            var mCorner = SelectionHandles.CanvasPosition(SelHandle.BottomRight, mFrame, DpiScale);
            bool tookCorner = SelectionGestureForTest(mCorner.X, mCorner.Y);
            UpdateSelectionGestureForTest(mCorner.X + 200f, mCorner.Y + 200f);
            SettleFrames(80);
            Check("吸附（真机）：拖矩形的角、吸住时胶囊说得出「正方形」",
                  tookCorner && ShapeSnapKind == ShapeSnapKind.Square
                  && SelectionHandles.ShapeSnapLabel(ShapeSnapKind) == "正方形",
                  $"接住={tookCorner}，吸到={ShapeSnapKind}"
                  + $"（「{SelectionHandles.ShapeSnapLabel(ShapeSnapKind)}」）");
            EndSelectionGestureForTest();
            SettleFrames(200);
            var mRectBox = mRect.WorldInkBounds;
            Check("吸附（真机）：提交的几何是**精确**正方形",
                  Near(mRectBox.MaxX - mRectBox.MinX, mRectBox.MaxY - mRectBox.MinY, 0.01f),
                  $"框 {(mRectBox.MaxX - mRectBox.MinX):F3}×{(mRectBox.MaxY - mRectBox.MinY):F3}");

            // ---- 整体移动 / 旋转**不吸**（规格 9.6 第一条硬要求）----
            Doc.Clear();
            Doc.ClearHistory();
            var moveTri = new Stroke
            {
                Tool = Tool.Triangle, Kind = StrokeKind.Triangle,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 6f * DpiScale,
            };
            // 这个三角形**本来就在等腰的容差里**：如果整体移动 / 旋转也做形状吸附，
            // 三个顶点会被"修正"一个像素——自检就是盯这一条。
            moveTri.AddPoint(midX + tol * 0.25f, mY - 150f, 1f, 0);
            moveTri.AddPoint(mA, mY, 1f, 0);
            moveTri.AddPoint(mB, mY, 1f, 0);
            Doc.AddStroke(moveTri);
            Doc.SelectOnly(new[] { moveTri });
            SettleFrames(250);
            string movePts0 = $"{moveTri.Points[0].X},{moveTri.Points[0].Y}"
                            + $"|{moveTri.Points[1].X},{moveTri.Points[1].Y}"
                            + $"|{moveTri.Points[2].X},{moveTri.Points[2].Y}";
            var mvFrame = SelectionHandles.FrameOf(Doc.Selected);
            var mvCenter = new Vector2((mvFrame.CanvasAabb.MinX + mvFrame.CanvasAabb.MaxX) * 0.5f,
                                       (mvFrame.CanvasAabb.MinY + mvFrame.CanvasAabb.MaxY) * 0.5f);
            bool tookMove = SelectionGestureForTest(mvCenter.X, mvCenter.Y);
            UpdateSelectionGestureForTest(mvCenter.X + 150f, mvCenter.Y + 80f);
            SettleFrames(80);
            Check("整体移动不吸：拖的是位置，顶点一个都不动、也没有吸附",
                  tookMove && ShapeSnapKind == ShapeSnapKind.None
                  && movePts0 == $"{moveTri.Points[0].X},{moveTri.Points[0].Y}"
                             + $"|{moveTri.Points[1].X},{moveTri.Points[1].Y}"
                             + $"|{moveTri.Points[2].X},{moveTri.Points[2].Y}",
                  $"接住={tookMove}，吸到={ShapeSnapKind}，顶点原样（逐位）");
            EndSelectionGestureForTest();
            SettleFrames(200);
            var mvApex = SelectionHandles.ShapeHandleCanvasPosition(moveTri, ShapeHandle.Vertex0);
            Check("整体移动：真的挪了 (150,80)、顶点仍然逐位不变",
                  movePts0 == $"{moveTri.Points[0].X},{moveTri.Points[0].Y}"
                             + $"|{moveTri.Points[1].X},{moveTri.Points[1].Y}"
                             + $"|{moveTri.Points[2].X},{moveTri.Points[2].Y}"
                  && Near(mvApex.X - (midX + tol * 0.25f), 150f, 1f)
                  && Near(mvApex.Y - (mY - 150f), 80f, 1f),
                  $"顶点画布位移 ({mvApex.X - (midX + tol * 0.25f):F1},"
                  + $"{mvApex.Y - (mY - 150f):F1})，局部点逐位不变");
            Doc.Undo();
            SettleFrames(150);

            // 旋转：同样不该改顶点
            Doc.SelectOnly(new[] { moveTri });
            SettleFrames(200);
            var rotFrame2 = SelectionHandles.FrameOf(Doc.Selected);
            var rotPivot = new Vector2((rotFrame2.CanvasAabb.MinX + rotFrame2.CanvasAabb.MaxX) * 0.5f,
                                       (rotFrame2.CanvasAabb.MinY + rotFrame2.CanvasAabb.MaxY) * 0.5f);
            var rotGrip = SelectionHandles.CanvasPosition(SelHandle.Rotate, rotFrame2, DpiScale);
            float rotArm = Vector2.Distance(rotGrip, rotPivot);
            float rotA0 = MathF.Atan2(rotGrip.Y - rotPivot.Y, rotGrip.X - rotPivot.X);
            bool tookRot = SelectionGestureForTest(rotGrip.X, rotGrip.Y);
            // **旋转中不画框**（用户 2026-09-25 照 ClassIn 定）：框是轴对齐的，一转就每帧重贴
            // 内容、边角看着像在抖；转的当下也没人看框 —— 干脆收起来，松手再出现。
            // 量法：在**框上边那一段**数强调色（#0078D4）像素。
            // ⚠ 窗口必须**每次从"当前框"重算**（写成局部函数、两次调用各算一次）：
            //   转起来框会被重新贴合，窗口固定不动就量不到转后的边 —— 变异抽查时只差 16 像素，
            //   余量小到不够硬（2026-09-25 实测）。跟着当前框走，两边都压在"今天这个框的上边"，
            //   对比才有意义。
            int FrameTopPixels()
            {
                var bx = LiveSelectionFrame.CanvasAabb;
                return ScreenProbe.CountNear(
                    (int)bx.MinX, (int)(bx.MinY - 3f * DpiScale),
                    Math.Max(8, (int)((bx.MaxX - bx.MinX) * 0.6f)), Math.Max(4, (int)(8f * DpiScale)),
                    0, 120, 212, 60);
            }
            int framePixStatic = FrameTopPixels();

            var rp = new Vector2(rotPivot.X + rotArm * MathF.Cos(rotA0 - 0.35f),
                                 rotPivot.Y + rotArm * MathF.Sin(rotA0 - 0.35f));    // 逆时针 20°
            UpdateSelectionGestureForTest(rp.X, rp.Y);
            SettleFrames(80);
            int framePixRotating = FrameTopPixels();
            // 判据：静止时那一段**必须有**框的强调色（太少说明窗口没压住边、这条就白验了）；
            //       旋转中必须**一个都没有**。
            Check("旋转中**不画**选中框（ClassIn 的手感：转的时候没有矩形框）",
                  framePixStatic > 100 && framePixRotating == 0,
                  $"框上边那一段：静止 {framePixStatic} 像素 → 旋转中 {framePixRotating} 像素（期望 0）");
            Check("整体旋转不吸：转的时候顶点一个都不动、也没有形状吸附",
                  tookRot && SelRotating && ShapeSnapKind == ShapeSnapKind.None
                  && movePts0 == $"{moveTri.Points[0].X},{moveTri.Points[0].Y}"
                             + $"|{moveTri.Points[1].X},{moveTri.Points[1].Y}"
                             + $"|{moveTri.Points[2].X},{moveTri.Points[2].Y}",
                  $"接住={tookRot}，旋转中={SelRotating}，吸到={ShapeSnapKind}，顶点原样（逐位）");
            EndSelectionGestureForTest();
            SettleFrames(200);
            var rotM = moveTri.Transform;
            Check("整体旋转：变换是**纯旋转**（顶点逐位不变，只换了姿态）",
                  movePts0 == $"{moveTri.Points[0].X},{moveTri.Points[0].Y}"
                             + $"|{moveTri.Points[1].X},{moveTri.Points[1].Y}"
                             + $"|{moveTri.Points[2].X},{moveTri.Points[2].Y}"
                  && Near(rotM.M11 * rotM.M11 + rotM.M12 * rotM.M12, 1f, 1e-3f)
                  && Near(rotM.M21, -rotM.M12, 1e-3f) && Near(rotM.M22, rotM.M11, 1e-3f),
                  $"矩阵 ({rotM.M11:F4},{rotM.M12:F4},{rotM.M21:F4},{rotM.M22:F4})，顶点逐位不变");
        }

        // ================= N. 存档：圆 / 椭圆 / 三角形 / 平行四边形读回来逐位一致 =================
        //
        // 格式**没有加字段**（三角形的三个顶点、平行四边形的三个顶点都是普通控制点），
        // 只是多了两个 `Kind` 取值，所以升版本的理由和前几版一样：
        // 让不认识新 Kind 的老程序直接说"请升级"，而不是画出个残缺的形状；
        // 反方向（新程序读老文件）不受影响。
        Console.WriteLine("  -- N. 存档（圆 / 椭圆 / 三角形 / 平行四边形往返）--");
        {
            Doc.Clear();
            Doc.ClearHistory();
            var kCircle = new Stroke
            {
                Tool = Tool.Circle, Kind = StrokeKind.Circle,
                Color = new Color4(0.1f, 0.2f, 0.3f, 1f), Width = 6f,
            };
            kCircle.AddPoint(1000f, 500f, 1f, 0);
            kCircle.AddPoint(1180f, 500f, 1f, 0);
            var kEllipse = new Stroke
            {
                Tool = Tool.Ellipse, Kind = StrokeKind.Ellipse,
                Color = new Color4(0.3f, 0.2f, 0.1f, 1f), Width = 5f,
            };
            kEllipse.AddPoint(400f, 300f, 1f, 0);
            kEllipse.AddPoint(620f, 420f, 1f, 0);
            kEllipse.Transform = SelectionHandles.RotateMatrix(25f, new Vector2(400f, 300f));
            // 三角形 / 平行四边形也一起过一遍（第二批第②步新增的两个 Kind）
            var kTriangle = new Stroke
            {
                Tool = Tool.Triangle, Kind = StrokeKind.Triangle,
                Color = new Color4(0.2f, 0.5f, 0.3f, 1f), Width = 7f,
            };
            kTriangle.AddPoint(1500f, 400f, 1f, 0);
            kTriangle.AddPoint(1300f, 700f, 1f, 0);
            kTriangle.AddPoint(1750f, 700f, 1f, 0);
            kTriangle.Transform = SelectionHandles.RotateMatrix(-18f, new Vector2(1500f, 600f));
            var kPara = new Stroke
            {
                Tool = Tool.Parallelogram, Kind = StrokeKind.Parallelogram,
                Color = new Color4(0.5f, 0.2f, 0.4f, 1f), Width = 4f,
            };
            kPara.AddPoint(200f, 900f, 1f, 0);          // 底左
            kPara.AddPoint(520f, 900f, 1f, 0);          // 底右
            kPara.AddPoint(280f, 620f, 1f, 0);          // 顶左
            Doc.AddStroke(kCircle);
            Doc.AddStroke(kEllipse);
            Doc.AddStroke(kTriangle);
            Doc.AddStroke(kPara);

            var blob = InkSerializer.Save(Doc);
            var back = new InkDocument();
            InkSerializer.LoadInto(back, blob);

            // 这里**不再写死版本号**：这一条要验的是"文件头里写的 = 常量"，
            // 而不是"版本正好是 7"。写死数字的话，以后每次抬版本都要回来改一次
            // （2026-09-19 加坐标系 / 数轴抬到 9，这里就是当场红的那一条）。
            // `>= 7` 那一半仍然钉住"这一批的两个 Kind 存在 ⇒ 版本至少 7"。
            Check("存档：格式版本抬过 7、且文件头里写的就是常量",
                  InkSerializer.FormatVersion >= 7
                  && BitConverter.ToInt32(blob, 4) == InkSerializer.FormatVersion,
                  $"常量 {InkSerializer.FormatVersion}，文件头里的版本 {BitConverter.ToInt32(blob, 4)}");
            Check("存档：四个对象都读回来了（Kind 也对）",
                  back.Strokes.Count == 4
                  && back.Strokes[0].Kind == StrokeKind.Circle
                  && back.Strokes[1].Kind == StrokeKind.Ellipse
                  && back.Strokes[2].Kind == StrokeKind.Triangle
                  && back.Strokes[3].Kind == StrokeKind.Parallelogram,
                  $"对象 {back.Strokes.Count} 个，Kind = {back.Strokes[0].Kind} / {back.Strokes[1].Kind}"
                  + $" / {back.Strokes[2].Kind} / {back.Strokes[3].Kind}");

            var bc = back.Strokes[0];
            var be = back.Strokes[1];
            var bt = back.Strokes[2];
            var bp = back.Strokes[3];
            Check("存档：圆的圆心 / 半径逐位一致",
                  bc.Points[0].X == kCircle.Points[0].X && bc.Points[0].Y == kCircle.Points[0].Y
                  && bc.Points[1].X == kCircle.Points[1].X && bc.Points[1].Y == kCircle.Points[1].Y
                  && bc.CircleRadiusLocal == kCircle.CircleRadiusLocal,
                  $"圆心 ({bc.Points[0].X:F1},{bc.Points[0].Y:F1})，半径 {bc.CircleRadiusLocal:F3}");
            Check("存档：椭圆的中心 / 半轴 / 变换逐位一致",
                  be.Points[0].X == kEllipse.Points[0].X && be.Points[0].Y == kEllipse.Points[0].Y
                  && be.SemiAxisALocal == kEllipse.SemiAxisALocal
                  && be.SemiAxisBLocal == kEllipse.SemiAxisBLocal
                  && be.Transform.Equals(kEllipse.Transform),
                  $"中心 ({be.Points[0].X:F1},{be.Points[0].Y:F1})，"
                  + $"a={be.SemiAxisALocal:F1} b={be.SemiAxisBLocal:F1}");
            Check("存档：紧框与原件一致（口径也跟着存下来的点走）",
                  bc.WorldInkBounds.MaxX == kCircle.WorldInkBounds.MaxX
                  && be.WorldInkBounds.MaxY == kEllipse.WorldInkBounds.MaxY,
                  $"圆框 {bc.WorldInkBounds.MaxX - bc.WorldInkBounds.MinX:F1}"
                  + $"/{kCircle.WorldInkBounds.MaxX - kCircle.WorldInkBounds.MinX:F1}，"
                  + $"椭圆框 {be.WorldInkBounds.MaxY - be.WorldInkBounds.MinY:F1}"
                  + $"/{kEllipse.WorldInkBounds.MaxY - kEllipse.WorldInkBounds.MinY:F1}");
            Check("存档：三角形的三个顶点 / 变换逐位一致",
                  bt.Points.Count == 3
                  && bt.Points[0].X == kTriangle.Points[0].X && bt.Points[0].Y == kTriangle.Points[0].Y
                  && bt.Points[1].X == kTriangle.Points[1].X && bt.Points[1].Y == kTriangle.Points[1].Y
                  && bt.Points[2].X == kTriangle.Points[2].X && bt.Points[2].Y == kTriangle.Points[2].Y
                  && bt.Transform.Equals(kTriangle.Transform),
                  $"顶点0 ({bt.Points[0].X:F1},{bt.Points[0].Y:F1})，变换 {bt.Transform.M11:F4}");
            Check("存档：平行四边形的三个顶点逐位一致（第四个读回来仍是公式推出来的）",
                  bp.Points.Count == 3
                  && bp.Points[0].X == kPara.Points[0].X && bp.Points[0].Y == kPara.Points[0].Y
                  && bp.Points[1].X == kPara.Points[1].X && bp.Points[1].Y == kPara.Points[1].Y
                  && bp.Points[2].X == kPara.Points[2].X && bp.Points[2].Y == kPara.Points[2].Y
                  && bp.ParallelogramFourthLocal() == kPara.ParallelogramFourthLocal(),
                  $"第四个顶点 ({bp.ParallelogramFourthLocal().X:F1},"
                  + $"{bp.ParallelogramFourthLocal().Y:F1})");
            Check("存档：两个多边形的紧框与原件一致",
                  bt.WorldInkBounds.MinX == kTriangle.WorldInkBounds.MinX
                  && bt.WorldInkBounds.MaxY == kTriangle.WorldInkBounds.MaxY
                  && bp.WorldInkBounds.MinY == kPara.WorldInkBounds.MinY
                  && bp.WorldInkBounds.MaxX == kPara.WorldInkBounds.MaxX,
                  $"三角框 {bt.WorldInkBounds.MaxX - bt.WorldInkBounds.MinX:F1}"
                  + $"/{kTriangle.WorldInkBounds.MaxX - kTriangle.WorldInkBounds.MinX:F1}，"
                  + $"平四框 {bp.WorldInkBounds.MaxX - bp.WorldInkBounds.MinX:F1}"
                  + $"/{kPara.WorldInkBounds.MaxX - kPara.WorldInkBounds.MinX:F1}");
        }

        // ================= O. 拉伸中的形体完整性（缺块 / 残影）=================
        //
        // 用户真机反馈（2026-09-19）："椭圆 / 圆在拉伸的时候有时候会消失一部分"。
        //
        // **触发条件**（"有时候"的那个"有时候"）：拉伸让形体跨过**分块边界**
        // （块边长 256 画布像素）。根因在内容层这一头，两步：
        //   ① 起手那一刻形体被摘出内容层（DetachForDrag），它压过的分块整块重画一次
        //      ——那次是**不带它**画的，于是那些块上留着一个"洞"；
        //   ② 松手提交几何时，新位置的脏区由 Stroke.PaddedBoundsOf 算。它以前对圆 / 椭圆
        //      退化成"圆心 + 圆周点这两个点的外接"——那只是形体的一角（椭圆的四分之一），
        //      于是**左边的分块没被标脏**，洞永远补不上：屏幕上就是"形体缺一大块"，
        //      而缺到哪一刀正好落在分块边界上（所以是"有时候"）。
        // 拖动过程本身是好的（浮动层按"实时框"画临时几何，框是完整的），
        // 所以症状总在**手一松的那一瞬**露出来。这一节把它钉死：
        //   · 放大（未松手）：被拖手柄那一侧的远端、对面那个极端点、以及另一条半轴的
        //     两个极端点，四处都必须有墨——缺一块就会被抓到；
        //   · 缩小（未松手）：旧形体外侧不许留墨（残影会被抓到），新形体外侧必须有墨；
        //   · 松手后：整块墨量必须等于"整层作废重画"的墨量（= 静止态直接画出来）。
        Console.WriteLine("  -- O. 拉伸中的形体完整性（缺块 / 残影）--");
        {
            ViewOffsetY = 0f;                       // 屏幕坐标 == 画布坐标，探针才好对位
            foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }

            // 探针窗口半径（物理像素）。**别开太大**：拖元素时的读数胶囊挂在被拖的那个点
            // **上方**（间距 ≈ 21 逻辑像素），开大了会把胶囊的底色算进来。
            const int ProbeHalf = 12;
            // "这一处有墨"的门槛：8 逻辑像素宽的笔画在 24×24 的窗里约 190 个核心像素，
            // 门槛给 60 足够宽裕，又能把"整条弧少了一截"抓出来。
            const int HasInk = 60, NoInk = 20;

            int Ink(float x, float y)
                => ScreenProbe.CountMagenta((int)x - ProbeHalf, (int)y - ProbeHalf,
                                            ProbeHalf * 2, ProbeHalf * 2);

            // 形体整块的墨量（按墨迹框四边各放 20 物理像素量）。缺一块会当场少一大截。
            int WholeInk(Stroke s)
            {
                var b = s.WorldInkBounds;
                return ScreenProbe.CountMagenta((int)b.MinX - 20, (int)b.MinY - 20,
                                                (int)(b.MaxX - b.MinX) + 40, (int)(b.MaxY - b.MinY) + 40);
            }

            // 拖一次尺寸手柄：放大 → 缩小 → 松手，全程盯"缺块 / 残影"。
            //   · `dir`     = 从中心出发、被拖那个手柄的单位方向（右轴端点 = (+1,0)…）；
            //   · `r0`      = 起手时沿着 `dir` 的那条半轴（圆的半径）长度；
            //   · `other0`  = 另一条半轴的长度（圆与 `r0` 相同）；
            //   · `rGrow` / `rShrink` = 放大 / 缩小到多少（两次拖的是同一个手柄）。
            void ResizeCase(string name, StrokeKind kind, float cx, float cy,
                            ShapeHandle handle, Vector2 dir, float r0, float other0,
                            float rGrow, float rShrink)
            {
                Doc.Clear();
                Doc.ClearHistory();
                Tool = Tool.Marquee;
                var s = new Stroke
                {
                    Tool = kind == StrokeKind.Circle ? Tool.Circle : Tool.Ellipse,
                    Kind = kind, Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
                };
                s.AddPoint(cx, cy, 1f, 0);                       // 中心 / 圆心
                if (kind == StrokeKind.Circle)                   // 圆周点：沿着 dir，半径 r0
                    s.AddPoint(cx + dir.X * r0, cy + dir.Y * r0, 1f, 0);
                else
                {
                    // 外角点：**横着的那条半轴总是 a、竖着的那条总是 b**（和拖的哪个手柄无关）。
                    // 所以"被拖的那条半轴是 r0、另一条是 other0"要按 dir 落到 a / b 上。
                    float a = MathF.Abs(dir.X) > 0.5f ? r0 : other0;
                    float b = MathF.Abs(dir.Y) > 0.5f ? r0 : other0;
                    s.AddPoint(cx + a, cy + b, 1f, 0);
                }
                Doc.AddStroke(s);
                Doc.SelectOnly(new[] { s });
                SettleFrames(300);

                var perp = new Vector2(-dir.Y, dir.X);           // 另一条半轴的方向
                // 四个极端点：沿被拖那条半轴的远端 / 近端，以及另一条半轴的两端。
                Vector2 Far(float along) => new(cx + dir.X * along, cy + dir.Y * along);
                Vector2 Near(float along) => new(cx - dir.X * along, cy - dir.Y * along);
                Vector2 Side(float across, float sign)
                    => new(cx + perp.X * across * sign, cy + perp.Y * across * sign);

                // 按下手柄（真走一次选择手势的分流，和用户手拖是同一条路）。
                // 顺手对一次"手柄在哪"：这里算的 Far(r0) 必须就是引擎给的那个手柄位置，
                // 否则探针盯的地方和用户拖的地方不是一回事（判据自己会骗自己）。
                var handlePos = SelectionHandles.ShapeHandleCanvasPosition(s, handle);
                bool took = SelectionGestureForTest(handlePos.X, handlePos.Y);
                Check($"{name}：{handle} 手柄就在被拖那条半轴的端点上",
                      MathF.Abs(handlePos.X - Far(r0).X) < 0.5f && MathF.Abs(handlePos.Y - Far(r0).Y) < 0.5f,
                      $"手柄 ({handlePos.X:F1},{handlePos.Y:F1}) 期望 ({Far(r0).X:F1},{Far(r0).Y:F1})");
                // **一帧跳到位**：这一步正是真机上"拖快了"的那一帧。
                var growTo = Far(rGrow);
                UpdateSelectionGestureForTest(growTo.X, growTo.Y);
                SettleFrames(120);
                int farGrow = Ink(growTo.X, growTo.Y);
                int nearGrow = Ink(Near(rGrow).X, Near(rGrow).Y);
                var sideA = Side(kind == StrokeKind.Circle ? rGrow : other0, +1f);
                var sideB = Side(kind == StrokeKind.Circle ? rGrow : other0, -1f);
                int sideAGrow = Ink(sideA.X, sideA.Y);
                int sideBGrow = Ink(sideB.X, sideB.Y);
                Check($"{name}：放大中被拖那一侧的远端有墨（缺一块会在这儿露）",
                      took && VertexDragging && farGrow > HasInk,
                      $"远端 ({growTo.X:F0},{growTo.Y:F0}) {farGrow} 像素（期望 >{HasInk}）");
                Check($"{name}：放大中对面那个极端点有墨",
                      nearGrow > HasInk, $"对面 {nearGrow} 像素（期望 >{HasInk}）");
                Check($"{name}：放大中另一条半轴的两个极端点都有墨",
                      sideAGrow > HasInk && sideBGrow > HasInk,
                      $"两个极端点 {sideAGrow} / {sideBGrow} 像素（期望都 >{HasInk}）");

                // 缩小：同一个手柄往回收（rGrow → rShrink，且 rShrink < r0）。
                var shrinkTo = Far(rShrink);
                UpdateSelectionGestureForTest(shrinkTo.X, shrinkTo.Y);
                SettleFrames(120);
                int farShrink = Ink(shrinkTo.X, shrinkTo.Y);
                int nearShrink = Ink(Near(rShrink).X, Near(rShrink).Y);
                int oldResidue = Ink(growTo.X, growTo.Y);      // 放大时待过的地方：必须干净
                Check($"{name}：缩小后新形体外侧有墨",
                      farShrink > HasInk, $"新远端 {farShrink} 像素（期望 >{HasInk}）");
                Check($"{name}：缩小后对面那个极端点也有墨",
                      nearShrink > HasInk, $"对面 {nearShrink} 像素（期望 >{HasInk}）");
                Check($"{name}：缩小后旧形体外侧不留墨（残影）",
                      oldResidue < NoInk, $"放大时待过的 ({growTo.X:F0},{growTo.Y:F0}) 还剩 {oldResidue} 像素（期望 <{NoInk}）");

                // 松手：模型这才改，屏幕改由内容层那一份来画。
                EndSelectionGestureForTest();
                SettleFrames(250);
                // **先取消选中再量**：手柄方块正好压在被拖的那个端点上，带着选中量会把
                // "手柄盖住了弧"当成"缺了一块"（这条自检第一版就是这么误报的）。
                Doc.Selected.Clear();
                SettleFrames(250);
                int afterFar = Ink(shrinkTo.X, shrinkTo.Y);
                int afterOld = Ink(growTo.X, growTo.Y);
                int commitInk = WholeInk(s);
                Check($"{name}：松手后探针与拖动中一致（还是那条几何）",
                      afterFar > HasInk && afterOld < NoInk,
                      $"远端 {farShrink} → {afterFar} 像素；旧位 {afterOld} 像素");
                // **最硬的一条**：松手后的墨量 == 把内容层整层作废重画的墨量。
                // 后者就是"静止态直接画出来"，只差一点抗锯齿接缝（实测 <1%）。
                // 脏区算窄了 → 有分块从没重画过 → 这一条当场掉下去（修之前 6936 / 12636）。
                Doc.InvalidateAll();
                SettleFrames(300);
                int fullInk = WholeInk(s);
                Check($"{name}：松手后整块墨量 = 整层重画（脏区算窄了就会缺一块）",
                      commitInk >= (int)(fullInk * 0.97f),
                      $"松手 {commitInk} vs 整层重画 {fullInk} 像素");
                Doc.Undo();
                SettleFrames(150);
            }

            // 圆拖圆周点（半径 240 → 520 → 140）。另一条半轴 = 半径，跟着一起变。
            ResizeCase("圆·拖圆周点", StrokeKind.Circle, lx + 900f, ly - 300f,
                       ShapeHandle.Rim, new Vector2(1f, 0f), 240f, 240f, 520f, 140f);

            // 椭圆拖两个轴端点（a/b 起手 240/120）：横着、竖着各放大缩小一次。
            // **只有右端点和上端点两条**（用户 2026-09-20 精简：原来左右都管 a、上下都管 b，
            // 各留一个）。"缩小"这一半由 rShrink 覆盖，不依赖另一个手柄。
            ResizeCase("椭圆·拖右端点（管 a）", StrokeKind.Ellipse, lx + 900f, ly - 300f,
                       ShapeHandle.AxisRight, new Vector2(1f, 0f), 240f, 120f, 520f, 140f);
            ResizeCase("椭圆·拖上端点（管 b）", StrokeKind.Ellipse, lx + 900f, ly - 300f,
                       ShapeHandle.AxisTop, new Vector2(0f, -1f), 120f, 240f, 360f, 70f);

            // ---- 顺手检查：三角形 / 平行四边形拖顶点、矩形拖角，有没有同类问题 ----
            //
            // 它们和圆 / 椭圆走的是**同一条"提交时算新几何包围盒"的路**
            // （SetStrokeGeometryAction → Stroke.PaddedBoundsOf），所以一起验。
            // 判据只有一条但很硬：松手后的整块墨量必须等于"整层作废重画"的墨量。
            // （按道理它们是绿的：三角形的三个顶点、平行四边形的四个顶点、矩形的两个对角点，
            //   "点的外接"本来就等于形体自己的外接——但验过才算数。）
            void DragReleaseCase(string name, Stroke s, Vector2 from, Vector2 to, Vector2 oldSpot)
            {
                Doc.Clear();
                Doc.ClearHistory();
                Tool = Tool.Marquee;
                Doc.AddStroke(s);
                Doc.SelectOnly(new[] { s });
                SettleFrames(300);

                var before = s.WorldInkBounds;
                bool took = SelectionGestureForTest(from.X, from.Y);
                UpdateSelectionGestureForTest(to.X, to.Y);
                SettleFrames(120);
                EndSelectionGestureForTest();
                SettleFrames(250);
                Doc.Selected.Clear();                  // 手柄 / 框会盖住形体，先取消选中再量
                SettleFrames(250);

                int commitInk = WholeInk(s);
                int oldInk = Ink(oldSpot.X, oldSpot.Y);
                Check($"{name}：拖到手了（几何真的变了）",
                      took && s.WorldInkBounds.MaxX > before.MaxX + 1f,
                      $"接住={took}，框右边界 {before.MaxX:F0} → {s.WorldInkBounds.MaxX:F0}");
                Check($"{name}：搬走的那一头不留墨（残影）",
                      oldInk < NoInk, $"旧位 ({oldSpot.X:F0},{oldSpot.Y:F0}) 还剩 {oldInk} 像素（期望 <{NoInk}）");
                Doc.InvalidateAll();
                SettleFrames(300);
                int fullInk = WholeInk(s);
                Check($"{name}：松手后整块墨量 = 整层重画（脏区算窄了就会缺一块）",
                      commitInk >= (int)(fullInk * 0.97f),
                      $"松手 {commitInk} vs 整层重画 {fullInk} 像素");
            }

            {   // 三角形：拖那个上顶点，往右搬一大段（跨分块边界的拖法）
                var t = new Stroke
                {
                    Tool = Tool.Triangle, Kind = StrokeKind.Triangle,
                    Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
                };
                t.AddPoint(lx + 900f, ly - 700f, 1f, 0);        // 上中
                t.AddPoint(lx + 600f, ly - 260f, 1f, 0);        // 下左
                t.AddPoint(lx + 1200f, ly - 260f, 1f, 0);       // 下右
                var from = SelectionHandles.ShapeHandleCanvasPosition(t, ShapeHandle.Vertex0);
                DragReleaseCase("三角形·拖顶点", t, from, new Vector2(from.X + 460f, from.Y - 120f), from);
            }

            {   // 平行四边形：拖右下那个顶点（它一动，现推的第四个顶点跟着动）
                var q = new Stroke
                {
                    Tool = Tool.Parallelogram, Kind = StrokeKind.Parallelogram,
                    Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
                };
                q.AddPoint(lx + 600f, ly - 260f, 1f, 0);        // 底左
                q.AddPoint(lx + 1200f, ly - 260f, 1f, 0);       // 底右
                q.AddPoint(lx + 750f, ly - 700f, 1f, 0);        // 顶左
                var from = SelectionHandles.ShapeHandleCanvasPosition(q, ShapeHandle.Vertex1);
                DragReleaseCase("平行四边形·拖顶点", q, from, new Vector2(from.X + 420f, from.Y - 90f), from);
            }

            {   // 箭头：拖端点。箭头的翅膀尖伸到轴外 ~22 像素（比端点外接宽），
                // 所以它是最像"脏区算窄"的那一个——验下来**没有**这条毛病：
                // 那 22 像素远小于块边长 256，漏掉的那一小条永远和端点带同处一块，
                // 块照样被标脏、照样重画（下面这条判据绿着就是证据）。
                var ar = new Stroke
                {
                    Tool = Tool.Arrow, Kind = StrokeKind.Arrow,
                    Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
                };
                ar.AddPoint(lx + 600f, ly - 700f, 1f, 0);       // 尾
                ar.AddPoint(lx + 1250f, ly - 700f, 1f, 0);      // 头（水平 → 翅膀在轴上下各 ~22 像素）
                var from = SelectionHandles.ShapeHandleCanvasPosition(ar, ShapeHandle.Rim);
                DragReleaseCase("箭头·拖端点", ar, from, new Vector2(from.X + 320f, from.Y - 300f), from);
            }

            {   // 矩形：拖右下角。这条走的是**另一条路**（缩放矩阵，不是改几何），
                // 所以单独写：提交的是 TransformObjectsAction（脏区按 PaddedBounds 算）。
                var r = new Stroke
                {
                    Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
                    Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
                };
                r.AddPoint(lx + 600f, ly - 700f, 1f, 0);        // 左上
                r.AddPoint(lx + 1100f, ly - 300f, 1f, 0);       // 右下
                Doc.Clear();
                Doc.ClearHistory();
                Tool = Tool.Marquee;
                Doc.AddStroke(r);
                Doc.SelectOnly(new[] { r });
                SettleFrames(300);

                var rectFrame = SelectionHandles.FrameOf(Doc.Selected);
                var corner = SelectionHandles.CanvasPosition(SelHandle.BottomRight, rectFrame, DpiScale);
                var rectBefore = r.WorldInkBounds;
                bool rectTook = SelectionGestureForTest(corner.X, corner.Y);
                // 角往右下拖：矩形被放大（对角那个角钉住不动）
                UpdateSelectionGestureForTest(corner.X + 380f, corner.Y + 220f);
                SettleFrames(120);
                EndSelectionGestureForTest();
                SettleFrames(250);
                Doc.Selected.Clear();
                SettleFrames(250);
                int commitInk = WholeInk(r);
                Doc.InvalidateAll();
                SettleFrames(300);
                int fullInk = WholeInk(r);
                Check("矩形·拖角放大：墨量 = 整层重画 + 右下角确实出去了",
                      rectTook && r.WorldInkBounds.MaxX > rectBefore.MaxX + 1f && commitInk >= (int)(fullInk * 0.97f),
                      $"接住={rectTook}，框右边界 {rectBefore.MaxX:F0} → {r.WorldInkBounds.MaxX:F0}，"
                      + $"松手 {commitInk} vs 整层重画 {fullInk} 像素");
            }
        }

        // 线宽**不跟着缩放**（用户 2026-09-13 拍板、2026-09-20 落地）：
        // 横着把一个矩形拉 3 倍，四条边该多粗还是多粗。
        // 判据用"数墨"——数出来的是屏幕上真看到的东西，比查矩阵可靠。
        Console.WriteLine("  -- P. 拉伸 / 旋转时线宽不变（图形）--");
        {
            ViewOffsetY = 0f;
            foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }

            var rs = new Stroke
            {
                Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 8f * DpiScale,
            };
            rs.AddPoint(700f, 320f, 1f, 0);
            rs.AddPoint(1000f, 520f, 1f, 0);

            Doc.Clear();
            Doc.ClearHistory();
            Tool = Tool.Marquee;
            Doc.AddStroke(rs);
            Doc.Selected.Clear();
            Doc.InvalidateAll();
            SettleFrames(300);

            // 沿一条扫描线数**连续的墨**，返回最长的一段 = 那条边看起来有多粗（物理像素）
            int ThickAcrossY(float x, float yFrom, float yTo)      // 竖着扫：量横边
            {
                int run = 0, best = 0;
                for (int y = (int)yFrom; y <= (int)yTo; y++)
                {
                    if (ScreenProbe.CountMagenta((int)x, y, 2, 1) > 0) { run++; best = Math.Max(best, run); }
                    else run = 0;
                }
                return best;
            }
            int ThickAcrossX(float y, float xFrom, float xTo)      // 横着扫：量竖边
            {
                int run = 0, best = 0;
                for (int x = (int)xFrom; x <= (int)xTo; x++)
                {
                    if (ScreenProbe.CountMagenta(x, (int)y, 1, 2) > 0) { run++; best = Math.Max(best, run); }
                    else run = 0;
                }
                return best;
            }

            int top0 = ThickAcrossY(850f, 300f, 345f);         // 上边（y = 320 那条）
            int right0 = ThickAcrossX(420f, 975f, 1025f);      // 右边（x = 1000 那条）

            // 用**真手势**拖右中柄（横向拉长、纵向不动）——和用户的手一模一样，
            // 也顺便验了"缩放手势提交之后屏幕上的线宽"。
            Doc.SelectOnly(new[] { rs });
            SettleFrames(200);
            var rFrame = SelectionHandles.FrameOf(Doc.Selected);
            var rMid = SelectionHandles.CanvasPosition(SelHandle.Right, rFrame, DpiScale);
            bool rTook = SelectionGestureForTest(rMid.X, rMid.Y);
            UpdateSelectionGestureForTest(rMid.X + 700f, rMid.Y);     // 右边往右拖 700 → 横向拉长
            SettleFrames(150);
            EndSelectionGestureForTest();
            SettleFrames(250);
            Doc.Selected.Clear();
            SettleFrames(250);

            int top1 = ThickAcrossY(1200f, 300f, 345f);        // 上边中段（现在伸到 x = 1700）
            int right1 = ThickAcrossX(420f, 1655f, 1710f);     // 右边（被拖到 x ≈ 1682）
            Check("拖右中柄横拉：**横边**粗细不变（拉伸只改形状，不改线宽）",
                  rTook && top0 >= 6 && Math.Abs(top1 - top0) <= 2,
                  $"接住={rTook}，上边 {top0} → {top1} 物理像素");
            Check("拖右中柄横拉：**竖边**粗细也不变（老做法这里会粗 3 倍，看着像书法笔）",
                  rTook && rs.WorldBounds.MaxX > 1400f && right0 >= 6 && Math.Abs(right1 - right0) <= 2,
                  $"框右边界 {rs.WorldBounds.MaxX:F0}，右边 {right0} → {right1} 物理像素"
                  + $"（老做法约 {right0 * 3}）");

            // 规则本身也钉一条：**图形**不跟着缩放、**手写墨迹**跟着缩放（像图片一样）。
            // 免得以后有人把"线宽不变"顺手套到笔迹上，或者反过来把图形漏掉。
            var inkProbe = new Stroke { Tool = Tool.Pen };          // 自由笔迹
            var shapeProbe = new Stroke { Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle };
            shapeProbe.AddPoint(0f, 0f, 1f, 0);
            shapeProbe.AddPoint(10f, 10f, 1f, 0);
            Check("规则：图形 KeepsWidth=true、手写墨迹=false、图像=false（三种各归各位）",
                  shapeProbe.KeepsWidth && !inkProbe.KeepsWidth
                  && !new Stroke { Kind = StrokeKind.Image }.KeepsWidth,
                  $"矩形 {shapeProbe.KeepsWidth}、笔迹 {inkProbe.KeepsWidth}");
        }

        Console.WriteLine();
        Console.WriteLine(fail == 0
            ? $"  PASS: 图形工具（画图入口 / 吸附 / 端点编辑）都正确（{pass} 项）"
            : $"  FAIL: {fail} 项不对（{pass} 项通过）");
        Doc.Clear();
        Doc.ClearHistory();
        _quit = true;
    }

    /// <summary>
    /// 图形工具摆样出图（离屏，锁屏 / 远程也能出）。
    ///
    ///   · `--shapetoolshow &lt;图&gt;`：**选中一条直线**——两个端点手柄 + 旋转柄；
    ///   · `--shapetoolshow &lt;图&gt; --drag`：**拖端点中**——临时几何 + 倾斜角读数 α；
    ///   · `--shapetoolshow &lt;图&gt; --draw`：**正在画一条直线**——实时几何 + α 读数
    ///     （2026-09-18 用户要的"画线时也要显示 α"）；
    ///   · `--shapetoolshow &lt;图&gt; --rotate`：**旋转拖动中**——给用户核对
    ///     "转的时候那个框看着不对劲"（2026-09-18 的第三条）；
    ///   · `--shapetoolshow &lt;图&gt; --rotated`：**已经转过 60° 的线**、静止选中
    ///     （紧框改口径前后的对照：旧口径下这张同样是虚胖的）；
    ///   · `--shapetoolshow &lt;图&gt; --circle / --ellipse / --triangle / --parallelogram`：
    ///     **那个图形静止选中**——给第二批①（圆 / 椭圆）补出图、并新增②（三角形 /
    ///     平行四边形）那两张，看的是"手柄是不是只有定义元素那几个、第四个角有没有手柄"；
    ///   · 再加 `--snap`：把被拖的顶点拖到"会在容差里"的位置停住，
    ///     拍下**吸附生效的那一帧**（胶囊上写「等边」这类字，强调色）。
    ///   · `--rectangle` + `--pose`：**拖旋转柄**、拍姿态角读数那一帧（矩形停在吸住的 0°）；
    ///   · `--ellipse` + `--pose`：**歪椭圆拖到吸住的 90°**（用户提这个需求的初衷）；
    ///   · `--triangle` + `--angles`：**拖着一个顶点、不松手**，拍三个内角那一帧
    ///     （**没有**"内角和"那一行，用户 2026-09-19 定："显示和太乱"；
    ///      2026-09-20 又定"三角形改成**拖动时才显示**"，所以这张也必须拖着拍）；
    ///   · `--parallelogram` + `--angles`：拖一个顶点、拍两个夹角那一帧。
    ///
    /// 为什么这几张必须出图而不是靠自检：手柄的样子、标签的位置与排版**只能看**，
    /// 几何全对也一样难看（这是仓库里"出图"这一组的由来）。
    ///
    ///   · 再加 `--autosel`（2026-09-22）：**画完自动选中那个框**那一帧——真机拖一个矩形、
    ///     松手之后**工具还是矩形**，框只有"框 ＋ 手柄 ＋ 旋转柄"、**没有操作条**
    ///    （那一条只在框选工具下出现，理由见 `Engine.SelectionBarShown`）。
    ///     这张图看的就是"没有一个条挂在下面"这件事本身。
    /// </summary>
    private void ShapeToolShowcase(string path, string kind, bool drag, bool drawing,
                                   bool rotate, bool rotated, bool snap,
                                   bool angleRead, bool poseRead, bool autoSel)
    {
        BoardOn = true;                       // 白底：手柄压在桌面上看不清
        SetUiFactory(() => new InkUi.FullUi());   // 浮层配色/投影由界面推上来
        Doc.Clear();
        Doc.ClearHistory();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }

        float cx = _virtualX + _virtualW * 0.5f, cy = _virtualY + _virtualH * 0.5f;

        // ---- `--autosel`：**画完自动选中那一帧**（2026-09-22）----
        //
        // 真机拖一个矩形、松手，拍"刚画完"的样子。要看的是两件事：
        //   ① 框在（框 ＋ 八个手柄 ＋ 旋转柄）；
        //   ② **下面没有操作条**——图形工具下那一条不画（见 Engine.SelectionBarShown），
        //      因为它正好挂在图形正下方，会吃掉"接着画下一个"的那一下。
        // 出图范围因此刻意**往下多留一段**：不往下留的话，"有没有条"这件事看不出来。
        if (autoSel)
        {
            SetToolFromUi(Tool.Rectangle);
            var aFrom = new Vector2(cx - 260f, cy - 170f);
            var aTo = new Vector2(cx + 260f, cy + 170f);
            SendMouse((int)aFrom.X, (int)aFrom.Y, 0);                            SettleFrames(60);
            SendMouse((int)aFrom.X, (int)aFrom.Y, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
            for (int i = 1; i <= 4; i++)
            {
                SendMouse((int)(aFrom.X + (aTo.X - aFrom.X) * i / 4f),
                          (int)(aFrom.Y + (aTo.Y - aFrom.Y) * i / 4f), 0);
                SettleFrames(40);
            }
            SendMouse((int)aTo.X, (int)aTo.Y, Native.MOUSEEVENTF_LEFTUP);
            SettleFrames(400);                       // 松手 → 自动选中，等它画完

            Console.WriteLine($"画完自动选中：对象 {Doc.Strokes.Count} 个，"
                            + $"选中 {Doc.Selected.Count} 个，工具还是 {Host.State.Tool}，"
                            + $"操作条画不画 = {SelectionBarShown}");

            var sel = SelectionHandles.FrameOf(Doc.Selected);
            var shot = sel.CanvasAabb;
            // 旋转柄在框上方外侧，单独并进来（它不在 aabb 里）。
            var grip = SelectionHandles.CanvasPosition(SelHandle.Rotate, sel, DpiScale);
            shot.Add(grip.X - 40f, grip.Y - 40f);
            shot.Add(grip.X + 40f, grip.Y + 40f);
            // **往下多留 120 逻辑像素**：那正是"操作条本该出现的地方"
            //（`SelectionHandles.BarOffsetLogical` 起算），留出来才看得出它不在。
            shot.Add(shot.MinX, shot.MaxY + 120f * DpiScale);
            if (!OffscreenFloatingShot(path, shot.Inflate(30f))) Console.WriteLine("出图失败");
            _quit = true;
            return;
        }

        // ---- 第③轮（读数）那几张 ----
        // `--pose`：拖旋转柄 → 姿态角读数（矩形停在吸住的 **0°**、椭圆停在 **90°**）。
        if (poseRead)
        {
            bool isRect = kind != "ellipse";
            var sh = new Stroke
            {
                Color = new Color4(0.11f, 0.12f, 0.15f, 1f), Width = 6f * DpiScale,
            };
            // 起手都是"歪的"：矩形 8°（差一点点就正）、椭圆 52°（很明显是歪的）。
            float startDeg = isRect ? 8f : 52f;
            var center = new Vector2(cx, cy);
            if (isRect)
            {
                sh.Tool = Tool.Rectangle; sh.Kind = StrokeKind.Rectangle;
                sh.AddPoint(center.X - 320f, center.Y - 200f, 1f, 0);
                sh.AddPoint(center.X + 320f, center.Y + 200f, 1f, 0);
            }
            else
            {
                sh.Tool = Tool.Ellipse; sh.Kind = StrokeKind.Ellipse;
                sh.AddPoint(center.X, center.Y, 1f, 0);              // 中心
                sh.AddPoint(center.X + 330f, center.Y + 150f, 1f, 0); // 外角点（a=330, b=150）
            }
            sh.Transform = SelectionHandles.RotateMatrix(startDeg, center);
            Doc.AddStroke(sh);
            Doc.SelectOnly(new[] { sh });
            Tool = Tool.Marquee;
            Doc.InvalidateAll();
            SettleFrames(700);

            var f0 = SelectionHandles.FrameOf(Doc.Selected);
            var pv = new Vector2((f0.CanvasAabb.MinX + f0.CanvasAabb.MaxX) * 0.5f,
                                 (f0.CanvasAabb.MinY + f0.CanvasAabb.MaxY) * 0.5f);
            var grip = SelectionHandles.CanvasPosition(SelHandle.Rotate, f0, DpiScale);
            float arm = Vector2.Distance(grip, pv);
            float a0 = MathF.Atan2(grip.Y - pv.Y, grip.X - pv.X);
            // 要转到哪儿：矩形顺时针 8.4°（8 → -0.4，±1° 内 → 吸到 0）；
            //          椭圆逆时针 38.4°（52 → 90.4，±1° 内 → 吸到 90）。
            float turn = isRect ? -8.4f : 38.4f;

            SendMouse((int)grip.X, (int)grip.Y, 0);                          SettleFrames(60);
            SendMouse((int)grip.X, (int)grip.Y, Native.MOUSEEVENTF_LEFTDOWN); SettleFrames(60);
            var last = grip;
            for (int i = 1; i <= 4; i++)
            {
                // 屏幕坐标 y 朝下：方向角**减小**才是视觉上的逆时针，所以 rad = a0 − 转过的角。
                float rad = a0 - turn * i / 4f * MathF.PI / 180f;
                last = new Vector2(pv.X + arm * MathF.Cos(rad), pv.Y + arm * MathF.Sin(rad));
                SendMouse((int)last.X, (int)last.Y, 0);
                SettleFrames(50);
            }
            SettleFrames(220);

            var live = LiveSelectionFrame;
            var gripNow = SelectionHandles.CanvasPosition(SelHandle.Rotate, live, DpiScale);
            var region = live.CanvasAabb;
            region.Add(gripNow.X - 70f * DpiScale, gripNow.Y - 80f * DpiScale);
            region.Add(gripNow.X + 70f * DpiScale, gripNow.Y + 20f * DpiScale);
            Console.WriteLine($"姿态角那一帧（{(isRect ? "矩形" : "椭圆")}）：读数 {SelRotationPose:F1}°"
                            + $"（吸住={SelRotationSnapped}），起手 {startDeg:F0}°，拖了 {turn:F1}°"
                            + $"，标签文案「{SelectionHandles.FormatPose(SelRotationPose)}」");
            if (!OffscreenFloatingShot(path, region.Inflate(40f))) Console.WriteLine("出图失败");
            SendMouse((int)last.X, (int)last.Y, Native.MOUSEEVENTF_LEFTUP);
            SettleFrames(150);
            _quit = true;
            return;
        }

        // `--angles`：三角形和平行四边形**都要拖着一个顶点不松手**才出角度
        //（用户 2026-09-20 定：三角形也改成"拖动时才显示"，和平行四边形一条判据）。
        if (angleRead)
        {
            bool para = kind == "parallelogram";
            var sh = new Stroke
            {
                Color = new Color4(0.11f, 0.12f, 0.15f, 1f), Width = 6f * DpiScale,
            };
            if (para)
            {
                sh.Tool = Tool.Parallelogram; sh.Kind = StrokeKind.Parallelogram;
                sh.AddPoint(cx - 300f, cy + 170f, 1f, 0);      // 底左
                sh.AddPoint(cx + 300f, cy + 170f, 1f, 0);      // 底右
                sh.AddPoint(cx - 110f, cy - 170f, 1f, 0);      // 顶左
            }
            else
            {
                // 刻意**不等边**：三个角三个不同的数，出图时一眼能看出"每个角各自独立"
                sh.Tool = Tool.Triangle; sh.Kind = StrokeKind.Triangle;
                sh.AddPoint(cx - 70f, cy - 250f, 1f, 0);       // 上顶点
                sh.AddPoint(cx - 320f, cy + 170f, 1f, 0);      // 下左
                sh.AddPoint(cx + 320f, cy + 170f, 1f, 0);      // 下右
            }
            Doc.AddStroke(sh);
            Doc.SelectOnly(new[] { sh });
            Tool = Tool.Marquee;
            Doc.InvalidateAll();
            SettleFrames(700);

            // 拖一个顶点、**停住不松手**：三角形和平行四边形**都只在拖顶点时**才出角度
            // （用户 2026-09-20 定："三角形应该在拖动的时候再显示角度，要不然看起来也乱"），
            // 所以拍这一张必须按住不放——松手拍出来是空的。
            // 三角形拖**上顶点**（Vertex0）、平行四边形拖**底右顶点**（Vertex1）。
            var dragHandle = para ? ShapeHandle.Vertex1 : ShapeHandle.Vertex0;
            var dragBy = para ? new Vector2(70f, 40f) : new Vector2(90f, 70f);
            var v = SelectionHandles.ShapeHandleCanvasPosition(sh, dragHandle);
            var toP = new Vector2(v.X + dragBy.X, v.Y + dragBy.Y);
            SendMouse((int)v.X, (int)v.Y, 0);                            SettleFrames(60);
            SendMouse((int)v.X, (int)v.Y, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
            for (int i = 1; i <= 4; i++)
            {
                SendMouse((int)(v.X + (toP.X - v.X) * i / 4f),
                          (int)(v.Y + (toP.Y - v.Y) * i / 4f), 0);
                SettleFrames(50);
            }
            SettleFrames(220);

            Span<Vector2> vs = stackalloc Vector2[4];
            Span<float> ds = stackalloc float[3];
            int n = FillAngleReadout(vs, ds);
            // **没有"内角和"那一行**（用户 2026-09-19 定），所以只报那几个角自己。
            Console.WriteLine(para
                ? $"夹角那一帧（平行四边形拖顶点中）：{n} 个角 = "
                  + $"{SelectionHandles.FormatAngleDegrees(ds[0])} / "
                  + $"{SelectionHandles.FormatAngleDegrees(ds[1])}，顶点 {vs[0]} / {vs[1]}"
                : $"内角那一帧（三角形拖顶点中）：{n} 个角 = "
                  + $"{SelectionHandles.FormatAngleDegrees(ds[0])} / "
                  + $"{SelectionHandles.FormatAngleDegrees(ds[1])} / "
                  + $"{SelectionHandles.FormatAngleDegrees(ds[2])}");
            var region = SelectionHandles.FrameOf(Doc.Selected).CanvasAabb;
            region = region.Inflate(220f * DpiScale);            // 角标挂在顶点外侧，框要放宽
            if (!OffscreenFloatingShot(path, region)) Console.WriteLine("出图失败");
            SendMouse((int)toP.X, (int)toP.Y, Native.MOUSEEVENTF_LEFTUP);
            SettleFrames(150);
            _quit = true;
            return;
        }

        // ---- 圆 / 椭圆 / 三角形 / 平行四边形 / 抛物线 / 长方体：静止选中态 ----
        //（后两种是"**没有特殊手柄**"的那一类：拍的是通用八手柄 ＋ 旋转柄那根连线）
        if (kind != "line")
        {
            var sh = new Stroke
            {
                Color = new Color4(0.11f, 0.12f, 0.15f, 1f), Width = 6f * DpiScale,
            };
            switch (kind)
            {
                case "circle":
                    sh.Tool = Tool.Circle; sh.Kind = StrokeKind.Circle;
                    sh.AddPoint(cx - 40f, cy - 40f, 1f, 0);        // 圆心
                    sh.AddPoint(cx + 200f, cy - 40f, 1f, 0);       // 圆周点（半径 240）
                    break;
                case "ellipse":
                    sh.Tool = Tool.Ellipse; sh.Kind = StrokeKind.Ellipse;
                    sh.AddPoint(cx - 40f, cy, 1f, 0);              // 中心
                    sh.AddPoint(cx + 260f, cy + 180f, 1f, 0);      // 外角点（a=300, b=180）
                    break;
                case "triangle":
                    sh.Tool = Tool.Triangle; sh.Kind = StrokeKind.Triangle;
                    sh.AddPoint(cx, cy - 220f, 1f, 0);             // 上中
                    sh.AddPoint(cx - 260f, cy + 160f, 1f, 0);      // 下左
                    sh.AddPoint(cx + 260f, cy + 160f, 1f, 0);      // 下右
                    break;
                case "parabola":
                    // 抛物线：顶点在左下、经过点在右上 → 开口向上（四个朝向里最好认的那个）。
                    // 它是"没有特殊手柄"那一类的代表：选中后该看到**通用八手柄**，
                    // 旋转柄那根线该连到**框上边中点**（不是顶点与经过点的中点）。
                    sh.Tool = Tool.Parabola; sh.Kind = StrokeKind.Parabola;
                    sh.CurveAxis = CurveAxis.OpenUp;
                    sh.AddPoint(cx - 240f, cy + 150f, 1f, 0);      // 顶点（按下那个点）
                    sh.SetParabolaVertex(cx - 240f, cy + 150f);
                    sh.SetParabolaThroughPoint(cx + 200f, cy - 170f);
                    break;
                case "cuboid":
                    // 长方体：正面矩形 ＋ 深度 150（照画法：深度往右上退）。
                    sh.Tool = Tool.Cuboid; sh.Kind = StrokeKind.Cuboid;
                    sh.AddPoint(cx - 260f, cy - 40f, 1f, 0);
                    sh.SetCuboidFront(cx - 260f, cy - 40f, cx + 180f, cy + 200f);
                    sh.SetCuboidDepth(cy - 40f, cy - 40f + 150f);  // 深 = |正面上边 − 这个 y| = 150
                    break;
                default: // parallelogram
                    sh.Tool = Tool.Parallelogram; sh.Kind = StrokeKind.Parallelogram;
                    sh.AddPoint(cx - 250f, cy + 160f, 1f, 0);      // 底左
                    sh.AddPoint(cx + 250f, cy + 160f, 1f, 0);      // 底右
                    sh.AddPoint(cx - 125f, cy - 160f, 1f, 0);      // 顶左
                    break;
            }
            Doc.AddStroke(sh);
            Doc.SelectOnly(new[] { sh });
            Tool = Tool.Marquee;
            Doc.InvalidateAll();
            SettleFrames(700);

            // 吸附那一帧：真拖一次顶点，**停住不松手**再拍（松手就没有胶囊了）。
            // 三角形摆到"等边"的容差里（高 = √3/2 × 底边长 520 ≈ 450.3）。
            if (snap && kind == "triangle")
            {
                var apex = SelectionHandles.ShapeHandleCanvasPosition(sh, ShapeHandle.Vertex0);
                var apexTo = new Vector2(cx + 1f, cy + 160f - 260f * MathF.Sqrt(3f));
                SendMouse((int)apex.X, (int)apex.Y, 0);                          SettleFrames(60);
                SendMouse((int)apex.X, (int)apex.Y, Native.MOUSEEVENTF_LEFTDOWN); SettleFrames(60);
                for (int i = 1; i <= 4; i++)
                {
                    SendMouse((int)(apex.X + (apexTo.X - apex.X) * i / 4f),
                              (int)(apex.Y + (apexTo.Y - apex.Y) * i / 4f), 0);
                    SettleFrames(40);
                }
                SettleFrames(200);
                Console.WriteLine($"吸附帧：吸到={ShapeSnapKind}"
                                + $"（「{SelectionHandles.ShapeSnapLabel(ShapeSnapKind)}」），"
                                + $"被拖的顶点 {apex} → {apexTo}");
            }

            var sFrame = SelectionHandles.FrameOf(Doc.Selected);
            var sAabb = sFrame.CanvasAabb;
            var sBar = SelectionHandles.BarRect(sAabb, DpiScale, ViewportCanvas);
            var region = sAabb;
            region.Add(sBar);
            if (SelectionHandles.RotateHandleVisible(sh))       // 圆没有旋转柄，别白算一块
            {
                var grip = SelectionHandles.CanvasPosition(SelHandle.Rotate, sFrame, DpiScale);
                region.Add(grip.X - 40f * DpiScale, grip.Y - 40f * DpiScale);
                region.Add(grip.X + 40f * DpiScale, grip.Y + 40f * DpiScale);
            }
            // 拖元素时的胶囊挂在元素外侧：`--snap` 那张必须把它一起圈进来
            if (snap && VertexDragging)
            {
                region.Add(VertexPreviewCanvasPoint.X - 90f * DpiScale,
                           VertexPreviewCanvasPoint.Y - 60f * DpiScale);
                region.Add(VertexPreviewCanvasPoint.X + 90f * DpiScale,
                           VertexPreviewCanvasPoint.Y + 10f * DpiScale);
            }
            if (!OffscreenFloatingShot(path, region.Inflate(30f))) Console.WriteLine("出图失败");
            if (snap && VertexDragging)
            {
                SendMouse((int)ShapeSnapAnchor.X, (int)ShapeSnapAnchor.Y, Native.MOUSEEVENTF_LEFTUP);
                SettleFrames(150);
            }
            _quit = true;
            return;
        }

        // ---- 一条"已经转过 60°"的直线、静止选中（紧框改口径的第二个现场）----
        if (rotated)
        {
            var rl = new Stroke
            {
                Tool = Tool.Line, Kind = StrokeKind.Line,
                Color = new Color4(0.11f, 0.12f, 0.15f, 1f), Width = 6f * DpiScale,
            };
            // 和另外几张**同一条线**（α₀ ≈ 27.65°），绕它自己的中点视觉逆时针转 32.35°
            // → 转完 α ≈ 60°，正是 --rotate 松手之后那个状态。
            rl.AddPoint(cx - 420f, cy + 220f, 1f, 0);
            rl.AddPoint(cx + 420f, cy - 220f, 1f, 0);
            rl.Transform = SelectionHandles.RotateMatrix(32.35f, new Vector2(cx, cy));
            Doc.AddStroke(rl);
            Doc.SelectOnly(new[] { rl });
            Tool = Tool.Marquee;
            Doc.InvalidateAll();
            SettleFrames(700);

            var fr = SelectionHandles.FrameOf(Doc.Selected);
            var aabbR = fr.CanvasAabb;
            var barR = SelectionHandles.BarRect(aabbR, DpiScale, ViewportCanvas);
            var gripR = SelectionHandles.CanvasPosition(SelHandle.Rotate, fr, DpiScale);
            var regionR = aabbR;
            regionR.Add(barR);
            regionR.Add(gripR.X - 40f * DpiScale, gripR.Y - 40f * DpiScale);
            regionR.Add(gripR.X + 40f * DpiScale, gripR.Y + 40f * DpiScale);
            Console.WriteLine($"转过 60° 的线、静止选中：框 {aabbR.MaxX - aabbR.MinX:F0}×{aabbR.MaxY - aabbR.MinY:F0}"
                            + $"，线自己的墨迹 {rl.WorldInkBounds.MaxX - rl.WorldInkBounds.MinX:F0}"
                            + $"×{rl.WorldInkBounds.MaxY - rl.WorldInkBounds.MinY:F0}"
                            + $"，PaddedBounds {rl.PaddedBounds.MaxX - rl.PaddedBounds.MinX:F0}"
                            + $"×{rl.PaddedBounds.MaxY - rl.PaddedBounds.MinY:F0}");
            if (!OffscreenFloatingShot(path, regionR.Inflate(30f))) Console.WriteLine("出图失败");
            _quit = true;
            return;
        }

        // ---- 旋转拖动中：真按真转（用户要看的就是这一帧）----
        if (rotate)
        {
            var spinLine = new Stroke
            {
                Tool = Tool.Line, Kind = StrokeKind.Line,
                Color = new Color4(0.11f, 0.12f, 0.15f, 1f), Width = 6f * DpiScale,
            };
            // 和"静止选中"那张**同一条线**（α ≈ 27.65°），三张图才好对比
            spinLine.AddPoint(cx - 420f, cy + 220f, 1f, 0);
            spinLine.AddPoint(cx + 420f, cy - 220f, 1f, 0);
            Doc.AddStroke(spinLine);
            Doc.SelectOnly(new[] { spinLine });
            Tool = Tool.Marquee;
            Doc.InvalidateAll();
            SettleFrames(700);

            var f0 = SelectionHandles.FrameOf(Doc.Selected);
            var pv = new Vector2((f0.CanvasAabb.MinX + f0.CanvasAabb.MaxX) * 0.5f,
                                 (f0.CanvasAabb.MinY + f0.CanvasAabb.MaxY) * 0.5f);
            var grip = SelectionHandles.CanvasPosition(SelHandle.Rotate, f0, DpiScale);
            float arm = Vector2.Distance(grip, pv);
            float a0 = MathF.Atan2(grip.Y - pv.Y, grip.X - pv.X);

            SendMouse((int)grip.X, (int)grip.Y, 0);                          SettleFrames(60);
            SendMouse((int)grip.X, (int)grip.Y, Native.MOUSEEVENTF_LEFTDOWN); SettleFrames(60);
            // 逆时针 31.5°：这条线 α₀ ≈ 27.65° → 59.15°（±1° 内）→ 吸到 60°，读数好看也吸住了
            const float Turn = 31.5f;
            var last = grip;
            for (int i = 1; i <= 4; i++)
            {
                float rad = a0 - Turn * i / 4f * MathF.PI / 180f;
                last = new Vector2(pv.X + arm * MathF.Cos(rad), pv.Y + arm * MathF.Sin(rad));
                SendMouse((int)last.X, (int)last.Y, 0);
                SettleFrames(40);
            }
            SettleFrames(200);

            // 范围：**实时框**（旋转中框按预览几何算，见 LiveSelectionFrame）∪ 旋转柄 ∪ 读数标签
            var live = LiveSelectionFrame;
            var aabb = live.CanvasAabb;
            var gripNow = SelectionHandles.CanvasPosition(SelHandle.Rotate, live, DpiScale);
            var region = aabb;
            region.Add(gripNow.X - 60f * DpiScale, gripNow.Y - 60f * DpiScale);
            region.Add(gripNow.X + 60f * DpiScale, gripNow.Y + 60f * DpiScale);
            region.Add(gripNow.X - 90f * DpiScale, gripNow.Y - 90f * DpiScale);
            region.Add(gripNow.X + 90f * DpiScale, gripNow.Y);
            // 顺带量一个"线**真实**占多大"（把两个端点过实时矩阵再外扩半笔宽）——
            // 用来和上面那个框比：相等就是贴合，明显小就是框虚胖（只打印，不改行为）。
            var liveM = spinLine.Transform * DragPreviewMatrix;
            var t0 = Vector2.Transform(new Vector2(spinLine.Points[0].X, spinLine.Points[0].Y), liveM);
            var t1 = Vector2.Transform(new Vector2(spinLine.Points[^1].X, spinLine.Points[^1].Y), liveM);
            var tight = RectF.Empty;
            tight.Add(t0.X, t0.Y);
            tight.Add(t1.X, t1.Y);
            tight = tight.Inflate(spinLine.Width * 0.5f + 2f);
            Console.WriteLine($"旋转中：读数 {SelRotationInclination:F1}°（吸住={SelRotationSnapped}），"
                            + $"实时框 {aabb.MaxX - aabb.MinX:F0}×{aabb.MaxY - aabb.MinY:F0}"
                            + $" ({(int)aabb.MinX},{(int)aabb.MinY})-({(int)aabb.MaxX},{(int)aabb.MaxY})，"
                            + $"线自己真实占 {tight.MaxX - tight.MinX:F0}×{tight.MaxY - tight.MinY:F0}"
                            + $" ({(int)tight.MinX},{(int)tight.MinY})-({(int)tight.MaxX},{(int)tight.MaxY})"
                            + $"，模型里（没动）的墨迹范围 "
                            + $"{(int)spinLine.WorldInkBounds.MinX},{(int)spinLine.WorldInkBounds.MinY}"
                            + $"-{(int)spinLine.WorldInkBounds.MaxX},{(int)spinLine.WorldInkBounds.MaxY}");
            if (!OffscreenFloatingShot(path, region.Inflate(30f))) Console.WriteLine("出图失败");

            SendMouse((int)last.X, (int)last.Y, Native.MOUSEEVENTF_LEFTUP);
            SettleFrames(250);
            // 松手后框会重新按**模型**算（FrameOf）——和拖动中那个"旧框转过去的外接矩形"
            // 差多少，这里给出数字（只打印，不改行为）。
            var afterAabb = SelectionHandles.FrameOf(Doc.Selected).CanvasAabb;
            Console.WriteLine($"旋转松手后：框 {afterAabb.MaxX - afterAabb.MinX:F0}×{afterAabb.MaxY - afterAabb.MinY:F0}"
                            + $"（拖动中是 {aabb.MaxX - aabb.MinX:F0}×{aabb.MaxY - aabb.MinY:F0}），"
                            + $"线的实时姿态 "
                            + $"{SelectionHandles.InclinationDegrees(SelectionHandles.EndpointCanvasPosition(spinLine, 0), SelectionHandles.EndpointCanvasPosition(spinLine, 1)):F1}°");
            _quit = true;
            return;
        }

        // ---- 正在画一条直线：按住不放，拖到**原始 45.5°**（±1° 容差内 → 吸到 45°）----
        if (drawing)
        {
            SetToolFromUi(Tool.Line);
            var from = new Vector2(cx - 380f, cy + 200f);
            float rad = -45.5f * MathF.PI / 180f;
            var tipTarget = new Vector2(from.X + 620f * MathF.Cos(rad), from.Y + 620f * MathF.Sin(rad));

            SendMouse((int)from.X, (int)from.Y, 0);                            SettleFrames(60);
            SendMouse((int)from.X, (int)from.Y, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
            for (int i = 1; i <= 4; i++)
            {
                SendMouse((int)(from.X + (tipTarget.X - from.X) * i / 4f),
                          (int)(from.Y + (tipTarget.Y - from.Y) * i / 4f), 0);
                SettleFrames(40);
            }
            SettleFrames(200);

            var tip = ShapeInclinationAnchor;
            // 起手必须是 RectF.Empty（默认构造的 RectF 是 (0,0)-(0,0)，会把画面原点算进来）
            var drawBox = RectF.Empty;
            drawBox.Add(from.X, from.Y);
            drawBox.Add(tip.X, tip.Y);
            drawBox = drawBox.Inflate(30f * DpiScale);
            // 读数标签挂在"正在拖的那一端"上方，高度 30 逻辑 + 一段间距：一起圈进画面
            drawBox.Add(tip.X - 80f * DpiScale, tip.Y - 60f * DpiScale);
            drawBox.Add(tip.X + 80f * DpiScale, tip.Y);
            Console.WriteLine($"画线中：α = {ShapeInclinationDegrees:F1}°（吸住={ShapeInclinationSnapped}）"
                            + $"，起点 {from}，笔尖 {tip}"
                            + $"，出图范围 ({drawBox.MinX:F0},{drawBox.MinY:F0})-({drawBox.MaxX:F0},{drawBox.MaxY:F0})");
            if (!OffscreenFloatingShot(path, drawBox)) Console.WriteLine("出图失败");

            SendMouse((int)tipTarget.X, (int)tipTarget.Y, Native.MOUSEEVENTF_LEFTUP);
            SettleFrames(120);
            _quit = true;
            return;
        }

        var line = new Stroke
        {
            Tool = Tool.Line, Kind = StrokeKind.Line,
            Color = new Color4(0.11f, 0.12f, 0.15f, 1f), Width = 6f * DpiScale,
        };
        line.AddPoint(cx - 420f, cy + 220f, 1f, 0);
        line.AddPoint(cx + 420f, cy - 220f, 1f, 0);
        Doc.AddStroke(line);
        Doc.SelectOnly(new[] { line });
        Tool = Tool.Marquee;
        Doc.InvalidateAll();
        SettleFrames(700);

        if (!drag)
        {
            // 范围 = 选中框 ∪ 旋转柄 ∪ 操作条（操作条也由 DrawSelection 画，
            // 不并进来会被裁掉一半），再留一圈给投影。
            var aabb = SelectionHandles.FrameOf(Doc.Selected).CanvasAabb;
            var bar = SelectionHandles.BarRect(aabb, DpiScale, ViewportCanvas);
            var grip = SelectionHandles.CanvasPosition(SelHandle.Rotate,
                                                       SelectionHandles.FrameOf(Doc.Selected), DpiScale);
            var region = aabb;
            region.Add(bar);
            region.Add(grip.X - 40f, grip.Y - 40f);
            region.Add(grip.X + 40f, grip.Y + 40f);
            if (!OffscreenFloatingShot(path, region.Inflate(30f))) Console.WriteLine("出图失败");
            _quit = true;
            return;
        }

        // 真拖一次端点：原始方向 30.5°（±1° 容差内）→ 读数该显示 α = 30.0°。
        // 用真输入（而不是直接摆内部状态），出的图才是产品里那一帧。
        var eFixed = SelectionHandles.EndpointCanvasPosition(line, 1);
        var eDrag = SelectionHandles.EndpointCanvasPosition(line, 0);
        float theta = 149.5f * MathF.PI / 180f;
        var to = new Vector2(eFixed.X + 700f * MathF.Cos(theta), eFixed.Y + 700f * MathF.Sin(theta));

        SendMouse((int)eDrag.X, (int)eDrag.Y, 0);                          SettleFrames(60);
        SendMouse((int)eDrag.X, (int)eDrag.Y, Native.MOUSEEVENTF_LEFTDOWN); SettleFrames(60);
        for (int i = 1; i <= 4; i++)
        {
            SendMouse((int)(eDrag.X + (to.X - eDrag.X) * i / 4f),
                      (int)(eDrag.Y + (to.Y - eDrag.Y) * i / 4f), 0);
            SettleFrames(40);
        }
        SettleFrames(200);

        var preview = VertexPreviewCanvasPoint;
        // 起手必须是 RectF.Empty：默认构造的 RectF 是 (0,0)-(0,0)，
        // 直接 Add 进去会把画面原点也算进范围（出图一半是空白就是它）。
        var box = RectF.Empty;
        box.Add(eFixed.X, eFixed.Y);
        box.Add(preview.X, preview.Y);
        box = box.Inflate(40f * DpiScale);
        // 读数标签挂在被拖端点上方，高度 30 逻辑 + 一段间距：把它一起圈进画面
        box.Add(preview.X - 70f * DpiScale, preview.Y - 60f * DpiScale);
        box.Add(preview.X + 70f * DpiScale, preview.Y);
        Console.WriteLine($"拖端点中：α = {VertexReadoutValue:F1}°（吸住={VertexInclinationSnapped}），"
                        + $"固定端 {eFixed}，拖动端 {preview}"
                        + $"（模型里这条线还没动：墨迹范围 {(int)line.WorldInkBounds.MinX},{(int)line.WorldInkBounds.MinY}"
                        + $"-{(int)line.WorldInkBounds.MaxX},{(int)line.WorldInkBounds.MaxY}），"
                        + $"出图范围 ({box.MinX:F0},{box.MinY:F0})-({box.MaxX:F0},{box.MaxY:F0})");
        if (!OffscreenFloatingShot(path, box)) Console.WriteLine("出图失败");

        SendMouse((int)to.X, (int)to.Y, Native.MOUSEEVENTF_LEFTUP);
        SettleFrames(120);
        _quit = true;
    }

    /// <summary>
    /// 折角填充自检：**拐角处不能掉色**（写"L""V""7""∠"这类折笔时，填充在
    /// 自交处被挖空的那个老 bug）。
    ///
    /// 判据在 2026-09-14 重写过，因为**旧判据自己有问题**：它拿"拐角窗口的墨量"
    /// 比"直段窗口的墨量"，要求前者 ≥ 后者的 95%。可是拐角窗口里本来就有 3/4 的
    /// 地方没墨（两个臂分别从窗口的左边和下边出去），所以这条自检从写下来那天起
    /// 就是红的——一条永远红的自检等于没有自检，它把真正的信号淹掉了。
    ///
    /// 现在的判据直接对着**要防的 bug**：沿笔迹中心线取一串采样点（含拐角本身），
    /// 每个点在填充里都必须有墨（FillContainsPoint）。拐角被挖空 → 拐角那个点
    /// 就是空的 → 报红。另加一条"上屏兜底"（白板 + 拐角窗口数黑像素），
    /// 因为"几何对但没画到屏幕上"也是一种可能。
    /// </summary>
    /// <summary>
    /// 自交叠色自检：**一笔自己穿过自己的地方，颜色不能变深**。
    ///
    /// 为什么单独拎出来验：我们画的是"一条闭合轮廓 + 一次填充"，理论上自交处只会让
    /// Winding 计数变成 2，仍然只合成一次；但中间有一道工序可能破坏这个前提——
    /// **几何细分缓存**（`CreateFilledGeometryRealization`）如果按三角形逐个合成，
    /// 重叠区就会被合成两次。用户报的"画角时内部变深"正是这个形状，所以要专门盯。
    ///
    /// 判据：在同一笔的"自交重叠区"和"普通区"各取一个像素，颜色必须相同
    /// （半透明荧光笔最敏感——叠两次一眼就能看出来）。
    /// </summary>
    // ------------------------------------------------------------------
    //  离屏渲染小工具
    //
    //  量"颜色会不会变深"这类事不能靠抓屏：抓屏在锁屏 / 远程会话 / 被别的窗口盖住时
    //  拍到的是桌面壁纸，两处都是壁纸 → "差 0" 看着像通过，其实什么都没验
    //  （2026-09-15 就被骗过一次）。离屏渲染什么时候跑都一样。
    // ------------------------------------------------------------------

    /// <summary>建一对离屏位图：一个当渲染目标，一个 CPU 可读（读回像素用）。</summary>
    private (ID2D1Bitmap1 target, ID2D1Bitmap1 cpu) MakeOffscreen(int w, int h)
    {
        var ctx = _windows[0].Context;
        var pf = new Vortice.DCommon.PixelFormat(
            Vortice.DXGI.Format.B8G8R8A8_UNorm, Vortice.DCommon.AlphaMode.Premultiplied);
        var target = ctx.CreateBitmap(new SizeI(w, h), IntPtr.Zero, 0,
            new BitmapProperties1(pf, 96f, 96f, BitmapOptions.Target | BitmapOptions.CannotDraw));
        var cpu = ctx.CreateBitmap(new SizeI(w, h), IntPtr.Zero, 0,
            new BitmapProperties1(pf, 96f, 96f, BitmapOptions.CpuRead | BitmapOptions.CannotDraw));
        return (target, cpu);
    }

    /// <summary>把文档里的笔画画进离屏位图（画布坐标 → 位图坐标，按 -origin 平移）。</summary>
    private void RenderDocToBitmap(ID2D1Bitmap1 target, float originX, float originY)
    {
        var ctx = _windows[0].Context;
        ctx.Target = target;
        ctx.BeginDraw();
        ctx.Clear(new Color4(0.98f, 0.98f, 0.98f, 1f));      // 当作白板底色
        ctx.Transform = System.Numerics.Matrix3x2.CreateTranslation(-originX, -originY);
        foreach (var s in Doc.Strokes) _windows[0].DrawStrokeForTest(s);
        ctx.Transform = System.Numerics.Matrix3x2.Identity;
        var hr = ctx.EndDraw();
        if (hr.Failure) Console.WriteLine("  离屏 EndDraw 失败: " + hr.Description);
        ctx.Target = null;
    }

    /// <summary>把离屏位图读回内存（BGRA）。</summary>
    private static byte[] ReadPixels(ID2D1Bitmap1 target, ID2D1Bitmap1 cpu, int w, int h)
    {
        cpu.CopyFromBitmap(new System.Drawing.Point(0, 0), target);
        var m = cpu.Map(MapOptions.Read);
        var buf = new byte[w * h * 4];
        for (int y = 0; y < h; y++)
            Marshal.Copy(IntPtr.Add(m.Bits, (int)(y * m.Pitch)), buf, y * w * 4, w * 4);
        cpu.Unmap();
        return buf;
    }

    private byte[] RenderAndRead(ID2D1Bitmap1 target, ID2D1Bitmap1 cpu, int w, int h,
                                 float originX, float originY)
    {
        RenderDocToBitmap(target, originX, originY);
        return ReadPixels(target, cpu, w, h);
    }

    /// <summary>取一小块的平均色（参数是 BGRA 缓冲、行宽像素数、左上角、边长）。</summary>
    private static (int r, int g, int b) AvgPatch(byte[] buf, int width, int px, int py, int size)
    {
        // 探针落在缓冲外面时**夹回来**，而不是抛异常：这是量颜色的工具，
        // 量歪了应该报一个可疑的数字让人去看，不该把整个自检进程打断。
        int height = buf.Length / (width * 4);
        px = Math.Clamp(px, 0, Math.Max(0, width - size));
        py = Math.Clamp(py, 0, Math.Max(0, height - size));
        long r = 0, g = 0, b = 0; int n = 0;
        for (int y = py; y < py + size; y++)
            for (int x = px; x < px + size; x++)
            {
                int i = y * width * 4 + x * 4;
                b += buf[i]; g += buf[i + 1]; r += buf[i + 2]; n++;
            }
        return ((int)(r / n), (int)(g / n), (int)(b / n));
    }

    /// <summary>两个颜色的差（三通道绝对值之和）。</summary>
    private static int ColorDiff((int r, int g, int b) a, (int r, int g, int b) b)
        => Math.Abs(a.r - b.r) + Math.Abs(a.g - b.g) + Math.Abs(a.b - b.b);

    /// <summary>
    /// 造一条"自己穿过自己"的荧光笔笔迹（`--selfcross`、`--eraseselfcross`、像素橡皮自检
    /// 共用同一条）。
    ///
    /// **真正的自交点**：两段中心线联立解出来是相对 (161.7, 20.9)，不是 (200, 0)——
    /// 后者离交点 40 像素，那儿只有一股墨，拿它做判据等于什么都没验（老用例就是这么错的）。
    /// </summary>
    private static Stroke MakeSelfCrossingHighlight(float cx, float cy, float width)
    {
        var s = new Stroke
        {
            Tool = Tool.Pen, Kind = StrokeKind.Freehand,
            Color = InkPalette.HighlighterDefault, Width = width,
        };
        var raw = new List<Vector2>
        {
            new(cx, cy), new(cx + 120, cy), new(cx + 240, cy + 60),
            new(cx + 240, cy + 220), new(cx + 60, cy + 260),
            new(cx - 20, cy + 120), new(cx + 200, cy),          // ← 穿过第一段
            new(cx + 330, cy - 150),
        };
        for (int i = 0; i + 1 < raw.Count; i++)
            for (int k = 0; k < 20; k++)
            {
                float t = k / 20f;
                s.AddPoint(raw[i].X + (raw[i + 1].X - raw[i].X) * t,
                           raw[i].Y + (raw[i + 1].Y - raw[i].Y) * t, 0.5f, i * 20 + k);
            }
        s.AddPoint(raw[^1].X, raw[^1].Y, 0.5f, 999);
        return s;
    }

    /// <summary>
    /// 橡皮手测台（--eraserlab [日志前缀]）。
    ///
    /// **这是给人用的，不是自检**：铺一屏"可擦的东西"，打开橡皮遥测，然后把控制权交回
    /// 引擎的正常消息循环，用户拿鼠标自己擦。每条拖拽结束立刻落一行 CSV，退出时写汇总。
    ///
    /// 为什么要有它：手感、习惯、误擦这些事只有真人用真手才知道。自检能证明"切得对、
    /// 撤销一步、上屏像素对"，证明不了"这个尺寸顺手""这一擦我其实不想擦"。
    ///
    /// 样例里**故意放了三类对象**——笔迹（会被切开）、荧光笔（自交，看颜色会不会变深）、
    /// 图形（碰到轮廓整条删），一屏就能把三种行为都试到。
    /// </summary>
    /// <summary>
    /// 实验（--eraseimage）：**画面里有一张大图时，擦除一步要多久**。
    ///
    /// 查的是用户报的"擦图像不流畅"。分块缓存的重画是"整块清掉再画一遍块内的所有对象"，
    /// 而图像对象画的是**一张位图**——块里有图，这一块每次重画都要把图重新贴一遍。
    /// 所以图越大、橡皮跨过的块越多，一步擦除就越贵。这里做 A/B：同一串擦除动作，
    /// 一次在"有图 + 图上有墨"的版面上跑，一次在"没有图"的版面上跑。
    /// </summary>
    /// <summary>
    /// 探针（--imageerase）：**两种橡皮碰到图像对象时分别会怎样**。
    ///
    /// 用户报"擦图像不流畅"，先把"到底会发生什么"钉死：
    ///   · 像素橡皮（Ctrl+Alt+7）：按设计**不碰**图像（代码里 `if (s.IsImage) continue`）；
    ///   · 整笔橡皮（Ctrl+Alt+4）：走 `IsShape` 分支 → `HitTestExact` → 图像**整条删掉**。
    /// 这两个不一样，是历史遗留（图像是后来加的，整笔橡皮那条分支没跟着改）。
    /// </summary>
    private void ImageEraseProbe()
    {
        Console.WriteLine();
        Console.WriteLine("=== 探针：两种橡皮碰到图像对象时会怎样 ===");

        float cx = _virtualX + _virtualW * 0.5f, cy = _virtualY + _virtualH * 0.5f;

        Doc.Clear();
        Doc.ClearHistory();
        var img = Doc.AddImage(MakeTestImage(400, 300), cx - 200, cy - 150, 1f);
        Console.WriteLine($"  先放一张 400×300 的图（对象数 {Doc.Strokes.Count}），"
                        + "橡皮落点打在图像正中");

        int hit = Doc.EraseRectAt(cx, cy, 40f, 40f);          // 像素橡皮的调用
        Console.WriteLine($"  像素橡皮擦一下：受影响 {hit} 条，图还在吗 "
                        + $"{(Doc.Strokes.Contains(img) ? "在" : "**没了**")}"
                        + $"（对象数 {Doc.Strokes.Count}）");

        int removed = Doc.EraseAt(cx, cy, 40f);               // 整笔橡皮的调用
        Console.WriteLine($"  整笔橡皮擦一下：删掉 {removed} 条，图还在吗 "
                        + $"{(Doc.Strokes.Contains(img) ? "在" : "**没了**")}"
                        + $"（对象数 {Doc.Strokes.Count}）");

        Console.WriteLine("image-erase probe done");
        _quit = true;
    }

    private void EraseImageProbe()
    {
        Console.WriteLine();
        Console.WriteLine("=== 实验：画面里有大图时，擦除一步的代价 ===");

        float cx = _virtualX + _virtualW * 0.5f, cy = _virtualY + _virtualH * 0.5f;
        const int Steps = 25;

        double Run(bool withImage, out double patchMax, out int tiles, out int drawn, out double selfMs)
        {
            Doc.Clear();
            Doc.ClearHistory();
            // 按**截图**的实际尺寸来：一张全屏截图就是虚拟桌面那么大（2880×1800 = 20MB）。
            int iw = (int)_virtualW, ih = (int)_virtualH;
            if (withImage) Doc.AddImage(MakeTestImage(iw, ih), _virtualX, _virtualY, 1f);

            // 图上画几行笔迹（老师在图/PPT 上圈画），橡皮就擦这些
            var rnd = new Random(5);
            for (int k = 0; k < 6; k++)
            {
                var s = new Stroke { Tool = Tool.Pen, Color = new Color4(0.9f, 0.15f, 0.15f, 1f), Width = 8f * DpiScale };
                float y = cy - 400 + k * 130;
                for (int i = 0; i <= 60; i++)
                {
                    float t = i / 60f;
                    s.AddPoint(cx - 700 + t * 1400, y + MathF.Sin(t * 7f + k) * 12f, 0.9f, i);
                }
                Doc.AddStroke(s);
            }
            Doc.InvalidateAll();
            SettleFrames(500);

            double sum = 0, mx = 0, self = 0;
            int tl = 0, dr = 0;
            float bx = cx - 600, by = cy - 400;
            for (int i = 0; i < Steps; i++)
            {
                bx += 48; by += 32;
                var sw = Stopwatch.StartNew();
                Doc.EraseRectAt(bx, by, PixelEraserHalfWidthPx, PixelEraserHalfHeightPx);
                sw.Stop();
                self += sw.Elapsed.TotalMilliseconds;
                NowMs = _clock.Elapsed.TotalMilliseconds;
                RenderAll();
                sum += _windows[0].LastPatchMs;
                if (_windows[0].LastPatchMs > mx) mx = _windows[0].LastPatchMs;
                tl += _windows[0].LastPatchCount;
                dr += _windows[0].LastDrawnStrokes;
            }
            patchMax = mx; tiles = tl; drawn = dr; selfMs = self;
            return sum / Steps;
        }

        double noImg = Run(false, out var mxA, out var tlA, out var drA, out var selfA);
        double withImg = Run(true, out var mxB, out var tlB, out var drB, out var selfB);

        Console.WriteLine($"  没有图：重画 {noImg,6:F2} ms/步（峰值 {mxA,5:F2}）"
                        + $"　{TL(tlA)} 块/步　{DR(drA)} 笔/步　擦除本身 {selfA / Steps,5:F2} ms/步");
        Console.WriteLine($"  有  图：重画 {withImg,6:F2} ms/步（峰值 {mxB,5:F2}）"
                        + $"　{TL(tlB)} 块/步　{DR(drB)} 笔/步　擦除本身 {selfB / Steps,5:F2} ms/步");
        Console.WriteLine($"  结论：带图时一步慢 {withImg - noImg:F2} ms（重画部分）");
        string TL(int t) => (t / (double)Steps).ToString("F1");
        string DR(int d) => (d / (double)Steps).ToString("F0");
        Console.WriteLine("erase-image probe done");
        _quit = true;
    }

    /// <summary>造一张"截图"：渐变 + 棋盘格，模拟真实内容（尺寸给的是像素）。</summary>
    private static ImageData MakeTestImage(int w, int h)
    {
        var px = new byte[w * h * 4];
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
            {
                int i = (y * w + x) * 4;
                px[i] = (byte)(200 - y * 100 / h);                          // B
                px[i + 1] = (byte)(180 - x * 80 / w);                       // G
                px[i + 2] = (byte)(150 + ((x / 16 + y / 16) % 2) * 30);     // R
                px[i + 3] = 255;
            }
        return ImageData.Adopt(w, h, px, hasAlpha: true);
    }

    private void EraserLab(string prefix, bool keepSystemCursor = false)
    {
        string stamp = DateTime.Now.ToString("MMdd-HHmmss");
        string root = string.IsNullOrWhiteSpace(prefix) ? $"reports/橡皮-手测-{stamp}" : prefix;

        Doc.Clear();
        Doc.ClearHistory();

        float L = DpiScale;                       // 逻辑 → 物理
        float X(float logical) => _virtualX + logical * L;
        float Y(float logical) => _virtualY + logical * L;
        var ink = new Color4(0.08f, 0.09f, 0.12f, 1f);

        // ① 两行"板书"：每行三条长笔迹（模拟一行连着写下来）
        for (int row = 0; row < 2; row++)
        {
            float yy = Y(320f + row * 80f);
            for (int seg = 0; seg < 3; seg++)
            {
                var s = new Stroke { Tool = Tool.Pen, Color = ink, Width = 5f * L };
                float x0 = X(90f + seg * 420f), x1 = X(90f + seg * 420f + 395f);
                for (int i = 0; i <= 40; i++)
                {
                    float t = i / 40f;
                    s.AddPoint(x0 + (x1 - x0) * t,
                               yy + MathF.Sin(t * 9f + seg * 2f) * 7f * L, 0.9f, i);
                }
                Doc.AddStroke(s);
            }
        }

        // ② 三个"字"：三横一竖——"改一个字要重写一整行"那种场景（整笔擦会连带整行）
        for (int ch = 0; ch < 3; ch++)
        {
            float x0 = X(140f + ch * 220f), y0 = Y(470f);
            for (int k = 0; k < 3; k++)
            {
                var s = new Stroke { Tool = Tool.Pen, Color = ink, Width = 6f * L };
                s.AddPoint(x0, y0 + k * 26f * L, 1f, 0);
                s.AddPoint(x0 + 120f * L, y0 + k * 26f * L, 1f, 1);
                Doc.AddStroke(s);
            }
            var v = new Stroke { Tool = Tool.Pen, Color = ink, Width = 6f * L };
            v.AddPoint(x0 + 60f * L, y0 - 12f * L, 1f, 0);
            v.AddPoint(x0 + 60f * L, y0 + 64f * L, 1f, 1);
            Doc.AddStroke(v);
        }

        // ③ 一条自交的荧光笔：擦一刀，看交叠处会不会变深（这正是这版改动的核心收益）
        Doc.AddStroke(MakeSelfCrossingHighlight(X(880f), Y(360f), 26f * L));

        // ④ 图形：碰到轮廓整条删（橡皮从正中间划过不该删）
        var rect = new Stroke
        {
            Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
            Color = new Color4(0.85f, 0.2f, 0.2f, 1f), Width = 5f * L,
        };
        rect.AddPoint(X(790f), Y(520f), 1f, 0);
        rect.AddPoint(X(1090f), Y(620f), 1f, 1);
        Doc.AddStroke(rect);

        var arrow = new Stroke
        {
            Tool = Tool.Arrow, Kind = StrokeKind.Arrow,
            Color = new Color4(0.15f, 0.45f, 0.9f, 1f), Width = 5f * L,
        };
        arrow.AddPoint(X(1160f), Y(600f), 1f, 0);
        arrow.AddPoint(X(1360f), Y(530f), 1f, 1);
        Doc.AddStroke(arrow);

        // ⑤ 一块"截图区"：模拟老师截了 PPT/图，然后在图上圈画。
        //    用它试两件事——**图上的墨能正常擦掉**，而**图本身不该被橡皮吃掉**
        //    （图像对象按设计不参与擦除，要删它用框选 + Delete）。
        Doc.AddImage(MakeTestImage(640, 220), X(90f), Y(660f), DpiScale);
        for (int k = 0; k < 3; k++)
        {
            var s = new Stroke { Tool = Tool.Pen, Color = new Color4(0.9f, 0.15f, 0.15f, 1f), Width = 4f * L };
            float y0 = Y(690f + k * 60f);
            for (int i = 0; i <= 30; i++)
            {
                float t = i / 30f;
                s.AddPoint(X(120f + t * 560f), y0 + MathF.Sin(t * 8f + k) * 6f * L, 0.9f, i);
            }
            Doc.AddStroke(s);
        }

        // 默认就站在像素橡皮上——要测的就是它。整笔橡皮 Ctrl+Alt+4，一键换回来。
        Tool = Tool.PixelEraser;
        ShowHud = true;                 // 面板上有一行"记录中 N 条"，用户看得见确实在记
        PassThrough = false;
        BoardOn = false;                // 透明批注：能看见底下的东西，和上课一样
        Doc.InvalidateAll();
        _dirty = true;

        EraserTelemetry = new EraserTelemetry(root + ".csv", root + ".txt", NowMs);
        if (keepSystemCursor)
        {
            EraserKeepsSystemCursor = true;
            Console.WriteLine("  已打开对照：系统箭头也会显示（和自绘方块对比跟手程度）");
        }

        Console.WriteLine();
        Console.WriteLine($"=== 橡皮手测台 ===  日志：{Path.GetFullPath(root)}.csv / .txt");
        Console.WriteLine("  已铺样例：两行板书、三个字、一条自交荧光笔、一个矩形一个箭头");
        Console.WriteLine("  左下角还有一块「截图区」：图上有三条批注，试试图上的墨能不能正常擦、图本身会不会被吃掉");
        Console.WriteLine("  当前工具：像素橡皮 Ctrl+Alt+7（整笔橡皮 4、笔 1、撤销 Z、"
                        + "换橡皮大小 6、退出 X）");
        SettleFrames(300);
    }

    /// <summary>
    /// 实验 / 回归（--eraseselfcross）：**切一刀之后，荧光笔自交处会不会变深**。
    ///
    /// 2026-09-15：像素橡皮改成"在一条笔迹上记擦除区间"之后，这个实验从"报数字"变成
    /// 了**回归判据**（差必须是 0）——它正是那一版改动存在的理由。同一件事在
    /// `--pixelerasetest` 里也会验一次。
    ///
    /// 为什么值得单独量：`--selfcross` 守着"一笔自己穿过自己时颜色不能变深"这条不变量，
    /// 而它是**一次 DrawGeometry** 的性质——D2D 把一条描边当成一个整体填充一次。
    /// 像素橡皮把一条笔迹**拆成两个对象**之后就变成两次填充，两段墨在空间上重叠的地方
    /// 会各画一次：半透明的荧光笔叠两次，交叠处就深了。
    ///
    /// 这不是"看着差不多"的事，能被像素证伪。所以这里在**离交点很远的地方**切一刀，
    /// 让互相穿过的那两股墨落在不同的碎片里，再量交点色和普通处色的差。
    /// 只报数字、不判红绿（它是在验证一个设计取舍，不是回归用例）。
    /// </summary>
    private void EraseSelfCrossProbe()
    {
        Console.WriteLine();
        Console.WriteLine("=== 实验：切段之后自交处会不会变深（半透明荧光笔）===");

        Doc.Clear();
        Doc.ClearHistory();

        const int W = 800, H = 800;
        var (target, cpu) = MakeOffscreen(W, H);
        byte[] Render() => RenderAndRead(target, cpu, W, H, _virtualX, _virtualY);

        float cx = _virtualX + 500f, cy = _virtualY + 500f;
        Doc.AddStroke(MakeSelfCrossingHighlight(cx, cy, 40f));
        (int r, int g, int b) Avg(byte[] buf, int px, int py, int size)
            => AvgPatch(buf, W, px, py, size);
        // **真正的自交点在哪儿**：把两段中心线解出来才知道。
        //   A: P1(120,0) → P2(240,60)（第一段那条横线的斜尾巴）
        //   B: P5(-20,120) → P6(200,0)（绕回来那一股）
        //   A(u) = (120+120u, 60u)、B(t) = (-20+220t, 120-120t)
        //   60u = 120-120t → u = 2-2t；代进 x：-20+220t = 360-240t → t = 0.826, u = 0.348
        //   → 交点 ≈ (161.7, 20.9)
        //
        // 顺带一提：原来那条 --selfcross 用例探的是相对 (200, 0)，离这里 40 像素——
        // 那儿其实只有一股墨，两边颜色当然一样，那条判据是**空的**（见文档）。
        int crossX = (int)(cx + 161.7f - _virtualX) - 8;
        int crossY = (int)(cy + 20.9f - _virtualY) - 8;
        int plainX = (int)(cx + 60f - _virtualX) - 8;
        int plainY = (int)(cy - _virtualY) - 8;

        var buf0 = Render();
        var cross0 = Avg(buf0, crossX, crossY, 17);
        var plain0 = Avg(buf0, plainX, plainY, 17);
        int Diff((int r, int g, int b) a, (int r, int g, int b) b) => ColorDiff(a, b);
        int diff0 = Diff(cross0, plain0);
        Console.WriteLine($"  一刀没切（{Doc.Strokes.Count} 个对象）：交叠处 ({cross0.r},{cross0.g},{cross0.b})"
                        + $" vs 普通处 ({plain0.r},{plain0.g},{plain0.b})  差 {diff0}");

        // 在右侧那条竖边上切一刀（离交点 240 像素以上）：
        // 擦除区间记在**同一条笔迹**上，所以互相穿过的那两股墨还在同一次 DrawGeometry 里。
        int before = Doc.Strokes.Count;
        Doc.BeginEraseRect();
        Doc.EraseRectAt(cx + 240, cy + 140, 20f, 30f);
        Doc.EndErase();

        var buf1 = Render();
        var cross1 = Avg(buf1, crossX, crossY, 17);
        var plain1 = Avg(buf1, plainX, plainY, 17);
        int diff1 = Diff(cross1, plain1);
        Console.WriteLine($"  切一刀后（{Doc.Strokes.Count} 个对象）：交叠处 ({cross1.r},{cross1.g},{cross1.b})"
                        + $" vs 普通处 ({plain1.r},{plain1.g},{plain1.b})  差 {diff1}");
        Console.WriteLine($"  对象数 {before} → {Doc.Strokes.Count}"
                        + $"；交叠处比切之前深了 {diff1 - diff0}（0 = 没变深）");

        target.Dispose();
        cpu.Dispose();
        Console.WriteLine("erase-selfcross probe done");
        _quit = true;
    }

    private void SelfCrossTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 自交叠色自检（一笔自己穿过自己，颜色不能变深）===");

        bool boardBefore = BoardOn;
        var boardColorBefore = BoardColor;
        BoardOn = true;
        BoardColor = new Color4(0.98f, 0.98f, 0.98f, 1f);
        ViewOffsetY = 0f;
        foreach (var win in _windows) { win.ViewOffsetX = 0f; win.ViewOffsetY = 0f; }
        Doc.Clear();
        Doc.ClearHistory();

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-30} {detail}");
        }

        float w = 40f;                 // 物理像素
        float cx = _virtualX + 500f, cy = _virtualY + 500f;

        // 造一条"自己穿过自己"的笔迹：先往右，再绕回来从第一段上方穿过去。
        // **真正的交点在相对 (161.7, 20.9)**（两段中心线联立解出来的，推导见
        // EraseSelfCrossProbe），不是 (200, 0)。
        Stroke MakeLoop(float dx)
        {
            var s = new Stroke
            {
                Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                Color = HighlighterCurrent, Width = w,
            };
            var pts = new List<Vector2>
            {
                new(cx + dx, cy), new(cx + dx + 120, cy), new(cx + dx + 240, cy + 60),
                new(cx + dx + 240, cy + 220), new(cx + dx + 60, cy + 260),
                new(cx + dx - 20, cy + 120), new(cx + dx + 200, cy),   // ← 穿过第一段
                new(cx + dx + 330, cy - 150),
            };
            // 点之间插值，模拟真实采样密度
            for (int i = 0; i + 1 < pts.Count; i++)
                for (int k = 0; k < 20; k++)
                {
                    float t = k / 20f;
                    s.AddPoint(pts[i].X + (pts[i + 1].X - pts[i].X) * t,
                               pts[i].Y + (pts[i + 1].Y - pts[i].Y) * t, 0.5f, i * 20 + k);
                }
            s.AddPoint(pts[^1].X, pts[^1].Y, 0.5f, 999);
            return s;
        }

        Doc.AddStroke(MakeLoop(0f));
        Doc.InvalidateAll();
        SettleFrames(700);

        (int r, int g, int b) Avg(byte[] buf, int ww)
        {
            if (buf.Length < ww * ww * 4) return (0, 0, 0);
            long r = 0, g = 0, b = 0; int n = 0;
            for (int i = 0; i < buf.Length; i += 4) { b += buf[i]; g += buf[i + 1]; r += buf[i + 2]; n++; }
            return ((int)(r / n), (int)(g / n), (int)(b / n));
        }
        // 交叠区（两段墨重叠）与普通区（只有一段墨）各取一个小方块的平均色
        //
        // 探针位置 2026-09-15 修过一次：以前探的是相对 (200,0)，离真交点 40 像素——
        // 那儿只有一股墨，两边颜色当然一样，于是这条判据**永远是绿的、什么都没验**。
        void Probe(string label, float dx)
        {
            var co = Avg(ScreenProbe.CaptureRegion(
                (int)(cx + dx + 161.7f) - 8, (int)(cy + 20.9f) - 8, 17, 17), 17);
            var cs = Avg(ScreenProbe.CaptureRegion((int)(cx + dx + 60) - 8, (int)cy - 8, 17, 17), 17);
            int diff = Math.Abs(co.r - cs.r) + Math.Abs(co.g - cs.g) + Math.Abs(co.b - cs.b);
            Check($"自交处没有叠色（{label}）", diff <= 6,
                  $"交叠处 ({co.r},{co.g},{co.b}) vs 普通处 ({cs.r},{cs.g},{cs.b})，差 {diff}");
        }

        // 先确认"能看见墨"：抓屏在锁屏 / 远程会话 / 被别的窗口盖住时拿到的根本不是
        // 我们这一层，那时任何颜色比对都是假的（实测踩到：两处都拍到桌面壁纸，
        // 于是"差 0 = 通过"）。看不见就明确跳过，不能给一个假绿。
        var sanity = Avg(ScreenProbe.CaptureRegion((int)(cx + 60) - 8, (int)cy - 8, 17, 17), 17);
        // 荧光笔是黄色（r > g > b，都很亮）。拿"是不是黄的"当判据，比"和板色不一样"
        // 硬得多：桌面壁纸、任何别的窗口都能和板色不一样，但不该是黄的。
        bool canSeeInk = sanity.r > 180 && sanity.r > sanity.g && sanity.g > sanity.b;
        if (!canSeeInk)
        {
            Console.WriteLine($"  环境：抓屏看不到我们的墨（拍到的大概是桌面或别的窗口）"
                            + $" → SKIP: 自交叠色那一条跳过（这里应该是一块黄荧光笔，"
                            + $"实际拍到 ({sanity.r},{sanity.g},{sanity.b})）");
            BoardColor = boardColorBefore;
            BoardOn = boardBefore;
            _quit = true;
            return;
        }
        Probe("一笔自交", 0f);

        string shot = Path.Combine("reports", "自交叠色.bmp");
        ScreenProbe.SaveBmp(shot, (int)(cx - 120), (int)(cy - 260), 700, 700);
        Console.WriteLine($"  （已导出 {shot}：一笔自交，看交叉处有没有更深）");
        Console.WriteLine();
        Console.WriteLine($"  合计 {pass + fail} 项：通过 {pass}，失败 {fail}");
        Console.WriteLine();

        BoardOn = boardBefore;
        BoardColor = boardColorBefore;
        Doc.Clear();
        Doc.InvalidateAll();
        _quit = true;
    }


    /// <summary>
    /// **找洞自检**：笔是不透明的，所以"墨里出现深色"只可能是**墨真的缺了一块**
    /// （露出后面的背景），不是叠色。缺口的成因是轮廓自交时**绕向翻转**，
    /// 在 Winding 规则下正负抵消 → 那一块变成"外面"。
    ///
    /// 判据不靠肉眼：把笔画所在的区域截下来，从边界做一次**背景的连通填充**，
    /// 凡是"填不到、又被墨围住"的背景像素就是洞。这比"看谁变深"硬得多，
    /// 也不会把正常凹处（比如 V 字两臂之间）误判成洞。
    ///
    /// 造四种最容易出洞的笔迹：急折（内角 10°/20°）、自交（λ）、
    /// 以及"长斜线 + 顶端折返 + 穿过去"这种一笔画出来的交叉。
    /// </summary>
    private void HoleTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 找洞自检（不透明笔迹里不能露出背景）===");

        bool boardBefore = BoardOn;
        var boardColorBefore = BoardColor;
        BoardOn = true;
        BoardColor = new Color4(0.98f, 0.98f, 0.98f, 1f);
        ViewOffsetY = 0f;
        foreach (var win in _windows) { win.ViewOffsetX = 0f; win.ViewOffsetY = 0f; }
        Doc.Clear();
        Doc.ClearHistory();

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-26} {detail}");
        }

        float w = 48f;                       // 粗笔：问题在粗笔上才显形
        float arm = 220f;
        var ink = new Color4(0.95f, 0.18f, 0.18f, 1f);   // 不透明红

        // 一笔画出来的形状；返回包围盒（画布坐标）
        RectF Make(string kind, float cx, float cy)
        {
            var s = new Stroke
            {
                Tool = Tool.Pen, Kind = StrokeKind.Freehand, Color = ink, Width = w,
            };
            var pts = new List<Vector2>();
            if (kind == "折170")
            {
                float rad = 170f * MathF.PI / 180f;
                var d = new Vector2(MathF.Cos(rad), MathF.Sin(rad));
                for (int i = 0; i <= 30; i++) pts.Add(new(cx + arm * i / 30f, cy));
                for (int i = 1; i <= 30; i++)
                    pts.Add(new(cx + arm + d.X * arm * i / 30f, cy + d.Y * arm * i / 30f));
            }
            else if (kind == "折160")
            {
                float rad = 160f * MathF.PI / 180f;
                var d = new Vector2(MathF.Cos(rad), MathF.Sin(rad));
                for (int i = 0; i <= 30; i++) pts.Add(new(cx + arm * i / 30f, cy));
                for (int i = 1; i <= 30; i++)
                    pts.Add(new(cx + arm + d.X * arm * i / 30f, cy + d.Y * arm * i / 30f));
            }
            else if (kind == "自交λ")
            {
                // 上、折、再穿回来：经典的"λ"（自己的尾巴穿过自己的身子）
                for (int i = 0; i <= 30; i++) pts.Add(new(cx + i * 6f, cy + 180f - i * 6f));
                for (int i = 1; i <= 30; i++) pts.Add(new(cx + 180f + i * 6f, cy + i * 6f));
            }
            else // "∧ 加穿线"：用户的形状（长斜线 + 顶端折返 + 一笔穿过去）
            {
                for (int i = 0; i <= 30; i++) pts.Add(new(cx + i * 7f, cy + 200f - i * 7f));
                for (int i = 1; i <= 20; i++) pts.Add(new(cx + 210f + i * 3f, cy - 10f + i * 9f));
                for (int i = 1; i <= 40; i++) pts.Add(new(cx + 270f - i * 8f, cy + 170f - i * 9f));
            }
            if (kind == "原路折返")
            {
                // 画出去、再从原路画回来（同一笔）：两段完全重合
                for (int i = 0; i <= 40; i++) pts.Add(new(cx + i * 6f, cy));
                for (int i = 39; i >= 0; i--) pts.Add(new(cx + i * 6f, cy));
            }
            else if (kind == "浅角自交")
            {
                // 两条腿以很小的夹角交叉（"X" 的浅角版本）
                for (int i = 0; i <= 60; i++) pts.Add(new(cx + i * 7f, cy + 200f - i * 4f));
                for (int i = 1; i <= 60; i++) pts.Add(new(cx + 420f - i * 7f, cy - 40f + i * 5f));
            }

            // 点之间插值，贴近真实采样密度（5px 一个点）
            for (int i = 0; i + 1 < pts.Count; i++)
            {
                var a = pts[i]; var b = pts[i + 1];
                int steps = Math.Max(1, (int)(Vector2.Distance(a, b) / 5f));
                for (int k = 0; k < steps; k++)
                {
                    float t = k / (float)steps;
                    s.AddPoint(a.X + (b.X - a.X) * t, a.Y + (b.Y - a.Y) * t, 0.5f, i * 100 + k);
                }
            }
            s.AddPoint(pts[^1].X, pts[^1].Y, 0.5f, 9999);
            Doc.AddStroke(s);
            return s.PaddedBounds;
        }

        var kinds = new (string kind, string name, float cx)[]
        {
            ("折170", "急折·内角10°", _virtualX + 260f),
            ("折160", "急折·内角20°", _virtualX + 820f),
            ("自交λ", "自交（λ）", _virtualX + 1420f),
            ("∧穿线", "∧ + 穿线", _virtualX + 2000f),
            ("原路折返", "原路折返", _virtualX + 2600f),
            ("浅角自交", "浅角自交", _virtualX + 900f),
        };
        // 3 列 × 2 行摆开（现在只有一种画法了：D2D 原生描边）
        var boxes = new List<(string name, RectF box)>();
        float[] colX = { _virtualX + 260f, _virtualX + 900f, _virtualX + 1560f };
        for (int i = 0; i < kinds.Length; i++)
        {
            int row = i < 3 ? 0 : 1;
            float cy = _virtualY + 380f + row * 460f;
            boxes.Add((kinds[i].name, Make(kinds[i].kind, colX[i % 3], cy)));
        }
        Doc.InvalidateAll();
        SettleFrames(700);

        // 逐个形状找洞：把区域截下来，从边界对"背景色"做连通填充，
        // 填不到又被墨围住的背景像素 = 洞。
        foreach (var (name, box) in boxes)
        {
            int x0 = (int)box.MinX - 6, y0 = (int)box.MinY - 6;
            int ww = (int)(box.MaxX - box.MinX) + 12, hh = (int)(box.MaxY - box.MinY) + 12;
            var px = ScreenProbe.CaptureRegion(x0, y0, ww, hh);
            if (px.Length < ww * hh * 4) { Check(name, false, "截屏失败"); continue; }

            bool IsBackground(int x, int y)
            {
                int i = (y * ww + x) * 4;
                int b = px[i], g = px[i + 1], r = px[i + 2];
                return r > 225 && g > 225 && b > 225;      // 白板底色
            }

            var seen = new bool[ww * hh];
            var stack = new Stack<int>();
            void Push(int x, int y)
            {
                if (x < 0 || y < 0 || x >= ww || y >= hh) return;
                int k = y * ww + x;
                if (seen[k] || !IsBackground(x, y)) return;
                seen[k] = true; stack.Push(k);
            }
            for (int x = 0; x < ww; x++) { Push(x, 0); Push(x, hh - 1); }
            for (int y = 0; y < hh; y++) { Push(0, y); Push(ww - 1, y); }
            while (stack.Count > 0)
            {
                int k = stack.Pop(); int x = k % ww, y = k / ww;
                Push(x - 1, y); Push(x + 1, y); Push(x, y - 1); Push(x, y + 1);
            }

            int holes = 0; int hx = 0, hy = 0;
            for (int y = 0; y < hh; y++)
                for (int x = 0; x < ww; x++)
                    if (!seen[y * ww + x] && IsBackground(x, y))
                    { holes++; if (holes == 1) { hx = x0 + x; hy = y0 + y; } }

            Check(name, holes == 0,
                  holes == 0 ? "没有露底" : $"露出背景 {holes} 像素（第一处在 {hx},{hy}）");
        }

        string shot = Path.Combine("reports", "洞检.bmp");
        ScreenProbe.SaveBmp(shot, (int)(_virtualX + 100f), (int)(_virtualY + 200f), 2400, 1000);
        Console.WriteLine($"  （已导出 {shot}）");
        Console.WriteLine();
        Console.WriteLine($"  合计 {pass + fail} 项：通过 {pass}，失败 {fail}");
        Console.WriteLine();

        BoardOn = boardBefore;
        BoardColor = boardColorBefore;
        Doc.Clear();
        Doc.InvalidateAll();
        _quit = true;
    }

    private void CornerTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 折角自检（拐角会不会缺墨）===");

        float w = 20f * DpiScale;            // 粗笔，问题在粗笔上最明显
        float cx = VirtualScreen.MinX + 700, cy = VirtualScreen.MinY + 600;
        float arm = 400f;

        // 相机归零：下面的兜底判据要数"屏幕上"的像素，靠的是"画布坐标 = 屏幕坐标"
        // 这个前提。别的用例滚动过之后相机不为 0，不归零就会量到错的地方。
        ViewOffsetY = 0f;
        foreach (var win in _windows) { win.ViewOffsetX = 0f; win.ViewOffsetY = 0f; }

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-26} {detail}");
        }

        // 白板：兜底那一处要数屏幕上的黑像素，背景必须是干净的。
        bool boardBefore = BoardOn;
        var boardColorBefore = BoardColor;
        BoardOn = true;
        BoardColor = new Color4(0.98f, 0.98f, 0.98f, 1f);

        // 造一条"先水平走、再按 turnDeg 折过去"的笔迹，中心线上的采样点一并返回。
        (Stroke s, List<Vector2> pts) MakeElbow(float turnDeg)
        {
            var stroke = new Stroke
            {
                Tool = Tool.Pen, Color = new Color4(0, 0, 0, 1), Width = w,
            };
            var samples = new List<Vector2>();
            float rad = turnDeg * MathF.PI / 180f;
            var dir = new Vector2(MathF.Cos(rad), MathF.Sin(rad));
            for (int i = 0; i <= 30; i++)
            {
                var p = new Vector2(cx + arm * i / 30f, cy);
                stroke.AddPoint(p.X, p.Y, 0.5f, i);
                samples.Add(p);
            }
            for (int i = 1; i <= 30; i++)
            {
                var p = new Vector2(cx + arm + dir.X * arm * i / 30f, cy + dir.Y * arm * i / 30f);
                stroke.AddPoint(p.X, p.Y, 0.5f, 30 + i);
                samples.Add(p);
            }
            return (stroke, samples);
        }

        foreach (float turnDeg in new[] { 45f, 90f, 135f, 170f })
        {
            var (s, pts) = MakeElbow(turnDeg);

            // 判据：中心线上的采样点必须都落在墨里。几何现在是"中心线"，
            // 所以用描边判定（和画出来用的是同一条几何、同一个描边样式）。
            var geo = s.BuildGeometry(Gfx.D2DFactory);
            int dry = 0;
            Vector2 dryAt = default;
            foreach (var p in pts)
            {
                if (Vector2.Distance(p, new Vector2(cx + arm, cy)) > arm * 0.6f) continue;
                if (!geo.StrokeContainsPoint(p, MathF.Max(1f, s.Width), Gfx.Round))
                { dry++; dryAt = p; }
            }

            Check($"{turnDeg:F0}° 折角", dry == 0,
                  dry == 0 ? "中心线上每个采样点都有墨"
                           : $"有 {dry} 个采样点是空的（例如 "
                             + $"({dryAt.X - cx - arm:F0},{dryAt.Y - cy:F0})）");
        }

        // ---- 墨不能超出脏区（残影防线）----
        // 脏区（PaddedBounds）算小了不会报错、只会留残影，所以必须自己盯着。
        // 现在的墨 = 中心线 ± 半个笔宽（圆头圆角），用 D2D 的"加宽边界"对账。
        {
            var (s, _) = MakeElbow(90f);
            var geo = s.BuildGeometry(Gfx.D2DFactory);
            var wb = geo.GetWidenedBounds(MathF.Max(1f, s.Width), Gfx.Round, 0.25f);
            var pb = s.PaddedBounds;
            bool inside = wb.Left >= pb.MinX - 0.5f && wb.Top >= pb.MinY - 0.5f
                       && wb.Right <= pb.MaxX + 0.5f && wb.Bottom <= pb.MaxY + 0.5f;
            Check("墨不超出脏区（残影防线）", inside,
                  $"墨 {wb.Left:F0},{wb.Top:F0}→{wb.Right:F0},{wb.Bottom:F0}；"
                  + $"脏区 {pb.MinX:F0},{pb.MinY:F0}→{pb.MaxX:F0},{pb.MaxY:F0}");
        }

        // ---- 兜底：90° 折角在屏幕上真的画出来了（白板 + 拐角窗口）----
        {
            var (s, pts) = MakeElbow(90f);
            var ideal = new Vector2(cx + arm, cy);

            Doc.Clear();
            Doc.InvalidateAll();
            Doc.AddStroke(s);
            SettleFrames(500);

            var onPathPts = new List<Vector2>();
            foreach (var p in pts)
                if (Vector2.Distance(p, ideal) <= w) onPathPts.Add(p);
            int small = 5, darkest = int.MaxValue;
            foreach (var p in onPathPts)
            {
                int h = ScreenProbe.CountNear((int)(p.X - small * 0.5f), (int)(p.Y - small * 0.5f),
                                              small, small, 0, 0, 0, 60);
                if (h < darkest) darkest = h;
            }
            float cover = onPathPts.Count > 0 ? darkest / (float)(small * small) : 0f;
            Check("拐角上屏（白板）", onPathPts.Count > 0 && cover >= 0.8f,
                  $"拐角附近 {onPathPts.Count} 个中心线点，最暗的一个 {cover:P0} 是黑的");

            string shot = Path.Combine("reports", "拐角-放大.bmp");
            ScreenProbe.SaveBmp(shot, (int)(cx + arm - 200f), (int)(cy - 200f), 400, 400);
            Console.WriteLine($"  （拐角已导出：{shot}，白底黑字）");
        }

        Console.WriteLine();
        Console.WriteLine($"  合计 {pass + fail} 项：通过 {pass}，失败 {fail}");
        Console.WriteLine();
        BoardOn = boardBefore;
        BoardColor = boardColorBefore;
        Doc.Clear();
        Doc.InvalidateAll();
        _quit = true;
    }


    private void GenerateStrokes(int strokeCount)
    {
        var rnd = new Random(20260913);
        Doc.Clear();
        for (int i = 0; i < strokeCount; i++)
        {
            var s = new Stroke
            {
                Tool = Tool.Pen,
                Color = PenColor,
                Width = 2.5f + (float)rnd.NextDouble() * 4f,
            };
            float x = _virtualX + (float)rnd.NextDouble() * _virtualW;
            float y = _virtualY + (float)rnd.NextDouble() * _virtualH;
            int pts = 8 + rnd.Next(24);
            float ang = (float)(rnd.NextDouble() * Math.PI * 2);
            for (int j = 0; j < pts; j++)
            {
                ang += (float)((rnd.NextDouble() - 0.5) * 0.7);
                float d = 5f + (float)rnd.NextDouble() * 9f;
                x += MathF.Cos(ang) * d;
                y += MathF.Sin(ang) * d;
                x = Math.Clamp(x, _virtualX + 1, _virtualX + _virtualW - 1);
                y = Math.Clamp(y, _virtualY + 1, _virtualY + _virtualH - 1);
                s.AddPoint(x, y, (float)rnd.NextDouble(), NowMs);
            }
            Doc.AppendStroke(s);
        }
        Doc.ClearHistory();
    }

    /// <summary>
    /// 铺开 <paramref name="screens"/> 屏的笔画。
    ///
    /// 为什么要有它：<see cref="GenerateStrokes"/> 把笔画全塞在一屏里，那是
    /// "满屏"的极端形状，和真实板书不一样。真实情况是**纵向累积**——一节课
    /// 往下写十几屏，每屏只有那么多字。两者的差别对分块缓存是决定性的：
    /// 前者的重建代价随总量涨，后者不该涨。
    /// </summary>
    private void GenerateStrokesSpread(int strokeCount, int screens)
    {
        var rnd = new Random(20260913);
        Doc.Clear();
        float spanH = _virtualH * screens;
        for (int i = 0; i < strokeCount; i++)
        {
            var s = new Stroke
            {
                Tool = Tool.Pen,
                Color = PenColor,
                Kind = StrokeKind.Freehand,
                Width = 2.5f + (float)rnd.NextDouble() * 4f,
            };
            float x = _virtualX + (float)rnd.NextDouble() * _virtualW;
            float y = _virtualY + (float)rnd.NextDouble() * spanH;
            int pts = 8 + rnd.Next(24);
            float ang = (float)(rnd.NextDouble() * Math.PI * 2);
            for (int j = 0; j < pts; j++)
            {
                ang += (float)((rnd.NextDouble() - 0.5) * 0.7);
                float d = 5f + (float)rnd.NextDouble() * 9f;
                x = Math.Clamp(x + MathF.Cos(ang) * d, _virtualX + 1, _virtualX + _virtualW - 1);
                y = Math.Clamp(y + MathF.Sin(ang) * d, _virtualY + 1, _virtualY + spanH - 1);
                s.AddPoint(x, y, (float)rnd.NextDouble(), NowMs);
            }
            Doc.AppendStroke(s);
        }
        Doc.ClearHistory();
    }

    private void Benchmark(int strokeCount)
    {
        Console.WriteLine();
        Console.WriteLine($"=== benchmark: {strokeCount} strokes ===");

        var gen = Stopwatch.StartNew();
        GenerateStrokes(strokeCount);
        gen.Stop();

        var buildSw = Stopwatch.StartNew();
        foreach (var s in Doc.Strokes) s.BuildGeometry(Gfx.D2DFactory);
        buildSw.Stop();

        // Force a full content rebuild so the next frames re-rasterise everything.
        Doc.InvalidateAll();
        _dirty = true;

        RenderAll();
        var w0 = _windows[0];
        double rebuildMs = w0.LastRebuildMs;

        Console.WriteLine($"  generate      : {gen.Elapsed.TotalMilliseconds,8:F1} ms");
        Console.WriteLine($"  build geometry: {buildSw.Elapsed.TotalMilliseconds,8:F1} ms  ({buildSw.Elapsed.TotalMilliseconds / strokeCount:F3} ms/stroke)");
        Console.WriteLine($"  full rebuild  : {rebuildMs,8:F1} ms  (rasterise {strokeCount} strokes onto the content layer)");
        Console.WriteLine($"  points total  : {Doc.TotalPoints}");
        Console.WriteLine($"  working set   : {Process.GetCurrentProcess().WorkingSet64 / 1048576.0:F1} MB");
        Console.WriteLine();
    }

    // =====================================================================
    //  Measurement report
    // =====================================================================

    private void MemoryReport(string outFile)
    {
        var lines = new List<string>();
        void P(string s = "")
        {
            Console.WriteLine(s);
            lines.Add(s);
        }

        // Working set alone is misleading: Windows only drops resident pages
        // under pressure, so a process can look huge while holding very little.
        // Commit charge (private bytes) is the honest number to quote.
        void Settle()
        {
            GC.Collect();
            GC.WaitForPendingFinalizers();
            GC.Collect();
            Mem.TrimWorkingSet();
        }

        P("===== InkTeach 内存归因 =====");
        P($"显卡        : {Gfx.AdapterInfo}");
        P($"屏幕        : {_virtualW}x{_virtualH}，{_windows.Count} 个覆盖窗口");
        P($"对照        : 一个什么都不做的 .NET 控制台程序 = 23.3 MB 工作集 / 6.9 MB 私有");
        P("说明        : 「工作集」（任务管理器里那一列）会被系统随时回收，不反映真实占用；");
        P("              下面统一用「提交大小 / 私有字节」，另外附上显存占用。");
        P();

        P("【分阶段】启动过程中内存的增长");
        foreach (var l in Mem.Log) P("  " + l);
        P();

        for (int i = 0; i < 40; i++) RenderAll();
        Settle();
        P($"【空闲稳态】提交大小 {Mem.Priv():F1} MB（真实占用），工作集 {Mem.Ws():F1} MB");
        P("             （40 帧之后强制回收，这才是产品日常挂着时的占用）");
        P();

        P("【按笔画数】内存增长");
        P("    笔画数 | 提交大小 | 相对空闲 | 显存 (已用/预算) | 场景");
        P("  ---------|----------|----------|------------------|----------------");
        double basePriv = Mem.Priv();
        foreach (int count in new[] { 0, 20, 100, 500, 2000, 10000 })
        {
            GenerateStrokes(count);
            Doc.Version++;
            RenderAll();
            Settle();
            double priv = Mem.Priv();
            string note = count switch
            {
                0 => "空闲",
                <= 100 => "讲一页 PPT",
                <= 500 => "一节完整课程",
                <= 2000 => "重度使用",
                _ => "压力测试",
            };
            string delta = count == 0 ? "    —    " : $"+{priv - basePriv,5:F1} MB";
            P($"  {count,8} | {priv,6:F1} MB | {delta} | {GpuMb(),16} | {note}");
        }
        P();

        // Where exactly does the 10k-stroke memory go?
        P("【一万笔的内存去向】逐步拆开（看提交大小）");
        Doc.Clear();
        Settle();
        RenderAll();
        Settle();
        P($"  清空、回收、并让系统释放后 : 提交 {Mem.Priv(),6:F1} MB | 显存 {GpuMb()}");
        GenerateStrokes(10_000);
        Settle();
        P($"  只生成笔画数据、还没画     : 提交 {Mem.Priv(),6:F1} MB | 显存 {GpuMb()}  （{Doc.TotalPoints} 个点）");
        Doc.Version++;
        RenderAll();
        P($"  第一次整层绘制之后         : 提交 {Mem.Priv(),6:F1} MB | 显存 {GpuMb()}");
        Doc.Clear();
        Settle();
        P($"  再把笔画全部清空并回收后   : 提交 {Mem.Priv(),6:F1} MB | 显存 {GpuMb()}");
        P($"  已释放的几何对象累计       : {Stroke.ReleasedGeometries}");
        P();

        // Cost of one screen-sized offscreen layer.
        {
            Settle();
            double before = Mem.Priv();
            var pf = new Vortice.DCommon.PixelFormat(
                Vortice.DXGI.Format.B8G8R8A8_UNorm, Vortice.DCommon.AlphaMode.Premultiplied);
            var ctx = _windows[0].Context;
            var bmp = ctx.CreateBitmap(new SizeI(_virtualW, _virtualH), IntPtr.Zero, 0,
                new BitmapProperties1(pf, 96f, 96f, BitmapOptions.Target | BitmapOptions.CannotDraw));
            ctx.Target = bmp;
            ctx.BeginDraw();
            ctx.Clear(new Color4(0f, 0f, 0f, 0f));
            ctx.EndDraw();
            ctx.Target = null;
            double after = Mem.Priv();
            bmp.Dispose();
            P($"【图层成本】一张与本屏同尺寸的离屏图层 = +{after - before:F1} MB（提交大小）"
              + $"（理论值 {_virtualW * _virtualH * 4 / 1048576.0:F1} MB；4K 每层 32 MB）");
            P();
        }

        P("【结论】");
        P("  - 空闲基线才是产品日常占用；一万笔那次 200 MB 是压力测试的极端值。");
        P("  - 空闲基线的构成：.NET 运行时 + 程序集约 31 MB，Direct3D/Direct2D/文字约 42 MB，");
        P("    屏幕尺寸的合成缓冲区约 26 MB。");
        P("  - 笔画数量带来的增长主要在 GPU 侧，而且清空之后并不会还回操作系统");
        P("    （Direct2D 内部留着复用），所以峰值是「棘轮式」保持的。");
        P("  - 这是 Direct2D 的行为，不是 .NET 的行为；换成 C++ 也一样。");

        try
        {
            var dir = Path.GetDirectoryName(Path.GetFullPath(outFile));
            if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
            File.WriteAllLines(outFile, lines, System.Text.Encoding.UTF8);
            Console.WriteLine();
            Console.WriteLine("报告已写入 " + Path.GetFullPath(outFile));
        }
        catch (Exception ex) { Console.WriteLine("写报告失败: " + ex.Message); }
    }

    private static double WorkingSetMb()
    {
        var p = Process.GetCurrentProcess();
        p.Refresh();
        return p.WorkingSet64 / 1048576.0;
    }

    private static double PrivateMb()
    {
        var p = Process.GetCurrentProcess();
        p.Refresh();
        return p.PrivateMemorySize64 / 1048576.0;
    }

    /// <summary>Dedicated GPU memory currently held by this process's device.</summary>
    private static string GpuMb()
    {
        try
        {
            if (Gfx.Adapter3 == null) return "n/a";
            var info = Gfx.Adapter3.QueryVideoMemoryInfo(0, Vortice.DXGI.MemorySegmentGroup.Local);
            return $"{info.CurrentUsage / 1048576.0:F0}/{info.Budget / 1048576.0:F0} MB";
        }
        catch { return "n/a"; }
    }

    private (double rec, double present) MeasureFrames(int n)
    {
        double rec = 0, pres = 0;
        for (int i = 0; i < n; i++)
        {
            NowMs = _clock.Elapsed.TotalMilliseconds;
            RenderAll();
            rec += _windows[0].LastRecordMs;
            pres += _windows[0].LastPresentMs;
        }
        return (rec / n, pres / n);
    }

    /// <summary>
    /// Draws a bright magenta probe stroke, waits for the compositor, then looks
    /// for those pixels in a screen grab. This is the only way to tell whether
    /// what the GPU produced actually made it onto the display.
    /// </summary>
    private bool VerifyRendering(out int hits, out int fullScreenHits, out string diag)
    {
        float cx = _virtualX + _virtualW * 0.5f;
        float cy = _virtualY + _virtualH * 0.5f;

        var probe = new Stroke { Tool = Tool.Pen, Color = new Color4(1f, 0f, 1f, 1f), Width = 16f };
        for (int i = 0; i <= 60; i++)
        {
            float t = i / 60f;
            probe.AddPoint(cx - 380 + t * 760, cy + MathF.Sin(t * 6.28f) * 120, 0.8f, NowMs);
        }

        Doc.Clear();
        Doc.AddStroke(probe);
        Doc.InvalidateAll();

        var settle = Stopwatch.StartNew();
        while (settle.ElapsedMilliseconds < 600) { PumpMessages(); RenderAll(); }

        bool ok = ScreenProbe.TryFindMagenta((int)(cx - 400), (int)(cy - 160), 800, 320, out hits);
        fullScreenHits = ok ? hits : ScreenProbe.CountMagenta(_virtualX, _virtualY, _virtualW, _virtualH);
        diag = $"笔画 {Doc.Strokes.Count}，实绘 {_windows[0].LastDrawnStrokes}，"
             + $"重建 {_windows[0].LastRebuildMs:F1} ms，错误 {(string.IsNullOrEmpty(_windows[0].LastError) ? "无" : _windows[0].LastError)}";
        return ok;
    }

    /// <summary>Asks the OS which window is top-most under the screen centre.
    /// Read-only: no synthetic clicks are ever sent.</summary>
    private string ProbeHitTest()
    {
        var pt = new Native.POINT { X = _virtualX + _virtualW / 2, Y = _virtualY + _virtualH / 2 };
        IntPtr under = Native.WindowFromPoint(pt);
        IntPtr own = _windows[0].Hwnd;
        bool ours = under == own || Native.GetAncestor(under, 2 /*GA_ROOT*/) == own;
        return $"hwnd 0x{under:X}{(ours ? " = 本覆盖窗口" : $" ≠ 本覆盖窗口 0x{own:X}")}";
    }

    private void Report(string outFile)
    {
        var lines = new List<string>();
        void P(string s = "")
        {
            Console.WriteLine(s);
            lines.Add(s);
        }

        P("===== InkTeach 实测数据 =====");
        P($"日期          : {DateTime.Now:yyyy-MM-dd HH:mm}");
        P($"显示器        : {_virtualW}x{_virtualH} 虚拟桌面，{_windows.Count} 个覆盖窗口");
        P($"监视器 DPI    : {_windows[0].Dpi}");
        P($"运行时        : .NET {Environment.Version}");
        P($"Windows       : {Environment.OSVersion.Version}");
        P();

        for (int i = 0; i < 8; i++)
        {
            RenderAll();
            if (i < 3)
                P($"  [warmup frame {i}] render error: {(string.IsNullOrEmpty(_windows[0].LastError) ? "none" : _windows[0].LastError)}");
        }

        P($"【基线】0 笔画、空闲           : 工作集 {WorkingSetMb(),6:F1} MB   私有 {PrivateMb(),6:F1} MB   显存 {GpuMb()}");
        P($"【渲染验证】启动后             : {(VerifyRendering(out var h0, out _, out var d0) ? "正常" : "丢失")} ({h0} 像素)  {d0}");
        P();

        // --- 4K layer memory probe -------------------------------------
        {
            double before = WorkingSetMb();
            var probes = new List<ID2D1Bitmap1>();
            var pf = new Vortice.DCommon.PixelFormat(
                Vortice.DXGI.Format.B8G8R8A8_UNorm, Vortice.DCommon.AlphaMode.Premultiplied);
            var ctx = _windows[0].Context;
            for (int i = 0; i < 2; i++)
            {
                var bmp = ctx.CreateBitmap(new SizeI(3840, 2160), IntPtr.Zero, 0,
                    new BitmapProperties1(pf, 96f, 96f, BitmapOptions.Target | BitmapOptions.CannotDraw));
                // Force the allocation: Direct2D commits memory lazily on first use.
                ctx.Target = bmp;
                ctx.BeginDraw();
                ctx.Clear(new Color4(0f, 0f, 0f, 0f));
                ctx.EndDraw();
                ctx.Target = null;
                probes.Add(bmp);
            }
            double after = WorkingSetMb();
            P($"【内存】额外 2 张 3840x2160 图层: 工作集 +{after - before:F1} MB，显存 {GpuMb()}");
            P("        （两张图层理论值 2 x 3840 x 2160 x 4B = 66 MB。注意 GPU 合成的图层通常");
            P("          不计入进程工作集，要看显存/专用 GPU 内存，任务管理器里也要看这一列。）");
            foreach (var b in probes) b.Dispose();
            P();
        }

        // --- per-stroke-count measurements -----------------------------
        P("【性能】按笔画数量对比（记录=CPU 提交绘制命令，上屏=交到显示器）");
        P();
        P("  笔画数 | 首帧全量重建 | 缓存层每帧记录 | 不缓存每帧记录 | 上屏 | 工作集");
        P("  -------|--------------|----------------|----------------|------|--------");

        foreach (int count in new[] { 0, 1_000, 10_000 })
        {
            GenerateStrokes(count);
            NoContentCache = false;

            Doc.InvalidateAll();
            NowMs = _clock.Elapsed.TotalMilliseconds;
            RenderAll();
            double rebuild = _windows[0].LastRebuildMs;

            var cached = MeasureFrames(count >= 10_000 ? 30 : 20);

            NoContentCache = true;
            var uncached = MeasureFrames(count >= 10_000 ? 8 : 20);
            NoContentCache = false;

            // Keep the cached layer in sync again for the next round.
            Doc.Version++;

            P($"  {count,7} | {rebuild,10:F1} ms | {cached.rec,12:F2} ms | {uncached.rec,12:F2} ms | {cached.present,4:F2} ms | {WorkingSetMb(),5:F1} MB / 显存 {GpuMb()}");
        }
        P();

        bool okAfterTable = VerifyRendering(out var h1, out _, out var d1);
        P($"【渲染验证】性能测试之后       : {(okAfterTable ? "正常" : "丢失")} ({h1} 像素)  {d1}");
        P();

        // --- eraser: correctness, then cost ----------------------------
        EraseCheck(out bool eraseOk, out string eraseDetail);
        P($"【橡皮擦】擦除是否正确          : {(eraseOk ? "正确" : "异常")}  {eraseDetail}");
        P();

        // --- interactive path: cost of committing one new stroke ---------
        {
            GenerateStrokes(10_000);
            Doc.Version++;
            RenderAll();

            double sum = 0;
            const int n = 25;
            var rnd = new Random(7);
            for (int i = 0; i < n; i++)
            {
                var s = new Stroke { Tool = Tool.Pen, Color = PenColor, Width = 4f };
                float x = _virtualX + (float)rnd.NextDouble() * _virtualW;
                float y = _virtualY + (float)rnd.NextDouble() * _virtualH;
                for (int j = 0; j < 12; j++)
                {
                    x += 9; y += 7;
                    s.AddPoint(x, y, 0.7f, NowMs);
                }
                Doc.AppendStroke(s);
                NowMs = _clock.Elapsed.TotalMilliseconds;
                RenderAll();
                sum += _windows[0].LastPatchMs;
            }
            P($"【交互路径】在 1 万笔画的画面上，结束一笔的增量更新: {sum / n:F2} ms/笔"
              + $"（对照：整层重画 {_windows[0].LastRebuildMs:F0} ms 量级）");

            // Eraser drag: each step removes the strokes under the cursor and
            // repaints only that little box.
            double eraseSum = 0;
            int eraseSteps = 0, eraseRemoved = 0;
            var rnd2 = new Random(11);
            float ex = _virtualX + (float)rnd2.NextDouble() * _virtualW;
            float ey = _virtualY + (float)rnd2.NextDouble() * _virtualH;
            double eraseRebuildRef = _windows[0].LastRebuildMs;
            for (int i = 0; i < n; i++)
            {
                ex += 14; ey += 9;
                eraseRemoved += Doc.EraseAt(ex, ey, 30f);
                NowMs = _clock.Elapsed.TotalMilliseconds;
                RenderAll();
                eraseSum += _windows[0].LastPatchMs;
                eraseSteps++;
            }
            P($"【橡皮擦】在 1 万笔画的画面上，擦除拖动一步: {eraseSum / eraseSteps:F2} ms/步"
              + $"（共擦掉 {eraseRemoved} 笔；对照整层重画 {eraseRebuildRef:F0} ms）");

            // 像素橡皮的一步：命中判定 + 切段 + 重画那一小块。它比整笔橡皮多做
            // 一件事（切段与新建碎片），所以必须单独量——不能拿整笔橡皮的数字顶替。
            double cutSum = 0;
            int cutSteps = 0, cutStrokes = 0;
            double cutSelfMs = 0;
            int cutTiles = 0, cutDrawn = 0;
            var rnd3 = new Random(13);
            float bx = _virtualX + (float)rnd3.NextDouble() * _virtualW;
            float by = _virtualY + (float)rnd3.NextDouble() * _virtualH;
            int objBefore = Doc.Strokes.Count;
            // 注意：这里走的是**一次完整拖拽**的 API（Begin/End），和用户真擦一笔一模一样。
            // 拖拽中每步只改区间（便宜），松手时一次性落成独立对象——那一笔单独计时。
            Doc.BeginEraseRect();
            for (int i = 0; i < n; i++)
            {
                bx += 14; by += 9;
                var swCut = Stopwatch.StartNew();
                cutStrokes += Doc.EraseRectAt(bx, by, PixelEraserHalfWidthPx, PixelEraserHalfHeightPx);
                swCut.Stop();
                cutSelfMs += swCut.Elapsed.TotalMilliseconds;
                NowMs = _clock.Elapsed.TotalMilliseconds;
                RenderAll();
                cutSum += _windows[0].LastPatchMs;
                cutTiles += _windows[0].LastPatchCount;
                cutDrawn += _windows[0].LastDrawnStrokes;
                cutSteps++;
            }
            var swSettle = Stopwatch.StartNew();
            Doc.EndErase();
            swSettle.Stop();
            double settleMs = swSettle.Elapsed.TotalMilliseconds;
            P($"【像素橡皮】在 1 万笔画的画面上，擦除拖动一步: {cutSum / cutSteps:F2} ms/步"
              + $"（其中擦除本身 {cutSelfMs / cutSteps:F2} ms + 重画 {cutSum / cutSteps - cutSelfMs / cutSteps:F2} ms；"
              + $"共切到 {cutStrokes} 笔、每步重画 {cutTiles / (double)cutSteps:F1} 块；"
              + $"对象数 {objBefore} → {Doc.Strokes.Count}（区间表那一版不涨，拆对象那版会涨到 {objBefore + cutStrokes}）；"
              + $"每步重画笔数 {cutDrawn / (double)cutSteps:F0}；"
              + $"松手结账（区间 → 独立对象）{settleMs:F1} ms，一次性；"
              + $"整笔橡皮同位置 {eraseSum / eraseSteps:F2} ms/步）");
            // 上面这几个数（擦除本身 / 重画 / 每步几块 / 每步几笔）是**分得开**的：
            // 换一版实现时就看得出慢在哪一半——2026-09-15 比"拆对象"和"区间表"两版，
            // 擦除本身 5.9→2.9ms（快一倍）、重画 2.5→5.8ms（每步要画的笔数 764→886，
            // 多出来的是"被擦过但还在文档里"的整条笔迹）。

            // Undo of a single stroke costs the same as an erase patch.
            double undoSum = 0;
            int undoCount = 0;
            for (int i = 0; i < n; i++)
            {
                if (!Doc.Undo()) break;
                NowMs = _clock.Elapsed.TotalMilliseconds;
                RenderAll();
                undoSum += _windows[0].LastPatchMs;
                undoCount++;
            }
            P($"【撤销】在 1 万笔画的画面上，撤销一步: {(undoCount > 0 ? undoSum / undoCount : 0):F2} ms/步"
              + $"（{undoCount} 步）");
            P();

            // Where does an erase step actually spend its time? Split the hit
            // test from the repaint, and A/B the spatial index against a linear
            // scan over every stroke. Runs after the undo measurement because
            // it rebuilds the document and clears the undo history.
            {
                GenerateStrokes(10_000);
                Doc.InvalidateAll();
                RenderAll();

                var list = new List<Stroke>();
                var rndQ = new Random(99);
                var probes = new RectF[500];
                for (int i = 0; i < probes.Length; i++)
                {
                    float px = _virtualX + (float)rndQ.NextDouble() * _virtualW;
                    float py = _virtualY + (float)rndQ.NextDouble() * _virtualH;
                    probes[i] = new RectF { MinX = px - 45, MinY = py - 45, MaxX = px + 45, MaxY = py + 45 };
                }

                var swq = Stopwatch.StartNew();
                int found = 0;
                foreach (var r in probes) found += Doc.QueryGrid(r, list);
                swq.Stop();

                var swl = Stopwatch.StartNew();
                int found2 = 0;
                foreach (var r in probes)
                    foreach (var s in Doc.Strokes)
                        if (s.Bounds.Intersects(r)) found2++;
                swl.Stop();

                P($"【命中测试】500 次查询：空间索引 {swq.Elapsed.TotalMilliseconds:F1} ms"
                  + $"，全表扫描 {swl.Elapsed.TotalMilliseconds:F1} ms"
                  + $"（提速 {swl.Elapsed.TotalMilliseconds / Math.Max(0.01, swq.Elapsed.TotalMilliseconds):F0} 倍，命中 {found2} 条）");
                P();
            }
        }

        // --- laser cost on top of 10k cached strokes --------------------
        GenerateStrokes(10_000);
        Doc.Version++;
        RenderAll();
        var idle10k = MeasureFrames(20);

        double MeasureLaser(out int frames)
        {
            Laser.Clear();
            Laser.Begin(_virtualX + _virtualW * 0.5f, _virtualY + _virtualH * 0.5f,
                        _clock.Elapsed.TotalMilliseconds, LaserWidthLogical);
            double t0 = _clock.Elapsed.TotalMilliseconds;
            double total = 0;
            frames = 0;
            while (_clock.Elapsed.TotalMilliseconds - t0 < 2000)
            {
                double t = _clock.Elapsed.TotalMilliseconds;
                float px = _virtualX + _virtualW * 0.5f + (float)(Math.Sin(t / 300.0) * 400);
                float py = _virtualY + _virtualH * 0.5f + (float)(Math.Cos(t / 220.0) * 200);
                Laser.Add(px, py, t);
                NowMs = t;
                Laser.Prune(NowMs);
                RenderAll();
                total += _windows[0].LastRecordMs;
                frames++;
            }
            Laser.Clear();
            return frames > 0 ? total / frames : 0;
        }

        double laserRibbon = MeasureLaser(out int framesRibbon);
        P($"【激光笔】1 万笔画之上叠加激光轨迹（每帧记录耗时）");
        P($"    画激光                 : {laserRibbon:F2} ms   （{framesRibbon} 帧）");
        P($"    不开激光（同一画面）   : {idle10k.rec:F2} ms");
        bool okAfterLaser = VerifyRendering(out var h2, out _, out var d2);
        P($"【渲染验证】激光笔之后         : {(okAfterLaser ? "正常" : "丢失")} ({h2} 像素)  {d2}");
        P();

        // --- pass-through rendering check ------------------------------
        P("【穿透】三种实现方式下，覆盖层是否仍然正常显示：");
        PassThrough = false;
        foreach (var w in _windows) ApplyPassThroughStyle(w);
        P($"  {"（对照）不穿透",-20} : 命中测试 {ProbeHitTest()}");
        foreach (PassThroughMode m in new[] { PassThroughMode.HitTest, PassThroughMode.ExTransparent, PassThroughMode.LayeredTransparent })
        {
            PassThrough = true;
            PassMode = m;
            foreach (var w in _windows) ApplyPassThroughStyle(w);

            bool visible = VerifyRendering(out int hits, out int allHits, out string diag);
            string extra = "";
            if (!visible) extra = $"  全屏另找到 {allHits} 个同色像素";
            P($"  {m,-20} : {(visible ? "渲染正常" : "渲染丢失")}  ({hits} 像素){extra}");
            P($"      诊断: {diag}");

            P($"      命中测试: {ProbeHitTest()}");

            PassThrough = false;
            foreach (var w in _windows) ApplyPassThroughStyle(w);
        }
        P();
        P("说明：「渲染正常」只表示覆盖层本身没被破坏。鼠标点击是否真的落到下层程序，需要在真机上手动确认。");

        try
        {
            var dir = Path.GetDirectoryName(Path.GetFullPath(outFile));
            if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
            File.WriteAllLines(outFile, lines, System.Text.Encoding.UTF8);
            Console.WriteLine();
            Console.WriteLine("报告已写入 " + Path.GetFullPath(outFile));
        }
        catch (Exception ex)
        {
            Console.WriteLine("写报告失败: " + ex.Message);
        }
    }

    private void MemoryProbe()
    {
        Console.WriteLine();
        Console.WriteLine("=== memory probe: cost of one full-screen content layer ===");
        var proc = Process.GetCurrentProcess();
        proc.Refresh();
        double before = proc.WorkingSet64 / 1048576.0;

        var pf = new Vortice.DCommon.PixelFormat(
            Vortice.DXGI.Format.B8G8R8A8_UNorm, Vortice.DCommon.AlphaMode.Premultiplied);
        var probes = new List<ID2D1Bitmap1>();
        var ctx = _windows[0].Context;
        int w = 3840, h = 2160;
        for (int i = 0; i < 3; i++)
        {
            probes.Add(ctx.CreateBitmap(new SizeI(w, h), IntPtr.Zero, 0,
                new BitmapProperties1(pf, 96f, 96f, BitmapOptions.Target | BitmapOptions.CannotDraw)));
        }
        proc.Refresh();
        double after = proc.WorkingSet64 / 1048576.0;
        Console.WriteLine($"  {w}x{h} x3 layers: working set {before:F1} MB -> {after:F1} MB  (delta {after - before:F1} MB)");
        foreach (var b in probes) b.Dispose();
        Console.WriteLine();
    }

    // =====================================================================
    //  Self test
    // =====================================================================

    private void SelfTest(double seconds)
    {
        Console.WriteLine();
        Console.WriteLine("=== self test ===");
        Console.WriteLine("drawing a synthetic stroke across the primary monitor...");

        var probe = new Stroke { Tool = Tool.Pen, Color = new Color4(1f, 0f, 1f, 1f), Width = 14f };
        float cx = _virtualX + _virtualW * 0.5f;
        float cy = _virtualY + _virtualH * 0.3f;
        for (int i = 0; i <= 60; i++)
        {
            float t = i / 60f;
            probe.AddPoint(cx - 400 + t * 800, cy + MathF.Sin(t * 6.28f) * 120, 0.8f, NowMs);
        }
        Doc.AddStroke(probe);
        _dirty = true;

        RenderAll();

        // Let DirectComposition settle, then verify the pixels really reached the screen.
        var settle = Stopwatch.StartNew();
        while (settle.ElapsedMilliseconds < 700)
        {
            PumpMessages();
            RenderAll();
        }

        bool found = ScreenProbe.TryFindMagenta((int)(cx - 420), (int)(cy - 160), 840, 320, out int hits);
        Console.WriteLine(found
            ? $"PASS: overlay pixels verified on screen ({hits} matching pixels)"
            : $"FAIL: no overlay pixels found on screen ({hits} matches)");
        LastCaptureReport = found ? "rendering verified" : "rendering NOT verified";

        Console.WriteLine();
        Console.WriteLine("running the 10k-stroke benchmark...");
        Benchmark(10_000);

        Console.WriteLine("laser stress: forcing a continuous 120 Hz trail...");
        // 一条**一直写**的长轨迹（2026-09-27 起激光笔"手写期间整条都留着"，
        // 所以这里量的正是"点最多、最贵"的那一种：它会一直涨到 3 秒长）。
        Laser.Begin(cx - 300, cy + 400, _clock.Elapsed.TotalMilliseconds, LaserWidthLogical);
        var t0 = _clock.Elapsed.TotalMilliseconds;
        while (_clock.Elapsed.TotalMilliseconds - t0 < 3000)
        {
            double t = _clock.Elapsed.TotalMilliseconds;
            float px = cx - 300 + (float)(Math.Sin(t / 300.0) * 300);
            float py = cy + 400 + (float)(Math.Cos(t / 220.0) * 120);
            Laser.Add(px, py, t);
            NowMs = t;
            Laser.Prune(NowMs);
            PumpMessages();
            RenderAll();
        }
        Laser.Clear();

        Console.WriteLine();
        Console.WriteLine("--- summary ---");
        Console.WriteLine($"  rendering verified : {LastCaptureReport}");
        Console.WriteLine($"  fps                : {_fps:F1}");
        Console.WriteLine($"  record per frame   : {_lastRecordMs:F2} ms");
        Console.WriteLine($"  present per frame  : {_lastPresentMs:F2} ms");
        Console.WriteLine($"  full rebuild       : {_lastRebuildMs:F1} ms");
        Console.WriteLine($"  working set        : {Process.GetCurrentProcess().WorkingSet64 / 1048576.0:F1} MB");
        Console.WriteLine($"  peak working set   : {_peakWorkingSetMb:F1} MB");
        Console.WriteLine();
    }

    private void PumpMessages()
    {
        while (Native.PeekMessage(out var msg, IntPtr.Zero, 0, 0, 1))
        {
            Native.TranslateMessage(ref msg);
            Native.DispatchMessage(ref msg);
        }
        NowMs = _clock.Elapsed.TotalMilliseconds;
    }

    /// <summary>Renders for a while so DirectComposition has definitely put the
    /// latest frame on screen before we grab pixels.</summary>
    private void SettleFrames(int ms)
    {
        var sw = Stopwatch.StartNew();
        while (sw.ElapsedMilliseconds < ms)
        {
            PumpMessages();
            StepCameraAnim();          // 主循环每帧做的那一件事，自检也得做（否则相机永远停在起点）
            RenderAll();
        }
    }

    // ------------------------------------------------------------------
    //  Synthetic input test
    // ------------------------------------------------------------------

    private static Native.INPUT MouseInput(int x, int y, uint extraFlags, int vx, int vy, int vw, int vh)
    {
        var inp = new Native.INPUT { type = Native.INPUT_MOUSE };
        inp.mi.dx = (int)Math.Round((x - vx) * 65535.0 / Math.Max(1, vw - 1));
        inp.mi.dy = (int)Math.Round((y - vy) * 65535.0 / Math.Max(1, vh - 1));
        inp.mi.dwFlags = Native.MOUSEEVENTF_MOVE | Native.MOUSEEVENTF_ABSOLUTE
                       | Native.MOUSEEVENTF_VIRTUALDESK | extraFlags;
        return inp;
    }

    private void SendMouse(int x, int y, uint extraFlags)
    {
        var inp = new[] { MouseInput(x, y, extraFlags, _virtualX, _virtualY, _virtualW, _virtualH) };
        Native.SendInput(1, inp, Marshal.SizeOf<Native.INPUT>());
    }

    private static Native.INPUT_KBD KeyInput(ushort vk, bool up)
    {
        var inp = new Native.INPUT_KBD { type = Native.INPUT_KEYBOARD };
        inp.ki.wVk = vk;
        inp.ki.dwFlags = up ? Native.KEYEVENTF_KEYUP : 0u;
        return inp;
    }

    /// <summary>
    /// 合成键盘：把一串虚拟键**按顺序按下、再倒序抬起**（Ctrl+Alt+O 这种组合必须这样发，
    /// 只按主键是触发不了全局热键的）。
    ///
    /// 为什么要它（而不是像批注内按键那样直接 `PostMessage`）：全局热键是**系统**在
    /// 键盘输入流上判定的，`RegisterHotKey` 收到的是真实的按键；要验"按下去真的切了工具"，
    /// 就得走真实的键盘通路。批注内那些键不用它是因为它们由我们自己的窗口收，
    /// 直接投递窗口消息就能到。
    /// </summary>
    private uint SendKeyChord(params ushort[] vks)
    {
        var seq = new List<Native.INPUT_KBD>();
        foreach (var vk in vks) seq.Add(KeyInput(vk, false));
        for (int i = vks.Length - 1; i >= 0; i--) seq.Add(KeyInput(vks[i], true));
        // 返回值＝**真的塞进系统输入流的事件个数**。自检要把它打出来：
        // 它比"工具没切"多一层信息——分得清"按键没进系统"和"进了但热键没响应"。
        return Native.SendInput((uint)seq.Count, seq.ToArray(), Marshal.SizeOf<Native.INPUT_KBD>());
    }

    private const ushort VK_CONTROL = 0x11;
    private const ushort VK_MENU = 0x12;        // Alt

    /// <summary>按一次 Ctrl+Alt+&lt;主键&gt;（全局热键都是这个形状）。返回塞进去的事件数。</summary>
    private uint SendCtrlAlt(ushort vk) => SendKeyChord(VK_CONTROL, VK_MENU, vk);

    /// <summary>
    /// Drives a real drag through SendInput so the whole input path is exercised
    /// end to end - pointer messages, stroke accumulation, redraw, and finally
    /// pixels on screen. Synthetic input is consumed by this overlay, which is
    /// topmost, so nothing underneath is clicked.
    /// </summary>
    // ------------------------------------------------------------------
    //  Click target (second process) + real pass-through test
    // ------------------------------------------------------------------

    /// <summary>Runs a plain window in its own process that records every time
    /// it is clicked. Used as the window underneath the overlay.</summary>
    private void RunClickTarget(string logFile)
    {
        _clickLogFile = logFile;
        _clickTargetHwnd = Native.CreateWindowEx(
            0, _className, "InkTeach 点击目标",
            0x00CF0000L /*WS_OVERLAPPEDWINDOW*/, 120, 120, 420, 320,
            IntPtr.Zero, IntPtr.Zero, _hInstance, IntPtr.Zero);
        if (_clickTargetHwnd == IntPtr.Zero)
        {
            File.WriteAllText(logFile, "error\n");
            return;
        }
        Native.ShowWindow(_clickTargetHwnd, 5 /*SW_SHOW*/);
        File.WriteAllText(logFile, "ready\n");

        while (!_quit)
        {
            if (Native.GetMessage(out var msg, IntPtr.Zero, 0, 0))
            {
                Native.TranslateMessage(ref msg);
                Native.DispatchMessage(ref msg);
            }
            else break;
        }
    }

    private static int CountClicks(string file)
    {
        try
        {
            if (!File.Exists(file)) return 0;
            var text = ReadTextShared(file);
            int n = 0, i = 0;
            while ((i = text.IndexOf("clicked", i, StringComparison.Ordinal)) >= 0) { n++; i += 7; }
            return n;
        }
        catch { return 0; }
    }

    /// <summary>
    /// 读一个"另一个进程正在写"的小文件，**带重试**。
    ///
    /// 为什么需要：点击目标进程每隔一会儿就往这个文件里追加一行，父进程同时在读；
    /// 撞上共享冲突时 `File.ReadAllText` 直接抛 IOException，整条用例会以"异常"收场
    /// 而不是判据失败——套件里就报成 FATAL，看起来像功能坏了。
    /// 这类"测试自己的时序问题"必须和被测的东西分开，不然会浪费很多时间去查一个不存在的 bug。
    /// </summary>
    private static string ReadTextShared(string path, int timeoutMs = 3000)
    {
        var sw = Stopwatch.StartNew();
        while (true)
        {
            try { return File.ReadAllText(path); }
            catch (IOException) when (sw.ElapsedMilliseconds < timeoutMs) { Thread.Sleep(20); }
            catch (UnauthorizedAccessException) when (sw.ElapsedMilliseconds < timeoutMs) { Thread.Sleep(20); }
            catch (Exception) { return ""; }   // 到点了还读不到就当空的，别把用例打成异常
        }
    }

    /// <summary>
    /// The real question is not "does hit testing report another window" - that
    /// gave a false pass - but "does a click actually arrive at the window
    /// underneath". So this spawns a second process with a target window,
    /// synthesises real clicks, and counts how many it received.
    /// </summary>
    private void PassThroughTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 穿透真机测试（合成真实点击，看下层窗口收不收到）===");

        string dir = Path.Combine(Path.GetTempPath(), "inkprobe_passtest");
        Directory.CreateDirectory(dir);
        // 每次跑用**带进程号的文件名**：上一轮要是留了个没退干净的点击目标进程，
        // 它还在往老文件里写，两边就会抢同一个文件（套件里真撞到过一次）。
        string log = Path.Combine(dir, $"target-{Environment.ProcessId}.txt");
        File.WriteAllText(log, "");      // must write before spawning? no: spawn then wait for ready

        var psi = new ProcessStartInfo(Environment.ProcessPath, $"--clicktarget \"{log}\"")
        {
            UseShellExecute = false,
        };
        var target = Process.Start(psi);
        if (target == null) { Console.WriteLine("  无法启动点击目标进程"); _quit = true; return; }

        // 读的时候带重试：父进程读、子进程写，撞上共享冲突时直接抛会把整条用例打成异常
        for (int i = 0; i < 120 && !ReadTextShared(log, 200).Contains("ready"); i++)
            Thread.Sleep(50);
        if (!ReadTextShared(log, 200).Contains("ready"))
        {
            Console.WriteLine("  点击目标窗口没有就绪");
            target.Kill();
            _quit = true;
            return;
        }

        int tx = 120 + 210, ty = 120 + 160;   // centre of the target window

        // Expected outcomes come from the documented rules:
        //  - HTTRANSPARENT only hands off to windows of the same thread
        //  - WS_EX_TRANSPARENT only makes a *layered* window click-through
        (string name, bool pass, bool expectReach, PassThroughMode mode)[] cases =
        {
            ("对照：不穿透",              false, false, PassThroughMode.LayeredTransparent),
            ("只改命中测试返回值",        true,  false, PassThroughMode.HitTest),
            ("只加 WS_EX_TRANSPARENT",    true,  false, PassThroughMode.ExTransparent),
            ("加 LAYERED+TRANSPARENT",    true,  true,  PassThroughMode.LayeredTransparent),
        };

        int failures = 0;
        foreach (var (name, pass, expectReach, mode) in cases)
        {
            PassMode = mode;
            PassThrough = pass;
            foreach (var w in _windows) ApplyPassThroughStyle(w);

            SettleFrames(150);

            int before = CountClicks(log);
            SendMouse(tx, ty, 0);
            SettleFrames(80);
            SendMouse(tx, ty, Native.MOUSEEVENTF_LEFTDOWN);
            SettleFrames(60);
            SendMouse(tx, ty, Native.MOUSEEVENTF_LEFTUP);
            SettleFrames(400);
            int after = CountClicks(log);

            bool reached = after > before;
            bool good = reached == expectReach;
            if (!good) failures++;
            Console.WriteLine($"  {name,-26} 下层窗口收到点击: {(reached ? "是" : "否"),-2}"
                              + $"  文档预期: {(expectReach ? "是" : "否"),-2}  {(good ? "PASS" : "FAIL")}"
                              + (pass ? "" : "   （对照组）"));
        }
        Console.WriteLine(failures == 0 ? "  结论: 穿透行为与文档一致" : $"  结论: {failures} 项与文档不符");

        PassThrough = false;
        foreach (var w in _windows) ApplyPassThroughStyle(w);

        try { target.Kill(); } catch { }
        _quit = true;
    }

    /// <summary>
    /// 界面输入通路的真机自检：把"面板内 / 面板外 × 穿透开 / 穿透关 × 界面吃不吃"
    /// 这几种组合各合成一次**真实点击**，然后看**到底谁收到了**。
    ///
    /// 四类判定（这就是引擎与界面之间那四条规矩）：
    ///
    ///   · 命中界面矩形、界面消费 → 归界面（画布不落墨，穿透也不交下层）
    ///   · 命中界面矩形、界面没消费 → 画布不落墨；穿透时交下层
    ///   · 没命中界面矩形 → 穿透时交下层，否则照常落墨
    ///   · 悬停同样要转发给界面（按钮高亮靠它），坐标必须是**逻辑屏幕**坐标
    ///
    /// 为什么非要真窗口 + 真点击：这一类 bug 全在"系统命中测试 → WM_NCHITTEST →
    /// WM_POINTER* → 引擎"这条路上，纯函数自检与不接引擎的假面板**都看不见**。
    /// 合成输入走的就是真实的那条路。
    /// </summary>
    private void UiInputTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 界面输入通路自检（合成真实点击，看谁收到）===");

        if (SkipIfNoSyntheticInput("界面输入通路自检")) { _quit = true; return; }

        // 目标窗口：另一个进程里的一块普通窗口，被我们的覆盖层压着。
        string dir = Path.Combine(Path.GetTempPath(), "inkprobe_uitest");
        Directory.CreateDirectory(dir);
        string log = Path.Combine(dir, $"target-{Environment.ProcessId}.txt");   // 同 --passtest：按进程号分开
        File.WriteAllText(log, "");

        var psi = new ProcessStartInfo(Environment.ProcessPath, $"--clicktarget \"{log}\"")
        {
            UseShellExecute = false,
        };
        var target = Process.Start(psi);
        if (target == null)
        {
            Console.WriteLine("  无法启动点击目标进程");
            _quit = true;
            return;
        }

        for (int i = 0; i < 120 && !ReadTextShared(log, 200).Contains("ready"); i++)
            Thread.Sleep(50);
        if (!ReadTextShared(log, 200).Contains("ready"))
        {
            Console.WriteLine("  点击目标窗口没有就绪");
            try { target.Kill(); } catch { }
            _quit = true;
            return;
        }

        // 面板盖住目标窗口的中段：这样"面板内"和"面板外"两个落点都在同一个
        // 下层窗口里，唯一的差别就是有没有被界面接住。
        const int twX = 120, twY = 120, twW = 420, twH = 320;
        int cx = twX + twW / 2, cy = twY + twH / 2;
        int panelX = cx - 140, panelW = 280, panelH = 140;

        var probe = new UiProbe
        {
            BoundsPhysical = new RectF
            {
                MinX = panelX, MinY = cy - panelH / 2,
                MaxX = panelX + panelW, MaxY = cy + panelH / 2,
            },
        };
        SetUi(probe);
        Tool = Tool.Pen;
        Doc.Clear();
        Doc.InvalidateAll();
        SettleFrames(200);

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-26} {detail}");
        }

        void Click(int x, int y)
        {
            SendMouse(x, y, 0);                            SettleFrames(80);
            SendMouse(x, y, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
            SendMouse(x, y, Native.MOUSEEVENTF_LEFTUP);    SettleFrames(320);
        }

        void SetPass(bool on)
        {
            PassMode = PassThroughMode.LayeredTransparent;
            PassThrough = on;
            foreach (var w in _windows) ApplyPassThroughStyle(w);
            SettleFrames(150);
        }

        // 三个落点：都在目标窗口的**客户区**里（窗口有边框和标题栏，
        // 点在标题栏上系统不会发 WM_LBUTTONDOWN，下层就"收不到点击"了），
        // 差别只在面板/界面怎么处理。
        int inX = cx - 80, inY = cy;             // 面板左半：界面会消费
        int holeX = cx + 80, holeY = cy;         // 面板右半：界面返回 false
        int outX = cx, outY = cy + 140;          // 面板下沿之外、客户区内

        // ---- ① 悬停要能到界面 ----
        SetPass(false);
        probe.Move = 0;
        SendMouse(inX, inY, 0);
        SettleFrames(200);
        Check("悬停转发到界面", probe.Move > 0, $"界面收到 {probe.Move} 次移动");

        // ---- ② 悬停坐标必须是"逻辑屏幕"，不能是画布坐标 ----
        // 判法：同一个物理点，相机滚过之后再悬停一次，界面看到的坐标不该变。
        float y0 = probe.LastY;
        ViewOffsetY = -300f;
        SettleFrames(150);
        SendMouse(inX, inY + 6, 0);              // 错开一点，确保真的有 WM_POINTERUPDATE
        SettleFrames(200);
        float y1 = probe.LastY;
        bool coordsUsable = !float.IsNaN(y0) && !float.IsNaN(y1);
        bool drift = coordsUsable && MathF.Abs(y1 - y0) > 4f;
        Check("悬停坐标不受相机影响", coordsUsable && !drift,
              coordsUsable
                  ? $"滚前 y={y0:F0}，滚后 y={y1:F0}（差 {MathF.Abs(y1 - y0):F0} 像素）"
                  : "界面根本没收到悬停，这一项无从判定");
        ViewOffsetY = 0f;
        SettleFrames(150);

        // ---- ③ 不穿透：面板内点击归界面，且不许画出一笔 ----
        int strokes0 = Doc.Strokes.Count;
        int clicks0 = CountClicks(log);
        probe.Down = 0;
        Tool = Tool.Pen;
        Click(inX, inY);
        bool uiGot = probe.Down > 0;
        Check("不穿透·点面板归界面", uiGot, $"界面收到 {probe.Down} 次按下");
        Check("不穿透·点面板不落墨", Doc.Strokes.Count == strokes0,
              $"笔画 {strokes0} → {Doc.Strokes.Count}");
        Check("不穿透·点面板不传下层", CountClicks(log) == clicks0, "下层窗口没收到点击");
        Check("界面的命令真的到了引擎", probe.LastToolFromState == Tool.Eraser,
              $"界面按钮把工具切成了 {probe.LastToolFromState}");

        // ---- ④ 不穿透：界面"看见了但不吃"的那一半也不该落墨 ----
        Tool = Tool.Pen;
        strokes0 = Doc.Strokes.Count;
        Click(holeX, holeY);
        Check("不穿透·面板空洞不落墨", Doc.Strokes.Count == strokes0,
              $"笔画 {strokes0} → {Doc.Strokes.Count}");

        // ---- ⑤ 不穿透：面板外照常画线 ----
        Tool = Tool.Pen;
        strokes0 = Doc.Strokes.Count;
        clicks0 = CountClicks(log);
        Click(outX, outY);
        Check("不穿透·面板外照常落墨", Doc.Strokes.Count > strokes0,
              $"笔画 {strokes0} → {Doc.Strokes.Count}");
        Check("不穿透·面板外不传下层", CountClicks(log) == clicks0, "下层窗口没收到点击");

        // ---- ⑥ 穿透：面板内点击必须由界面收下（这就是这次要修的那条）----
        SetPass(true);

        // 穿透下悬停也要到界面：这是"看 PPT 时随手叫出笔"的同一组合。
        probe.Move = 0;
        SendMouse(inX, inY, 0);
        SettleFrames(220);
        Check("穿透·悬停到界面", probe.Move > 0, $"界面收到 {probe.Move} 次移动");

        clicks0 = CountClicks(log);
        strokes0 = Doc.Strokes.Count;
        probe.Down = 0;
        Tool = Tool.Pen;
        Click(inX, inY);
        Check("穿透·点面板归界面", probe.Down > 0, $"界面收到 {probe.Down} 次按下");
        Check("穿透·面板不许穿到下层", CountClicks(log) == clicks0,
              $"下层窗口收到 {CountClicks(log) - clicks0} 次点击（应为 0）");
        Check("穿透·点面板不落墨", Doc.Strokes.Count == strokes0,
              $"笔画 {strokes0} → {Doc.Strokes.Count}");

        // ---- ⑦ 穿透：面板是界面的地盘，"看见但不吃"也不许漏给下层 ----
        // （面板要放行某个位置，得它自己别把那一块算进 QueryBounds；
        //   将来若真需要"面板中间挖个洞让点击穿过去"，再加一个逐点命中回调。）
        clicks0 = CountClicks(log);
        strokes0 = Doc.Strokes.Count;
        Click(holeX, holeY);
        Check("穿透·面板空洞不漏给下层", CountClicks(log) == clicks0,
              $"下层窗口收到 {CountClicks(log) - clicks0} 次点击（应为 0）");
        Check("穿透·面板空洞不落墨", Doc.Strokes.Count == strokes0,
              $"笔画 {strokes0} → {Doc.Strokes.Count}");

        // ---- ⑧ 穿透：面板外交下层 ----
        clicks0 = CountClicks(log);
        strokes0 = Doc.Strokes.Count;
        Click(outX, outY);
        Check("穿透·面板外交下层", CountClicks(log) > clicks0,
              $"下层窗口收到 {CountClicks(log) - clicks0} 次点击（应 ≥ 1）");
        Check("穿透·面板外不落墨", Doc.Strokes.Count == strokes0,
              $"笔画 {strokes0} → {Doc.Strokes.Count}");

        // ---- ⑨ 界面驱动的动画必须拿到连续帧，停下之后必须回到零帧 ----
        // 判据用的是引擎自己的 NeedsFrame()：测的和跑的是同一个判据。
        SetPass(false);
        SettleFrames(150);
        probe.AnimateUntilMs = NowMs + 220;

        int framesDuring = 0;
        var swAnim = Stopwatch.StartNew();
        while (swAnim.ElapsedMilliseconds < 240)
        {
            PumpMessages();
            if (NeedsFrame()) { RenderAll(); _dirty = false; framesDuring++; }
            else Thread.Sleep(1);
        }
        Check("界面驱动的动画拿到连续帧", framesDuring >= 5,
              $"220 毫秒里出了 {framesDuring} 帧（60 fps 下约 13 帧）");

        // 先落地一帧把脏区清干净，再看安静期是不是真的 0 帧
        PumpMessages();
        RenderAll();
        _dirty = false;
        int framesQuiet = 0;
        var swQuiet = Stopwatch.StartNew();
        while (swQuiet.ElapsedMilliseconds < 150)
        {
            PumpMessages();
            if (NeedsFrame()) { RenderAll(); _dirty = false; framesQuiet++; }
            else Thread.Sleep(2);
        }
        Check("动画结束后回到零帧", framesQuiet == 0, $"安静 150 毫秒出了 {framesQuiet} 帧");

        // ---- ⑩ 命令通道：新加的三条命令走一遍，状态读得回来 ----
        // 这段走的是**界面能看到的那条路**（IUiHost.Commands → IEngineCommands → 引擎），
        // 不是直接改引擎字段——否则测的就不是"契约通不通"。
        var host = Host;
        host.Commands.SetSelectMode(SelectMode.Lasso);
        Check("命令·切套索", host.State.SelectMode == SelectMode.Lasso,
              $"读回 {host.State.SelectMode}");
        host.Commands.SetSelectMode(SelectMode.Rect);

        var green = InkPalette.BoardPresets[1].Color;
        host.Commands.SetBoardColor(green);
        Check("命令·换板色", host.State.BoardColor.Equals(green), "读回绿板");
        host.Commands.SetBoardColor(InkPalette.BoardPresets[0].Color);

        Doc.Clear();
        Doc.ClearHistory();
        var only = new Stroke { Tool = Tool.Pen, Color = new Color4(0f, 0f, 0f, 1f), Width = 6f };
        only.AddPoint(400, 400, 1f, 0);
        only.AddPoint(620, 400, 1f, 1);
        Doc.AddStroke(only);
        Tool = Tool.Pen;
        host.Commands.SelectAll();
        Check("命令·全选", Doc.Selected.Count == 1 && Tool == Tool.Marquee,
              $"选中 {Doc.Selected.Count} 条，工具={Tool}");
        Doc.Clear();
        Doc.ClearHistory();

        // ---- ⑪ 界面看到的"屏幕"必须和 IUiHost.Screen 是同一个 ----
        // 单屏上这两者本来就相等（覆盖窗口 == 虚拟桌面），所以这一条是**回归护栏**：
        // 一旦有人把 Layout 的实参改回"本窗口那一块显示器"，双屏上才会露馅，
        // 而在没有双屏的机器上，护栏能立刻发现它不等了。
        Check("Layout 与 Screen 同一套坐标",
              probe.LastLayoutScreen.Equals(host.Screen),
              $"Layout ({probe.LastLayoutScreen.MinX:F0},{probe.LastLayoutScreen.MinY:F0})-"
              + $"({probe.LastLayoutScreen.MaxX:F0},{probe.LastLayoutScreen.MaxY:F0})  vs  "
              + $"Screen ({host.Screen.MinX:F0},{host.Screen.MinY:F0})-"
              + $"({host.Screen.MaxX:F0},{host.Screen.MaxY:F0})");

        // ---- ⑫ 界面抛异常不许留死局：重建 → 重启 → 兜底，而且板书不许丢 ----
        // 教室大屏/手写板上可能根本没有键盘，界面是唯一的出口：界面没了又关不掉、
        // 重启不了，就是死局（用户 2026-09-16 提的）。
        Recovery.ClearRestartCount();          // 别让上一次自检留下的计数影响这一次
        try { File.Delete(Recovery.SessionPath); } catch { }

        int uiBuilt = 0;
        var panelRect = probe.BoundsPhysical;
        UiProbe MakeProbe()
        {
            uiBuilt++;
            return new UiProbe { BoundsPhysical = panelRect };
        }
        SetUiFactory(MakeProbe);               // 引擎从此有"再造一个回来"的办法
        SettleFrames(200);

        // ① 第一次崩：3 秒内 3 次 → 重建界面（不是停用）
        var firstUi = (UiProbe)CurrentUi;
        firstUi.ThrowOnDown = true;
        for (int i = 0; i < 3; i++) { probe.Down = 0; Click(inX, inY); }
        bool rebuilt = CurrentUi is UiProbe && !ReferenceEquals(CurrentUi, firstUi);
        Check("界面崩了先重建（不停用）", rebuilt,
              $"重建次数 {uiBuilt - 1}，当前界面 = {CurrentUi.Name}");

        // ② 重建之后继续崩（重建额度用完）→ 重启软件，且重启前把板书存下来
        Doc.Clear();
        Doc.ClearHistory();
        var keep = new Stroke { Tool = Tool.Pen, Color = new Color4(0f, 0f, 0f, 1f), Width = 6f };
        keep.AddPoint(400, 400, 1f, 0);
        keep.AddPoint(700, 400, 1f, 1);
        Doc.AddStroke(keep);
        int strokesBeforeRestart = Doc.Strokes.Count;

        for (int round = 0; round < 2; round++)
        {
            var ui = CurrentUi as UiProbe;
            if (ui == null) break;
            ui.ThrowOnDown = true;
            for (int i = 0; i < 3; i++) { probe.Down = 0; Click(inX, inY); }
            SettleFrames(120);
        }
        Check("重建救不回来就重启软件", RestartRequested, $"当前界面 = {CurrentUi.Name}");

        // 板书必须读得回来——"重启"的前提是不丢东西
        var blob = Recovery.TakeSession();
        bool restorable = false;
        string detail = "没有暂存文件";
        if (blob != null)
        {
            var fresh = new InkDocument();
            InkSerializer.LoadInto(fresh, blob);
            restorable = fresh.Strokes.Count == strokesBeforeRestart && strokesBeforeRestart > 0;
            detail = $"暂存 {blob.Length} 字节 → 读回 {fresh.Strokes.Count} 笔（重启前 {strokesBeforeRestart} 笔）";
        }
        Check("重启后板书读得回来", restorable, detail);
        try { File.Delete(Recovery.SessionPath); } catch { }
        Recovery.ClearRestartCount();

        Console.WriteLine($"  结果: {pass} 项通过, {fail} 项失败");
        ExitCode = fail == 0 ? 0 : 1;

        // ---- 诊断（不计红绿）：穿透的两种实现方式各自牺牲了什么 ----
        // "面板可点"和"点击透给下层"在现在的实现里是互斥的：
        //   · 只改 WM_NCHITTEST（HitTest 档）：面板能收到，但下层收不到
        //     —— HTTRANSPARENT 只在**同一个线程内**继续往下找窗口；
        //   · LAYERED+TRANSPARENT 档：下层收得到，但这个窗口在系统那一层
        //     就被排除在输入之外了，NCHITTEST 根本轮不到我们，面板点不动。
        // 这段打印就是为了把这条取舍钉成数字，选架构时不用再猜。
        // 上面的熔断自检留着"故意抛异常"的界面，诊断这几下点击会继续触发重建/重启
        // （还会往临时目录写会话文件）。先把开关关掉，让这段只回答它要回答的问题。
        var diagUi = CurrentUi as UiProbe;
        if (diagUi != null) diagUi.ThrowOnDown = false;

        foreach (var (modeName, mode) in new[]
                 {
                     ("只按点回答命中测试", PassThroughMode.HitTest),
                     ("LAYERED+TRANSPARENT", PassThroughMode.LayeredTransparent),
                 })
        {
            PassMode = mode;
            PassThrough = true;
            foreach (var w in _windows) ApplyPassThroughStyle(w);
            SettleFrames(150);

            if (diagUi != null) diagUi.Down = 0;
            int c0 = CountClicks(log);
            int nc0 = _cntNcHitTest, ncc0 = _cntNcHitClient;
            int dn0 = _cntDown;
            Click(inX, inY);
            Console.WriteLine($"  [诊断] {modeName,-24} 面板收到按下 {(diagUi != null && diagUi.Down > 0 ? "是" : "否")}"
                              + $"   下层窗口收到 {(CountClicks(log) > c0 ? "是" : "否")}"
                              + $"   系统问了命中测试 {_cntNcHitTest - nc0} 次"
                              + $"（其中答「这块是我的」{_cntNcHitClient - ncc0} 次）"
                              + $"   引擎收到指针按下 {_cntDown - dn0} 次");
            PassThrough = false;
            foreach (var w in _windows) ApplyPassThroughStyle(w);
            SettleFrames(120);
        }
        try { File.Delete(Recovery.SessionPath); } catch { }
        Recovery.ClearRestartCount();

        SetPass(false);
        try { target.Kill(); } catch { }
        _quit = true;
    }

    /// <summary>
    /// 产品界面（`src/InkUi` 的 `FullUi`）自检：球 ↔ 按钮带这条最小闭环。
    ///
    /// 这一步故意只验四件事——**坐标 / DPI / 脏区 / 输入拦截**：
    /// 它们在假面板里验证不到（假面板自成一个窗口、自带坐标系），而恰恰是接引擎
    /// 最容易错的地方。这四件对了，后面搬色带、滑块、抽屉都只是堆代码。
    ///
    /// 挂法用的是 `SetUiFactory`——产品的挂法。界面崩了引擎要能自己再造一个，
    /// 没工厂就只能一路走到重启（见 计划-底层对接界面.md 4.5）。
    /// </summary>
    /// <summary>
    /// 把界面挂上、展开、出图（给人看的，不判红绿）。
    /// 出图这条链子是这个仓库一贯的验收方式：观感的事眼睛说了算，数字只负责证明没坏。
    /// </summary>
    /// <summary>出图：**截屏图标候选**（用户 2026-09-17："截图图标和选中图标一样的，是不是不大好？"）。</summary>
    private void CaptureIconShow(string path) => SheetShow(new CaptureIconSheet(), path);

    /// <summary>出图：**激光笔图标候选**（开发期比图用，见 <see cref="LaserIconSheet"/>）。</summary>
    private void IconShow(string path) => SheetShow(new LaserIconSheet(), path);

    /// <summary>出图：图形面板那些自绘图标的对照表（见 <see cref="ShapeIconSheet"/>）。</summary>
    private void ShapeIconShow(string path) => SheetShow(new ShapeIconSheet(), path);

    /// <summary>出图：**白板 / 激光笔的图标候选**（2026-09-26，见 <see cref="ToolIconSheet"/>）。</summary>
    private void ToolIconShow(string path) => SheetShow(new ToolIconSheet(), path);

    /// <summary>
    /// **把一张"图标对照表"的图截下来**——`--iconshow` / `--captureicons` / `--shapeiconshow`
    /// 三处共用这一份（原来只有前面两个、各写了一遍，加第三个时收过来的）。
    /// </summary>
    private void SheetShow(IOverlayUi sheet, string path)
    {
        SetUi(sheet);
        BoardOn = true;                      // 白板打底：图里没有桌面上的杂东西
        SettleFrames(400);

        // 优先走**离屏出图**：锁屏 / 远程 / 没显示器时照样出得来，图里也不会混进桌面。
        if (OffscreenShot(path)) return;

        var b = CurrentUi.QueryBounds();
        int x = (int)MathF.Floor(b.MinX * DpiScale) - 20;
        int y = (int)MathF.Floor(b.MinY * DpiScale) - 20;
        int w = (int)MathF.Ceiling((b.MaxX - b.MinX) * DpiScale) + 40;
        int h = (int)MathF.Ceiling((b.MaxY - b.MinY) * DpiScale) + 40;
        bool ok = ScreenProbe.SaveBmp(path, x, y, w, h);
        Console.WriteLine(ok ? $"已出图 {path}" : "出图失败");
        ExitCode = ok ? 0 : 1;
        _quit = true;
    }

    /// <summary>
    /// 真实面板的每帧代价：**同一份内容**，挂面板与不挂面板各渲染一遍，比时间。
    ///
    /// 为什么要有这个：设计阶段那句"面板每帧 0.5～1.5 毫秒"是**估**的
    /// （拿 160×60 的小界面按面积外推的），而面板现在有 636×82、
    /// 还在写字这条最敏感的路径上。教室机器比开发机慢，估的数不能当结论。
    ///
    /// 量三档：不挂界面（基准）／收起成球／展开成带子（含设置条，最贵的一档）。
    /// 每档都强制 `_dirty = true` 再渲染，避免"空闲不出帧"把代价量成 0。
    /// </summary>
    private void PanelPerf()
    {
        Console.WriteLine();
        Console.WriteLine("=== 真实面板的每帧代价（同一份内容，挂 vs 不挂）===");

        // 一屏板书：200 条各 40 个点
        Doc.Clear();
        Doc.ClearHistory();
        var rnd = new Random(7);
        for (int s = 0; s < 200; s++)
        {
            var st = new Stroke
            {
                Tool = Tool.Pen, Color = new Color4(0.1f, 0.1f, 0.1f, 1f),
                Width = 6f * DpiScale,
            };
            float x0 = _virtualX + rnd.Next(100, Math.Max(200, _virtualW - 400));
            float y0 = _virtualY + rnd.Next(100, Math.Max(200, _virtualH - 300));
            for (int k = 0; k < 40; k++) st.AddPoint(x0 + k * 6, y0 + MathF.Sin(k * 0.3f) * 20, 1f, k);
            Doc.AddStroke(st);
        }
        Doc.InvalidateAll();
        SettleFrames(400);

        double Measure(int frames)
        {
            // **跑 3 轮取最小值**：这台机器上同时跑着远程控制和几个吃 GPU 的客户端，
            // 平均值被"别人抢走的那几毫秒"抬高得离谱（同一档实测在 1.1～3.0 之间跳）。
            // 最小值 = 最"干净"的那一轮，用它比才比得出我们自己代码的差别。
            double best = double.MaxValue;
            for (int round = 0; round < 3; round++)
            {
                SettleFrames(150);
                var sw = Stopwatch.StartNew();
                for (int i = 0; i < frames; i++) { _dirty = true; RenderAll(); }
                sw.Stop();
                best = Math.Min(best, sw.Elapsed.TotalMilliseconds / frames);
            }
            return best;
        }

        SetUi(new HeadlessUi());
        SettleFrames(200);
        double none = Measure(200);

        SetUiFactory(() => new InkUi.FullUi());
        SettleFrames(300);
        double ball = Measure(200);                       // 收起态：一个球

        if (CurrentUi is InkUi.FullUi ui)
        {
            ui.SnapForTest();                             // 一步展开
            ui.OpenRailForTest();                         // 色带也张开（最贵的一档）
        }
        SettleFrames(300);
        double full = Measure(200);

        Console.WriteLine($"  不挂界面            {none,6:F2} ms/帧");
        Console.WriteLine($"  收起成一个球        {ball,6:F2} ms/帧   （比不挂多 {ball - none,5:F2}）");
        Console.WriteLine($"  展开＋色带张开      {full,6:F2} ms/帧   （比不挂多 {full - none,5:F2}）");

        // ---- 归因：把几块分别关掉再量，看钱花在哪 ----
        Console.WriteLine();
        Console.WriteLine("  归因（从「展开＋色带」这一档里省了多少）：");
        void Attrib(string name, Action set)
        {
            set();
            SettleFrames(200);
            double t = Measure(200);
            Console.WriteLine($"    {name,-22} {t,6:F2} ms/帧   （省 {full - t,5:F2}）");
        }
        Attrib("不算阴影", () => InkUi.FullUi.PerfSkipShadow = true);
        InkUi.FullUi.PerfSkipShadow = false;
        Attrib("不算凹槽与顶光", () => InkUi.FullUi.PerfSkipChrome = true);
        InkUi.FullUi.PerfSkipChrome = false;
        Attrib("不算色片细节", () => InkUi.FullUi.PerfSkipSwatchDetail = true);
        InkUi.FullUi.PerfSkipSwatchDetail = false;
        Attrib("不算图标", () => InkUi.FullUi.PerfSkipIcons = true);
        InkUi.FullUi.PerfSkipIcons = false;

        bool ok = (full - none) <= 1.5;                   // 计划里定的红线：≤1.5ms/帧
        Console.WriteLine(ok
            ? "  PASS: 完整展开态的额外代价在 1.5 毫秒以内"
            : $"  FAIL: 完整展开态比不挂界面贵了 {full - none:F2} 毫秒（红线 1.5）");
        ExitCode = ok ? 0 : 1;
        _quit = true;
    }

    /// <summary>
    /// 自动存档 / 崩溃恢复自检（开发期）。
    ///
    /// 它是"一节课的板书会不会丢"这条链子的唯一自动化验证：
    ///   ① 存了能原样读回来（笔画数/颜色/粗细/身份一致）；
    ///   ② **没变就不写**（靠文档版本号节流，不然每 15 秒白写一遍全量）；
    ///   ③ **清空之后存的是空的**（不然重启会把擦掉的东西又变回来）；
    ///   ④ 坏文件读不出来时**不许影响启动**（从空白开始，只提示）；
    ///   ⑤ 存档落在 LOCALAPPDATA，**不是 TEMP**（TEMP 会被清理工具删掉，
    ///      而"断电一节课"恰恰要跨重启活下来）。
    ///
    /// 自检全程用临时路径（`Recovery.AutoSavePathOverride`），不碰用户真正的板书。
    /// </summary>
    private void RecoveryTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 自动存档/崩溃恢复自检 ===");

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-34} {detail}");
        }

        string path = Recovery.AutoSavePath;
        Recovery.DeleteAuto();

        Check("存档落在 LOCALAPPDATA（不是 TEMP）",
              path.Contains("Local", StringComparison.OrdinalIgnoreCase)
              || Recovery.AutoSavePathOverride != null,
              path);

        // ⓪ **默认档：不接上次的板书，也不写那个文件**（用户 2026-09-17）
        //
        // "退出以后再打开不用恢复墨迹吧……我觉得默认不恢复墨迹。"
        // 理由：教室机器是公用的，一开机铺满上一节课的板书不合理。
        // 这里先按"上次留下了一份存档"造现场，再走一遍**启动时那条真路径**。
        {
            SetUiPref("restoreInk", null);              // 默认：没有这一项
            Doc.Clear();
            Doc.ClearHistory();
            var keep = new Stroke { Tool = Tool.Pen, Color = new Color4(0f, 0f, 0f, 1f), Width = 5f * DpiScale };
            keep.AddPoint(300, 300, 1f, 0); keep.AddPoint(500, 320, 1f, 1);
            Doc.AddStroke(keep);
            AutoSaveNow();                              // 硬盘上留下一份"上次的板书"
            Doc.Clear();
            Doc.ClearHistory();

            RestoreAutoSaveForTest();                   // 启动时走的就是这一条
            Check("默认（没设偏好）：启动**不接**上次的板书",
                  Doc.Strokes.Count == 0 && !RestoreInkOnStartup,
                  $"偏好 = {RestoreInkOnStartup}，读回 {Doc.Strokes.Count} 笔");

            // 不写：改一下板书、跑够时间，自动存档次数不该动
            SetAutoSaveIntervalForTest(80);
            int n0 = AutoSaveCount;
            var s0 = new Stroke { Tool = Tool.Pen, Color = new Color4(0f, 0f, 0f, 1f), Width = 5f * DpiScale };
            s0.AddPoint(200, 200, 1f, 0); s0.AddPoint(260, 230, 1f, 1);
            Doc.AddStroke(s0);
            var sw0 = Stopwatch.StartNew();
            while (sw0.ElapsedMilliseconds < 260) { PumpMessages(); RenderAll(); }
            Check("默认（没设偏好）：板书变了也不写档（不留没人读的文件）",
                  AutoSaveCount == n0, $"{n0} → {AutoSaveCount} 次");

            // 打开偏好：下面几条按"要恢复"的老路径验
            SetUiPref("restoreInk", "1");
            Check("打开偏好之后：读得到这一项", RestoreInkOnStartup, "restoreInk = 1");
        }

        // ① 存 → 读回来，逐项一致
        Doc.Clear();
        Doc.ClearHistory();
        var a = new Stroke { Tool = Tool.Pen, Color = new Color4(0.13f, 0.70f, 0.33f, 1f), Width = 7f * DpiScale };
        a.AddPoint(400, 400, 1f, 0); a.AddPoint(700, 500, 1f, 1);
        Doc.AddStroke(a);
        var b = new Stroke { Tool = Tool.Highlighter, Color = new Color4(1f, 0.85f, 0.15f, 0.32f), Width = 24f * DpiScale };
        b.AddPoint(500, 700, 1f, 0); b.AddPoint(900, 760, 1f, 1);
        Doc.AddStroke(b);

        AutoSaveNow();
        long size = new FileInfo(path).Length;
        var fresh = new InkDocument();
        InkSerializer.LoadInto(fresh, Recovery.LoadAuto());
        bool same = fresh.Strokes.Count == 2
                 && MathF.Abs(fresh.Strokes[0].Color.G - 0.70f) < 0.02f
                 && MathF.Abs(fresh.Strokes[1].Width - 24f * DpiScale) < 0.5f
                 && fresh.Strokes[1].Tool == Tool.Highlighter;
        Check("存了能原样读回来", same,
              $"暂存 {size} 字节 → 读回 {fresh.Strokes.Count} 笔，第 2 笔 {fresh.Strokes[1].Width:F0} 物理像素");

        // ② 没变就不写
        SetAutoSaveIntervalForTest(80);
        int before = AutoSaveCount;
        var sw = Stopwatch.StartNew();
        while (sw.ElapsedMilliseconds < 260) { PumpMessages(); RenderAll(); }
        int afterIdle = AutoSaveCount;
        Check("板书没变就不写", afterIdle == before, $"{before} → {afterIdle} 次");

        // 变一下 → 到点就该写
        var c = new Stroke { Tool = Tool.Pen, Color = new Color4(0f, 0f, 0f, 1f), Width = 4f * DpiScale };
        c.AddPoint(300, 300, 1f, 0); c.AddPoint(360, 330, 1f, 1);
        Doc.AddStroke(c);
        sw.Restart();
        while (sw.ElapsedMilliseconds < 260) { PumpMessages(); RenderAll(); }
        Check("板书变了就到点写一次", AutoSaveCount > afterIdle, $"{afterIdle} → {AutoSaveCount} 次");

        // ③ 清空之后存的是空的
        Doc.Clear();
        Doc.ClearHistory();
        AutoSaveNow();
        var empty = new InkDocument();
        InkSerializer.LoadInto(empty, Recovery.LoadAuto());
        Check("清空之后存的是空文档", empty.Strokes.Count == 0, $"读回 {empty.Strokes.Count} 笔");

        // ④ 坏文件不影响启动
        File.WriteAllBytes(path, new byte[] { 1, 2, 3, 4, 5, 6, 7, 8, 9 });
        Doc.Clear();
        Doc.ClearHistory();
        bool threw = false;
        try { RestoreAutoSaveForTest(); } catch { threw = true; }
        Check("坏文件不影响启动（从空白开始）", !threw && Doc.Strokes.Count == 0,
              $"抛异常 = {threw}，读回 {Doc.Strokes.Count} 笔");

        // ⑤ 真存档能"重启接上"（走启动那条路）
        Doc.Clear();
        Doc.ClearHistory();
        var d = new Stroke { Tool = Tool.Pen, Color = new Color4(0.1f, 0.4f, 0.9f, 1f), Width = 6f * DpiScale };
        d.AddPoint(200, 200, 1f, 0); d.AddPoint(600, 260, 1f, 1);
        Doc.AddStroke(d);
        AutoSaveNow();
        Doc.Clear();
        Doc.ClearHistory();
        RestoreAutoSaveForTest();
        Check("重开接上上次的板书", Doc.Strokes.Count == 1, $"读回 {Doc.Strokes.Count} 笔");

        Recovery.DeleteAuto();
        Console.WriteLine($"  结果: {pass} 项通过, {fail} 项失败");
        ExitCode = fail == 0 ? 0 : 1;
        _quit = true;
    }

    /// <summary>
    /// 离屏把界面画下来存成 BMP。返回 true = 出图成功。
    ///
    /// 这条路**不截屏**：它让界面渲染到自己的位图上。
    /// 好处是锁屏 / 远程 / 这台机器上没人看着的时候照样能出图，
    /// 而且图里只有界面本身，没有桌面、任务栏、别的窗口。
    /// </summary>
    private bool OffscreenShot(string path)
    {
        if (_windows.Count == 0) return false;
        var bytes = _windows[0].RenderUiToBgra(this, 24, out int w, out int h);
        return SaveBgraAsBmp(path, bytes, w, h);
    }

    /// <summary>同上，但**画哪一块自己指定**（逻辑像素）——见 `RenderUiToBgra` 的重载。</summary>
    private bool OffscreenShot(string path, in RectF bounds)
    {
        if (_windows.Count == 0) return false;
        var bytes = _windows[0].RenderUiToBgra(this, 24, bounds, out int w, out int h);
        return SaveBgraAsBmp(path, bytes, w, h);
    }

    /// <summary>同上，但画的是**浮动层**（选中框 / 操作条 / 小面板）——坐标给画布坐标。</summary>
    private bool OffscreenFloatingShot(string path, in RectF canvasBounds)
    {
        if (_windows.Count == 0) return false;
        var bytes = _windows[0].RenderFloatingToBgra(this, 24, canvasBounds, out int w, out int h);
        return SaveBgraAsBmp(path, bytes, w, h);
    }

    /// <summary>
    /// `--makeicon &lt;out.ico&gt;`：**用界面自己的渲染**生成程序图标。
    ///
    /// 图标就是"收起态那颗球"：白面 ＋ **当前笔色那一圈**（`Tokens.BallRing`，0.76R、线宽 2.5）
    /// ＋ 中间那个自绘笔图标（`Tokens.BallIcon`）。用户 2026-09-27 点的名
    /// （"用那个菜单收缩起来的那个小圆球，然后用红色那个批注那个圈"——笔色默认是红）。
    ///
    /// 为什么不另画一张 SVG / 用画图工具拼：
    ///   ① 中间那个笔图标是**自绘矢量**（`IconAtlas`），另画一份迟早和界面对不上；
    ///   ② "和屏幕上那颗一模一样"这件事，只有同一条渲染路径能保证
    ///      （本仓库反复吃过的教训：同一个东西写两份，早晚不一致）。
    ///
    /// 做法：把窗口 DPI **临时放大**再离屏出图。界面是按"逻辑坐标 × DPI/96"画的，
    /// 所以放大 DPI 等于**按矢量重画一张大的**，而不是把 96 的小图拉大（拉大会糊）。
    /// 再把那一张按各档尺寸缩下去、装成一个多尺寸 .ico。
    /// </summary>
    private void MakeIcon(string path)
    {
        SetUiFactory(() => new InkUi.FullUi());
        SettleFrames(200);
        if (CurrentUi is not InkUi.FullUi ui || _windows.Count == 0)
        {
            Console.WriteLine("  出图标失败：界面没挂上 / 没有窗口");
            _quit = true;
            return;
        }

        // 收起态（那颗球）＋ 不许贴边隐藏把它沉下去（沉下去就只剩 8 像素的一条把手）。
        ui.SetExpandForTest(0f);
        ui.ForcePeekForTest(1f);
        SettleFrames(250);

        var ball = ui.QueryBounds();
        if (ball.IsEmpty) { Console.WriteLine("  出图标失败：占用矩形是空的"); _quit = true; return; }
        // 四周留白：投影最外那几层（α 0.03 上下）不值得为它留位置，留 6 就够——
        // 球在图标里占 48/60 = 80%，和系统自带图标那个比例接近。
        var box = ball.Inflate(6f);

        // 目标边长 256：临时把窗口 DPI 抬高，让界面按矢量重画到这个尺寸。
        var win = _windows[0];
        uint want = (uint)Math.Clamp(MathF.Round(96f * 256f / (box.MaxX - box.MinX)), 96, 96 * 12);
        uint dpi0 = win.Dpi;
        win.Dpi = want;
        byte[] px = win.RenderUiToBgraTransparent(this, 0, box, out int bw, out int bh);
        win.Dpi = dpi0;
        if (px == null || bw <= 0)
        {
            Console.WriteLine("  出图标失败：" + (win.LastError ?? "没画出来"));
            _quit = true;
            return;
        }
        Console.WriteLine($"  渲染尺寸 {bw}×{bh}（为它把窗口 DPI 临时抬到 {want}）");

        // **圆外一律清成完全透明**（用户 2026-09-29 反馈："图标不是正圆、隐约能看见方框"）：
        // 球底下的投影是一团**方形**柔光，方框那圈像素带一点点黑——实测 256×256 那帧
        // 最外一圈 1020 个像素里 782 个 α>0、最高 α≈23/255，圆外也有一批 α≈26。
        // 图标就该是一个干净的圆，所以按量出来的球半径做一次圆形蒙版（边缘 1px 抗锯齿）。
        int rIcon = IconRadiusPx(px, bw, bh);
        MaskIconToCircle(px, bw, bh, rIcon);
        Console.WriteLine($"  圆形蒙版：半径 {rIcon}px（球外面那圈方形投影清成透明）");

        try
        {
            string dir = Path.GetDirectoryName(Path.GetFullPath(path));
            if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
            int[] sizes = { 16, 24, 32, 48, 64, 128, 256 };
            WriteMultiSizeIco(path, px, bw, bh, sizes);
            // 顺带出一张 PNG 预览：这个圆对不对、圈红不红，**只能看图**（几何自检看不出来）。
            string png = Path.ChangeExtension(path, ".png");
            using (var b = BgraToBitmap(px, bw, bh)) b.Save(png, System.Drawing.Imaging.ImageFormat.Png);
            Console.WriteLine($"  已写出 {path}（{sizes.Length} 档：{string.Join('/', sizes)}）");
            Console.WriteLine($"  预览图 {png}（人眼核对用）");
        }
        catch (Exception ex) { Console.WriteLine("  出图标失败：" + ex.Message); }
        _quit = true;
    }

    /// <summary>
    /// 量出"球"的半径（像素）：沿中心行/列找 α≥96 的最远点，取两者的较小值。
    /// 为什么要量而不是算：真实半径由界面渲染（含 DPI 缩放与投影）决定，硬算容易差几像素。
    /// 投影的 α 很小（≤30 上下），进不了 96 这道门，所以量到的是球本身。
    /// </summary>
    private static int IconRadiusPx(byte[] bgra, int w, int h)
    {
        int cx = w / 2, cy = h / 2, rx = 0, ry = 0;
        for (int x = 0; x < w; x++) if (bgra[(cy * w + x) * 4 + 3] >= 96) rx = Math.Max(rx, Math.Abs(x - cx));
        for (int y = 0; y < h; y++) if (bgra[(y * w + cx) * 4 + 3] >= 96) ry = Math.Max(ry, Math.Abs(y - cy));
        return Math.Max(1, Math.Min(rx, ry) - 1);      // 再收 1px：把抗锯齿那圈也收进去
    }

    /// <summary>
    /// 圆形 alpha 蒙版：圆外全透明，边缘 1px 线性过渡（抗锯齿）。
    /// ⚠ 数据是**预乘** BGRA，四个分量要一起乘——只把 α 清零会留下黑边（预乘的经典坑）。
    /// </summary>
    private static void MaskIconToCircle(byte[] bgra, int w, int h, int radius)
    {
        float cx = w / 2f, cy = h / 2f;
        for (int y = 0; y < h; y++)
        {
            for (int x = 0; x < w; x++)
            {
                float dx = x + 0.5f - cx, dy = y + 0.5f - cy;
                float d = MathF.Sqrt(dx * dx + dy * dy);
                float k = Math.Clamp(radius - d + 0.5f, 0f, 1f);      // 圆内 1、圆外 0、边缘过渡
                if (k >= 1f) continue;
                int o = (y * w + x) * 4;
                bgra[o]     = (byte)(bgra[o]     * k);
                bgra[o + 1] = (byte)(bgra[o + 1] * k);
                bgra[o + 2] = (byte)(bgra[o + 2] * k);
                bgra[o + 3] = (byte)(bgra[o + 3] * k);
            }
        }
    }

    /// <summary>BGRA（D2D 的**预乘**格式）→ GDI+ 位图。像素行是自上而下的。</summary>
    private static System.Drawing.Bitmap BgraToBitmap(byte[] bgra, int w, int h)
    {
        var bmp = new System.Drawing.Bitmap(w, h, System.Drawing.Imaging.PixelFormat.Format32bppPArgb);
        var d = bmp.LockBits(new System.Drawing.Rectangle(0, 0, w, h),
                             System.Drawing.Imaging.ImageLockMode.WriteOnly,
                             System.Drawing.Imaging.PixelFormat.Format32bppPArgb);
        try
        {
            var row = new byte[w * 4];
            for (int y = 0; y < h; y++)
            {
                Buffer.BlockCopy(bgra, y * w * 4, row, 0, w * 4);
                Marshal.Copy(row, 0, IntPtr.Add(d.Scan0, y * d.Stride), w * 4);
            }
        }
        finally { bmp.UnlockBits(d); }
        return bmp;
    }

    /// <summary>
    /// 写一个**多尺寸 ICO**（每档一张 PNG——Vista 以后系统就认这种）。
    ///
    /// 格式很小，手写比引第三方库省事：6 字节目录头 ＋ 每档 16 字节目录项 ＋ 各档 PNG 数据。
    /// 注意目录项里宽高各只占**一个字节**：256 要写成 0（这是 ICO 格式的约定，不是笔误）。
    /// </summary>
    private static void WriteMultiSizeIco(string path, byte[] bgra, int bw, int bh, int[] sizes)
    {
        using var src = BgraToBitmap(bgra, bw, bh);
        var blobs = new List<byte[]>();
        foreach (int s in sizes)
        {
            using var one = new System.Drawing.Bitmap(s, s, System.Drawing.Imaging.PixelFormat.Format32bppArgb);
            using (var g = System.Drawing.Graphics.FromImage(one))
            {
                g.InterpolationMode = System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;
                g.PixelOffsetMode = System.Drawing.Drawing2D.PixelOffsetMode.HighQuality;
                g.CompositingQuality = System.Drawing.Drawing2D.CompositingQuality.HighQuality;
                g.DrawImage(src, new System.Drawing.Rectangle(0, 0, s, s));
            }
            using var ms = new MemoryStream();
            one.Save(ms, System.Drawing.Imaging.ImageFormat.Png);
            blobs.Add(ms.ToArray());
        }

        using var fs = File.Create(path);
        using var wr = new BinaryWriter(fs);
        wr.Write((ushort)0); wr.Write((ushort)1); wr.Write((ushort)sizes.Length);
        int offset = 6 + 16 * sizes.Length;
        for (int i = 0; i < sizes.Length; i++)
        {
            byte wh = (byte)(sizes[i] >= 256 ? 0 : sizes[i]);
            wr.Write(wh); wr.Write(wh);
            wr.Write((byte)0);            // 调色板颜色数（真彩不用）
            wr.Write((byte)0);            // 保留
            wr.Write((ushort)1);          // 平面数
            wr.Write((ushort)32);         // 位深
            wr.Write(blobs[i].Length);
            wr.Write(offset);
            offset += blobs[i].Length;
        }
        foreach (var b in blobs) wr.Write(b);
    }

    private bool SaveBgraAsBmp(string path, byte[] bytes, int w, int h)
    {
        if (bytes == null)
        {
            Console.WriteLine("离屏出图失败：" + (_windows[0].LastError ?? "没有占用矩形"));
            return false;
        }

        // BMP：文件头 14 ＋ 信息头 40，像素按 BGRA、行从下往上（行宽 4 字节对齐）。
        int stride = w * 4;
        int size = 54 + stride * h;
        var outBytes = new byte[size];
        void W16(int at, int v) { outBytes[at] = (byte)v; outBytes[at + 1] = (byte)(v >> 8); }
        void W32(int at, int v)
        {
            outBytes[at] = (byte)v; outBytes[at + 1] = (byte)(v >> 8);
            outBytes[at + 2] = (byte)(v >> 16); outBytes[at + 3] = (byte)(v >> 24);
        }
        outBytes[0] = (byte)'B'; outBytes[1] = (byte)'M';
        W32(2, size); W32(10, 54); W32(14, 40);
        W32(18, w); W32(22, h);
        W16(26, 1); W16(28, 32);
        W32(34, stride * h);
        for (int y = 0; y < h; y++)
            Array.Copy(bytes, (h - 1 - y) * w * 4, outBytes, 54 + y * stride, w * 4);

        try
        {
            Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path)) ?? ".");
            File.WriteAllBytes(path, outBytes);
            Console.WriteLine($"已离屏出图 {path}（{w}×{h}）");
            ExitCode = 0;
            _quit = true;
            return true;
        }
        catch (Exception ex)
        {
            Console.WriteLine("写出图失败：" + ex.Message);
            return false;
        }
    }

    /// <summary>
    /// **页界线摆样**：白板打底、铺三屏板书，出两张图——
    ///   · `<path>`：相机停在两屏之间（页界线落在屏幕中间，最好看细节）；
    ///   · `<path>-对齐.bmp`：相机正好停在第 2 屏（页界线压在屏幕上下沿）。
    /// 为什么要两张：一眼看出"一屏一页"的分界到底顺不顺眼、会不会被当成画面上的脏点。
    /// </summary>
    private void PageShow(string path)
    {
        SetUiFactory(() => new InkUi.FullUi());
        BoardOn = true;
        BoardColor = InkPalette.BoardPresets[0].Color;
        // --pattern N：出图时带上白板底纹（0 无 / 1 方格 / 2 横线；--step 给间距）
        {
            var cli0 = Environment.GetCommandLineArgs();
            int pi = Array.IndexOf(cli0, "--pattern");
            int si = Array.IndexOf(cli0, "--step");
            if (pi >= 0 && pi + 1 < cli0.Length && int.TryParse(cli0[pi + 1], out int pat))
            {
                float step = si >= 0 && si + 1 < cli0.Length && float.TryParse(cli0[si + 1], out float sv)
                             ? sv : 40f;
                SetBoardPatternFromUi(pat, step);
            }
        }

        for (int screen = 0; screen < 3; screen++)
            for (int row = 0; row < 4; row++)
            {
                var s = new Stroke
                {
                    Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                    Color = new Color4(0.10f, 0.11f, 0.14f, 1f), Width = 5f * DpiScale,
                };
                float y = _virtualY + screen * _virtualH + 240f + row * 380f;
                for (int i = 0; i <= 36; i++)
                    s.AddPoint(_virtualX + 420f + i * 52f, y + MathF.Sin(i * 0.4f) * 26f, 1f, i * 8);
                Doc.AddStroke(s);
            }

        // 第 2 屏右边标一句"这里是第 2 屏"，看图时好对号
        var tag = new Stroke
        {
            Tool = Tool.Pen, Kind = StrokeKind.Freehand,
            Color = new Color4(0.13f, 0.36f, 0.24f, 1f), Width = 9f * DpiScale,
        };
        float ty = _virtualY + _virtualH + 150f;
        for (int i = 0; i <= 60; i++) tag.AddPoint(_virtualX + 2200f + i * 4f, ty + (i % 7) * 6f, 1f, i * 8);
        Doc.AddStroke(tag);

        void Shot(float offset, string outPath)
        {
            ViewOffsetY = offset;
            foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = offset; }
            Doc.InvalidateAll();
            SettleFrames(600);
            bool ok = ScreenProbe.SaveBmp(outPath, (int)_virtualX, (int)_virtualY,
                                          (int)_virtualW, (int)_virtualH);
            Console.WriteLine(ok ? $"已出图 {outPath}" : $"出图失败 {outPath}");
        }

        Shot(-_virtualH * 0.55f, path);                       // 界线落在屏幕中间
        string aligned = System.IO.Path.ChangeExtension(path, null) + "-对齐.bmp";
        Shot(-_virtualH * 1.0f, aligned);                     // 正好第 2 屏

        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        _quit = true;
    }

    private void PanelShow(string path)
    {
        _panelShowDrawer = Environment.GetCommandLineArgs().Contains("--drawer");
        _panelShowMini = Environment.GetCommandLineArgs().Contains("--mini");
        _panelShowBand = Environment.GetCommandLineArgs().Contains("--band");
        SetUiFactory(() => new InkUi.FullUi());
        Tool = Tool.Pen;
        BoardOn = true;                      // 白板打底：截出来的图里没有桌面上的杂东西
        // --pixel：把工具切成面积橡皮再出图（看"橡皮按钮的图标跟着换"那一版）
        if (Environment.GetCommandLineArgs().Contains("--pixel")) Tool = Tool.PixelEraser;
        if (Environment.GetCommandLineArgs().Contains("--eraser")) Tool = Tool.Eraser;
        if (Environment.GetCommandLineArgs().Contains("--laser")) Tool = Tool.Laser;
        if (Environment.GetCommandLineArgs().Contains("--hl")) Tool = Tool.Highlighter;
        // --select：把工具切成选择（看"选择那一格的图标"）；配 --lasso 就是套索那一档
        //（2026-09-26 加：选择那格现在"选中什么显示什么"，两种框选各一个图标）。
        if (Environment.GetCommandLineArgs().Contains("--select")) Tool = Tool.Marquee;
        // --board-green / --board-black：换板色再出图（看"白板那格填的是哪块板的颜色"）
        {
            var argvB = Environment.GetCommandLineArgs();
            if (argvB.Contains("--board-green")) Host.Commands.SetBoardColor(InkPalette.BoardPresets[1].Color);
            if (argvB.Contains("--board-black")) Host.Commands.SetBoardColor(InkPalette.BoardPresets[2].Color);
        }
        // --pattern N / --step N：把白板底纹摆成某一档再出图（看色带上那两格文字和档位点）。
        // 和 `--cell` / `--zoom` / `--dashline` 同一类：产品里没有这个入口，只服务"图上看细节"。
        {
            var argvP = Environment.GetCommandLineArgs();
            int pi = Array.IndexOf(argvP, "--pattern");
            if (pi >= 0 && pi + 1 < argvP.Length && int.TryParse(argvP[pi + 1], out int patArg))
            {
                int si = Array.IndexOf(argvP, "--step");
                float stepArg = si >= 0 && si + 1 < argvP.Length
                                && float.TryParse(argvP[si + 1], out float sv) ? sv : 40f;
                Host.Commands.SetBoardPattern(patArg, stepArg);
            }
        }
        // --board-on：把白板真的打开再出图。**只影响图**：`BoardOn = true` 那句设的是 App
        // 自己的字段，引擎那边是关着的——而"白板色带最右端那个 ✕"在板关着时是压暗的
        //（见 FullUi.DrawBandAction），所以要看它正常的样子必须真开一下板。
        if (Environment.GetCommandLineArgs().Contains("--board-on")) Host.Commands.SetBoard(true);
        // --shape <名字>：把工具切成某一种图形再出图（看"主条那一格的图标跟着种类变"）。
        // 名字用命令行里那套小写写法，和 --shapetoolshow 的 --circle/--triangle 一致。
        {
            var argv = Environment.GetCommandLineArgs();
            int si = Array.IndexOf(argv, "--shape");
            if (si >= 0 && si + 1 < argv.Length)
            {
                Tool = argv[si + 1].ToLowerInvariant() switch
                {
                    "line" => Tool.Line,
                    "rect" or "rectangle" => Tool.Rectangle,
                    "ellipse" => Tool.Ellipse,
                    "circle" => Tool.Circle,
                    "triangle" => Tool.Triangle,
                    "parallelogram" => Tool.Parallelogram,
                    "arrow" => Tool.Arrow,
                    // 2026-09-20：四种曲线（出图看"图形格两行 + 新图标"时要用）
                    "parabola" => Tool.Parabola,
                    "hyperbola" => Tool.Hyperbola,
                    "sine" => Tool.Sine,
                    "cosine" => Tool.Cosine,
                    "wave" => Tool.Wave,
                    "tangent" => Tool.Tangent,
                    "cylinder" => Tool.Cylinder,
                    "cone" => Tool.Cone,
                    "conefrustum" => Tool.ConeFrustum,
                    "sphere" => Tool.Sphere,
                    // 立体那一族（出图看"图形格第二行 + 档位点"时要用）：三个的名字就是
                    // 它们各自的工具名小写（棱柱 / 棱锥 / 棱台）。
                    "prism" => Tool.Prism,
                    "pyramid" => Tool.Pyramid,
                    "frustum" => Tool.Frustum,
                    _ => Tool.Line,
                };
            }
        }
        // 上面那几行改的是 **App 自己的 Tool 字段**，界面不会因此重算"当前是哪一格"
        // （`Tool` 是个裸字段，没有通知）。而出图要看的恰恰是"图形那一格的两行"，
        // 所以这里**走一次真的换工具**（引擎 → 通知界面 → 上带跟着切到图形格）。
        Host.Commands.SetTool(Tool);
        // 套索那一档要单独设（它和"选的是哪个工具"是两回事，见 SetSelectMode）
        if (Environment.GetCommandLineArgs().Contains("--lasso"))
            Host.Commands.SetSelectMode(SelectMode.Lasso);
        SettleFrames(400);

        // --hide：贴边隐藏**要先写进偏好再挂界面**（界面是在 Attach 里读偏好的），
        // 挂完再把露头一把按到底。配合 --ball 出"收起态露头"，不配就是"展开态露头"。
        bool wantHide = Environment.GetCommandLineArgs().Contains("--hide");
        if (wantHide)
        {
            SetUiPref("hide", "1");
            SetUiFactory(() => new InkUi.FullUi());
        }

        if (CurrentUi is InkUi.FullUi ui)
        {
            // --ball：**出收起态（那个球）**，不做"一步展开"。
            // 默认是展开态；收起/贴边这一类毛病只在球上看得见，所以要能单拍它。
            bool wantBall = Environment.GetCommandLineArgs().Contains("--ball");
            if (!wantBall) ui.SnapForTest();     // 一步展开，不用等 200 毫秒
            if (wantHide) ui.ForcePeekForTest(0f);
            // --expand <0..1>：把"球 → 带子"的展开进度钉在中间某一帧（核对动画用）
            {
                var argv = Environment.GetCommandLineArgs();
                int ei = Array.IndexOf(argv, "--expand");
                if (ei >= 0 && ei + 1 < argv.Length && float.TryParse(argv[ei + 1], out float ex))
                    ui.SetExpandForTest(ex);
            }
            if (_panelShowMini) ui.SetProfileForTest(0);     // --mini：极简档（短胶囊）
            if (_panelShowBand) ui.OpenRailForTest();        // --band：把色线张开成设置条
            // --cell N：把上带掰到第 N 格再出图（N=2 就是白板那条
            // `[上一屏] [白][绿][黑] [下一屏]` ＋ "第 N 屏"）
            var cli = Environment.GetCommandLineArgs();
            int ci = Array.IndexOf(cli, "--cell");
            if (ci >= 0 && ci + 1 < cli.Length && int.TryParse(cli[ci + 1], out int cellArg))
                ui.SelectBandCellForTest(cellArg);
            // --width N：先把粗细调成 N 再出图（看"真实大小预览"用）
            int wi = Array.IndexOf(cli, "--width");
            if (wi >= 0 && wi + 1 < cli.Length && float.TryParse(cli[wi + 1], out float widthArg))
            {
                Host.Commands.SetWidth(widthArg);
                SettleFrames(120);
            }
            if (cli.Contains("--preview")) ui.ShowSizePreviewForTest();
            // --dashline N：把「直线」那一格的档位往后切 N 下（看"图标跟着线型换"那三档：
            // N=0 实线、1 虚线、2 点线；配 `--shape line` 用）。产品里没有这个入口，
            // 它只服务"图上看细节"（和 --zoom / --cell 同一类）。
            {
                int dli = Array.IndexOf(cli, "--dashline");
                if (dli >= 0 && dli + 1 < cli.Length && int.TryParse(cli[dli + 1], out int dashArg))
                {
                    for (int k = 0; k < dashArg; k++) Host.Commands.CycleLineDash();
                    SettleFrames(120);
                }
            }
            // --paraaxis N：把「抛物线」那一格的档位往后切 N 下（N=1 就是"左右抛物"那一档）。
            // 和 --dashline 同一类，只服务"图上看细节"。
            {
                int pai = Array.IndexOf(cli, "--paraaxis");
                if (pai >= 0 && pai + 1 < cli.Length && int.TryParse(cli[pai + 1], out int paArg))
                {
                    for (int k = 0; k < paArg; k++) Host.Commands.CycleParabolaAxis();
                    SettleFrames(120);
                }
            }
            if (_panelShowDrawer) ui.OpenDrawerForTest();   // --drawer：连抽屉一起出图
            SettleFrames(500);

            // 优先离屏出图（锁屏 / 远程也能出，图里不混桌面）。
            // **范围要连"画到外面那一圈"一起给**（投影，见 IOverlayUi.PaintMargin）：
            // 这一条的边上留白只有 24 **物理**像素，200% 缩放下就是 12 逻辑像素，
            // 而投影最远胀出去 16+8 逻辑像素——不给就会被切掉一半，图看着像"没有投影"。
            var b = ui.QueryBounds();
            var shot = new RectF
            {
                MinX = b.MinX - ui.PaintMargin, MinY = b.MinY - ui.PaintMargin,
                MaxX = b.MaxX + ui.PaintMargin, MaxY = b.MaxY + ui.PaintMargin,
            };
            // --zoom N：只出**第 N 格的近景**（2026-09-19 加，看"图形那一格的图标"用）。
            // 裁剪框就是那一格的矩形再松 8 逻辑像素——多给一圈是为了别把按钮的圆角
            // 和选中底色切掉（切掉之后图上看着像"图标缺了一块"）。产品里没有这个入口，
            // 它只服务"图上看细节"。
            {
                int zi = Array.IndexOf(cli, "--zoom");
                if (zi >= 0 && zi + 1 < cli.Length && int.TryParse(cli[zi + 1], out int zoomCell))
                {
                    var cr = ui.CellRectForTest(zoomCell);
                    if (!cr.IsEmpty)
                        shot = new RectF
                        {
                            MinX = cr.MinX - 8f, MinY = cr.MinY - 8f,
                            MaxX = cr.MaxX + 8f, MaxY = cr.MaxY + 8f,
                        };
                }
            }
            if (OffscreenShot(path, shot)) return;
            int x = (int)MathF.Floor(b.MinX * DpiScale) - 30;
            int y = (int)MathF.Floor(b.MinY * DpiScale) - 30;
            int w = (int)MathF.Ceiling((b.MaxX - b.MinX) * DpiScale) + 60;
            int h = (int)MathF.Ceiling((b.MaxY - b.MinY) * DpiScale) + 60;
            bool ok = ScreenProbe.SaveBmp(path, x, y, w, h);
            Console.WriteLine(ok
                ? $"已出图 {path}（面板 {b.MaxX - b.MinX:F0}×{b.MaxY - b.MinY:F0} 逻辑像素）"
                : "出图失败");
            ExitCode = ok ? 0 : 1;
        }
        _quit = true;
    }

    private void PanelTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 产品界面自检（球 → 按钮带）===");

        if (SkipIfNoSyntheticInput("产品界面自检")) { _quit = true; return; }

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-26} {detail}");
        }

        void ClickPhysical(float x, float y)
        {
            SendMouse((int)x, (int)y, 0);                            SettleFrames(80);
            SendMouse((int)x, (int)y, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
            SendMouse((int)x, (int)y, Native.MOUSEEVENTF_LEFTUP);    SettleFrames(320);
        }

        PassMode = PassThroughMode.LayeredTransparent;
        PassThrough = false;
        foreach (var w in _windows) ApplyPassThroughStyle(w);
        SetUiFactory(() => new InkUi.FullUi());
        Doc.Clear();
        Doc.ClearHistory();
        Tool = Tool.Pen;
        SettleFrames(300);

        var ui = CurrentUi as InkUi.FullUi;
        if (ui == null)
        {
            Console.WriteLine($"  界面没挂上：当前 = {CurrentUi.Name}");
            ExitCode = 1;
            _quit = true;
            return;
        }

        // ---- ⓪ 贴边隐藏 + **刚启动**：不许一上来就收（用户 2026-09-17）----
        //
        // 原来 `_leftAtMs` 初值是负无穷，第一帧就满足"离开够久了"——一开机面板立刻收成
        // 屏幕底边那条 8 像素的露头（而且露头正好压在任务栏上），老师根本找不到它。
        // 现在：**先露着**，等指针碰过面板一次才允许自动收。
        {
            // 先把指针挪到画布上（确保没碰过面板），再把"贴边隐藏"写进偏好、重新挂一个界面
            // ——重新挂就等于"刚启动"那一刻。
            SendMouse((int)(_virtualX + _virtualW * 0.5f), (int)(_virtualY + _virtualH * 0.3f), 0);
            SettleFrames(200);
            SetUiPref("hide", "1");
            SetUiFactory(() => new InkUi.FullUi());
            ui = CurrentUi as InkUi.FullUi;
            SettleFrames(1800);                 // 等过"离开 700 毫秒才收"那一段
            var b0 = ui.QueryBounds();
            Check("贴边隐藏开着＋刚启动：面板还是完整的（不许一上来就收）",
                  (b0.MaxY - b0.MinY) > 40f && !ui.PeekArmedForTest,
                  $"占用 {b0.MaxX - b0.MinX:F0}×{b0.MaxY - b0.MinY:F0}，允许自动收 = {ui.PeekArmedForTest}");

            SendMouse((int)((b0.MinX + b0.MaxX) * 0.5f * DpiScale),
                      (int)((b0.MinY + b0.MaxY) * 0.5f * DpiScale), 0);
            SettleFrames(250);
            SendMouse((int)(_virtualX + _virtualW * 0.5f), (int)(_virtualY + _virtualH * 0.3f), 0);
            SettleFrames(2000);
            var b1 = ui.QueryBounds();
            Check("碰过之后再离开：这时才收成露头",
                  (b1.MaxY - b1.MinY) < 12f || (b1.MaxX - b1.MinX) < 12f,
                  $"占用 {b1.MaxX - b1.MinX:F0}×{b1.MaxY - b1.MinY:F0}，允许自动收 = {ui.PeekArmedForTest}");

            // ---- 露头状态下"写一笔"：面板**不许自己蹦回来**（用户 2026-09-18 报的）----
            //
            // 起因是 `UpdatePeek` 里 `keepOpen` 那条把 `IsDrawing` 和"指针在面板上"混在了一起：
            // 规则的本意是**写字中不许收**，写成了"写字中强制展开"，于是藏好的面板一落笔就被拽出来。
            // 判据：在**画布中间**（离那条露头足够远，排除"是碰到面板才展开的"）画一笔，
            // 画完占用矩形必须还是露头那一条。
            {
                float inkX = _virtualX + _virtualW * 0.5f;
                float inkY = _virtualY + _virtualH * 0.4f;
                SendMouse((int)inkX, (int)inkY, 0);                          SettleFrames(60);
                SendMouse((int)inkX, (int)inkY, Native.MOUSEEVENTF_LEFTDOWN); SettleFrames(60);
                for (int i = 1; i <= 5; i++)
                { SendMouse((int)(inkX + 20 * i * DpiScale), (int)inkY, 0); SettleFrames(20); }
                SendMouse((int)(inkX + 100 * DpiScale), (int)inkY, Native.MOUSEEVENTF_LEFTUP);
                SettleFrames(250);

                var b2 = ui.QueryBounds();
                Check("露头时在画布上写一笔：面板不许被拽出来",
                      (b2.MaxY - b2.MinY) < 12f || (b2.MaxX - b2.MinX) < 12f,
                      $"占用 {b2.MaxX - b2.MinX:F0}×{b2.MaxY - b2.MinY:F0}"
                      + $"，露头值 peek={ui.PeekForTest:F2}（0 = 收着），"
                      + $"允许自动收 = {ui.PeekArmedForTest}，"
                      + $"画完真出了笔 = {Doc.Strokes.Count > 0}");

                // ---- 反过来那一半也要钉住：**面板开着的时候写字，不许它自己收** ----
                //
                // 这是那条规则原本的用途（"老师写到屏幕边上，工具条不能自己缩回去"）。
                // 修上面那个 bug 时很容易顺手把这条一起弄丢，所以单独钉一条。
                SendMouse((int)((b1.MinX + b1.MaxX) * 0.5f * DpiScale),
                          (int)((b1.MinY + b1.MaxY) * 0.5f * DpiScale), 0);   // 碰露头，把它叫回来
                SettleFrames(400);
                float ix = _virtualX + _virtualW * 0.5f;
                float iy = _virtualY + _virtualH * 0.4f;
                SendMouse((int)ix, (int)iy, 0);                           SettleFrames(60);
                SendMouse((int)ix, (int)iy, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
                for (int i = 1; i <= 8; i++)
                { SendMouse((int)(ix + 18 * i * DpiScale), (int)iy, 0); SettleFrames(120); }  // 按住写约 1 秒
                var mid = ui.QueryBounds();
                SendMouse((int)(ix + 144 * DpiScale), (int)iy, Native.MOUSEEVENTF_LEFTUP);
                SettleFrames(200);
                Check("面板开着时按着写约 1 秒：不许它自己收",
                      (mid.MaxY - mid.MinY) > 40f,
                      $"写字中占用 {mid.MaxX - mid.MinX:F0}×{mid.MaxY - mid.MinY:F0}");
            }

            // ---- 左右两条边：**球能藏、条不藏**（用户 2026-09-18 定的规则）----
            //
            // 面板是横的，"缩进侧边"等于把它**侧着塞进边里**——贴左边露出来的其实是它的
            // 右端（最后一格和动作按钮区），跟"球"没有任何关系；而球是 48×48 的正方形，
            // 塞进哪条边都是同一个姿态。所以：收起态四边都藏，展开态只在上下藏，
            // 左右**保留吸附停靠**但不再往里缩。
            {
                // 此刻面板是展开的、贴在屏幕下边（可能正在收着露头）——先碰一下叫回来，
                // 再收成球，然后把球拖到左边缘。
                var side0 = ui.QueryBounds();
                SendMouse((int)((side0.MinX + side0.MaxX) * 0.5f * DpiScale),
                          (int)((side0.MinY + side0.MaxY) * 0.5f * DpiScale), 0);
                SettleFrames(400);
                if (ui.ExpandedForTest)
                {
                    var c0 = ui.CellRectForTest(0);
                    ClickPhysical((c0.MinX + c0.MaxX) * 0.5f * DpiScale,
                                  (c0.MinY + c0.MaxY) * 0.5f * DpiScale);
                    SettleFrames(350);
                }

                var side1 = ui.QueryBounds();
                float bx = (side1.MinX + side1.MaxX) * 0.5f * DpiScale;
                float by = (side1.MinY + side1.MaxY) * 0.5f * DpiScale;
                int leftX = _virtualX + 20;
                SendMouse((int)bx, (int)by, 0);                            SettleFrames(60);
                SendMouse((int)bx, (int)by, Native.MOUSEEVENTF_LEFTDOWN);   SettleFrames(50);
                for (int i = 1; i <= 8; i++) { SendMouse((int)(bx + (leftX - bx) * i / 8f), (int)by, 0); SettleFrames(20); }
                SendMouse(leftX, (int)by, Native.MOUSEEVENTF_LEFTUP);       SettleFrames(200);

                // 看一眼就走：球停在左边，700 毫秒后应该收成侧边那条竖的露头
                SendMouse((int)(_virtualX + _virtualW * 0.5f), (int)(_virtualY + _virtualH * 0.35f), 0);
                SettleFrames(1400);
                var tucked = ui.QueryBounds();
                Check("收起态停在左边：会藏成侧边那条露头（竖的 8×48）",
                      (tucked.MaxX - tucked.MinX) < 12f && (tucked.MaxY - tucked.MinY) > 30f,
                      $"占用 {tucked.MaxX - tucked.MinX:F0}×{tucked.MaxY - tucked.MinY:F0}"
                      + $"，展开 = {ui.ExpandedForTest}");

                // 碰回来 → 点开成条 → 再走开：这一次**不许收**
                SendMouse((int)((tucked.MinX + tucked.MaxX) * 0.5f * DpiScale),
                          (int)((tucked.MinY + tucked.MaxY) * 0.5f * DpiScale), 0);
                SettleFrames(450);
                var side2 = ui.QueryBounds();
                ClickPhysical((side2.MinX + side2.MaxX) * 0.5f * DpiScale,
                              (side2.MinY + side2.MaxY) * 0.5f * DpiScale);
                SettleFrames(400);
                SendMouse((int)(_virtualX + _virtualW * 0.5f), (int)(_virtualY + _virtualH * 0.35f), 0);
                SettleFrames(1400);
                var barLeft = ui.QueryBounds();
                Check("展开态停在左边：**不缩回**（左右只吸附、不藏）",
                      (barLeft.MaxX - barLeft.MinX) > 400f && (barLeft.MaxY - barLeft.MinY) > 40f,
                      $"占用 {barLeft.MaxX - barLeft.MinX:F0}×{barLeft.MaxY - barLeft.MinY:F0}，"
                      + $"展开 = {ui.ExpandedForTest}，露头值 peek={ui.PeekForTest:F2}");
            }

            // 收尾：关掉贴边隐藏、重新挂回默认界面（后面几段用例都按"没开贴边隐藏"写）
            SetUiPref("hide", null);
            Doc.Clear();                    // 上面为了验贴边隐藏画了两笔，后面的用例从空画布起
            Doc.ClearHistory();
            SetUiFactory(() => new InkUi.FullUi());
            ui = CurrentUi as InkUi.FullUi;
            SettleFrames(400);
        }

        // 把面板弄到"展开 ＋ 抽屉开着"这个已知状态。
        // 每一步都先问**当前**状态再动手——面板可能正收着、可能刚被换成新实例，
        // 硬按上一次算好的坐标去点，点空了都不知道（这一版用例被坑过一次）。
        void NormalizePanel()
        {
            if (!ui.ExpandedForTest)
            {
                var b = ui.QueryBounds();
                ClickPhysical((b.MinX + b.MaxX) * 0.5f * DpiScale,
                              (b.MinY + b.MaxY) * 0.5f * DpiScale);
                SettleFrames(300);
            }
            if (!ui.DrawerOpenForTest)
            {
                var m = ui.CellRectForTest(12);
                ClickPhysical((m.MinX + m.MaxX) * 0.5f * DpiScale,
                              (m.MinY + m.MaxY) * 0.5f * DpiScale);
                SettleFrames(250);
            }
        }

        // ---- ① 启动默认态：**展开 ＋ 贴在工作区底边、水平居中**（用户 2026-09-27 定）----
        //
        // 用户原话："打开后默认居中，高度大概在 Win11 系统任务栏的上面"，随后补了一句
        // "和任务栏不重叠，在它上方一点点"。落成三条判据：
        //   ① 启动就是**展开**的（不是一颗球等人去点）；
        //   ② 主条底边 = **工作区**底边 − 4（工作区 = 屏幕减掉任务栏）；
        //   ③ 水平在**工作区**里居中（不是虚拟桌面——多屏时那样会落在两块屏的缝上）。
        Check("启动即展开（不是一颗球等人去点）",
              ui.ExpandedForTest, $"展开 = {ui.ExpandedForTest}");

        var work = ui.WorkAreaForTest;
        {
            var b0 = ui.BarRectForTest;
            float screenBottom = VirtualScreen.MaxY / DpiScale;
            Check("默认位置：主条底边 = 工作区底边 − 4（紧贴任务栏上方）",
                  MathF.Abs(b0.MaxY - (work.MaxY - InkUi.Tokens.EdgeMargin)) < 1.5f,
                  $"条底 {b0.MaxY:F0}，工作区底 {work.MaxY:F0}，屏幕底 {screenBottom:F0}"
                  + $"（差 {screenBottom - work.MaxY:F0} = 任务栏那一条）");
            Check("默认位置：**不压任务栏**（条底 ≤ 工作区底）",
                  b0.MaxY <= work.MaxY + 0.5f,
                  $"条底 {b0.MaxY:F0} ≤ 工作区底 {work.MaxY:F0}");
            float wantCx = (work.MinX + work.MaxX) * 0.5f;
            Check("默认位置：整条带子在**工作区**里水平居中",
                  MathF.Abs((b0.MinX + b0.MaxX) * 0.5f - wantCx) < 2f,
                  $"带子中心 {(b0.MinX + b0.MaxX) * 0.5f:F0}，工作区中心 {wantCx:F0}，"
                  + $"虚拟桌面中心 {(_virtualX + _virtualW * 0.5f) / DpiScale:F0}"
                  + "（单屏时这两个数相同，多屏才会分开——那正是这条要挡的）");
        }

        // 底下几段验的是**收起态**（球的几何、点球展开），所以这里先手动收起来。
        // 产品里"收起"是点一下主条的结果（那条路在 ⑦ 的收起/展开用例里），
        // 这里用 `SetExpandForTest` 一步到位——它和动画终态是同一个值。
        ui.SetExpandForTest(0f);
        SettleFrames(250);

        // ---- ①b 收起态：球真的在屏幕上，而且是个 48 的方（圆） ----
        var ball = ui.QueryBounds();
        float ballW = ball.MaxX - ball.MinX, ballH = ball.MaxY - ball.MinY;
        Check("收起态是一个 48 的球",
              MathF.Abs(ballW - 48f) < 1f && MathF.Abs(ballH - 48f) < 1f,
              $"占用 {ballW:F0}×{ballH:F0}，位置 ({ball.MinX:F0},{ball.MinY:F0})");

        // ---- 收起球里那两个比例：**笔图标不许碰到色圈** ----
        //
        // 用户 2026-09-18 报过一次"笔碰到色圈"：产品把假面板的 0.70R 抄成了 1.40R，
        // 半边长 16.8 正好顶到色圈内沿 16.99。这条不靠眼睛——**碰没碰到是算得出来的**：
        //   色圈内沿 = BallRing × R − 线宽/2；  图标半边长 = BallIcon × R ÷ 2
        // 要求留 ≥ 1 像素的空（0.19 那种"看着压上去了"的余量不算）。
        {
            float R = InkUi.Tokens.Ball * 0.5f;
            float ringInner = InkUi.Tokens.BallRing * R - 1.25f;      // 线宽 2.5 的一半
            float iconHalf = InkUi.Tokens.BallIcon * R * 0.5f;
            Check("收起球：笔图标不碰色圈（半边长 < 色圈内沿 − 1）",
                  iconHalf < ringInner - 1f,
                  $"图标半边长 {iconHalf:F2} vs 色圈内沿 {ringInner:F2}"
                  + $"（BallIcon = {InkUi.Tokens.BallIcon:F2}R，留 {ringInner - iconHalf:F2} 的空）");
        }

        // 球也贴**工作区**底边（和展开态同一个锚点：锚的是"展开后带子的左端"，
        // 所以收起/展开之间球一动不动，Y 自然也一样）。
        // ⚠ 这里 2026-09-27 之前是按**屏幕**底边 + 离边 12 写的，还专门注了
        //   "允许盖住任务栏"——用户改主意了：不盖、也不重叠，紧贴任务栏上方。
        Check("球贴在**工作区**底边、离边 4（同样不压任务栏）",
              MathF.Abs(ball.MaxY - (work.MaxY - InkUi.Tokens.EdgeMargin)) < 1.5f,
              $"球底 {ball.MaxY:F0}，工作区底 {work.MaxY:F0}，屏幕底 {VirtualScreen.MaxY / DpiScale:F0}");

        // 没拖过时的横向位置：锚点是**展开后那条带子的左端**，而带子在**工作区**里居中，
        // 所以球停在"工作区中心 − 带子宽/2"（偏左半个带子）。
        // 用户 2026-09-17 要的就是这个：**点一下往右展开、展开完全局居中**。
        {
            float wantBallLeft = work.MinX + ((work.MaxX - work.MinX) - ui.ExpandedWidthForTest) * 0.5f;
            Check("没拖过：球停在「展开后带子居中」的左端",
                  MathF.Abs(ball.MinX - wantBallLeft) < 1.5f,
                  $"球左 {ball.MinX:F0}（应为 {wantBallLeft:F0} = 工作区中心 − 带子宽/2），"
                  + $"带子宽 {ui.ExpandedWidthForTest:F0}");
        }

        // ---- ② 点球展开：动画期间必须连续出帧 ----
        int strokes0 = Doc.Strokes.Count;
        float ballCx = (ball.MinX + ball.MaxX) * 0.5f * DpiScale;
        float ballCy = (ball.MinY + ball.MaxY) * 0.5f * DpiScale;
        SendMouse((int)ballCx, (int)ballCy, 0);                            SettleFrames(70);
        SendMouse((int)ballCx, (int)ballCy, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(50);
        SendMouse((int)ballCx, (int)ballCy, Native.MOUSEEVENTF_LEFTUP);

        // 松手就开始数帧——**别先 settle**：动画只有 200 毫秒，
        // 先 settle 一遍等于等它跑完再来数"动画期间的帧"，那永远数不出东西。
        int frames = 0;
        var sw = Stopwatch.StartNew();
        while (sw.ElapsedMilliseconds < 260)
        {
            PumpMessages();
            if (NeedsFrame()) { RenderAll(); _dirty = false; frames++; }
            else Thread.Sleep(1);
        }
        SettleFrames(120);

        Check("点球能展开", ui.ExpandedForTest, $"展开状态 = {ui.ExpandedForTest}");
        Check("展开动画拿到了连续帧", frames >= 5, $"260 毫秒里出了 {frames} 帧");
        Check("点球不落墨", Doc.Strokes.Count == strokes0, $"笔画 {strokes0} → {Doc.Strokes.Count}");

        // ---- ③ 展开后的尺寸：算出来的宽，不是一个拍脑袋的数 ----
        var bar = ui.QueryBounds();
        float barW = bar.MaxX - bar.MinX, barH = bar.MaxY - bar.MinY;
        var barOnly = ui.BarRectForTest;
        // 总高看这一刻上带是色线还是设置条（58 / 86），所以这里只卡"主条 48、宽 > 600、
        // 总高在这两档之间"；两条精确的高度由上面那两条"色线/设置条"专测。
        Check("展开成一条带子（主条高 48、宽 > 600）",
              MathF.Abs((barOnly.MaxY - barOnly.MinY) - 48f) < 1f
              && barH >= 52f && barH <= 88f      // 色线时 54、设置条时 82
              && barW > 600f,
              $"占用 {barW:F0}×{barH:F0}（主条高 {barOnly.MaxY - barOnly.MinY:F0}）");

        // 展开之后**整条带子在工作区里居中**（没拖过时）。球停在带子左端，从头到尾没动过。
        {
            float workCx = (work.MinX + work.MaxX) * 0.5f;
            Check("展开后整条带子在**工作区**里居中",
                  MathF.Abs((barOnly.MinX + barOnly.MaxX) * 0.5f - workCx) < 2f,
                  $"带子中心 {(barOnly.MinX + barOnly.MaxX) * 0.5f:F0}，工作区中心 {workCx:F0}"
                  + $"（带子 {barOnly.MinX:F0}..{barOnly.MaxX:F0}）");
        }

        // 带子长在**上面**（贴底时朝屏幕中心）：主条位置不许动——
        // 你刚点的那个按钮要是往上跳 38 像素，下一次点它就得重新瞄（费茨定律）。
        Check("展开时主条不动（只有带子长出来）",
              MathF.Abs(barOnly.MinY - ball.MinY) < 1.5f
              && MathF.Abs(barOnly.MaxY - ball.MaxY) < 1.5f,
              $"收起时 y {ball.MinY:F0}..{ball.MaxY:F0}，展开后主条 y {barOnly.MinY:F0}..{barOnly.MaxY:F0}");

        // ---- ④ 点"笔"那一格：引擎状态真的变了（走的是命令通道）----
        Tool = Tool.Eraser;
        var penCell = ui.CellRectForTest(3);
        ClickPhysical((penCell.MinX + penCell.MaxX) * 0.5f * DpiScale,
                      (penCell.MinY + penCell.MaxY) * 0.5f * DpiScale);
        Check("点「笔」切到笔", Tool == Tool.Pen, $"工具 = {Tool}");

        // ---- ⑤ 输入拦截：面板内不落墨，面板外照常落墨 ----
        strokes0 = Doc.Strokes.Count;
        var boardCell = ui.CellRectForTest(2);
        ClickPhysical((boardCell.MinX + boardCell.MaxX) * 0.5f * DpiScale,
                      (boardCell.MinY + boardCell.MaxY) * 0.5f * DpiScale);
        Check("点「白板」不落墨", Doc.Strokes.Count == strokes0,
              $"笔画 {strokes0} → {Doc.Strokes.Count}，白板 = {BoardOn}");
        if (BoardOn) { Host.Commands.SetBoard(false); SettleFrames(120); }

        strokes0 = Doc.Strokes.Count;
        Tool = Tool.Pen;
        ClickPhysical(_virtualX + _virtualW * 0.5f, _virtualY + _virtualH * 0.45f);
        Check("面板外照常落墨", Doc.Strokes.Count > strokes0,
              $"笔画 {strokes0} → {Doc.Strokes.Count}");

        // ---- ⑥ 上带：色片 / 滑条 / 分段（都走命令通道）----
        //
        // **张不张开只看焦点在不在面板上**（2026-09-17 用户定的新语义）：
        //   指针落在面板（主条 ∪ 设置条）上 → 张开；离开 → 220 毫秒后收成一条 6 像素色线。
        // 旧的那套"点一次钉住、再点同一个工具收起"已经删掉了——两套规则会打架：
        // 指针还停在面板上，收下去会立刻又张开。
        var penCellAgain = ui.CellRectForTest(3);
        ClickPhysical((penCellAgain.MinX + penCellAgain.MaxX) * 0.5f * DpiScale,
                      (penCellAgain.MinY + penCellAgain.MaxY) * 0.5f * DpiScale);
        SettleFrames(300);
        Check("焦点在面板上：设置条张开",
              ui.RailHoverForTest && ui.RailOpenForTest
              && MathF.Abs(ui.BandHeightForTest - InkUi.Tokens.BandHeight) < 1.5f,
              $"焦点在面板 = {ui.RailHoverForTest}，张开 = {ui.RailOpenForTest}，高 {ui.BandHeightForTest:F0}");

        // 指针移到画布上（离开面板）→ 收成一条色线
        SendMouse((int)(_virtualX + _virtualW * 0.6f), (int)(_virtualY + _virtualH * 0.3f), 0);
        SettleFrames(700);                              // 220ms 退出延迟 + 167ms 动画，留足
        Check("指针离开面板：收成一条色线",
              !ui.RailOpenForTest
              && MathF.Abs(ui.BandHeightForTest - InkUi.Tokens.BandLine) < 1.5f,
              $"张开 = {ui.RailOpenForTest}，高 {ui.BandHeightForTest:F0}（色线应为 {InkUi.Tokens.BandLine:F0}）");

        // 再把指针挪回**主条**（不是色带本身）→ 不用点，它自己就该张开。
        // 这一条就是用户说的"焦点在悬浮框的时候就展开"。
        var barHover = ui.BarRectForTest;
        int hoverPx = (int)((barHover.MinX + barHover.MaxX) * 0.5f * DpiScale);
        int hoverPy = (int)((barHover.MinY + barHover.MaxY) * 0.5f * DpiScale);
        // 合成鼠标**偶尔会丢一次移动**（自检里见过：同一份代码，一次跑红一次跑绿）——
        // 每次把坐标挪 1 像素再发，保证真的产生一次 WM_MOUSEMOVE，最多给三次机会。
        for (int attempt = 0; attempt < 3 && !ui.RailOpenForTest; attempt++)
        {
            SendMouse(hoverPx, hoverPy - attempt, 0);
            SettleFrames(350);
        }
        var hb = ui.QueryBounds();
        Console.WriteLine($"    [诊断] 指针物理 ({hoverPx},{hoverPy})，主条 {barHover.MinX:F0}..{barHover.MaxX:F0}"
                        + $" × {barHover.MinY:F0}..{barHover.MaxY:F0}，面板 {hb.MinX:F0}..{hb.MaxX:F0}"
                        + $" × {hb.MinY:F0}..{hb.MaxY:F0}，railHover={ui.RailHoverForTest}");
        Check("指针回到面板（主条）上就自己张开",
              ui.RailOpenForTest && ui.RailHoverForTest,
              $"张开 = {ui.RailOpenForTest}，高 {ui.BandHeightForTest:F0}");

        var bandRect = ui.BandRectForTest;
        Check("展开后有上带", bandRect.MaxY - bandRect.MinY > 20f,
              $"上带 {bandRect.MaxX - bandRect.MinX:F0}×{bandRect.MaxY - bandRect.MinY:F0}");

        Check("上带是笔的设置条（色片行）", ui.RailOpenForTest,
              $"张开 = {ui.RailOpenForTest}");

        // 挑一个**不是默认色**的色片（默认笔色就是红，用红当期望值会假通过——
        // 这一条自检第一版就是这么假通过的，被"换色成功"蒙了一次）。
        // 期望值跟着 `Tokens.Palette` 走、这里不写死颜色名：2026-09-27 换过色表
        //（第 7 个从"绿"变成了"紫"），当时这条自检**没红**——因为两边都读同一个下标。
        var swatch = ui.SwatchRectForTest(6);                 // 第 7 个色片
        float swx = (swatch.MinX + swatch.MaxX) * 0.5f * DpiScale;
        float swy = (swatch.MinY + swatch.MaxY) * 0.5f * DpiScale;
        ClickPhysical(swx, swy);
        var wantColor = InkUi.Tokens.Palette[6].Color;
        var gotColor = Host.State.PaletteBase;
        var defaultColor = InkPalette.PenDefault;
        bool isDefault = MathF.Abs(gotColor.R - defaultColor.R) < 0.02f
                      && MathF.Abs(gotColor.G - defaultColor.G) < 0.02f
                      && MathF.Abs(gotColor.B - defaultColor.B) < 0.02f;
        Check("点色片换笔色",
              MathF.Abs(wantColor.R - gotColor.R) < 0.02f
              && MathF.Abs(wantColor.G - gotColor.G) < 0.02f
              && MathF.Abs(wantColor.B - gotColor.B) < 0.02f
              && !isDefault,
              $"期望 ({wantColor.R:F2},{wantColor.G:F2},{wantColor.B:F2})，实际 ({gotColor.R:F2},{gotColor.G:F2},{gotColor.B:F2})");

        // ---- ⑥.1 色带条上的**虚实线切换**（用户 2026-09-19 第 2 件）----
        //
        // 位置是用户点的："加在'调按钮大小'和'颜色带'中间"。所以这里除了"点得到、
        // 三档轮回"，还断言**它真的夹在色片和滑条之间**（两边都不压着）——
        // 位置是需求的一部分，光验"有个按钮"验不出来。
        {
            Check("笔的设置条上有虚实线那一格", ui.DashToggleVisibleForTest, "");
            var dashR = ui.DashToggleRectForTest;
            var lastSw = ui.SwatchRectForTest(ui.SwatchCountForTest - 1);
            var sliderR = ui.SliderRectForTest;
            Check("虚实线那一格夹在色片和粗细滑条中间（两边都不压着）",
                  dashR.MinX >= lastSw.MaxX - 0.5f && dashR.MaxX <= sliderR.MinX + 0.5f,
                  $"色片到 {lastSw.MaxX:F0}，虚实线 {dashR.MinX:F0}..{dashR.MaxX:F0}，滑条从 {sliderR.MinX:F0}");

            // 加了这一格之后色片会变窄——"挤到看不清"等于这个入口没有（和极简档 4 色那条同一个判据）。
            var swFirst = ui.SwatchRectForTest(0);
            Check("完整档：加了这一格之后色片仍然够宽（≥ 30 逻辑像素）",
                  swFirst.MaxX - swFirst.MinX >= 30f, $"色片宽 {swFirst.MaxX - swFirst.MinX:F0}");

            float dx = (dashR.MinX + dashR.MaxX) * 0.5f * DpiScale;
            float dy = (dashR.MinY + dashR.MaxY) * 0.5f * DpiScale;
            var dash0 = Host.State.Dash;
            ClickPhysical(dx, dy); SettleFrames(120);
            var dash1 = Host.State.Dash;
            ClickPhysical(dx, dy); SettleFrames(120);
            var dash2 = Host.State.Dash;
            ClickPhysical(dx, dy); SettleFrames(150);
            Check("点虚实线那一格：三档轮回（实线 → 虚线 → 点线 → 实线）",
                  dash0 == StrokeDash.Solid && dash1 == StrokeDash.Dashed
                  && dash2 == StrokeDash.Dotted && Host.State.Dash == StrokeDash.Solid,
                  $"{dash0} → {dash1} → {dash2} → {Host.State.Dash}");
            Check("换挡只动线型，不许顺手换工具",
                  Tool == Tool.Pen, $"工具 = {Tool}");
        }

        float widthBefore = Host.State.Width;
        var slider = ui.SliderRectForTest;
        float sliderY = (slider.MinY + slider.MaxY) * 0.5f * DpiScale;
        SendMouse((int)(slider.MinX * DpiScale), (int)sliderY, 0);                          SettleFrames(60);
        SendMouse((int)(slider.MinX * DpiScale), (int)sliderY, Native.MOUSEEVENTF_LEFTDOWN); SettleFrames(50);
        for (int i = 1; i <= 6; i++)
        {
            SendMouse((int)((slider.MinX + (slider.MaxX - slider.MinX) * i / 6f) * DpiScale),
                      (int)sliderY, 0);
            SettleFrames(25);
        }
        SendMouse((int)(slider.MaxX * DpiScale), (int)sliderY, Native.MOUSEEVENTF_LEFTUP);  SettleFrames(150);
        Check("拖滑条改粗细", Host.State.Width > widthBefore + 5f,
              $"粗细 {widthBefore:F1} → {Host.State.Width:F1}");

        // ---- ⑥.2 滑条**按工具路由**：橡皮终于能调大小了 ----
        //
        // 这一条是被用户点出来的："橡皮擦现在没有调节大小功能"。
        // 真相是界面上**有**滑条（`BandHasSlider` 一直包含橡皮那一格），
        // 但引擎的 `SetWidthFromUi` 只分了"荧光笔 / 激光 / 其它"三支，
        // 两种橡皮全落进"其它"——拖橡皮的滑条，**改的是笔宽**，橡皮一点没动。
        // 所以这三条要一起看：橡皮变了 **且** 笔宽没变（不然还会退回旧 bug）。
        {
            Host.Commands.SetTool(Tool.Eraser);
            SettleFrames(200);
            float penW0 = PenWidthLogical;
            // 先把指针放回面板（不然设置条是收着的，滑条不在）
            var barE = ui.BarRectForTest;
            SendMouse((int)((barE.MinX + barE.MaxX) * 0.5f * DpiScale),
                      (int)((barE.MinY + barE.MaxY) * 0.5f * DpiScale), 0);
            SettleFrames(400);
            var slE = ui.SliderRectForTest;
            float slEy = (slE.MinY + slE.MaxY) * 0.5f * DpiScale;

            var (emin, emax) = (8f, 48f);              // 界面那边 WidthRange(Tool.Eraser)
            var (trackL, trackR) = ui.SliderTrackRangeForTest;
            SendMouse((int)(trackL * DpiScale), (int)slEy, 0);                          SettleFrames(60);
            SendMouse((int)(trackL * DpiScale), (int)slEy, Native.MOUSEEVENTF_LEFTDOWN); SettleFrames(50);
            SendMouse((int)(trackR * DpiScale), (int)slEy, 0);                          SettleFrames(120);
            SendMouse((int)(trackR * DpiScale), (int)slEy, Native.MOUSEEVENTF_LEFTUP);   SettleFrames(150);
            Check("橡皮的滑条拖到最右＝最大落点",
                  MathF.Abs(EraserRadiusLogical - emax) < 1.5f,
                  $"橡皮半径 {EraserRadiusLogical:F1}（应到 {emax}）");
            Check("拖橡皮的滑条**不动笔宽**",
                  MathF.Abs(PenWidthLogical - penW0) < 0.01f,
                  $"笔宽 {penW0:F2} → {PenWidthLogical:F2}（旧 bug 就是这里被改掉的）");

            var (trackL2, trackR2) = ui.SliderTrackRangeForTest;
            SendMouse((int)(trackL2 * DpiScale), (int)slEy, Native.MOUSEEVENTF_LEFTDOWN); SettleFrames(60);
            SendMouse((int)(trackL2 * DpiScale), (int)slEy, 0);                          SettleFrames(120);
            SendMouse((int)(trackL2 * DpiScale), (int)slEy, Native.MOUSEEVENTF_LEFTUP);   SettleFrames(150);
            Check("橡皮的滑条拖到最左＝最小落点",
                  MathF.Abs(EraserRadiusLogical - emin) < 1.5f,
                  $"橡皮半径 {EraserRadiusLogical:F1}（应到 {emin}）");

            // **真实大小预览**（用户 2026-09-17："那个点和实际大小是不是应该一样大，
            // 但是太大了装不下，我又不希望改动界面"）。
            // 验的是"预览整个落在 QueryBounds() 里"——引擎按那份矩形裁剪界面，
            // 只要不包含它，画出去的部分就会被裁掉（这才是"预览看不见"的真因）。
            // 拖完滑条指针还停在滑条上 → 预览应该在。
            var pv = ui.SizePreviewRectForTest;
            var qb = ui.QueryBounds();
            Check("粗细预览画在面板外、且算进可见范围（不会被裁掉）",
                  pv.MaxY - pv.MinY > InkUi.Tokens.BandHeight
                  && pv.MinX >= qb.MinX - 0.5f && pv.MaxX <= qb.MaxX + 0.5f
                  && pv.MinY >= qb.MinY - 0.5f && pv.MaxY <= qb.MaxY + 0.5f,
                  $"预览 {pv.MaxX - pv.MinX:F0}×{pv.MaxY - pv.MinY:F0}"
                  + $"（{pv.MinX:F0}..{pv.MaxX:F0} × {pv.MinY:F0}..{pv.MaxY:F0}），"
                  + $"可见范围 {qb.MaxX - qb.MinX:F0}×{qb.MaxY - qb.MinY:F0}");

            // 面积橡皮同理，而且它的范围比笔宽大得多（30～160）
            Host.Commands.SetTool(Tool.PixelEraser);
            SettleFrames(200);
            float penW1 = PenWidthLogical;
            var slP = ui.SliderRectForTest;
            float slPy = (slP.MinY + slP.MaxY) * 0.5f * DpiScale;
            var (pl, pr) = ui.SliderTrackRangeForTest;
            SendMouse((int)(pr * DpiScale), (int)slPy, 0);                          SettleFrames(60);
            SendMouse((int)(pr * DpiScale), (int)slPy, Native.MOUSEEVENTF_LEFTDOWN); SettleFrames(50);
            SendMouse((int)(pr * DpiScale), (int)slPy, 0);                          SettleFrames(120);
            SendMouse((int)(pr * DpiScale), (int)slPy, Native.MOUSEEVENTF_LEFTUP);   SettleFrames(150);
            Check("面积橡皮的滑条能放到 160（比笔宽的上限 40 大）",
                  MathF.Abs(PixelEraserWidthLogical - 160f) < 2f,
                  $"面积橡皮宽 {PixelEraserWidthLogical:F1}（应到 160）");
            Check("拖面积橡皮的滑条**不动笔宽**",
                  MathF.Abs(PenWidthLogical - penW1) < 0.01f,
                  $"笔宽 {penW1:F2} → {PenWidthLogical:F2}");
            Host.Commands.SetTool(Tool.Pen);
            SettleFrames(200);
        }

        // ---- ⑥.3 穿透与工具**互斥** ----
        {
            Host.Commands.SetPassThrough(true);
            SettleFrames(250);
            Check("穿透开着时，工具格一律不高亮（免得`穿透＋笔`同时亮）",
                  ui.CellActiveForTest(1) && !ui.CellActiveForTest(3) && !ui.CellActiveForTest(4)
                  && !ui.CellActiveForTest(6) && !ui.CellActiveForTest(9),
                  $"鼠标 = {ui.CellActiveForTest(1)}，笔 = {ui.CellActiveForTest(3)}，工具 = {Tool}");

            var penCellPt = ui.CellRectForTest(3);
            ClickPhysical((penCellPt.MinX + penCellPt.MaxX) * 0.5f * DpiScale,
                          (penCellPt.MinY + penCellPt.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("点工具格＝顺手关掉穿透（不用先去点鼠标格）",
                  !Host.State.PassThrough && Tool == Tool.Pen,
                  $"穿透 = {Host.State.PassThrough}，工具 = {Tool}");
            Check("关掉穿透之后工具格亮回来", ui.CellActiveForTest(3),
                  $"笔格高亮 = {ui.CellActiveForTest(3)}");
        }

        // ---- ⑥.3b 主条那几格"选中显示选中什么"（2026-09-26）----
        //
        // 用户那天说的那条逻辑：**没选中画一个固定的，选中之后就画"手里到底是什么"**。
        // 图形那一格早就这样了（见 ShapeBandTest 的 D 段），这一轮补了三处：
        //   · 白板那一格：板开着 → 图标就是**这块板的颜色**（白 / 绿 / 黑）；
        //   · 选择那一格：切到套索 → 画套索（不再是那个通用的选择框）；
        //   · 激光笔那一格：未选中/选中各一张（上游那个专名）。
        // 断言问的是 `CellIconForTest`——**和绘制同一条判据**（这正是这条自检要盯的：
        // 自检说换了、屏幕上没换，等于白测）。
        {
            Host.Commands.SetPassThrough(false);
            Host.Commands.SetTool(Tool.Pen);
            SettleFrames(200);

            // 穿透那一格（2026-09-26 用户："把'穿透'的图标换成鼠标，在'更多'里面也要改"）：
            // 两态都得是**鼠标设备**（MDI 那张：常态描边、选中实心）。原来那个是 Fluent `Cursor`
            // ＝ 一根箭头指针，和"选择"工具那根容易混。
            // ⚠ "更多里面也要改"这一半**不用另测**：抽屉和主条走的是同一个
            // `DrawCellIcon` / `CellIconName`（见那两处的说明），所以这一条断言同时管着两边——
            // 抽屉要是哪天又自己写一份图标名单，这条就会在出图验收时露馅（抽屉那张图见 --drawer）。
            Check("穿透那一格：没选中 → 指针箭头（Tabler 描边版）",
                  ui.CellIconForTest(1) == "cursorArrow",
                  $"画的是 {ui.CellIconForTest(1)}（期望 cursorArrow）");
            Host.Commands.SetPassThrough(true);
            SettleFrames(150);
            Check("穿透那一格：穿透开着 → 同一支箭头的实心版",
                  ui.CellIconForTest(1) == "cursorArrowFilled",
                  $"画的是 {ui.CellIconForTest(1)}（期望 cursorArrowFilled）");
            Host.Commands.SetPassThrough(false);
            Host.Commands.SetBoard(true);
            SettleFrames(150);

            foreach (var (idx, want) in new[] { (0, "白板"), (1, "绿板"), (2, "黑板") })
            {
                Host.Commands.SetBoardColor(InkPalette.BoardPresets[idx].Color);
                SettleFrames(120);
                Check($"白板那一格：板色换成「{want}」→ 图标就是这块板",
                      ui.CellIconForTest(2) == "board:" + want,
                      $"画的是 {ui.CellIconForTest(2)}（期望 board:{want}）");
            }
            Host.Commands.SetBoard(false);
            SettleFrames(120);
            Check("白板那一格：板关掉 → 回到固定的那张（不填颜色）",
                  ui.CellIconForTest(2) == "board",
                  $"画的是 {ui.CellIconForTest(2)}（期望 board）");
            Host.Commands.SetBoardColor(InkPalette.BoardPresets[0].Color);
            Host.Commands.SetBoard(true);
            SettleFrames(120);

            // 橡皮那一格（2026-09-26 用户挑的图标）：未选中＝**纯橡皮**（Radix 那张，
            // 15 网格，路径里一根横线都没有——用户："就像一个纯粹的橡皮擦，不要带那种横线"）；
            // 选中＝跟着当前是哪种橡皮换
            //（整笔擦＝Fluent 原版带横线、面积擦＝Eraser Medium 那个大圈）。
            Host.Commands.SetTool(Tool.Pen);
            SettleFrames(150);
            Check("橡皮那一格：没选中 → Radix 纯橡皮（无横线）",
                  ui.CellIconForTest(6) == "eraserPure",
                  $"画的是 {ui.CellIconForTest(6)}（期望 eraserPure）");
            Host.Commands.SetTool(Tool.Eraser);
            SettleFrames(150);
            Check("橡皮那一格：选中·整笔擦 → Fluent 那张（橡皮＋底下那道线）",
                  ui.CellIconForTest(6) == "eraser",
                  $"画的是 {ui.CellIconForTest(6)}（期望 eraser）");
            Host.Commands.SetTool(Tool.PixelEraser);
            SettleFrames(150);
            Check("橡皮那一格：切到面积擦 → Eraser Medium（橡皮＋大圈）",
                  ui.CellIconForTest(6) == "eraserMedium",
                  $"画的是 {ui.CellIconForTest(6)}（期望 eraserMedium）");

            // 选择那一格：未选中＝Lucide 虚线框＋指针；选中＝框选（MDI）/ 套索（Fluent）
            Host.Commands.SetTool(Tool.Marquee);
            Host.Commands.SetSelectMode(SelectMode.Rect);
            SettleFrames(150);
            Check("选择那一格：选中·框选 → MDI 那张（四角括号＋断续边）",
                  ui.CellIconForTest(7) == "mdiSelection",
                  $"画的是 {ui.CellIconForTest(7)}（期望 mdiSelection）");
            Host.Commands.SetSelectMode(SelectMode.Lasso);
            SettleFrames(150);
            Check("选择那一格：切到套索 → 图标跟着换成套索",
                  ui.CellIconForTest(7) == "lasso",
                  $"画的是 {ui.CellIconForTest(7)}（期望 lasso）");
            Host.Commands.SetTool(Tool.Pen);
            SettleFrames(150);
            Check("选择那一格：没选中 → 固定的那支（Lucide 虚线框＋指针）",
                  ui.CellIconForTest(7) == "lucideSelectPointer",
                  $"画的是 {ui.CellIconForTest(7)}（期望 lucideSelectPointer）");

            Host.Commands.SetTool(Tool.Laser);
            SettleFrames(150);
            string laserOn = ui.CellIconForTest(5);
            Check("激光笔那一格：选中 →「笔射出一道光」那张（现在是哪一支见 IconAtlas）",
                  laserOn.StartsWith("laser") || laserOn.StartsWith("msStylusLaser"),
                  $"画的是 {laserOn}");
            Host.Commands.SetTool(Tool.Pen);
            SettleFrames(150);
            string laserOff = ui.CellIconForTest(5);
            // 这条是**真断言**：两态必须是**两支不同的画法**——判据和绘制同源，
            // 所以"未选中那一档忘了换"这类漏法会当场红（不是"自己跟自己比"）。
            Check("激光笔那一格：未选中 != 选中（两态是两支画法，不许同一张）",
                  laserOff != laserOn, $"未选中 = {laserOff}，选中 = {laserOn}");
        }

        // ---- ⑥.4 截图那一格真的接上了（用户 2026-09-17："截图功能还没有接进来"）----
        //
        // 引擎里截图工具（Tool.Capture）和"拖框抓图"这条链路是有的（--capturetest 全绿），
        // 面板上第 9 格也在走 SetTool(Capture)。这一条把它**钉在自检里**：
        // 点一下必须真的切到截图工具、而且那一格要亮——不然老师点了没反应，
        // 只能得出"还没接进来"这个结论（这正是用户看到的）。
        {
            Host.Commands.SetTool(Tool.Pen);
            SettleFrames(150);
            var cap = ui.CellRectForTest(9);
            ClickPhysical((cap.MinX + cap.MaxX) * 0.5f * DpiScale,
                          (cap.MinY + cap.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("点「截屏」真的切到截图工具", Tool == Tool.Capture, $"工具 = {Tool}");
            Check("截屏那一格亮起来（点了有反馈）", ui.CellActiveForTest(9),
                  $"截屏格高亮 = {ui.CellActiveForTest(9)}");

            // 截图那一格现在也长设置条了：**[直接截取][隐藏批注截取]**（照 InkClass 的两项菜单）
            var capBar = ui.BarRectForTest;
            SendMouse((int)((capBar.MinX + capBar.MaxX) * 0.5f * DpiScale),
                      (int)((capBar.MinY + capBar.MaxY) * 0.5f * DpiScale), 0);
            SettleFrames(400);
            var segDirect = ui.SegmentRectForTest(0);
            var segHidden = ui.SegmentRectForTest(1);
            Check("截屏那一格有两条设置（0 宽 = 没接上）",
                  segDirect.MaxX - segDirect.MinX > 20f && segHidden.MinX > segDirect.MaxX - 1f,
                  $"段宽 {segDirect.MaxX - segDirect.MinX:F0}，第二段起点 {segHidden.MinX:F0}");

            ClickPhysical((segDirect.MinX + segDirect.MaxX) * 0.5f * DpiScale,
                          (segDirect.MinY + segDirect.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("点「直接截取」→ hideInk = false",
                  !Host.State.CaptureHideInk, $"hideInk = {Host.State.CaptureHideInk}");

            segHidden = ui.SegmentRectForTest(1);
            ClickPhysical((segHidden.MinX + segHidden.MaxX) * 0.5f * DpiScale,
                          (segHidden.MinY + segHidden.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("点「隐藏批注截取」→ hideInk = true",
                  Host.State.CaptureHideInk, $"hideInk = {Host.State.CaptureHideInk}");

            // 第三段是**动作**：粘贴图片（没有键盘的触摸屏 / 手写板也能用）
            {
                // 先在剪贴板上放一张 60×40 的图（绿底），再点"粘贴图片"
                var buf = new byte[60 * 40 * 4];
                for (int i = 0; i < buf.Length; i += 4)
                { buf[i] = 0; buf[i + 1] = 200; buf[i + 2] = 0; buf[i + 3] = 255; }
                ClipboardImage.SetImage(buf, 60, 40);
                int imgBefore = Doc.Strokes.Count(s => s.IsImage);

                var segPaste = ui.SegmentRectForTest(2);
                ClickPhysical((segPaste.MinX + segPaste.MaxX) * 0.5f * DpiScale,
                              (segPaste.MinY + segPaste.MaxY) * 0.5f * DpiScale);
                SettleFrames(400);
                int imgAfter = Doc.Strokes.Count(s => s.IsImage);
                Check("点「粘贴图片」：剪贴板里的图进了画布",
                      imgAfter == imgBefore + 1,
                      $"图像对象 {imgBefore} → {imgAfter}");

                // 收尾：把刚粘的那张删掉
                Doc.DeleteSelected();
                SettleFrames(150);
            }

            Host.Commands.SetTool(Tool.Pen);
            SettleFrames(150);
        }

        // ---- ⑥.5 上带右端的两个动作：清空（按住 0.8 秒）、全选（点一下）----
        //
        // 出自假面板：清空挂在**橡皮**那条（擦一点/擦一块/全擦掉是一路的事），
        // 按住 0.8 秒才算数；全选挂在**选择**那条。清空可撤销，但代价大，所以防误触。
        {
            Doc.Clear();
            Doc.ClearHistory();
            for (int i = 0; i < 3; i++)
            {
                var s = new Stroke
                {
                    Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                    Color = new Color4(0f, 0f, 0f, 1f), Width = 6f,
                };
                s.AddPoint(_virtualX + 300 + i * 40, _virtualY + 300, 1f, 0);
                s.AddPoint(_virtualX + 380 + i * 40, _virtualY + 340, 1f, 1);
                Doc.AddStroke(s);
            }
            // 再补一笔**洋红**的：专供"屏幕像素"核对。本轮那个 bug（清空之后墨还留在
            // 屏幕上、连橡皮都擦不掉）只有量屏幕才抓得到——当时只验了 Doc.Strokes.Count。
            float magX = _virtualX + 900f, magY = _virtualY + 620f;
            var magStroke = new Stroke
            {
                Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 26f * DpiScale,
            };
            magStroke.AddPoint(magX - 200f, magY, 1f, 0);
            magStroke.AddPoint(magX + 200f, magY, 1f, 1);
            Doc.AddStroke(magStroke);
            SettleFrames(150);
            SettleFrames(300);
            int inkBefore = ScreenProbe.CountMagenta((int)magX - 240, (int)magY - 40, 480, 80);
            Check("清空前：洋红那笔在屏幕上", inkBefore > 300, $"{inkBefore} 像素");

            Host.Commands.SetTool(Tool.Eraser);
            SettleFrames(200);
            var barA = ui.BarRectForTest;          // 指针挪回面板：设置条才开着
            SendMouse((int)((barA.MinX + barA.MaxX) * 0.5f * DpiScale),
                      (int)((barA.MinY + barA.MaxY) * 0.5f * DpiScale), 0);
            SettleFrames(400);

            var act = ui.ActionRectForTest;
            Check("橡皮那条右端有「清空」", act.MaxX - act.MinX > 40f,
                  $"动作按钮宽 {act.MaxX - act.MinX:F0}");

            float ax = (act.MinX + act.MaxX) * 0.5f * DpiScale;
            float ay = (act.MinY + act.MaxY) * 0.5f * DpiScale;
            int before = Doc.Strokes.Count;

            // 按住 0.3 秒就松手：**不清空**，而且那一刻进度条该走到一半
            SendMouse((int)ax, (int)ay, 0);                            SettleFrames(60);
            SendMouse((int)ax, (int)ay, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(300);
            bool midHold = ui.ActionHoldingForTest
                        && ui.HoldProgressForTest > 0.1f && ui.HoldProgressForTest < 0.9f;
            SendMouse((int)ax, (int)ay, Native.MOUSEEVENTF_LEFTUP);    SettleFrames(250);
            Check("按住 0.3 秒松手：不清空（进度条走到一半）",
                  midHold && Doc.Strokes.Count == before,
                  $"按住中 = {midHold}，笔画 {before} → {Doc.Strokes.Count}");

            // 按住够 0.8 秒：清空
            SendMouse((int)ax, (int)ay, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(1100);
            SendMouse((int)ax, (int)ay, Native.MOUSEEVENTF_LEFTUP);    SettleFrames(250);
            Check("按住 0.8 秒：清空生效", Doc.Strokes.Count == 0,
                  $"笔画 {before} → {Doc.Strokes.Count}");

            // **屏幕上也得干净**。这一条是本轮真 bug 的靶子：清空是在界面的 Render 里
            // 触发的，引擎渲染完无条件把脏区清了 → 文档空了、屏幕上那层墨还留着，
            // 表现就是"清空没用，而且常规橡皮也擦不掉"（文档里已经没东西可擦）。
            int inkAfter = ScreenProbe.CountMagenta((int)magX - 240, (int)magY - 40, 480, 80);
            Check("清空之后**屏幕上**也干净了（不然就是'墨迹卡住'）", inkAfter < 40,
                  $"{inkBefore} → {inkAfter} 像素");

            Host.Commands.Undo();
            SettleFrames(250);
            Check("清空能撤销回来（不是不可逆的破坏）", Doc.Strokes.Count == before,
                  $"撤销后 {Doc.Strokes.Count} 笔");
            int inkUndo = ScreenProbe.CountMagenta((int)magX - 240, (int)magY - 40, 480, 80);
            Check("撤销之后墨回到屏幕上", inkUndo > 300, $"{inkAfter} → {inkUndo} 像素");

            // 全选：挂在选择那条
            Host.Commands.SetTool(Tool.Marquee);
            SettleFrames(200);
            var barS = ui.BarRectForTest;
            SendMouse((int)((barS.MinX + barS.MaxX) * 0.5f * DpiScale),
                      (int)((barS.MinY + barS.MaxY) * 0.5f * DpiScale), 0);
            SettleFrames(400);
            var act2 = ui.ActionRectForTest;
            Check("选择那条右端有「全选」", act2.MaxX - act2.MinX > 40f,
                  $"动作按钮宽 {act2.MaxX - act2.MinX:F0}");

            Doc.Selected.Clear();
            ClickPhysical((act2.MinX + act2.MaxX) * 0.5f * DpiScale,
                          (act2.MinY + act2.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("点「全选」：选中的条数 = 笔画数",
                  Doc.Selected.Count == Doc.Strokes.Count && Doc.Selected.Count > 0,
                  $"选中 {Doc.Selected.Count} / 笔画 {Doc.Strokes.Count}");
        }

        // ---- ⑥.6 撤销/重做的**灰度**（用户 2026-09-17："撤销重做灰度"）----
        {
            Doc.Clear();
            Doc.ClearHistory();
            SettleFrames(250);
            Check("栈空：撤销和重做都压暗",
                  ui.CellUnavailableForTest(10) && ui.CellUnavailableForTest(11),
                  $"撤销压暗 = {ui.CellUnavailableForTest(10)}，重做压暗 = {ui.CellUnavailableForTest(11)}");

            var s1 = new Stroke
            {
                Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                Color = new Color4(0f, 0f, 0f, 1f), Width = 6f,
            };
            s1.AddPoint(_virtualX + 400, _virtualY + 400, 1f, 0);
            s1.AddPoint(_virtualX + 500, _virtualY + 420, 1f, 1);
            Doc.AddStroke(s1);
            SettleFrames(250);
            Check("画一笔之后：撤销亮、重做仍暗",
                  !ui.CellUnavailableForTest(10) && ui.CellUnavailableForTest(11),
                  $"撤销压暗 = {ui.CellUnavailableForTest(10)}，重做压暗 = {ui.CellUnavailableForTest(11)}");

            Host.Commands.Undo();
            SettleFrames(250);
            Check("撤销之后：重做亮起来",
                  ui.CellUnavailableForTest(10) && !ui.CellUnavailableForTest(11),
                  $"撤销压暗 = {ui.CellUnavailableForTest(10)}，重做压暗 = {ui.CellUnavailableForTest(11)}");
            Doc.Clear();
            Doc.ClearHistory();
            SettleFrames(150);
        }

        // ---- ⑥.8 白板色带：翻页器 ＋ 板色 ＋ 底纹 ＋ 间距（2026-09-27 重排）----
        //
        // 两件事一起做的：
        //   · 用户 2026-09-27："我现在要把更多里面的白板底纹，底纹间距这些设置移动到白板的
        //     展开色带里面" → 抽屉那两行删掉、搬到这里（**引擎接口与偏好键没动，存档格式不变**）；
        //   · 同一天还说了"上下翻页和页码应该挨着" → 两件翻页和「第 N 屏」合成一个翻页器，
        //     摆在带子最左，不再被三个板色劈成两端。
        // ⚠ 这一段**按段种找段、不写死下标**：段序刚被重排过，写死下标会静默点到别的段上
        //   （那正是抽屉那边当年踩过的坑，见 `RowRectByLabelForTest` 的注释）。
        {
            Host.Commands.SetBoard(false);                 // 先关板，等下"点那一格"把它打开
            Host.Commands.SetBoardPattern(0, 40f);
            SettleFrames(250);

            var bCell = ui.CellRectForTest(2);
            ClickPhysical((bCell.MinX + bCell.MaxX) * 0.5f * DpiScale,
                          (bCell.MinY + bCell.MaxY) * 0.5f * DpiScale);
            SettleFrames(300);

            int patSeg = ui.BoardSegIndexOfForTest("Pattern");
            int stepSeg = ui.BoardSegIndexOfForTest("Step");
            Check("白板色带上有「底纹」「间距」两段（从「更多」抽屉搬过来的）",
                  patSeg >= 0 && stepSeg >= 0 && BoardOn,
                  $"底纹第 {patSeg} 段、间距第 {stepSeg} 段（共 {ui.BandSegmentCountForTest} 段），板开 = {BoardOn}");

            // 翻页器：三件"挨着"——段序上连着，几何上也贴着
            int pgUpSeg = ui.BoardSegIndexOfForTest("PageUp");
            int pgLblSeg = ui.BoardSegIndexOfForTest("PageLabel");
            int pgDownSeg = ui.BoardSegIndexOfForTest("PageDown");
            var rUp = ui.SegmentRectForTest(pgUpSeg);
            var rLbl = ui.SegmentRectForTest(pgLblSeg);
            var rDown = ui.SegmentRectForTest(pgDownSeg);
            Check("翻页两件和「第 N 屏」挨着（‹ / 页码 / › 三件连着）",
                  pgLblSeg == pgUpSeg + 1 && pgDownSeg == pgLblSeg + 1
                  && rUp.MaxX <= rLbl.MinX + 0.6f && rLbl.MaxX <= rDown.MinX + 0.6f,
                  $"段序 {pgUpSeg}/{pgLblSeg}/{pgDownSeg}，两处缝 {rLbl.MinX - rUp.MaxX:F1} / {rDown.MinX - rLbl.MaxX:F1}");

            // 底纹：三档循环（无 → 方格 → 横线 → 无）
            var pr = ui.SegmentRectForTest(patSeg);
            ClickPhysical((pr.MinX + pr.MaxX) * 0.5f * DpiScale, (pr.MinY + pr.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("点色带上的「底纹」→ 方格",
                  Host.State.BoardPattern == 1, $"底纹 = {Host.State.BoardPattern}（1 = 方格）");

            pr = ui.SegmentRectForTest(patSeg);
            ClickPhysical((pr.MinX + pr.MaxX) * 0.5f * DpiScale, (pr.MinY + pr.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("再点一下 → 横线",
                  Host.State.BoardPattern == 2, $"底纹 = {Host.State.BoardPattern}（2 = 横线）");

            // 间距：**五档循环**（20 / 30 / 40 / 64 / 96）——用户 2026-09-27："需要多几档"
            float step0 = Host.State.BoardPatternStep;
            var sr = ui.SegmentRectForTest(stepSeg);
            ClickPhysical((sr.MinX + sr.MaxX) * 0.5f * DpiScale, (sr.MinY + sr.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("点色带上的「间距」→ 换下一档（五档循环）",
                  MathF.Abs(Host.State.BoardPatternStep - step0) > 1f,
                  $"{step0:F0} → {Host.State.BoardPatternStep:F0}");

            // 板没开时点这两格：改了**顺手把板打开**——底纹只画在板面上，不打开就等于改了看不见
            //（这条原来是靠"白板没开就把那两行压暗"来守的，搬进色带之后换成更好用的做法）。
            Host.Commands.SetBoard(false);
            SettleFrames(250);
            int patBefore = Host.State.BoardPattern;
            pr = ui.SegmentRectForTest(patSeg);
            ClickPhysical((pr.MinX + pr.MaxX) * 0.5f * DpiScale, (pr.MinY + pr.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("板没开时点「底纹」：改了顺带把板打开",
                  Host.State.BoardPattern != patBefore && BoardOn,
                  $"底纹 {patBefore} → {Host.State.BoardPattern}，板开 = {BoardOn}");

            // **每一段都不许越出带子**：本轮顺带修掉的老 bug 就是"5 段写死 70 宽把色带撑爆"
            //（极简档那条带子只有 315 宽）。这条断言就是那个 bug 的哨兵。
            bool fit = true; string why = "";
            {
                var bd = ui.BandRectForTest;
                for (int k = 0; k < ui.BandSegmentCountForTest; k++)
                {
                    var segR = ui.SegmentRectForTest(k);
                    if (segR.MaxX > bd.MaxX - 15f)
                    {
                        fit = false;
                        why = $"第 {k} 段的右沿 {segR.MaxX:F0} 越过了带子右沿 {bd.MaxX - 15f:F0}";
                        break;
                    }
                }
            }
            Check("完整档：白板色带每一段都在带子里", fit, why.Length == 0 ? "最右一段也没越界" : why);

            // 「更多」抽屉里**不该再有**那两行——防"挪了没删"（那样两处都能改，用户会以为是两个开关）。
            // 口径和「坐标系网格」那次一样：**按标签找，找不到 = 空矩形**。
            var moreMoved = ui.CellRectForTest(12);
            ClickPhysical((moreMoved.MinX + moreMoved.MaxX) * 0.5f * DpiScale,
                          (moreMoved.MinY + moreMoved.MaxY) * 0.5f * DpiScale);
            SettleFrames(300);
            Check("「更多」抽屉里已经没有「白板底纹」这一行",
                  ui.RowRectByLabelForTest("白板底纹").IsEmpty, "按标签找不到 = 已经删干净");
            Check("「更多」抽屉里已经没有「底纹间距」这一行",
                  ui.RowRectByLabelForTest("底纹间距").IsEmpty, "按标签找不到 = 已经删干净");
            var moreMoved2 = ui.CellRectForTest(12);
            ClickPhysical((moreMoved2.MinX + moreMoved2.MaxX) * 0.5f * DpiScale,
                          (moreMoved2.MinY + moreMoved2.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
        }

        // ---- ⑥.9 极简档：白板色带自动退到**紧凑布局** ----
        //
        // 用户 2026-09-27 定的口径："翻页不要，保留黑白色，底纹 间距"。
        // 极简档那条带子只有 315 宽（完整布局要 420 ＋ 滑条），所以这一格会退到紧凑布局。
        // 判据是 BoardCompactBand —— **真的量一下放不放得下**，不是写死"极简档"；
        // 所以"自定义档里把格子取消钉得只剩几格"也一样不会撑爆（那正是原来坏掉的根因）。
        {
            ui.SetProfileForTest(0);                        // 极简档（短胶囊）
            SettleFrames(350);
            var bCellMini = ui.CellRectForTest(2);
            ClickPhysical((bCellMini.MinX + bCellMini.MaxX) * 0.5f * DpiScale,
                          (bCellMini.MinY + bCellMini.MaxY) * 0.5f * DpiScale);
            SettleFrames(300);

            Check("极简档：白板色带退到紧凑布局（翻页那两件不放）",
                  ui.BoardCompactBandForTest && ui.BoardSegIndexOfForTest("PageUp") < 0
                  && ui.BoardSegIndexOfForTest("PageLabel") < 0,
                  $"紧凑 = {ui.BoardCompactBandForTest}，段数 {ui.BandSegmentCountForTest}");
            Check("极简档：板色三个 ＋ 底纹 ＋ 间距都还在",
                  ui.BoardSegIndexOfForTest("Color0") >= 0 && ui.BoardSegIndexOfForTest("Color1") >= 0
                  && ui.BoardSegIndexOfForTest("Color2") >= 0
                  && ui.BoardSegIndexOfForTest("Pattern") >= 0 && ui.BoardSegIndexOfForTest("Step") >= 0,
                  $"段数 {ui.BandSegmentCountForTest}");

            bool fitMini = true; string whyMini = "";
            {
                var bd = ui.BandRectForTest;
                for (int k = 0; k < ui.BandSegmentCountForTest; k++)
                {
                    var segR = ui.SegmentRectForTest(k);
                    if (segR.MaxX > bd.MaxX - 15f)
                    {
                        fitMini = false;
                        whyMini = $"第 {k} 段的右沿 {segR.MaxX:F0} 越过了带子右沿 {bd.MaxX - 15f:F0}";
                        break;
                    }
                }
            }
            Check("极简档：白板色带每一段都在带子里（原来就是这儿撑爆的）",
                  fitMini, whyMini.Length == 0 ? "最右一段也没越界" : whyMini);

            // 关板入口**不许随档位消失**：极简档也得有那个 ✕（否则这一档就关不掉白板了）
            var arMini = ui.ActionRectForTest;
            Check("极简档：最右端那个「关闭白板」✕ 也在",
                  !arMini.IsEmpty, $"按钮矩形 {arMini.MinX:F0},{arMini.MinY:F0}-{arMini.MaxX:F0},{arMini.MaxY:F0}");

            // 布局换了、行为不能变：极简档里点底纹照样换档
            int patSegMini = ui.BoardSegIndexOfForTest("Pattern");
            var prM = ui.SegmentRectForTest(patSegMini);
            int patBeforeM = Host.State.BoardPattern;
            ClickPhysical((prM.MinX + prM.MaxX) * 0.5f * DpiScale, (prM.MinY + prM.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("极简档：点色带上的「底纹」照样换档",
                  Host.State.BoardPattern != patBeforeM,
                  $"{patBeforeM} → {Host.State.BoardPattern}");

            ui.SetProfileForTest(2);                        // 回完整档
            SettleFrames(350);
            Host.Commands.SetBoardPattern(0, 40f);          // 收尾：回到"无底纹"
            // **收尾要把指针挪回主条**：色带只在指针落在面板上时才张开，指针不动就永远不张开，
            // 后面那几条"点分段"的用例就会全部点空（当年就是这么红的）。
            var barBack = ui.BarRectForTest;
            SendMouse((int)((barBack.MinX + barBack.MaxX) * 0.5f * DpiScale),
                      (int)((barBack.MinY + barBack.MaxY) * 0.5f * DpiScale), 0);
            SettleFrames(400);
        }

        // ---- ⑥.10 白板格：**点三下是一个来回**（用户 2026-09-27 第三次定）----
        //
        // 用户的三条原话就是规则本身：
        //   "1. 如果第一遍打开，白板是开启的；2. 开启后，如果此时色带不在白板上，
        //    再点击一下，色带就会来到白板；3. 再点击一下，白板就关掉。"
        // 还加了一句"单击切换上面的白板颜色，我感觉不需要了"——所以原来"第三下换板色"
        // 那条**删掉了**，第三下改成关板（`CycleBoardColor` 整个函数已删）。
        //
        // 下面按 ①②③④ 逐下点过去，验的就是这个闭环；**板色一下都不许变**。
        {
            // 起手先把色带落到「笔」那一格（产品里就是点一下笔格）
            var penCellA = ui.CellRectForTest(3);
            ClickPhysical((penCellA.MinX + penCellA.MaxX) * 0.5f * DpiScale,
                          (penCellA.MinY + penCellA.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Host.Commands.SetBoard(false);
            Host.Commands.SetBoardColor(InkPalette.BoardPresets[0].Color);   // 白板：好看出"这一下没换色"
            SettleFrames(300);

            bool SameBoard(Color4 a, Color4 b) =>
                MathF.Abs(a.R - b.R) < 0.02f && MathF.Abs(a.G - b.G) < 0.02f
                && MathF.Abs(a.B - b.B) < 0.02f;
            void ClickBoardCell()
            {
                var c = ui.CellRectForTest(2);
                ClickPhysical((c.MinX + c.MaxX) * 0.5f * DpiScale,
                              (c.MinY + c.MaxY) * 0.5f * DpiScale);
                SettleFrames(300);
            }

            // ① 板关着 → 开板 ＋ 色带切过来（**不换色**）
            ClickBoardCell();
            Check("① 板关着时点白板格：开板 ＋ 色带切到白板（不换色）",
                  BoardOn && ui.BandCellForTest == 2
                  && SameBoard(Host.State.BoardColor, InkPalette.BoardPresets[0].Color),
                  $"板开 = {BoardOn}，色带在第 {ui.BandCellForTest} 格（2 = 白板），板色 = {Host.State.BoardColor}");

            // 回到"用笔写字"这个常态：点笔格把色带拿回去（板**保持开着**）
            var penCell2 = ui.CellRectForTest(3);
            ClickPhysical((penCell2.MinX + penCell2.MaxX) * 0.5f * DpiScale,
                          (penCell2.MinY + penCell2.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("（前提）点笔格：色带回到笔那一格，板还是开着的",
                  ui.BandCellForTest == 3 && BoardOn,
                  $"色带在第 {ui.BandCellForTest} 格（3 = 笔），板开 = {BoardOn}");

            // ② 板开着、色带在笔 → 只把色带拿过来，板一动不动
            ClickBoardCell();
            Check("② 板开着时点白板格：只把色带切过来，**板一动不动**",
                  BoardOn && ui.BandCellForTest == 2,
                  $"板开 = {BoardOn}（必须还是 True），色带在第 {ui.BandCellForTest} 格");

            // ③ 色带已经在白板格 → **关板**（这一下原来是"换个板色"，用户不要了）
            ClickBoardCell();
            Check("③ 色带就在这一格时再点：**白板关掉**（不再是换板色）",
                  !BoardOn && ui.BandCellForTest == 2,
                  $"板开 = {BoardOn}（期望 False），色带在第 {ui.BandCellForTest} 格");

            // ④ 再点一下 → 又开板（三下之后循环，不会卡在"关着点不动"）
            ClickBoardCell();
            Check("④ 关着再点：又开板（这三下是循环的）", BoardOn, $"板开 = {BoardOn}");

            // 全程**板色一点没变**（用户明确不要"单击换板色"了）
            Check("全程板色没被动过（单击不再换色）",
                  SameBoard(Host.State.BoardColor, InkPalette.BoardPresets[0].Color),
                  $"板色 = {Host.State.BoardColor}");

            // ---- 设置条最右端那个 ✕ 仍然在（一眼看得见的关板键）----
            var ar = ui.ActionRectForTest;
            Check("白板设置条上有关闭按钮（最右端，和橡皮「清空」同一个位置）",
                  !ar.IsEmpty, $"按钮矩形 {ar.MinX:F0},{ar.MinY:F0}-{ar.MaxX:F0},{ar.MaxY:F0}");

            ClickPhysical((ar.MinX + ar.MaxX) * 0.5f * DpiScale,
                          (ar.MinY + ar.MaxY) * 0.5f * DpiScale);
            SettleFrames(300);
            Check("点色带上那个 ✕ → 白板关掉", !BoardOn, $"板开 = {BoardOn}");

            // 板已经关着时，那个 ✕ 是压暗的、点了也不动（关了没意义）
            var ar2 = ui.ActionRectForTest;
            ClickPhysical((ar2.MinX + ar2.MaxX) * 0.5f * DpiScale,
                          (ar2.MinY + ar2.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("板已经关着时点 ✕：什么都不发生（还是关着）",
                  !BoardOn, $"板开 = {BoardOn}");

            Host.Commands.SetBoard(false);
            SettleFrames(200);
        }

        // ---- ⑥.11 笔 / 荧光笔：**已经是它了，再点一下换下一个颜色**（用户 2026-09-27 定）----
        //
        // 同一天还定了另一件事，在这里一起验：**荧光笔用自己的一张亮色表**
        //（不再和笔共用一套色相——那样能选到"黑/灰"，画出来只是一道灰道道）。
        {
            // "两个颜色算同一个"——口径和 FullUi.SameColor 一致（阈值 0.02）
            bool SameCol(Color4 a, Color4 b) =>
                MathF.Abs(a.R - b.R) < 0.02f && MathF.Abs(a.G - b.G) < 0.02f
                && MathF.Abs(a.B - b.B) < 0.02f;

            var penPal = InkUi.Tokens.Palette;                 // 笔那张（12 个）
            var hlPal = InkUi.Tokens.HighlighterPalette;       // 荧光笔那张（5 个）

            // 起手：把色带挪到别格（点橡皮），再把笔色设成新表第 1 个（黑）
            var offCell = ui.CellRectForTest(6);
            ClickPhysical((offCell.MinX + offCell.MaxX) * 0.5f * DpiScale,
                          (offCell.MinY + offCell.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Host.Commands.SetColor(penPal[0].Color);
            SettleFrames(200);

            // 这一下**只把色带拿过来，不换色**（"把笔拿回来"不能被悄悄换色）
            var penC1 = ui.CellRectForTest(3);
            ClickPhysical((penC1.MinX + penC1.MaxX) * 0.5f * DpiScale,
                          (penC1.MinY + penC1.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("色带不在笔格时点笔格：色带过来、**颜色不动**",
                  ui.BandCellForTest == 3 && SameCol(Host.State.PaletteBase, penPal[0].Color),
                  $"色带在第 {ui.BandCellForTest} 格（应是 3），颜色 {Host.State.PaletteBase}");

            // 现在色带已经在笔格了 —— 再点一下 = 换下一个颜色（黑 → 红）
            var penC2 = ui.CellRectForTest(3);
            ClickPhysical((penC2.MinX + penC2.MaxX) * 0.5f * DpiScale,
                          (penC2.MinY + penC2.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("已经是笔、再点一下：换到下一个颜色（黑 → 红）",
                  SameCol(Host.State.PaletteBase, penPal[1].Color),
                  $"期望 {penPal[1].Name}，实际 {Host.State.PaletteBase}");

            // 再点一下 → 蓝（第 3 个）：连点就是顺着色片表往下走
            var penC3 = ui.CellRectForTest(3);
            ClickPhysical((penC3.MinX + penC3.MaxX) * 0.5f * DpiScale,
                          (penC3.MinY + penC3.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("再点一下（红 → 蓝）：顺序 = 色片表的顺序",
                  SameCol(Host.State.PaletteBase, penPal[2].Color),
                  $"期望 {penPal[2].Name}，实际 {Host.State.PaletteBase}");

            // 环回：先把色设成**最后一个**（藏青），点一下应该绕回第 1 个（黑）
            Host.Commands.SetColor(penPal[penPal.Length - 1].Color);
            SettleFrames(200);
            var penC4 = ui.CellRectForTest(3);
            ClickPhysical((penC4.MinX + penC4.MaxX) * 0.5f * DpiScale,
                          (penC4.MinY + penC4.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("走到最后一个再点：环回第 1 个（藏青 → 黑）",
                  SameCol(Host.State.PaletteBase, penPal[0].Color),
                  $"期望 {penPal[0].Name}，实际 {Host.State.PaletteBase}");

            // ---- 荧光笔：独立的那张亮色表 ----
            var keepPen = Host.State.PaletteBase;              // 记下笔色，等下要比

            var hlC1 = ui.CellRectForTest(4);
            ClickPhysical((hlC1.MinX + hlC1.MaxX) * 0.5f * DpiScale,
                          (hlC1.MinY + hlC1.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("切到荧光笔：色片换成那张亮色表（5 个）",
                  ui.BandCellForTest == 4 && ui.SwatchCountForTest == hlPal.Length,
                  $"色片数 {ui.SwatchCountForTest}（笔那张是 {penPal.Length}）");
            Check("荧光笔当前色 = 第一个色片「荧光黄」（和引擎默认色对得上）",
                  SameCol(Host.State.PaletteBase, hlPal[0].Color),
                  $"期望 {hlPal[0].Name}，实际 {Host.State.PaletteBase}");

            // 荧光笔也支持"再点一下换色"
            var hlC2 = ui.CellRectForTest(4);
            ClickPhysical((hlC2.MinX + hlC2.MaxX) * 0.5f * DpiScale,
                          (hlC2.MinY + hlC2.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("荧光笔再点一下：换到下一个（荧光黄 → 荧光绿）",
                  SameCol(Host.State.PaletteBase, hlPal[1].Color),
                  $"期望 {hlPal[1].Name}，实际 {Host.State.PaletteBase}");

            // 换荧光笔的颜色**不许带着笔的颜色一起变**（两套色各记各的）
            var backPen = ui.CellRectForTest(3);
            ClickPhysical((backPen.MinX + backPen.MaxX) * 0.5f * DpiScale,
                          (backPen.MinY + backPen.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("换荧光笔的颜色**不影响笔的颜色**（两套各记各的）",
                  ui.BandCellForTest == 3 && SameCol(Host.State.PaletteBase, keepPen),
                  $"笔色应还是 {Host.State.PaletteBase}，色带在第 {ui.BandCellForTest} 格");

            Host.Commands.SetTool(Tool.Pen);
            Host.Commands.SetColor(InkPalette.PenDefault);     // 收尾：回到默认红
            SettleFrames(200);
        }

        // ---- ⑥.12 选择格：**已经是它了，再点一下换下一档** ＋ **双击 = 全选**（用户 2026-09-27 定）----
        //
        // 和笔 / 荧光笔"再点一下换个颜色"是同一条规矩，只是这里换的是**选择方式**
        //（矩形框选 ←→ 自由套索，见 FullUi.CycleSelectMode）。
        //
        // 双击全选照的是 InkClass 那个"经典交互"（它那边 500ms 内双击选择图标 = 全选）。
        // 能跟"单击换档"共存**全靠只有两档**：连点两下正好转两圈回到原档，
        // 所以双击的净效果就是"全选、模式没动"——这一条也断言了（不然以后加第三档会静默出错）。
        {
            // "快击"：两次之间的间隔必须**真的**小于 500ms（`NowMs` 是真实秒表）。
            // 而 `ClickPhysical` 一次就要 460ms（80+60+320），两次相距 920ms —— 判不出双击。
            // 所以双击这件事得用这个 45ms 一发的版本（单发之间照旧用 ClickPhysical ＋ 补时间）。
            void ClickFast(float px, float py)
            {
                SendMouse((int)px, (int)py, 0);                           SettleFrames(15);
                SendMouse((int)px, (int)py, Native.MOUSEEVENTF_LEFTDOWN); SettleFrames(15);
                SendMouse((int)px, (int)py, Native.MOUSEEVENTF_LEFTUP);   SettleFrames(15);
            }

            // 摆两笔进去：全选才有的可"全"（断言写成"选中的条数 = 总条数"，
            // 不去假设这一刻文档里到底有几条——前面的用例画过东西）。
            Doc.Clear();
            Doc.ClearHistory();
            for (int k = 0; k < 2; k++)
            {
                var line = new Stroke
                {
                    Tool = Tool.Pen, Color = new Color4(0, 0, 0, 1), Width = 6f * DpiScale,
                };
                float ly = VirtualScreen.MinY + 300f + k * 120f;
                for (int i = 0; i <= 60; i++)
                    line.AddPoint(VirtualScreen.MinX + 300f + i * 4f, ly, 0.5f, i);
                Doc.AddStroke(line);
            }
            Doc.Selected.Clear();
            SettleFrames(250);

            var selCell = ui.CellRectForTest(7);
            float sxSel = (selCell.MinX + selCell.MaxX) * 0.5f * DpiScale;
            float sySel = (selCell.MinY + selCell.MaxY) * 0.5f * DpiScale;

            // 起手：色带在**笔**那一格（"从别的工具进来"这一种）
            ui.SelectBandCellForTest(3);
            Host.Commands.SetTool(Tool.Pen);
            SettleFrames(200);
            Host.Commands.SetSelectMode(SelectMode.Rect);
            SettleFrames(200);

            // 第一下：从别的工具进来 → 只切工具，**不换档**
            ClickPhysical(sxSel, sySel);
            SettleFrames(400);                       // 把和下一击的间隔拉过 500ms（别被当成双击）
            Check("选择格第一下（从别的工具进来）：只切到选择工具，**档位不动**",
                  Host.State.Tool == Tool.Marquee && Host.State.SelectMode == SelectMode.Rect,
                  $"工具 {Host.State.Tool}，档 {Host.State.SelectMode}（期望 Rect）");

            // 第二下：已经是它了、色带也在这一格 → 换下一档（矩形 → 套索）
            ClickPhysical(sxSel, sySel);
            SettleFrames(400);
            Check("已经是选择工具、再点一下：换到下一档（矩形 → 套索）",
                  Host.State.SelectMode == SelectMode.Lasso,
                  $"档 {Host.State.SelectMode}（期望 Lasso）");

            // 第三下：再换一次 → 转回矩形（两档循环）
            ClickPhysical(sxSel, sySel);
            SettleFrames(400);
            Check("再点一下：两档循环转回矩形",
                  Host.State.SelectMode == SelectMode.Rect,
                  $"档 {Host.State.SelectMode}（期望 Rect）");

            // ---- 双击 = 全选 ----
            var modeBeforeDbl = Host.State.SelectMode;
            int strokeCount = Doc.Strokes.Count;
            ClickFast(sxSel, sySel);
            ClickFast(sxSel, sySel);
            SettleFrames(300);
            Check("双击选择格 = **全选**",
                  strokeCount > 0 && Doc.Selected.Count == strokeCount,
                  $"选中 {Doc.Selected.Count} / 共 {strokeCount} 条");

            // ⚠ 这一条是"双击和单击换档不打架"的守门人：连点两下必须**回到原档**。
            // 哪天选择方式加到三档，这条会当场红（那时得重新决定双击还要不要）。
            Check("双击全选**不动档位**（连点两下正好转两圈回到原档）",
                  Host.State.SelectMode == modeBeforeDbl,
                  $"档 {modeBeforeDbl} → {Host.State.SelectMode}（期望没变）");

            // 边界：**中间点了别的格子，双击序列要断掉**。
            // 三下挨得再近也不能算"对选择格的双击"——不这么守的话，
            // 老师只是在"选择格 / 笔格"之间来回看一眼，就被全选了。
            Doc.Selected.Clear();
            SettleFrames(150);
            ClickFast(sxSel, sySel);                                   // 选择格（第 1 下）
            var penCellDbl = ui.CellRectForTest(3);
            ClickFast((penCellDbl.MinX + penCellDbl.MaxX) * 0.5f * DpiScale,
                      (penCellDbl.MinY + penCellDbl.MaxY) * 0.5f * DpiScale);   // 摸一下笔格
            ClickFast(sxSel, sySel);                                   // 又回选择格
            SettleFrames(250);
            Check("中间点过别的格子 → 双击序列断掉（不会误全选）",
                  Doc.Selected.Count == 0, $"选中 {Doc.Selected.Count} 条（期望 0）");

            // 收尾：清掉选中、回到笔（选中态会叫出选中操作条，别带给后面的用例）
            Doc.Selected.Clear();
            Host.Commands.SetTool(Tool.Pen);
            SettleFrames(250);
        }

        // ---- ⑥.7 白板和穿透**互斥**（用户 2026-09-17 问："鼠标和白板是不是也应该互斥"）----
        //
        // 该互斥：白板是不透明的一层，穿透是"点击落到下层程序"——两个一起开着，
        // 老师看到的是白板、点到的却是白板下面那个看不见的窗口。
        {
            Host.Commands.SetBoard(true);
            SettleFrames(200);
            Host.Commands.SetPassThrough(true);
            SettleFrames(250);
            Check("开穿透 → 白板自动关掉",
                  !BoardOn && Host.State.PassThrough,
                  $"板开 = {BoardOn}，穿透 = {Host.State.PassThrough}");

            Host.Commands.SetBoard(true);
            SettleFrames(300);
            Check("开白板 → 穿透自动关掉",
                  BoardOn && !Host.State.PassThrough,
                  $"板开 = {BoardOn}，穿透 = {Host.State.PassThrough}");

            Host.Commands.SetBoard(false);
            Host.Commands.SetTool(Tool.Pen);
            SettleFrames(200);
        }

        // 换工具（走引擎那条路，等同按热键）：上带要跟着换成"选择"的设置条
        Host.Commands.SetTool(Tool.Marquee);
        SettleFrames(150);
        var lasso = ui.SegmentRectForTest(1);
        ClickPhysical((lasso.MinX + lasso.MaxX) * 0.5f * DpiScale,
                      (lasso.MinY + lasso.MaxY) * 0.5f * DpiScale);
        Check("点分段切成套索", Host.State.SelectMode == SelectMode.Lasso,
              $"选择方式 = {Host.State.SelectMode}（上带跟着工具换成选择才点得到）");

        Host.Commands.SetTool(Tool.Pen);
        SettleFrames(150);
        var boardCell2 = ui.CellRectForTest(2);
        ClickPhysical((boardCell2.MinX + boardCell2.MaxX) * 0.5f * DpiScale,
                      (boardCell2.MinY + boardCell2.MaxY) * 0.5f * DpiScale);
        SettleFrames(150);
        // 白板那一格的段序**2026-09-27 重排过**（现在是 `[‹] 第 N 屏 [›] [白][绿][黑] [底纹][间距]`），
        // 所以这里**按段种找段**，不写死下标——写死的话下次重排又会静默点到别的段上
        //（这一条自检第一版就是按老的三段布局点下标 1，点到了"白板"，被判成失败）。
        var green = ui.SegmentRectForTest(ui.BoardSegIndexOfForTest("Color1"));
        ClickPhysical((green.MinX + green.MaxX) * 0.5f * DpiScale,
                      (green.MinY + green.MaxY) * 0.5f * DpiScale);
        var wantBoard = InkPalette.BoardPresets[1].Color;
        var gotBoard = Host.State.BoardColor;
        Check("点板色换成绿板",
              BoardOn && MathF.Abs(wantBoard.R - gotBoard.R) < 0.02f
              && MathF.Abs(wantBoard.G - gotBoard.G) < 0.02f
              && MathF.Abs(wantBoard.B - gotBoard.B) < 0.02f,
              $"板开 = {BoardOn}，板色 ({gotBoard.R:F2},{gotBoard.G:F2},{gotBoard.B:F2})");

        // ---- ⑥.1 白板那一格的滑条 = **板面不透明度**（用户 2026-09-17 要的）----
        {
            float penW = PenWidthLogical;
            var slB = ui.SliderRectForTest;
            float slBy = (slB.MinY + slB.MaxY) * 0.5f * DpiScale;
            var (bl, _) = ui.SliderTrackRangeForTest;

            SendMouse((int)(bl * DpiScale), (int)slBy, 0);                            SettleFrames(60);
            SendMouse((int)(bl * DpiScale), (int)slBy, Native.MOUSEEVENTF_LEFTDOWN);   SettleFrames(50);
            SendMouse((int)(bl * DpiScale), (int)slBy, 0);                            SettleFrames(120);
            SendMouse((int)(bl * DpiScale), (int)slBy, Native.MOUSEEVENTF_LEFTUP);     SettleFrames(150);
            Check("白板滑条拖到最左 = 最透（0.35）",
                  MathF.Abs(Host.State.BoardOpacity - 0.35f) < 0.02f,
                  $"不透明度 {Host.State.BoardOpacity:F2}");

            var (_, br2) = ui.SliderTrackRangeForTest;
            SendMouse((int)(br2 * DpiScale), (int)slBy, 0);                            SettleFrames(60);
            SendMouse((int)(br2 * DpiScale), (int)slBy, Native.MOUSEEVENTF_LEFTDOWN);   SettleFrames(50);
            SendMouse((int)(br2 * DpiScale), (int)slBy, 0);                            SettleFrames(120);
            SendMouse((int)(br2 * DpiScale), (int)slBy, Native.MOUSEEVENTF_LEFTUP);     SettleFrames(150);
            Check("白板滑条拖到最右 = 实心（1.0）",
                  MathF.Abs(Host.State.BoardOpacity - 1f) < 0.02f,
                  $"不透明度 {Host.State.BoardOpacity:F2}");
            Check("拖白板滑条**不动笔宽**（和橡皮那条一个坑）",
                  MathF.Abs(PenWidthLogical - penW) < 0.01f,
                  $"笔宽 {penW:F2} → {PenWidthLogical:F2}");
        }

        // ---- ⑥.5 白板翻页：上带上的 [‹] / [›] ----
        // 屏幕高必须是"整数屏"的底数：跑到第一屏（相机偏移 = 0）再往下翻。
        // 段序**按段种找**（2026-09-27 重排过：现在是 `[‹] 第 N 屏 [›] [白][绿][黑] [底纹][间距]`）。
        var upSeg = ui.SegmentRectForTest(ui.BoardSegIndexOfForTest("PageUp"));
        float upX = (upSeg.MinX + upSeg.MaxX) * 0.5f * DpiScale;
        float upY = (upSeg.MinY + upSeg.MaxY) * 0.5f * DpiScale;
        var downSeg = ui.SegmentRectForTest(ui.BoardSegIndexOfForTest("PageDown"));
        float downX = (downSeg.MinX + downSeg.MaxX) * 0.5f * DpiScale;
        float downY = (downSeg.MinY + downSeg.MaxY) * 0.5f * DpiScale;
        float camHome = ViewOffsetY;

        // 已经在最上面：点"上一屏"不该动（按钮也该是压暗的）
        Check("到顶时「上一屏」不可用", !Host.State.CanFlipPageUp,
              $"相机 {camHome:F0}，还能上翻 = {Host.State.CanFlipPageUp}");
        ClickPhysical(upX, upY);
        SettleFrames(400);
        Check("到顶时点「上一屏」相机不动",
              MathF.Abs(ViewOffsetY - camHome) < 1f,
              $"相机 {camHome:F0} → {ViewOffsetY:F0}");

        ClickPhysical(downX, downY);
        SettleFrames(400);
        Check("点「下一屏」翻到第 2 屏",
              Host.State.ScreenIndex == 2 && ViewOffsetY < -1f,
              $"屏号 {Host.State.ScreenIndex}，相机 {ViewOffsetY:F0}");

        ClickPhysical(downX, downY);
        SettleFrames(400);
        Check("再点一次翻到第 3 屏（下面永远还有一屏）",
              Host.State.ScreenIndex == 3, $"屏号 {Host.State.ScreenIndex}");

        ClickPhysical(upX, upY);
        SettleFrames(400);
        Check("点「上一屏」回到第 2 屏",
              Host.State.ScreenIndex == 2 && Host.State.CanFlipPageUp,
              $"屏号 {Host.State.ScreenIndex}，还能上翻 = {Host.State.CanFlipPageUp}");

        // 收尾：把相机送回第一屏，别把后面的用例带偏（后面的用例都假设相机为 0）
        while (Host.State.CanFlipPageUp)
        {
            ClickPhysical(upX, upY);
            SettleFrames(300);
        }
        Check("翻回第一屏（相机归零）", Math.Abs(ViewOffsetY) < 1f,
              $"相机 {ViewOffsetY:F1}");

        // ---- ⑥.6 放映时白板那一格**仍然只管白板**（用户 2026-09-26 更正：
        //      "取消掉白板区的翻页，白板区不需要 ppt 翻页"）。
        // 这是一条**负向断言**：放映中点两端，命令一条都不许跑到 PPT 上去
        //（PPT 的翻页入口只有底部那两条，见 `--ppttest` ⑧.5）。----
        var pptFake = new PptFakeSource { Showing = true, Slide = 1, SlideId = 101, Total = 5 };

        // ---- ⑥.5 进放映那一刻：面板**自动展开 ＋ 回到默认位置**（用户 2026-09-27 定）----
        //
        // 用户原话："PPT 开始播放以后，把它打开放到居中靠底部。"
        // 先人为破坏一下前提（收成球 + 拖到左上角），再进放映——**两条都得被掰回来**。
        //
        // ⚠ 归位目标就是上面 ⑥ 那一段算坐标时所在的**默认位置**，所以 `downX/downY/upX/upY`
        //   （放映中按白板格翻页那几个点）在这之后仍然有效——不是巧合，是同一个 `RawAnchor`。
        ui.SetExpandForTest(0f);
        ui.SetAnchorForTest(new Vector2(work.MinX + 40f, work.MinY + 40f));
        SettleFrames(250);
        Check("（前提）面板已被收成球、并拖到左上角",
              !ui.ExpandedForTest && ui.QueryBounds().MinY < work.MinY + 80f,
              $"展开 = {ui.ExpandedForTest}，占用顶 {ui.QueryBounds().MinY:F0}");

        AttachPptSource(pptFake, watch: false);
        StepPpt();
        SettleFrames(300);
        Check("进放映：引擎进入 PPT 模式", PptMode && PptTotal == 5,
              $"PptMode={PptMode}，{PptSlide}/{PptTotal} 页");

        {
            var pb = ui.BarRectForTest;
            Check("进放映：面板**自动展开**（一放片笔就出来）",
                  ui.ExpandedForTest, $"展开 = {ui.ExpandedForTest}");
            Check("进放映：位置**归到工作区底边居中**（拖走过的也掰回来）",
                  MathF.Abs(pb.MaxY - (work.MaxY - InkUi.Tokens.EdgeMargin)) < 1.5f
                  && MathF.Abs((pb.MinX + pb.MaxX) * 0.5f - (work.MinX + work.MaxX) * 0.5f) < 2f,
                  $"条底 {pb.MaxY:F0}（应 {work.MaxY - InkUi.Tokens.EdgeMargin:F0}），"
                  + $"带子中心 {(pb.MinX + pb.MaxX) * 0.5f:F0}"
                  + $"（应 {(work.MinX + work.MaxX) * 0.5f:F0}）");
        }

        // ⚠ 上面那次"收成球再展开"会**把色带一起收掉**：收起时 `_railHover` 被清成 false
        //   （见 UpdateRail），而它**只在指针事件里**重算。不重新碰一下的话，下面 ⑥.6 那几刀
        //   （点「下一屏」/「上一屏」）会点在一条已经收起来的色带上——坐标是对的、东西不在那，
        //   表现是"点了没反应"（自检当场抓到：屏号还是 1、相机还是 0）。
        //   这一段就是"把指针放回面板、等色带重新张开"，和别处恢复悬停用同一个套路。
        {
            var panelBack = ui.BarRectForTest;
            SendMouse((int)((panelBack.MinX + panelBack.MaxX) * 0.5f * DpiScale),
                      (int)((panelBack.MinY + panelBack.MaxY) * 0.5f * DpiScale), 0);
            SettleFrames(500);          // 悬停意图 120ms + 色带张开 RailMs
            Check("（准备）指针回面板后色带重新张开（不然下面点空）",
                  !ui.BandRectForTest.IsEmpty, $"色带 {(ui.BandRectForTest.IsEmpty ? "没张开" : "已张开")}");
        }

        float camBeforePpt = ViewOffsetY;
        ClickPhysical(downX, downY);                   // 白板格的「下一屏」
        SettleFrames(400);
        Check("放映中点「下一屏」：翻的是白板、**一条命令都不给 PPT**",
              pptFake.NextCalls == 0 && Host.State.ScreenIndex == 2
              && MathF.Abs(ViewOffsetY - camBeforePpt) > 1f,
              $"NextCalls={pptFake.NextCalls}，屏号 {Host.State.ScreenIndex}，相机 {ViewOffsetY:F0}");

        ClickPhysical(upX, upY);                       // 白板格的「上一屏」
        SettleFrames(400);
        Check("放映中点「上一屏」：回到第 1 屏，也不给 PPT",
              pptFake.PrevCalls == 0 && Host.State.ScreenIndex == 1,
              $"PrevCalls={pptFake.PrevCalls}，屏号 {Host.State.ScreenIndex}");

        pptFake.Showing = false;                       // 退出放映
        StepPpt();
        SettleFrames(200);
        Check("退出放映：退出 PPT 模式", !PptMode, $"PptMode={PptMode}");

        Host.Commands.SetBoard(false);
        Host.Commands.SetBoardColor(InkPalette.BoardPresets[0].Color);
        SettleFrames(150);

        // ---- ⑦ 「更多」抽屉：开合、深色主题、贴边隐藏 ----
        var moreCell = ui.CellRectForTest(12);
        ClickPhysical((moreCell.MinX + moreCell.MaxX) * 0.5f * DpiScale,
                      (moreCell.MinY + moreCell.MaxY) * 0.5f * DpiScale);
        SettleFrames(150);
        var drawer = ui.DrawerRectForTest;
        Check("点「更多」开出抽屉", ui.DrawerOpenForTest,
              $"抽屉 ({drawer.MinX:F0},{drawer.MinY:F0})-({drawer.MaxX:F0},{drawer.MaxY:F0})");
        Check("抽屉在面板上方、且在屏幕内",
              ui.DrawerOpenForTest && drawer.MaxY <= ui.BarRectForTest.MinY - 2f
              && drawer.MinY >= _virtualY / DpiScale && drawer.MaxX <= _virtualX / DpiScale + _virtualW / DpiScale,
              $"抽屉底 {drawer.MinY:F0}+{drawer.MaxY - drawer.MinY:F0}，主条顶 {ui.BarRectForTest.MinY:F0}");

        // 抽屉和设置条**互斥**（2026-09-17）：两者只隔 16 像素，抽屉开着的时候设置条
        // 要是被指针挤出来，会从抽屉底下冒一截，很难看（假面板里也是这么让位的）。
        // 顺带守住老规矩：**抽屉的位置不许跟着设置条的高低走**——
        // 跟着走就是"鼠标一碰色带、抽屉往上跳一下"（用户说的"起伏"）。
        var lineRect = ui.BandRectForTest;             // 这一刻是那条色线
        SendMouse((int)((lineRect.MinX + lineRect.MaxX) * 0.5f * DpiScale),
                  (int)((lineRect.MinY + lineRect.MaxY) * 0.5f * DpiScale), 0);
        SettleFrames(400);                              // 等过"该张开"的那段时间
        var drawerAfter = ui.DrawerRectForTest;
        Check("抽屉开着时设置条让位（不挤出来、也不推抽屉）",
              !ui.RailOpenForTest
              && MathF.Abs(ui.BandHeightForTest - InkUi.Tokens.BandLine) < 1.5f
              && MathF.Abs(drawerAfter.MinY - drawer.MinY) < 1.5f,
              $"设置条高 {ui.BandHeightForTest:F0}（该是色线 {InkUi.Tokens.BandLine:F0}），"
              + $"抽屉底 {drawer.MinY:F0} → {drawerAfter.MinY:F0}");

        var darkRow = ui.RowRectForTest(0);
        ClickPhysical((darkRow.MinX + darkRow.MaxX) * 0.5f * DpiScale,
                      (darkRow.MinY + darkRow.MaxY) * 0.5f * DpiScale);
        Check("点「深色主题」切换", ui.DarkForTest, $"深色 = {ui.DarkForTest}");

        var hideRow = ui.RowRectForTest(1);
        ClickPhysical((hideRow.MinX + hideRow.MaxX) * 0.5f * DpiScale,
                      (hideRow.MinY + hideRow.MaxY) * 0.5f * DpiScale);
        Check("点「贴边隐藏」打开", ui.HideEnabledForTest, $"开关 = {ui.HideEnabledForTest}");

        // 关掉抽屉（点「更多」再点一下），然后把指针移到画布上：
        // 贴边状态下应该收成一条 8 像素的"露头"，悬停露头再长回来。
        ClickPhysical((moreCell.MinX + moreCell.MaxX) * 0.5f * DpiScale,
                      (moreCell.MinY + moreCell.MaxY) * 0.5f * DpiScale);
        SendMouse((int)(_virtualX + _virtualW * 0.5f), (int)(_virtualY + _virtualH * 0.4f), 0);
        // 等过"离开 700 毫秒才收"＋收起动画那一段（167 毫秒）：留足余量，别把动画
        // 中间态当成终态来判——第一版就是这么误判成"露头 56 像素"的。
        SettleFrames(2000);
        var peeked = ui.QueryBounds();
        Check("贴边隐藏收成露头",
              (peeked.MaxY - peeked.MinY) < 12f || (peeked.MaxX - peeked.MinX) < 12f,
              $"占用 {peeked.MaxX - peeked.MinX:F0}×{peeked.MaxY - peeked.MinY:F0}（应只剩露头那条）");

        SendMouse((int)((peeked.MinX + peeked.MaxX) * 0.5f * DpiScale),
                  (int)((peeked.MinY + peeked.MaxY) * 0.5f * DpiScale), 0);
        SettleFrames(500);
        var back = ui.QueryBounds();
        Check("碰一下露头就长回来", (back.MaxX - back.MinX) > 100f,
              $"占用 {back.MaxX - back.MinX:F0}×{back.MaxY - back.MinY:F0}");

        // 关掉贴边隐藏，免得影响后面的用例
        var moreCell2 = ui.CellRectForTest(12);
        ClickPhysical((moreCell2.MinX + moreCell2.MaxX) * 0.5f * DpiScale,
                      (moreCell2.MinY + moreCell2.MaxY) * 0.5f * DpiScale);
        SettleFrames(150);
        var hideRow2 = ui.RowRectForTest(1);
        ClickPhysical((hideRow2.MinX + hideRow2.MaxX) * 0.5f * DpiScale,
                      (hideRow2.MinY + hideRow2.MaxY) * 0.5f * DpiScale);
        ClickPhysical((moreCell2.MinX + moreCell2.MaxX) * 0.5f * DpiScale,
                      (moreCell2.MinY + moreCell2.MaxY) * 0.5f * DpiScale);
        SettleFrames(250);
        Check("关掉贴边隐藏", !ui.HideEnabledForTest, $"开关 = {ui.HideEnabledForTest}");

        // ---- ⑦.5 界面档位与钉住 ----
        var moreCell4 = ui.CellRectForTest(12);
        ClickPhysical((moreCell4.MinX + moreCell4.MaxX) * 0.5f * DpiScale,
                      (moreCell4.MinY + moreCell4.MaxY) * 0.5f * DpiScale);   // 开抽屉
        SettleFrames(200);

        Check("完整档是 13 格", ui.VisibleCountForTest == 13, $"显示 {ui.VisibleCountForTest} 格");

        // 极简档的色片行：**只给 4 个**（用户 2026-09-17："极简模式的色带展开栏里面的
        // 内容排布有点问题"——短胶囊里塞 12 个色片，减掉滑条之后每个只有 11 像素宽）。
        {
            var miniSeg0 = ui.ProfileRectForTest(0);
            ClickPhysical((miniSeg0.MinX + miniSeg0.MaxX) * 0.5f * DpiScale,
                          (miniSeg0.MinY + miniSeg0.MaxY) * 0.5f * DpiScale);   // 切极简
            SettleFrames(250);
            ui.SelectBandCellForTest(3);                                     // 笔的设置条
            SettleFrames(150);
            Check("极简档：色片只有 4 个", ui.SwatchCountForTest == 4,
                  $"色片数 {ui.SwatchCountForTest}");
            var sw0 = ui.SwatchRectForTest(0);
            Check("极简档：每个色片都够宽（≥ 30 逻辑像素，点得准）",
                  sw0.MaxX - sw0.MinX >= 30f, $"色片宽 {sw0.MaxX - sw0.MinX:F0}");
            // 极简档那条带子塞不下第三样东西（见 FullUi.BandHasDashToggle），
            // 所以那一格**不给**——色片优先。这条要验出来，不然以后谁把它加回去，
            // 色片会悄悄变窄、而"≥30"那条也会跟着红，两处却对不上因果。
            Check("极简档：没有虚实线那一格（挤不下，让位给色片）",
                  !ui.DashToggleVisibleForTest, $"可见 = {ui.DashToggleVisibleForTest}");
            // 切回完整档
            var fullSeg0 = ui.ProfileRectForTest(2);
            ClickPhysical((fullSeg0.MinX + fullSeg0.MaxX) * 0.5f * DpiScale,
                          (fullSeg0.MinY + fullSeg0.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("完整档：色片回到 12 个", ui.SwatchCountForTest == 12,
                  $"色片数 {ui.SwatchCountForTest}");
        }

        // 切到极简：只留六格 ＋ 收起格，整条带子明显变短
        var miniSeg = ui.ProfileRectForTest(0);
        ClickPhysical((miniSeg.MinX + miniSeg.MaxX) * 0.5f * DpiScale,
                      (miniSeg.MinY + miniSeg.MaxY) * 0.5f * DpiScale);
        SettleFrames(250);
        var miniBar = ui.BarRectForTest;
        Check("极简档是七格（六格 ＋ 收起格）", ui.VisibleCountForTest == 7,
              $"显示 {ui.VisibleCountForTest} 格，档位 = {ui.ProfileForTest}");
        Check("极简档是一条短胶囊", (miniBar.MaxX - miniBar.MinX) < 360f,
              $"宽 {miniBar.MaxX - miniBar.MinX:F0}（完整档是 636）");

        // 切档时"当前工具不在这一档里"要落到笔：先把工具换成图形（极简档里没有它）
        Host.Commands.SetTool(Tool.Rectangle);
        SettleFrames(150);
        var miniSeg2 = ui.ProfileRectForTest(0);          // 已经在极简了，再点一次也走同一条路
        ClickPhysical((miniSeg2.MinX + miniSeg2.MaxX) * 0.5f * DpiScale,
                      (miniSeg2.MinY + miniSeg2.MaxY) * 0.5f * DpiScale);
        Check("切档时工具不在档内→落到笔", Tool == Tool.Pen, $"工具 = {Tool}");

        // 切回完整档
        var fullSeg = ui.ProfileRectForTest(2);
        ClickPhysical((fullSeg.MinX + fullSeg.MaxX) * 0.5f * DpiScale,
                      (fullSeg.MinY + fullSeg.MaxY) * 0.5f * DpiScale);
        SettleFrames(250);
        Check("切回完整档", ui.VisibleCountForTest == 13, $"显示 {ui.VisibleCountForTest} 格");

        // 取消钉住"图形"（下标 8）：档位自动变成自定义，主条上少一格
        var chip = ui.ChipRectForTest(8);
        ClickPhysical((chip.MinX + chip.MaxX) * 0.5f * DpiScale,
                      (chip.MinY + chip.MaxY) * 0.5f * DpiScale);
        SettleFrames(250);
        Check("取消钉住→进自定义档、主条少一格",
              ui.ProfileForTest == 1 && !ui.PinnedForTest(8) && ui.VisibleCountForTest == 12,
              $"档位 = {ui.ProfileForTest}，钉着 = {ui.PinnedForTest(8)}，显示 {ui.VisibleCountForTest} 格");

        // 安全项：笔（下标 3）点一下不该被取消
        var penChip = ui.ChipRectForTest(3);
        ClickPhysical((penChip.MinX + penChip.MaxX) * 0.5f * DpiScale,
                      (penChip.MinY + penChip.MaxY) * 0.5f * DpiScale);
        SettleFrames(200);
        Check("安全项（笔）取消不掉", ui.PinnedForTest(3), $"笔钉着 = {ui.PinnedForTest(3)}");

        // 钉回去，回到完整档，别把后面的用例带偏
        // 注意：每次点之前**重新取一次矩形**——切档会让主条宽度变、抽屉跟着挪，
        // 复用之前算好的坐标就会点空（这一版自检就是这么把自己坑了一次）。
        var chipBack = ui.ChipRectForTest(8);
        ClickPhysical((chipBack.MinX + chipBack.MaxX) * 0.5f * DpiScale,
                      (chipBack.MinY + chipBack.MaxY) * 0.5f * DpiScale);
        SettleFrames(200);
        var fullSeg2 = ui.ProfileRectForTest(2);
        ClickPhysical((fullSeg2.MinX + fullSeg2.MaxX) * 0.5f * DpiScale,
                      (fullSeg2.MinY + fullSeg2.MaxY) * 0.5f * DpiScale);
        SettleFrames(200);
        var moreCell5 = ui.CellRectForTest(12);
        ClickPhysical((moreCell5.MinX + moreCell5.MaxX) * 0.5f * DpiScale,
                      (moreCell5.MinY + moreCell5.MaxY) * 0.5f * DpiScale);   // 关抽屉
        SettleFrames(250);
        Check("收尾：回到完整档、抽屉已关",
              ui.ProfileForTest == 2 && ui.VisibleCountForTest == 13 && !ui.DrawerOpenForTest,
              $"档位 = {ui.ProfileForTest}，显示 {ui.VisibleCountForTest} 格，抽屉 = {ui.DrawerOpenForTest}");

        // ---- ⑥ 收起来，然后空闲必须 0 帧 ----
        var ball2 = ui.CellRectForTest(0);
        ClickPhysical((ball2.MinX + ball2.MaxX) * 0.5f * DpiScale,
                      (ball2.MinY + ball2.MaxY) * 0.5f * DpiScale);
        SettleFrames(250);
        Check("点最左那格能收起", !ui.ExpandedForTest, $"展开状态 = {ui.ExpandedForTest}");

        PumpMessages();
        RenderAll();
        _dirty = false;
        int quiet = 0;
        var swQuiet = Stopwatch.StartNew();
        while (swQuiet.ElapsedMilliseconds < 150)
        {
            PumpMessages();
            if (NeedsFrame()) { RenderAll(); _dirty = false; quiet++; }
            else Thread.Sleep(2);
        }
        Check("空闲 0 帧", quiet == 0, $"安静 150 毫秒出了 {quiet} 帧");

        // ---- ⑦ 拖动并贴边：拖到左边缘附近松手，应该吸附过去（离边 2）----
        var home = ui.QueryBounds();
        float hx = (home.MinX + home.MaxX) * 0.5f * DpiScale;
        float hy = (home.MinY + home.MaxY) * 0.5f * DpiScale;
        int targetX = _virtualX + 20;
        SendMouse((int)hx, (int)hy, 0);                          SettleFrames(60);
        SendMouse((int)hx, (int)hy, Native.MOUSEEVENTF_LEFTDOWN); SettleFrames(50);
        for (int i = 1; i <= 10; i++)
        {
            SendMouse((int)(hx + (targetX - hx) * i / 10f), (int)hy, 0);
            SettleFrames(20);
        }
        SendMouse(targetX, (int)hy, Native.MOUSEEVENTF_LEFTUP);
        SettleFrames(200);

        var docked = ui.QueryBounds();
        float wantLeft = _virtualX / DpiScale + InkUi.Tokens.DockGap;
        Check("拖到左边缘会吸附", MathF.Abs(docked.MinX - wantLeft) < 3f,
              $"左边缘 {docked.MinX:F0}（贴边后应为 {wantLeft:F0}），拖动前在 {home.MinX:F0}");

        // ---- ⑦.2 锚点：**球不动、带子往右长**；顶到右边就整条夹回屏幕内 ----
        //
        // 用户 2026-09-17 定的规则（也是假面板当年的做法）：
        //   球是锚点（它长在**展开后那条带子的左端**），展开＝从球往右铺；
        //   铺出去会出屏时，把整条带子夹回屏幕内——看着就是"贴住右边往左铺开"。
        //
        // 这里要验两件事：① 拖到中间之后展开，**球一动不动**（收起时不用重新瞄）；
        // ② 拖到右边缘再展开，**整条带子还在屏幕里**（不会有一截跑到屏幕外）。
        {
            // ① 拖到屏幕中左部（离两边都远）→ 展开 → 球的位置必须没变
            var d0 = ui.QueryBounds();                        // 此刻贴着左边、收起态
            float sx = (d0.MinX + d0.MaxX) * 0.5f * DpiScale;
            float sy = (d0.MinY + d0.MaxY) * 0.5f * DpiScale;
            int toX = _virtualX + (int)(500 * DpiScale);
            SendMouse((int)sx, (int)sy, 0);                           SettleFrames(60);
            SendMouse((int)sx, (int)sy, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(50);
            for (int i = 1; i <= 8; i++) { SendMouse((int)(sx + (toX - sx) * i / 8f), (int)sy, 0); SettleFrames(20); }
            SendMouse(toX, (int)sy, Native.MOUSEEVENTF_LEFTUP);        SettleFrames(250);
            var parked = ui.QueryBounds();
            float parkedLeft = parked.MinX;

            ClickPhysical((parked.MinX + parked.MaxX) * 0.5f * DpiScale,
                          (parked.MinY + parked.MaxY) * 0.5f * DpiScale);   // 点球展开
            SettleFrames(400);
            var ballAfter = ui.CellRectForTest(0);                 // 展开后那一格就是球
            var anchoredBar = ui.BarRectForTest;
            Check("拖到中间后展开：球不动、只往右长",
                  // 比的是**锚点**（主条左端）：收起时它就是球的位置；
                  // 展开后球那一格还要往里让 BarPad（8 像素），拿格子比会差这 8 像素。
                  MathF.Abs(anchoredBar.MinX - parkedLeft) < 1.5f
                  && anchoredBar.MaxX > ballAfter.MaxX + 400f,
                  $"锚点（主条左端）{parkedLeft:F0} → {anchoredBar.MinX:F0}，"
                  + $"带子 {anchoredBar.MinX:F0}..{anchoredBar.MaxX:F0}");

            // 收回去（后面几段用例都假设"面板是收起的"）
            var ballCell = ui.CellRectForTest(0);
            ClickPhysical((ballCell.MinX + ballCell.MaxX) * 0.5f * DpiScale,
                          (ballCell.MinY + ballCell.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            Check("再点一次收起（回到球）", !ui.ExpandedForTest, $"展开状态 = {ui.ExpandedForTest}");

            // ② 拖到**右边缘**（会吸附）→ 展开 → 整条带子必须还在屏幕里
            var e0 = ui.QueryBounds();
            float ex = (e0.MinX + e0.MaxX) * 0.5f * DpiScale;
            float ey = (e0.MinY + e0.MaxY) * 0.5f * DpiScale;
            int farX = (int)((_virtualX + _virtualW) - 30 * DpiScale);
            SendMouse((int)ex, (int)ey, 0);                           SettleFrames(60);
            SendMouse((int)ex, (int)ey, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(50);
            for (int i = 1; i <= 10; i++) { SendMouse((int)(ex + (farX - ex) * i / 10f), (int)ey, 0); SettleFrames(20); }
            SendMouse(farX, (int)ey, Native.MOUSEEVENTF_LEFTUP);       SettleFrames(250);

            var atRight = ui.QueryBounds();
            ClickPhysical((atRight.MinX + atRight.MaxX) * 0.5f * DpiScale,
                          (atRight.MinY + atRight.MaxY) * 0.5f * DpiScale);  // 展开
            SettleFrames(500);
            var rightBar = ui.BarRectForTest;
            float screenL = _virtualX / DpiScale, screenR = (_virtualX + _virtualW) / DpiScale;
            Check("球贴右边时展开：整条带子夹回屏幕内（贴着右边、往左铺）",
                  rightBar.MinX >= screenL - 1f && rightBar.MaxX <= screenR + 1f
                  && MathF.Abs(rightBar.MaxX - (screenR - InkUi.Tokens.DockGap)) < 3f,
                  $"带子 {rightBar.MinX:F0}..{rightBar.MaxX:F0}（屏 {screenL:F0}..{screenR:F0}）");

            // 收拾干净：收回球、拖回屏幕中间，别把后面几段用例带偏
            var ballCell2 = ui.CellRectForTest(0);
            ClickPhysical((ballCell2.MinX + ballCell2.MaxX) * 0.5f * DpiScale,
                          (ballCell2.MinY + ballCell2.MaxY) * 0.5f * DpiScale);
            SettleFrames(250);
            var b2 = ui.QueryBounds();
            float b2x = (b2.MinX + b2.MaxX) * 0.5f * DpiScale, b2y = (b2.MinY + b2.MaxY) * 0.5f * DpiScale;
            SendMouse((int)b2x, (int)b2y, 0);                          SettleFrames(60);
            SendMouse((int)b2x, (int)b2y, Native.MOUSEEVENTF_LEFTDOWN); SettleFrames(50);
            int homeX = _virtualX + (int)(720 * DpiScale);
            for (int i = 1; i <= 8; i++) { SendMouse((int)(b2x + (homeX - b2x) * i / 8f), (int)b2y, 0); SettleFrames(20); }
            SendMouse(homeX, (int)b2y, Native.MOUSEEVENTF_LEFTUP);      SettleFrames(250);
        }

        // ---- ⑧ 抽屉里的「重启软件」：先暂存板书，再拉起新进程（这里只记一笔，不真拉）----
        Recovery.ClearRestartCount();
        try { File.Delete(Recovery.SessionPath); } catch { }

        // ---- ⑨ 偏好落盘：改过的写进 settings.json，重开界面读得回来 ----
        // 把状态弄成一组"非默认"：深色开着（前面的用例已经开了）、取消钉住"图形"
        // （档位随之进"自定义"）。自检模式用的是临时配置文件，不碰用户真正的设置。
        //
        // 注意：上一条用例结束时面板是**收起**的，得先展开再去点抽屉里的东西——
        // 收起状态下那些格子的坐标算出来是"按球的位置铺开"，点过去全是空的
        // （这一版用例第一次跑就是这么点空的）。
        var ballFirst = ui.QueryBounds();
        ClickPhysical((ballFirst.MinX + ballFirst.MaxX) * 0.5f * DpiScale,
                      (ballFirst.MinY + ballFirst.MaxY) * 0.5f * DpiScale);
        SettleFrames(300);
        var moreCell6 = ui.CellRectForTest(12);
        ClickPhysical((moreCell6.MinX + moreCell6.MaxX) * 0.5f * DpiScale,
                      (moreCell6.MinY + moreCell6.MaxY) * 0.5f * DpiScale);       // 开抽屉
        SettleFrames(200);
        var chip6 = ui.ChipRectForTest(8);
        ClickPhysical((chip6.MinX + chip6.MaxX) * 0.5f * DpiScale,
                      (chip6.MinY + chip6.MaxY) * 0.5f * DpiScale);               // 取消钉住"图形"
        SettleFrames(250);
        SaveSettingsForTest();

        string prefsPath = InkSettings.PathOverride ?? "";
        string prefsText = File.Exists(prefsPath) ? File.ReadAllText(prefsPath) : "";
        Check("改动写进了配置文件",
              prefsText.Contains("\"ui\"") && prefsText.Contains("\"dark\"")
              && prefsText.Contains("\"profile\"") && prefsText.Contains("\"unpinned\""),
              $"{Path.GetFileName(prefsPath)}（{prefsText.Length} 字节）");

        // 把内存里那份清掉、从文件重读，再挂一个新界面——这才算"重开软件"那条链子
        ReloadUiPrefsForTest();
        SetUiFactory(() => new InkUi.FullUi());
        SettleFrames(300);
        ui = CurrentUi as InkUi.FullUi;
        Check("重开界面读回了偏好",
              ui != null && ui.DarkForTest && ui.ProfileForTest == 1 && !ui.PinnedForTest(8),
              $"深色={ui?.DarkForTest}，档位={ui?.ProfileForTest}（1=自定义），图形钉着={ui?.PinnedForTest(8)}");

        try { File.Delete(prefsPath); } catch { }        // 临时配置用完就删

        Doc.Clear();
        Doc.ClearHistory();
        var keep2 = new Stroke { Tool = Tool.Pen, Color = new Color4(0f, 0f, 0f, 1f), Width = 6f };
        keep2.AddPoint(500, 500, 1f, 0);
        keep2.AddPoint(800, 500, 1f, 1);
        Doc.AddStroke(keep2);

        NormalizePanel();
        // **按标签找那一行，不写行下标**：抽屉的行会插来插去（2026-09-17 插了底纹两行、
        // 2026-09-19 把「学科工具」换成坐标系/数轴/网格三行），
        // 写死下标的话每插一次就要改一处引用，而且点错行时红的是那条断言本身
        // （"点重启没反应"）——2026-09-19 就是这么又红了一次。
        var restartRow = ui.RowRectByLabelForTest("重启软件");
        Check("自检能按标签找到「重启软件」那一行",
              restartRow.MaxY > restartRow.MinY, $"行高 {restartRow.MaxY - restartRow.MinY:F0}");
        // 造一个"上次崩溃抢救留下的残留"，并清掉自动存档从零开始：
        // **这一条是故意的**——新语义里光"不写会话暂存"是不够的，残留会被新进程读回去，
        // 那就成了"重启还带出旧板书"。所以必须被删掉。
        File.WriteAllBytes(Recovery.SessionPath, new byte[] { 1, 2, 3, 4 });
        Recovery.DeleteAuto();

        ClickPhysical((restartRow.MinX + restartRow.MaxX) * 0.5f * DpiScale,
                      (restartRow.MinY + restartRow.MaxY) * 0.5f * DpiScale);
        // 新语义（2026-09-22 用户定："重启就相当于电脑重启，墨迹不保存"）：
        // **判据和"界面崩了自己重建"那条路正好相反**——那条要求 SessionPath 存在
        //（见 `--uitest` 里"板书必须读得回来"那一条），因为那是 App 自己决定重启、
        // 丢了板书是事故。两处一起改就会把其中一条弄坏。
        Check("点「重启软件」＝ 像电脑重启：不写会话暂存，残留也被删掉",
              RestartRequested && !File.Exists(Recovery.SessionPath),
              $"重启已发起 = {RestartRequested}，会话暂存还在 = {File.Exists(Recovery.SessionPath)}");
        Check("但盘上留了一份自动存档（需要时能找回来）",
              Recovery.AutoSaveExists, $"autosave 存在 = {Recovery.AutoSaveExists}");

        // 留的那一份**要真的解得回来**：只断言"文件存在"等于没验（写个空文件也算存在）。
        int keptStrokes = -1;
        try
        {
            var keptBlob = Recovery.LoadAuto();
            Doc.Clear();
            InkSerializer.LoadInto(Doc, keptBlob);
            keptStrokes = Doc.Strokes.Count;
        }
        catch (Exception ex) { Console.WriteLine("  读回自动存档失败：" + ex.Message); }
        Check("留的那一份解得回来、笔数对得上", keptStrokes == 1,
              $"读回 {keptStrokes} 笔（应为 1 笔）");

        Recovery.DeleteAuto();
        Recovery.ClearRestartCount();

        Console.WriteLine($"  结果: {pass} 项通过, {fail} 项失败");
        ExitCode = fail == 0 ? 0 : 1;
        _quit = true;
    }

    /// <summary>
    /// **图形那格的界面入口自检**（2026-09-19：给圆 / 三角形 / 平行四边形补真机入口）。
    ///
    /// 为什么单独一支、不塞进 `--paneltest`：
    ///   · paneltest 是"球 → 按钮带"那条最小闭环，项数是**写进报告里的 100**；
    ///     往里加用例会把那个数字改掉，"这次和上次哪里不一样"就说不清了；
    ///   · 这一支要**按真键**（SendInput 发 Ctrl+Alt+O），比 paneltest 慢、也更依赖桌面环境，
    ///     单独一支好在"合成输入不可用"时整支 SKIP，不拖累别的用例。
    ///
    /// 四段：
    ///   A. 上带是**七段**，逐段点一遍 → 工具切成对应的那一种（"真机上点得到"的判据）；
    ///   B. 三个新热键（圆 / 三角形 / 平行四边形）**真按一次** → 工具跟着切；
    ///   C. 用点段选出来的那三种工具**在画布上画一笔** → StrokeKind 就是那一种
    ///      （工具切对了 ≠ 画得出来，最终答案在 StrokeKind 上）；
    ///   D. 主条"图形"那一格的**图标跟着当前种类变**（七种两两不同）。
    /// </summary>
    private void ShapeBandTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 图形那格的界面入口自检（七段 / 三个新热键 / 主条图标）===");

        if (SkipIfNoSyntheticInput("图形界面入口自检")) { _quit = true; return; }

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-32} {detail}");
        }

        void ClickPhysical(float x, float y)
        {
            SendMouse((int)x, (int)y, 0);                            SettleFrames(80);
            SendMouse((int)x, (int)y, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
            SendMouse((int)x, (int)y, Native.MOUSEEVENTF_LEFTUP);    SettleFrames(320);
        }

        // 起手和 paneltest 一样：关穿透、挂产品界面、清空文档（判据要确定）。
        PassMode = PassThroughMode.LayeredTransparent;
        PassThrough = false;
        foreach (var w in _windows) ApplyPassThroughStyle(w);
        SetUiFactory(() => new InkUi.FullUi());
        Doc.Clear();
        Doc.ClearHistory();
        Tool = Tool.Pen;
        SettleFrames(300);

        var ui = CurrentUi as InkUi.FullUi;
        if (ui == null)
        {
            Console.WriteLine($"  界面没挂上：当前 = {CurrentUi.Name}");
            ExitCode = 1;
            _quit = true;
            return;
        }

        // 图形那一格从左到右、从上到下分别是什么。**这里是期望值**
        // （界面那边读的是 FullUi.ShapeRows，一行一个数组）：
        // 自检要是也从界面那张表里读，就成了"自己和自己比"。
        var want = new (Tool tool, string name)[]
        {
            (Tool.Line, "直线"), (Tool.Rectangle, "矩形"), (Tool.Ellipse, "椭圆"),
            (Tool.Circle, "圆"), (Tool.Triangle, "三角形"),
            (Tool.Parallelogram, "平行四边形"), (Tool.Arrow, "箭头"),
            // 2026-09-19：坐标轴那一批**接在末尾**（用户要求"所有图形都从图形框那个入口进"）。
            // **数轴那一段当天晚些又撤掉了**（用户："把快捷栏最后一个图标删掉，我感觉用不到"），
            // 所以第一行到此为止是 8 段、坐标系是最后一段。撤的是**入口**：
            // `StrokeKind.NumberLine` 留在存档里，老板书里的数轴照样能打开、能选中、能删
            // （见 计划-图形工具.md 11.2）。
            (Tool.Coordinate, "坐标系"),

            // **第二行（2026-09-20 第五批）**：四种曲线。用户定的入口是
            // "图形框里加第二行，高频的只要一行"——所以第一行八段一个没动。
            //
            // ⚠ **2026-09-22 用户重排了行首三格**（原话："椭圆排在第二行的最前面，
            // 然后是椭圆的……图标前三个是椭圆，双曲线，抛物线"）：
            //   ① 椭圆（带焦点）② 双曲线 ③ 抛物线 —— 三个**圆锥曲线**连在一起，
            //   双曲线那一格当天还多了"有 / 无渐近线"两档、椭圆那一格多了"有 / 无焦点三角形"。
            //   注意段落号是按**工具名**找的（`ShapeSegmentIndexForTest`），所以这次重排
            //   不会让下面任何一条断言点错格子。
            (Tool.ConicEllipse, "椭圆（带焦点）"),
            (Tool.Hyperbola, "双曲线"), (Tool.Parabola, "抛物线"),
            (Tool.Sine, "正弦"), (Tool.Cosine, "余弦"),
            // 2026-09-20 第十六批：**波浪线**（用户："还有一个另外的**很多周期的波浪**的弦函数线"）。
            // 它和正弦是同一条曲线，差别只在**这一拖管什么**：
            // 正弦的框宽 = 一个周期（讲"一个周期的图象"）、波浪线的框宽 = 要画多长
            //（周期由振幅定，讲周期性用）。所以两格紧挨着排，曲线那一行七格。
            (Tool.Wave, "波浪线"),
            // 2026-09-20 第十五批：**正切**（用户："可以画正切"）。它和正弦 / 余弦同族
            // （都在第二行这一族曲线上），但**一笔**画完：按下是原点、拖出去是以它为中心的框
            //（见 StrokeKind.Tangent）。⚠ 它在余弦**后面**——同一族的曲线连着排。
            (Tool.Tangent, "正切"),
            // 同一天又搬进来两个**立体图形**（照 InkClass 的 case 6/7）：
            // 一次拖出外接矩形，底面被挡住的那半圈是虚线。
            (Tool.Cylinder, "圆柱"), (Tool.Cone, "圆锥"),
            // 2026-09-20 第十三批：**圆台**（用户："再加一个圆台"）。和圆柱 / 圆锥同族
            //（一笔拖出外接矩形），所以紧挨着它们放。
            (Tool.ConeFrustum, "圆台"),
            // 2026-09-20 第十四批：**球**（用户："在加入球"）。一笔拖外接矩形。
            // ⚠ 位置按用户同一天的口径改过："把球放在旋转体后面" —— 所以它在圆台之后、
            // 棱柱之前（旋转体那一组"柱 / 锥 / 台 / 球"连着排）。
            (Tool.Sphere, "球"),
            // 2026-09-20 第十一批：**棱柱**（3/4/5/6 棱柱 ＋ 直/斜）。两笔，
            // 而且那一格"再点一次换一档"（和直线的线型同构，见 §32）。
            (Tool.Prism, "棱柱"),
            // 2026-09-20 第十二批：**棱锥 / 棱台**（见 §34）。它们和棱柱是**一族**
            //（同样的两笔、同样的 3/4/5/6 档、同样的"直"吸附），所以紧挨着排。
            (Tool.Pyramid, "棱锥"), (Tool.Frustum, "棱台"),
            // ⚠ **长方体 / 四面体那两段撤掉了**（同一天，用户："那两格似乎可以删除掉了"）——
            // 所以这张期望表里也没有它们了，但**画法与存档都还在**（下面单列一条断言钉住
            // "能画、没入口"这第三种状态，正因为"有入口的那些"这张表管不到它们）。
            // 行结构见下面的 `wantRowLens`（2026-09-20 第十三批从两行改成三行）。
        };
        // 图形那一格的**行结构**（每行几段）——**期望值，独立于界面那张表**。
        // 加图形时必须一起改：下面先断一句"各行加起来 = want 的段数"，对不上就红
        //（这就是"自检表本身也要被卡住"那条规矩在这里的落点）。
        // 2026-09-20 第十三批：从"两行 8+10"改成"三行 8+4+6"——第二行 10 段时每格
        // 只有 55 宽，低于"每段 ≥ 60"那条量出来的门槛（见 计划-图形工具.md §35）；
        // 第十四批加球：第三行 6 → **7** 段（604 ÷ 7 ≈ 81，还在门槛之上）。
        // 第十五批加正切、第十六批加波浪线：**第二行 4 → 6** 段（604 ÷ 6 ≈ 101）。
        // 2026-09-22 加椭圆（带焦点）：**第二行 6 → 7** 段（604 ÷ 7 ≈ 86，和第三行一样宽，
        // 仍在"每段 ≥ 60"那条门槛之上）。
        // 2026-09-22 加「图库」：**第四行 1 段**——它是**动作**（点开图库面板），
        // 不是图形工具，所以 `want` 里没有它，但**行结构里要有它**（带子高了就得占一行）。
        int[] wantRowLens = { 8, 7, 7, 1 };
        /** 「图库」那一段：段表之外的**动作段**（不计入 `want`）。 */
        const int actionSegs = 1;

        // 上带只在"指针落在面板上"时张开（见 FullUi.RailHoverZone）。点完一格、画完一笔
        // 之后指针可能在画布上，所以每次要点段之前先把指针挪回主条等它张开。
        // 合成鼠标**偶尔会丢一次移动**（paneltest 里也见过），给三次机会。
        void EnsureRailOpen()
        {
            var bar = ui.BarRectForTest;
            int px = (int)((bar.MinX + bar.MaxX) * 0.5f * DpiScale);
            int py = (int)((bar.MinY + bar.MaxY) * 0.5f * DpiScale);
            for (int attempt = 0; attempt < 3 && !ui.RailOpenForTest; attempt++)
            {
                SendMouse(px, py - attempt, 0);
                SettleFrames(350);
            }
        }

        void ClickSegment(int i)
        {
            var seg = ui.SegmentRectForTest(i);
            ClickPhysical((seg.MinX + seg.MaxX) * 0.5f * DpiScale,
                          (seg.MinY + seg.MaxY) * 0.5f * DpiScale);
        }

        // 让上带回到"图形"那一格，再把指针挪回主条等它张开。
        // **每一步都要重新做**：上带是跟着当前工具走的（CellForTool），按过换工具的热键
        // 或换成笔之后，它显示的是**那个工具**的设置条——这时去点"第 3 段"会点在
        // 别的设置条上（笔那格是 12 个色片），点出来的结果和图形毫无关系。
        // C 段第一次跑就是这么点空的。
        void GotoShapeBand()
        {
            var cell = ui.CellRectForTest(8);
            ClickPhysical((cell.MinX + cell.MaxX) * 0.5f * DpiScale,
                          (cell.MinY + cell.MaxY) * 0.5f * DpiScale);
            EnsureRailOpen();
        }

        // 面板现在是**启动即展开**的（用户 2026-09-27 定的默认态），所以正常情况下这一段
        // 什么都不用做。留着兜底：万一哪天默认态又改回收起（或者这里的界面是中途换过的），
        // 点一下"收起格"旁边的球把它掰开，后面才不会"一段都点不到"。
        if (!ui.ExpandedForTest)
        {
            var bb = ui.QueryBounds();
            ClickPhysical((bb.MinX + bb.MaxX) * 0.5f * DpiScale,
                          (bb.MinY + bb.MaxY) * 0.5f * DpiScale);
            SettleFrames(300);
        }
        Check("面板是展开的（不然面板上的格子一个都点不到）",
              ui.ExpandedForTest, $"展开 = {ui.ExpandedForTest}");

        // ================= A. 每一段都点得到 =================
        //
        // ⚠ 段数**不写死在文案里**（"十七段"这种字眼一加图形就过期）：下面几条断言全用
        // `want.Length` / `n` 现算。
        Console.WriteLine($"  -- A. 上带图形格（{want.Length} 段）：逐段点一遍，工具真的切了 --");
        GotoShapeBand();

        int n = ui.BandSegmentCountForTest;
        Check($"自检表：行结构 {string.Join("＋", wantRowLens)} = {want.Length} 个图形 ＋ {actionSegs} 段动作",
              wantRowLens.Sum() == want.Length + actionSegs && wantRowLens.All(v => v > 0),
              $"{string.Join("＋", wantRowLens)} = {wantRowLens.Sum()}（期望 {want.Length + actionSegs}）");
        Check($"图形那格的上带是 {want.Length + actionSegs} 段（{wantRowLens.Length} 行：{string.Join("＋", wantRowLens)}）",
              n == want.Length + actionSegs && InkUi.FullUi.ShapeRowCountForTest == wantRowLens.Length,
              $"段数 {n}（期望 {want.Length + actionSegs}），行数 {InkUi.FullUi.ShapeRowCountForTest}"
              + $"（期望 {wantRowLens.Length}）");

        // 段宽和越界：段宽 = 可用宽 ÷ **本行**段数，所以各行各有各的宽度。
        // "挤到看不清" ＝ 这个入口等于没有，所以宽度本身就是判据（图标 18 逻辑像素，
        // 60 的门槛给的是"图标四周还留得下 20 像素空白"）——2026-09-20 第十三批
        // 就是这条把"第二行 10 段（每格 55 宽）"当场拦下来的，所以才改成三行。
        //
        // 行分组按**自检自己那份 `wantRowLens`** 走（不读界面的行表，那成了自己和自己比）；
        // 每行再从界面拿一次段矩形，验"行不重叠、都在带子里"。
        var bandRect = ui.BandRectForTest;
        float minW = float.MaxValue, maxRight = float.MinValue;
        var rowTop = new float[wantRowLens.Length];
        var rowBottom = new float[wantRowLens.Length];
        for (int r = 0; r < wantRowLens.Length; r++) { rowTop[r] = float.MaxValue; rowBottom[r] = float.MinValue; }
        int segIdx = 0;
        for (int r = 0; r < wantRowLens.Length; r++)
        {
            for (int c = 0; c < wantRowLens[r]; c++, segIdx++)
            {
                var rr = ui.SegmentRectForTest(segIdx);
                minW = MathF.Min(minW, rr.MaxX - rr.MinX);
                maxRight = MathF.Max(maxRight, rr.MaxX);
                rowTop[r] = MathF.Min(rowTop[r], rr.MinY);
                rowBottom[r] = MathF.Max(rowBottom[r], rr.MaxY);
            }
        }
        Check($"{want.Length + actionSegs} 段都画得下（每段 ≥ 60 宽、最右一段不越出上带）",
              n == want.Length + actionSegs && minW >= 60f && maxRight <= bandRect.MaxX + 0.5f,
              $"最窄 {minW:F0} 逻辑像素（门槛 60），上带宽 {bandRect.MaxX - bandRect.MinX:F0}");
        // 各行**不许叠在一起**，而且都要落在带子里——带子为多行长得更高
        // （见 FullUi.BandHeightLogical），这一条就是钉住"长得够高"。
        bool rowsOk = true;
        string rowNote = "";
        for (int r = 0; r < wantRowLens.Length; r++)
        {
            if (rowTop[r] < bandRect.MinY - 0.5f || rowBottom[r] > bandRect.MaxY + 0.5f)
            { rowsOk = false; rowNote = $"第 {r + 1} 行出了带子"; }
            if (r > 0 && rowTop[r] < rowBottom[r - 1] - 0.5f)
            { rowsOk = false; rowNote = $"第 {r + 1} 行和第 {r} 行叠了"; }
        }
        Check($"{wantRowLens.Length} 行不重叠、且都在带子里（带子为多行长得更高）",
              rowsOk,
              rowsOk
                  ? "各行 y " + string.Join(" / ", Enumerable.Range(0, wantRowLens.Length)
                        .Select(r => $"{rowTop[r]:F0}..{rowBottom[r]:F0}"))
                    + $"，带子 y {bandRect.MinY:F0}..{bandRect.MaxY:F0}"
                  : rowNote);

        // == 指针停在**任何一行**上，带子都得留得住（不许收） ==
        //
        // 用户 2026-09-20 报的 bug 就是这一条："**鼠标移动到第一行的任何图形位置，
        // 色带会收起来**"——根因是"焦点在面板上"的判定区用了**一行**的带子高
        //（`Tokens.BandHeight`），而这一格是三行：指针挪到上面那两行就落到判定区外面，
        // 220 毫秒后带子收回。
        //
        // 所以判据要**逐行**来，而且要看**两件事**：判定为悬停（`RailHoverForTest`）
        // 和真的没收（`RailOpenForTest`）—— 只看前者的话，"判定区对了但动画被别处打断"
        // 会溜过去。等 400 毫秒是故意的：退出判定要 220 毫秒才动，等短了测不出来。
        {
            string badRow = "";
            for (int r = 0; r < wantRowLens.Length && badRow.Length == 0; r++)
            {
                EnsureRailOpen();
                // 段矩形 / 带子矩形都是**逻辑**坐标，合成鼠标要的是屏幕像素 → 乘 DpiScale
                //（和上面 `EnsureRailOpen` 同一个口径）。
                int cx = (int)((bandRect.MinX + bandRect.MaxX) * 0.5f * DpiScale);
                int cy = (int)((rowTop[r] + rowBottom[r]) * 0.5f * DpiScale);
                SendMouse(cx, cy, 0);
                SettleFrames(400);
                if (!ui.RailHoverForTest || !ui.RailOpenForTest)
                    badRow = $"第 {r + 1} 行（y {cy}）：悬停={ui.RailHoverForTest}，张开={ui.RailOpenForTest}";
            }
            Check($"{wantRowLens.Length} 行的**每一行**都留得住带子（指针停上去不许收）",
                  badRow.Length == 0,
                  badRow.Length == 0
                      ? $"逐行停 400 毫秒，带子一直张开（带子 y {bandRect.MinY:F0}..{bandRect.MaxY:F0}）"
                      : badRow);
        }

        // **哪几格该有档位点、各有几档**——期望值独立写在下面这张表里。
        // 用户 2026-09-20 提的两条都落在这上面：
        //   · "你把档位点挪到图标右边"（位置）—— 那条只有出图看得见；
        //   · "抛物线页增加小圆点"（**这一格原来没有点**）—— 这条能断，而且该断：
        //     它有"再点一次换一档"却一直没给点，是**漏的**（和加图形忘了自检同一类）。
        // 所以这里逐段比：该有几档就几档，别的图形必须 0。
        {
            var pipWant = new Dictionary<Tool, int>
            {
                [Tool.Line] = 3,        // 实 / 虚 / 点
                [Tool.Parabola] = 2,    // 上下 / 左右
                [Tool.Prism] = 4, [Tool.Pyramid] = 4, [Tool.Frustum] = 4,   // 三 / 四 / 五 / 六
                // 2026-09-22 加的两格，各 2 档：双曲线（有 / 无渐近线）、
                // 椭圆（带焦点）（有 / 无焦点三角形）。
                [Tool.Hyperbola] = 2, [Tool.ConicEllipse] = 2,
                // 2026-09-24：「坐标系」也成了"再点一次换一档"的那一格（带网格 / 不带网格）
                // ——这一档是从「更多」抽屉挪过来的，**一样要给点**：
                // 用户当天紧接着就提了"它档位之间是有切换按钮的，你可以参照一下其他那个切换逻辑"。
                [Tool.Coordinate] = 2,
            };
            int pipOk = 0, pipNo = 0;
            var pipWrong = new List<string>();
            for (int i = 0; i < want.Length; i++)
            {
                int wantCount = pipWant.TryGetValue(want[i].tool, out int c) ? c : 0;
                var (gotCount, gotCur) = ui.ShapePipsForTest(i);
                bool ok = gotCount == wantCount && (gotCount == 0 || (gotCur >= 0 && gotCur < gotCount));
                if (ok && gotCount > 0) pipOk++; else if (ok) pipNo++;
                if (!ok)
                    pipWrong.Add($"{want[i].name}：{gotCount} 个（期望 {wantCount}）");
            }
            Check("档位点：**该有的那几格**有（直线 3 / 抛物线 2 / 双曲线 2 / 椭圆带焦点 2 / 坐标系 2 / 棱柱族 4），别的图形一个点都没有",
                  pipWrong.Count == 0,
                  pipWrong.Count > 0
                      ? string.Join("；", pipWrong)
                      : $"有档位的 {pipOk} 格、没档位的 {pipNo} 格，当前档也都在范围内");
        }

        for (int i = 0; i < want.Length; i++)
        {
            EnsureRailOpen();
            ClickSegment(i);
            Check($"第 {i + 1} 段「{want[i].name}」点得到、工具切了",
                  Host.State.Tool == want[i].tool,
                  $"工具 = {Host.State.Tool}（期望 {want[i].tool}）");
        }

        // ---- 名单一致性：三份"图形"判据必须一一对应 ----
        //
        // 2026-09-20 收敛之后，"哪些是图形"只剩三个入口，维度不同但**必须同步**：
        //   · `Engine.IsShapeTool(Tool)`  = 这个工具**画出来的是图形**（**含数轴**——
        //     它没有面板入口了，但画法还在，老存档里的数轴要能选中、能删）；
        //   · `FullUi` 的两张段表         = 面板上**有入口**的那些（**不含数轴**）；
        //   · `Stroke.IsShapeKind(Kind)`  = 按种类的"参数化图形"那一份
        //     （Model 与 Selection 共用；**矩形不在里面，是故意的**：它的局部 AABB 就是
        //      自己的边界、选中后走通用框那套八向柄，不参与"按参数算墨迹框 / 发定义元素手柄"）。
        //
        // 这里逐段对照"有入口的必须能画；除矩形外还必须算参数化图形"。
        // 加新图形时漏改一处，这一条立刻红——而不是等到"画出来点不中"才发现。
        bool namesAgree = true;
        string nameNote = "";
        for (int i = 0; i < want.Length; i++)
        {
            var kind = KindOfShapeTool(want[i].tool);
            if (!IsShapeTool(want[i].tool))
            {
                namesAgree = false;
                nameNote = $"「{want[i].name}」面板上有入口，但 Engine.IsShapeTool 说它不是图形工具";
                break;
            }
            if (kind != StrokeKind.Rectangle && !Stroke.IsShapeKind(kind))
            {
                namesAgree = false;
                nameNote = $"「{want[i].name}」的 Kind = {kind}，但 Stroke.IsShapeKind 说它不是参数化图形";
                break;
            }
        }
        Check("名单一致：面板十二段 ↔ Engine.IsShapeTool ↔ Stroke.IsShapeKind 三方对得上",
              namesAgree,
              namesAgree ? $"逐段核对 {want.Length} 段（矩形落在 ShapeKind 之外，故意的）" : nameNote);
        // 另一头单独验一句：**能画、但面板上没入口**的那些（2026-09-19 撤的数轴、
        // 2026-09-20 第十二批撤的长方体 / 四面体）——撤的是**入口**，画法与存档都留着。
        // 不单列的话，上面对照表只会看"有入口的那些"，这第三种状态就没人管了
        //（而它恰恰是最容易出事的一种：以为删干净了，结果旧板书打开少一条）。
        var noEntry = new (Tool tool, string name)[]
        {
            (Tool.NumberLine, "数轴"),
            (Tool.Cuboid, "长方体"),
            (Tool.Tetrahedron, "四面体"),
        };
        foreach (var (tool, name) in noEntry)
        {
            Check($"名单一致：「{name}」**能画、但面板没入口**（撤的是入口，不是画法）",
                  IsShapeTool(tool) && !InkUi.FullUi.HasShapeEntryForTest(tool),
                  $"能画 = {IsShapeTool(tool)}，"
                  + $"有入口 = {InkUi.FullUi.HasShapeEntryForTest(tool)}");
            Check($"名单一致：「{name}」的种类仍算参数化图形（旧板书要能选中、能移动）",
                  Stroke.IsShapeKind(KindOfShapeTool(tool)),
                  $"Kind = {KindOfShapeTool(tool)}");
        }

        // **自检表本身也要被卡住**——这一条是给"**以后每个新增图形都要自检**"立的规矩。
        //
        // 做法：把引擎里所有"能画的图形"**枚举出来**（`IsShapeTool` 说了算），要求它们
        // 一个不漏地出现在上面两张表里。以后新加一种图形、只要忘了写进自检表，
        // **这条当场红**——而不是像棱锥 / 棱台这一轮那样，靠用户上手才发现。
        //
        // （为什么要"枚举 + 集合比较"，而不是"再数一遍个数"：个数对不上说明不了**谁**漏了，
        //   而这里错了会直接把名字打出来。）
        var engineShapes = Enum.GetValues<Tool>().Where(IsShapeTool).ToArray();
        var listedTools = want.Select(w => w.tool).Concat(noEntry.Select(n => n.tool)).ToArray();
        var missingShapes = engineShapes.Where(t => !listedTools.Contains(t)).ToArray();
        var extraShapes = listedTools.Where(t => !engineShapes.Contains(t)).ToArray();
        Check("自检覆盖：引擎里**每一个**图形都在自检表里（新增图形忘了写自检 → 这里红）",
              missingShapes.Length == 0 && extraShapes.Length == 0,
              missingShapes.Length > 0
                  ? $"自检表漏了：{string.Join(" / ", missingShapes)}"
                  : extraShapes.Length > 0
                      ? $"自检表里多出（引擎说它不是图形）：{string.Join(" / ", extraShapes)}"
                      : $"引擎 {engineShapes.Length} 个图形 = 自检表 {listedTools.Length} 个"
                        + $"（有入口 {want.Length} ＋ 没入口 {noEntry.Length}），两边完全对上");

        // ================= A2. 抛物线那格：**再点一次 = 换一档（上下 / 左右）** =================
        //
        // 用户 2026-09-20 深夜定：**上下还是左右**画之前定，不从选中框改
        //（"选中框的抛物线按钮功能取消哦，我不打算从这个转抛物线开口"）；
        // 后来（同一天更晚）他看了手感又说"感觉不对，还是参考他的逻辑"——
        // 于是**具体朝哪边**改由那一拖的符号定（照 InkClass 的 case 20/21），
        // 面板这一格只剩"哪一对"（= 他那儿两个按钮：上下抛物 / 左右抛物）。
        // 这里验四件事：
        //   ① 点第一下 = 选中抛物线、还是"上下"那一档；
        //   ② 再点 = 换到"左右"（两档循环）；
        //   ③ 那一格的**图标名**跟着变（不换的话，老师看不出点第二下有没有生效）；
        //   ④ 别的图形**不参与**这条规则（再点还是它自己）。
        Console.WriteLine("  -- A2. 抛物线格：再点一次换一档（上下 / 左右，画之前定）--");
        GotoShapeBand();
        int paraSeg = InkUi.FullUi.ShapeSegmentIndexForTest(Tool.Parabola);   // 按工具名找（不写死段号）
        ClickSegment(paraSeg);
        Check("抛物线：点第一下 = 选中它，还是「上下抛物」那一档",
              Host.State.Tool == Tool.Parabola && Host.State.ParabolaAxis == CurveAxis.OpenUp,
              $"工具 {Host.State.Tool}、档位 {Host.State.ParabolaAxis}");

        var axisRun = new (CurveAxis want, string icon)[]
        {
            (CurveAxis.OpenRight, "parabolaRight"),   // 第二下 = 换到"左右抛物"
            (CurveAxis.OpenUp, "parabola"),           // 第三下 = 转回"上下抛物"
        };
        for (int k = 0; k < axisRun.Length; k++)
        {
            EnsureRailOpen();
            ClickSegment(paraSeg);                    // 再点一次 = 换一档
            Check($"抛物线：第 {k + 2} 次点 = 换到 {axisRun[k].want}（工具没变）",
                  Host.State.Tool == Tool.Parabola && Host.State.ParabolaAxis == axisRun[k].want,
                  $"工具 {Host.State.Tool}、档位 {Host.State.ParabolaAxis}");
            Check($"抛物线：图标名跟着变成 {axisRun[k].icon}",
                  ui.ShapeIconNameForTest(paraSeg) == axisRun[k].icon,
                  ui.ShapeIconNameForTest(paraSeg));
        }

        // 别的图形**不许**被这条规则影响：连点两次三角形，还是三角形。
        EnsureRailOpen();
        ClickSegment(4);                              // 第一行第 5 段 = 三角形
        EnsureRailOpen();
        ClickSegment(4);
        Check("别的图形：再点一次仍然是它自己（这条规则只对抛物线）",
              Host.State.Tool == Tool.Triangle, $"工具 {Host.State.Tool}");

        // ================= A3. 直线那一段：**再点一次 = 换一档线型** =================
        //
        // 用户 2026-09-20 定（落地记在 计划-图形工具.md §27.1）：
        // "点击直线的图标，它会变成虚线，再点击变成点虚线，再点击又变成直线……
        //  这样就可以在虚实之间切换，而且又**省了好几个空间格**"。
        //
        // 验五件事（缺哪一件都可能"看着绿其实没做"）：
        //   ① **一轮三档**：实线 → 虚线 → 点线 → 实线（第四下回到起点，不是停在点线）；
        //   ② 那一格的**图标名**跟着换（不换的话，老师看不出点第二下有没有生效）；
        //   ③ 新画出来的直线**真的带那一档**（几何层，不只是界面显示）；
        //   ④ **只影响以后画的**：先画好的那条一个字节都不许动；
        //   ⑤ 别的图形**不吃这一档**（画出来一律实线）——这条钉住"只给直线"的口径。
        Console.WriteLine("  -- A3. 直线格：再点一次换一档线型（实线 → 虚线 → 点线）--");
        GotoShapeBand();

        // 先归零：不写死"进来时一定是实线、一定是直线工具"——前面任何一段点过它就会错位。
        // **两个条件都要判**：工具不是直线时，点它只是"选中它"（不换档）；
        // 工具已经是直线时，点它才换档。最多四下一。
        for (int k = 0; k < 4
             && (Host.State.Tool != Tool.Line || Host.State.LineDash != StrokeDash.Solid); k++)
        {
            EnsureRailOpen();
            ClickSegment(0);                          // 第一行第 1 段 = 直线
        }
        Check("直线：点它 = 选中直线，当前档是**实线**",
              Host.State.Tool == Tool.Line && Host.State.LineDash == StrokeDash.Solid,
              $"工具 {Host.State.Tool}、档位 {Host.State.LineDash}");
        Check("直线：实线那一档的图标名 = line",
              ui.ShapeIconNameForTest(0) == "line", ui.ShapeIconNameForTest(0));

        Doc.Clear();
        Doc.ClearHistory();
        // 落点和 C 段同一套：画布中上部，别落到屏幕下沿的面板上（那就变成点按钮了）。
        int ldX = (int)(_virtualX + _virtualW * 0.28f);
        int ldY = (int)(_virtualY + _virtualH * 0.42f);
        void DragLine(int x, int y)
        {
            SendMouse(x, y, 0);                                       SettleFrames(60);
            SendMouse(x, y, Native.MOUSEEVENTF_LEFTDOWN);             SettleFrames(60);
            SendMouse(x + 130, y + 60, 0);                            SettleFrames(40);
            SendMouse(x + 260, y + 120, 0);                           SettleFrames(40);
            SendMouse(x + 260, y + 120, Native.MOUSEEVENTF_LEFTUP);   SettleFrames(220);
        }

        // 第一条：实线（用来验 ④"老的那条不受影响"）。
        DragLine(ldX, ldY);
        var oldLine = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
        Check("直线·实线档：新画的直线带**实线**",
              oldLine != null && oldLine.Kind == StrokeKind.Line && oldLine.Dash == StrokeDash.Solid,
              $"对象 {Doc.Strokes.Count} 个，线型 "
              + $"{(oldLine == null ? "（没画出来）" : oldLine.Dash.ToString())}（期望 Solid）");

        // 一轮三档：点一下换一档，图标名跟着换。
        var dashRun = new (StrokeDash want, string icon)[]
        {
            (StrokeDash.Dashed, "lineDash"),
            (StrokeDash.Dotted, "lineDot"),
            (StrokeDash.Solid, "line"),               // 第四下回到实线（一轮闭环）
        };
        for (int k = 0; k < dashRun.Length; k++)
        {
            EnsureRailOpen();
            ClickSegment(0);                          // 再点一次 = 换一档
            Check($"直线：第 {k + 2} 次点 = 换到 {dashRun[k].want}（工具没变）",
                  Host.State.Tool == Tool.Line && Host.State.LineDash == dashRun[k].want,
                  $"工具 {Host.State.Tool}、档位 {Host.State.LineDash}（期望 {dashRun[k].want}）");
            Check($"直线：图标名跟着变成 {dashRun[k].icon}",
                  ui.ShapeIconNameForTest(0) == dashRun[k].icon, ui.ShapeIconNameForTest(0));

            // 第三下（点线）那一档顺手验"画出来真的是点线"——三档各画一条就够说明问题，
            // 不必每档都拖一次（拖一次要等 400 毫秒，这段会白长三倍）。
            if (dashRun[k].want == StrokeDash.Dotted)
            {
                DragLine(ldX, ldY + 200);
                var dotLine = Doc.Strokes.Count == 2 ? Doc.Strokes[1] : null;
                Check("直线·点线档：新画的直线带**点线**",
                      dotLine != null && dotLine.Kind == StrokeKind.Line
                      && dotLine.Dash == StrokeDash.Dotted,
                      $"对象 {Doc.Strokes.Count} 个，线型 "
                      + $"{(dotLine == null ? "（没画出来）" : dotLine.Dash.ToString())}（期望 Dotted）");
                Check("直线：换档**只影响以后画的**，先前那条实线一个字节没动",
                      oldLine != null && oldLine.Dash == StrokeDash.Solid,
                      $"先前那条 = {(oldLine == null ? "（没了）" : oldLine.Dash.ToString())}（期望 Solid）");
            }
        }

        // ⑤ 别的图形不吃这一档：切到矩形再画一条，必须是实线（哪怕直线那格刚切过点线）。
        EnsureRailOpen();
        ClickSegment(1);                              // 第一行第 2 段 = 矩形
        DragLine(ldX, ldY + 400);
        var rectLine = Doc.Strokes.Count == 3 ? Doc.Strokes[2] : null;
        Check("别的图形不吃这一档：矩形画出来仍然是**实线**",
              Host.State.Tool == Tool.Rectangle
              && rectLine != null && rectLine.Kind == StrokeKind.Rectangle
              && rectLine.Dash == StrokeDash.Solid,
              $"对象 {Doc.Strokes.Count} 个，矩形线型 "
              + $"{(rectLine == null ? "（没画出来）" : rectLine.Dash.ToString())}（期望 Solid）");
        Doc.Clear();
        Doc.ClearHistory();

        // ================= A4. 双曲线 / 椭圆（带焦点）那两格：**再点一次换一档** =================
        //
        // 用户 2026-09-22 定的两条（原话）：
        //   · 双曲线"增加两挡，有渐近线和无渐近线？**就是化的时候是都有渐近线，但是最终显示没有**，
        //     图标就按照有渐近线和无渐近线"；
        //   · 椭圆（带焦点）"也有两档，有焦点三角形和没有焦点三角形，焦点三角形顶点在椭圆上，
        //     可以在椭圆上拖动"（"拖 P"那一条在 `--curvetest` 的 ⑤e 里验，这里只管格子）。
        //
        // 两格同构，所以一段里一起验，每格盯四件事：
        //   ① 一轮两档（点第二下换到另一档、第三下转回来）；② 图标名跟着换；
        //   ③ **真的画出来是按那一档**（几何层：`ShowAsymptotes` / `FocusTriangle`）；
        //   ④ 双曲线多一条"**画的过程中一律有渐近线**"——半成品那一位必须是 true，
        //      哪怕当前档是"无"（收口在松手那一刻，见 Engine.EndStroke）。
        Console.WriteLine("  -- A4. 双曲线 / 椭圆（带焦点）：再点一次换一档（各 2 档）--");
        GotoShapeBand();
        int hySeg = InkUi.FullUi.ShapeSegmentIndexForTest(Tool.Hyperbola);          // 按工具名找（不写死段号）
        int ceSeg = InkUi.FullUi.ShapeSegmentIndexForTest(Tool.ConicEllipse);

        // 下面两条**屏幕像素**断言要数品红（照 --curvetest 那一套），所以这一段先换成品红，
        // 段落末尾再换回原来的颜色（后面的 B/C/D 段不该受这一段影响）。
        var colorBeforeA4 = Host.State.PaletteBase;
        Host.Commands.SetColor(new Color4(1f, 0f, 1f, 1f));

        // 渐近线上"离曲线足够远"的一个取样点（照 --pixelerasetest 4b 段那套）＋
        // "数它周围那一小块的品红像素"。**为什么要数像素**：见下面"无渐近线"那条断言
        // ——只查字段的话，"字段对了、屏幕上那两条虚线还留着"这种 bug 照不出来
        //（第一版就是这么漏的，用户一眼就看见了）。
        Vector2 AsymSample(Stroke s)
        {
            var outline = s.ShapeOutline();
            for (int side = -1; side <= 1; side += 2)
            {
                var (from, to) = s.HyperbolaAsymptoteLocal(side);
                for (int k = 1; k < 20; k++)
                {
                    var q = Vector2.Lerp(from, to, k / 20f);
                    float d = float.MaxValue;
                    for (int m = 0; m < outline.Count; m++)
                        if (!Stroke.IsOutlineBreak(outline[m]))
                            d = MathF.Min(d, Vector2.Distance(q, outline[m]));
                    if (d > 14f) return q;
                }
            }
            return new Vector2(float.NaN, float.NaN);
        }
        int InkAt(Vector2 q) => float.IsNaN(q.X)
            ? -1
            : ScreenProbe.CountMagenta((int)q.X - 18, (int)q.Y - 18, 36, 36);

        // 归零到"有渐近线"那一档（最多三下：选中它 / 换一档 / 再换回来）。
        for (int k = 0; k < 3
             && (Host.State.Tool != Tool.Hyperbola || !Host.State.HyperbolaAsymptotes); k++)
        {
            EnsureRailOpen();
            ClickSegment(hySeg);
        }
        Check("双曲线：点它 = 选中它，当前档 = **有渐近线**（默认档）",
              Host.State.Tool == Tool.Hyperbola && Host.State.HyperbolaAsymptotes,
              $"工具 {Host.State.Tool}、档 {Host.State.HyperbolaAsymptotes}");
        Check("双曲线：有渐近线那一档的图标名 = hyperbola（两支 ＋ 两条细斜线）",
              ui.ShapeIconNameForTest(hySeg) == "hyperbola", ui.ShapeIconNameForTest(hySeg));
        Check("双曲线：那一格右边点**2 个档位点**、当前是第 1 个",
              ui.ShapePipsForTest(hySeg) == (2, 0), $"{ui.ShapePipsForTest(hySeg)}");

        // 真机画一条（双曲线是**两笔**：渐近线框 → 曲线经过的点）。
        // `midCheck` 在**两笔之间**跑——那一刻半成品还在引擎手里（没进文档），
        // 正好用来验 ④"画的过程里渐近线一直在"。
        int hyX = (int)(_virtualX + _virtualW * 0.30f);
        int hyY = (int)(_virtualY + _virtualH * 0.34f);
        void DragHyperbola(int x, int y, Action midCheck)
        {
            SendMouse(x, y, 0);                                       SettleFrames(60);
            SendMouse(x, y, Native.MOUSEEVENTF_LEFTDOWN);             SettleFrames(60);
            SendMouse(x + 130, y + 60, 0);                            SettleFrames(40);
            SendMouse(x + 260, y + 120, 0);                           SettleFrames(40);
            SendMouse(x + 260, y + 120, Native.MOUSEEVENTF_LEFTUP);   SettleFrames(160);   // 第 1 笔完
            midCheck();
            // 第 2 笔：**也是一次完整的按下-拖-松手**（照 --curvetest ⑧ 段那套；
            // 只发移动 + 松手是**不算一笔**的——自检第一版就这么写的，画出来 0 个对象）。
            SendMouse(x + 300, y + 80, 0);                            SettleFrames(50);
            SendMouse(x + 300, y + 80, Native.MOUSEEVENTF_LEFTDOWN);   SettleFrames(60);
            SendMouse(x + 330, y + 60, 0);                            SettleFrames(50);
            SendMouse(x + 340, y + 50, Native.MOUSEEVENTF_LEFTUP);     SettleFrames(240);   // 第 2 笔完 → 提交
        }

        Doc.Clear();
        Doc.ClearHistory();
        bool midAsymOn = false, midAsymOff = false;
        DragHyperbola(hyX, hyY, () => midAsymOn = ActiveStroke != null && ActiveStroke.ShowAsymptotes);
        var hyOn = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
        Check("双曲线·有渐近线档：画出来带那两条虚线（ShowAsymptotes = true）",
              hyOn != null && hyOn.Kind == StrokeKind.Hyperbola && hyOn.ShowAsymptotes,
              hyOn == null ? $"对象 {Doc.Strokes.Count} 个（没画出来）"
                           : $"Kind {hyOn.Kind}、渐近线 {hyOn.ShowAsymptotes}（期望 true）");
        Check("双曲线：画的过程中也画渐近线（有那一档，两笔之间为 true）",
              midAsymOn, $"两笔之间 ShowAsymptotes = {midAsymOn}");
        // **屏幕上也真有那两条虚线**（不是只在字段里）：在离曲线 > 14 像素的那段虚线上数品红。
        var qOnAsym = AsymSample(hyOn);
        Doc.InvalidateAll();
        SettleFrames(200);
        int asymInkOn = InkAt(qOnAsym);
        Check("双曲线·有渐近线档：屏幕上**真有**那两条虚线（离曲线 14 像素以外那块有墨）",
              asymInkOn > 20, $"{asymInkOn} 个品红像素（门槛 20）");

        EnsureRailOpen();
        ClickSegment(hySeg);                              // 再点一次 = 换到"无渐近线"
        Check("双曲线：第 2 次点 = 换到**无渐近线**（工具没变）",
              Host.State.Tool == Tool.Hyperbola && !Host.State.HyperbolaAsymptotes,
              $"工具 {Host.State.Tool}、档 {Host.State.HyperbolaAsymptotes}（期望 False）");
        Check("双曲线：图标名跟着变成 hyperbolaNoAsym",
              ui.ShapeIconNameForTest(hySeg) == "hyperbolaNoAsym", ui.ShapeIconNameForTest(hySeg));
        Check("双曲线：档位点跟着移到第 2 个",
              ui.ShapePipsForTest(hySeg) == (2, 1), $"{ui.ShapePipsForTest(hySeg)}");

        Doc.Clear();
        Doc.ClearHistory();
        DragHyperbola(hyX, hyY + 320, () => midAsymOff = ActiveStroke != null && ActiveStroke.ShowAsymptotes);
        var hyOff = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
        Check("双曲线：**无渐近线那一档，画的时候照样有**（向导不能少）",
              midAsymOff, $"两笔之间 ShowAsymptotes = {midAsymOff}（期望 true）");
        Check("双曲线·无渐近线档：画完只剩曲线（ShowAsymptotes = false）",
              hyOff != null && hyOff.Kind == StrokeKind.Hyperbola && !hyOff.ShowAsymptotes,
              hyOff == null ? $"对象 {Doc.Strokes.Count} 个（没画出来）"
                            : $"Kind {hyOff.Kind}、渐近线 {hyOff.ShowAsymptotes}（期望 false）");
        Check("双曲线：换档**只影响以后画的**，先前那条（有渐近线）一个字节没动",
              hyOn != null && hyOn.ShowAsymptotes,
              $"先前那条 = {(hyOn == null ? "（没了）" : hyOn.ShowAsymptotes.ToString())}（期望 true）");
        // ⚠ **这一条才是用户报的那个 bug 的判据**："我选择的不带渐近线的，但是画完以后还有渐近线？"
        // 根因是**改了字段、没让几何缓存失效**（见 Stroke.SetShowAsymptotes）——屏幕上那份
        // "带渐近线"的辅助几何原样留着。**只查字段是绿的**，所以这里必须数屏幕像素：
        // 同一个取样点（在渐近线上、离曲线 > 14 像素），"无"那一档必须**一个墨点都没有**。
        var qOffAsym = AsymSample(hyOff);
        Doc.InvalidateAll();
        SettleFrames(200);
        int asymInkOff = InkAt(qOffAsym);
        Check("双曲线·无渐近线档：画完之后屏幕上**一个虚线墨点都没有**（不是只在字段里）",
              asymInkOff == 0, $"{asymInkOff} 个品红像素（期望 0；非 0 就是缓存没重建）");

        EnsureRailOpen();
        ClickSegment(hySeg);                              // 第三下 = 转回来（一轮闭环）
        Check("双曲线：第 3 次点 = 转回**有渐近线**（两档一轮）",
              Host.State.Tool == Tool.Hyperbola && Host.State.HyperbolaAsymptotes,
              $"工具 {Host.State.Tool}、档 {Host.State.HyperbolaAsymptotes}（期望 true）");

        // ---- 椭圆（带焦点）：两档 = 有 / 无焦点三角形 ----
        for (int k = 0; k < 3
             && (Host.State.Tool != Tool.ConicEllipse || !Host.State.EllipseFocusTriangle); k++)
        {
            EnsureRailOpen();
            ClickSegment(ceSeg);
        }
        Check("椭圆（带焦点）：点它 = 选中它，当前档 = **有焦点三角形**（默认档）",
              Host.State.Tool == Tool.ConicEllipse && Host.State.EllipseFocusTriangle,
              $"工具 {Host.State.Tool}、档 {Host.State.EllipseFocusTriangle}");
        Check("椭圆（带焦点）：那一格的图标名 = ovalFocusTri",
              ui.ShapeIconNameForTest(ceSeg) == "ovalFocusTri", ui.ShapeIconNameForTest(ceSeg));
        Check("椭圆（带焦点）：那一格右边点**2 个档位点**、当前是第 1 个",
              ui.ShapePipsForTest(ceSeg) == (2, 0), $"{ui.ShapePipsForTest(ceSeg)}");
        Check("两格并存：第一行的「椭圆」和这一格是**两个格子、两张图标**（不是同一个）",
              InkUi.FullUi.ShapeSegmentIndexForTest(Tool.Ellipse) != ceSeg
              && ui.ShapeIconNameForTest(InkUi.FullUi.ShapeSegmentIndexForTest(Tool.Ellipse)) == "oval",
              $"「椭圆」段 {InkUi.FullUi.ShapeSegmentIndexForTest(Tool.Ellipse)} 图标 "
              + $"{ui.ShapeIconNameForTest(InkUi.FullUi.ShapeSegmentIndexForTest(Tool.Ellipse))}、"
              + $"「椭圆（带焦点）」段 {ceSeg} 图标 {ui.ShapeIconNameForTest(ceSeg)}");

        int ceX = (int)(_virtualX + _virtualW * 0.30f);
        int ceY = (int)(_virtualY + _virtualH * 0.62f);
        void DragConicEllipse(int x, int y)
        {
            SendMouse(x, y, 0);                                       SettleFrames(60);
            SendMouse(x, y, Native.MOUSEEVENTF_LEFTDOWN);             SettleFrames(60);
            SendMouse(x + 130, y + 60, 0);                            SettleFrames(40);
            SendMouse(x + 260, y + 120, 0);                           SettleFrames(40);
            SendMouse(x + 260, y + 120, Native.MOUSEEVENTF_LEFTUP);   SettleFrames(240);
        }

        Doc.Clear();
        Doc.ClearHistory();
        DragConicEllipse(ceX, ceY);
        var ceOn = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
        Check("椭圆（带焦点）·有三角形档：画出来带焦点三角形（FocusTriangle = true）",
              ceOn != null && ceOn.Kind == StrokeKind.ConicEllipse && ceOn.FocusTriangle,
              ceOn == null ? $"对象 {Doc.Strokes.Count} 个（没画出来）"
                           : $"Kind {ceOn.Kind}、焦点三角形 {ceOn.FocusTriangle}（期望 true）");
        Check("椭圆（带焦点）：焦点 / 三角形走的是**主几何**（虚线辅助槽一笔都没有）",
              ceOn != null && ceOn.InkPieces().Count(pc => pc.Aux) == 0,
              ceOn == null ? "（没画出来）" : $"{ceOn.InkPieces().Count(pc => pc.Aux)} 笔 Aux（期望 0）");

        EnsureRailOpen();
        ClickSegment(ceSeg);                              // 再点一次 = 换到"无焦点三角形"
        Check("椭圆（带焦点）：第 2 次点 = 换到**无焦点三角形**（工具没变）",
              Host.State.Tool == Tool.ConicEllipse && !Host.State.EllipseFocusTriangle,
              $"工具 {Host.State.Tool}、档 {Host.State.EllipseFocusTriangle}（期望 False）");
        Check("椭圆（带焦点）：图标名跟着变成 ovalFocus",
              ui.ShapeIconNameForTest(ceSeg) == "ovalFocus", ui.ShapeIconNameForTest(ceSeg));
        Check("椭圆（带焦点）：档位点跟着移到第 2 个",
              ui.ShapePipsForTest(ceSeg) == (2, 1), $"{ui.ShapePipsForTest(ceSeg)}");

        Doc.Clear();
        Doc.ClearHistory();
        DragConicEllipse(ceX, ceY);
        var ceOff = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
        Check("椭圆（带焦点）·无三角形档：还是画两个焦点、只是不连那两条边（FocusTriangle = false）",
              ceOff != null && ceOff.Kind == StrokeKind.ConicEllipse && !ceOff.FocusTriangle,
              ceOff == null ? $"对象 {Doc.Strokes.Count} 个（没画出来）"
                            : $"Kind {ceOff.Kind}、焦点三角形 {ceOff.FocusTriangle}（期望 false）");
        EnsureRailOpen();
        ClickSegment(ceSeg);                              // 第三下 = 转回来（留给后面 C 段按默认档拖）
        Doc.Clear();
        Doc.ClearHistory();
        Host.Commands.SetColor(colorBeforeA4);            // 品红只借这一段用（见段首注释）

        // ================= A5. 坐标系那格：**再点一次 = 换一档（带网格 / 不带网格）** =========
        //
        // 用户 2026-09-24："那个更多里面现在有一个显示网格，我打算把它挪到图形里面的那个坐标系，
        // ……点一下切换成网格，点一下网格没了。" 于是这一档从「更多」抽屉那一行（**已经拿掉**）
        // 挪到图形面板，**和抛物线 / 直线 / 双曲线 / 椭圆同构**（同一个格再点一次换一档）。
        //
        // 盯四件事：
        //   ① 一轮两档（点第二下换过去，再点一下转回来）；② 图标名跟着换（`axes` / `axesGrid`）；
        //   ③ **档真的落到"下一笔画的坐标系"上**（真手势拖一个，看它的 `Grid`）；
        //   ④ 抽屉里**不再有**那一行（防"挪了没删"——那样两处都能改，用户会以为是两个开关）。
        // ⚠ ③ 之后那一下还要记一条引擎的**分派规则**（原来在抽屉那行上就有的）：
        //   **选中了坐标系 → 改的是选中的那些；没选中 → 才翻"新画的默认值"**。
        Console.WriteLine("  -- A5. 坐标系格：再点一次换一档（带网格 / 不带网格）--");
        GotoShapeBand();
        int axSeg = InkUi.FullUi.ShapeSegmentIndexForTest(Tool.Coordinate);   // 按工具名找（不写死段号）

        // 归零到"不带网格"那一档（最多三下：选中它 / 换一档 / 再换回来）
        for (int k = 0; k < 3
             && (Host.State.Tool != Tool.Coordinate || Host.State.CoordGridDefault); k++)
        {
            EnsureRailOpen();
            ClickSegment(axSeg);
        }
        Check("坐标系：点它 = 选中它，当前档 = **不带网格**（默认档）",
              Host.State.Tool == Tool.Coordinate && !Host.State.CoordGridDefault,
              $"工具 {Host.State.Tool}、档 {Host.State.CoordGridDefault}");
        Check("坐标系：不带网格那一档的图标名 = axes",
              ui.ShapeIconNameForTest(axSeg) == "axes", ui.ShapeIconNameForTest(axSeg));

        EnsureRailOpen();
        ClickSegment(axSeg);                              // 再点一次 = 换一档
        Check("坐标系：第 2 次点 = 换到**带网格**（工具没变）",
              Host.State.Tool == Tool.Coordinate && Host.State.CoordGridDefault,
              $"工具 {Host.State.Tool}、档 {Host.State.CoordGridDefault}（期望 True）");
        Check("坐标系：图标名跟着变成 axesGrid（同一张图多一层细格线）",
              ui.ShapeIconNameForTest(axSeg) == "axesGrid", ui.ShapeIconNameForTest(axSeg));

        // ③ 档落到"下一笔"：真手势拖一个坐标系出来（照 --axistest ① 那套鼠标动作）
        {
            Doc.Clear();
            Doc.ClearHistory();
            float ax0 = _virtualX + 700f, ay0 = _virtualY + 1500f, abw = 700f, abh = 500f;
            SendMouse((int)ax0, (int)ay0, 0);                              SettleFrames(60);
            SendMouse((int)ax0, (int)ay0, Native.MOUSEEVENTF_LEFTDOWN);    SettleFrames(60);
            for (int i = 1; i <= 4; i++)
            {
                SendMouse((int)(ax0 + abw * i / 4f), (int)(ay0 + abh * i / 4f), 0);
                SettleFrames(30);
            }
            SendMouse((int)(ax0 + abw), (int)(ay0 + abh), Native.MOUSEEVENTF_LEFTUP); SettleFrames(220);
            var axOn = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
            Check("坐标系：带网格那一档画出来的坐标系**真的带网格**（Grid = true）",
                  axOn != null && axOn.Kind == StrokeKind.Coordinate && axOn.Grid,
                  axOn == null ? "没有对象" : $"Kind {axOn.Kind}、网格 {axOn.Grid}（期望 true）");
            // 网格比轴线细一半、淡一半：几何是**两段**（主几何只有轴线，网格走辅助槽）——
            // 这是 2026-09-24 "变细变淡" 的落点，也是"一个几何只能有一种描边"的直接后果。
            Check("坐标系：网格自成一笔身份、单独一段几何（细/淡就是这么落地的）",
                  axOn != null && axOn.InkPieces().Any(p => p.Grid)
                  && axOn.BuildAuxGeometry(Gfx.D2DFactory) != null,
                  axOn == null ? "没有对象"
                               : $"网格笔数 {axOn.InkPieces().Count(p => p.Grid)}、"
                                 + $"辅助几何 {(axOn.BuildAuxGeometry(Gfx.D2DFactory) != null ? "有" : "无")}");

            // 第 3 次点：⚠ 刚才画出来的那个**还选中着**（画完自动选中），于是按引擎的分派规则
            //（`ToggleSelectionGrid`：**选中了就改它们、没选中才翻"新画的默认值"**）
            // 这一下改的是**那个对象**，默认档不动。这正是老师的实际用法：
            // 画完发现"这个要格子" → 再点一下这一格就给它加上（日志会印"1 个对象 → 关"）。
            EnsureRailOpen();
            ClickSegment(axSeg);
            Check("坐标系：刚画完那个还选中着 → 这一点改的是**它**（默认档不动）",
                  axOn != null && !axOn.Grid && Host.State.CoordGridDefault,
                  $"对象网格 {axOn?.Grid}、默认档 {Host.State.CoordGridDefault}（期望 False / True）");

            // 第 4 下：**清掉选中**再点 → 才轮到"新画的默认值"（转回不带网格，留给后面的段）
            Doc.Clear();
            Doc.ClearHistory();
            Doc.SelectOnly(Array.Empty<Stroke>());
            SettleFrames(120);
            EnsureRailOpen();
            ClickSegment(axSeg);
            Check("坐标系：没选中任何东西时，这一点翻的是**新画的默认值**（转回不带网格）",
                  !Host.State.CoordGridDefault, $"档 {Host.State.CoordGridDefault}（期望 False）");
        }

        // ④ 「更多」抽屉里**不该再有**「坐标系网格」那一行（按标签找，找不到 = 空矩形）
        {
            var staleRow = ui.RowRectByLabelForTest("坐标系网格");
            Check("更多抽屉：**没有**「坐标系网格」那一行了（挪走了就删干净）",
                  staleRow.MaxY <= staleRow.MinY,
                  $"找到的行高 {staleRow.MaxY - staleRow.MinY:F0}（期望 0）");
        }

        // ================= B. 图形**一个热键都没有**（用户 2026-09-19 定）=================
        //
        // 用户原话："图形不需要加快捷键，通通取消掉"。原来给圆 / 三角形 / 平行四边形 /
        // 坐标系 / 数轴 配过 `Ctrl+Alt+O/T/G/F/N`，这一轮全撤——它们的入口就是上面那 8 段。
        //
        // 判据分两层，缺一层都可能"看着绿其实没撤干净"：
        //   ① **对表查**：那五个组合在任何作用域里都不许再绑着动作；
        //   ② **真按一次**：合成键盘发一个 `Ctrl+Alt+O`，工具**不许**变——
        //      这一层防的是"表里删了、注册那一路还留着"。
        Console.WriteLine("  -- B. 图形一个热键都没有 --");
        var retired = new (string chord, ushort vk)[]
        {
            ("Ctrl+Alt+O", 'O'), ("Ctrl+Alt+T", 'T'), ("Ctrl+Alt+G", 'G'),
            ("Ctrl+Alt+F", 'F'), ("Ctrl+Alt+N", 'N'),
        };
        foreach (var (chord, vk) in retired)
        {
            var c = new KeyChord(KeyChord.ModCtrl | KeyChord.ModAlt, vk);
            var hit = Keys.Bindings.FirstOrDefault(b => b.Chord.Equals(c));
            Check($"退役键 {chord} 不再绑任何动作", hit == null,
                  hit == null ? "表里没有这一条"
                              : $"还绑着「{KeyMap.Describe(hit.Action)}」（{hit.Scope}）");
        }

        Host.Commands.SetTool(Tool.Line);
        SettleFrames(150);
        SendCtrlAlt('O');
        SettleFrames(400);
        Check("真按一次 Ctrl+Alt+O：工具一动不动（图形确实没有键了）",
              Host.State.Tool == Tool.Line,
              $"工具 = {Host.State.Tool}（期望 Line）");

        // ================= C. **每一个有入口的图形**都真拖一笔，画出来就是那一种 =================
        //
        // ⚠ 这一段原来是**抽查 6 个**（"每次拖拽要等几帧，省时间"），结果正好漏在
        // 棱锥 / 棱台身上（用户："锥体和台体只能画四棱"）。省下的那几秒，换来的是
        // **一个图形入口整整没走过一遍**——不值。现在**逐段全拖**：
        // 判据表就是上面那张 `want`（有入口的那些），一个都跑不掉。
        //
        // 两件事**不再由人写**（写了就会跟不上）：
        //   · **拖几笔** → 问引擎 `ShapeStepCount(tool)`（它是从那张三笔表算出来的）；
        //   · **段号** → 问界面 `ShapeSegmentIndexForTest(tool)`。
        Console.WriteLine($"  -- C. 逐个图形真拖一笔（{want.Length} 个）：StrokeKind 就是那一种 --");
        // 落点在画布中上部：面板在屏幕下沿，别画到面板上（那就变成点按钮了）。
        //
        // ⚠ 格子是"每行 4 个、行距 120"**从上面往下排**的，所以**图形越多、最后几个越靠下** ——
        // 2026-09-20 第十六批加到 21 个时，最后那格正好排进了面板（症状是"对象 0 个"，
        // 看着像功能坏了）。所以起点取在画布 30% 高处、行距收紧到 120：
        // 21 个图形最底下一格的落点是 `0.30 × 1800 ＋ 5 × 120 ＝ 1140`，
        // 再加拖出去的 120 也才 1260，离下沿的面板还有一大截。
        int dragX = (int)(_virtualX + _virtualW * 0.28f);
        int dragY = (int)(_virtualY + _virtualH * 0.30f);
        for (int i = 0; i < want.Length; i++)
        {
            var d = want[i];
            Doc.Clear();
            Doc.ClearHistory();
            GotoShapeBand();
            ClickSegment(InkUi.FullUi.ShapeSegmentIndexForTest(d.tool));

            // 一个图形一格（互相别叠上），按引擎说的**笔数**一笔一笔拖
            int x = dragX + (i % 4) * 260, y = dragY + (i / 4) * 120;
            int steps = ShapeStepCount(d.tool);
            for (int k = 0; k < steps; k++)
            {
                // 第 1 笔拖 260×120（比"太短不产生对象"的阈值大得多）；第 2 笔（多笔图形的
                // "方向 / 深度 / 顶上那个中心"）拖 160×40——和 --prismtest 那套最短两笔同一个口径。
                int dx = k == 0 ? 260 : 160, dy = k == 0 ? 120 : 40;
                SendMouse(x, y, 0);                                    SettleFrames(60);
                SendMouse(x, y, Native.MOUSEEVENTF_LEFTDOWN);           SettleFrames(60);
                SendMouse(x + dx / 2, y + dy / 2, 0);                   SettleFrames(40);
                SendMouse(x + dx, y + dy, 0);                           SettleFrames(40);
                SendMouse(x + dx, y + dy, Native.MOUSEEVENTF_LEFTUP);   SettleFrames(k + 1 < steps ? 120 : 220);
            }

            var s = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
            var kindWant = KindOfShapeTool(d.tool);      // 期望值**从引擎问**，不再表里再抄一遍
            Check($"「{d.name}」：点段选的工具、拖 {steps} 笔，画出来就是它",
                  Host.State.Tool == d.tool && s != null && s.Kind == kindWant,
                  $"工具 = {Host.State.Tool}，对象 {Doc.Strokes.Count} 个，"
                  + $"Kind = {(s == null ? "（一个对象都没有）" : s.Kind.ToString())}"
                  + $"（期望 {kindWant}）");
        }
        Doc.Clear();
        Doc.ClearHistory();

        // ================= D. 主条那一格的图标跟着种类变 =================
        Console.WriteLine("  -- D. 主条「图形」那一格的图标跟着当前种类变 --");
        var icons = new List<string>();
        foreach (var (tool, name) in want)
        {
            Host.Commands.SetTool(tool);
            SettleFrames(120);
            string icon = ui.CellIconForTest(8);
            bool changed = icons.Count == 0 || icon != icons[icons.Count - 1];
            Check($"「{name}」那一格的图标 = {icon}", changed,
                  changed
                      ? $"（上一种是 {(icons.Count == 0 ? "还没切过" : icons[icons.Count - 1])}）"
                      : $"和上一种「{icons[icons.Count - 1]}」是同一张图——切了种类图标没跟着变");
            icons.Add(icon);
        }
        Check("十二种图形的图标两两不同",
              icons.Distinct().Count() == want.Length, string.Join(" → ", icons));

        // ---- D2. 没选中图形工具时，这一格画的是**通用图标** ----
        //
        // 用户 2026-09-22 定："图形图标在未选中时，默认使用最初始的圆框（Fluent 官方
        // 通用的图标）；当选中它并再选中一个具体图形时，图标就显示为矩形。"
        // 判据必须和绘制同一条（`FullUi` 里那句 `active ? ShapeIcon : Cells[8].Icon`），
        // 所以这里挑几个**不是图形**的工具，逐个问一遍——它们都不该画成某一种具体图形。
        Console.WriteLine("  -- D2. 没选中图形工具 → 这一格回到通用图标 --");
        foreach (var t in new[] { Tool.Pen, Tool.Eraser, Tool.Marquee, Tool.Capture })
        {
            Host.Commands.SetTool(t);
            SettleFrames(120);
            string icon = ui.CellIconForTest(8);
            Check($"手里是{t}时，图形那一格画通用图标",
                  icon == "shapes", $"画的是 {icon}（期望 shapes）");
        }
        // 再切回一种图形：必须**立刻**回到那一种（不是"切走了就再也不跟着变"）。
        Host.Commands.SetTool(Tool.Rectangle);
        SettleFrames(120);
        Check("切回矩形：图标立刻跟着回到矩形",
              ui.CellIconForTest(8) == "square", $"画的是 {ui.CellIconForTest(8)}（期望 square）");
        // 这一段是**真渲染过的**：图标名一旦拼错，`IconAtlas.Draw` 会当场抛
        // （那条"绝不画一个空图标了事"的规矩），所以它同时就是
        // "自绘的图标（oval / parallelogram / axes / parabola / hyperbola / sine / cosine
        // 那几张）画得出来"的判据——它们在图标库里不存在，
        // `ShapeIconFor` 里名字写错了只会在这里露出来。

        Console.WriteLine($"  结果: {pass} 项通过, {fail} 项失败");
        ExitCode = fail == 0 ? 0 : 1;
        _quit = true;
    }

    /// <summary>
    /// Three long strokes, then a deliberately coarse vertical swipe with the
    /// eraser. Without path interpolation the sample spacing leaves gaps and
    /// strokes in between survive, which is the "eraser is not sensitive"
    /// symptom. Also checks the whole swipe collapses into one undo step.
    /// </summary>
    /// <summary>
    /// Draws the same wavy stroke at every width preset and measures how much
    /// ink actually lands. A filled ribbon can collapse if the winding rule
    /// cancels where the shape folds over itself, which shows up as a coverage
    /// ratio far below 1 - and it only appears once strokes get fat.
    /// </summary>
    /// <summary>
    /// 指针形状自检：把"设备 × 工具 × 悬停目标 × 是否拖拽"这张表逐条算出来，
    /// 跟期望值比对。
    ///
    /// 为什么值得写成自检：光标这类东西**漏一个状态很难靠肉眼发现**——
    /// 典型的是"拖拽中突然变回箭头"，只有真去拖一遍才会看到。这里把状态
    /// 直接构造出来，一条命令跑完全部组合。
    ///
    /// 只验"该显示什么"（纯计算，不碰系统）。"系统真的显示出来了"要另开
    /// 一个进程读 GetCursorInfo，那是端到端测试的事。
    /// </summary>
    private void CursorTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 指针形状自检（状态 → 光标）===");
        Console.WriteLine($"  系统指针尺寸 {CursorSizePx}px   DPI 缩放 {DpiScale:F2}");
        Console.WriteLine();

        int pass = 0, fail = 0;

        void Check(string name, CursorKind want)
        {
            var got = ComputeCursorKind();
            bool ok = got == want;
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-34} 期望 {Cursors.Name(want),-24} 实际 {Cursors.Name(got)}");
        }

        void CheckBool(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-34} {detail}");
        }

        // 准备一份真实的选区：三笔横线，全选。
        Doc.Clear();
        for (int i = 0; i < 3; i++)
        {
            var s = new Stroke { Tool = Tool.Pen, Color = new Color4(0f, 0f, 0f, 1f), Width = 6f * DpiScale };
            float y = 500 + i * 140;
            for (int k = 0; k <= 60; k++) s.AddPoint(600 + k * 14, y, 1f, NowMs);
            Doc.AddStroke(s);
        }
        Doc.InvalidateAll();

        PassThrough = false;
        PointerInside = true;
        LastPointerType = Native.PT_MOUSE;
        Doc.Selected.Clear();
        Tool = Tool.Pen;
        PointerX = 100; PointerY = 100;

        // ---- 输入设备 × 工具 ----
        // 规则（2026-09-27 更新，用户报"手写板书写时光标消失"之后定的）：
        //   · 鼠标 / 手写板 → **一路给斜笔**（自绘彩笔：热点在笔尖、跟墨色/笔宽）；
        //   · 触摸屏自带的笔（笔尖就压在屏幕上）→ 藏系统光标，落点由自绘环表达，
        //     落笔后连环也不画（笔尖本身就是最准的落点）；
        //   · 触摸 → 什么都不显示。
        // 判据是 PenDeviceOnScreen（设备出身：INTEGRATED_PEN vs EXTERNAL_PEN，见引擎注释）。
        Check("画笔 · 鼠标悬停（斜笔）", CursorKind.Pen);
        CheckBool("画笔 · 鼠标下不叠自绘环（斜笔本身就是落点）",
            DrawnCursor == ToolCursorShape.None, $"DrawnCursor={DrawnCursor}");

        LastPointerType = Native.PT_PEN;
        PenDeviceOnScreen = false;      // 手写板：笔尖在板子上，不在屏幕里
        Check("画笔 · 手写板悬停（斜笔）", CursorKind.Pen);
        CheckBool("画笔 · 手写板悬停不叠自绘环",
            DrawnCursor == ToolCursorShape.None, $"DrawnCursor={DrawnCursor}");

        PenDeviceOnScreen = true;       // 触摸屏自带笔：笔尖即落点
        Check("画笔 · 触屏笔悬停（藏系统光标，落点自己画）", CursorKind.Hidden);
        CheckBool("画笔 · 触屏笔悬停画圆环",
            DrawnCursor == ToolCursorShape.Ring, $"DrawnCursor={DrawnCursor}");

        PenDeviceOnScreen = false;      // 之后默认按手写板走（谁要测触屏笔谁自己设 true）
        LastPointerType = Native.PT_TOUCH;
        Check("触摸（不显示指针）", CursorKind.Hidden);

        LastPointerType = Native.PT_MOUSE;
        Tool = Tool.Highlighter;
        Check("荧光笔 · 悬停", CursorKind.Hidden);
        CheckBool("荧光笔 · 落点是圆盘（直径 = 笔宽）",
            DrawnCursor == ToolCursorShape.Disc,
            $"DrawnCursor={DrawnCursor}");

        Tool = Tool.Eraser;
        Check("橡皮 · 悬停", CursorKind.Hidden);
        CheckBool("橡皮 · 落点是圆环（半径跟着橡皮半径走）",
            DrawnCursor == ToolCursorShape.Ring && DrawnCursorRadius > 0f,
            $"DrawnCursor={DrawnCursor} 半径={DrawnCursorRadius:F0}px");

        // ---- 笔尾橡皮（倒持的笔）：悬停就要按橡皮显示（用户 2026-09-27 报的）----
        //
        // 落笔分派早就按"倒持 = 橡皮"走了（OnPointerDown / OnPointerMove 里的
        // `inverted ? Tool.Eraser : Tool`），光标当时没跟上——笔尾悬停在画布上，
        // 屏幕上还是斜笔 / 笔尖环，看不出"这一头是橡皮、会擦掉多大一块"。
        // 现在光标这一族问的是 EffectiveTool（判据只写一处）。
        Tool = Tool.Pen;
        LastPointerType = Native.PT_PEN;
        PenDeviceOnScreen = false;                 // 手写板的笔
        LastPointerInverted = true;                // 倒过来拿：笔尾（橡皮头）朝下
        Check("笔尾（倒持）· 悬停 = 橡皮光标（藏起来，落点自己画）", CursorKind.Hidden);
        CheckBool("笔尾 · 落点是圆环（不是斜笔）",
            DrawnCursor == ToolCursorShape.Ring, $"DrawnCursor={DrawnCursor}");
        CheckBool("笔尾 · 圆环半径 = 橡皮半径（和真的会擦掉的范围一致）",
            Math.Abs(CursorOuterRadius - EraserRadius) < 0.01f,
            $"外圈 {CursorOuterRadius:F1}px，橡皮半径 {EraserRadius:F1}px");
        _drawing = true;                           // 正用笔尾擦着
        CheckBool("笔尾 · 擦除中圆环一直画", DrawnCursor == ToolCursorShape.Ring, $"{DrawnCursor}");
        _drawing = false;
        LastPointerInverted = false;               // 笔正过来拿：立刻回到斜笔
        Check("笔正过来 · 悬停回到斜笔", CursorKind.Pen);
        CheckBool("笔正过来 · 不再画圆环", DrawnCursor == ToolCursorShape.None, $"{DrawnCursor}");

        LastPointerType = Native.PT_PEN;
        Tool = Tool.Pen;
        PenDeviceOnScreen = true;
        CheckBool("触屏笔 · 悬停时笔画环", DrawnCursor == ToolCursorShape.Ring, $"DrawnCursor={DrawnCursor}");
        PenDeviceOnScreen = false;
        CheckBool("手写板 · 悬停时给斜笔、不画环",
            DrawnCursor == ToolCursorShape.None, $"DrawnCursor={DrawnCursor}");
        LastPointerType = Native.PT_MOUSE;

        Tool = Tool.Laser;
        Check("激光笔 · 悬停", CursorKind.Hidden);
        CheckBool("激光笔 · 落点是实心点",
            DrawnCursor == ToolCursorShape.Dot, $"DrawnCursor={DrawnCursor}");
        Tool = Tool.Marquee;
        Check("框选 · 空白处", CursorKind.Cross);

        // ---- 截图 vs 框选/图形：**光标必须能分开** ----
        //
        // 用户 2026-09-17："截图图标和选中图标一样的，是不是不大好？"——
        // 随即澄清是**鼠标光标**：截图/框选/图形原来共用一个系统十字，
        // 老师分不出"我现在是要截图还是要选框"。
        // 现在截图有自己的**取景框**落点（四角括号 + 中心小十字），框选/图形仍是十字。
        Tool = Tool.Capture;
        Check("截图 · 系统光标藏起来（落点自己画）", CursorKind.Hidden);
        CheckBool("截图 · 落点是取景框（不是十字）",
            DrawnCursor == ToolCursorShape.Frame && DrawnCursorRadius > 0f,
            $"DrawnCursor={DrawnCursor} 脏区半径={DrawnCursorRadius:F0}px");
        _drawing = true;
        CheckBool("截图 · 拖动中也画（正在框的那一块要看得见）",
            DrawnCursor == ToolCursorShape.Frame, $"{DrawnCursor}");
        _drawing = false;
        Tool = Tool.Rectangle;
        Check("图形 · 仍是十字准星", CursorKind.Cross);
        CheckBool("图形 · 不画自绘落点", DrawnCursor == ToolCursorShape.None, $"{DrawnCursor}");
        Tool = Tool.Marquee;

        // ---- 书写中：**手写板的光标不能消失**（用户 2026-09-27 报的手感 bug）----
        _drawing = true;
        LastPointerType = Native.PT_MOUSE;
        Tool = Tool.Pen;         CheckBool("鼠标书写中 · 斜笔一路跟着（不叠自绘环）", DrawnCursor == ToolCursorShape.None, $"{DrawnCursor}");
        Tool = Tool.Highlighter; CheckBool("鼠标书写中 · 圆盘跟着走", DrawnCursor == ToolCursorShape.Disc, $"{DrawnCursor}");
        Tool = Tool.Laser;       CheckBool("鼠标书写中 · 点跟着走", DrawnCursor == ToolCursorShape.Dot, $"{DrawnCursor}");

        // 手写板：笔尖在板子上、不在屏幕里，**屏幕上必须留着指示**——
        // 这一组就是这次用户报的 bug（"光标消失、不流畅"）的回归钉子。
        LastPointerType = Native.PT_PEN;
        PenDeviceOnScreen = false;
        Tool = Tool.Pen;
        Check("手写板书写中 · 斜笔光标留着（不消失）", CursorKind.Pen);
        CheckBool("手写板书写中 · 斜笔就是指示、不叠自绘环",
            DrawnCursor == ToolCursorShape.None, $"{DrawnCursor}");
        Tool = Tool.Highlighter;
        CheckBool("手写板书写中 · 荧光笔圆盘留着（宽度要看得见）",
            DrawnCursor == ToolCursorShape.Disc, $"{DrawnCursor}");
        Tool = Tool.Laser;
        CheckBool("手写板书写中 · 激光点留着", DrawnCursor == ToolCursorShape.Dot, $"{DrawnCursor}");

        // 触屏笔：笔尖就压在屏幕上，落笔后不画（保持 2026-09 的定案：笔尖即落点）
        PenDeviceOnScreen = true;
        Tool = Tool.Pen;         CheckBool("触屏笔落笔后 · 不画（笔尖即落点）", DrawnCursor == ToolCursorShape.None, $"{DrawnCursor}");
        Tool = Tool.Highlighter; CheckBool("触屏笔落笔后 · 荧光笔也不画", DrawnCursor == ToolCursorShape.None, $"{DrawnCursor}");
        PenDeviceOnScreen = false;
        Tool = Tool.Eraser;      CheckBool("橡皮擦除中 · 一直画（范围要看得见）", DrawnCursor == ToolCursorShape.Ring, $"{DrawnCursor}");
        _drawing = false;
        LastPointerType = Native.PT_MOUSE;

        // ---- 粗细 → 落点反馈 ----
        // ⚠ 2026-09-27 起：鼠标 / 手写板改用系统斜笔，**自绘环这条路只剩触屏笔**——
        // 所以这一段显式按"触屏笔"测（环的内圈 / 外圈 / 脏区仍然要跟着笔宽走）。
        LastPointerType = Native.PT_PEN;
        PenDeviceOnScreen = true;
        Tool = Tool.Pen;
        // 取**档位表里的**最细 / 最粗两档，不写死数字：写死的话表一改（2026-09-27
        // 最细档就从 1.5 降到了 1）这里会静默量错值（同"写死常量会随功能移位而静默失效"那条教训）。
        PenWidthLogical = WidthPresets[0];
        float thinTrue = CursorRingTrueRadius, thinOuter = CursorOuterRadius;
        float thinDirty = DrawnCursorRadius;
        PenWidthLogical = WidthPresets[^1];
        float fatTrue = CursorRingTrueRadius, fatOuter = CursorOuterRadius;
        CheckBool("笔 · 内圈跟着真实笔宽变",
            fatTrue > thinTrue * 10f,
            $"{WidthPresets[0]} → {thinTrue:F1}px，{WidthPresets[^1]} → {fatTrue:F1}px（半径）");
        CheckBool("笔 · 细笔有外圈兜底（看得见落点）",
            thinOuter > thinTrue && Math.Abs(thinOuter - 6f * DpiScale) < 0.01f,
            $"真半径 {thinTrue:F1}px，外圈 {thinOuter:F1}px（下限 {6f * DpiScale:F1}px）");
        CheckBool("笔 · 粗笔时内外圈合一",
            fatOuter <= fatTrue + 0.01f, $"外圈 {fatOuter:F1}px，真半径 {fatTrue:F1}px");
        CheckBool("笔 · 脏区跟着落点反馈放大",
            DrawnCursorRadius > thinDirty, $"{thinDirty:F0}px → {DrawnCursorRadius:F0}px");
        LastPointerType = Native.PT_MOUSE;
        PenDeviceOnScreen = false;

        float penBefore = PenWidthLogical, hlBefore = HighlighterWidthLogical;
        Tool = Tool.Highlighter;
        HighlighterWidthLogical = 8f;
        float thinDisc = CursorRingTrueRadius;
        float thinDiscDirty = DrawnCursorRadius;
        HighlighterWidthLogical = 32f;
        CheckBool("荧光笔 · 圆盘半径就是半个笔宽",
            Math.Abs(thinDisc - 8f * DpiScale * 0.5f) < 0.01f
            && Math.Abs(CursorRingTrueRadius - 32f * DpiScale * 0.5f) < 0.01f,
            $"8 → 半径 {thinDisc:F1}px，32 → {CursorRingTrueRadius:F1}px");
        CheckBool("荧光笔 · 脏区盖得住圆盘（含描边）",
            DrawnCursorRadius > CursorRingTrueRadius,
            $"脏区 {DrawnCursorRadius:F0}px > 圆盘 {CursorRingTrueRadius:F0}px");
        CheckBool("荧光笔 · 脏区跟着荧光笔宽变",
            DrawnCursorRadius > thinDiscDirty,
            $"{thinDiscDirty:F0}px → {DrawnCursorRadius:F0}px（脏区半径）");
        HighlighterWidthLogical = hlBefore;

        Tool = Tool.Laser;
        // ⚠ 设值要**连索引一起设**：切粗细（CycleWidth）是按索引走的，只改
        // LaserWidthLogical 不改 LaserWidthIndex 的话，后面"切粗细"那条用例会撞上
        // 同一个值直接判红（2026-09-27 把档位改成 8/14/22 时就这么红过一次）。
        LaserWidthIndex = 0;
        LaserWidthLogical = LaserWidthPresets[0];            // 最细档
        float thinDot = DrawnCursorRadius;
        LaserWidthIndex = LaserWidthPresets.Length - 1;
        LaserWidthLogical = LaserWidthPresets[^1];           // 最粗档
        CheckBool("激光笔 · 点跟着激光宽变",
            DrawnCursorRadius > thinDot, $"{thinDot:F0}px → {DrawnCursorRadius:F0}px");

        // ---- 切粗细改的是**当前工具**那一档（这条是 bug 回归）----
        Tool = Tool.Laser;
        float laserBefore = LaserWidthLogical;
        CycleWidth();
        CheckBool("切粗细 · 激光改的是激光宽", LaserWidthLogical != laserBefore
                  && Math.Abs(PenWidthLogical - penBefore) < 1e-4f,
                  $"激光 {laserBefore} → {LaserWidthLogical}，笔宽保持 {PenWidthLogical}");
        Tool = Tool.Highlighter;
        float hlBefore2 = HighlighterWidthLogical;
        CycleWidth();
        CheckBool("切粗细 · 荧光笔改的是荧光笔宽", HighlighterWidthLogical != hlBefore2
                  && Math.Abs(PenWidthLogical - penBefore) < 1e-4f,
                  $"荧光笔 {hlBefore2} → {HighlighterWidthLogical}，笔宽保持 {PenWidthLogical}");
        Tool = Tool.Pen;
        float penBefore2 = PenWidthLogical;
        float hlAfterCycle = HighlighterWidthLogical;
        CycleWidth();
        CheckBool("切粗细 · 笔改的是笔宽", Math.Abs(PenWidthLogical - penBefore2) > 1e-4f
                  && Math.Abs(HighlighterWidthLogical - hlAfterCycle) < 1e-4f,
                  $"笔 {penBefore2} → {PenWidthLogical}");
        // 复位成常用值，后面的用例不受影响（激光要连索引一起复位——见上面那条警告；
        // 写死的 4f 已经不是合法档位了，会留下"值不在档位表里"的隐性不一致）
        PenWidthLogical = 3f; HighlighterWidthLogical = 18f;
        LaserWidthIndex = 0; LaserWidthLogical = LaserWidthPresets[0];

        // ---- 选中框：八个手柄 + 旋转 + 整体拖动 + 操作条 ----
        Doc.Selected.Clear();
        foreach (var s in Doc.Strokes) Doc.Selected.Add(s);
        Tool = Tool.Marquee;

        var frame = SelectionHandles.FrameOf(Doc.Selected);
        float dpi = DpiScale;
        var aabb = frame.CanvasAabb;

        void At(SelHandle h)
        {
            var p = SelectionHandles.CanvasPosition(h, frame, dpi);
            PointerX = p.X; PointerY = p.Y;
        }

        At(SelHandle.Left);        Check("选中框 · 左边中点（左右拉伸）", CursorKind.ResizeWE);
        At(SelHandle.Right);       Check("选中框 · 右边中点（左右拉伸）", CursorKind.ResizeWE);
        At(SelHandle.Top);         Check("选中框 · 上边中点（上下拉伸）", CursorKind.ResizeNS);
        At(SelHandle.Bottom);      Check("选中框 · 下边中点（上下拉伸）", CursorKind.ResizeNS);
        At(SelHandle.TopLeft);     Check("选中框 · 左上角（对角）", CursorKind.ResizeNWSE);
        At(SelHandle.BottomRight); Check("选中框 · 右下角（对角）", CursorKind.ResizeNWSE);
        At(SelHandle.TopRight);    Check("选中框 · 右上角（对角）", CursorKind.ResizeNESW);
        At(SelHandle.BottomLeft);  Check("选中框 · 左下角（对角）", CursorKind.ResizeNESW);
        At(SelHandle.Rotate);      Check("选中框 · 旋转手柄", CursorKind.Rotate);

        PointerX = (aabb.MinX + aabb.MaxX) * 0.5f;
        PointerY = (aabb.MinY + aabb.MaxY) * 0.5f;
        Check("选中框 · 框内（整体移动）", CursorKind.Move);

        var b0 = SelectionHandles.BarButtonRect(0, aabb, dpi, ViewportCanvas);
        PointerX = (b0.MinX + b0.MaxX) * 0.5f;
        PointerY = (b0.MinY + b0.MaxY) * 0.5f;
        Check("操作条按钮（不换光标）", CursorKind.Default);

        // **按下中（_drawing=true）也要保持箭头**——用户 2026-09-27 报的
        // "悬浮过去是鼠标、点一下它又变成十字了"。
        // 根因：`OnPointerDown` 在"这一下归谁"分流**之前**就设了 `_drawing = true` 并调了
        // ApplyCursor，按下的那一帧光标落到 ToolCursorKind（框选 = 十字）。
        // 这里把那个瞬间的状态直接构造出来钉住：框选工具 + 按下中 + 指针在条上。
        _drawing = true;
        Check("操作条 · 按下中仍是箭头（不是十字）", CursorKind.Default);
        _drawing = false;

        // ---- 操作条**整块**都是"界面"（用户 2026-09-17 报的）----
        //
        // "操作对应图标的时候一会是十字光标，一会是箭头图标"——原来只认按钮本体，
        // 按钮之间的分隔线、两头的留白都退回工具光标（框选是十字），
        // 鼠标在条上横着滑过去就是 箭头／十字／箭头／十字。
        {
            var bar = SelectionHandles.BarRect(aabb, dpi, ViewportCanvas);
            // 条**尾部那段留白**（最后一格右边到条右端）：一定不在任何按钮上。
            // 注：九格是**紧挨着**排的（BarGapLogical = 0，靠分隔线分区），所以
            // "两格之间"其实是共用一条边，那里算前一个按钮；真正露在外面的
            // 只有条两端的 6 逻辑像素留白，也正是原来会漏出十字的地方。
            var last = SelectionHandles.BarButtonRect(SelectionHandles.BarButtonCount - 1,
                                                      aabb, dpi, ViewportCanvas);
            PointerX = (last.MaxX + bar.MaxX) * 0.5f;
            PointerY = (bar.MinY + bar.MaxY) * 0.5f;
            CheckBool("（先确认那个点真的不在按钮上）",
                SelectionHandles.BarButtonAt(PointerX, PointerY, aabb, dpi, ViewportCanvas) == -1
                && PointerX < bar.MaxX, "不在按钮上、但在条里");
            Check("操作条 · 条内留白（箭头，不是十字）", CursorKind.Default);

            // 挂在下头的小面板：整块也是界面，面板的空白处同样是箭头
            SelPanelOpen = SelPanel.Layer;
            var pnl = SelectionHandles.LayerPanelRect(aabb, dpi, ViewportCanvas);
            PointerX = pnl.MinX + 3f; PointerY = pnl.MaxY - 3f;      // 面板的内边距
            Check("层级面板 · 面板空白处（箭头）", CursorKind.Default);
            var cell0 = SelectionHandles.LayerCellRect(0, aabb, dpi, ViewportCanvas);
            PointerX = (cell0.MinX + cell0.MaxX) * 0.5f;
            PointerY = (cell0.MinY + cell0.MaxY) * 0.5f;
            Check("层级面板 · 置顶那格（箭头）", CursorKind.Default);
            SelPanelOpen = SelPanel.None;

            // 收起态那颗圆钮也一样
            SelBarCollapsed = true;
            var dot = SelectionHandles.BarCollapsedRect(aabb, dpi, ViewportCanvas);
            PointerX = (dot.MinX + dot.MaxX) * 0.5f;
            PointerY = (dot.MinY + dot.MaxY) * 0.5f;
            Check("操作条收起态的圆钮（箭头）", CursorKind.Default);
            SelBarCollapsed = false;
        }

        PointerX = aabb.MinX - 120f * dpi; PointerY = aabb.MinY - 120f * dpi;
        Check("选中框外的空白（重新框选）", CursorKind.Cross);

        // ---- 图库面板（自绘界面块）：光标**不许取决于"来路"**（2026-09-27 修）----
        //
        // 病根：图库面板不在"接输入小窗"里，它的悬停分支以前只调 ApplyCursor、
        // 没有任何地方更新"指针在界面上"这个状态，于是同一块面板上的光标取决于**从哪边进来**：
        //   从工具条过来（_uiHover=true）→ 箭头 ✔；从画布直入（_uiHover=false）→ 工具光标（十字）✘。
        // 现在判据收成一条 PointerOnDrawnChrome（纯几何），两种情况必须一样：箭头 + 不画落点。
        {
            LibraryPanelOpen = true;
            var panel = LibraryPanelRectNow();
            PointerX = panel.MinX + 12f; PointerY = panel.MinY + 12f;    // 面板里（左上内边距处）

            // ① 框选工具：画布上是十字，最容易暴露"来路差异"——面板里必须是箭头
            Tool = Tool.Marquee;
            _uiHover = false;                          // 从画布直入（bug 现场）
            Check("图库面板 · 框选工具直入也是箭头", CursorKind.Default);
            _uiHover = true;                           // 从工具条进入（老路，钉住"两条路一致"）
            Check("图库面板 · 从工具条进入还是箭头", CursorKind.Default);

            // ② 橡皮：画布上**恒画圆环**，最能验"落点反馈在面板上被收起来"
            Tool = Tool.Eraser;
            _uiHover = false;
            CheckBool("图库面板 · 从画布直入不画圆环",
                DrawnCursor == ToolCursorShape.None, $"{DrawnCursor}");
            _uiHover = true;
            CheckBool("图库面板 · 从工具条进入也不画圆环",
                DrawnCursor == ToolCursorShape.None, $"{DrawnCursor}");

            _uiHover = false;
            Tool = Tool.Marquee;                       // 还原（后面的段落都按框选工具写）
            CloseLibraryPanel();                       // 走真实关闭路径（顺带复位 _onDrawnChrome）
        }

        // ---- 拖拽中：用按下那一刻的语义，不重新命中测试 ----
        PointerX = 100; PointerY = 100;         // 指针早就离开手柄了
        _drawing = true;
        SelDragging = true;
        _dragIsMove = false;
        _dragHandle = SelHandle.Left;
        Check("拖拽中 · 左右拉伸（指针已离开手柄）", CursorKind.ResizeWE);
        _dragHandle = SelHandle.Rotate;
        Check("拖拽中 · 旋转", CursorKind.Rotate);
        _dragIsMove = true;
        _dragHandle = SelHandle.None;
        Check("拖拽中 · 整体移动", CursorKind.Move);
        _drawing = false; SelDragging = false; _dragIsMove = false; _dragHandle = SelHandle.None;

        // ---- 滚动条 / 穿透 ----
        ScrollBarHover = true;
        Check("滚动条悬停（滑块自己变粗，不换光标）", CursorKind.Default);
        ScrollBarHover = false;

        PassThrough = true;
        Check("穿透模式（交给下层窗口）", CursorKind.Leave);
        PassThrough = false;

        // ---- 自绘光标能不能真的建出来 ----
        var hRot = Cursors.HandleFor(CursorKind.Rotate, CursorSizePx);
        var hHide = Cursors.HandleFor(CursorKind.Hidden, CursorSizePx);
        CheckBool("旋转光标建立成功（位图/热点没写错）", hRot != IntPtr.Zero,
            $"句柄 0x{hRot:X}  {CursorSizePx}px");
        CheckBool("隐藏光标建立成功", hHide != IntPtr.Zero, $"句柄 0x{hHide:X}");

        // ---- 斜笔（系统 IDC_PEN）：句柄能取到、热点真在笔尖 ----
        //
        // "不挡视线"全靠热点在笔尖——取错光标序号（比如落到箭头/十字上）时，
        // 屏幕上会变成"笔杆压在落点上"，肉眼第一时间很难发现，所以钉两个数：
        // 句柄非零 + 热点 (0,0)。完整形状的验证在 tmp/penprobe（导出大图看）。
        // ⚠ 2026-09-27 晚试过"自绘彩笔版"（跟墨色/跟笔宽），用户看过真机后否掉了
        //   （"填充颜色有点难看，原来那支就挺好"）——**已撤回**，这里保住"用的是系统那支"。
        var hPen = Cursors.HandleFor(CursorKind.Pen, CursorSizePx);
        CheckBool("斜笔建立成功（IDC_PEN 系统光标）", hPen != IntPtr.Zero, $"句柄 0x{hPen:X}");
        var (penHotX, penHotY) = Cursors.HotspotOf(hPen);
        CheckBool("斜笔热点在笔尖（左上角 0,0；别处会挡视线）",
            penHotX == 0 && penHotY == 0, $"热点=({penHotX},{penHotY})");
        CheckBool("斜笔用的是**系统那支**（不是自绘的彩笔）",
            hPen == Cursors.System(Native.IDC_PEN), $"句柄 0x{hPen:X}");

        // ---- 光标"设过就不重设"的缓存**必须会被作废**（用户 2026-09-27 报的 bug）----
        //
        // 病根：穿透（`CursorKind.Leave`，指针归下层窗口）和**改窗口扩展样式**这两处
        // 会让屏幕上的光标变成箭头，而我们那句"同一个句柄不重复设"只认自己记的数——
        // 于是之后所有"设成同一个"的请求全被跳过，**光标卡在箭头上**。
        // 用户的原话："切成穿透再切回画笔，还是三角形；切荧光笔更明显（箭头 + 圆盘一起出现）；
        // 多切几遍有时候又能切回来"。
        // 这两条就是那个 bug 的回归钉子：放手之后缓存必须归零。
        {
            LastPointerType = Native.PT_MOUSE;
            Tool = Tool.Pen;
            PassThrough = false;
            ApplyCursor(force: true);
            CheckBool("（准备）画笔下光标已设成斜笔",
                CursorAppliedForTest == hPen, $"已设 0x{CursorAppliedForTest:X}");

            PassThrough = true;
            ApplyCursor();                       // 穿透：把指针交给下层窗口
            CheckBool("穿透时：放手 + 缓存作废（下次才会真设）",
                CursorAppliedForTest == IntPtr.Zero, $"缓存 0x{CursorAppliedForTest:X}");

            PassThrough = false;
            ApplyCursor();                       // 退出穿透：非 force 也必须真设回去
            CheckBool("退出穿透后：光标真的设回斜笔（不再卡在箭头上）",
                CursorAppliedForTest == hPen, $"已设 0x{CursorAppliedForTest:X}");

            // 换穿透（真实入口：它会**改窗口扩展样式**，系统顺手把光标恢复成箭头）
            // ——缓存同样必须作废，否则用户看到的还是那个箭头。
            SetPassThroughFromUi(true);
            CheckBool("开穿透（改样式）后：缓存作废",
                CursorAppliedForTest == IntPtr.Zero, $"缓存 0x{CursorAppliedForTest:X}");
            SetPassThroughFromUi(false);
            CheckBool("关穿透后：光标真设回斜笔（一条路走通，不再卡箭头）",
                CursorAppliedForTest == hPen, $"已设 0x{CursorAppliedForTest:X}");
        }

        // 自绘光标导出成图，供人眼检查形状与抗锯齿。
        try
        {
            Directory.CreateDirectory("reports");
            string dump = Path.Combine("reports", "cursor-rotate.bmp");
            Cursors.DumpRotate(dump, CursorSizePx);
            // 再导一张大的：实际尺寸只有 64px，放大看才能判断形状和抗锯齿。
            Cursors.DumpRotate(Path.Combine("reports", "cursor-rotate-big.bmp"), 128, 3);
            Console.WriteLine($"  （旋转光标已导出：{dump}，放大 4 倍）");
            Console.WriteLine("  旋转光标圆周采样（0°=右 90°=下 180°=左 270°=上，缺口应在右上）：");
            Console.WriteLine("    " + Cursors.RotateRingReport(CursorSizePx));
            int stray = Cursors.RotateStrayPixels(CursorSizePx);
            CheckBool("旋转光标 · 圆环外没有多余墨点（箭头没跑位）", stray == 0, $"环外墨点 {stray} 个");
        }
        catch (Exception ex)
        {
            Console.WriteLine("  旋转光标导出失败：" + ex.Message);
        }

        Console.WriteLine();
        Console.WriteLine($"  合计 {pass + fail} 项：通过 {pass}，失败 {fail}");
        Console.WriteLine();
        _quit = true;
    }

    /// <summary>
    /// 框选自检：**框到的就该选中**。
    ///
    /// 判据（这是产品语义，不是实现细节）：
    ///   ① 框住全部墨 → 全部选中（老师最常做的动作）；
    ///   ② 框只压住笔身的一部分 → 这条也要选中（"碰到就选中"），
    ///      否则屏幕上永远选不全：笔迹只要有一头在屏幕外（或框拖不到的地方），
    ///      要求"整条都在框里"就永远选不上，用户看到的就是"框了但没全选中"；
    ///   ③ 框在空白处 → 一个都不选；
    ///   ④ 图像对象（截图/粘贴）和旋转过的对象，同一套规则。
    /// </summary>
    private void SelTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 框选自检（框到的就该选中）===");

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-32} {detail}");
        }

        float x0 = _virtualX + 300f, y0 = _virtualY + 300f;
        var ink = new Color4(1f, 0f, 1f, 1f);

        Stroke Line(float x, float y, float dx, float dy, float w)
        {
            var s = new Stroke { Tool = Tool.Pen, Color = ink, Width = w };
            s.AddPoint(x, y, 0.5f, NowMs);
            s.AddPoint(x + dx, y + dy, 0.5f, NowMs);
            return s;
        }

        Doc.Clear();
        Doc.ClearHistory();

        var a = Line(x0, y0, 200f, 0f, 6f * DpiScale);            // 横线
        var b = Line(x0, y0 + 200f, 0f, 160f, 40f * DpiScale);    // 竖的粗笔（笔身很宽）
        var c = Line(x0 + 300f, y0, 300f, 300f, 8f * DpiScale);   // 斜线
        var d = Line(x0 - 500f, y0 + 500f, 3000f, 0f, 10f * DpiScale); // 长横线（一头在屏幕外）
        foreach (var s in new[] { a, b, c, d }) Doc.AddStroke(s);

        // 旋转 30° 的一条：包围盒是旋转后的 AABB
        var rot = Line(x0 + 200f, y0 + 500f, 200f, 0f, 10f * DpiScale);
        rot.Transform = Matrix3x2.CreateRotation(MathF.PI / 6f) * Matrix3x2.CreateTranslation(0, 0);
        Doc.AddStroke(rot);

        int n = Doc.Strokes.Count;
        Doc.Selected.Clear();

        // ① 框住全部
        var all = RectF.Empty;
        foreach (var s in Doc.Strokes) all.Add(s.PaddedBounds);
        Doc.ApplyMarquee(all.Inflate(20f));
        Check("框住全部 → 全部选中", Doc.Selected.Count == n, $"{Doc.Selected.Count}/{n} 条");

        // ② 只压住粗竖笔的笔身（中心线在框外）
        Doc.Selected.Clear();
        var body = RectF.Empty;
        body.Add(b.Points[0].X - 30f, b.Points[0].Y + 40f);
        body.Add(b.Points[0].X + 30f, b.Points[0].Y + 100f);
        Doc.ApplyMarquee(body);
        Check("框压住笔身的一角 → 这一条也选中",
            Doc.Selected.Contains(b), $"选中 {Doc.Selected.Count} 条（期望含这条粗竖笔）");

        // ③ 框住屏幕外那条长横线可见的一段：也该选中
        Doc.Selected.Clear();
        var edge = RectF.Empty;
        edge.Add(_virtualX + 10f, d.Points[0].Y - 4f);
        edge.Add(_virtualX + 200f, d.Points[0].Y + 4f);
        Doc.ApplyMarquee(edge);
        Check("框住长线露出来的一段 → 整条选中",
            Doc.Selected.Contains(d), $"选中 {Doc.Selected.Count} 条");

        // ④ 空白处 → 一个都不选
        Doc.Selected.Clear();
        var empty = RectF.Empty;
        empty.Add(_virtualX + 40f, _virtualY + 40f);
        empty.Add(_virtualX + 120f, _virtualY + 120f);
        Doc.ApplyMarquee(empty);
        Check("空白处 → 一个都不选", Doc.Selected.Count == 0, $"{Doc.Selected.Count} 条");

        // ⑤ 精确框一条：不能顺手把别的也选进来
        Doc.Selected.Clear();
        var onlyA = RectF.Empty;
        onlyA.Add(a.Points[0].X - 10f, a.Points[0].Y - 10f);
        onlyA.Add(a.Points[1].X + 10f, a.Points[1].Y + 10f);
        Doc.ApplyMarquee(onlyA);
        Check("框住横线 → 只有它", Doc.Selected.Count == 1 && Doc.Selected[0] == a,
              $"选中 {Doc.Selected.Count} 条");

        // ⑥ 旋转过的对象：框住它的包围盒就该选中
        Doc.Selected.Clear();
        Doc.ApplyMarquee(rot.PaddedBounds.Inflate(6f));
        Check("旋转对象 → 框住包围盒即选中", Doc.Selected.Contains(rot),
              $"选中 {Doc.Selected.Count} 条");

        // ⑦ 截图/粘贴来的图像对象走同一套规则
        var img = ImageData.Adopt(40, 30, new byte[40 * 30 * 4], false);
        if (img != null)
        {
            var placed = Doc.AddImage(img, _virtualX + 300f, _virtualY + 700f, 1f);
            Doc.Selected.Clear();
            Doc.ApplyMarquee(placed.PaddedBounds.Inflate(6f));
            Check("图像对象 → 同样能被框到", Doc.Selected.Contains(placed),
                  $"选中 {Doc.Selected.Count} 条");
        }

        // ⑧ 宽墨迹：选中框必须把**墨**圈住（不是只圈中心线）
        //    64 像素宽的荧光笔，屏幕上是一条 64 像素宽的带子；框要是按中心线算，
        //    四条边全压在墨里面——用户实测就是嫌这个。
        {
            var wide = new Stroke
            {
                Tool = Tool.Highlighter, Color = HighlighterCurrent,
                Width = 32f * DpiScale,                 // 最粗的一档荧光笔
            };
            wide.AddPoint(x0 + 400f, y0 + 800f, 0.5f, NowMs);
            wide.AddPoint(x0 + 900f, y0 + 800f, 0.5f, NowMs);
            Doc.AddStroke(wide);
            Doc.SelectOnly(new[] { wide });

            var frame = SelectionHandles.FrameOf(Doc.Selected);
            var inkBox = wide.InkBounds;                // 无变换：局部 = 画布
            float paint = wide.Width * 0.5f;            // 鼠标压感 0.5 → 半宽 = 半个笔宽
            bool contains = frame.Local.MinX <= inkBox.MinX + 0.01f
                         && frame.Local.MinY <= inkBox.MinY + 0.01f
                         && frame.Local.MaxX >= inkBox.MaxX - 0.01f
                         && frame.Local.MaxY >= inkBox.MaxY - 0.01f;
            float slack = MathF.Max(
                MathF.Max(frame.Local.MinX - inkBox.MinX, frame.Local.MinY - inkBox.MinY),
                MathF.Max(inkBox.MaxX - frame.Local.MaxX, inkBox.MaxY - frame.Local.MaxY));
            Check("宽笔选中框把墨圈住", contains,
                  contains ? $"框 {frame.Local.MaxX - frame.Local.MinX:F0}×"
                             + $"{frame.Local.MaxY - frame.Local.MinY:F0}px，"
                             + $"墨是中心线外扩 {paint:F0}px"
                           : $"框 {frame.Local.MinX:F0},{frame.Local.MinY:F0}→"
                             + $"{frame.Local.MaxX:F0},{frame.Local.MaxY:F0}；"
                             + $"墨 {inkBox.MinX:F0},{inkBox.MinY:F0}→"
                             + $"{inkBox.MaxX:F0},{inkBox.MaxY:F0}");
            Check("宽笔选中框不虚胖", slack <= 2f, $"比墨大出 {slack:F1}px（要 ≤ 2）");
            Doc.Selected.Clear();
        }

        // ⑨ **点选**（2026-09-15 新增）：按在墨上就选中那一条
        {
            float tol = ClickToleranceLogical * DpiScale;

            Doc.Selected.Clear();
            var hitA = Doc.SelectAt(a.Points[0].X + 100f, a.Points[0].Y, tol);
            Check("点选：点在墨上 → 选中这一条",
                  ReferenceEquals(hitA, a) && Doc.Selected.Count == 1 && Doc.Selected[0] == a,
                  $"点到 {(hitA == null ? "空" : "一条")}，选中 {Doc.Selected.Count} 条");

            // 细笔（1.5 逻辑像素）：容差让"点得中"成为可能，但离太远仍然不该命中
            var thin = Line(x0 + 1200f, y0, 400f, 0f, 1.5f * DpiScale);
            Doc.AddStroke(thin);
            var near = Doc.SelectAt(x0 + 1300f, y0 + 3f, tol);
            var far = Doc.HitObjectAt(x0 + 1300f, y0 + 12f, tol);
            Check("点选：细笔有容差（3px 命中、12px 不命中）",
                  ReferenceEquals(near, thin) && far == null,
                  $"近处点到 {(near == null ? "空" : "细笔")}，远处 {(far == null ? "空" : "误命中")}");

            // 两条重叠：取**最上面**那条（后画的）
            var under = Line(x0 + 2000f, y0, 200f, 0f, 12f * DpiScale);
            var over = Line(x0 + 2000f, y0, 200f, 0f, 12f * DpiScale);
            Doc.AddStroke(under);
            Doc.AddStroke(over);
            var top = Doc.HitObjectAt(x0 + 2100f, y0, tol);
            Check("点选：重叠处取最上面那条", ReferenceEquals(top, over),
                  ReferenceEquals(top, over) ? "取到后画的那条" : "取错了（取到下面那条）");

            // Shift 加选 / 再点同一条移出 / Alt 减选
            Doc.Selected.Clear();
            Doc.SelectAt(a.Points[0].X + 100f, a.Points[0].Y, tol);
            Doc.SelectAt(c.Points[0].X + 150f, c.Points[0].Y + 150f, tol, additive: true);
            Check("点选：Shift 加选 → 两条",
                  Doc.Selected.Count == 2 && Doc.Selected.Contains(a) && Doc.Selected.Contains(c),
                  $"选中 {Doc.Selected.Count} 条");

            Doc.SelectAt(c.Points[0].X + 150f, c.Points[0].Y + 150f, tol, additive: true);
            Check("点选：再 Shift 点同一条 → 移出（切换）",
                  Doc.Selected.Count == 1 && !Doc.Selected.Contains(c),
                  $"选中 {Doc.Selected.Count} 条");

            Doc.SelectAt(a.Points[0].X + 100f, a.Points[0].Y, tol, subtractive: true);
            Check("点选：Alt 减选 → 空", Doc.Selected.Count == 0, $"选中 {Doc.Selected.Count} 条");

            // 点空白：返回空、**不动选中**（交给框选那一步去处理"单击空白＝取消"）
            Doc.SelectOnly(new[] { a });
            var miss = Doc.SelectAt(_virtualX + 40f, _virtualY + 40f, tol);
            Check("点选：点空白 → 返回空、选中不动（交给框选）",
                  miss == null && Doc.Selected.Count == 1 && Doc.Selected[0] == a,
                  miss == null ? "没命中，选中保持 1 条" : "空白处竟然命中了");

            // **被像素橡皮擦断之后，缺口里不算墨**（点缺口不该命中）
            var cut = Line(x0 + 2400f, y0, 600f, 0f, 10f * DpiScale);
            Doc.AddStroke(cut);
            float gapX = cut.Points[0].X + 300f;
            Doc.EraseRectAt(gapX, y0, 30f, 30f);
            var inGap = Doc.HitObjectAt(gapX, y0, tol);
            var onInk = Doc.HitObjectAt(cut.Points[0].X + 60f, y0, tol);
            Check("点选：擦断的缺口不算墨（点缺口不命中、点墨命中）",
                  inGap == null && onInk != null,
                  $"缺口 {(inGap == null ? "没命中" : "误命中")}，"
                  + $"墨上 {(onInk != null ? "命中某一段" : "没命中")}");
        }

        // ⑩ 操作条：**只给下限、不翻面**（用户 2026-09-15 定的）
        {
            var vp = ViewportCanvas;

            var low = Line(x0, _virtualY + _virtualH - 30f, 200f, 0f, 8f * DpiScale);
            Doc.AddStroke(low);
            Doc.SelectOnly(new[] { low });
            var lowAabb = SelectionHandles.FrameOf(Doc.Selected).CanvasAabb;
            var barLow = SelectionHandles.BarRect(lowAabb, DpiScale, vp);
            float floor = vp.MaxY - SelectionHandles.BarMinBottomMarginLogical * DpiScale;
            Check("操作条：贴屏幕下边时停在下限（不越界、也不翻面）",
                  MathF.Abs(barLow.MaxY - floor) <= 0.5f,
                  $"条底 {barLow.MaxY:F0}，下限 {floor:F0}（可见下边 {vp.MaxY:F0}）");

            var leftLine = Line(vp.MinX + 5f, _virtualY + 200f, 0f, 200f, 8f * DpiScale);
            Doc.AddStroke(leftLine);
            Doc.SelectOnly(new[] { leftLine });
            var leftAabb = SelectionHandles.FrameOf(Doc.Selected).CanvasAabb;
            var barLeft = SelectionHandles.BarRect(leftAabb, DpiScale, vp);
            bool inView = barLeft.MinX >= vp.MinX - 0.5f && barLeft.MaxX <= vp.MaxX + 0.5f;
            bool barsHit = true;
            for (int i = 0; i < SelectionHandles.BarButtonCount; i++)
            {
                var r = SelectionHandles.BarButtonRect(i, leftAabb, DpiScale, vp);
                int got = SelectionHandles.BarButtonAt((r.MinX + r.MaxX) * 0.5f,
                                                       (r.MinY + r.MaxY) * 0.5f,
                                                       leftAabb, DpiScale, vp);
                if (got != i) barsHit = false;
            }
            Check("操作条：贴屏幕左边 → 整条在可见区内、按钮都能点中",
                  inView && barsHit,
                  $"条 x {barLeft.MinX:F0}..{barLeft.MaxX:F0}（可见 {vp.MinX:F0}..{vp.MaxX:F0}），"
                  + $"按钮命中 {(barsHit ? "全中" : "有点不中")}");
        }

        // ⑪ 点选的**手势接线**（引擎那一侧：无选中时点一条、点空白、Shift 加选、收窄成单选）
        {
            float tol = ClickToleranceLogical * DpiScale;

            Doc.Selected.Clear();
            Tool = Tool.Marquee;
            bool tookA = SelectionGestureForTest(a.Points[0].X + 100f, a.Points[0].Y);
            Check("手势：**没选中**时点一条 → 接住并选中它（这条最容易写漏）",
                  tookA && Doc.Selected.Count == 1 && Doc.Selected[0] == a && SelDragging,
                  $"接住={tookA}，选中 {Doc.Selected.Count} 条，拖动态={SelDragging}");
            EndSelectionGestureForTest();

            Doc.Selected.Clear();
            bool tookBlank = SelectionGestureForTest(_virtualX + 40f, _virtualY + 40f);
            Check("手势：点空白 → 不接（交给框选）", !tookBlank, $"接住={tookBlank}");

            Doc.Selected.Clear();
            SelectionGestureForTest(a.Points[0].X + 100f, a.Points[0].Y);
            EndSelectionGestureForTest();
            bool tookC = SelectionGestureForTest(c.Points[0].X + 150f, c.Points[0].Y + 150f, shift: true);
            Check("手势：Shift 点第二条 → 加选，且不进拖动",
                  tookC && Doc.Selected.Count == 2 && !SelDragging,
                  $"接住={tookC}，选中 {Doc.Selected.Count} 条，拖动态={SelDragging}");

            // "点一下把多选收窄成单选"：按在多选中的一条上、松手不移动
            Doc.Selected.Clear();
            Doc.SelectOnly(new[] { a, c });
            SelectionGestureForTest(a.Points[0].X + 100f, a.Points[0].Y);   // 落在 a 的框里 → 整体拖动
            EndSelectionGestureForTest();                                   // 没移动 → 收窄
            Check("手势：点多选中的一条、不移动 → 收窄成只选它",
                  Doc.Selected.Count == 1 && Doc.Selected[0] == a,
                  $"选中 {Doc.Selected.Count} 条{(Doc.Selected.Count == 1 && Doc.Selected[0] == a ? "（就是那一条）" : "")}");

            Doc.Selected.Clear();
            SelDragging = false;
            _ = tol;
        }

        // ⑫ 框选矩形**咬着指针**（用户 2026-09-15 反馈："感觉有点不大跟手"）
        //
        // 以前按下之后每次移动都累积 min/max，于是框只会**变大**：指针往回走框不跟着缩，
        // 屏幕上看到的是"扫过的最大范围"，而不是"从起点拉到现在的这一个矩形"。
        // 现在按**锚点 ↔ 当前点**算（和同行一致），往回拖要能缩回去。
        // 截图取景框用的是同一套算法，这里一起验。
        {
            SelMode = SelectMode.Rect;
            Tool = Tool.Marquee;

            // ① 拖到 +400 再拖回 +100 松手：框应该是 [锚点, +100]，不是 [锚点, +400]
            Doc.Clear();
            Doc.ClearHistory();
            var sweptOnly = Line(x0 + 200f, y0 + 50f, 100f, 0f, 6f * DpiScale);  // 扫过、但不在最终框里
            var inside = Line(x0 + 20f, y0 + 50f, 60f, 0f, 6f * DpiScale);       // 在最终框里
            Doc.AddStroke(sweptOnly);
            Doc.AddStroke(inside);
            MarqueeDragForTest(new[]
            {
                new Vector2(x0, y0),
                new Vector2(x0 + 400f, y0 + 400f),      // 先拖远
                new Vector2(x0 + 100f, y0 + 100f),      // 再拖回来松手
            });
            bool sweptPicked = Doc.Selected.Contains(sweptOnly);
            Check("框选：拖远再拖回来 → 框跟着缩（不是扫过的最大范围）",
                  Doc.Selected.Count == 1 && Doc.Selected[0] == inside,
                  $"选中 {Doc.Selected.Count} 条（扫过但已退回的那条"
                  + (sweptPicked ? "**被误选**" : "没被选") + "）");

            // ② 从锚点往左上拖：反向也要能拉出框
            Doc.Clear();
            Doc.ClearHistory();
            var upLeft = Line(x0 - 120f, y0 - 120f, 60f, 0f, 6f * DpiScale);
            Doc.AddStroke(upLeft);
            MarqueeDragForTest(new[]
            {
                new Vector2(x0, y0),
                new Vector2(x0 - 180f, y0 - 180f),
            });
            Check("框选：从锚点往左上拖 → 反向也能拉出框",
                  Doc.Selected.Count == 1 && Doc.Selected[0] == upLeft,
                  $"选中 {Doc.Selected.Count} 条");

            // ③ 截图取景框：同一套锚点算法（只驱动"按下 → 拖"，不抓屏）
            CaptureFrameDragForTest(x0, y0, x0 + 400f, y0 + 400f, x0 + 100f, y0 + 100f);
            bool capShrunk = MathF.Abs(CapMinX - x0) < 0.01f && MathF.Abs(CapMaxX - (x0 + 100f)) < 0.01f
                          && MathF.Abs(CapMinY - y0) < 0.01f && MathF.Abs(CapMaxY - (y0 + 100f)) < 0.01f;
            Check("截图取景框：同一套锚点算法（拖远再拖回也缩）", capShrunk,
                  $"框 = ({CapMinX:F0},{CapMinY:F0})..({CapMaxX:F0},{CapMaxY:F0})，"
                  + $"期望 ({x0:F0},{y0:F0})..({x0 + 100f:F0},{y0 + 100f:F0})");
            CaptureActive = false;
        }

        // ⑬ "选中是临时上下文"（用户 2026-09-15 定的规则，也是 InkClass/PPT/Figma 的惯例）
        {
            // 换工具 → 收起；按"框选"（本来就是它）→ 保留
            Doc.SelectOnly(new[] { a });
            RunActionForTest(KeyAction.ToolPen);
            bool clearedOnSwitch = Doc.Selected.Count == 0 && Tool == Tool.Pen;
            Tool = Tool.Marquee;                       // 直接换回来（不经过 SwitchTool，免得又清）
            Doc.SelectOnly(new[] { a });
            RunActionForTest(KeyAction.ToolMarquee);
            Check("换工具收起选区；按框选（同一工具）保留",
                  clearedOnSwitch && Doc.Selected.Count == 1,
                  $"换笔后 {(clearedOnSwitch ? "已收起" : "没收起")}，再按框选后选中 {Doc.Selected.Count} 条");

            // 对象从文档里消失 → 自动从选中里去掉
            Doc.Clear();
            Doc.ClearHistory();
            var gone = Line(x0, y0, 200f, 0f, 8f * DpiScale);
            Doc.AddStroke(gone);
            Doc.SelectOnly(new[] { gone });
            Doc.RemoveStroke(gone);
            Check("对象被删/被擦掉 → 自动从选中里去掉", Doc.Selected.Count == 0,
                  $"选中 {Doc.Selected.Count} 条");

            // 滚动**不算**"操作选区"：滚轮只改相机，不该把选中弄没
            Doc.SelectOnly(new[] { a });
            float camBefore = ViewOffsetY;
            HandleWheel((IntPtr)(-120L << 16));        // 高 16 位 = 滚轮增量
            bool camMoved = MathF.Abs(ViewOffsetY - camBefore) > 0.5f;
            ViewOffsetY = camBefore;
            Check("滚动不清选中（滚动是「看」，不是「操作对象」）",
                  Doc.Selected.Count == 1 && camMoved,
                  $"选中 {Doc.Selected.Count} 条，相机 {(camMoved ? "动了" : "没动")}");

            // **复制拖拽模式**：点复制按钮进模式 → 按住选中内容拖 → 拖出副本（原件不动）→
            // 可以连着拖第二份；**克隆 + 位移算一步撤销**
            Doc.Clear();
            Doc.ClearHistory();
            Tool = Tool.Marquee;
            var src = Line(x0, y0, 200f, 0f, 8f * DpiScale);
            Doc.AddStroke(src);
            Doc.SelectOnly(new[] { src });
            var srcXform0 = src.Transform;

            RunBarActionForTest((int)SelBarButton.Copy);              // 复制按钮（第二轮从 0 挪到 5）
            bool armed = CopyDragArmed && Doc.Selected.Count == 1;

            bool took = SelectionGestureForTest(x0 + 100f, y0);        // 按在原件上（框内 → 拖动）
            bool cloneMade = Doc.Strokes.Count == 2;                   // 克隆发生在按下那一刻
            if (took)
            {
                UpdateSelectionGestureForTest(x0 + 300f, y0 + 60f);    // 拖出去
                EndSelectionGestureForTest();
            }
            var firstCopy = Doc.Selected.Count == 1 ? Doc.Selected[0] : null;
            bool firstOk = armed && took && cloneMade
                        && firstCopy != null && !ReferenceEquals(firstCopy, src)
                        && src.Transform.Equals(srcXform0);

            // 再拖一次 → 第三份（「可连续多份」）
            bool took2 = SelectionGestureForTest(x0 + 300f, y0 + 60f);
            if (took2)
            {
                UpdateSelectionGestureForTest(x0 + 500f, y0 + 120f);
                EndSelectionGestureForTest();
            }
            bool secondOk = Doc.Strokes.Count == 3 && Doc.Selected.Count == 1;

            Check("复制拖拽模式：拖出副本、原件不动、可连续拖第二份",
                  firstOk && secondOk,
                  $"进模式={armed}，第一次接住={took}（克隆重合={cloneMade}），"
                  + $"第二次接住={took2}；对象数 {Doc.Strokes.Count}（应 3），"
                  + $"原件 {(src.Transform.Equals(srcXform0) ? "没动" : "动了")}");

            // 每拖出一份 = 一步撤销（**克隆 + 位移是一步**，不是两步）
            Doc.Undo();
            bool backToTwo = Doc.Strokes.Count == 2;
            Doc.Undo();
            Check("复制拖拽：一次撤销回退一份（克隆+位移合成一步）",
                  backToTwo && Doc.Strokes.Count == 1 && ReferenceEquals(Doc.Strokes[0], src)
                  && src.Transform.Equals(srcXform0),
                  $"撤一次后 {2} 条、再撤一次 {Doc.Strokes.Count} 条，"
                  + $"原件位置 {(src.Transform.Equals(srcXform0) ? "回到原位" : "没回来")}");

            RunBarActionForTest((int)SelBarButton.Copy);              // 退出模式（收尾）
            Check("再点一次复制按钮 → 退出复制拖拽模式", !CopyDragArmed, $"armed={CopyDragArmed}");
        }

        // ⑭ 拖动 / 旋转期间的画法（2026-09-16）：方案 A 收装饰 + 方案 B 拖动预览
        //
        // 这一段的判据全部落在**屏幕像素**上，因为要验的两件事都是"看得见"的性质：
        //   · 拖动中手柄与操作条到底还在不在屏幕上（方案 A）；
        //   · 被拖的那块到底有没有跟着指针走、并且**没被选中的墨一个像素都没动**（方案 B）。
        //
        // 前置条件是把板铺成**不透明**并选一个**没有别的程序参与**的颜色：
        // 桌面上"没画东西的地方"是别的程序，白像素到处都是，数不出"手柄的白在不在"。
        // 板色取深灰，于是四种东西互不撞色：板=深灰、墨=品红、手柄与操作条=白、选中框=蓝。
        {
            bool boardWas = BoardOn;
            var boardColorWas = BoardColor;
            float camWas = ViewOffsetY;
            BoardOn = true;
            BoardColor = new Color4(0.10f, 0.10f, 0.12f, 1f);
            ViewOffsetY = 0f;                        // 屏幕坐标 == 画布坐标，抓屏好算
            Doc.Clear();
            Doc.ClearHistory();
            Tool = Tool.Marquee;

            float dpi = DpiScale;
            Stroke FatLine(float yy, Color4 col)
            {
                var s = new Stroke { Tool = Tool.Pen, Color = col, Width = 10f * dpi };
                s.AddPoint(x0, yy, 0.5f, NowMs);
                s.AddPoint(x0 + 260f * dpi, yy, 0.5f, NowMs);
                return s;
            }
            var dragInk = FatLine(y0 + 700f, new Color4(1f, 0f, 1f, 1f));    // 品红：被拖的这一条
            var refInk = FatLine(y0 + 1100f, new Color4(0f, 1f, 0f, 1f));    // 绿：什么都不做的参照物
            Doc.AddStroke(dragInk);
            Doc.AddStroke(refInk);
            Doc.SelectOnly(new[] { dragInk });
            SettleFrames(250);

            var frame0 = LiveSelectionFrame;
            var barRect = SelectionHandles.BarRect(frame0.CanvasAabb, dpi, ViewportCanvas);
            var handleTL = SelectionHandles.CanvasPosition(SelHandle.TopLeft, frame0, dpi);

            int BarWhite() => ScreenProbe.CountNear(
                (int)barRect.MinX, (int)barRect.MinY,
                (int)(barRect.MaxX - barRect.MinX), (int)(barRect.MaxY - barRect.MinY),
                255, 255, 255, 30);
            int HandleWhite() => ScreenProbe.CountNear(
                (int)handleTL.X - 20, (int)handleTL.Y - 20, 40, 40, 255, 255, 255, 30);

            var oldBox = dragInk.PaddedBounds.Inflate(8f);
            int BoxMagenta(in RectF r) => ScreenProbe.CountMagenta(
                (int)r.MinX, (int)r.MinY, (int)(r.MaxX - r.MinX), (int)(r.MaxY - r.MinY));
            var refBox = refInk.PaddedBounds.Inflate(10f);
            byte[] RefShot() => ScreenProbe.CaptureRegion(
                (int)refBox.MinX, (int)refBox.MinY,
                (int)(refBox.MaxX - refBox.MinX), (int)(refBox.MaxY - refBox.MinY));

            int barBefore = BarWhite(), handleBefore = HandleWhite();
            int oldBefore = BoxMagenta(oldBox);
            var refBefore = RefShot();

            // 按住选中内容中间拖走（中间离手柄最远，命中的一定是"整体拖动"）
            float px = x0 + 130f * dpi, py = y0 + 700f;
            float dx = 150f, dy = 210f;
            bool tookDrag = SelectionGestureForTest(px, py);
            UpdateSelectionGestureForTest(px + dx, py + dy);
            SettleFrames(90);

            var movedBox = new RectF
            {
                MinX = oldBox.MinX + dx, MinY = oldBox.MinY + dy,
                MaxX = oldBox.MaxX + dx, MaxY = oldBox.MaxY + dy,
            };
            // 墨量比对只在**中间那一段**做：两端压着缩放手柄，而手柄拖动中是收起来的，
            // 拿整条去比会把"手柄盖住了几块墨"当成"两种画法不一致"。
            var midStrip = new RectF
            {
                MinX = (movedBox.MinX + movedBox.MaxX) * 0.5f - 200f,
                MinY = (movedBox.MinY + movedBox.MaxY) * 0.5f - 30f,
                MaxX = (movedBox.MinX + movedBox.MaxX) * 0.5f - 100f,
                MaxY = (movedBox.MinY + movedBox.MaxY) * 0.5f + 30f,
            };
            int barDuring = BarWhite(), handleDuring = HandleWhite();
            int oldDuring = BoxMagenta(oldBox), newDuring = BoxMagenta(movedBox);
            int stripDuring = BoxMagenta(midStrip);
            var refDuring = RefShot();
            int patchDuring = _windows[0].LastPatchCount;

            Check("拖动中：手柄与操作条收起来（方案 A）",
                  tookDrag && SelChromeCollapsed
                  && barDuring * 10 < barBefore && handleDuring * 10 < handleBefore,
                  $"接住={tookDrag}，收起={SelChromeCollapsed}；"
                  + $"操作条的白 {barBefore}→{barDuring}，手柄的白 {handleBefore}→{handleDuring}");

            Check("拖动中：内容层一帧都不重画（方案 B）",
                  patchDuring == 0,
                  $"上一帧光栅化分块 {patchDuring} 块（老做法要把走过的面积整块重画一遍）");

            Check("拖动中：预览真的上屏（新位置有墨、原位置干净）",
                  newDuring > 200 && oldDuring == 0,
                  $"新位置 {newDuring} 像素，原位置 {oldDuring} 像素");

            Check("拖动中：没被选中的墨迹一个像素都不许变",
                  ScreenProbe.DiffCount(refBefore, refDuring) == 0,
                  $"参照物区域差异 {ScreenProbe.DiffCount(refBefore, refDuring)} 像素");

            EndSelectionGestureForTest();
            SettleFrames(250);

            // 松手后框跟着内容走到了新位置，所以手柄与操作条要**按现在的框**重新取位置
            var frameAfter = LiveSelectionFrame;
            var barRectAfter = SelectionHandles.BarRect(frameAfter.CanvasAabb, dpi, ViewportCanvas);
            var handleAfterPt = SelectionHandles.CanvasPosition(SelHandle.TopLeft, frameAfter, dpi);
            int barAfter = ScreenProbe.CountNear(
                (int)barRectAfter.MinX, (int)barRectAfter.MinY,
                (int)(barRectAfter.MaxX - barRectAfter.MinX), (int)(barRectAfter.MaxY - barRectAfter.MinY),
                255, 255, 255, 30);
            int handleAfter = ScreenProbe.CountNear(
                (int)handleAfterPt.X - 20, (int)handleAfterPt.Y - 20, 40, 40, 255, 255, 255, 30);
            int oldAfter = BoxMagenta(oldBox), newAfter = BoxMagenta(movedBox);
            int stripAfter = BoxMagenta(midStrip);
            int parity = Math.Abs(stripAfter - stripDuring);
            var refAfter = RefShot();

            Check("松手后：装饰回来、模型才动、原位置干净",
                  !SelChromeCollapsed && handleAfter > handleBefore / 2 && barAfter > barBefore / 2
                  && !dragInk.Transform.IsIdentity && oldAfter == 0,
                  $"手柄的白 {handleAfter}（拖动前 {handleBefore}），条的白 {barAfter}，"
                  + $"模型 {(dragInk.Transform.IsIdentity ? "还没动" : "动了")}，原位置 {oldAfter} 像素");

            Check("松手前后同一段墨的墨量一致（预览与内容层像素一致）",
                  stripDuring > 200 && parity <= Math.Max(20, stripDuring / 50),
                  $"中间那一段：拖动中 {stripDuring} 像素，松手后 {stripAfter} 像素（差 {parity}）");

            Check("松手后参照物仍然一个像素都没变",
                  ScreenProbe.DiffCount(refBefore, refAfter) == 0,
                  $"差异 {ScreenProbe.DiffCount(refBefore, refAfter)} 像素");

            Doc.Undo();
            SettleFrames(250);
            Check("一次撤销回到原位（方案 B 没改撤销语义）",
                  dragInk.Transform.IsIdentity && BoxMagenta(oldBox) > oldBefore / 2
                  && BoxMagenta(movedBox) == 0,
                  $"模型 {(dragInk.Transform.IsIdentity ? "回原位" : "没回来")}，"
                  + $"原位置品红 {BoxMagenta(oldBox)} 像素（拖着时 {oldBefore}），"
                  + $"拖过去的位置 {BoxMagenta(movedBox)} 像素（该是 0）");

            // ---- 方案 A 的另一半：旋转中**留**旋转柄与度数标签 ----
            Doc.Clear();
            Doc.ClearHistory();
            var spinInk = FatLine(y0 + 700f, new Color4(1f, 0f, 1f, 1f));
            Doc.AddStroke(spinInk);
            Doc.SelectOnly(new[] { spinInk });
            SettleFrames(250);

            var f2 = LiveSelectionFrame;
            var grip2 = SelectionHandles.CanvasPosition(SelHandle.Rotate, f2, dpi);
            var pivot2 = new Vector2((f2.CanvasAabb.MinX + f2.CanvasAabb.MaxX) * 0.5f,
                                     (f2.CanvasAabb.MinY + f2.CanvasAabb.MaxY) * 0.5f);
            float arm2 = Vector2.Distance(grip2, pivot2);
            var barRect2 = SelectionHandles.BarRect(f2.CanvasAabb, dpi, ViewportCanvas);
            int SpinBarWhite() => ScreenProbe.CountNear(
                (int)barRect2.MinX, (int)barRect2.MinY,
                (int)(barRect2.MaxX - barRect2.MinX), (int)(barRect2.MaxY - barRect2.MinY),
                255, 255, 255, 30);
            // 度数标签就在**当前**旋转柄的上方（手柄跟着内容转，所以每步都要重算位置）
            int LabelAccent()
            {
                var h = SelectionHandles.CanvasPosition(SelHandle.Rotate, LiveSelectionFrame, dpi);
                int pw = (int)(120f * dpi), ph = (int)(70f * dpi);
                return ScreenProbe.CountNear((int)(h.X - pw * 0.5f), (int)(h.Y - ph),
                                             pw, ph, 0, 120, 212, 40);
            }

            int spinBarBefore = SpinBarWhite();
            bool tookSpin = SelectionGestureForTest(grip2.X, grip2.Y);
            UpdateSelectionGestureForTest(pivot2.X - arm2, pivot2.Y);     // 屏幕上逆时针 90°
            SettleFrames(90);

            int labelPixels = LabelAccent();
            int spinBarDuring = SpinBarWhite();
            Check("旋转中：柄与度数标签还在、操作条收起来（方案 A）",
                  tookSpin && SelRotating && SelChromeCollapsed
                  && spinBarDuring * 10 < spinBarBefore && labelPixels > 800,
                  $"接住={tookSpin}，旋转中={SelRotating}，收起={SelChromeCollapsed}；"
                  + $"度数标签强调色 {labelPixels} 像素，操作条的白 {spinBarBefore}→{spinBarDuring}");

            EndSelectionGestureForTest();
            SettleFrames(200);
            var f2After = LiveSelectionFrame;
            var barRect2After = SelectionHandles.BarRect(f2After.CanvasAabb, dpi, ViewportCanvas);
            int spinBarAfter = ScreenProbe.CountNear(
                (int)barRect2After.MinX, (int)barRect2After.MinY,
                (int)(barRect2After.MaxX - barRect2After.MinX), (int)(barRect2After.MaxY - barRect2After.MinY),
                255, 255, 255, 30);
            Check("旋转松手后：标签消失、操作条回来",
                  !SelRotating && spinBarAfter > spinBarBefore / 2,
                  $"条的白 {spinBarAfter}（旋转前 {spinBarBefore}）");

            // ---- 多选拖动：框是**轴对齐并集**，拖动中同样要跟着内容走 ----
            // （LiveSelectionFrame 的另一条分支：单选靠"框坐标系右乘"，多选要
            //   逐条过实时矩阵再并。少了这条，多选拖动时会只剩框留在原地。）
            Doc.Clear();
            Doc.ClearHistory();
            var m1 = FatLine(y0 + 600f, new Color4(1f, 0f, 1f, 1f));
            var m2 = FatLine(y0 + 980f, new Color4(1f, 0f, 1f, 1f));
            Doc.AddStroke(m1);
            Doc.AddStroke(m2);
            Doc.SelectOnly(new[] { m1, m2 });
            SettleFrames(200);

            var multiBefore = LiveSelectionFrame.CanvasAabb;
            float mx = (multiBefore.MinX + multiBefore.MaxX) * 0.5f;
            float my = (multiBefore.MinY + multiBefore.MaxY) * 0.5f;
            bool tookMulti = SelectionGestureForTest(mx, my);
            UpdateSelectionGestureForTest(mx + 120f, my - 80f);
            SettleFrames(60);
            var multiDuring = LiveSelectionFrame.CanvasAabb;
            bool frameFollows = MathF.Abs(multiDuring.MinX - (multiBefore.MinX + 120f)) < 1.5f
                             && MathF.Abs(multiDuring.MinY - (multiBefore.MinY - 80f)) < 1.5f;
            Check("多选拖动：框（轴对齐并集）跟着内容走",
                  tookMulti && DragPreviewActive && frameFollows,
                  $"{multiBefore.MinX:F0},{multiBefore.MinY:F0} → {multiDuring.MinX:F0},{multiDuring.MinY:F0}"
                  + $"（期望 +120,-80）");
            EndSelectionGestureForTest();
            SettleFrames(120);

            // ---- 缩放手势也走同一条"摘出去"的路，但**装饰不收** ----
            // （方案 B 对三种手势一视同仁；方案 A 只收移动与旋转——
            //   拖某个手柄时，另外几个手柄是有用的参照。）
            Doc.Clear();
            Doc.ClearHistory();
            var scInk = FatLine(y0 + 700f, new Color4(1f, 0f, 1f, 1f));
            Doc.AddStroke(scInk);
            Doc.SelectOnly(new[] { scInk });
            SettleFrames(200);

            var fScale = LiveSelectionFrame;
            var gripR = SelectionHandles.CanvasPosition(SelHandle.Right, fScale, dpi);
            float widthBefore = fScale.CanvasAabb.MaxX - fScale.CanvasAabb.MinX;
            bool tookScale = SelectionGestureForTest(gripR.X, gripR.Y);
            UpdateSelectionGestureForTest(gripR.X + 200f, gripR.Y);
            SettleFrames(60);
            var fScaled = LiveSelectionFrame;
            float widthDuring = fScaled.CanvasAabb.MaxX - fScaled.CanvasAabb.MinX;
            Check("缩放中：框跟着手柄变宽，且装饰不收（方案 A 只管移动与旋转）",
                  tookScale && widthDuring > widthBefore + 150f && !SelChromeCollapsed,
                  $"宽 {widthBefore:F0} → {widthDuring:F0}（期望 +200），收起={SelChromeCollapsed}");
            EndSelectionGestureForTest();
            SettleFrames(120);

            // ---- 单选一个**转过角度**的对象：框也必须是轴对齐的正矩形 ----
            // （用户 2026-09-16 定：单选也走多选那条量法。早先是"单选跟对象转"，
            //   判据就一条——框坐标系必须是单位阵，且框恰好是对象墨迹的外接正矩形。
            //   有人把它改回"跟对象转"，这里会红。）
            Doc.Clear();
            Doc.ClearHistory();
            var tilted = FatLine(y0 + 700f, new Color4(1f, 0f, 1f, 1f));
            Doc.AddStroke(tilted);
            Doc.SelectOnly(new[] { tilted });
            var tCenter = new Vector2((tilted.PaddedBounds.MinX + tilted.PaddedBounds.MaxX) * 0.5f,
                                      (tilted.PaddedBounds.MinY + tilted.PaddedBounds.MaxY) * 0.5f);
            Doc.ApplyTransform(Matrix3x2.CreateRotation(-40f * MathF.PI / 180f, tCenter));
            SettleFrames(150);

            var tf = SelectionHandles.FrameOf(Doc.Selected);
            var tExpect = tilted.WorldInkBounds;
            bool tAligned = tf.ToCanvas.IsIdentity
                         && MathF.Abs(tf.Local.MinX - tExpect.MinX) < 0.01f
                         && MathF.Abs(tf.Local.MinY - tExpect.MinY) < 0.01f
                         && MathF.Abs(tf.Local.MaxX - tExpect.MaxX) < 0.01f
                         && MathF.Abs(tf.Local.MaxY - tExpect.MaxY) < 0.01f;
            var tGrip = SelectionHandles.CanvasPosition(SelHandle.Rotate, tf, dpi);
            bool tGripOnTop = MathF.Abs(tGrip.X - (tf.Local.MinX + tf.Local.MaxX) * 0.5f) < 0.01f
                           && tGrip.Y < tf.Local.MinY;
            Check("单选一个转过的对象：框是正矩形、旋转柄在正上方",
                  tAligned && tGripOnTop,
                  $"框 {tf.Local.MinX:F0},{tf.Local.MinY:F0}..{tf.Local.MaxX:F0},{tf.Local.MaxY:F0}"
                  + $"（墨迹 {tExpect.MinX:F0},{tExpect.MinY:F0}..{tExpect.MaxX:F0},{tExpect.MaxY:F0}）；"
                  + $"柄在 ({tGrip.X:F0},{tGrip.Y:F0})");

            // 再转一手：拖动中框仍然轴对齐，而且是**每帧重新贴合**当前内容
            var tPivot = new Vector2((tf.Local.MinX + tf.Local.MaxX) * 0.5f,
                                     (tf.Local.MinY + tf.Local.MaxY) * 0.5f);
            float tArm = Vector2.Distance(tGrip, tPivot);
            float tA0 = MathF.Atan2(tGrip.Y - tPivot.Y, tGrip.X - tPivot.X);
            float tA1 = tA0 - 30f * MathF.PI / 180f;              // 屏幕上逆时针 30°
            bool tookTilt = SelectionGestureForTest(tGrip.X, tGrip.Y);
            UpdateSelectionGestureForTest(tPivot.X + tArm * MathF.Cos(tA1),
                                          tPivot.Y + tArm * MathF.Sin(tA1));
            SettleFrames(60);

            var dFrame = LiveSelectionFrame;
            var wb = tilted.WorldInkBounds;
            var expBox = RectF.Empty;
            foreach (var corner in new[]
            {
                new Vector2(wb.MinX, wb.MinY), new Vector2(wb.MaxX, wb.MinY),
                new Vector2(wb.MaxX, wb.MaxY), new Vector2(wb.MinX, wb.MaxY),
            })
            {
                var q = Vector2.Transform(corner, DragPreviewMatrix);
                expBox.Add(q.X, q.Y);
            }
            bool tLiveAligned = dFrame.ToCanvas.IsIdentity
                             && MathF.Abs(dFrame.Local.MinX - expBox.MinX) < 0.5f
                             && MathF.Abs(dFrame.Local.MaxX - expBox.MaxX) < 0.5f;
            Check("旋转中：框仍正着，并每帧重新贴合当前内容",
                  tookTilt && tLiveAligned,
                  $"框宽 {dFrame.Local.MaxX - dFrame.Local.MinX:F0}"
                  + $"（内容外接 {(expBox.MaxX - expBox.MinX):F0}），轴对齐={dFrame.ToCanvas.IsIdentity}");
            EndSelectionGestureForTest();
            SettleFrames(120);

            // ---- 操作条第二轮（2026-09-16）：九格 / 收起 / 提示条 / 颜色面板 / 锁定 / 层级 ----
            Doc.Clear();
            Doc.ClearHistory();
            var bA = FatLine(y0 + 700f, new Color4(1f, 0f, 1f, 1f));
            var bB = FatLine(y0 + 900f, new Color4(1f, 0f, 1f, 1f));
            Doc.AddStroke(bA);
            Doc.AddStroke(bB);
            Doc.SelectOnly(new[] { bA });
            SettleFrames(220);

            var barFrame = LiveSelectionFrame;
            var barBoxR = SelectionHandles.BarRect(barFrame.CanvasAabb, dpi, ViewportCanvas);
            int Bar2White() => ScreenProbe.CountNear((int)barBoxR.MinX, (int)barBoxR.MinY,
                (int)(barBoxR.MaxX - barBoxR.MinX), (int)(barBoxR.MaxY - barBoxR.MinY), 255, 255, 255, 24);

            // ① 九格逐格命中（纯函数，便宜且能钉住"下标 ↔ 语义"不错位）
            bool allHit = true; string hitNote = "";
            for (int i = 0; i < SelectionHandles.BarButtonCount; i++)
            {
                var br = SelectionHandles.BarButtonRect(i, barFrame.CanvasAabb, dpi, ViewportCanvas);
                int got = SelectionHandles.BarButtonAt((br.MinX + br.MaxX) * 0.5f,
                                                      (br.MinY + br.MaxY) * 0.5f,
                                                      barFrame.CanvasAabb, dpi, ViewportCanvas);
                if (got != i) { allHit = false; hitNote = $"第 {i} 格命中成了 {got}"; }
            }
            Check("操作条十格：每格都点得中自己（灰格也占一格——它只是不响应，见下）", allHit,
                  allHit ? $"{SelectionHandles.BarButtonCount} 格逐格核对" : hitNote);

            // ② 收起 / 展开（用户更正：条首那个 ✕ 是"收起工具条"，不是"取消选择"）
            int barWhiteBeforeCollapse = Bar2White();
            RunBarActionForTest((int)SelBarButton.Collapse);
            SettleFrames(140);
            var dotR = SelectionHandles.BarCollapsedRect(barFrame.CanvasAabb, dpi, ViewportCanvas);
            int barWhiteCollapsed = Bar2White();
            int dotWhite = ScreenProbe.CountNear((int)dotR.MinX, (int)dotR.MinY,
                (int)(dotR.MaxX - dotR.MinX), (int)(dotR.MaxY - dotR.MinY), 255, 255, 255, 24);
            bool tookDot = SelectionGestureForTest((dotR.MinX + dotR.MaxX) * 0.5f,
                                                   (dotR.MinY + dotR.MaxY) * 0.5f);
            EndSelectionGestureForTest();
            SettleFrames(140);
            Check("收起：整条没了、圆钮在；点圆钮又展开",
                  // 判据用"白底掉了 80% 以上"而不是"归零"：**圆钮自己就落在条的那块区域里**
                  // （它居中在框下方，和条的横纵位置一致），所以那块不会真的全黑。
                  tookDot && !SelBarCollapsed && barWhiteCollapsed * 5 < barWhiteBeforeCollapse
                  && dotWhite > 300 && Bar2White() > 3000,
                  $"条的白底 {barWhiteBeforeCollapse} → 收起后 {barWhiteCollapsed} → 展开后 {Bar2White()}，"
                  + $"圆钮的白 {dotWhite}（圆心 {dotR.MinX:F0},{dotR.MinY:F0}），"
                  + $"点中圆钮={tookDot}，收起态={SelBarCollapsed}");

            // ③ 颜色面板：点"颜色"开面板 → 点色片改色 → 一次撤销回原色
            RunBarActionForTest((int)SelBarButton.Color);
            SettleFrames(140);
            var panelR = SelectionHandles.PanelRect(barFrame.CanvasAabb, dpi, ViewportCanvas,
                                                    SelectionHandles.SwatchCount);
            int panelWhite = ScreenProbe.CountNear((int)panelR.MinX, (int)panelR.MinY,
                (int)(panelR.MaxX - panelR.MinX), (int)(panelR.MaxY - panelR.MinY), 255, 255, 255, 24);
            int swatchPick = 5;                                   // 橙
            var swR = SelectionHandles.SwatchRect(swatchPick, barFrame.CanvasAabb, dpi, ViewportCanvas,
                                                  SelectionHandles.SwatchCount);
            bool tookSwatch = SelectionGestureForTest((swR.MinX + swR.MaxX) * 0.5f,
                                                     (swR.MinY + swR.MaxY) * 0.5f);
            EndSelectionGestureForTest();
            SettleFrames(140);
            var wantColor = InkPalette.SelectionSwatches[swatchPick].Color;
            bool colorChanged = MathF.Abs(bA.Color.R - wantColor.R) < 0.02f
                             && MathF.Abs(bA.Color.G - wantColor.G) < 0.02f
                             && MathF.Abs(bA.Color.B - wantColor.B) < 0.02f;
            Doc.Undo();
            SettleFrames(140);
            bool colorBack = bA.Color.R > 0.9f && bA.Color.G < 0.1f && bA.Color.B > 0.9f;
            Check("颜色面板：点色片真的改色、一次撤销回原色",
                  SelPanelOpen == SelPanel.Ink && panelWhite > 5000 && tookSwatch
                  && colorChanged && colorBack,
                  $"面板白底 {panelWhite} 像素；改色 {(colorChanged ? "对" : "不对")}，"
                  + $"撤销后回原色 {(colorBack ? "是" : "否")}");

            // ⑤ 粗细滑条：拖到最粗那一档 → Width 变 + 选中框跟着变大
            var sliderT = SelectionHandles.SliderRect(barFrame.CanvasAabb, dpi, ViewportCanvas,
                                                      SelectionHandles.SwatchCount);
            // 档位表由引擎决定（全荧光笔用荧光笔那三档）——自检这边跟着引擎的口径走
            int lastStep = SliderStepCount();
            float wBefore = bA.Width;
            var frameWBeforeBox = LiveSelectionFrame.CanvasAabb;
            float frameWBefore = frameWBeforeBox.MaxX - frameWBeforeBox.MinX;
            float sx = SelectionHandles.SliderStepX(lastStep - 1, lastStep, barFrame.CanvasAabb, dpi,
                                                    ViewportCanvas, SelectionHandles.SwatchCount);
            bool tookSlider = SelectionGestureForTest(sx, (sliderT.MinY + sliderT.MaxY) * 0.5f);
            EndSelectionGestureForTest();
            SettleFrames(140);
            float frameWAfter = LiveSelectionFrame.CanvasAabb.MaxX - LiveSelectionFrame.CanvasAabb.MinX;
            bool widthChanged = bA.Width > wBefore + 1f;
            Check("粗细滑条：拖到最粗 → 墨变粗、选中框跟着变大",
                  tookSlider && widthChanged && frameWAfter > frameWBefore + 1f,
                  $"宽 {wBefore:F1} → {bA.Width:F1}；框宽 {frameWBefore:F0} → {frameWAfter:F0}");
            Doc.Undo();
            SettleFrames(120);

            // ⑥ 锁定（用户定的 B 语义）：锁上以后能选中、但拖不动、也删不掉
            RunBarActionForTest((int)SelBarButton.Color);          // 先收面板（免得盖住条）
            RunBarActionForTest((int)SelBarButton.Lock);
            SettleFrames(120);
            bool lockedNow = bA.Locked;
            var lockC = new Vector2((barFrame.CanvasAabb.MinX + barFrame.CanvasAabb.MaxX) * 0.5f,
                                    (barFrame.CanvasAabb.MinY + barFrame.CanvasAabb.MaxY) * 0.5f);
            int depthBefore = Doc.UndoDepth;
            bool tookLockedDrag = SelectionGestureForTest(lockC.X, lockC.Y);
            UpdateSelectionGestureForTest(lockC.X + 160f, lockC.Y + 60f);
            EndSelectionGestureForTest();
            SettleFrames(120);
            bool stayed = bA.Transform.IsIdentity && Doc.UndoDepth == depthBefore;
            int nBefore = Doc.Strokes.Count;
            RunBarActionForTest((int)SelBarButton.Delete);
            SettleFrames(120);
            bool survivedDelete = Doc.Strokes.Contains(bA) && Doc.Strokes.Count == nBefore;
            Check("锁定：能选中，但拖不动、也删不掉（B 语义）",
                  lockedNow && tookLockedDrag && stayed && survivedDelete,
                  $"锁上={lockedNow}，拖了以后位置 {(bA.Transform.IsIdentity ? "没动" : "动了")}，"
                  + $"撤销栈 +{Doc.UndoDepth - depthBefore}（该是 0），删除后还在={Doc.Strokes.Contains(bA)}");

            // ⑦ 解锁之后能拖（B 语义的另一半：锁是可以随时解开的）
            Doc.SelectOnly(new[] { bA });
            RunBarActionForTest((int)SelBarButton.Lock);           // 再点一次 = 解锁
            SettleFrames(120);
            var unlockC = new Vector2((LiveSelectionFrame.CanvasAabb.MinX + LiveSelectionFrame.CanvasAabb.MaxX) * 0.5f,
                                      (LiveSelectionFrame.CanvasAabb.MinY + LiveSelectionFrame.CanvasAabb.MaxY) * 0.5f);
            SelectionGestureForTest(unlockC.X, unlockC.Y);
            UpdateSelectionGestureForTest(unlockC.X + 120f, unlockC.Y);
            EndSelectionGestureForTest();
            SettleFrames(140);
            Check("解锁之后又能拖了", !bA.Locked && !bA.Transform.IsIdentity,
                  $"锁={bA.Locked}，位置 {(bA.Transform.IsIdentity ? "没动" : "动了")}");
            Doc.Undo();
            SettleFrames(120);

            // ⑧ 层级：置顶（下标关系反过来）→ 一次撤销回原顺序
            Doc.SelectOnly(new[] { bA });
            int idxBefore = Doc.Strokes.IndexOf(bA);
            RunBarActionForTest((int)SelBarButton.Layer);          // 开层级面板
            SettleFrames(120);
            var frontCell = SelectionHandles.LayerCellRect(0, LiveSelectionFrame.CanvasAabb, dpi, ViewportCanvas);
            bool tookFront = SelectionGestureForTest((frontCell.MinX + frontCell.MaxX) * 0.5f,
                                                    (frontCell.MinY + frontCell.MaxY) * 0.5f);
            EndSelectionGestureForTest();
            SettleFrames(140);
            bool onTop = Doc.Strokes.IndexOf(bA) == Doc.Strokes.Count - 1;
            Doc.Undo();
            SettleFrames(140);
            Check("层级：置顶把这一条移到最上，一次撤销回原顺序",
                  tookFront && onTop && Doc.Strokes.IndexOf(bA) == idxBefore,
                  $"下标 {idxBefore} → 置顶后 {Doc.Strokes.Count - 1}（最上）→ 撤销后 {Doc.Strokes.IndexOf(bA)}");

            // ⑨ 导出那一格：**已接**（离屏渲染 → 系统"另存为" → 落盘；自检里对话框是关的）。
            // 判据两条：
            //   · 点了**真的走导出这条路**（`ExportAttempts` +1）——不自检这一步的话，
            //     "点了没反应"和"点了在跑导出"长得一模一样；
            //   · 但**不动文档、不进撤销栈、不改选中**——导出是只读操作，污染文档就是 bug。
            // 屏幕上不弹提示条（用户 2026-09-16 明确不要提示条），只写控制台。
            {
                int n0 = Doc.Strokes.Count, d0 = Doc.UndoDepth, sel0 = Doc.Selected.Count;
                int a0 = ExportAttempts;
                RunBarActionForTest((int)SelBarButton.Export);
                SettleFrames(80);
                Check("导出格子：点了真的走导出，而且不动文档、不进撤销栈",
                      ExportAttempts == a0 + 1
                      && Doc.Strokes.Count == n0 && Doc.UndoDepth == d0 && Doc.Selected.Count == sel0,
                      $"导出 {a0}→{ExportAttempts} 次；对象 {n0}→{Doc.Strokes.Count}，"
                      + $"撤销栈 +{Doc.UndoDepth - d0}，选中 {sel0}→{Doc.Selected.Count}");
            }

            // ---- 选中逻辑三连测（用户点名要的）：一条 / 多条 / 里面混着图片 ----
            {
                // (1) 单选一条：框 = 它自己的墨迹包围盒（不是中心线、也不虚胖）
                Doc.Clear();
                Doc.ClearHistory();
                var one = FatLine(y0 + 700f, new Color4(1f, 0f, 1f, 1f));
                Doc.AddStroke(one);
                Doc.SelectOnly(new[] { one });
                SettleFrames(160);
                var oneF = SelectionHandles.FrameOf(Doc.Selected);
                var oneInk = one.WorldInkBounds;
                bool oneFrameOk = MathF.Abs(oneF.Local.MinX - oneInk.MinX) < 0.01f
                               && MathF.Abs(oneF.Local.MaxY - oneInk.MaxY) < 0.01f;

                // (2) 多条：框 = 并集；**改一次颜色只记一步撤销**；置顶后内部相对顺序不变
                var two = FatLine(y0 + 1000f, new Color4(1f, 0f, 1f, 1f));
                Doc.AddStroke(two);
                Doc.SelectOnly(new[] { one, two });
                SettleFrames(160);
                var twoF = SelectionHandles.FrameOf(Doc.Selected);
                bool twoFrameOk = twoF.Local.MinY < oneInk.MinY + 1f
                               && twoF.Local.MaxY > two.WorldInkBounds.MaxY - 1f;
                int d0 = Doc.UndoDepth;
                SetSelectionColor(InkPalette.SelectionSwatches[9].Color);      // 蓝
                bool bothColored = one.Color.B > 0.8f && two.Color.B > 0.8f;
                bool oneUndo = Doc.UndoDepth == d0 + 1;
                Doc.Undo();
                SettleFrames(120);
                // 置顶要有"别人在下面"才谈得上：再加一条**不选中**的（否则"全选"是特例，
                // 引擎会拒绝并提示"整页都选中了，没有层级可调"——第一版自检就踩了这个）。
                var bystander = FatLine(y0 + 1150f, new Color4(1f, 0f, 1f, 1f));
                Doc.AddStroke(bystander);
                Doc.SelectOnly(new[] { one, two });
                SettleFrames(120);
                int iOne = Doc.Strokes.IndexOf(one), iTwo = Doc.Strokes.IndexOf(two);
                ReorderSelection(toFront: true);                               // 两条一起置顶
                SettleFrames(120);
                bool orderKept = Doc.Strokes.IndexOf(one) < Doc.Strokes.IndexOf(two)
                              && Doc.Strokes.IndexOf(two) == Doc.Strokes.Count - 1;
                Doc.Undo();
                SettleFrames(120);
                bool orderBack = Doc.Strokes.IndexOf(one) == iOne && Doc.Strokes.IndexOf(two) == iTwo;

                // (3) 里面混着图片：改颜色/粗细**跳过图片**，翻转**连图片一起翻**，
                //     删除/框选都算上它（它是普通对象）
                var img3 = ImageData.Adopt(32, 24, new byte[32 * 24 * 4], false);
                var placedImg = img3 != null ? Doc.AddImage(img3, x0 + 200f, y0 + 1300f, 1f) : null;
                if (placedImg != null)
                {
                    Doc.SelectOnly(new[] { one, placedImg });
                    SettleFrames(160);
                    var imgColor = placedImg.Color; var imgWidth = placedImg.Width;
                    int d1 = Doc.UndoDepth;
                    SetSelectionColor(InkPalette.SelectionSwatches[5].Color);  // 橙
                    bool imgColorKept = placedImg.Color.Equals(imgColor);
                    bool inkChanged = one.Color.R > 0.9f && one.Color.G > 0.4f && one.Color.B < 0.2f;
                    SetSelectionWidth(24f);
                    bool imgWidthKept = MathF.Abs(placedImg.Width - imgWidth) < 0.01f;
                    bool twoSteps = Doc.UndoDepth == d1 + 2;
                    Doc.Undo(); Doc.Undo();
                    SettleFrames(160);
                    // 翻转：图像也该跟着翻（M11 变负）
                    Doc.SelectOnly(new[] { placedImg });
                    Doc.ApplyTransform(SelectionHandles.MirrorMatrix(placedImg.WorldInkBounds, true));
                    SettleFrames(120);
                    bool imgFlipped = placedImg.Transform.M11 < -0.5f;
                    Check("含图片的选中：改色/改粗细跳过图片、翻转照翻、各记一步撤销",
                          imgColorKept && inkChanged && imgWidthKept && twoSteps && imgFlipped,
                          $"图片颜色 {(imgColorKept ? "没动" : "被改了")}、粗细 {(imgWidthKept ? "没动" : "被改了")}；"
                          + $"墨变色={(inkChanged ? "是" : "否")}；两步撤销={(twoSteps ? "对" : "错")}；"
                          + $"图片翻转={(imgFlipped ? "翻了" : "没翻")}");
                }
                Check("单选一条 / 多选多条：框按墨迹范围、多选按并集，改一次只记一步撤销",
                      oneFrameOk && twoFrameOk && bothColored && oneUndo && orderKept && orderBack,
                      $"单选框贴合墨迹={(oneFrameOk ? "是" : "否")}，多选并集={(twoFrameOk ? "是" : "否")}，"
                      + $"两条都变色={(bothColored ? "是" : "否")}，一步撤销={(oneUndo ? "对" : "错")}，"
                      + $"置顶保持内部顺序={(orderKept && orderBack ? "是" : "否")}");
            }

            BoardOn = boardWas;
            BoardColor = boardColorWas;
            ViewOffsetY = camWas;
            Doc.Clear();
            Doc.ClearHistory();
        }

        Console.WriteLine();
        Console.WriteLine($"  合计 {pass + fail} 项：通过 {pass}，失败 {fail}");
        Console.WriteLine();
        Doc.Clear();
        Doc.ClearHistory();
        _quit = true;
    }

    /// <summary>
    /// 笔迹两端自检：**圆头端帽**。
    ///
    /// 这一层以前把带子两侧的端点直接用直线连起来，于是两端是被切平的方块：
    /// 宽笔拖出来像一根长条尺子，单击一下也不是圆点、而是一小段扁条。
    /// 现在两端各补一段半圆（半径 = 端点处的半宽），收尾自然收成半圆。
    ///
    /// 判定分两层，缺一层都说明不了问题：
    ///   ① **几何精确判定**：直接问 Direct2D"端帽里那个点有没有被墨盖住"
    ///      （FillContainsPoint，和命中测试用的是同一条几何）；
    ///   ② **屏幕上数像素**：端帽那一小块到底有多少墨在真正的屏幕上。
    /// 只看①会漏掉"几何对了但没画出来"，只看②会分不清形状错了还是没上屏。
    /// 最后再导一张图，人能一眼看形状。
    /// </summary>
    private void CapTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 笔迹两端自检（单击＝圆点，宽笔＝圆头收尾）===");
        Console.WriteLine($"  本机 DPI 缩放 {DpiScale:F2}");

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-34} {detail}");
        }

        float w = 40f * DpiScale;                       // 宽笔：端帽形状在粗笔上最显眼
        float r = w * 0.5f;
        float x0 = _virtualX + 380f, y0 = _virtualY + 320f;
        var ink = new Color4(1f, 0f, 1f, 1f);           // 品红：便于在屏幕上数像素

        // ---------- ① 单击：一个采样点 → 一个圆 ----------
        var click = new Stroke { Tool = Tool.Pen, Color = ink, Width = w };
        click.AddPoint(x0, y0, 0.5f, NowMs);
        var gClick = click.BuildGeometry(Gfx.D2DFactory);
        // 单点笔迹的几何本身就是那个圆 → 用填充判定
        Check("单击 · 圆心有墨", gClick.FillContainsPoint(new Vector2(x0, y0)), "");
        Check("单击 · 半径内 0.95r 有墨",
            gClick.FillContainsPoint(new Vector2(x0 + r * 0.95f, y0)), $"r = {r:F0}px");
        Check("单击 · 半径外 1.1r 没墨",
            !gClick.FillContainsPoint(new Vector2(x0 + r * 1.1f, y0)), "");

        // ---------- ② 短拖（2 个采样点）：两端都是半圆 ----------
        var drag = new Stroke { Tool = Tool.Pen, Color = ink, Width = w };
        float dx = x0 + 240f, dy = y0, len = 140f;
        drag.AddPoint(dx, dy, 0.5f, NowMs);
        drag.AddPoint(dx + len, dy, 0.5f, NowMs);
        var gDrag = drag.BuildGeometry(Gfx.D2DFactory);
        // 两点以上的笔迹，几何是**中心线**，墨是 D2D 描出来的 →
        // 判定要用描边判定（和画出来用的是同一条几何、同一个描边样式）。
        bool InkedAt(ID2D1Geometry geo, Stroke s, float x, float y)
            => geo.StrokeContainsPoint(new Vector2(x, y), MathF.Max(1f, s.Width), Gfx.Round);

        // 端点"正前方"只有圆头端帽盖得到：平头的话这里一定是空的。
        Check("短拖 · 收笔正前方 0.8r 有墨（圆头）",
            InkedAt(gDrag, drag, dx + len + r * 0.8f, dy), "");
        Check("短拖 · 起笔正后方 0.8r 有墨（圆头）",
            InkedAt(gDrag, drag, dx - r * 0.8f, dy), "");
        Check("短拖 · 端帽外 1.1r 没墨（半圆，不是超出去的方块）",
            !InkedAt(gDrag, drag, dx + len + r * 1.1f, dy), "");
        Check("短拖 · 侧面外 1.1r 没墨",
            !InkedAt(gDrag, drag, dx + len * 0.5f, dy + r * 1.1f), "");

        // ---------- ③ 起笔连报重复坐标：方向不能翻车 ----------
        // 鼠标刚按下的一瞬间经常连报好几个相同坐标。方向要取"前后各一个真的
        // 不一样的点"，否则会被强行当成水平，起笔处的轮廓就歪了。
        var dup = new Stroke { Tool = Tool.Pen, Color = ink, Width = w };
        float ex = x0, ey = y0 + 200f;
        dup.AddPoint(ex, ey, 0.5f, NowMs);
        dup.AddPoint(ex, ey, 0.5f, NowMs);
        dup.AddPoint(ex, ey, 0.5f, NowMs);
        dup.AddPoint(ex + 200f, ey + 200f, 0.5f, NowMs);   // 斜着走
        var gDup = dup.BuildGeometry(Gfx.D2DFactory);
        var d = Vector2.Normalize(new Vector2(1f, 1f));    // 真实前进方向
        Check("重复点起笔 · 正后方 0.95r 有墨（端帽朝反方向鼓）",
            InkedAt(gDup, dup, ex - d.X * r * 0.95f, ey - d.Y * r * 0.95f), "");
        Check("重复点起笔 · 正后方 1.1r 没墨",
            !InkedAt(gDup, dup, ex - d.X * r * 1.1f, ey - d.Y * r * 1.1f), "");

        // ---------- ④ 真的画到屏幕上再数一遍像素 ----------
        Doc.Clear();
        Doc.AddStroke(click);
        Doc.AddStroke(drag);
        Doc.AddStroke(dup);

        float hlW = 32f * DpiScale;
        var hl = new Stroke
        {
            Tool = Tool.Highlighter, Color = HighlighterCurrent, Width = hlW,
        };
        hl.AddPoint(x0, y0 + 400f, 0.5f, NowMs);
        hl.AddPoint(x0 + 420f, y0 + 400f, 0.5f, NowMs);
        Doc.AddStroke(hl);

        // 竖着拖一笔：端帽是"斜着/竖着"的时候也得成立（横线和竖线走的
        // 是同一条几何路径，但画到屏幕上的方向完全不同）。
        var vert = new Stroke { Tool = Tool.Pen, Color = ink, Width = w };
        float vx = x0 + 560f, vy = y0 - 40f;
        vert.AddPoint(vx, vy, 0.5f, NowMs);
        vert.AddPoint(vx, vy + 320f, 0.5f, NowMs);
        Doc.AddStroke(vert);
        Doc.InvalidateAll();
        SettleFrames(700);

        int dotIn = ScreenProbe.CountMagenta((int)(x0 - r), (int)(y0 - r), (int)(2 * r), (int)(2 * r));
        int dotCorner = ScreenProbe.CountMagenta((int)(x0 + r * 0.75f), (int)(y0 + r * 0.75f),
                                                 (int)(r * 0.6f), (int)(r * 0.6f));
        float expect = MathF.PI * r * r;
        Check("单击上屏 · 圆点墨量对得上面积",
            Math.Abs(dotIn - expect) < expect * 0.12f,
            $"实测 {dotIn} / 理论 {expect:F0}（{dotIn / expect:P0}）");
        Check("单击上屏 · 圆的外角没有墨（不是方块）", dotCorner == 0, $"角上 {dotCorner} 像素");

        int capPx = ScreenProbe.CountMagenta((int)(dx + len + r * 0.1f), (int)(dy - r * 0.3f),
                                            (int)(r * 0.8f), (int)(r * 0.6f));
        int capFlat = ScreenProbe.CountMagenta((int)(dx + len + r * 1.15f), (int)(dy - r * 0.3f),
                                              (int)(r * 0.4f), (int)(r * 0.6f));
        Check("宽笔上屏 · 端帽那一段有墨", capPx > 200, $"端帽区 {capPx} 像素");
        Check("宽笔上屏 · 端帽外是空的", capFlat == 0, $"外侧 {capFlat} 像素");

        int vertBody = ScreenProbe.CountMagenta((int)(vx - r * 0.9f), (int)(vy + 60f),
                                                (int)(r * 1.8f), (int)(200f * DpiScale));
        int vertCap = ScreenProbe.CountMagenta((int)(vx - r * 0.3f), (int)(vy + 320f + r * 0.1f),
                                               (int)(r * 0.6f), (int)(r * 0.8f));
        Check("竖笔上屏 · 笔身有墨", vertBody > 20000, $"笔身区 {vertBody} 像素");
        Check("竖笔上屏 · 收笔端帽有墨", vertCap > 200, $"端帽区 {vertCap} 像素");

        string shot = Path.Combine("reports", "端帽-圆头.bmp");
        bool saved = ScreenProbe.SaveBmp(shot, (int)(x0 - 120f), (int)(y0 - 160f), 900, 700);
        Console.WriteLine(saved ? $"  （已导出 {shot}：单击圆点 / 短拖 / 斜拖 / 荧光笔 / 竖拖）"
                                : "  导出失败");

        Console.WriteLine();
        Console.WriteLine($"  合计 {pass + fail} 项：通过 {pass}，失败 {fail}");
        Console.WriteLine();
        _quit = true;
    }

    /// <summary>
    /// 坐标系 / 数轴自检（2026-09-19 第三批）。
    ///
    /// 四层判据，缺一层都可能"看着绿其实没做"：
    ///   ① **画法**：真机拖一下 → 定义元素按规格落地（**原点 = 按下点**、外框 = 原点对称展开
    ///      出来的半宽半高）；
    ///   ② **手柄**：三个顶点柄、**没有旋转柄**、别的 SelHandle 不留后门；
    ///      并真拖一遍——原点"框不动"、拖出框外会被夹回来；
    ///   ③ **屏幕**：两条轴真的上屏（轴上有墨、框里空白处没墨），打开网格墨量明显变多；
    ///   ④ **存档**：v10 往返（含网格与压感那两位）；再造一个**真·v8 老文件**
    ///      （见 MakeLegacyFile），读进来必须是"没有网格"（老文件本来就没这个概念）。
    /// </summary>
    private void AxisTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 坐标系 / 数轴自检 ===");
        Console.WriteLine($"  本机 DPI 缩放 {DpiScale:F2}");

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-34} {detail}");
        }

        // 屏幕坐标 == 画布坐标（探针才好对位），和 O 段同一套做法。
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }

        const int ProbeHalf = 12;
        const int HasInk = 60, NoInk = 20;
        int Ink(float x, float y)
            => ScreenProbe.CountMagenta((int)x - ProbeHalf, (int)y - ProbeHalf,
                                        ProbeHalf * 2, ProbeHalf * 2);
        // ⚠ 这里原来还有一个 `WholeInk`（整块数品红像素），专门用来判"网格那些线画出来了没有"。
        // 网格改成"细一半、淡一半"之后它就不再适用（0.45 alpha 的像素不是纯品红，数不到），
        // ④ 那一段改用了**前后差分**，于是它没了用武之地——删掉，别留着当摆设。
        bool Near(float a, float b, float tol) => MathF.Abs(a - b) <= tol;

        // **探针数的是品红**，所以真机拖出来的图形也必须是品红：
        // 画笔的当前色默认是红的，不换色的话"轴上屏了吗"这一条永远是 0 像素
        // ——第一版就是这么假失败的（图形好好地画在那儿，只是颜色不对）。
        Host.Commands.SetColor(new Color4(1f, 0f, 1f, 1f));

        // ================= ① 画法：真机拖一个外框 =================
        Doc.Clear();
        Doc.ClearHistory();
        SetToolFromUi(Tool.Coordinate);
        float x0 = _virtualX + 500f, y0 = _virtualY + 420f;
        float bw = 800f, bh = 600f;
        SendMouse((int)x0, (int)y0, 0);                              SettleFrames(60);
        SendMouse((int)x0, (int)y0, Native.MOUSEEVENTF_LEFTDOWN);    SettleFrames(60);
        for (int i = 1; i <= 4; i++)
        {
            SendMouse((int)(x0 + bw * i / 4f), (int)(y0 + bh * i / 4f), 0);
            SettleFrames(30);
        }
        SendMouse((int)(x0 + bw), (int)(y0 + bh), Native.MOUSEEVENTF_LEFTUP); SettleFrames(220);

        var cs = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
        Check("坐标系：拖出一个坐标系对象",
              cs != null && cs.Kind == StrokeKind.Coordinate,
              cs == null ? "没有对象" : $"Kind={cs.Kind}");
        if (cs == null) { Console.WriteLine("  （后面几项没法验）"); _quit = true; return; }

        Check("坐标系：三个定义元素（外框两角 / 原点）",
              cs.Points.Count == 3, $"控制点 {cs.Points.Count} 个");
        // 按下点 = **原点**（用户 2026-09-19："先确定原点，原点确定以后，再把它展开"）；
        // 外框 = 原点 ± 拖动量（对称展开，所以框是拖出来的那个框的两倍大、原点在正中间）。
        var fr = cs.AxisFrameLocal();
        Check("坐标系：外框 = 原点 ± 拖动量（对称展开，±2 像素）",
              Near(fr.MinX, x0 - bw, 2f) && Near(fr.MinY, y0 - bh, 2f)
              && Near(fr.MaxX, x0 + bw, 2f) && Near(fr.MaxY, y0 + bh, 2f),
              $"框 ({fr.MinX:F0},{fr.MinY:F0})..({fr.MaxX:F0},{fr.MaxY:F0})"
              + $" 期望 ({x0 - bw:F0},{y0 - bh:F0})..({x0 + bw:F0},{y0 + bh:F0})");
        var o0 = cs.AxisOriginLocal();
        Check("坐标系：**原点就是按下的那个点**（±2 像素）",
              Near(o0.X, x0, 2f) && Near(o0.Y, y0, 2f),
              $"原点 ({o0.X:F0},{o0.Y:F0}) 期望按下点 ({x0:F0},{y0:F0})");
        Check("坐标系：一次拖拽 = 一步撤销", Doc.UndoDepth == 1, $"撤销栈 {Doc.UndoDepth} 步");

        // ================= ② 手柄：三格、无旋转柄、不留后门 =================
        Span<ShapeHandle> handles = stackalloc ShapeHandle[5];
        int hn = SelectionHandles.ShapeHandlesOf(cs, handles);
        Check("坐标系：三个顶点柄",
              hn == 3 && handles[0] == ShapeHandle.Vertex0 && handles[2] == ShapeHandle.Vertex2,
              $"{hn} 个，第 3 格 = {(hn > 2 ? handles[2].ToString() : "无")}");
        Check("坐标系：**不给旋转柄**（转歪了就不是坐标系了）",
              !SelectionHandles.RotateHandleVisible(cs), "");
        Check("坐标系：八向缩放柄不留后门（翻译成 None）",
              SelectionHandles.HandleOf(cs, SelHandle.TopLeft) == ShapeHandle.None
              && SelectionHandles.HandleOf(cs, SelHandle.Right) == ShapeHandle.None,
              $"TopLeft → {SelectionHandles.HandleOf(cs, SelHandle.TopLeft)}");
        Check("坐标系：顶点柄 ↔ SelHandle 双向对得上",
              SelectionHandles.HandleOf(cs, SelHandle.VertexD) == ShapeHandle.Vertex3
              && SelectionHandles.SelHandleOf(ShapeHandle.Vertex3) == SelHandle.VertexD,
              "");

        // ================= ③ 屏幕：轴真的上屏、框里是空的 =================
        Doc.SelectOnly(Array.Empty<Stroke>());     // 先取消选中，免得选中框和手柄混进探针
        SettleFrames(300);
        // 原点在**按下的那个点**上，所以两条轴分别过 (任意 x, y0) 与 (x0, 任意 y)。
        int onXAxis = Ink(x0 + bw * 0.2f, y0);                  // x 轴那一行、离原点远一点
        int onYAxis = Ink(x0, y0 - bh * 0.2f);                  // y 轴那一列
        int inBlank = Ink(x0 + bw * 0.5f, y0 + bh * 0.5f);      // 第一象限中间：两条轴都够不着
        Check("屏幕：x 轴那一行有墨", onXAxis > HasInk, $"{onXAxis} 像素（期望 >{HasInk}）");
        Check("屏幕：y 轴那一列有墨", onYAxis > HasInk, $"{onYAxis} 像素（期望 >{HasInk}）");
        Check("屏幕：框里的空白处没有墨（不是画了个框）",
              inBlank <= NoInk, $"{inBlank} 像素（期望 ≤{NoInk}）");

        // ---- 拖原点：**框不动**（这是老师最常用的那个动作）----
        Tool = Tool.Marquee;
        Doc.SelectOnly(new[] { cs });
        SettleFrames(300);
        var frameBefore = cs.AxisFrameLocal();
        var oHandle = SelectionHandles.ShapeHandleCanvasPosition(cs, ShapeHandle.Vertex2);
        var oTarget = new Vector2(fr.MinX + 60f, fr.MaxY - 60f);      // 拖到框的左下角附近
        bool tookO = SelectionGestureForTest(oHandle.X, oHandle.Y);
        UpdateSelectionGestureForTest(oTarget.X, oTarget.Y);
        SettleFrames(120);
        EndSelectionGestureForTest();
        SettleFrames(200);
        var frameAfter = cs.AxisFrameLocal();
        Check("拖原点：真的抓住了原点手柄", tookO, $"起点 ({oHandle.X:F0},{oHandle.Y:F0})");
        Check("拖原点：原点到了目标位置（±2 像素）",
              Near(cs.AxisOriginLocal().X, oTarget.X, 2f) && Near(cs.AxisOriginLocal().Y, oTarget.Y, 2f),
              $"原点 ({cs.AxisOriginLocal().X:F0},{cs.AxisOriginLocal().Y:F0})"
              + $" 期望 ({oTarget.X:F0},{oTarget.Y:F0})");
        Check("拖原点：**外框一分不动**（哪部分是范围、哪部分是原点，各管各的）",
              Near(frameAfter.MinX, frameBefore.MinX, 0.01f)
              && Near(frameAfter.MaxX, frameBefore.MaxX, 0.01f)
              && Near(frameAfter.MinY, frameBefore.MinY, 0.01f)
              && Near(frameAfter.MaxY, frameBefore.MaxY, 0.01f),
              $"框 {frameBefore.MinX:F0},{frameBefore.MinY:F0}..{frameBefore.MaxX:F0},{frameBefore.MaxY:F0} 未变");

        // 原点拖出框外要被夹回来（跑到框外，两条轴就都不在框里交叉了）
        {
            var far = new Vector2(fr.MaxX + 900f, fr.MaxY + 900f);
            SelectionGestureForTest(SelectionHandles.ShapeHandleCanvasPosition(cs, ShapeHandle.Vertex2).X,
                                    SelectionHandles.ShapeHandleCanvasPosition(cs, ShapeHandle.Vertex2).Y);
            UpdateSelectionGestureForTest(far.X, far.Y);
            SettleFrames(120);
            EndSelectionGestureForTest();
            SettleFrames(200);
            var ov = cs.AxisOriginLocal();
            Check("拖原点：拖出框外会被夹回框里（轴永远不会跑出框）",
                  ov.X <= fr.MaxX + 0.5f && ov.Y <= fr.MaxY + 0.5f
                  && ov.X >= fr.MinX - 0.5f && ov.Y >= fr.MinY - 0.5f,
                  $"原点 ({ov.X:F0},{ov.Y:F0})，框 ({fr.MinX:F0},{fr.MinY:F0})..({fr.MaxX:F0},{fr.MaxY:F0})");
        }

        // ---- 拖外框角：改范围 ----
        var cHandle = SelectionHandles.ShapeHandleCanvasPosition(cs, ShapeHandle.Vertex0);
        var cTarget = new Vector2(cHandle.X - 120f, cHandle.Y - 90f);
        SelectionGestureForTest(cHandle.X, cHandle.Y);
        UpdateSelectionGestureForTest(cTarget.X, cTarget.Y);
        SettleFrames(120);
        EndSelectionGestureForTest();
        SettleFrames(200);
        Check("拖外框角：外框跟着变大（±2 像素）",
              Near(cs.AxisFrameLocal().MinX, cTarget.X, 2f)
              && Near(cs.AxisFrameLocal().MinY, cTarget.Y, 2f),
              $"左上角 ({cs.AxisFrameLocal().MinX:F0},{cs.AxisFrameLocal().MinY:F0})"
              + $" 期望 ({cTarget.X:F0},{cTarget.Y:F0})");

        // ---- 紧框就是"定义点的外接 + 半笔宽"（**刻度取消之后不该再虚报那一截**）----
        {
            var wb = cs.WorldInkBounds;
            var f2 = cs.AxisFrameLocal();
            float halfPen = cs.Width * 0.5f;
            // 外框宽 + 半笔宽 ×2 = 紧框宽（±2 像素：渲染那边还会各留一点抗锯齿余量）。
            float needW = (f2.MaxX - f2.MinX) + halfPen * 2f;
            Check("紧框：等于「外框 + 半笔宽」（没有刻度就不该再往外多算）",
                  Near(wb.MaxX - wb.MinX, needW, 2.5f),
                  $"紧框宽 {wb.MaxX - wb.MinX:F1}，期望 {needW:F1}"
                  + $"（外框 {f2.MaxX - f2.MinX:F0} + 2×{halfPen:F1}）");
        }

        // ================= ④ 网格：开着比关着**屏幕上真的多了那些格线** =================
        //
        // ⚠ **判据 2026-09-24 换过**：网格改成"细一半、淡一半"之后，它的像素是 0.45 alpha
        // 混过背景的——**不再是纯品红**，`CountMagenta` 数不到它（实测"关 18882 → 开 18925"，
        // 只多出 43 个像素，看着像"格线没画出来"）。所以改照 `--paneltest` 那套
        // **前后差分**（同一块区域开 / 关各截一次，数"变了的像素"）：
        // 这比"数某种颜色"更贴问题本身——要问的就是"那些格线有没有上屏"。
        {
            Doc.Clear();
            Doc.ClearHistory();
            Tool = Tool.Marquee;
            var g = MakeCoordinateForTest(x0, y0 + 300f, 400f, 300f, grid: false);
            Doc.AddStroke(g);
            Doc.SelectOnly(new[] { g });
            Doc.InvalidateAll();
            SettleFrames(400);
            var wb = g.WorldInkBounds;
            int gx0 = (int)wb.MinX - 20, gy0 = (int)wb.MinY - 20;
            int gw0 = (int)(wb.MaxX - wb.MinX) + 40, gh0 = (int)(wb.MaxY - wb.MinY) + 40;
            var shotOff = ScreenProbe.CaptureRegion(gx0, gy0, gw0, gh0);

            int changed = ToggleSelectionGrid();       // 选中了坐标系 → 改的是它
            SettleFrames(400);
            var shotOn = ScreenProbe.CaptureRegion(gx0, gy0, gw0, gh0);
            int gridPix = ScreenProbe.DiffCount(shotOff, shotOn);
            Check("网格：选中坐标系时点那一下改的是它（返回 1）", changed == 1, $"返回 {changed}");
            Check("网格：开关落到对象身上", g.Grid, $"Grid = {g.Grid}");
            Check("网格：开了之后**屏幕上真的多出格线**（前后差分，关 → 开）",
                  gridPix > 300, $"{gridPix} 个像素变了");
            Doc.Undo();
            SettleFrames(200);
            Check("网格：一步撤销能回到没有网格", !g.Grid, $"Grid = {g.Grid}");
        }

        // ================= ⑤ 数轴：水平锁 + 右端箭头 =================
        {
            Doc.Clear();
            Doc.ClearHistory();
            SetToolFromUi(Tool.NumberLine);
            float nx = _virtualX + 500f, ny = _virtualY + 1400f, nl = 900f;
            SendMouse((int)nx, (int)(ny + 300f), 0);                     SettleFrames(60);
            SendMouse((int)nx, (int)(ny + 300f), Native.MOUSEEVENTF_LEFTDOWN); SettleFrames(60);
            for (int i = 1; i <= 4; i++)
            {
                // 故意**斜着**拖：数轴必须还是水平的（y 钉在按下点那一行）。
                SendMouse((int)(nx + nl * i / 4f), (int)(ny + 300f - 120f * i / 4f), 0);
                SettleFrames(30);
            }
            SendMouse((int)(nx + nl), (int)(ny + 180f), Native.MOUSEEVENTF_LEFTUP); SettleFrames(220);

            var nl0 = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
            Check("数轴：拖出一个数轴对象",
                  nl0 != null && nl0.Kind == StrokeKind.NumberLine,
                  nl0 == null ? "没有对象" : $"Kind={nl0?.Kind}");
            if (nl0 != null)
            {
                Check("数轴：两个定义元素（左端 / 右端）",
                      nl0.Points.Count == 2, $"控制点 {nl0.Points.Count} 个");
                Check("数轴：斜着拖也还是水平的（两个点 y 相同）",
                      Near(nl0.Points[0].Y, ny + 300f, 2f) && Near(nl0.Points[1].Y, ny + 300f, 2f),
                      $"两个点 y = {nl0.Points[0].Y:F0} / {nl0.Points[1].Y:F0}"
                      + $"（按下点 {ny + 300f:F0}）");
                Span<ShapeHandle> nlh = stackalloc ShapeHandle[5];
                Check("数轴：两个顶点柄（没有刻度之后不再有零点/单位长度两个柄）",
                      SelectionHandles.ShapeHandlesOf(nl0, nlh) == 2
                      && nlh[0] == ShapeHandle.Vertex0 && nlh[1] == ShapeHandle.Vertex1,
                      $"{SelectionHandles.ShapeHandlesOf(nl0, nlh)} 个");

                // 拖右端到斜上方：x 要走过去，y 一动不动。
                Tool = Tool.Marquee;
                Doc.SelectOnly(new[] { nl0 });
                SettleFrames(300);
                var rHandle = SelectionHandles.ShapeHandleCanvasPosition(nl0, ShapeHandle.Vertex1);
                var rTarget = new Vector2(rHandle.X - 150f, rHandle.Y - 260f);
                SelectionGestureForTest(rHandle.X, rHandle.Y);
                UpdateSelectionGestureForTest(rTarget.X, rTarget.Y);
                SettleFrames(120);
                EndSelectionGestureForTest();
                SettleFrames(200);
                Check("数轴：拖右端到斜上方 → x 跟过去、y 一动不动",
                      Near(nl0.Points[1].X, rTarget.X, 2f)
                      && Near(nl0.Points[1].Y, rTarget.Y + 260f, 0.01f),
                      $"右端 ({nl0.Points[1].X:F0},{nl0.Points[1].Y:F0})"
                      + $" 期望 ({rTarget.X:F0},{rTarget.Y + 260f:F0})");

                Doc.SelectOnly(Array.Empty<Stroke>());
                SettleFrames(300);
                int nlInk = Ink(nx + nl * 0.5f, ny + 300f);
                Check("数轴：线本身有墨上屏", nlInk > HasInk, $"{nlInk} 像素");
            }
        }

        // ================= ⑤ 格距手柄（**开网格才有**）：拖动 / 夹范围 / 一步撤销 ==========
        //
        // 用户 2026-09-24："那个坐标系坐标原点现在不是有一个空心点吗？选中的时候它是可以拖动的。
        // 那么我打算那个第一个方格那个格点，它也做一个空心点，这样的话我就可以通过拖动那个点
        // 来改变这个方格的大小。"
        // 落点 = **第 4 颗手柄**，位置 = 第一象限第一个格子的外角 = 原点 ＋ (格距, −格距)。
        // 盯五件事：① 只在开网格时才有；② 位置真的在那个格点上；③ 拖它只改格距、
        // **三个控制点一个字不动**；④ 一步撤销回得去；⑤ 拖到天边也只夹到外框短边。
        {
            Doc.Clear();
            Doc.ClearHistory();
            Tool = Tool.Marquee;
            var gh = MakeCoordinateForTest(x0, y0 + 1600f, 500f, 400f, grid: true);
            gh.AxisGridStep = 0f;                       // 从「自动」那一档起手
            Doc.AddStroke(gh);
            Doc.SelectOnly(new[] { gh });
            SettleFrames(300);

            float autoStep = gh.AxisGridStepLocal();
            Span<ShapeHandle> hbuf = stackalloc ShapeHandle[5];
            int hn2 = SelectionHandles.ShapeHandlesOf(gh, hbuf);
            Check("格距手柄：开网格之后是**四颗**，第 4 颗是 Vertex3",
                  hn2 == 4 && hbuf[3] == ShapeHandle.Vertex3, $"{hn2} 颗");
            var hpos = SelectionHandles.ShapeHandleCanvasPosition(gh, ShapeHandle.Vertex3);
            var gridOrg = gh.AxisOriginLocal();
            Check("格距手柄：落在**第一象限第一个格子的外角**（右上：x 加、y 减）",
                  Near(hpos.X, gridOrg.X + autoStep, 1.5f) && Near(hpos.Y, gridOrg.Y - autoStep, 1.5f),
                  $"手柄 ({hpos.X:F0},{hpos.Y:F0}) 期望 ({gridOrg.X + autoStep:F0},{gridOrg.Y - autoStep:F0})");

            // 拖到「每格大一半」的位置：手柄本来在原点 +(s,−s)，目标放到原点 +(1.5s,−1.5s)
            var pts0 = new[]
            {
                new Vector2(gh.Points[0].X, gh.Points[0].Y),
                new Vector2(gh.Points[1].X, gh.Points[1].Y),
                new Vector2(gh.Points[2].X, gh.Points[2].Y),
            };
            int undoBeforeDrag = Doc.UndoDepth;   // 拖之前现取底数
            SelectionGestureForTest(hpos.X, hpos.Y);
            UpdateSelectionGestureForTest(hpos.X + autoStep * 0.5f, hpos.Y - autoStep * 0.5f);
            SettleFrames(120);
            EndSelectionGestureForTest();
            SettleFrames(200);
            Check("格距手柄：拖完格距就是拖到的那一档（±3%）",
                  Near(gh.AxisGridStepLocal(), autoStep * 1.5f, autoStep * 0.03f),
                  $"格距 {gh.AxisGridStepLocal():F1}，期望 {autoStep * 1.5f:F1}");
            Check("格距手柄：**三个控制点一个字都没动**（它不是控制点）",
                  Near(gh.Points[0].X, pts0[0].X, 0.01f) && Near(gh.Points[1].Y, pts0[1].Y, 0.01f)
                  && Near(gh.Points[2].X, pts0[2].X, 0.01f) && Near(gh.Points[2].Y, pts0[2].Y, 0.01f),
                  $"原点 ({gh.Points[2].X:F0},{gh.Points[2].Y:F0})");
            // 底数由「拖之前」现取：AddStroke 自己也占一步撤销，写死数字会随功能移位而假红
            Check("格距手柄：一次拖拽 = 一步撤销", Doc.UndoDepth == undoBeforeDrag + 1,
                  $"撤销栈 {undoBeforeDrag} → {Doc.UndoDepth} 步");

            Doc.Undo();
            SettleFrames(120);
            Check("格距手柄：撤销回到「自动」那一档（0）",
                  Near(gh.AxisGridStep, 0f, 0.001f), $"格距字段 {gh.AxisGridStep:F2}（期望 0 = 自动）");
            Doc.Redo();
            SettleFrames(120);

            // 拖到很远处：只能夹到「外框短边」为止（再大就一个格子都看不见了）
            var hpos2 = SelectionHandles.ShapeHandleCanvasPosition(gh, ShapeHandle.Vertex3);
            SelectionGestureForTest(hpos2.X, hpos2.Y);
            UpdateSelectionGestureForTest(hpos2.X + 5000f, hpos2.Y - 5000f);
            SettleFrames(120);
            EndSelectionGestureForTest();
            SettleFrames(200);
            var fr2 = gh.AxisFrameLocal();
            float shortSide = MathF.Min(fr2.MaxX - fr2.MinX, fr2.MaxY - fr2.MinY);
            Check("格距手柄：拖到天边也只夹到「外框短边」为止",
                  gh.AxisGridStepLocal() <= shortSide + 0.5f,
                  $"格距 {gh.AxisGridStepLocal():F0}，外框短边 {shortSide:F0}");

            // 关掉网格 → 第 4 颗必须消失（没格子就没有「第一个格子」）
            gh.Grid = false;
            gh.InvalidateMetrics();
            Doc.SelectOnly(new[] { gh });
            SettleFrames(200);
            Check("格距手柄：**关掉网格就没有第 4 颗**（不留看不见却点得到的死元素）",
                  SelectionHandles.ShapeHandlesOf(gh, hbuf) == 3,
                  $"{SelectionHandles.ShapeHandlesOf(gh, hbuf)} 颗");
        }

        // ================= ⑥ 存档：v9 往返 + 真·v8 老文件 =================
        {
            Doc.Clear();
            Doc.ClearHistory();
            var a1 = MakeCoordinateForTest(x0, y0, bw, bh, grid: true);
            // v24：拖过格距的那些，格距要跟着存档走（**不是 0**，0 是"自动"、
            // 和"拖过"分不开，这里特意挑一个非整、非默认的数）。
            a1.AxisGridStep = 37.5f;
            var a2 = MakeNumberLineForTest(x0, y0 + 800f, 600f);
            Doc.AddStroke(a1);
            Doc.AddStroke(a2);

            byte[] blob = InkSerializer.Save(Doc);
            var back = new InkDocument();
            InkSerializer.LoadInto(back, blob);
            Check("存档：读回两条都在", back.Strokes.Count == 2, $"读回 {back.Strokes.Count} 条");
            Check("存档：坐标系读回来还是坐标系、网格位也在",
                  back.Strokes.Count > 0 && back.Strokes[0].Kind == StrokeKind.Coordinate
                  && back.Strokes[0].Grid && back.Strokes[0].Points.Count == 3,
                  back.Strokes.Count > 0
                      ? $"{back.Strokes[0].Kind}，网格 {back.Strokes[0].Grid}，"
                        + $"{back.Strokes[0].Points.Count} 个点"
                      : "条数不对");
            Check("存档：数轴读回来还是数轴（第二条，能验出闸门错位）",
                  back.Strokes.Count > 1 && back.Strokes[1].Kind == StrokeKind.NumberLine
                  && back.Strokes[1].Points.Count == 2,
                  back.Strokes.Count > 1 ? $"{back.Strokes[1].Kind}" : "条数不对");
            // v24 那一位：格距往返（0 = 自动也算"带回来了"，所以这里挑的是 37.5）
            Check("存档：拖过的**格距**读回来原样（v24 那一位）",
                  back.Strokes.Count > 0 && Near(back.Strokes[0].AxisGridStep, 37.5f, 0.01f),
                  back.Strokes.Count > 0 ? $"{back.Strokes[0].AxisGridStep:F1}（期望 37.5）" : "条数不对");

            // 真·v8 老文件（见 MakeLegacyFile）：读进来必须是"没有网格"。
            // 砍 4 位 = v9 网格 ＋ v10 压感 ＋ v11 朝向 ＋ v12 渐近线（**v13 没加字段**）。
            var one = new InkDocument();
            one.AddStroke(MakeCoordinateForTest(x0, y0, bw, bh, grid: true));
            byte[] v8 = MakeLegacyFile(one, 8, 4);
            var old = new InkDocument();
            bool oldOk = true;
            try { InkSerializer.LoadInto(old, v8); } catch (Exception ex) { oldOk = false; Console.WriteLine("    " + ex.Message); }
            Check("真·v8 老文件读得进，网格是关的（老文件没这个概念）",
                  oldOk && old.Strokes.Count == 1 && !old.Strokes[0].Grid
                  && old.Strokes[0].Points.Count == 3,
                  oldOk ? $"{old.Strokes.Count} 条，网格 {old.Strokes[0].Grid}" : "读取抛异常");

            // 真·v23 老文件（**没有格距这一位**）：把 v24 追加的那 4 个字节（一个 float）砍掉。
            // 期望 = 格距读成 **0 = 自动**，也就是加这一位之前的行为 → **不用迁移**。
            var doc23 = new InkDocument();
            var g23 = MakeCoordinateForTest(x0, y0, bw, bh, grid: true);
            g23.AxisGridStep = 88f;                 // 先塞一个值：砍掉之后必须读不到它
            doc23.AddStroke(g23);
            byte[] v23blob = MakeLegacyFile(doc23, 23, 4);
            var old23 = new InkDocument();
            bool ok23 = true;
            try { InkSerializer.LoadInto(old23, v23blob); }
            catch (Exception ex) { ok23 = false; Console.WriteLine("    " + ex.Message); }
            Check("真·v23 老文件读得进：格距 = 0（自动）——加这一位之前的行为，不用迁移",
                  ok23 && old23.Strokes.Count == 1 && old23.Strokes[0].Grid
                  && Near(old23.Strokes[0].AxisGridStep, 0f, 0.001f)
                  && old23.Strokes[0].Points.Count == 3,
                  ok23 ? $"{old23.Strokes.Count} 条，格距 {old23.Strokes[0].AxisGridStep:F1}"
                       + $"、网格 {old23.Strokes[0].Grid}"
                       : "读取抛异常");
        }

        Console.WriteLine();
        Console.WriteLine($"  合计 {pass + fail} 项：通过 {pass}，失败 {fail}");
        Console.WriteLine();
        _quit = true;
    }

    /// <summary>
    /// 自检用：造一个**真·老版本**存档。
    ///
    /// 原理：从 v8 起，每抬一版基本就是"每条笔画末尾多 1 个字节"（v8 线型 / v9 网格 /
    /// v10 压感 / v12 渐近线），所以"砍掉那几位 + 把版本号改回去"得到的就是货真价实的老文件。
    ///
    /// **为什么按"砍几位"传参、不写死**：2026-09-20 加 v10 时，三处"砍 1 字节"的自检
    /// 一起静默失效——它们各留了一两个字节的尾巴，而读端不检查"流有没有读完"，
    /// 于是照样通过、却不再是在验老文件（这正是仓库里那条教训：
    /// "自检里写死常量会随功能移位而静默失效"）。
    ///
    /// **但 v13 破了"版本号之差 = 砍几位"这条公式**：它只改了抛物线第二个点的含义、
    /// 没加字段。所以砍几位改成**显式传**（见下面 <paramref name="droppedBytes"/>），
    /// 不能让调用方去猜。
    /// </summary>
    /// <summary>
    /// 自检用：把当前格式的存档"退化"成某个老版本的文件。
    ///
    /// <paramref name="droppedBytes"/> = **从这个老版本到现在，每条笔画后面一共追加了几位**
    /// ——**它不等于版本号之差**：v13 只改了抛物线第二个点的**含义**、没加字段，
    /// 所以"v12 的文件"和"v13 的文件"**字节数一模一样**，要传 0。
    /// （v12 则比 v13 少一位：少了渐近线那一个字节。）
    /// </summary>
    private static byte[] MakeLegacyFile(InkDocument doc, int version, int droppedBytes)
    {
        byte[] cur = InkSerializer.Save(doc);
        byte[] old = droppedBytes > 0 ? new byte[cur.Length - droppedBytes] : cur;
        if (droppedBytes > 0) Array.Copy(cur, old, old.Length);
        // 魔数（8 字节）后面那个小端 int32 就是版本号。
        old[4] = (byte)version; old[5] = 0; old[6] = 0; old[7] = 0;
        return old;
    }

    /// <summary>
    /// 自检用：造一个坐标系（不经过工具，直接摆点）。
    /// 三个定义点 = 外框两角 + 原点，和 <see cref="Stroke.SetAxisBox"/> 的规则一致。
    ///
    /// 参数就是 <c>SetAxisBox</c> 的那四个：**(x, y) = 原点**、**(x+w, y+h) = 往右下拖了多远**
    /// （外框 = 原点 ± (w, h)）。所以外框的左上角在 (x−w, y−h)——传参时留神别让它跑出屏幕。
    /// </summary>
    private Stroke MakeCoordinateForTest(float x, float y, float w, float h, bool grid)
    {
        var s = new Stroke
        {
            Tool = Tool.Coordinate,
            Kind = StrokeKind.Coordinate,
            Color = new Color4(1f, 0f, 1f, 1f),        // 品红：便于在屏幕上数像素
            Width = 6f * DpiScale,
            Grid = grid,
        };
        // 先铺够三个点（SetAxisBox 要求控制点已经够数），再按外框算。
        for (int i = 0; i < 3; i++) s.AddPoint(x, y, 1f, NowMs);
        s.SetAxisBox(x, y, x + w, y + h);
        return s;
    }

    /// <summary>自检用：造一个数轴（两个定义点 = 左端 / 右端，y 相同）。</summary>
    private Stroke MakeNumberLineForTest(float x, float y, float len)
    {
        var s = new Stroke
        {
            Tool = Tool.NumberLine,
            Kind = StrokeKind.NumberLine,
            Color = new Color4(1f, 0f, 1f, 1f),
            Width = 6f * DpiScale,
        };
        for (int i = 0; i < 2; i++) s.AddPoint(x, y, 1f, NowMs);
        s.SetAxisBox(x, y, x + len, y);
        return s;
    }

    /// <summary>
    /// 出图：坐标系（带网格 / 不带网格各一个）＋ 数轴 ＋ 一条虚线。
    /// 用法 `--axisshow [路径]`，默认 `reports/坐标系与数轴.bmp`。
    /// 自检盯的是"数值对不对"，这一张是给**眼睛**看的：箭头大不大、网格疏密、
    /// 虚线在粗笔上是不是像样——这些量没有一条能写成判据。
    /// </summary>
    private void AxisShowcase(string path)
    {
        Console.WriteLine($"=== 出图：{path} ===");
        BoardOn = true;                          // 白底：不然桌面背景会混进画面
        Doc.Clear();
        Doc.ClearHistory();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }

        var ink = new Color4(0.11f, 0.12f, 0.15f, 1f);      // 板书的近黑色
        float x0 = _virtualX + 460f, y0 = _virtualY + 400f;
        // 外框（两张坐标系共用）：x0..x0+760 × y0..y0+620，所以半宽半高 = (380, 310)。
        // **画法改成了"按下 = 原点、拖出去 = 展开"**（见 Stroke.SetAxisBox），
        // 所以这里的第一参数是原点、第二参数是"往右下拖多远"，不再是外框的两个角。
        const float hw = 380f, hh = 310f;

        // ① 坐标系 · 带网格，原点摊在框的左下（老师最常用的"只留第一象限"）
        var g = new Stroke
        {
            Tool = Tool.Coordinate, Kind = StrokeKind.Coordinate,
            Color = ink, Width = 4f * DpiScale, Grid = true,
        };
        for (int i = 0; i < 3; i++) g.AddPoint(x0 + 130f, y0 + 470f, 1f, 0);
        g.SetAxisBox(x0 + 130f, y0 + 470f, x0 + 130f + hw, y0 + 470f + hh);
        Doc.AddStroke(g);

        // ② 坐标系 · 不带网格，原点在框正中间（和左边对照）
        var c = new Stroke
        {
            Tool = Tool.Coordinate, Kind = StrokeKind.Coordinate,
            Color = ink, Width = 4f * DpiScale, Grid = false,
        };
        for (int i = 0; i < 3; i++) c.AddPoint(x0 + 900f + hw, y0 + hh, 1f, 0);
        c.SetAxisBox(x0 + 900f + hw, y0 + hh, x0 + 900f + hw + hw, y0 + hh + hh);
        Doc.AddStroke(c);

        // ③ 数轴：一条水平线 + 右端箭头（没有刻度）
        var n = new Stroke
        {
            Tool = Tool.NumberLine, Kind = StrokeKind.NumberLine,
            Color = ink, Width = 4f * DpiScale,
        };
        for (int i = 0; i < 2; i++) n.AddPoint(x0, y0 + 760f, 1f, 0);
        n.SetAxisBox(x0, y0 + 760f, x0 + 1660f, y0 + 760f);
        Doc.AddStroke(n);

        // ④ 一条虚线直线（顺带把线型也看进去：虚线在粗笔上是不是像样）
        var d = new Stroke
        {
            Tool = Tool.Line, Kind = StrokeKind.Line,
            Color = ink, Width = 7f * DpiScale, Dash = StrokeDash.Dashed,
        };
        d.AddPoint(x0, y0 + 960f, 1f, 0);
        d.AddPoint(x0 + 1660f, y0 + 960f, 1f, 0);
        Doc.AddStroke(d);

        Doc.InvalidateAll();
        SettleFrames(800);

        bool ok = ScreenProbe.SaveBmp(path, (int)(x0 - 60f), (int)(y0 - 60f), 1900, 1150);
        Console.WriteLine(ok ? $"  已保存 {path}" : "  保存失败");
        Console.WriteLine();
        _quit = true;
    }

    /// <summary>
    /// 出图：函数曲线各来一份——**抛物线四种开口、双曲线两个方向、正弦 / 余弦各一个周期、
    /// 波浪线三个周期、正切一支**。
    /// 用法 `--curveshow [路径]`，默认 `reports/四种曲线.bmp`。
    ///
    /// 自检盯的是"数值对不对"，这一张是给**眼睛**看的（这条教训见 计划-图形工具.md 10.7）：
    ///   · 曲线胖不胖、够不够顺（段数按尺寸定，太少了看着是折线）；
    ///   · 双曲线**截断到哪**（`Stroke.HyperbolaTMaxOf`：出框就停笔、最多画到 `2a`：
    ///     太短看着像两根短线、太长就把包围盒撑得很大）；
    ///   · 四种开口是不是真的四个方向（左右开口是"换自变量"，最容易写反）；
    ///   · 正弦 / 余弦的**起点**对不对（正弦从轴起、余弦从峰起），而且**都是一个周期**；
    ///   · **波浪线**是不是"很多个周期"（和正弦那一张摆在一起看，一眼就该分得开）；
    ///   · 正切**两侧的渐近线**在不在、曲线有没有贴着它上去（这条靠 `TangentMinAspect` 兜着，
    ///     所以这一张**故意只拖 60 高**：画出来仍该是贴着渐近线的那一支）。
    /// 摆放：4 列 × 3 行，第一行四种开口、第二行"双曲线两个方向 ＋ 正弦 / 余弦 / 波浪线 / 正切"、
    /// 第三行四种立体。第二行挤了 6 个图形，所以位置是按"不碰上邻居"逐个摆的（见各段注释）。
    /// </summary>
    /// <summary>
    /// 出图（`--smoothshow [路径]`）：**曲线化开/关的对照**（2026-09-28）。
    ///
    /// 同一组"手写样本"画两遍——先按现在的折线出 `-off`，再把曲线化打开、整层重画出 `-on`：
    ///   ① 快弧：采样故意稀（模拟"关掉 Windows Ink 的笔 / 鼠标"）；
    ///   ② 直角：必须原样保留（用户唯一的硬约束）；
    ///   ③ 抛物线：手画曲线不许被改形（上次砍"保形平滑"就是因为这个）；
    ///   ④ 锯齿：连续尖角，一个都不许被磨圆。
    /// 好不好看只能靠眼睛，所以单开一条出图命令（判据交给下一轮真人对比）。
    /// </summary>
    private void SmoothShowcase(string path)
    {
        Console.WriteLine($"=== 出图：曲线化对照（{path}）===");
        BoardOn = true;                          // 白底：不然桌面背景会混进画面
        Doc.Clear();
        Doc.ClearHistory();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }

        var ink = new Color4(0.11f, 0.12f, 0.15f, 1f);
        var dotInk = new Color4(0.62f, 0.66f, 0.72f, 1f);   // 采样点的小灰点
        float penW = 6f * DpiScale;
        float ox = _virtualX + 120f, oy = _virtualY + 160f;

        void Add(IEnumerable<Vector2> pts, float dx, float dy, bool dots = true)
        {
            var list = new List<Vector2>();
            foreach (var p in pts) list.Add(new Vector2(p.X + dx, p.Y + dy));

            var s = new Stroke { Tool = Tool.Pen, Kind = StrokeKind.Freehand, Color = ink, Width = penW };
            foreach (var p in list) s.AddPoint(p.X, p.Y, 0.5f, 0);
            Doc.AddStroke(s);

            if (!dots) return;
            // 每个采样点打一个小灰点：曲线过不过点、直角动没动，看这个最直观
            foreach (var p in list)
            {
                var d = new Stroke
                {
                    Tool = Tool.Pen, Kind = StrokeKind.Freehand, Color = dotInk, Width = 2.4f * DpiScale,
                };
                d.AddPoint(p.X, p.Y, 0.5f, 0);
                Doc.AddStroke(d);
            }
        }

        // ① 快弧：中心 (ox+300, oy+280)、半径 280、每 13° 一个点（≈65px 一段，折角肉眼可见）
        var arc = new List<Vector2>();
        for (int i = 0; i <= 14; i++)
        {
            float a = MathF.PI * i / 14f;
            arc.Add(new Vector2(MathF.Cos(a) * 280f, -MathF.Sin(a) * 280f));
        }
        Add(arc, ox + 300f, oy + 280f);

        // ② 直角：两条臂各 6 个点（步长 56）
        var corner = new List<Vector2>();
        for (int i = 0; i <= 6; i++) corner.Add(new Vector2(i * 56f, 0f));
        for (int i = 1; i <= 6; i++) corner.Add(new Vector2(336f, i * 56f));
        Add(corner, ox + 760f, oy + 100f);

        // ③ 抛物线：y = x²/500，x ∈ [−260, 260]（手画曲线不许被改形）
        var parab = new List<Vector2>();
        for (int i = 0; i <= 13; i++)
        {
            float x = -260f + i * 40f;
            parab.Add(new Vector2(x, x * x / 500f));
        }
        Add(parab, ox + 1400f, oy + 120f);

        // ④ 锯齿：周期 2 的连续尖角（每个峰谷都必须留住）
        var zig = new List<Vector2>();
        for (int i = 0; i <= 12; i++) zig.Add(new Vector2(i * 55f, (i % 2 == 0) ? 0f : 110f));
        Add(zig, ox + 1860f, oy + 100f);

        // ⑤ 慢画直角：90° 摊在三小段上（每段只有 30°，比角点阈值小）——只有窗口判据兜得住
        var slow = new List<Vector2> { new(0f, 0f), new(120f, 0f) };
        for (int k = 1; k <= 3; k++)
        {
            var d = new Vector2(MathF.Cos(k * MathF.PI / 6f), MathF.Sin(k * MathF.PI / 6f));
            slow.Add(slow[^1] + d * 120f);
        }
        Add(slow, ox + 760f, oy + 520f);

        // ⑥ 密采样弧：**和真笔（Windows Ink 开）一个量级**（每 1° 一个点 ≈ 4.9px 一段）。
        // 它回答的是"拿手写板试为什么看不出区别"：点密到一定程度，折线和曲线就是同一根线
        //（弦长 c、半径 R 时中点偏差 ≈ c²/8R，c=5、R=280 → 0.011px，比一个像素小两个数量级）。
        var dense = new List<Vector2>();
        for (int i = 0; i <= 180; i++)
        {
            float a = MathF.PI * i / 180f;
            dense.Add(new Vector2(MathF.Cos(a) * 280f, -MathF.Sin(a) * 280f));
        }
        Add(dense, ox + 1560f, oy + 700f, dots: false);

        string dir = Path.GetDirectoryName(Path.GetFullPath(path));
        string name = Path.GetFileNameWithoutExtension(path);
        string ext = Path.GetExtension(path);
        if (string.IsNullOrEmpty(ext)) ext = ".png";
        if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
        string off = Path.Combine(string.IsNullOrEmpty(dir) ? "." : dir, name + "-off" + ext);
        string on = Path.Combine(string.IsNullOrEmpty(dir) ? "." : dir, name + "-on" + ext);

        // 折线那张：先关掉开关，整层重画（版本号会顶掉每条笔的几何缓存）
        bool wasEnabled = StrokeSmoothing.Enabled;
        StrokeSmoothing.SetEnabled(false);
        Doc.InvalidateAll();
        SettleFrames(300);
        bool ok1 = ScreenProbe.SaveBmp(off, (int)_virtualX, (int)_virtualY, _virtualW, _virtualH);

        // 曲线那张：打开开关，同一批笔重画一遍
        StrokeSmoothing.SetEnabled(true);
        Doc.InvalidateAll();
        SettleFrames(300);
        bool ok2 = ScreenProbe.SaveBmp(on, (int)_virtualX, (int)_virtualY, _virtualW, _virtualH);
        StrokeSmoothing.SetEnabled(wasEnabled);     // 出完图恢复原状态，别把后面的路径带偏

        Console.WriteLine(ok1 ? $"  折线：{off}" : "  折线图保存失败");
        Console.WriteLine(ok2 ? $"  曲线：{on}" : "  曲线图保存失败");
        Console.WriteLine();
        _quit = true;
    }

    /// <summary>
    /// `--smoothflashtest [--off]`：**"画的时候一直在闪"的专项检测**（2026-09-28 用户实测）。
    ///
    /// 判据不是"看"，而是"**已经画过去的地方不许再变**"：
    ///   · 合成鼠标按住不放、一路画过去（路径固定：每步 8~24px、每步拐 ±25° 以内）；
    ///   · 笔尖跑过"检查点" 100px 之后，每帧拍一次检查点那一小块（30×30）；
    ///   · 那一块里的墨应该**冻住**了——它要是还在变，画面上就是残影 / 发闪。
    ///
    /// 对照组 `--off` 跑同一条路径的折线：折线一定冻得住，所以这条测试**自证有效**
    /// （不是"永远通过"的摆设）。它也是"曲线不改脏区假设"这句话的机器证明。
    /// </summary>
    private void SmoothFlashTest(bool smoothing, bool fast = false)
    {
        Console.WriteLine();
        Console.WriteLine($"=== 曲线化“画的时候闪不闪”专项检测（{(smoothing ? "曲线" : "折线对照")}）===");

        if (SkipIfNoSyntheticInput("曲线化闪不闪（需要合成鼠标移动光标）")) { _quit = true; return; }

        BoardOn = true;                     // 白底，判据干净
        bool wasEnabled = StrokeSmoothing.Enabled;
        StrokeSmoothing.SetEnabled(smoothing);
        Doc.Clear();
        Doc.ClearHistory();
        Tool = Tool.Pen;
        PassThrough = false;
        Doc.InvalidateAll();
        SettleFrames(400);

        // 固定路径（确定性）：一条整体往右、但不老实的抖动路径
        var rnd = new Random(20260928);
        var path = new List<Vector2>();
        float x = _virtualX + 300f, y = _virtualY + 700f;
        float ang = 0f;
        path.Add(new Vector2(x, y));
        for (int i = 0; i < 60; i++)
        {
            ang += (float)(rnd.NextDouble() * 2 - 1) * 25f * (MathF.PI / 180f);
            ang = Math.Clamp(ang, -0.6f, 0.6f);
            float step = fast ? 30f + (float)rnd.NextDouble() * 40f : 8f + (float)rnd.NextDouble() * 16f;
            x += MathF.Cos(ang) * step;
            y += MathF.Sin(ang) * step;
            path.Add(new Vector2(x, y));
        }

        // 整条路径所在的带：每次移动都在这里拍一张，和上一张比。
        // **离笔尖 60px 以外的像素不该变**——那里早就画过去了，变了就是残影 / 发闪。
        const int bandW = 1100, bandH = 320;
        int bx = (int)(_virtualX + 240f), by = (int)(_virtualY + 560f);

        SendMouse((int)path[0].X, (int)path[0].Y, 0);
        SettleFrames(200);
        SendMouse((int)path[0].X, (int)path[0].Y, Native.MOUSEEVENTF_LEFTDOWN);
        SettleFrames(80);

        byte[] prev = null;
        int samples = 0, far20 = 0, far60 = 0;
        float far20Dist = 0f, far60Dist = 0f;
        for (int i = 1; i < path.Count; i++)
        {
            SendMouse((int)path[i].X, (int)path[i].Y, 0);
            SettleFrames(fast ? 10 : 20);
            var cap = ScreenProbe.CaptureRegion(bx, by, bandW, bandH);
            if (cap == null) continue;
            if (prev != null)
            {
                // 两圈分别量：20px 以外（笔尖后面那一小段"回头看"）与 60px 以外（真正的残影）
                var d20 = DiffFarFromTip(prev, cap, bandW, bandH, bx, by, path[i].X, path[i].Y, 20f);
                var d60 = DiffFarFromTip(prev, cap, bandW, bandH, bx, by, path[i].X, path[i].Y, 60f);
                far20 = Math.Max(far20, d20.count);
                far60 = Math.Max(far60, d60.count);
                far20Dist = Math.Max(far20Dist, d20.maxDist);
                far60Dist = Math.Max(far60Dist, d60.maxDist);
            }
            prev = cap;
            samples++;
        }

        SendMouse((int)path[^1].X, (int)path[^1].Y, Native.MOUSEEVENTF_LEFTUP);
        SettleFrames(300);
        StrokeSmoothing.SetEnabled(wasEnabled);       // 恢复原状态，别把后面的路径带偏

        Console.WriteLine($"  画了 {samples} 步；带 {bandW}×{bandH} @ ({bx},{by})");
        Console.WriteLine($"  离笔尖 >20px 的变化：最多 {far20} 个像素（最远 {far20Dist:F0}px）");
        Console.WriteLine($"  离笔尖 >60px 的变化：最多 {far60} 个像素（最远 {far60Dist:F0}px）");
        bool ok = samples >= 8 && far60 <= 0.5f;
        Console.WriteLine(ok
            ? "  PASS: 已经画过去的地方是冻住的（离笔尖远处一个像素都没变）"
            : samples < 8
                ? "  FAIL: 没采到几步——测量无效（别当成通过）"
                : "  FAIL: 已经画过去的地方还在变——画面上就是残影 / 发闪");
        Console.WriteLine();
        _quit = true;
    }

    /// <summary>
    /// 两张同尺寸 BGRA 图的差异，只看**离笔尖 &gt; minDist 的那些像素**。
    /// 返回（这样的像素数、其中最远那个到笔尖的距离、它的屏幕坐标）。
    /// </summary>
    private static (int count, float maxDist, float x, float y) DiffFarFromTip(
        byte[] a, byte[] b, int w, int h, int ox, int oy, float tipX, float tipY, float minDist)
    {
        int count = 0;
        float maxDist = 0f, wx = 0f, wy = 0f;
        for (int j = 0; j < h; j++)
        {
            int row = j * w * 4;
            for (int i = 0; i < w; i++)
            {
                int o = row + i * 4;
                int d = Math.Abs(a[o] - b[o]) + Math.Abs(a[o + 1] - b[o + 1]) + Math.Abs(a[o + 2] - b[o + 2]);
                if (d <= 24) continue;
                float px = ox + i, py = oy + j;
                float dist = MathF.Sqrt((px - tipX) * (px - tipX) + (py - tipY) * (py - tipY));
                if (dist <= minDist) continue;      // 笔尖附近本来就是新墨，允许变
                count++;
                if (dist > maxDist) { maxDist = dist; wx = px; wy = py; }
            }
        }
        return (count, maxDist, wx, wy);
    }

    /// <summary>
    /// `--wetdrytest`：**湿墨（抬笔前）与干墨（抬笔后）接不接得上**（2026-09-28 定的第一条调查）。
    ///
    /// 背景：真笔/合成笔写字时，屏幕上那一笔是 **DWM 委托轨迹**画的；抬笔那一刻换成
    /// 我们自己画的 `ID2D1Ink`。两边只要**粗细**或**中心线**差一点，每一笔收尾就会
    /// "轻轻沉一下"——这正是"说不清但就是差一点"的头号嫌疑。
    ///
    /// 判据：按住不放的时候先拍一张（笔尖后 100~260px 那一段，肯定已经被轨迹画上），
    /// 抬笔、等轨迹收掉之后再拍同一块，逐列比**墨宽**和**中心线**。
    /// 先要求"湿墨那张真的有墨"，否则"没画出来"会被误判成"没有差别"。
    /// </summary>
    private void WetDryTest(bool live, double seconds)
    {
        Console.WriteLine();
        Console.WriteLine("=== 湿墨 / 干墨 交接测量（真笔）===");
        Console.WriteLine($"  委托墨迹轨迹: 可用={OverlayWindow.InkTrailAvailable}，启用={OverlayWindow.InkTrailEnabled}"
                          + $"（{OverlayWindow.InkTrailNote}）");

        if (!live)
        {
            Console.WriteLine();
            Console.WriteLine("  这条**只能拿真笔画**：合成笔不会被 DWM 画成湿墨（--wetinktest 实测如此），");
            Console.WriteLine("  拿合成笔量到的“湿墨”其实是我们自己画的那一笔，比出来必然一样（假绿）。");
            Console.WriteLine("  用法：拿手写笔在屏幕中间那条浅灰线之间画一条横线（压力从轻到重），然后松手：");
            Console.WriteLine("      InkTeach.exe --wetdrytest --live 20");
            Console.WriteLine();

            // 干跑校验：证明采集缓冲是复用的。第一版每次抓屏都 new 2MB（进 LOH），
            // 一次笔画能刷出 64 次 gen2 —— 那量的是工具自己，不是产品。这条要盯住。
            int tw = Math.Min(1400, _virtualW - 200), th = Math.Min(360, _virtualH - 200);
            var buf = new byte[tw * th * 4];
            long a0 = GC.GetAllocatedBytesForCurrentThread();
            int c0 = GC.CollectionCount(0), c2 = GC.CollectionCount(2);
            int shots = 0;
            for (int i = 0; i < 75; i++)
            {
                if (ScreenProbe.CaptureRegionInto(buf, _virtualX + 50, _virtualY + 50, tw, th)) shots++;
                SettleFrames(1);
            }
            long used = GC.GetAllocatedBytesForCurrentThread() - a0;
            Console.WriteLine($"  干跑校验：抓 {shots} 次（{tw}×{th}，**复用同一块缓冲**）工具自身分配 {used / 1024.0:F0} KB，"
                              + $"GC {GC.CollectionCount(0) - c0}/{GC.CollectionCount(2) - c2}"
                              + "——接近 0 才算工具干净");
            _quit = true; return;
        }
        if (!OverlayWindow.InkTrailEnabled || !OverlayWindow.InkTrailAvailable)
        {
            Console.WriteLine("  SKIP: 没有委托轨迹，这条测量没有意义——它比的就是"
                              + "“系统画的湿墨”与“我们画的干墨”");
            _quit = true; return;
        }

        BoardOn = true;
        Doc.Clear();
        Doc.ClearHistory();
        Tool = Tool.Pen;
        Doc.InvalidateAll();

        int bandW = Math.Min(1400, _virtualW - 200);
        int bandH = Math.Min(360, _virtualH - 200);
        int bandX = _virtualX + (_virtualW - bandW) / 2;
        int bandY = _virtualY + (_virtualH - bandH) / 2;
        float gy = bandY + bandH * 0.5f;

        // 浅灰引导线（**故意浅到进不了墨的判据**：白底判据是 RGB 之和 < 600，
        // 0.85 灰是 651，不会被当成墨）。两端加两个小竖标记，告诉用户画在哪儿。
        var guide = new Color4(0.85f, 0.86f, 0.88f, 1f);
        void Guide(float x1, float y1, float x2, float y2)
        {
            var s = new Stroke { Tool = Tool.Pen, Kind = StrokeKind.Freehand, Color = guide, Width = 2f * DpiScale };
            s.AddPoint(x1, y1, 0.5f, 0);
            s.AddPoint(x2, y2, 0.5f, 0);
            Doc.AddStroke(s);
        }
        Guide(bandX + 120f, gy, bandX + bandW - 120f, gy);
        Guide(bandX + 120f, gy - 40f, bandX + 120f, gy + 40f);
        Guide(bandX + bandW - 120f, gy - 40f, bandX + bandW - 120f, gy + 40f);
        SettleFrames(150);

        Console.WriteLine();
        Console.WriteLine($"  请在两条**竖标记之间**用笔从左画到右（压力从轻到重），{seconds:F0} 秒内、一笔画完。");
        Console.WriteLine("  松手后会自动出结果。");
        Console.WriteLine();

        byte[] wetBuf = new byte[bandW * bandH * 4];
        byte[] dryBuf = new byte[bandW * bandH * 4];
        bool gotWet = false;
        double wetAt = 0, lastCap = 0, t0 = NowMs;
        while (!_quit && NowMs - t0 < seconds * 1000)
        {
            DrainMessages();
            if (_dirty || _drawing) { if (OverlayWindow.VBlankPaced) Native.DwmFlush(); RenderAll(); _dirty = false; }
            else Native.MsgWaitForMultipleObjectsEx(0, IntPtr.Zero, 20, Native.QS_ALLINPUT, 0);
            NowMs = _clock.Elapsed.TotalMilliseconds;

            if (ActiveStroke != null)
            {
                // 笔还接触着：这一张就是**用户当下看到的湿墨**（委托轨迹 ∪ 我们自己画的那一笔）。
                // ⚠ 缓冲必须复用（`CaptureRegionInto`）：每帧 new 2MB 会进 LOH，
                //   实测能把一次笔画刷出 64 次 gen2 —— 那量的是测量工具自己。
                // 限到 ~25 次/秒：够拿到"松手前最后一帧"，又不给测量本身加负担。
                if (NowMs - lastCap >= 40 &&
                    ScreenProbe.CaptureRegionInto(wetBuf, bandX, bandY, bandW, bandH))
                {
                    gotWet = true;
                    wetAt = NowMs;
                    lastCap = NowMs;
                }
            }
            else if (gotWet && NowMs - wetAt > 300)
            {
                break;                              // 抬笔 300ms 了，轨迹该收掉了
            }
        }

        if (!gotWet)
        {
            Console.WriteLine("  FAIL: 整个过程没测到任何笔迹（笔接触时才会采样）");
            _quit = true; return;
        }
        SettleFrames(400);
        if (!ScreenProbe.CaptureRegionInto(dryBuf, bandX, bandY, bandW, bandH))
        {
            Console.WriteLine("  FAIL: 抓屏失败"); _quit = true; return;
        }
        ScreenProbe.SaveBuffer("reports/wetdry-wet.bmp", wetBuf, bandW, bandH);
        ScreenProbe.SaveBuffer("reports/wetdry-dry.bmp", dryBuf, bandW, bandH);

        var (widthW, centerW) = InkProfile(wetBuf, bandW, bandH);
        var (widthD, centerD) = InkProfile(dryBuf, bandW, bandH);
        int colsWet = 0, colsBoth = 0;
        var dw = new List<float>();
        var dc = new List<float>();
        float wMin = float.MaxValue, wMax = 0f, dMin = float.MaxValue, dMax = 0f;
        for (int i = 0; i < bandW; i++)
        {
            if (widthW[i] > 0) { colsWet++; wMin = MathF.Min(wMin, widthW[i]); wMax = MathF.Max(wMax, widthW[i]); }
            if (widthD[i] > 0) { dMin = MathF.Min(dMin, widthD[i]); dMax = MathF.Max(dMax, widthD[i]); }
            if (widthW[i] > 0 && widthD[i] > 0)
            {
                colsBoth++;
                dw.Add(MathF.Abs(widthW[i] - widthD[i]));
                dc.Add(MathF.Abs(centerW[i] - centerD[i]));
            }
        }
        dw.Sort();
        dc.Sort();
        float Med(List<float> l) => l.Count == 0 ? -1f : l[l.Count / 2];
        float Max(List<float> l) => l.Count == 0 ? -1f : l[^1];

        Console.WriteLine($"  湿墨有墨的列：{colsWet}/{bandW}（湿墨线宽 {wMin:F0}~{wMax:F0}px）");
        Console.WriteLine($"  干墨有墨的列  线宽 {dMin:F0}~{dMax:F0}px；两边都有墨的列 {colsBoth}");
        Console.WriteLine($"  线宽差（湿 vs 干）：中位 {Med(dw):F1}px，最大 {Max(dw):F1}px");
        Console.WriteLine($"  中心线偏移        ：中位 {Med(dc):F1}px，最大 {Max(dc):F1}px");

        // 沿笔迹方向的最佳对齐位移：把干墨的宽度序列相对湿墨平移 k，取"平均差最小"的那个 k。
        // ⚠ 别用"最急变化处"那种 argmax 判据——两个几乎一样的曲线，最高峰差 2px 就会翻到别处
        //   （2026-09-28 实测：中位差 0.0px 的一条笔，它报出"差 +361px"，纯属噪声）。
        int bestShift = 0;
        float bestErr = float.MaxValue;
        for (int k = -40; k <= 40; k++)
        {
            float sum = 0f;
            int cnt = 0;
            for (int i = 0; i < bandW; i++)
            {
                int j = i + k;
                if (j < 0 || j >= bandW) continue;
                if (widthW[i] <= 0 || widthD[j] <= 0) continue;
                sum += MathF.Abs(widthW[i] - widthD[j]);
                cnt++;
            }
            if (cnt < bandW / 3) continue;
            float err = sum / cnt;
            if (err < bestErr) { bestErr = err; bestShift = k; }
        }
        Console.WriteLine($"  沿笔迹方向的最佳对齐位移：{bestShift:+0;-0;0}px"
                          + $"（对齐后平均线宽差 {bestErr:F2}px）"
                          + (Math.Abs(bestShift) <= 2 ? "——没有滞后" : "——两边在笔迹方向上错开了"));
        Console.WriteLine("  出图：reports/wetdry-wet.bmp / wetdry-dry.bmp（人眼对照）");

        bool ok = colsBoth > bandW / 4 && colsWet > bandW / 4
                  && Med(dw) <= 2.5f && Med(dc) <= 1.5f && Math.Abs(bestShift) <= 2;
        Console.WriteLine(ok
            ? $"  PASS: 湿墨和干墨接得上（线宽差中位 {Med(dw):F1}px、中心线中位 {Med(dc):F1}px、"
              + $"对齐位移 {bestShift}px）"
            : colsWet <= bandW / 4
                ? "  FAIL: 湿墨那张几乎没有墨——轨迹没画出来，测量无效（别当成通过）"
                : $"  FAIL: 抬笔前后对不上（线宽差中位 {Med(dw):F1}px、对齐位移 {bestShift}px）——收笔会“沉一下”");
        Console.WriteLine();
        _quit = true;
    }

    /// <summary>
    /// 一块 BGRA 图里，**逐列**的墨宽与中心线（白底判据：不是白就算墨）。
    /// 返回的两个数组长度 = 图宽；某一列没有墨时该列 = -1。
    /// </summary>
    private static (float[] width, float[] center) InkProfile(byte[] bgra, int w, int h)
    {
        var width = new float[w];
        var center = new float[w];
        for (int i = 0; i < w; i++)
        {
            int min = int.MaxValue, max = -1;
            for (int j = 0; j < h; j++)
            {
                int o = (j * w + i) * 4;
                if (bgra[o] + bgra[o + 1] + bgra[o + 2] < 600)
                {
                    if (j < min) min = j;
                    if (j > max) max = j;
                }
            }
            width[i] = max >= 0 ? max - min + 1 : -1f;
            center[i] = max >= 0 ? (min + max) * 0.5f : -1f;
        }
        return (width, center);
    }

    /// <summary>
    /// `--tailjumptest`：**预测尾"突突突往外跳"的专项检测**（2026-09-28 用户实测：
    /// "鼠标模式下手写板写字，末端总会突突突往外跳，Ink 开了就没有了"）。
    ///
    /// 症状的机理：鼠标模式下没有委托轨迹，预测尾由我们自己画；而鼠标/兼容模式的输入
    /// 是**突发**的（报几个点、停一下、再报几个点）。来一阵好数据 → 末速度算得大 →
    /// 尾巴甩到前面；间隔一超 `MaxGapMs`(20ms) → 速度清零 → 尾巴没了；再来数据又甩出来。
    ///
    /// 判据是**笔尖的逐帧轨迹**（品红墨的最右列）：
    ///   · `往前跳的最大幅度`：一帧里笔尖突然前进多少；
    ///   · `往后退的次数 / 最大后退`：尾巴消失时笔尖会**缩回去**——这就是"突突"的正身。
    /// 对照组 `--nopredict` 应当明显更稳（这就是这条测试的自证）。
    /// ⚠ 2026-09-29 起预测**默认关**（用户拍板），所以这条测试要显式 `--predict` 才有对照。
    /// </summary>
    private void TailJumpTest(bool noisy = false, bool predictOff = false)
    {
        Console.WriteLine();
        Console.WriteLine("=== 预测尾“突突跳”检测（合成鼠标，突发节奏）===");
        // 测试自己摆状态（不依赖启动默认值）：默认测"开预测"，`--off` 测对照
        PredictEnabled = !predictOff;
        Console.WriteLine($"  预测={(PredictEnabled ? "开" : "关（对照）")}；节奏={(noisy ? "忽大忽小 + 间隔不齐（像真鼠标）" : "固定步长 + 每 4 点一停")}");

        if (SkipIfNoSyntheticInput("预测尾跳跃检测（需要合成鼠标）")) { _quit = true; return; }

        BoardOn = true;
        Doc.Clear();
        Doc.ClearHistory();
        Tool = Tool.Pen;
        PassThrough = false;
        SetColorFromUi(new Color4(1f, 0f, 1f, 1f));      // 品红：和光标/白底分得开
        Doc.InvalidateAll();
        SettleFrames(200);

        float y0 = _virtualY + _virtualH * 0.5f;
        float x0 = _virtualX + 400f;
        const int N = 90;

        // 先把这一步的"步长 + 间隔"定下来（确定性）：忽大忽小的步长是**鼠标加速**的样子，
        // 不齐的间隔是**报点节奏**的样子，两者一起才逼得出"尾巴一出一进"。
        var rnd = new Random(20260928);
        var steps = new float[N];
        var gaps = new int[N];
        float total = 0f;
        for (int i = 0; i < N; i++)
        {
            steps[i] = noisy ? 2f + (float)rnd.NextDouble() * 32f : 14f;
            gaps[i] = noisy ? 6 + rnd.Next(36) : (i % 4 == 3 ? 60 : 8);
            total += steps[i];
        }

        int bandW = (int)(total + 220f), bandH = 120;
        int bandX = (int)(x0 - 60f), bandY = (int)(y0 - bandH * 0.5f);
        var buf = new byte[bandW * bandH * 4];

        SendMouse((int)x0, (int)y0, 0);
        SettleFrames(120);
        SendMouse((int)x0, (int)y0, Native.MOUSEEVENTF_LEFTDOWN);
        SettleFrames(60);

        var tip = new List<(double t, float x)>();
        int sent = 0;
        float cx = x0;
        double nextMove = NowMs;
        while (!_quit && sent < N)
        {
            if (NowMs >= nextMove)
            {
                cx += steps[sent];
                sent++;
                SendMouse((int)cx, (int)y0, 0);
                nextMove = NowMs + gaps[sent - 1];
            }
            SettleFrames(16);                    // 一次采样 = 一帧
            if (ScreenProbe.CaptureRegionInto(buf, bandX, bandY, bandW, bandH))
            {
                int col = MaxInkColumn(buf, bandW, bandH, minRun: 5);
                tip.Add((NowMs, col >= 0 ? bandX + col : float.NaN));
            }
        }
        SendMouse((int)cx, (int)y0, Native.MOUSEEVENTF_LEFTUP);
        SettleFrames(200);

        float maxFwd = 0f, maxBack = 0f;
        int backCount = 0, measured = 0;
        for (int i = 1; i < tip.Count; i++)
        {
            if (float.IsNaN(tip[i].x) || float.IsNaN(tip[i - 1].x)) continue;
            float d = tip[i].x - tip[i - 1].x;
            measured++;
            if (d > maxFwd) maxFwd = d;
            if (d < 0f) { backCount++; if (-d > maxBack) maxBack = -d; }
        }
        float lastSent = cx;
        float lastTip = 0f;
        for (int i = tip.Count - 1; i >= 0; i--) if (!float.IsNaN(tip[i].x)) { lastTip = tip[i].x; break; }

        Console.WriteLine($"  采到 {tip.Count} 帧（有效 {measured} 对），画到 x={lastSent:F0}，"
                          + $"最后笔尖 x={lastTip:F0}（落后 {lastSent - lastTip:F0}px）");
        Console.WriteLine($"  往前跳：最大 {maxFwd:F0}px/帧");
        Console.WriteLine($"  往后退：{backCount} 次，最大 {maxBack:F0}px  ← “突突”的正身");
        bool ok = backCount <= 2 && maxFwd <= 30f;
        Console.WriteLine(ok
            ? "  PASS: 笔尖轨迹是稳的（没有反复回缩）"
            : $"  FAIL: 笔尖在往回缩（{backCount} 次）——尾巴在一出一进地弹");
        Console.WriteLine();
        _quit = true;
    }

    /// <summary>
    /// 一块 BGRA 图里**最右边**那一列"够粗的品红墨"（≥ <paramref name="minRun"/> 个连续像素）。
    /// 要求"够粗"是为了把落点光标环排除掉（那是细线，竖着切只有两三个像素）。
    /// </summary>
    private static int MaxInkColumn(byte[] bgra, int w, int h, int minRun)
    {
        for (int i = w - 1; i >= 0; i--)
        {
            int run = 0;
            for (int j = 0; j < h; j++)
            {
                int o = (j * w + i) * 4;
                bool magenta = bgra[o] > 200 && bgra[o + 1] < 90 && bgra[o + 2] > 200;
                if (magenta) { if (++run >= minRun) return i; }
                else run = 0;
            }
        }
        return -1;
    }

    private void CurveShowcase(string path)
    {
        Console.WriteLine($"=== 出图：{path} ===");
        BoardOn = true;                          // 白底：不然桌面背景会混进画面
        Doc.Clear();
        Doc.ClearHistory();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }

        var ink = new Color4(0.11f, 0.12f, 0.15f, 1f);      // 板书的近黑色
        float x0 = _virtualX + 200f, y0 = _virtualY + 180f;
        const float pitch = 620f;                            // 格子间距（横竖一样，看着是网格）

        // 造一条曲线：只有 BeginShapeAt 铺的那一个占位点，之后交给 Set*Box
        Stroke Make(Tool tool, StrokeKind kind, float x, float y)
        {
            var s = new Stroke
            {
                Tool = tool, Kind = kind, Color = ink, Width = 5f * DpiScale,
            };
            s.AddPoint(x, y, 1f, 0);
            return s;
        }
        // 每格的左上角
        float CellX(int col) => x0 + col * pitch;
        float CellY(int row) => y0 + row * pitch;

        // ---- 第一行：抛物线的四种开口（**先选朝向，再用"顶点 + 经过点"两点画**） ----
        // 这就是用户 2026-09-20 定的口径：方向是"选"出来的（CurveAxis），大小由"经过那个点"反解。
        var dirs = new[] { CurveAxis.OpenUp, CurveAxis.OpenDown, CurveAxis.OpenRight, CurveAxis.OpenLeft };
        for (int col = 0; col < dirs.Length; col++)
        {
            float cx = CellX(col), cy = CellY(0);
            var v = new Vector2(cx + 280f, cy + 280f);
            var s = Make(Tool.Parabola, StrokeKind.Parabola, v.X, v.Y);
            s.CurveAxis = dirs[col];                              // ① 先选开口方向
            s.SetParabolaVertex(v.X, v.Y);                        // ② 定顶点
            // ③ 定"曲线经过的点"：取 `u = 1` 处的曲线点（`s = p/2、t = p`），
            //    反解出来正好是 p = 140（见 Stroke.ParabolaPThroughPoint），一个格子装得下。
            var (dir, perp) = Stroke.ParabolaBasis(dirs[col]);
            var q = v + perp * 140f + dir * 70f;
            s.SetParabolaThroughPoint(q.X, q.Y);
            Doc.AddStroke(s);
        }

        // ---- 第二行：双曲线两个方向 ＋ 正弦 / 余弦各一个周期 ----
        // 双曲线按真实的**两步**出图（第一步拖出**渐近线框**、第二步定"曲线过哪个点"），
        // 这样图上这两条跟老师真画出来的完全一致（朝向也是那一步定的）。
        // 渐近线框是**拖到哪就是哪**：`A = |dx|、B = |dy|`（2026-09-20 改成不再打对折）。
        var hX = Make(Tool.Hyperbola, StrokeKind.Hyperbola, CellX(0) + 280f, CellY(1) + 280f);
        hX.SetHyperbolaFromAsymptote(CellX(0) + 280f, CellY(1) + 280f,
                                     CellX(0) + 280f + 300f, CellY(1) + 280f + 120f, 8f);   // 斜率 0.4
        hX.SetHyperbolaThroughPoint(CellX(0) + 280f + 300f, CellY(1) + 280f + 104f);
        Doc.AddStroke(hX);          // 点更横 → 焦点在 x 轴（左右双曲线）

        var hY = Make(Tool.Hyperbola, StrokeKind.Hyperbola, CellX(1) + 280f, CellY(1) + 280f);
        hY.SetHyperbolaFromAsymptote(CellX(1) + 280f, CellY(1) + 280f,
                                     CellX(1) + 280f + 120f, CellY(1) + 280f + 300f, 8f);   // 斜率 2.5
        hY.SetHyperbolaThroughPoint(CellX(1) + 280f + 104f, CellY(1) + 280f + 300f);
        Doc.AddStroke(hY);          // 点更竖 → 焦点在 y 轴（上下双曲线）

        // 正弦：起点在轴上（第一个零点），**往上拖 = 先上后下**（就是课本的 y = sin x）。
        // ⚠ 2026-09-20 第十六批：**框宽就是一个周期**（用户："正弦和余弦用一个周期的图"）——
        // 所以这一张拖出来的是**一个周期**（300 宽、A = 75）。多周期那件事在下一格「波浪线」。
        // ⚠ 这一行的**纵向位置都写成 `CellY(1) + 本行内偏移`**：格子间距是 620，
        // 第三行（立体）从 `CellY(1) + 600` 就开始了 —— 偏移超过 600 就压在立体上了
        //（2026-09-20 第十六批把波浪线摆到 +760、当场压住圆台和球，出图才发现）。
        float sinX = x0 + 1250f;
        var sin = Make(Tool.Sine, StrokeKind.Sine, sinX, CellY(1) + 300f);
        sin.SetWaveBox(sinX, CellY(1) + 300f, sinX + 300f, CellY(1) + 225f, 8f);   // dy = −75 → A = 75
        Doc.AddStroke(sin);

        // 余弦：起点在**峰顶**，**往下拖 = 从峰顶往下**（就是课本的 y = cos x）。
        // 同样是**一个周期**（纵拖 = 峰 → 谷 = 2A，所以同样 75 的振幅要拖 150 高）。
        float cosX = x0 + 1600f;
        var cos = Make(Tool.Cosine, StrokeKind.Cosine, cosX, CellY(1) + 225f);
        cos.SetWaveBox(cosX, CellY(1) + 225f, cosX + 300f, CellY(1) + 375f, 8f);
        Doc.AddStroke(cos);

        // 波浪线（第十六批）：**多周期的正弦波**——横向拖的是"要画多长"、周期由振幅定
        //（`T = 1 × A`，用户定的"振幅 = 一个周期"）。这里 A = 70、画 210 宽 → **3 个整周期**，
        // 正是用户要的"很多个周期的波浪线"。
        // 摆在正弦 / 余弦下面一点（同一行里错开，三张并排看"一个周期 vs 多周期"最直观）。
        float wavX = x0 + 1950f;
        var wav = Make(Tool.Wave, StrokeKind.Wave, wavX, CellY(1) + 400f);
        wav.SetWaveBox(wavX, CellY(1) + 400f, wavX + 210f, CellY(1) + 330f, 8f);
        Doc.AddStroke(wav);

        // 正切（2026-09-20 第十五批）：**一支**，按下 = 原点、拖出以它为中心的框
        //（横向 = 半支长、纵向 = 可视半高，两条渐近线就落在框的左右两边）。
        // ⚠ 视觉半高有**下限比例 3:1**（见 Stroke.TangentMinAspect）：这里故意只拖 60 高，
        // 画出来会被顶到 240 —— 图上要看的正是"随手一拖就贴着渐近线"这件事。
        float tanX = x0 + 2560f, tanY = CellY(1) + 330f;
        var tan = Make(Tool.Tangent, StrokeKind.Tangent, tanX, tanY);
        tan.SetTangentBox(tanX, tanY, tanX + 80f, tanY + 60f, 8f);
        Doc.AddStroke(tan);

        // ---- 第三行：立体图形（2026-09-20 第五批，照 InkClass 的 case 6/7）----
        // **旋转体那一族**：一次拖出**外接矩形**就成（椭圆由矩形派生，
        // 扁率 = `Stroke.SolidEllipseRatio`），被挡住的那半圈是**细虚线**（辅助几何槽）。
        // 位置贴着第三行的格线上沿：再往上抬就会和第二行（双曲线 / 正弦）叠在一起，
        // 再往下压出图（1800 高）就会被裁掉——两头都试过，这个位置刚好。
        //
        // ⚠ 这一行原来放的是**圆柱 / 圆锥 / 长方体 / 四面体**——后两个 2026-09-20 第十二批
        // 撤了面板入口（见 ShapeRows），所以这里换成**用户现在真能拖出来的四个**：
        // 圆柱 / 圆锥 / 圆台 / 球。（长方体 / 四面体的画法没删，`--curvetest` 里那些
        // 几何断言照旧在管着它们，旧板书也照样打开。）
        float sy0 = CellY(2) - 20f;
        var cyl = Make(Tool.Cylinder, StrokeKind.Cylinder, CellX(0) + 130f, sy0);
        cyl.SetSolidBox(CellX(0) + 130f, sy0, CellX(0) + 430f, sy0 + 350f);
        Doc.AddStroke(cyl);

        var cone = Make(Tool.Cone, StrokeKind.Cone, CellX(1) + 130f, sy0);
        cone.SetSolidBox(CellX(1) + 130f, sy0, CellX(1) + 430f, sy0 + 350f);
        Doc.AddStroke(cone);

        // 圆台（2026-09-20 第十三批）：同一个外接矩形，上底是一圈**小一圈**的椭圆。
        var cfz = Make(Tool.ConeFrustum, StrokeKind.ConeFrustum, CellX(2) + 130f, sy0);
        cfz.SetSolidBox(CellX(2) + 130f, sy0, CellX(2) + 430f, sy0 + 350f);
        Doc.AddStroke(cfz);

        // 球（第十四批）：半径 = min(半宽, 半高) 的内切正圆 ＋ 赤道椭圆（近侧实线）。
        // 这里**故意拖一个正方**（350×350）——球本来就该是个圆。
        var sph = Make(Tool.Sphere, StrokeKind.Sphere, CellX(3) + 130f, sy0);
        sph.SetSolidBox(CellX(3) + 130f, sy0, CellX(3) + 480f, sy0 + 350f);
        Doc.AddStroke(sph);

        Doc.InvalidateAll();
        SettleFrames(800);

        bool ok = ScreenProbe.SaveBmp(path, (int)_virtualX, (int)_virtualY, 2880, 1800);
        Console.WriteLine(ok ? $"  已保存 {path}" : "  保存失败");
        Console.WriteLine();
        _quit = true;
    }

    /// <summary>
    /// 出图（2026-09-22）：**双曲线两档 ＋ 椭圆（带焦点）两档**摆成一张四格的图。
    /// 用法 `--conicshow [路径]`，默认 `reports/圆锥曲线-两档.bmp`。
    ///
    /// 为什么单开一张、不塞进 `--curveshow`：那一张的三行已经满了（第二行末尾离立体
    /// 只有 600 像素），塞进去会叠在一起（第十六批就这么出过一次错）。而这一批要看的
    /// 正是"**两档之间的差别**"——四格并排、同一套尺寸，一眼就能对比：
    ///   上排：双曲线**有 / 无**渐近线；下排：椭圆**有焦点三角形 / 只有焦点**。
    /// 椭圆的 P 用**默认位置**（椭圆左上方那个点，见 `Stroke.DefaultFocusPointU`）——
    /// 图上要看的正是"顶点**在椭圆上**、三角形在上半边"，和面板图标同一个位置。
    /// </summary>
    private void ConicShowcase(string path)
    {
        Console.WriteLine($"=== 出图：{path} ===");
        BoardOn = true;                          // 白底：不然桌面背景会混进画面
        Doc.Clear();
        Doc.ClearHistory();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }

        var ink = new Color4(0.11f, 0.12f, 0.15f, 1f);      // 板书的近黑色
        const float colPitch = 1440f, rowPitch = 720f;
        float x0 = _virtualX + 720f, y0 = _virtualY + 300f;

        Stroke Make(Tool tool, StrokeKind kind, float x, float y)
        {
            var s = new Stroke
            {
                Tool = tool, Kind = kind, Color = ink, Width = 5f * DpiScale,
            };
            s.AddPoint(x, y, 1f, 0);
            return s;
        }

        // ---- 上排：双曲线两档（**同一个几何**，只差那两条虚线在不在）----
        // 画法按真实的两步来：第一步拖出**渐近线框**（+300, +120，斜率 0.4），
        // 第二步定"曲线经过哪个点"（更横 → 焦点在 x 轴）。
        for (int col = 0; col < 2; col++)
        {
            float cx = x0 + col * colPitch, cy = y0;
            var h = Make(Tool.Hyperbola, StrokeKind.Hyperbola, cx, cy);
            h.SetHyperbolaFromAsymptote(cx, cy, cx + 300f, cy + 120f, 8f);
            h.SetHyperbolaThroughPoint(cx + 300f, cy + 104f);
            h.ShowAsymptotes = col == 0;                 // 左：有渐近线；右：无渐近线
            Doc.AddStroke(h);
        }

        // ---- 下排：椭圆（带焦点）两档（**同一个椭圆**，只差那两条边在不在）----
        // 中心 ＋ 外角点拖 300 × 160 → 宽椭圆，焦点在横轴上、离中心 ±254。
        // 左：有焦点三角形（**P 用默认位置**，也就是"顶点在椭圆上"的那个样子）；
        // 右：只有两个焦点。
        // ⚠ P 的默认角是**左上方**（120°，见 `Stroke.DefaultFocusPointU`）——图上看的就是
        // "三角形的顶点贴着椭圆那条线、在上半边"，和面板图标上画的是同一个位置。
        for (int col = 0; col < 2; col++)
        {
            float cx = x0 + col * colPitch, cy = y0 + rowPitch;
            var e = Make(Tool.ConicEllipse, StrokeKind.ConicEllipse, cx, cy);
            // ⚠ **不要用 `SetShapeBox`**：那是"三角形 / 平行四边形"的外框写法（会写三个顶点），
            // 而椭圆的定义是"**中心 ＋ 外角点**"两个点 —— 用错的话画出来是个又细又高的怪东西
            //（第一版出图时就是这么翻的：a 和 b 全错了）。正确写法是"起手点当中心、再拖出外角点"。
            e.SetEnd(cx + 300f, cy + 160f);
            e.FocusTriangle = col == 0;
            Doc.AddStroke(e);
        }

        Doc.InvalidateAll();
        SettleFrames(800);

        bool ok = ScreenProbe.SaveBmp(path, (int)_virtualX, (int)_virtualY, 2880, 1800);
        Console.WriteLine(ok ? $"  已保存 {path}" : "  保存失败");
        Console.WriteLine();
        _quit = true;
    }

    /// <summary>
    /// 线型自检（2026-09-19）：实线 / 虚线 / 点线。
    ///
    /// 三层判据，缺哪一层都可能"看着绿其实没做"：
    ///   ① **屏幕层**：同一条水平线，三种线型在屏幕上数出来的墨量依次明显递减
    ///      （实线 ≈ 满、虚线 ≈ 六成、点线 ≈ 三成），**而包围盒一模一样**——
    ///      这一条专抓"字段存了但渲染没接上"（只看字段的话这一层会是绿的）。
    ///   ② **交互层**：改线型走的是面板那条真路（命中格子 → HandlePanelClick），
    ///      **图像不被改**（自由笔迹 2026-09-19 起**也改**——用户报的"选中以后虚线面板
    ///      还没有实现"就是它：引擎里 `Freehand` 那一行 `continue`），
    ///      改完包围盒一分不动，一步撤销能回到原样；
    ///   ②c **笔的线型开关**：色带条上切一档 → 新画出来的笔迹就是那一档，
    ///      而**已经画好的不被动**（"画之前选"和"画之后改"两条路各管各的）。
    ///   ③ **存档层**：写文件读回来线型还在；再造一个**真·v7 老文件**（见 MakeLegacyFile），
    ///      验"老文件读进来是实线"——这是版本闸写错时唯一会炸的地方。
    /// 最后导一张图，人能一眼看出三种样子。
    /// </summary>
    /// <summary>
    /// 四种曲线（抛物线 / 双曲线 / 正弦 / 余弦）自检。
    ///
    /// 盯的六件事：
    ///   ① **画法**：真机拖那一下，定义元素得落在该落的地方（顶点 / 中心 / 起点 = **按下的点**）；
    ///   ② **紧框**：必须等于"曲线自己的那个矩形 ＋ 半笔宽"，**不能是控制点的外接**——
    ///      双曲线会小掉一大圈、正弦会漏掉起点那一侧（椭圆当年就是这么翻的车）；
    ///   ③ **手柄**：精简之后抛物线 1 个、其余 2 个，而且每个手柄**只改一个量**；
    ///   ④ **朝向**：换一档几何真的换了、一步撤销回得去、四次一循环；
    ///   ⑤ **双曲线两支之间没有"幽灵线段"**（折线那份的抬笔约定，见 ShapeOutline）；
    ///   ⑥ **存档往返** ＋ **真 v10 老文件**读得进来（朝向位缺一位就是整体错位）。
    /// </summary>
    // =====================================================================
    //  棱柱自检（2026-09-20 第十一批，用户提的，见 计划-图形工具.md §32）
    // =====================================================================

    /// <summary>
    /// **棱柱 / 棱锥 / 棱台自检**：三兄弟的底面 / 棱 / 隐藏棱 ＋ 直/斜吸附 ＋ 档位 ＋ "长方体没被碰"。
    /// 用法：`--prismtest`
    ///
    /// 验六件事：
    ///   ① **底面是正 n 边形**：顶点数 = n，而且**参数角均匀**——不是"边长相等"：
    ///      底面是"俯视压扁"画的，边长方差被压过，只有参数角才是那个不变量；
    ///   ② **棱柱的三族边各 n 条**（顶面 / 底面 / 侧棱 = 3n），其中侧棱那 n 条的向量
    ///      就是"侧棱向量"（逐条对得上）；
    ///   ③ **隐藏棱条数** = §32.4 那条通用判据算出来的定值（见下面的小表）；
    ///   ④ **棱锥 / 棱台**只换"顶面怎么来"：棱锥顶面退化成一个点（棱只有 2n 条）、
    ///      棱台的上底按下底同形缩一个固定比例（棱仍是 3n 条），
    ///      被挡住的条数与棱柱**同一张表**（判据是同一条）；
    ///   ⑤ **真机直 / 斜**：往上拖偏一点点 → 吸住（胶囊「直棱柱 / 直棱锥 / 直棱台」）
    ///      且顶上那个中心严格在底心正上方；拖歪 → 不吸、方向就是那一拖的方向；
    ///   ⑥ **档位**：3→4→5→6→3、四张图标两两不同、**三格共用同一档**；**长方体一个字没动**。
    /// </summary>
    private void PrismTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 棱柱自检（3/4/5/6 棱柱 ＋ 直/斜）===");
        Console.WriteLine($"  本机 DPI 缩放 {DpiScale:F2}");

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-46} {detail}");
        }
        bool Near(float a, float b, float tol) => MathF.Abs(a - b) <= tol;

        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        var ink = new Color4(1f, 0f, 1f, 1f);
        Host.Commands.SetColor(ink);
        // 界面那一层（问"这一段现在画的是哪张图标"要用它）——和 `--shapebandtest` 同一套起手：
        // 挂产品界面、等它铺开。**不挂的话 `CurrentUi` 不是 FullUi**，下面会 NRE。
        PassMode = PassThroughMode.LayeredTransparent;
        PassThrough = false;
        foreach (var w in _windows) ApplyPassThroughStyle(w);
        SetUiFactory(() => new InkUi.FullUi());
        SettleFrames(300);
        var ui = CurrentUi as InkUi.FullUi;
        if (ui == null)
        {
            Console.WriteLine($"  界面没挂上：当前 = {CurrentUi.Name}");
            ExitCode = 1;
            _quit = true;
            return;
        }

        // **被挡住的棱有几条**：§32.4 那条通用判据手算的结果，判据本体在 `ShapeSpec.PrismFaceVisible`
        //（"侧面的外法向朝向观察者吗"——观察者是 `(错切比, 1)` 方向，**错切那一项不能漏**）。
        // 起始角见 `ShapeSpec.PrismBaseOffsetDegrees`（统一 `90° + 180°/n`，正前方永远是一条边）——
        // 这个表跟着那个起始角走：改起始角，四个数都要重算。
        int HiddenWant(int nsides) => nsides switch { 3 => 3, 4 => 3, 5 => 3, 6 => 5, _ => -1 };

        // 把**某个立体工具**那一档拧到指定值（走的就是面板上"再点一次"那个命令）。
        // ⚠ 必须先切到那个工具——引擎换的是"**当前工具**那一档"（三格各记各的，
        // 见 `UiState.SidesOf`），不切工具就会一直拧棱柱那一档。
        void SetSides(Tool tool, int want)
        {
            SetToolFromUi(tool);
            for (int k = 0; k < 8 && Host.State.SidesOf(tool) != want; k++)
                Host.Commands.CycleSolidSides();
            SettleFrames(60);
        }

        Stroke NewSolid(Tool tool, StrokeKind kind, int sides)
        {
            var s = new Stroke
            {
                Tool = tool, Kind = kind, Color = ink, Width = 4f * DpiScale,
                PrismSides = sides,
            };
            s.AddPoint(400f, 300f, 1f, 0);
            return s;
        }

        Stroke NewPrism(int sides) => NewSolid(Tool.Prism, StrokeKind.Prism, sides);

        // ================= ①②③ 数学层：四个 n 各造一个 =================
        Console.WriteLine("  -- 数学层：底面 / 三族边 / 隐藏棱 --");
        foreach (int sides in new[] { 3, 4, 5, 6 })
        {
            var s = NewPrism(sides);
            s.SetPrismBase(400f, 300f, 700f, 420f);      // 外接框 300×120
            s.SetPrismApex(550f, 120f);                  // 顶心：往上拖 180

            var b = s.PrismBaseLocal();
            var lat = s.PrismLateralLocal();
            Check($"底面顶点数 = {sides}", b.Length == sides, $"{b.Length} 个");

            // 参数角均匀：把顶点**按画布上那套投影反算回单位圆**，相邻夹角差该是 360/n。
            // 反算必须把**错切**一起减掉（`ShapeSpec`：x = rxUse·cos − skew·sin, y = ry·sin），
            // 不然后面那步"除以 rx"减不掉错切，算出来的角就不均匀（这一条当场抓到过）。
            var c = s.PrismBaseCenterLocal();
            const float rx = 150f, ry = 60f;
            ShapeSpec.PrismFrame(rx, ry, out float rxUse, out float skew);
            float maxDev = 0f;
            for (int k = 0; k < sides; k++)
            {
                var a = b[k];
                var nx = b[(k + 1) % sides];
                float v0 = (a.Y - c.Y) / ry;
                float v1 = (nx.Y - c.Y) / ry;
                float u0 = (a.X - c.X + skew * v0) / rxUse;
                float u1 = (nx.X - c.X + skew * v1) / rxUse;
                float d = MathF.Atan2(v1, u1) - MathF.Atan2(v0, u0);
                while (d <= 0f) d += MathF.Tau;
                maxDev = MathF.Max(maxDev, MathF.Abs(d - MathF.Tau / sides));
            }
            Check($"{sides} 棱柱·底面是**正** {sides} 边形（参数角均匀，±0.5°）",
                  maxDev <= .5f * MathF.PI / 180f, $"最大偏差 {maxDev * 180f / MathF.PI:F4}°");

            // 三族边各 n 条；侧棱那 n 条的两端点之差 = 侧棱向量。
            // （`InkPiece` 是 Stroke 的**嵌套内部类型**，这里用 `var` 免得写全名。）
            var vis = s.PrismFamilyEdges(hidden: false);
            var hid = s.PrismFamilyEdges(hidden: true);
            var visLat = new List<float>();      // 看得见的竖棱的 x
            var hidLat = new List<float>();      // 被挡住的竖棱的 x
            int latCount = 0;
            foreach (var pc in vis)
                if (pc.Pts.Count == 2 && Vector2.Distance(pc.Pts[0] + lat, pc.Pts[1]) < 0.01f)
                { latCount++; visLat.Add(pc.Pts[0].X); }
            foreach (var pc in hid)
                if (pc.Pts.Count == 2 && Vector2.Distance(pc.Pts[0] + lat, pc.Pts[1]) < 0.01f)
                { latCount++; hidLat.Add(pc.Pts[0].X); }
            Check($"{sides} 棱柱·三族边各 {sides} 条（顶面 ＋ 底面 ＋ 侧棱 = {3 * sides}）",
                  vis.Count + hid.Count == 3 * sides && latCount == sides,
                  $"共 {vis.Count + hid.Count} 条（实 {vis.Count} / 虚 {hid.Count}），侧棱 {latCount} 条");

            Check($"{sides} 棱柱·被挡住 {HiddenWant(sides)} 条（§32.4 判据的定值）",
                  hid.Count == HiddenWant(sides), $"{hid.Count} 条（期望 {HiddenWant(sides)}）");

            // ---- 用户 2026-09-20 要求的三条（每一条都是一个"看着不对"的现场）----

            // ① **最靠前的那一条边必须是水平的**（四棱柱原来"最前面那条棱是斜的"）。
            //    判据：落在最前那一排（y 最大）的顶点得**不止一个**——两个以上才谈得上一条边。
            float maxY = float.MinValue;
            foreach (var v in b) maxY = MathF.Max(maxY, v.Y);
            int frontVerts = 0;
            foreach (var v in b) if (MathF.Abs(v.Y - maxY) < 0.5f) frontVerts++;
            Check($"{sides} 棱柱·最靠前那一条边是**水平的**（两个顶点同高）",
                  frontVerts >= 2, $"最前一排有 {frontVerts} 个顶点");

            // ② **被挡住的竖棱不能躲在前面的实线背后**（六棱柱原来后面两条虚线完全看不见）。
            //    判据用**模型自己分出来的那两组**（上面 visLat / hidLat 就是 PrismFamilyEdges 的产物）——
            //    不在这里另写一份"哪个面看得见"，那份判据只有 `ShapeSpec.PrismFaceVisible` 一条。
            float minGap = float.MaxValue;
            foreach (var hx in hidLat)
                foreach (var vx in visLat) minGap = MathF.Min(minGap, MathF.Abs(hx - vx));
            Check($"{sides} 棱柱·被挡住的竖棱**错开**了可见的竖棱（x 上拉开 ≥ 0.1×半宽）",
                  hidLat.Count == 0 || minGap >= 0.1f * rx,
                  $"虚 {hidLat.Count} 条 / 实 {visLat.Count} 条，最小间距 "
                  + $"{(float.IsPositiveInfinity(minGap) ? 0f : minGap):F1}（半宽 {rx:F0}）");

            // ③ **紧框上沿要贴住最高的那个顶点**（原来"上面会漏一块"：
            //    包围盒按"底面外接框"算，而正 n 边形并不填满那个框）。
            float topmost = float.MaxValue;
            foreach (var v in b)
            {
                topmost = MathF.Min(topmost, v.Y);
                topmost = MathF.Min(topmost, v.Y + lat.Y);
            }
            float frameGap = topmost - s.WorldInkBounds.MinY;      // 期望 = 半个笔宽
            Check($"{sides} 棱柱·紧框上沿贴着最高顶点（差 ≈ 半笔宽，不漏块）",
                  Near(frameGap, s.Width * 0.5f, 1.5f),
                  $"差 {frameGap:F2}（半笔宽 {s.Width * 0.5f:F2}）");
        }

        // ================= ④ 棱锥 / 棱台：和棱柱**同族**，只换"顶面怎么来" =================
        //
        // 这三兄弟的控制点完全一样（底面外接框两角 ＋ 顶上那个中心），所以几何上的差别
        // 就只有**顶面那一份点**（见 `Stroke.PrismTopLocal`）。这一节就把那一点钉住：
        //   · 棱锥：n 个顶面点**全等**（退化成一点）→ 于是棱只有 2n 条（没有顶面那一圈）；
        //   · 棱台：顶面点 = 顶心 ＋（底点 − 底心）× 比例 → 棱仍是 3n 条。
        // 另外**被挡住的棱条数沿用棱柱那张定值表**——这不是偷懒：三个图形的可见性判据
        // 是同一条（侧面法向朝不朝观察者），所以"几虚几实"本来就该一样。
        // 哪天判据动了，这里跟着一起动；要是**只有一家变了**，这条立刻红。
        Console.WriteLine("  -- 棱锥 / 棱台：控制点同棱柱，差别只在顶面 --");
        var familyRun = new (Tool tool, StrokeKind kind, string name)[]
        {
            (Tool.Pyramid, StrokeKind.Pyramid, "棱锥"),
            (Tool.Frustum, StrokeKind.Frustum, "棱台"),
        };
        foreach (var (tool, kind, fname) in familyRun)
        {
            foreach (int sides in new[] { 3, 4, 5, 6 })
            {
                var s = NewSolid(tool, kind, sides);
                s.SetPrismBase(400f, 300f, 700f, 420f);      // 和棱柱那一段同一个外接框
                s.SetPrismApex(550f, 120f);                  // 顶心：往上拖 180（直的）

                // ---- 顶面那一份点 ----
                var tp = s.PrismTopLocal();
                if (kind == StrokeKind.Pyramid)
                {
                    // 棱锥：n 个点**全等**（就是顶点）。容差给 0.01——它们是同一份算式出来的，
                    // 只可能有浮点末位差。
                    float maxSpread = 0f;
                    for (int k = 1; k < tp.Length; k++)
                        maxSpread = MathF.Max(maxSpread, Vector2.Distance(tp[0], tp[k]));
                    Check($"{sides} {fname}·顶面**退化成一个点**（{sides} 个顶面点全等）",
                          maxSpread < 0.01f, $"最大间距 {maxSpread:F4}");
                }
                else
                {
                    // 棱台：顶面点 = 顶心 ＋（底点 − 底心）× 比例，逐点比（把比例也钉住）。
                    var b0 = s.PrismBaseLocal();
                    var c0 = s.PrismBaseCenterLocal();
                    var apex0 = s.PrismApexLocal();
                    float maxErr = 0f;
                    for (int k = 0; k < tp.Length; k++)
                    {
                        var want = apex0 + (b0[k] - c0) * ShapeSpec.FrustumTopScale;
                        maxErr = MathF.Max(maxErr, Vector2.Distance(tp[k], want));
                    }
                    Check($"{sides} {fname}·上底 = 下底同形缩 {ShapeSpec.FrustumTopScale:F2}（逐点对）",
                          maxErr < 0.01f, $"最大偏差 {maxErr:F4}");
                }

                // ---- 棱的条数：棱锥少一圈顶面，所以是 2n 而不是 3n ----
                var vis = s.PrismFamilyEdges(hidden: false);
                var hid = s.PrismFamilyEdges(hidden: true);
                int wantEdges = kind == StrokeKind.Pyramid ? 2 * sides : 3 * sides;
                Check($"{sides} {fname}·棱共 {wantEdges} 条"
                      + (kind == StrokeKind.Pyramid ? "（**没有顶面那一圈**）" : "（底面 ＋ 顶面 ＋ 侧棱）"),
                      vis.Count + hid.Count == wantEdges,
                      $"共 {vis.Count + hid.Count} 条（实 {vis.Count} / 虚 {hid.Count}）");

                // ---- 被挡住的条数：和棱柱**同一张定值表**（判据是同一条）----
                Check($"{sides} {fname}·被挡住 {HiddenWant(sides)} 条（和棱柱同一张表）",
                      hid.Count == HiddenWant(sides), $"{hid.Count} 条（期望 {HiddenWant(sides)}）");
            }
        }

        // ================= ⑤ 真机：第 2 笔的直 / 斜 =================
        Console.WriteLine("  -- 真机：第 2 笔往上拖 = 直棱柱（吸附）／拖歪 = 斜棱柱 --");

        // 第 1 笔（两处都要用）：拖一个底面外接框。
        void DragBase(float bx, float by)
        {
            SendMouse((int)bx, (int)by, 0);                                          SettleFrames(50);
            SendMouse((int)bx, (int)by, Native.MOUSEEVENTF_LEFTDOWN);                 SettleFrames(50);
            SendMouse((int)(bx + 300f), (int)(by + 120f), 0);                         SettleFrames(80);
            SendMouse((int)(bx + 300f), (int)(by + 120f), Native.MOUSEEVENTF_LEFTUP); SettleFrames(180);
        }

        Doc.Clear();
        Doc.ClearHistory();
        SetSides(Tool.Prism, 4);
        float bx0 = _virtualX + 900f, by0 = _virtualY + 900f;
        DragBase(bx0, by0);
        Check("真机：第 1 笔松手后**还没提交**（两笔图形，半成品不进文档）",
              Doc.Strokes.Count == 0 && ActiveStroke != null,
              $"文档 {Doc.Strokes.Count} 条");
        Check("真机：第 1 笔的预览就是底面那一圈（侧棱还没拖，几何是扁的）",
              ActiveStroke != null && ActiveStroke.PrismLateralLocal().LengthSquared() < 1e-6f,
              $"侧棱 {ActiveStroke?.PrismLateralLocal()}");

        // 第 2 笔：**故意偏 8 像素**（容差 12）→ 该吸住
        float ax = bx0 + 150f + 8f, ay = by0 + 60f - 180f;
        SendMouse((int)ax, (int)ay, 0);                                    SettleFrames(50);
        SendMouse((int)ax, (int)ay, Native.MOUSEEVENTF_LEFTDOWN);           SettleFrames(50);
        SendMouse((int)ax, (int)ay, 0);                                    SettleFrames(180);
        Check("真机·直棱柱：第 2 笔偏 8 像素 → **吸住**", StepSnap == ShapeSnapKind.RightPrism,
              $"StepSnap = {StepSnap}（期望 RightPrism）");
        Check("真机·直棱柱：那颗胶囊写的是「直棱柱」（和「等边/正方形」同一套语言）",
              SelectionHandles.ShapeSnapLabel(StepSnap) == "直棱柱",
              $"「{SelectionHandles.ShapeSnapLabel(StepSnap)}」");
        Check("真机·直棱柱：吸住那一刻侧棱**已经竖直**（吸附写在模型上，不只是显示）",
              ActiveStroke != null && MathF.Abs(ActiveStroke.PrismLateralLocal().X) < 0.5f,
              $"侧棱 {ActiveStroke?.PrismLateralLocal()}");
        SendMouse((int)ax, (int)ay, Native.MOUSEEVENTF_LEFTUP);             SettleFrames(240);
        Check("真机·直棱柱：松手后胶囊收回去", StepSnap == ShapeSnapKind.None,
              $"StepSnap = {StepSnap}");
        Check("真机·直棱柱：提交之后**侧棱严格竖直**（横向差 < 0.5）",
              Doc.Strokes.Count == 1 && MathF.Abs(Doc.Strokes[0].PrismLateralLocal().X) < 0.5f,
              $"侧棱 {(Doc.Strokes.Count == 1 ? Doc.Strokes[0].PrismLateralLocal().ToString() : "（没提交）")}");
        Check("真机·直棱柱：底面边数 = 当前那一档（4）",
              Doc.Strokes.Count == 1 && Doc.Strokes[0].PrismSidesClamped == 4,
              $"{(Doc.Strokes.Count == 1 ? Doc.Strokes[0].PrismSidesClamped : 0)} 边形");

        // 拖歪 → 不吸，方向就是那一拖的方向
        Doc.Clear();
        Doc.ClearHistory();
        SetToolFromUi(Tool.Prism);
        DragBase(bx0, by0);
        float sx = bx0 + 150f + 220f, sy = by0 + 60f - 140f;      // 明显偏右 → 斜棱柱
        SendMouse((int)sx, (int)sy, 0);                                    SettleFrames(50);
        SendMouse((int)sx, (int)sy, Native.MOUSEEVENTF_LEFTDOWN);           SettleFrames(50);
        SendMouse((int)sx, (int)sy, 0);                                    SettleFrames(160);
        Check("真机·斜棱柱：拖歪 → **不吸**（没有胶囊）", StepSnap == ShapeSnapKind.None,
              $"StepSnap = {StepSnap}");
        SendMouse((int)sx, (int)sy, Native.MOUSEEVENTF_LEFTUP);             SettleFrames(240);
        var slat = Doc.Strokes.Count == 1 ? Doc.Strokes[0].PrismLateralLocal() : Vector2.Zero;
        Check("真机·斜棱柱：侧棱方向 = 那一拖的方向（横向差 ≈ 220−8，不被动过）",
              Doc.Strokes.Count == 1 && Near(slat.X, 220f, 2f) && Near(slat.Y, -140f, 2f),
              $"侧棱 {slat}（期望 ≈ (220, −140)）");

        // ---- 棱锥 / 棱台：**同一套动作、同一个吸附**，只是胶囊上的字和"顶上那点"不同 ----
        //
        // 这几条一起看的就是"**族内一致**"：容差同一个（12）、判据同一条（顶上那个中心在
        // 底心正上方）、只是报出来的名字按种类分。所以这里最要紧的两条断言是：
        //   · **胶囊上的字**——它错了用户就会看到"画棱锥却写着直棱柱"；
        //   · **底面边数 = 这一格自己的档**——2026-09-20 第一版把"写档"那句写成
        //     `kind == StrokeKind.Prism`，于是棱锥 / 棱台**永远画成四棱**（用户："锥体和台体
        //     只能画四棱，不能画其他的"）。所以这里**故意给两家不同的档**（3 / 5）：
        //     要是又有人漏了那一句，两条都会红。
        var familyReal = new (Tool tool, StrokeKind kind, string name, ShapeSnapKind snap, string label, int sides)[]
        {
            (Tool.Pyramid, StrokeKind.Pyramid, "棱锥", ShapeSnapKind.RightPyramid, "直棱锥", 3),
            (Tool.Frustum, StrokeKind.Frustum, "棱台", ShapeSnapKind.RightFrustum, "直棱台", 5),
        };
        foreach (var (tool, kind, fname, snap, label, wantSides) in familyReal)
        {
            Doc.Clear();
            Doc.ClearHistory();
            SetSides(tool, wantSides);
            DragBase(bx0, by0);

            float px = bx0 + 150f + 8f, py = by0 + 60f - 180f;      // 故意偏 8 像素（容差 12）
            SendMouse((int)px, (int)py, 0);                                    SettleFrames(50);
            SendMouse((int)px, (int)py, Native.MOUSEEVENTF_LEFTDOWN);           SettleFrames(50);
            SendMouse((int)px, (int)py, 0);                                    SettleFrames(180);
            Check($"真机·{fname}：第 2 笔偏 8 像素 → **吸住**，胶囊「{label}」",
                  StepSnap == snap && SelectionHandles.ShapeSnapLabel(StepSnap) == label,
                  $"StepSnap = {StepSnap}「{SelectionHandles.ShapeSnapLabel(StepSnap)}」");
            SendMouse((int)px, (int)py, Native.MOUSEEVENTF_LEFTUP);             SettleFrames(240);

            var made = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
            float tilt = made == null ? -1f
                : MathF.Abs(made.PrismApexLocal().X - made.PrismBaseCenterLocal().X);
            Check($"真机·{fname}：提交之后顶上那个中心**严格在底心正上方**",
                  made != null && made.Kind == kind && tilt < 0.5f,
                  made == null ? "（没画出来）" : $"侧倾 {tilt:F2}（期望 < 0.5）");
            Check($"真机·{fname}：底面是**这一格自己的档**（{wantSides} 棱）——不是永远四棱",
                  made != null && made.PrismSidesClamped == wantSides
                  && made.PrismBaseLocal().Length == wantSides,
                  made == null ? "（没画出来）"
                               : $"存档里的档 {made.PrismSidesClamped}、底面 {made.PrismBaseLocal().Length} 个顶点");
        }

        // ================= ⑥ 档位 ＋ 长方体没被碰 =================
        Console.WriteLine("  -- 档位：点那一格再点一次 3→4→5→6→3 --");
        SetSides(Tool.Prism, 3);
        var iconNames = new List<string>();
        for (int k = 0; k < 4; k++)
        {
            iconNames.Add(ui.ShapeIconNameForTest(InkUi.FullUi.ShapeSegmentIndexForTest(Tool.Prism)));
            Host.Commands.CycleSolidSides();
            SettleFrames(60);
        }
        Check("档位：一轮四档，回到三棱柱（3→4→5→6→3）",
              Host.State.SidesOf(Tool.Prism) == 3, $"现在是 {Host.State.SidesOf(Tool.Prism)}");
        Check("档位：四张图标两两不同，而且都是 prism 那四张",
              iconNames.Distinct().Count() == 4 && iconNames.All(nm => nm.StartsWith("prism")),
              string.Join(" / ", iconNames));
        Check("档位：范围**随状态推上界面**（3 / 6）——界面靠它决定画几个档位点",
              Host.State.SolidMinSides == 3 && Host.State.SolidMaxSides == 6,
              $"{Host.State.SolidMinSides} ~ {Host.State.SolidMaxSides}");

        // **三格各记各的档**（用户 2026-09-20 上手就报的 bug："切一个另外两个也动"）。
        //
        // 第一版是"三格共用一个 `PrismSides`"——写的时候觉得"它们本来就是同一族，
        // 跟着走正好"，实际用起来完全不是：老师完全可能"四棱柱 ＋ 三棱锥"混着画。
        // 所以现在是引擎里**三个字段**，换档命令换的是"**当前工具**那一档"。
        // 这里就钉住那件事：先把三格拧成**三个不同的档**，再单独换一格，看另外两格动没动。
        //
        // ⚠ 段号一律**按工具名问**（`ShapeSegmentIndexForTest`），不写死：
        // 写死的话，第二行一旦插 / 删图形就会静默点错段（这一轮加棱锥 / 棱台时就栽了一下
        // ——写死的"16 = 棱柱"其实已经是"棱台"）。
        SetSides(Tool.Prism, 3);
        SetSides(Tool.Pyramid, 4);
        SetSides(Tool.Frustum, 5);
        string Sides3() => $"{Host.State.SidesOf(Tool.Prism)}/"
                         + $"{Host.State.SidesOf(Tool.Pyramid)}/{Host.State.SidesOf(Tool.Frustum)}";
        Check("档位：三格**各记各的档**（四棱柱 ＋ 三棱锥 ＋ 五棱台 这种配法要能存在）",
              Host.State.SidesOf(Tool.Prism) == 3 && Host.State.SidesOf(Tool.Pyramid) == 4
              && Host.State.SidesOf(Tool.Frustum) == 5,
              Sides3() + "（期望 3/4/5）");
        SetToolFromUi(Tool.Pyramid);                 // 换档换的是"当前工具那一档"
        Host.Commands.CycleSolidSides();
        SettleFrames(60);
        Check("档位：只换棱锥那一格 → **棱柱和棱台的档一点没动**",
              Host.State.SidesOf(Tool.Prism) == 3 && Host.State.SidesOf(Tool.Pyramid) == 5
              && Host.State.SidesOf(Tool.Frustum) == 5,
              Sides3() + "（期望 3/5/5）");
        string IconOf(Tool t) => ui.ShapeIconNameForTest(InkUi.FullUi.ShapeSegmentIndexForTest(t));
        Check("档位：三格的图标各按**自己那一档**画（棱柱 3 / 棱锥 5 / 棱台 5）",
              IconOf(Tool.Prism) == "prism3" && IconOf(Tool.Pyramid) == "pyramid5"
              && IconOf(Tool.Frustum) == "frustum5",
              $"{IconOf(Tool.Prism)} / {IconOf(Tool.Pyramid)} / {IconOf(Tool.Frustum)}");
        SetSides(Tool.Prism, 3);

        Doc.Clear();
        Doc.ClearHistory();
        DragBase(bx0, by0);
        SendMouse((int)(bx0 + 150f), (int)(by0 + 60f - 200f), 0);             SettleFrames(50);
        SendMouse((int)(bx0 + 150f), (int)(by0 + 60f - 200f), Native.MOUSEEVENTF_LEFTDOWN); SettleFrames(50);
        SendMouse((int)(bx0 + 150f), (int)(by0 + 60f - 200f), Native.MOUSEEVENTF_LEFTUP);   SettleFrames(240);
        Check("档位：三棱柱真的画得出来（底面 3 个顶点、侧棱 3 条）",
              Doc.Strokes.Count == 1 && Doc.Strokes[0].PrismBaseLocal().Length == 3
              && Doc.Strokes[0].PrismFamilyEdges(hidden: false).Count
                 + Doc.Strokes[0].PrismFamilyEdges(hidden: true).Count == 9,
              Doc.Strokes.Count == 1
                ? $"底面 {Doc.Strokes[0].PrismBaseLocal().Length} 个顶点、"
                  + $"棱 {Doc.Strokes[0].PrismFamilyEdges(false).Count + Doc.Strokes[0].PrismFamilyEdges(true).Count} 条"
                : "（没画出来）");

        // 长方体：一个数都不许变（它是另一族，见 §32.2 第 2 条）。
        var cu = new Stroke { Tool = Tool.Cuboid, Kind = StrokeKind.Cuboid, Color = ink, Width = 4f * DpiScale };
        cu.AddPoint(200f, 500f, 1f, 0);
        cu.SetCuboidFront(200f, 500f, 600f, 900f);
        cu.SetCuboidDepth(500f, 650f);
        Check("长方体不受影响：深度 150、第三个控制点还是背面右下角 (750, 750)",
              Near(cu.CuboidDepthLocal(), 150f, .5f)
              && Near(cu.CurvePointLocal(2).X, 750f, .5f) && Near(cu.CurvePointLocal(2).Y, 750f, .5f),
              $"深度 {cu.CuboidDepthLocal():F1}，第 3 点 "
              + $"({cu.CurvePointLocal(2).X:F0},{cu.CurvePointLocal(2).Y:F0})");
        Check("长方体不受影响：它给的还是**通用八手柄**那一套（棱柱没有碰它）",
              !SelectionHandles.HasShapeHandles(cu)
              && SelectionHandles.HasShapeHandles(NewPrism(4)) == false,
              "长方体 / 棱柱 都没有定义元素手柄（走通用框）");

        Doc.Clear();
        Doc.ClearHistory();
        SettleFrames(120);

        Console.WriteLine();
        Console.WriteLine($"  合计 {pass + fail} 项：通过 {pass}，失败 {fail}");
        _quit = true;
    }

    // =====================================================================
    //  棱柱出图（2026-09-20 第十一批）：`--prismshow <路径>`
    // =====================================================================

    /// <summary>
    /// 出图：**三 / 四 / 五 / 六** × **棱柱 / 棱锥 / 棱台**各一行（都是"直"的）
    /// ＋ 一行"**直 vs 斜**"。
    ///
    /// 为什么必须出图：这一族"立着画得对不对、虚线配得对不对"**只能看**——
    /// 几何全对（顶点数、边长、侧棱向量）也一样可能看着别扭。
    /// 尤其三点：① 四棱柱那条（底面是扁的正方形，以前左右两条边与视线平行、
    /// 整块塌成平板，见 §33.2 / §33.6）；② 五/六两张的底面看得出分别吗；
    /// ③ **棱锥的顶是不是收敛成一点、棱台的上底是不是明显小一圈**——
    /// 这两件事自检只能数出"点的个数 / 比例对"，"看着像不像"只有图能说。
    /// </summary>
    private void PrismShowcase(string path)
    {
        BoardOn = true;                       // 白底：虚线压在桌面上看不清
        Doc.Clear();
        Doc.ClearHistory();
        Tool = Tool.Marquee;
        var ink = new Color4(0.11f, 0.12f, 0.15f, 1f);

        void Put(Tool tool, StrokeKind kind, int sides, float bx, float by, float dx, float dy)
        {
            var s = new Stroke
            {
                Tool = tool, Kind = kind, Color = ink,
                Width = 6f * DpiScale, PrismSides = sides,
            };
            s.AddPoint(bx, by, 1f, 0);
            s.SetPrismBase(bx, by, bx + 340f, by + 140f);        // 底面外接框 340×140（压扁比 ≈ 0.41）
            s.SetPrismApex(bx + 170f + dx, by + 70f + dy);       // 顶上那个中心（dx/dy 决定直还是斜）
            Doc.AddStroke(s);
        }

        // 三行：棱柱 / 棱锥 / 棱台，每行都是**三/四/五/六**、都是直的（顶上那个中心正对底心上方 240）
        var rows = new (Tool tool, StrokeKind kind)[]
        {
            (Tool.Prism, StrokeKind.Prism),
            (Tool.Pyramid, StrokeKind.Pyramid),
            (Tool.Frustum, StrokeKind.Frustum),
        };
        float[] colX = { 200f, 820f, 1440f, 2060f };
        int[] colSides = { 3, 4, 5, 6 };
        for (int r = 0; r < rows.Length; r++)
        {
            float by = _virtualY + 420f + r * 400f;
            for (int c = 0; c < colX.Length; c++)
                Put(rows[r].tool, rows[r].kind, colSides[c], _virtualX + colX[c], by, 0f, -240f);
        }

        // 最后一行：**直 vs 斜**，三族各一对（同一个四棱，斜的那个顶心往右挪 200）
        float lastY = _virtualY + 420f + rows.Length * 400f;
        var pairs = new (Tool tool, StrokeKind kind, float x, bool slant)[]
        {
            (Tool.Prism, StrokeKind.Prism, 200f, false),
            (Tool.Prism, StrokeKind.Prism, 760f, true),
            (Tool.Pyramid, StrokeKind.Pyramid, 1320f, false),
            (Tool.Pyramid, StrokeKind.Pyramid, 1880f, true),
            (Tool.Frustum, StrokeKind.Frustum, 2440f, false),
        };
        foreach (var (tool, kind, x, slant) in pairs)
            Put(tool, kind, 4, _virtualX + x, lastY,
                slant ? 200f : 0f, slant ? -200f : -240f);

        Doc.InvalidateAll();
        SettleFrames(800);

        bool ok = ScreenProbe.SaveBmp(path, (int)_virtualX, (int)_virtualY, 2880, 1800);
        Console.WriteLine(ok
            ? $"  已保存 {path}（上三行：三/四/五/六 的 棱柱 / 棱锥 / 棱台，都是直的；末行：直 vs 斜）"
            : "  保存失败");
        _quit = true;
    }

    private void CurveTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 四种曲线自检（抛物线 / 双曲线 / 正弦 / 余弦）===");
        Console.WriteLine($"  本机 DPI 缩放 {DpiScale:F2}");

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-38} {detail}");
        }
        bool Near(float a, float b, float tol) => MathF.Abs(a - b) <= tol;
        // 方向比较：两个单位向量「几乎相同」（用于"方向没变 / 变到哪去了"这类断言）。
        bool NearDir(Vector2 a, Vector2 b) => Vector2.Distance(a, b) <= 0.01f;

        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        float minAxis = ShapeMinAxisLogical * DpiScale;
        var ink = new Color4(1f, 0f, 1f, 1f);            // 品红：屏幕上好数
        Host.Commands.SetColor(ink);

        // 造一条"刚起手"的曲线（只有 BeginShapeAt 铺的那一个占位点），
        // 再走 Set*Box —— 和真机拖动走的是同一条路。
        Stroke NewCurve(Tool tool, StrokeKind kind, float x, float y)
        {
            var s = new Stroke { Tool = tool, Kind = kind, Color = ink, Width = 4f * DpiScale };
            s.AddPoint(x, y, 1f, 0);
            return s;
        }
        // 点到线段的距离（验"两支之间有没有幽灵线段"用）。
        float DistPointSeg(Vector2 p, Vector2 a, Vector2 b)
        {
            var ab = b - a;
            float len2 = ab.LengthSquared();
            if (len2 < 1e-6f) return Vector2.Distance(p, a);
            float t = Math.Clamp(Vector2.Dot(p - a, ab) / len2, 0f, 1f);
            return Vector2.Distance(p, a + ab * t);
        }

        // ================= ① 画法：真机**一笔拖**画一条抛物线 =================
        // 口径（用户 2026-09-20 照 InkClass 的 `case 20/21`）：**顶点 = 按下那个点**，
        // 一次拖到"曲线要经过的地方"、松手就成；朝向是画之前在图形面板上选好的
        // （这里走默认的"开口向上"）。
        Doc.Clear();
        Doc.ClearHistory();
        SetToolFromUi(Tool.Parabola);
        float px = _virtualX + 900f, py = _virtualY + 900f;

        // 按下（还没拖）：半成品不进文档。
        SendMouse((int)px, (int)py, 0);                            SettleFrames(60);
        SendMouse((int)px, (int)py, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
        Check("抛物线：按下（定顶点）之后**还没提交**（半成品不进文档）",
              Doc.Strokes.Count == 0, $"对象 {Doc.Strokes.Count} 条（期望 0）");

        // 拖到顶点右上方 120 × 100：曲线**经过这个点**——
        // 朝上开口时 `s = 100、t = 120` → `p = t²/(2s) = 14400/200 = 72`。
        SendMouse((int)(px + 120f), (int)(py - 100f), 0);   SettleFrames(240);
        Check("抛物线：拖动的时候曲线**经过指针那个点**（p = t²/2s = 72）（±2）",
              ActiveStroke != null && Near(ActiveStroke.ParabolaPLocal(), 72f, 2f),
              $"p {(ActiveStroke == null ? -1f : ActiveStroke.ParabolaPLocal()):F1}（期望 72）");

        // 松手：完成（提交就发生在这一刻）。
        SendMouse((int)(px + 120f), (int)(py - 100f), Native.MOUSEEVENTF_LEFTUP); SettleFrames(180);

        var pbDraw = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
        Check("抛物线：**松手之后**对象才出来（一条抛物线）",
              pbDraw != null && pbDraw.Kind == StrokeKind.Parabola,
              pbDraw == null ? $"对象 {Doc.Strokes.Count} 条（期望 1）" : $"Kind={pbDraw.Kind}");
        if (pbDraw == null) { Console.WriteLine("  （后面几项没法验）"); _quit = true; return; }

        Check("抛物线：两个定义元素（顶点 ＋ 曲线上的那个点）",
              pbDraw.Points.Count == 2, $"控制点 {pbDraw.Points.Count} 个");
        Check("抛物线：**顶点 = 按下那个点**（±2 像素）",
              Near(pbDraw.CurvePointLocal(0).X, px, 2f) && Near(pbDraw.CurvePointLocal(0).Y, py, 2f),
              $"顶点 ({pbDraw.CurvePointLocal(0).X:F0},{pbDraw.CurvePointLocal(0).Y:F0})"
              + $" 期望 ({px:F0},{py:F0})");
        Check("抛物线：**经过点 = 最后点的那个位置**（±2 像素）",
              Near(pbDraw.CurvePointLocal(1).X, px + 120f, 2f)
              && Near(pbDraw.CurvePointLocal(1).Y, py - 100f, 2f),
              $"经过点 ({pbDraw.CurvePointLocal(1).X:F0},{pbDraw.CurvePointLocal(1).Y:F0})"
              + $" 期望 ({px + 120f:F0},{py - 100f:F0})");
        Check("抛物线：朝向 = **开口向上**（默认值，不是从两点推的）",
              pbDraw.EffectiveAxis == CurveAxis.OpenUp && Near(pbDraw.ParabolaDirLocal().Y, -1f, .01f),
              $"{pbDraw.EffectiveAxis} / {pbDraw.ParabolaDirLocal()}");
        Check("抛物线：p = 72（±4）", Near(pbDraw.ParabolaPLocal(), 72f, 4f),
              $"p {pbDraw.ParabolaPLocal():F1}");
        Check("抛物线：一笔拖到底 = **一步撤销**（不是两步）",
              Doc.UndoDepth == 1, $"撤销栈 {Doc.UndoDepth} 步");

        // ================= ② 几何算式（直接摆点，不走工具） =================
        Doc.Clear();
        Doc.ClearHistory();

        // ---- 抛物线：顶点 (400,400)、**开口向上**、经过点 (700,250) → p = 300 ----
        // 经过点取的是 `u = 1` 处的曲线点（也就是通径端点）：`s = p/2 = 150、t = p = 300`
        // → 反解 `p = t²/(2s) = 300`。它和上一版"顶点 + 张口点 (400,250)"画出来的是
        // **同一条曲线**，所以下面那些紧框 / 脏区断言一个都不用改。
        var vb = NewCurve(Tool.Parabola, StrokeKind.Parabola, 400f, 400f);
        vb.CurveAxis = CurveAxis.OpenUp;
        vb.SetParabolaVertex(400f, 400f);
        vb.SetParabolaThroughPoint(700f, 250f);
        Check("抛物线：顶点 (400,400)、经过点 (700,250)（±0.5）",
              Near(vb.CurvePointLocal(0).X, 400f, .5f) && Near(vb.CurvePointLocal(0).Y, 400f, .5f)
              && Near(vb.CurvePointLocal(1).X, 700f, .5f) && Near(vb.CurvePointLocal(1).Y, 250f, .5f),
              $"顶点 ({vb.CurvePointLocal(0).X:F1},{vb.CurvePointLocal(0).Y:F1})"
              + $" 经过点 ({vb.CurvePointLocal(1).X:F1},{vb.CurvePointLocal(1).Y:F1})");
        Check("抛物线：朝向 = **选出来的开口向上**（不是从两点推的）",
              vb.EffectiveAxis == CurveAxis.OpenUp
              && Near(vb.ParabolaDirLocal().X, 0f, .01f) && Near(vb.ParabolaDirLocal().Y, -1f, .01f),
              $"{vb.EffectiveAxis} / {vb.ParabolaDirLocal()}");
        Check("抛物线：p 由经过点反解 = t²/(2s) = 300²/300 = 300（±0.5）",
              Near(vb.ParabolaPLocal(), 300f, .5f), $"p {vb.ParabolaPLocal():F1}");
        var vbT0 = vb.ParabolaPointAt(0f);
        var vbT1 = vb.ParabolaPointAt(1f);
        Check("抛物线：t=0 落在顶点、t=±1 落在**通径端点**（= 我们给的那个经过点）上（±0.5）",
              Near(vbT0.X, 400f, .5f) && Near(vbT0.Y, 400f, .5f)
              && Near(vbT1.X, 700f, .5f) && Near(vbT1.Y, 250f, .5f),
              $"t0 ({vbT0.X:F1},{vbT0.Y:F1})  t1 ({vbT1.X:F1},{vbT1.Y:F1}) 期望 (400,400) / (700,250)");
        var vbBox = vb.CurveBoxLocal();
        // 紧框 = **"顶点 ↔ 经过点"那个矩形**（照 InkClass：画到拖到的那个点为止）——
        // 于是那个点**正好落在框角上**：横跨 ±300、沿轴 0…150。
        Check("抛物线：紧框 = **拖动那个矩形**（经过点正好落在框角上）（±0.5）",
              Near(vbBox.MinX, 100f, .5f) && Near(vbBox.MaxX, 700f, .5f)
              && Near(vbBox.MinY, 250f, .5f) && Near(vbBox.MaxY, 400f, .5f),
              $"框 ({vbBox.MinX:F1},{vbBox.MinY:F1})..({vbBox.MaxX:F1},{vbBox.MaxY:F1})"
              + " 期望 (100,250)..(700,400)");
        var vbPad = vb.PaddedBounds;
        Check("抛物线：脏区框 = 紧框 ＋ 半笔宽 ＋ 2（±0.05）",
              Near(vbPad.MinX, vbBox.MinX - vb.Width * .5f - 2f, .05f)
              && Near(vbPad.MaxY, 400f + vb.Width * .5f + 2f, .05f),
              $"({vbPad.MinX:F2},{vbPad.MinY:F2})..({vbPad.MaxX:F2},{vbPad.MaxY:F2})"
              + $" 笔宽 {vb.Width:F1}");

        // ---- 双曲线：中心 (1200,500)，第一步"拖出渐近线框 (320,240)" ----
        //      **拖到哪就是哪**：A = 320、B = 240（2026-09-20 改成不再打对折，
        //      因为渐近线自己就是框、不再需要"画到 2a、2b"那种放大）。
        //      第二步（第三个点）= "**曲线要经过的那个点**"：(1370,560)，相对中心 `dx = 170、dy = 60`
        //      → 曲线的 x 方向半宽 `a = √(170² − 60²·(4/3)²) = √22500 = 150`、
        //      y 方向半高 `b = a × B/A = 112.5`。**这一步渐近线框一个字都不动**（这次改动的核心）。
        var hy = NewCurve(Tool.Hyperbola, StrokeKind.Hyperbola, 1200f, 500f);
        hy.SetHyperbolaFromAsymptote(1200f, 500f, 1520f, 740f, minAxis);
        hy.SetHyperbolaThroughPoint(1370f, 560f);
        Check("双曲线：第一步 A = 320、B = 240（**拖到哪就是哪**）（±0.5）",
              Near(hy.HyperbolaALocal(), 320f, .5f) && Near(hy.HyperbolaBLocal(), 240f, .5f),
              $"A {hy.HyperbolaALocal():F1}  B {hy.HyperbolaBLocal():F1}");
        Check("双曲线：渐近线斜率 = B/A = 240/320 = 0.75（就是 InkClass 的 |dy/dx|）（±0.001）",
              Near(hy.HyperbolaBLocal() / hy.HyperbolaALocal(), 0.75f, .001f),
              $"{hy.HyperbolaBLocal() / hy.HyperbolaALocal():F4}（期望 0.7500）");
        // **第二步只写第三个点**：曲线的半轴由它反解，渐近线框（A / B）**原封不动**。
        Check("双曲线：第二步的点反解出曲线的半轴（a = 150、b = 112.5），框不动（±0.5）",
              Near(hy.HyperbolaCurveALocal(), 150f, .5f) && Near(hy.HyperbolaCurveBLocal(), 112.5f, .5f)
              && Near(hy.HyperbolaALocal(), 320f, .5f) && Near(hy.HyperbolaBLocal(), 240f, .5f),
              $"曲线 a {hy.HyperbolaCurveALocal():F1}、b {hy.HyperbolaCurveBLocal():F1}；"
              + $"框 A {hy.HyperbolaALocal():F1}、B {hy.HyperbolaBLocal():F1}");
        var hyBox = hy.CurveBoxLocal();
        // 紧框 = **渐近线的那个矩形**（用户 2026-09-20 定："把双曲线限制在渐近线的矩形框内"）。
        // hy：中心 (1200,500)、A = 320、B = 240 → 框 = ±320 × ±240。
        Check("双曲线：紧框 = ±A × ±B（就是渐近线框）（±0.5）",
              Near(hyBox.MinX, 1200f - 320f, .5f) && Near(hyBox.MaxX, 1200f + 320f, .5f)
              && Near(hyBox.MinY, 500f - 240f, .5f) && Near(hyBox.MaxY, 500f + 240f, .5f),
              $"框 ({hyBox.MinX:F1},{hyBox.MinY:F1})..({hyBox.MaxX:F1},{hyBox.MaxY:F1})"
              + $" 期望 (880,260)..(1520,740)");
        var hyApex = hy.HyperbolaVertexLocal(1);
        Check("双曲线：顶点在 (中心.x ＋ a, 中心.y) = (1350, 500)（±0.5）",
              Near(hyApex.X, 1350f, .5f) && Near(hyApex.Y, 500f, .5f),
              $"({hyApex.X:F1},{hyApex.Y:F1}) 期望 (1350,500)");
        // 两支之间的"幽灵线段"：轮廓折线是被逐段判交消费的（橡皮 / 套索），
        // 中间那条横穿的连线会让"橡皮从两支之间划过 = 整条被删"。
        var hyOutline = hy.ShapeOutline();
        float nearest = float.MaxValue;
        int breaks = 0;
        for (int i = 1; i < hyOutline.Count; i++)
        {
            if (Stroke.IsOutlineBreak(hyOutline[i - 1]))
            {
                breaks++;                 // 抬笔标记（见 Stroke.OutlineBreak）：一条接在它后面
                continue;
            }
            if (Stroke.IsOutlineBreak(hyOutline[i])) continue;      // 同上一条的尾巴
            nearest = MathF.Min(nearest, DistPointSeg(new Vector2(1200f, 500f),
                                                      hyOutline[i - 1], hyOutline[i]));
        }
        Check("双曲线：轮廓里恰好一个**抬笔标记**（两支分开、不连线）", breaks == 1, $"{breaks} 处抬笔");
        Check("双曲线：轮廓里**没有横穿两支之间**的幽灵线段（中心到任一段 ≥ 0.9a）",
              nearest >= 150f * 0.9f, $"最近距离 {nearest:F1}（a = 150，要 ≥ 135）");

        // **曲线整条收在渐近线框里**（用户 2026-09-20 的诉求）：
        // 渐近线框 = ±A × ±B = ±320 × ±240，而曲线"**出框就停笔**"（见 Stroke.HyperbolaTMaxOf）——
        // 先到哪条边就停在哪条边。hy 的 `2a = 300 < A = 320`，所以它**先撞上那条"最多画到 2a"的上限**
        // （`cosh t = 2`，见 HyperbolaDrawT），横向停在 300、纵向停在 `b√3 ≈ 194.9`。
        float hMaxX = 0f, hMaxY = 0f;
        foreach (var q in hyOutline)
        {
            if (Stroke.IsOutlineBreak(q)) continue;
            hMaxX = MathF.Max(hMaxX, MathF.Abs(q.X - 1200f));
            hMaxY = MathF.Max(hMaxY, MathF.Abs(q.Y - 500f));
        }
        Check("双曲线：**整条曲线收在渐近线框内**（|x| ≤ A、|y| ≤ B）（±0.5）",
              hMaxX <= 320f + .5f && hMaxY <= 240f + .5f,
              $"曲线最远 ({hMaxX:F1},{hMaxY:F1})，框 (±320,±240)");
        Check("双曲线：横向**画到拖到的那个点为止**（最远 x = 170，照 InkClass）（±0.5）",
              Near(hMaxX, 170f, .5f), $"{hMaxX:F1}（期望 170）");
        Check("双曲线：另一条轴只到 b·sinh(t)（≈59.8，那个点在那儿）（±0.5）",
              Near(hMaxY, 60f, .5f), $"{hMaxY:F1}（期望 ≈60）");

        // ---- 正弦：起点 (300,1000)；拖出 **480 宽 × 100 高 = 一个周期 + 振幅** ----
        // ⚠ 2026-09-20 第十六批：正弦 / 余弦回到"**框宽就是一个周期**"
        //（用户："正弦和余弦用一个周期的图"）——多周期那件事交给**波浪线**那一格
        //（横向 = 要画多长，见下面 ⑥ 段）。
        //   A = 100（正弦：纵拖 = 振幅）→ **T = 框宽 = 480** → 画 1 个周期。
        var sn = NewCurve(Tool.Sine, StrokeKind.Sine, 300f, 1000f);
        sn.SetWaveBox(300f, 1000f, 780f, 900f, minAxis);
        Check("正弦：起点 = 按下点、终点 = 起点＋(长度, 高度)（±0.5）",
              Near(sn.Points[0].X, 300f, .5f) && Near(sn.Points[0].Y, 1000f, .5f)
              && Near(sn.Points[1].X, 780f, .5f) && Near(sn.Points[1].Y, 900f, .5f),
              $"起点 ({sn.Points[0].X:F1},{sn.Points[0].Y:F1})"
              + $" 终点 ({sn.Points[1].X:F1},{sn.Points[1].Y:F1})");
        Check("正弦：两个定义元素（起点 ＋ 终点，极值点是现推的）",
              sn.Points.Count == 2, $"{sn.Points.Count} 个");
        Check("正弦：A = 100、**T = 框宽 = 480**、正好画 1 个周期（±0.5）",
              Near(sn.WaveAmplitudeLocal(), 100f, .5f)
              && Near(sn.WavePeriodLocal(), 480f, .5f)
              && Near(sn.WaveLengthLocal(), 480f, .5f)
              && Near(sn.WaveCyclesLocal(), 1f, .01f),
              $"A {sn.WaveAmplitudeLocal():F1}  T {sn.WavePeriodLocal():F1}"
              + $"  长 {sn.WaveLengthLocal():F1}  周期数 {sn.WaveCyclesLocal():F2}（期望 1.00）");
        var snQ = sn.WavePointAt(0.25f);
        var snH = sn.WavePointAt(0.5f);
        var snT = sn.WavePointAt(0.75f);
        Check("正弦：u=0 在轴上、u=0.25 到峰、u=0.5 回轴、u=0.75 到谷（±0.5）",
              Near(sn.WavePointAt(0f).Y, 1000f, .5f) && Near(snQ.Y, 900f, .5f)
              && Near(snH.Y, 1000f, .5f) && Near(snT.Y, 1100f, .5f),
              $"0:{sn.WavePointAt(0f).Y:F1} 1/4:{snQ.Y:F1} 1/2:{snH.Y:F1} 3/4:{snT.Y:F1}");
        var snBox = sn.CurveBoxLocal();
        Check("正弦：紧框 = 一个周期宽 × ±A（峰和谷都在里面）（±0.5）",
              Near(snBox.MinX, 300f, .5f) && Near(snBox.MaxX, 780f, .5f)
              && Near(snBox.MinY, 900f, .5f) && Near(snBox.MaxY, 1100f, .5f),
              $"框 ({snBox.MinX:F1},{snBox.MinY:F1})..({snBox.MaxX:F1},{snBox.MaxY:F1})");

        // ---- 余弦：起点 (300,1400)（**峰顶**）；拖出 480 宽 × 200 高 = 一个周期 ----
        // 纵向拖的是"峰 → 谷"＝ 2A（这是余弦和正弦唯一的不对称，见 WaveAmplitudeOf），
        // 横向那一拖同样是**一个周期**。
        var cs = NewCurve(Tool.Cosine, StrokeKind.Cosine, 300f, 1400f);
        cs.SetWaveBox(300f, 1400f, 780f, 1600f, minAxis);   // 纵拖 = 峰→谷 = 2A → A = 100
        Check("余弦：起点是**峰顶**、终点在**谷**那一侧（±0.5）",
              Near(cs.Points[0].Y, 1400f, .5f) && Near(cs.Points[1].Y, 1600f, .5f)
              && Near(cs.WaveTroughLocal().X, 540f, .5f) && Near(cs.WaveTroughLocal().Y, 1600f, .5f),
              $"起点 y {cs.Points[0].Y:F1}  终点 y {cs.Points[1].Y:F1}"
              + $"  谷 ({cs.WaveTroughLocal().X:F1},{cs.WaveTroughLocal().Y:F1})"
              + "（期望 x=540 = 300 ＋ 半个周期 240）");
        Check("余弦：A = 100、T = 框宽 = 480、正好 1 个周期（和正弦同一条算式）（±0.5）",
              Near(cs.WaveAmplitudeLocal(), 100f, .5f) && Near(cs.WavePeriodLocal(), 480f, .5f)
              && Near(cs.WaveCyclesLocal(), 1f, .01f),
              $"A {cs.WaveAmplitudeLocal():F1}  T {cs.WavePeriodLocal():F1}"
              + $"  周期数 {cs.WaveCyclesLocal():F2}（期望 1.00）");
        Check("余弦：u=0 在峰顶、u=0.25 到中线、u=0.5 到谷底（±0.5）",
              Near(cs.WavePointAt(0f).Y, 1400f, .5f) && Near(cs.WavePointAt(0.25f).Y, 1500f, .5f)
              && Near(cs.WavePointAt(0.5f).Y, 1600f, .5f),
              $"0:{cs.WavePointAt(0f).Y:F1} 1/4:{cs.WavePointAt(0.25f).Y:F1} 1/2:{cs.WavePointAt(0.5f).Y:F1}");
        var csBox = cs.CurveBoxLocal();
        Check("余弦：紧框 = 一个周期宽 × (起点 → 谷底 2A)（±0.5）",
              Near(csBox.MinX, 300f, .5f) && Near(csBox.MaxX, 780f, .5f)
              && Near(csBox.MinY, 1400f, .5f) && Near(csBox.MaxY, 1600f, .5f),
              $"框 ({csBox.MinX:F1},{csBox.MinY:F1})..({csBox.MaxX:F1},{csBox.MaxY:F1})");

        // ---- 波浪线（2026-09-20 第十六批，用户："还有一个另外的很多周期的波浪的弦函数线"）----
        // 和正弦是**同一条曲线**，差别只在**这一拖管什么**：正弦的框宽 = 一个周期、
        // 波浪线的框宽 = **要画多长**（周期由振幅定：**`T = 1 × A`** —— 用户 2026-09-20 定的
        // "振幅 = 一个周期"，见 WavePeriodPerAmplitude）。
        // 所以下面这几条就是**"多周期"这件事的正面断言**：
        //   · 拖得宽 → 周期数跟着涨，而 **T 和 A 一个字不变**（波形不会被拉变形）；
        //   · 拖得不足一个周期 → 紧框跟着收（峰还没到，不能撑到 ±A）。
        var wv = NewCurve(Tool.Wave, StrokeKind.Wave, 300f, 1000f);
        wv.SetWaveBox(300f, 1000f, 600f, 900f, minAxis);          // 300 宽、A = 100
        Check("波浪线：A = 100、**T = 1×A = 100**、画 300 宽 → 3 个整周期（±0.5）",
              Near(wv.WaveAmplitudeLocal(), 100f, .5f)
              && Near(wv.WavePeriodLocal(), 100f, .5f)
              && Near(wv.WaveLengthLocal(), 300f, .5f)
              && Near(wv.WaveCyclesLocal(), 3f, .02f),
              $"A {wv.WaveAmplitudeLocal():F1}  T {wv.WavePeriodLocal():F1}"
              + $"  长 {wv.WaveLengthLocal():F1}  周期数 {wv.WaveCyclesLocal():F2}（期望 3.00）");
        // **拖宽一倍**：周期数翻倍，而波形一个字不变（"画多长画多长"这件事的正面断言）。
        var wv2 = NewCurve(Tool.Wave, StrokeKind.Wave, 300f, 1000f);
        wv2.SetWaveBox(300f, 1000f, 900f, 900f, minAxis);        // 同样 A = 100、宽一倍（600）
        Check("波浪线：**同一个高度拖宽一倍（300 → 600）→ 周期数翻倍（3.0 → 6.0）**，"
              + "而 T 和 A 一个字没变（不变形）",
              Near(wv2.WaveCyclesLocal(), 6f, .02f)
              && Near(wv2.WaveAmplitudeLocal(), 100f, .5f)
              && Near(wv2.WavePeriodLocal(), 100f, .5f),
              $"A {wv2.WaveAmplitudeLocal():F1}  T {wv2.WavePeriodLocal():F1}"
              + $"  周期数 {wv2.WaveCyclesLocal():F2}（期望 6.00）");
        Check("波浪线：宽一倍的紧框 = 长度也翻倍、**上下两条线还是 ±A**（波形没被拉扁）",
              Near(wv2.CurveBoxLocal().MinX, 300f, .5f) && Near(wv2.CurveBoxLocal().MaxX, 900f, .5f)
              && Near(wv2.CurveBoxLocal().MinY, 900f, .5f) && Near(wv2.CurveBoxLocal().MaxY, 1100f, .5f),
              $"框 ({wv2.CurveBoxLocal().MinX:F1},{wv2.CurveBoxLocal().MinY:F1})"
              + $"..({wv2.CurveBoxLocal().MaxX:F1},{wv2.CurveBoxLocal().MaxY:F1})");
        // **拖得短**（不足一个周期）也要能画：那时紧框不该撑到 ±A（峰还没到）
        var wv3 = NewCurve(Tool.Wave, StrokeKind.Wave, 300f, 1000f);
        wv3.SetWaveBox(300f, 1000f, 320f, 900f, minAxis);         // 长 20、A = 100 → 0.2 个周期
        Check("波浪线：拖得**不足一个周期**时紧框跟着收（不撑到 ±A，峰根本还没到）（±0.5）",
              Near(wv3.WaveCyclesLocal(), 0.2f, .01f)
              && Near(wv3.CurveBoxLocal().MinY, 1000f - 100f * MathF.Sin(MathF.Tau * 0.2f), .5f)
              && wv3.CurveBoxLocal().MinY > 900.5f,
              $"周期数 {wv3.WaveCyclesLocal():F3}  框上沿 {wv3.CurveBoxLocal().MinY:F1}"
              + $"（期望 {1000f - 100f * MathF.Sin(MathF.Tau * 0.2f):F1}；"
              + "满峰才是 900 —— 这里峰还没到，框跟着收）");
        // 两种波浪**同一个框拖出来的东西不一样**（这是"分两格"的意义所在）：
        // 拿**同一个框**（正弦那一条：480 宽 × 100 高）比 —— 正弦是**一个周期**（T = 480）、
        // 波浪线是 **4.8 个周期**（T = 100 = A）。
        var wv4 = NewCurve(Tool.Wave, StrokeKind.Wave, 300f, 1000f);
        wv4.SetWaveBox(300f, 1000f, 780f, 900f, minAxis);         // 和上面 sn **一模一样的一拖**
        Check("正弦 / 波浪线**同一个框拖出来不是同一条**：T 480（一个周期）vs T 100（4.8 个周期）",
              Near(sn.WavePeriodLocal(), 480f, .5f) && Near(sn.WaveCyclesLocal(), 1f, .01f)
              && Near(wv4.WavePeriodLocal(), 100f, .5f) && Near(wv4.WaveCyclesLocal(), 4.8f, .02f),
              $"正弦 T {sn.WavePeriodLocal():F0}/周期数 {sn.WaveCyclesLocal():F2}、"
              + $"波浪线 T {wv4.WavePeriodLocal():F0}/周期数 {wv4.WaveCyclesLocal():F2}");

        // ---- 正切（2026-09-20 第十五批，用户："可以画正切"）----
        // 和正弦 / 余弦同族，但**一笔**：按下 = 原点（这一支的中心，也是图象与 x 轴的交点），
        // 拖出去 = **以它为中心的框**——横向 = 半支长（两条渐近线正好落在框的左右边）、
        // 纵向 = 可视半高（曲线冲到那儿就截断）。
        //
        // ⚠ 两条最要紧的：
        //   ① **它不该被拖变形**：横竖共用一个单位（`半支长 ↔ π/2`），所以框拖成什么形状，
        //      画出来的都是同一个正切（只是看得见的部分多少不同）；
        //   ② **可视半高有个下限**（`TangentMinAspect = 3`）：横竖既然同一个尺度，
        //      "看得见多高"就直接决定"两头离渐近线还有多远" —— 框太矮时曲线只画到一半就截断，
        //      看着是**一条斜线**（用户 2026-09-20 上手就是这个印象：他得故意拖得又高又窄才像）。
        //      所以引擎把高度顶到"贴着渐近线"的那个最小比例，**随手一拖就是课本的样子**。
        var tg = NewCurve(Tool.Tangent, StrokeKind.Tangent, 300f, 2400f);
        tg.SetTangentBox(300f, 2400f, 420f, 2540f, minAxis);      // 半支长 120、拖的半高只有 140
        Check("正切：两个定义元素（原点 ＋ 拖出去那个角），是**一笔**图形",
              tg.Points.Count == 2 && ShapeStepCount(Tool.Tangent) == 1,
              $"{tg.Points.Count} 个控制点、{ShapeStepCount(Tool.Tangent)} 笔"
              + "（期望 2 个 / 1 笔）");
        Check("正切：原点 = 按下点；半支长 120；可视半高**被顶到下限 360 = 3 × 120**（拖的是 140）（±0.5）",
              Near(tg.TangentOriginLocal().X, 300f, .5f) && Near(tg.TangentOriginLocal().Y, 2400f, .5f)
              && Near(tg.TangentHalfSpanLocal(), 120f, .5f)
              && Near(tg.TangentHalfHeightLocal(), 3f * 120f, .5f),
              $"原点 ({tg.TangentOriginLocal().X:F1},{tg.TangentOriginLocal().Y:F1})"
              + $"  半支长 {tg.TangentHalfSpanLocal():F1}  可视半高 {tg.TangentHalfHeightLocal():F1}"
              + $"（拖的 {MathF.Abs(tg.TangentEndLocal().Y - tg.TangentOriginLocal().Y):F1}）");
        // 单位 = 半支长 ÷ π/2 —— **这一条就是"横竖同一个尺度"的定义**（不变形的根）
        Check($"正切：横竖**共用一个单位**（半支长 120 ÷ π/2 ≈ {120f / (MathF.PI * .5f):F1}）（±0.5）",
              Near(tg.TangentUnitLocal(), 120f / (MathF.PI * 0.5f), .5f),
              $"{tg.TangentUnitLocal():F2}（期望 {120f / (MathF.PI * 0.5f):F2}）");
        Check("正切：θ=0 过原点、θ=π/4 降**一个单位**（tan 45° = 1）（±0.5）",
              Near(tg.TangentPointAtTheta(0f).X, 300f, .5f)
              && Near(tg.TangentPointAtTheta(0f).Y, 2400f, .5f)
              && Near(tg.TangentPointAtTheta(MathF.PI * .25f).Y, 2400f - tg.TangentUnitLocal(), .5f),
              $"θ=0 → ({tg.TangentPointAtTheta(0f).X:F1},{tg.TangentPointAtTheta(0f).Y:F1})"
              + $"  θ=π/4 → y {tg.TangentPointAtTheta(MathF.PI * .25f).Y:F1}"
              + $"（期望 {2400f - tg.TangentUnitLocal():F1}）");
        // 截断：曲线**冲到框的上下边就收笔**（框外的不画），所以首末两点的 y 正好是 ±半高
        Check("正切：一支的**首末两点正好落在框的上下边**（冲出框就截断）（±0.5）",
              Near(tg.TangentTracedPointAt(0f).Y, 2400f + 360f, .5f)
              && Near(tg.TangentTracedPointAt(1f).Y, 2400f - 360f, .5f)
              && tg.TangentTracedPointAt(0f).X < 300f && tg.TangentTracedPointAt(1f).X > 300f,
              $"端头 ({tg.TangentTracedPointAt(0f).X:F1},{tg.TangentTracedPointAt(0f).Y:F1})"
              + $" 和 ({tg.TangentTracedPointAt(1f).X:F1},{tg.TangentTracedPointAt(1f).Y:F1})");
        // **"贴着渐近线"的正面判据**：曲线两头停在离渐近线 13% 的地方（θ 走到 π/2 的 87%）
        // —— 这一条就是用户那句"很窄很高的时候才贴着渐近线"要做成默认行为的那件事。
        float tgGap = 1f - MathF.Abs(300f - tg.TangentTracedPointAt(1f).X) / tg.TangentHalfSpanLocal();
        Check("正切：两头**贴着渐近线**（只差 13% 的半支长；θ 走到 π/2 的 87%）（±0.02）",
              Near(tgGap, 0.133f, .02f)
              && Near(tg.TangentThetaMaxLocal() / (MathF.PI * .5f), 0.867f, .02f),
              $"离渐近线还差 {tgGap * 100f:F1}%（期望 13.3），"
              + $"θ 走到 π/2 的 {tg.TangentThetaMaxLocal() / (MathF.PI * .5f) * 100f:F1}%");
        // 两条渐近线：x = ±半支长（**正好落在框的左右边**）、上下从 −半高 到 ＋半高
        var (aFrom, aTo) = tg.TangentAsymptoteLocal(1);
        Check("正切：两条渐近线在 x = 原点 ± 半支长（就落在框的左右边上）（±0.5）",
              Near(tg.TangentAsymptoteLocal(-1).From.X, 180f, .5f)
              && Near(aFrom.X, 420f, .5f) && Near(aFrom.Y, 2400f - 360f, .5f)
              && Near(aTo.Y, 2400f + 360f, .5f),
              $"左 x {tg.TangentAsymptoteLocal(-1).From.X:F1}（期望 180）"
              + $"  右 x {aFrom.X:F1}（期望 420）  上下 {aFrom.Y:F1}..{aTo.Y:F1}（期望 2040..2760）");
        // 紧框 = **那个框本身**（不用采样求极值：曲线的范围就是 ±半支长 / ±半高）
        var tgBox = tg.CurveBoxLocal();
        Check("正切：紧框 = 那个框本身 (180,2040)..(420,2760)（±0.5）",
              Near(tgBox.MinX, 180f, .5f) && Near(tgBox.MaxX, 420f, .5f)
              && Near(tgBox.MinY, 2400f - 360f, .5f) && Near(tgBox.MaxY, 2400f + 360f, .5f),
              $"框 ({tgBox.MinX:F1},{tgBox.MinY:F1})..({tgBox.MaxX:F1},{tgBox.MaxY:F1})");
        // == 不变形：**同一个比例放大一倍** → 曲线逐点也放大一倍（形状一个字不变） ==
        // 这条比"看着像"硬得多：它证的是横竖**同一个**单位，也就是说
        // "框拖成什么形状都一样，画出来的还是那个正切"（少了这条，"拖宽就拉平"会溜过去）。
        var tg2 = NewCurve(Tool.Tangent, StrokeKind.Tangent, 300f, 2400f);
        tg2.SetTangentBox(300f, 2400f, 300f + 240f, 2400f + 280f, minAxis);   // 比例相同、放大一倍
        bool tgScaleOk = true; string tgScaleNote = "";
        for (int i = 0; i <= 4; i++)
        {
            float t = i / 4f;
            var pa = tg.TangentTracedPointAt(t);
            var pb = tg2.TangentTracedPointAt(t);
            if (!Near(pb.X - 300f, (pa.X - 300f) * 2f, .5f)
                || !Near(pb.Y - 2400f, (pa.Y - 2400f) * 2f, .5f))
            {
                tgScaleOk = false;
                tgScaleNote = $"t={t:F2}：(相对原点) ({pa.X - 300f:F1},{pa.Y - 2400f:F1})"
                            + $" → ({pb.X - 300f:F1},{pb.Y - 2400f:F1})（期望 ×2）";
                break;
            }
        }
        Check("正切：框**按同一比例放大一倍** → 曲线逐点放大一倍（拖不变形）", tgScaleOk,
              tgScaleOk ? "5 个采样点全是 ×2（形状一个字没变）" : tgScaleNote);
        // 拖得**又宽又矮**（480 × 70）：高度照样被顶到 3 倍下限，于是画出来的还是
        // "贴着渐近线的那一支"——**这就是这条下限存在的理由**（不然它是一条斜线）。
        // 注意 θ 的上限和半支长**无关**（`tan θmax = 3·π/2`），所以它和 tg 走到同一个 θ。
        var tg3 = NewCurve(Tool.Tangent, StrokeKind.Tangent, 300f, 2400f);
        tg3.SetTangentBox(300f, 2400f, 300f + 480f, 2400f + 70f, minAxis);   // 又宽又矮
        Check("正切：**又宽又矮**的框也被顶到同一条下限（θ 上限和 tg 一样、不走成斜线）",
              Near(tg3.CurveBoxLocal().MaxX - tg3.TangentOriginLocal().X, 480f, .5f)
              && Near(tg3.TangentHalfHeightLocal(), 3f * 480f, .5f)
              && Near(tg3.TangentThetaMaxLocal(), tg.TangentThetaMaxLocal(), .01f)
              && tg3.TangentThetaMaxLocal() < MathF.PI * .5f,
              $"半支长 480、拖的半高 70 → 实际半高 {tg3.TangentHalfHeightLocal():F0}、"
              + $"θ 上限 {tg3.TangentThetaMaxLocal():F3}（tg 是 {tg.TangentThetaMaxLocal():F3}）");
        // 反过来说：**拖得比下限更高就照你的来**（越高血压到越近）。
        var tg4 = NewCurve(Tool.Tangent, StrokeKind.Tangent, 300f, 2400f);
        tg4.SetTangentBox(300f, 2400f, 300f + 120f, 2400f + 700f, minAxis);   // 半支长 120、半高 700
        Check("正切：拖得**比下限更高**就照你的来（半高 700 > 360 → θ 上限更大、贴得更近）",
              Near(tg4.TangentHalfHeightLocal(), 700f, .5f)
              && tg4.TangentThetaMaxLocal() > tg.TangentThetaMaxLocal() + 0.05f,
              $"半支长 120、拖的半高 700 → θ 上限 {tg4.TangentThetaMaxLocal():F3} rad"
              + $"（下限那一档是 {tg.TangentThetaMaxLocal():F3}，π/2 是 {MathF.PI * .5f:F3}）");

        // ---- 圆柱 / 圆锥（2026-09-20 第五批：照 InkClass 的 case 6/7）----
        // 两个控制点就是**外接矩形**（拖到哪就是哪），椭圆由它派生：
        // `rx = 宽/2 = 200`、`ry = rx / 2.646 ≈ 75.59`。
        // 圆心从矩形上下边**往里缩一个 ry**，于是椭圆正好与矩形相切（范围好算、紧框不漏）。
        var cy = NewCurve(Tool.Cylinder, StrokeKind.Cylinder, 200f, 500f);
        cy.SetSolidBox(200f, 500f, 600f, 900f);
        var (ccx, cTop, cBot, crx, cry) = cy.SolidEllipsesLocal();
        Check("圆柱：外接矩形 = 拖出来的那个（200,500)..(600,900)（±0.5）",
              Near(cy.SolidRectLocal().X0, 200f, .5f) && Near(cy.SolidRectLocal().Y1, 900f, .5f),
              $"({cy.SolidRectLocal().X0:F0},{cy.SolidRectLocal().Y0:F0})"
              + $"..({cy.SolidRectLocal().X1:F0},{cy.SolidRectLocal().Y1:F0})");
        // 期望值**读引擎那个常量**，不在这里再抄一遍 2.646——写死的常数会随它改而静默失效
        //（仓库里为这类事栽过，见 计划-图形工具.md 的教训那几条）。
        Check($"圆柱：rx = 200、ry = rx × 扁率 ≈ {200f * Stroke.SolidEllipseRatio:F1}（照他的常数）（±0.5）",
              Near(crx, 200f, .5f) && Near(cry, 200f * Stroke.SolidEllipseRatio, .5f),
              $"rx {crx:F1}  ry {cry:F1}（期望 200 / {200f * Stroke.SolidEllipseRatio:F1}）");
        Check("圆柱：上下两个圆心从矩形边**往里缩一个 ry**（相切，不冒出去）（±0.5）",
              Near(ccx, 400f, .5f) && Near(cTop, 500f + cry, .5f) && Near(cBot, 900f - cry, .5f),
              $"cx {ccx:F1}  上圆心 y {cTop:F1}（期望 {500f + cry:F1}）"
              + $"  下圆心 y {cBot:F1}（期望 {900f - cry:F1}）");
        Check("圆柱：紧框 = 外接矩形本身（控制点外接就够，椭圆不会冒出去）（±0.5）",
              Near(cy.Bounds.MinX, 200f, .5f) && Near(cy.Bounds.MaxX, 600f, .5f)
              && Near(cy.Bounds.MinY, 500f, .5f) && Near(cy.Bounds.MaxY, 900f, .5f),
              $"框 ({cy.Bounds.MinX:F0},{cy.Bounds.MinY:F0})..({cy.Bounds.MaxX:F0},{cy.Bounds.MaxY:F0})");
        // 轮廓的**分段结构**：底面一圈 / 顶面一圈 / 两条母线（2026-09-20 补了母线——
        // 橡皮的粗筛按这份轮廓判"够不够得着"，少了母线就"明明画着线却擦不掉"）。
        var cyParts = Stroke.SplitOutlineParts(cy.ShapeOutline());
        Check("圆柱：轮廓分成 4 段（底圈 / 顶圈 / 两条母线），段与段之间靠抬笔标记隔开",
              cyParts.Count == 4 && cyParts[1].Count > 8 && cyParts[2].Count == 2 && cyParts[3].Count == 2,
              $"{cyParts.Count} 段，点数 {string.Join("/", cyParts.ConvertAll(p => p.Count))}"
              + "（期望 4 段：圈/圈/2/2）");

        var co = NewCurve(Tool.Cone, StrokeKind.Cone, 200f, 500f);
        co.SetSolidBox(200f, 500f, 600f, 900f);
        Check("圆锥：顶点 = 外接矩形的**上边中点** (400, 500)（照 InkClass）（±0.5）",
              Near(co.ConeApexLocal().X, 400f, .5f) && Near(co.ConeApexLocal().Y, 500f, .5f),
              $"({co.ConeApexLocal().X:F0},{co.ConeApexLocal().Y:F0}) 期望 (400,500)");

        // ---- 圆台（2026-09-20 第十三批，用户："再加一个圆台"）----
        // 它和圆柱 / 圆锥**共用同一份画法**（`Stroke.SolidPieces`：上底整圈 ＋ 下底下半圈 ＋
        // 两条母线，被挡的是下底上半圈），差别只在**上底小一圈**。所以这一节只钉那一点：
        // 上底的比例 / 相切、母线**往中间收**、轮廓还是 4 段。
        var cf = NewCurve(Tool.ConeFrustum, StrokeKind.ConeFrustum, 200f, 500f);
        cf.SetSolidBox(200f, 500f, 600f, 900f);
        var (fTop, frx, fry) = cf.ConeFrustumTopLocal();
        float fk = ShapeSpec.FrustumTopScale;
        Check($"圆台：上底 = 下底**同形缩 {fk:F2}**（两个半轴都乘，和棱台同一个数）（±0.5）",
              Near(frx, crx * fk, .5f) && Near(fry, cry * fk, .5f),
              $"上底 ({frx:F1}, {fry:F1})（期望 ({crx * fk:F1}, {cry * fk:F1})）");
        Check("圆台：上底与矩形上边**相切**（圆心往里缩的是 ry×比例，不是 ry）（±0.5）",
              Near(fTop.Y - fry, 500f, .5f),
              $"上底上沿 {fTop.Y - fry:F1}（期望 500 = 矩形上边）");
        var cfParts = Stroke.SplitOutlineParts(cf.ShapeOutline());
        Check("圆台：轮廓分 4 段（下底圈 / 上底圈 / 两条母线）——和圆柱同一个结构",
              cfParts.Count == 4 && cfParts[1].Count > 8 && cfParts[2].Count == 2 && cfParts[3].Count == 2,
              $"{cfParts.Count} 段，点数 {string.Join("/", cfParts.ConvertAll(p => p.Count))}"
              + "（期望 4 段：圈/圈/2/2）");
        // 母线**不是竖的**（是竖的就成圆柱了）；而且上端**正好落在上底左右端点**。
        Check("圆台：两条母线**往中间收**，上端落在上底左右端点（不是竖直的）",
              cfParts.Count == 4
              && Near(cfParts[2][0].X, 200f, .5f) && Near(cfParts[2][1].X, fTop.X - frx, .5f)
              && Near(cfParts[3][0].X, 600f, .5f) && Near(cfParts[3][1].X, fTop.X + frx, .5f)
              && cfParts[2][1].X > cfParts[2][0].X && cfParts[3][1].X < cfParts[3][0].X,
              cfParts.Count == 4
                  ? $"左 {cfParts[2][0].X:F0}→{cfParts[2][1].X:F0}、右 {cfParts[3][0].X:F0}→{cfParts[3][1].X:F0}"
                    + $"（期望 200→{fTop.X - frx:F0}、600→{fTop.X + frx:F0}）"
                  : "（轮廓没分成 4 段）");
        Check("圆台：紧框 = 外接矩形本身（上底缩小后不会冒出去）（±0.5）",
              Near(cf.Bounds.MinX, 200f, .5f) && Near(cf.Bounds.MaxX, 600f, .5f)
              && Near(cf.Bounds.MinY, 500f, .5f) && Near(cf.Bounds.MaxY, 900f, .5f),
              $"框 ({cf.Bounds.MinX:F0},{cf.Bounds.MinY:F0})..({cf.Bounds.MaxX:F0},{cf.Bounds.MaxY:F0})");

        // ---- 球（2026-09-20 第十四批，用户："在加入球"）----
        // 它有三件事和别的立体不同，都得钉住（不然"球"会退化成"圆"）：
        //   ① 投影永远是**圆**（取矩形里内切的圆，拖长了也不许画成扁球）；
        //   ② 必须画**赤道**那个椭圆（否则和「圆」那一格长得一样，看不出是个球）；
        //   ③ 赤道的近侧（下半圈）实线、远侧（上半圈）虚线。
        // 特意用**长方形** 400×200 来拖（不是正方形）：这样"内切正圆"这条才会真的被验到。
        var sp = NewCurve(Tool.Sphere, StrokeKind.Sphere, 200f, 500f);
        sp.SetSolidBox(200f, 500f, 600f, 700f);                      // 400×200
        var (spC, spR) = sp.SphereLocal();
        var (spEqC, spEqRx, spEqRy) = sp.SphereEquatorLocal();
        Check("球：投影是**内切正圆**——半径 = min(半宽, 半高) = 100（不是 200）、圆心 = 矩形中心（±0.5）",
              Near(spR, 100f, .5f) && Near(spC.X, 400f, .5f) && Near(spC.Y, 600f, .5f),
              $"半径 {spR:F1}（期望 100）、圆心 ({spC.X:F0},{spC.Y:F0})（期望 (400,600)）");
        Check("球：赤道椭圆 —— 长半轴 = 半径、圆心 = 球心、短半轴 = 半径 × 那个俯角（±0.5）",
              Near(spEqRx, spR, .5f) && Near(spEqRy, spR * Stroke.SolidEllipseRatio, .5f)
              && Near(spEqC.X, spC.X, .5f) && Near(spEqC.Y, spC.Y, .5f),
              $"赤道 ({spEqRx:F1}, {spEqRy:F1})（期望 ({spR:F1}, {spR * Stroke.SolidEllipseRatio:F1})），"
              + $"圆心 ({spEqC.X:F0},{spEqC.Y:F0})");
        Check("球：赤道**不是正圆**（短半轴 < 长半轴 —— 那个「从上往下看」的俯角）",
              spEqRy < spEqRx - 1f, $"短半轴 {spEqRy:F1} vs 长半轴 {spEqRx:F1}");
        var spParts = Stroke.SplitOutlineParts(sp.ShapeOutline());
        Check("球：轮廓分 2 段（外圈 / 赤道圈）——赤道的上下两半都要列进来（橡皮得够得着）",
              spParts.Count == 2 && spParts[0].Count > 8 && spParts[1].Count > 8,
              $"{spParts.Count} 段，点数 {string.Join("/", spParts.ConvertAll(p => p.Count))}"
              + "（期望 2 段：圈/圈）");
        Check("球：紧框 = **那个圆的外接方形**（圆心 ± 半径），不是拖出来的 400×200 矩形（±0.5）",
              Near(sp.Bounds.MinX, 300f, .5f) && Near(sp.Bounds.MaxX, 500f, .5f)
              && Near(sp.Bounds.MinY, 500f, .5f) && Near(sp.Bounds.MaxY, 700f, .5f),
              $"框 ({sp.Bounds.MinX:F0},{sp.Bounds.MinY:F0})..({sp.Bounds.MaxX:F0},{sp.Bounds.MaxY:F0})"
              + "（期望 (300,500)..(500,700)）");
        // 墨迹框（脏区/命中用）必须跟着**真实几何**走，不能是外接矩形——
        // 这和棱柱那次的"外接矩形上面漏一块"是同一类毛病，只是方向相反（这里是虚胖）。
        Check("球：墨迹框也按真实几何算（= 圆的外接方形 ＋ 半个笔宽，不是矩形 ＋ 半个笔宽）",
              Near(sp.WorldInkBounds.MaxY - sp.WorldInkBounds.MinY,
                   (500f - 300f) + sp.Width, 1.5f),
              $"墨迹框高 {sp.WorldInkBounds.MaxY - sp.WorldInkBounds.MinY:F1}"
              + $"（期望 {(500f - 300f) + sp.Width:F1} = 200 + 笔宽 {sp.Width:F1}）");

        // ---- 长方体 / 四面体（2026-09-20 第五批：照 InkClass 的 case 9/26，**两笔**）----
        // 长方体：第 1 笔正面矩形 (200,500)..(600,900)，第 2 笔拖到 y=650 → 深度 d = |500 − 650| = 150。
        var cu = NewCurve(Tool.Cuboid, StrokeKind.Cuboid, 200f, 500f);
        cu.SetCuboidFront(200f, 500f, 600f, 900f);
        cu.SetCuboidDepth(500f, 650f);
        Check("长方体：深度 = |正面上边 − 指针 y| = 150（照他的口径）（±0.5）",
              Near(cu.CuboidDepthLocal(), 150f, .5f), $"{cu.CuboidDepthLocal():F1}（期望 150）");
        Check("长方体：第 3 个控制点 = **背面右下角** (600+150, 900−150) = (750, 750)（±0.5）",
              Near(cu.CurvePointLocal(2).X, 750f, .5f) && Near(cu.CurvePointLocal(2).Y, 750f, .5f),
              $"({cu.CurvePointLocal(2).X:F0},{cu.CurvePointLocal(2).Y:F0}) 期望 (750,750)");
        Check("长方体：三个控制点（正面两角 ＋ 背面右下角）—— 多笔状态机要它凑齐才算画完",
              cu.Points.Count == 3 && Stroke.MinCurvePoints(StrokeKind.Cuboid) == 3,
              $"控制点 {cu.Points.Count} 个、MinCurvePoints = {Stroke.MinCurvePoints(StrokeKind.Cuboid)}");
        Check("长方体：紧框 = 正面 ∪ 背面（控制点外接正好就是画出来的范围）（±0.5）",
              Near(cu.Bounds.MinX, 200f, .5f) && Near(cu.Bounds.MaxX, 750f, .5f)
              && Near(cu.Bounds.MinY, 350f, .5f) && Near(cu.Bounds.MaxY, 900f, .5f),
              $"框 ({cu.Bounds.MinX:F0},{cu.Bounds.MinY:F0})..({cu.Bounds.MaxX:F0},{cu.Bounds.MaxY:F0})"
              + " 期望 (200,350)..(750,900)");

        // 四面体：第 1 笔外接矩形 (200,500)..(600,900) → 底面三角形（底边在下、顶点居中在上），
        // 第 2 笔拖到 (300, 200) = 顶点。
        var te = NewCurve(Tool.Tetrahedron, StrokeKind.Tetrahedron, 200f, 500f);
        te.SetTetraBase(200f, 500f, 600f, 900f);
        te.SetTetraApex(300f, 200f);
        Check("四面体：底面三角形 = 底左(200,900) / 底右(600,900) / 底顶(400,500)（照他）（±0.5）",
              Near(te.CurvePointLocal(0).X, 200f, .5f) && Near(te.CurvePointLocal(0).Y, 900f, .5f)
              && Near(te.CurvePointLocal(1).X, 600f, .5f) && Near(te.CurvePointLocal(1).Y, 900f, .5f)
              && Near(te.CurvePointLocal(2).X, 400f, .5f) && Near(te.CurvePointLocal(2).Y, 500f, .5f),
              $"({te.CurvePointLocal(0).X:F0},{te.CurvePointLocal(0).Y:F0}) / "
              + $"({te.CurvePointLocal(1).X:F0},{te.CurvePointLocal(1).Y:F0}) / "
              + $"({te.CurvePointLocal(2).X:F0},{te.CurvePointLocal(2).Y:F0})");
        Check("四面体：顶点 = 第 2 笔拖到的地方 (300, 200)（±0.5）",
              Near(te.TetraApexLocal().X, 300f, .5f) && Near(te.TetraApexLocal().Y, 200f, .5f),
              $"({te.TetraApexLocal().X:F0},{te.TetraApexLocal().Y:F0}) 期望 (300,200)");
        Check("四面体：四个控制点 ＋ 轮廓 = 六条棱（各段之间抬笔，不连出假线）",
              te.Points.Count == 4 && Stroke.MinCurvePoints(StrokeKind.Tetrahedron) == 4
              && te.ShapeOutline().Count == 6 * 2 + 5,
              $"控制点 {te.Points.Count} 个；轮廓 {te.ShapeOutline().Count} 点"
              + $"（6 段 × 2 点 ＋ 5 个抬笔 = 17）");

        // ================= ③ 手柄：四种曲线走**常规操作**（2026-09-20 第五批）========
        // 用户："抛物线、双曲线、正弦、余弦，把特殊点砍掉；通通按常规操作 ——
        //       给操作柄和旋转，和正常的一样。"
        Span<ShapeHandle> hs = stackalloc ShapeHandle[5];
        int nPb = SelectionHandles.ShapeHandlesOf(vb, hs);
        int nHy = SelectionHandles.ShapeHandlesOf(hy, hs);
        int nSn = SelectionHandles.ShapeHandlesOf(sn, hs);
        int nCs = SelectionHandles.ShapeHandlesOf(cs, hs);
        Check("手柄：四种曲线**一个特殊点都不给**（和矩形 / 立体图形一样，走通用框）",
              nPb == 0 && nHy == 0 && nSn == 0 && nCs == 0,
              $"抛物线 {nPb}、双曲线 {nHy}、正弦 {nSn}、余弦 {nCs}（都该是 0）");
        Check("手柄：四种曲线**都给旋转柄**（＝常规操作：缩放 ＋ 旋转 ＋ 平移）",
              SelectionHandles.RotateHandleVisible(vb) && SelectionHandles.RotateHandleVisible(hy)
              && SelectionHandles.RotateHandleVisible(sn) && SelectionHandles.RotateHandleVisible(cs),
              "抛物线 / 双曲线 / 正弦 / 余弦 都有旋转柄");
        Check("手柄：曲线仍然是**图形**（选中 / 移动 / 存档都走图形那一套）",
              Stroke.IsShapeKind(vb.Kind) && Stroke.IsShapeKind(hy.Kind)
              && Stroke.IsShapeKind(sn.Kind) && Stroke.IsShapeKind(cs.Kind),
              "四种曲线都在 IsShapeKind 里");

        // **通用八手柄真的给到了**（用户 2026-09-20 问"没有特殊点的图形……那八个是不是应该都给"）。
        //
        // 修的是一处**两头空**：Overlay 和 HitTest 原来都判"**是不是图形**"（`ShapeEditable`），
        // 而四种曲线 / 四个立体图形**是图形但没有特殊点** —— 于是既画不出特殊手柄、
        // 又拿不到通用八手柄，**画不出来也点不中**（真机上就只能整体拖，拉不动大小）。
        // 判据换成"**有没有特殊手柄**"之后，它们和矩形走同一条路。
        //
        // 这里对八个对象各点一次"框的右下角"：**点得中**才算给了（画的那一半靠出图看，
        // 拖的那一半由下面 ④ 验——那边还要求框**真的被拉大**，不然"整体挪一下"也能骗过去）。
        {
            var noSpecial = new (Stroke st, string name)[]
            {
                (vb, "抛物线"), (hy, "双曲线"), (sn, "正弦"), (cs, "余弦"),
                (cy, "圆柱"), (co, "圆锥"), (cf, "圆台"), (sp, "球"),
                (cu, "长方体"), (te, "四面体"),
            };
            int hitOk = 0;
            var missed = new List<string>();
            foreach (var (st, nm) in noSpecial)
            {
                var one = new[] { st };
                var f2 = SelectionHandles.FrameOf(one);
                var c2 = SelectionHandles.CanvasPosition(SelHandle.BottomRight, f2, DpiScale);
                if (SelectionHandles.HitTest(c2.X, c2.Y, one, f2, DpiScale) == SelHandle.BottomRight)
                    hitOk++;
                else missed.Add(nm);
            }
            Check("手柄：四种曲线 ＋ 六个立体图形**都点得中通用框的角**（＝八个缩放柄真的给了）",
                  hitOk == noSpecial.Length,
                  $"点得中 {hitOk}/{noSpecial.Length}"
                  + (missed.Count > 0 ? $"，点不中：{string.Join("/", missed)}" : ""));
        }

        // ================= ④ 编辑：曲线走**通用框**（只动变换，不动几何）=================
        // 曲线不再有"拖这个点只改那个量"的入口——模型层那几个函数（SetParabola… /
        // SetHyperbola… / SetWave…）只在**画的时候**用一次（见 §19、§22）。
        // 这里钉住通用框那条路：拖角只改 `Transform`，**局部几何一个点都不动**，
        // 朝向 / p 这些"曲线自己的参数"也一个字不动（这正是"线宽不变"那条路的前提，
        // 见 Stroke.KeepsWidth）。
        Doc.Clear();
        Doc.AddStroke(vb);
        Doc.ClearHistory();
        Doc.SelectOnly(new[] { vb });
        var pbP0 = new Vector2(vb.Points[0].X, vb.Points[0].Y);
        var pbP1 = new Vector2(vb.Points[1].X, vb.Points[1].Y);
        float pbPBefore = vb.ParabolaPLocal();
        var pbAxisBefore = vb.EffectiveAxis;
        var vbFrame = SelectionHandles.FrameOf(Doc.Selected);
        var vbCorner = SelectionHandles.CanvasPosition(SelHandle.BottomRight, vbFrame, DpiScale);
        float vbW0 = vbFrame.CanvasAabb.MaxX - vbFrame.CanvasAabb.MinX;
        float vbH0 = vbFrame.CanvasAabb.MaxY - vbFrame.CanvasAabb.MinY;
        // 先确认"按的是**手柄**，不是框内的空白"——不确认的话，按下会被当成"整体拖动"，
        // 下面那条 `!Transform.IsIdentity` 照样成立（整体挪一下也改变换），**断言等于白写**：
        // 这正是这一条原来漏掉的那半（用户 2026-09-20 问出来的那件事）。
        Check("曲线拖通用框的角：按下去命中**右下角手柄**（不是框内空白 → 不是整体拖动）",
              SelectionHandles.HitTest(vbCorner.X, vbCorner.Y, Doc.Selected, vbFrame, DpiScale)
                  == SelHandle.BottomRight,
              $"{SelectionHandles.HitTest(vbCorner.X, vbCorner.Y, Doc.Selected, vbFrame, DpiScale)}"
              + "（期望 BottomRight）");
        bool vbTook = SelectionGestureForTest(vbCorner.X, vbCorner.Y);
        UpdateSelectionGestureForTest(vbCorner.X + 200f, vbCorner.Y + 120f);
        SettleFrames(40);
        EndSelectionGestureForTest();
        SettleFrames(60);
        Check("曲线拖通用框的角：**只改 Transform，几何点一个都没动**",
              vbTook && !vb.Transform.IsIdentity
              && vb.Points[0].X == pbP0.X && vb.Points[0].Y == pbP0.Y
              && vb.Points[1].X == pbP1.X && vb.Points[1].Y == pbP1.Y,
              $"接住={vbTook}，变换={(vb.Transform.IsIdentity ? "单位（没动）" : "变了")}，"
              + $"两个控制点 {(vb.Points[0].X == pbP0.X && vb.Points[0].Y == pbP0.Y ? "原样" : "被改了！")}");
        // **框真的被拉大了**才算"八个缩放柄能用"：往右下角拖 200×120，
        // 框的宽高该跟着长——"整体挪一下"改的是位置、宽高一点不变，这一条能把它筛掉。
        var vbFrameAfter = SelectionHandles.FrameOf(Doc.Selected);
        float vbW1 = vbFrameAfter.CanvasAabb.MaxX - vbFrameAfter.CanvasAabb.MinX;
        float vbH1 = vbFrameAfter.CanvasAabb.MaxY - vbFrameAfter.CanvasAabb.MinY;
        Check("曲线拖通用框的角：框**真的被拉大了**（不是整体挪了一下）",
              vbW1 > vbW0 + 40f && vbH1 > vbH0 + 20f,
              $"框 {vbW0:F0}×{vbH0:F0} → {vbW1:F0}×{vbH1:F0}");
        Check("曲线拖通用框的角：**朝向 与 p 都不受影响**（它们是曲线自己的参数）",
              vb.EffectiveAxis == pbAxisBefore && Near(vb.ParabolaPLocal(), pbPBefore, .01f),
              $"{vb.EffectiveAxis}，p {vb.ParabolaPLocal():F1}（拖之前 {pbPBefore:F1}）");
        Doc.SelectOnly(Array.Empty<Stroke>());

        // ④b **四边中点也要能拉伸**（用户 2026-09-20："那八个点出现了，但是我看着只有对角线
        //     能拖动放缩？我觉得左右拉伸也可以给"）。
        //
        // 根因：`Top / Bottom / Left / Right` 这四个名字是**两用**的——对椭圆 / 坐标系 / 数轴
        // 它们是"定义元素"，对没有定义元素手柄的对象它们就是通用框的**四边中点缩放柄**。
        // 手势分流那里原来无条件把它们抹成 `None`，于是那类对象"四角能拉、四边中点只能整体拖"。
        // 这里拖**右边中点**：宽该变大、**高一个点不该变**（整体拖动是宽高都不变，
        // 等比缩放是宽高一起变——两头都能把"其实没在缩放"筛出来）。
        Doc.SelectOnly(new[] { vb });        // ④ 尾巴上把选择清空了，框要从"选中它"重新算
        var vbF2 = SelectionHandles.FrameOf(Doc.Selected);
        float vbW2a = vbF2.CanvasAabb.MaxX - vbF2.CanvasAabb.MinX;
        float vbH2a = vbF2.CanvasAabb.MaxY - vbF2.CanvasAabb.MinY;
        var vbMid = SelectionHandles.CanvasPosition(SelHandle.Right, vbF2, DpiScale);
        Check("曲线拖通用框：**右边中点**按下去命中的是缩放柄（不是框内空白）",
              SelectionHandles.HitTest(vbMid.X, vbMid.Y, Doc.Selected, vbF2, DpiScale) == SelHandle.Right,
              $"{SelectionHandles.HitTest(vbMid.X, vbMid.Y, Doc.Selected, vbF2, DpiScale)}（期望 Right）");
        bool vbTookMid = SelectionGestureForTest(vbMid.X, vbMid.Y);
        UpdateSelectionGestureForTest(vbMid.X + 200f, vbMid.Y);
        SettleFrames(40);
        EndSelectionGestureForTest();
        SettleFrames(60);
        var vbF3 = SelectionHandles.FrameOf(Doc.Selected);
        float vbW2b = vbF3.CanvasAabb.MaxX - vbF3.CanvasAabb.MinX;
        float vbH2b = vbF3.CanvasAabb.MaxY - vbF3.CanvasAabb.MinY;
        Check("曲线拖通用框的**右边中点**：横向拉长（宽变大、高基本不变）",
              vbTookMid && MathF.Abs(vbW2b - (vbW2a + 200f)) < 6f && MathF.Abs(vbH2b - vbH2a) < 2f,
              $"接住={vbTookMid}，框 {vbW2a:F0}×{vbH2a:F0} → {vbW2b:F0}×{vbH2b:F0}"
              + $"（期望 宽 {(vbW2a + 200f):F0}、高 {vbH2a:F0}）");
        // 判据自洽：**有**定义元素手柄的（直线）为真、**没有**的（曲线 / 立体图形 / 矩形）为假。
        // 三处调用点（Overlay 画手柄、HitTest 命中、手势分流认不认四边中点）问的都是它，
        // 所以它错了就是三处一起错——一条断言盯住三种成分。
        var vbLine = new Stroke { Tool = Tool.Line, Kind = StrokeKind.Line };
        vbLine.AddPoint(0f, 0f, 1f, 0);
        vbLine.AddPoint(10f, 0f, 1f, 0);
        var vbRect = new Stroke { Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle };
        vbRect.AddPoint(0f, 0f, 1f, 0);
        vbRect.AddPoint(10f, 10f, 1f, 0);
        Check("判据自洽：HasShapeHandles —— 直线 true，曲线 / 立体图形 / 矩形 false",
              SelectionHandles.HasShapeHandles(vbLine)
              && !SelectionHandles.HasShapeHandles(vb)
              && !SelectionHandles.HasShapeHandles(cy)
              && !SelectionHandles.HasShapeHandles(cu)
              && !SelectionHandles.HasShapeHandles(vbRect),
              "直线该 true；四种曲线 / 立体图形 / 矩形都该 false");
        Doc.SelectOnly(Array.Empty<Stroke>());

        // ⑤ 朝向：**选出来的**（不再靠拖动角度推）
        //
        // 这是 2026-09-20 这一版的核心改动：方向从"拖出来的"变成"选出来的"，
        // 于是"方向"和"大小"两个参数彻底分开、各管各的——用户的原话是
        // "开口的 4 种还要同时兼顾大小，这两个参数很不好调整"。
        Doc.Clear();
        var pb2 = NewCurve(Tool.Parabola, StrokeKind.Parabola, 500f, 500f);
        pb2.CurveAxis = CurveAxis.OpenUp;                        // 选：开口向上
        pb2.SetParabolaVertex(500f, 500f);
        pb2.SetParabolaThroughPoint(500f + 240f, 500f - 120f);   // s = 120、t = 240 → p = 240
        Doc.AddStroke(pb2);
        Doc.ClearHistory();
        Doc.SelectOnly(new[] { pb2 });
        Check("朝向：选「开口向上」→ 方向 = (0,−1)；p 由经过点反解 = 240（±1）",
              NearDir(pb2.ParabolaDirLocal(), new Vector2(0f, -1f)) && Near(pb2.ParabolaPLocal(), 240f, 1f),
              $"{pb2.ParabolaDirLocal()}，p {pb2.ParabolaPLocal():F0}");

        // 四个朝向各来一次：方向对得上，而且 **p 一点不变**（换朝向只转方向、不改形状——
        // 实现上是把"经过点"的 (s, t) 分量跟着新基重组，见 Stroke.SetParabolaAxis）。
        var axisCases = new (CurveAxis axis, Vector2 dir)[]
        {
            (CurveAxis.OpenUp, new Vector2(0f, -1f)),
            (CurveAxis.OpenDown, new Vector2(0f, 1f)),
            (CurveAxis.OpenRight, new Vector2(1f, 0f)),
            (CurveAxis.OpenLeft, new Vector2(-1f, 0f)),
        };
        bool axisOk = true, pKept = true;
        foreach (var (ax, dir) in axisCases)
        {
            pb2.SetParabolaAxis(ax);
            if (!NearDir(pb2.ParabolaDirLocal(), dir)) axisOk = false;
            if (!Near(pb2.ParabolaPLocal(), 240f, .5f)) pKept = false;
        }
        Check("朝向：四个方向切一圈 —— 方向都对得上，**p 始终是 240**（换朝向曲线不瘪）",
              axisOk && pKept, $"最后 {pb2.ParabolaDirLocal()}，p {pb2.ParabolaPLocal():F1}");
        // 坏值（比如读到别的族的值）要被归一成"开口向上"，不能带着它去算几何。
        // **在独立对象上试**：直接给 pb2 写个坏字段会把它的几何也带歪
        //（字段说"开口向上"、点位却是按旧朝向摆的），后面几条断言全跟着出错。
        var badAxis = NewCurve(Tool.Parabola, StrokeKind.Parabola, 2000f, 700f);
        badAxis.CurveAxis = CurveAxis.TransverseY;
        badAxis.SetParabolaVertex(2000f, 700f);
        Check("朝向：给到别的族的值 → 归一成**开口向上**（坏字节不许带进几何）",
              badAxis.EffectiveAxis == CurveAxis.OpenUp, $"{badAxis.EffectiveAxis}");
        pb2.SetParabolaAxis(CurveAxis.OpenUp);                   // 转回向上，下面接着用
        Check("朝向：转回向上之后仍然 p = 240（±0.5）",
              NearDir(pb2.ParabolaDirLocal(), new Vector2(0f, -1f)) && Near(pb2.ParabolaPLocal(), 240f, .5f),
              $"{pb2.ParabolaDirLocal()}，p {pb2.ParabolaPLocal():F1}");

        // 曲线参数由**画的那两笔**定，编辑时不再有"拖这个点"的入口（见 ③ / ④）。
        // 这里用一个**独立对象**直接调模型层那一份算式，验"经过点 → p 反解"这条口径没变
        //（画的时候用它，见 §19；拖手柄那条路已经删掉）——不碰 pb2，
        // 免得把下面"p 还是 240"那几条断言带歪。
        var pbParam = NewCurve(Tool.Parabola, StrokeKind.Parabola, 500f, 500f);
        pbParam.CurveAxis = CurveAxis.OpenUp;
        pbParam.SetParabolaVertex(500f, 500f);
        pbParam.SetParabolaThroughPoint(500f + 300f, 500f - 240f);   // s = 240、t = 300
        Check("参数：经过点 (300, −240) → p = t²/2s = 187.5（±2）",
              Near(pbParam.ParabolaPLocal(), 300f * 300f / 480f, 2f),
              $"p {pbParam.ParabolaPLocal():F1}（期望 {300f * 300f / 480f:F1}）");
        Check("参数：换经过点**不动朝向**（朝向是选出来的）",
              NearDir(pbParam.ParabolaDirLocal(), new Vector2(0f, -1f)), $"{pbParam.ParabolaDirLocal()}");

        // 换朝向这件事，2026-09-20 深夜**从操作条挪到了图形面板**（用户："选中框的抛物线按钮
        // 功能取消哦，我不打算从这个转抛物线开口"）：现在条上**没有「开口方向」这一格**，
        // 换朝向走的是 `Engine.CycleParabolaAxis`（画之前定，见 --shapebandtest 里那两条）。
        // ⚠ 数字 10 = 九格 ＋ **2026-09-22 加的第十格「图库」**（见 `SelBarButton` 和
        //   `BarButtonCount` 的注释）。这条早先写死 9，是那天之后**没跟着改**的遗留——
        //   正好又是"写死常量会随功能移位静默失效"那个坑（自检当场红，才没漏过去）。
        Check("操作条：没有「开口方向」那一格（九格 ＋ 图库 = 10）",
              SelectionHandles.BarButtonCount == 10,
              $"格子数 {SelectionHandles.BarButtonCount}");
        // 挪走的只是"入口"，能力本身没动：`Stroke.SetParabolaAxis` 仍然**保形状地转方向**
        //（这条前面④的四个朝向循环已经在验了，这里只补一句"入口换了、算式没换"）。
        pb2.SetParabolaAxis(CurveAxis.OpenRight);
        Check("朝向：入口换了之后，换朝向仍然**保形状**（p 不变）（±0.5）",
              pb2.EffectiveAxis == CurveAxis.OpenRight && Near(pb2.ParabolaPLocal(), 240f, .5f),
              $"{pb2.EffectiveAxis}，p {pb2.ParabolaPLocal():F1}（期望 240）");
        pb2.SetParabolaAxis(CurveAxis.OpenUp);
        SettleFrames(60);

        // 实轴沿 y 的双曲线：轮廓同样**不能有横穿两支之间的幽灵线段**。
        // 两步走来造：第一步拖出**渐近线框**（拖到哪就是哪：A = 300、B = 600 → 斜率 m = 2）；
        // 第二步拖一个"**比渐近线更竖**"的点 (200, 500)（m·|dx| = 400 < 500）
        // → 焦点落在 y 轴，也就是**上下双曲线**。
        var hy2 = NewCurve(Tool.Hyperbola, StrokeKind.Hyperbola, 1600f, 500f);
        hy2.SetHyperbolaFromAsymptote(1600f, 500f, 1600f + 300f, 500f + 600f, minAxis);
        hy2.SetHyperbolaThroughPoint(1600f + 200f, 500f + 500f);
        Check("双曲线：第二步的点更竖 → **焦点在 y 轴**（上下双曲线），半轴 300 / 150（±0.5）",
              hy2.CurveAxis == CurveAxis.TransverseY
              && Near(hy2.HyperbolaRealLocal(), 300f, .5f) && Near(hy2.HyperbolaImagLocal(), 150f, .5f),
              $"{hy2.CurveAxis}，实半轴 {hy2.HyperbolaRealLocal():F1}、虚半轴 {hy2.HyperbolaImagLocal():F1}");
        // 这一步的**核心**：曲线必须**正好经过那个点**（不是"投影到实轴"那种近似）。
        // 实轴沿 y 时标准式是 `y²/b² − x²/a² = 1`，把 (200, 500) 代进去应当等于 1。
        // 式子里要用**曲线自己的** x / y 方向系数（`HyperbolaCurveALocal/BLocal`），
        // **不是**渐近线框的 `HyperbolaALocal/BLocal` —— 2026-09-20 拆开之后这两个别拿错。
        float c2A = hy2.HyperbolaCurveALocal(), c2B = hy2.HyperbolaCurveBLocal();
        float hy2Fit = 500f * 500f / (c2B * c2B) - 200f * 200f / (c2A * c2A);
        Check("双曲线：曲线**正好经过那个点**（y²/b² − x²/a² = 1）（±0.01）",
              Near(hy2Fit, 1f, .01f), $"代入得 {hy2Fit:F4}（期望 1）");
        var hy2Outline = hy2.ShapeOutline();
        float nearest2 = float.MaxValue;
        for (int i = 1; i < hy2Outline.Count; i++)
        {
            if (Stroke.IsOutlineBreak(hy2Outline[i - 1]) || Stroke.IsOutlineBreak(hy2Outline[i])) continue;
            nearest2 = MathF.Min(nearest2, DistPointSeg(new Vector2(1600f, 500f),
                                                        hy2Outline[i - 1], hy2Outline[i]));
        }
        Check("双曲线（实轴沿 y）：轮廓也没有幽灵线段（中心到任一段 ≥ 0.9a）",
              nearest2 >= hy2.HyperbolaRealLocal() * 0.9f,
              $"{hy2.CurveAxis}，最近距离 {nearest2:F1}（实半轴 {hy2.HyperbolaRealLocal():F1}）");
        var hy2Box = hy2.CurveBoxLocal();
        Check("双曲线（实轴沿 y）：紧框 = ±A × ±B（就是渐近线框）（±0.5）",
              Near(hy2Box.MinX, 1600f - 300f, .5f) && Near(hy2Box.MaxX, 1600f + 300f, .5f)
              && Near(hy2Box.MinY, 500f - 600f, .5f) && Near(hy2Box.MaxY, 500f + 600f, .5f),
              $"框 ({hy2Box.MinX:F1},{hy2Box.MinY:F1})..({hy2Box.MaxX:F1},{hy2Box.MaxY:F1})"
              + " 期望 (1300,-100)..(1900,1100)");
        var (asFrom2, asTo2) = hy2.HyperbolaAsymptoteLocal(1);
        Check("双曲线：**渐近线的端点就是紧框的角**（两个朝向都成立）（默认 ShowAsymptotes = 画）",
              hy2.ShowAsymptotes
              && Near(asTo2.X, 1600f + 300f, .5f) && Near(asTo2.Y, 500f + 600f, .5f)
              && Near(asTo2.X, hy2Box.MaxX, .5f) && Near(asTo2.Y, hy2Box.MaxY, .5f),
              $"({asFrom2.X:F1},{asFrom2.Y:F1})..({asTo2.X:F1},{asTo2.Y:F1})"
              + $" vs 框角 ({hy2Box.MaxX:F1},{hy2Box.MaxY:F1})");

        // ============ ⑤b 四种开口：**真机拖出来**（用户 2026-09-20 问"是不是应该有四种"）===
        //
        // 面板那一格只有**两档**（上下抛物 / 左右抛物），**具体朝哪边由那一拖的符号定**
        //（见 `Stroke.ParabolaAxisOfDrag`）——所以四种开口本来就是画得出来的，
        // 只是"朝上还是朝下"这件事面板替不了你回答（方向被面板选死时，
        // "选着向上、手却往下拖"会画出跟手指反过来的曲线）。
        //
        // 上面 ⑤ 只钉了**模型层**（直接调 `SetParabolaAxis`），这一段补**真机**：
        // 按住顶点往四个方向各拖一次，看落点那一条的朝向对不对。
        // 判据是 `EffectiveAxis`（读端统一走它，不是那个存下来的字段）。
        Console.WriteLine("  -- ⑤b. 四种开口：真机拖出来的方向 --");
        {
            Doc.Clear();
            Doc.ClearHistory();

            // 把"哪一对"切到指定档（面板那一格点第二下就是干这个的）。
            void SetParaPair(CurveAxis pair)
            {
                for (int k = 0; k < 2 && Host.State.ParabolaAxis != pair; k++)
                    Host.Commands.CycleParabolaAxis();
                SettleFrames(80);
            }
            // 按住顶点 (vx,vy) 拖到 (vx+dx, vy+dy)，松手就成一条抛物线。
            void DragParaAxis(float vx, float vy, float dx, float dy)
            {
                SendMouse((int)vx, (int)vy, 0);                                    SettleFrames(60);
                SendMouse((int)vx, (int)vy, Native.MOUSEEVENTF_LEFTDOWN);          SettleFrames(60);
                SendMouse((int)(vx + dx * 0.5f), (int)(vy + dy * 0.5f), 0);        SettleFrames(80);
                SendMouse((int)(vx + dx), (int)(vy + dy), 0);                      SettleFrames(160);
                SendMouse((int)(vx + dx), (int)(vy + dy), Native.MOUSEEVENTF_LEFTUP);
                SettleFrames(200);
            }
            void SetParaTool()
            {
                SetToolFromUi(Tool.Parabola);
                SettleFrames(80);
            }

            float pvx = _virtualX + 700f, pvy = _virtualY + 1050f;
            // 四个方向都拖 (±300, ±300)：`s = t = 300` → `p = 300²/600 = 150`，一格装得下。
            var openCases = new (CurveAxis pair, float dx, float dy, CurveAxis want, string how)[]
            {
                (CurveAxis.OpenUp,     300f, -300f, CurveAxis.OpenUp,    "往上拖"),
                (CurveAxis.OpenUp,     300f,  300f, CurveAxis.OpenDown,  "往下拖"),
                (CurveAxis.OpenRight,  300f,  300f, CurveAxis.OpenRight, "往右拖"),
                (CurveAxis.OpenRight, -300f,  300f, CurveAxis.OpenLeft,  "往左拖"),
            };
            foreach (var oc in openCases)
            {
                Doc.Clear();
                Doc.ClearHistory();
                SetParaTool();
                SetParaPair(oc.pair);
                DragParaAxis(pvx, pvy, oc.dx, oc.dy);

                var ps = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
                Check($"抛物线·{oc.how}（面板「{(oc.pair == CurveAxis.OpenUp ? "上下" : "左右")}抛物」档）"
                      + $" → 开口 {oc.want}",
                      ps != null && ps.Kind == StrokeKind.Parabola && ps.EffectiveAxis == oc.want,
                      $"对象 {Doc.Strokes.Count} 条，"
                      + $"朝向 {(ps == null ? "（没画出来）" : ps.EffectiveAxis.ToString())}（期望 {oc.want}）");
            }
            Doc.Clear();
            Doc.ClearHistory();
            SetParaPair(CurveAxis.OpenUp);       // 收尾：给别人留下一档干净的（后面几段要用）
        }

        // ================= ⑤c. 正切：真机一笔拖出来 =================
        //
        // 上面那一段只钉了**模型层**（直接调 `SetTangentBox`）。这一段补**真机**：
        // 用户按下那一点、拖出那一笔，**引擎自己写出来的**是不是我们要的那份定义
        //（教训：自己 new 一个对象、字段自己填，**不算测**——那条路绕过了引擎）。
        //
        // 要盯的两个数：原点 = **按下那一点**（不是拖出去的那个角！正切和正弦在这点上
        // 正好相反：正弦把起手点留在原地当起点，正切是**以起手点为中心**往四周长）；
        // 半支长 / 可视半高 = 这一笔的 |dx| / |dy|。
        Console.WriteLine("  -- ⑤c. 正切：真机一笔拖出来（按下 = 原点）--");
        {
            Doc.Clear();
            Doc.ClearHistory();
            SetToolFromUi(Tool.Tangent);
            SettleFrames(80);

            float ox = _virtualX + 700f, oy = _virtualY + 1000f;
            SendMouse((int)ox, (int)oy, 0);                                        SettleFrames(60);
            SendMouse((int)ox, (int)oy, Native.MOUSEEVENTF_LEFTDOWN);              SettleFrames(60);
            SendMouse((int)(ox + 80f), (int)(oy + 90f), 0);                        SettleFrames(80);
            SendMouse((int)(ox + 160f), (int)(oy + 180f), 0);                      SettleFrames(160);
            SendMouse((int)(ox + 160f), (int)(oy + 180f), Native.MOUSEEVENTF_LEFTUP);
            SettleFrames(250);

            var ts = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
            Check("正切·真机一笔：画出来的是**正切**一个对象",
                  ts != null && ts.Kind == StrokeKind.Tangent,
                  $"对象 {Doc.Strokes.Count} 条，种类 {(ts == null ? "（没画出来）" : ts.Kind.ToString())}");
            Check("正切·真机一笔：**原点就是按下那一点**（不是拖出去的那个角）（±2）",
                  ts != null && Near(ts.TangentOriginLocal().X, ox, 2f)
                  && Near(ts.TangentOriginLocal().Y, oy, 2f),
                  ts == null ? "（没画出来）"
                  : $"原点 ({ts.TangentOriginLocal().X:F0},{ts.TangentOriginLocal().Y:F0})"
                    + $"（按下的 ({ox:F0},{oy:F0})）");
            Check("正切·真机一笔：半支长 = |dx| = 160；可视半高**被顶到下限 480**（拖的是 180）（±2）",
                  ts != null && Near(ts.TangentHalfSpanLocal(), 160f, 2f)
                  && Near(ts.TangentHalfHeightLocal(), 3f * 160f, 2f),
                  ts == null ? "（没画出来）"
                  : $"半支长 {ts.TangentHalfSpanLocal():F0}、可视半高 {ts.TangentHalfHeightLocal():F0}");

            // 屏幕上也**真的看得见**（不是"只进了文档、没渲染"）：笔色是品红，数那一片的品红像素
            //（这一段的探针口径和上面几段一样，见 `CountMagenta`）。
            Doc.InvalidateAll();
            SettleFrames(200);
            int inkOn = ScreenProbe.CountMagenta((int)(ox - 180f), (int)(oy - 560f), 360, 1120);
            Check("正切·真机一笔：屏幕上真有墨（不是只进了文档没画）", inkOn > 300,
                  $"{inkOn} 个品红像素（门槛 300）");
        }

        // ================= ⑤d. 波浪线：真机一笔拖出来（拖多长画多长） =================
        //
        // 这一格和「正弦」的差别全在"这一拖管什么"上，所以真机这一笔要盯住的就一件事：
        // **横向拖多远 → 画出来几个周期**（`框宽 ÷ 振幅`，因为用户定的"振幅 = 一个周期"），
        // 而不是"拖出来的框就是一个周期"。
        Console.WriteLine("  -- ⑤d. 波浪线：真机一笔拖出来（拖多长画多长）--");
        {
            Doc.Clear();
            Doc.ClearHistory();
            SetToolFromUi(Tool.Wave);
            SettleFrames(80);

            float wx = _virtualX + 700f, wy = _virtualY + 900f;
            SendMouse((int)wx, (int)wy, 0);                                        SettleFrames(60);
            SendMouse((int)wx, (int)wy, Native.MOUSEEVENTF_LEFTDOWN);              SettleFrames(60);
            SendMouse((int)(wx + 150f), (int)(wy - 50f), 0);                       SettleFrames(80);
            SendMouse((int)(wx + 300f), (int)(wy - 100f), 0);                      SettleFrames(160);
            SendMouse((int)(wx + 300f), (int)(wy - 100f), Native.MOUSEEVENTF_LEFTUP);
            SettleFrames(250);

            var ws = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
            Check("波浪线·真机一笔：画出来的是**波浪线**一个对象",
                  ws != null && ws.Kind == StrokeKind.Wave,
                  $"对象 {Doc.Strokes.Count} 条，种类 {(ws == null ? "（没画出来）" : ws.Kind.ToString())}");
            Check("波浪线·真机一笔：A = 100、T = 100、画 300 宽 → **3 个整周期**（±2）",
                  ws != null && Near(ws.WaveAmplitudeLocal(), 100f, 2f)
                  && Near(ws.WavePeriodLocal(), 100f, 2f)
                  && Near(ws.WaveCyclesLocal(), 3f, .02f),
                  ws == null ? "（没画出来）"
                  : $"A {ws.WaveAmplitudeLocal():F0}  T {ws.WavePeriodLocal():F0}"
                    + $"  周期数 {ws.WaveCyclesLocal():F2}（期望 3.00）");
            Check("波浪线·真机一笔：两个定义元素（起点 ＋ 终点，极值点是现推的）",
                  ws != null && ws.Points.Count == 2,
                  $"{ws?.Points.Count ?? -1} 个控制点（期望 2）");
        }

        // ================= ⑤e. 椭圆（带焦点）：真机一笔 ＋ 焦点 ＋ 拖 P =================
        //
        // 用户 2026-09-22 定的口径：
        //   · 第二行加一格**椭圆（带焦点）**（和第一行那个"纯椭圆"**并存**，两个工具）；
        //   · **两档**：有焦点三角形 / 没有焦点三角形——**两个焦点两档都画**，
        //     "无"那一档只是**不连** F₁P、F₂P（原话："还是画焦点，只是不连三角形"）；
        //   · 焦点三角形的**顶点 P 在椭圆上、可以拖着走**。
        //
        // 所以这一段盯五件事（第 ③/④ 条是硬判据，不是"看起来对"）：
        //   ① 真机一笔画出来的是它；② 两个焦点满足 `c² = a² − b²`、在长轴上；
        //   ③ **P 一定在椭圆上**——用椭圆的定义判：`|PF₁| + |PF₂| = 2a`（比"反解参数角"硬得多）；
        //   ④ 拖 P：角变了、"和"照样 2a、**一步撤销回得去**；
        //   ⑤ 两档：有三角形时多一笔、无三角形时它没了**但两个焦点还在**，
        //      而且都不走虚线辅助槽（`Aux == false`，焦点三角形是主体不是辅助线）。
        Console.WriteLine("  -- ⑤e. 椭圆（带焦点）：真机一笔 ＋ 焦点三角形 ＋ 拖 P --");
        {
            Doc.Clear();
            Doc.ClearHistory();
            SetToolFromUi(Tool.ConicEllipse);
            // 归到"有焦点三角形"那一档：不写死"进来时一定是默认档"（前面几段可能点过它）。
            for (int k = 0; k < 4 && !Host.State.EllipseFocusTriangle; k++)
                Host.Commands.CycleEllipseFocusTriangle();
            SettleFrames(80);

            // 按下 = **中心**、拖出去 = **外角点**（和第一行那个椭圆同一套定义）：
            // 这里拖 260 × 120 → a = 260、b = 120，于是 c = √(260² − 120²) ≈ 230.65。
            float ex = _virtualX + 1100f, ey = _virtualY + 1000f;
            const float wa = 260f, wb = 120f;
            SendMouse((int)ex, (int)ey, 0);                                        SettleFrames(60);
            SendMouse((int)ex, (int)ey, Native.MOUSEEVENTF_LEFTDOWN);              SettleFrames(60);
            SendMouse((int)(ex + wa), (int)(ey + wb / 2f), 0);                     SettleFrames(80);
            SendMouse((int)(ex + wa), (int)(ey + wb), 0);                          SettleFrames(160);
            SendMouse((int)(ex + wa), (int)(ey + wb), Native.MOUSEEVENTF_LEFTUP);  SettleFrames(250);

            var ce = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
            Check("带焦点椭圆·真机一笔：画出来的是**椭圆（带焦点）**一个对象",
                  ce != null && ce.Kind == StrokeKind.ConicEllipse,
                  $"对象 {Doc.Strokes.Count} 条，种类 {(ce == null ? "（没画出来）" : ce.Kind.ToString())}");
            if (ce == null)
            {
                Console.WriteLine("  （后面几项没法验）");
            }
            else
            {
                Check("带焦点椭圆：两个定义元素（中心 ＋ 外角点，和第一行那个椭圆同一套）",
                      ce.Points.Count == 2, $"{ce.Points.Count} 个控制点（期望 2）");
                Check("带焦点椭圆：中心 = 按下那一点、a = 260、b = 120（±2）",
                      Near(ce.ShapeCenterLocal.X, ex, 2f) && Near(ce.ShapeCenterLocal.Y, ey, 2f)
                      && Near(ce.SemiAxisALocal, wa, 2f) && Near(ce.SemiAxisBLocal, wb, 2f),
                      $"中心 ({ce.ShapeCenterLocal.X:F0},{ce.ShapeCenterLocal.Y:F0})"
                      + $"（按下 ({ex:F0},{ey:F0})）、a {ce.SemiAxisALocal:F0}、b {ce.SemiAxisBLocal:F0}");

                // ---- ② 两个焦点：c² = a² − b²，且落在**长轴**上 ----
                float cc = MathF.Sqrt(wa * wa - wb * wb);                   // ≈ 230.65
                var (f1, f2) = ce.ConicEllipseFociLocal();
                Check($"带焦点椭圆：焦点在长轴上、c = √(a²−b²) ≈ {cc:F0}（±2）",
                      Near(f1.X, ex - cc, 2f) && Near(f1.Y, ey, 2f)
                      && Near(f2.X, ex + cc, 2f) && Near(f2.Y, ey, 2f),
                      $"F1 ({f1.X:F0},{f1.Y:F0})、F2 ({f2.X:F0},{f2.Y:F0})（期望 y = {ey:F0}，x = ∓{cc:F0}）");

                // ---- ③ P 在椭圆上：|PF₁| + |PF₂| = 2a（椭圆的定义） ----
                // 这是"P 一定在椭圆上"最硬的一条判据：它不依赖我们对参数角的理解对不对。
                float SumOfDists(Vector2 p) => Vector2.Distance(p, f1) + Vector2.Distance(p, f2);
                var p0 = ce.ConicEllipsePointLocal();
                Check($"带焦点椭圆：默认的 P 在椭圆上（|PF₁|+|PF₂| = 2a = {2 * wa:F0}）（±1）",
                      Near(SumOfDists(p0), 2f * wa, 1f),
                      $"和 = {SumOfDists(p0):F1}（期望 {2 * wa:F0}）");
                // 默认角是**左上方**（120°，见 Stroke.DefaultFocusPointU）：
                // 用户 2026-09-22 的口径"焦点三角形那个顶点……弄在椭圆上面"。
                Check("带焦点椭圆：默认的 P 在椭圆的**左上方**（120° 那个点）",
                      Near(p0.X, ex + wa * MathF.Cos(Stroke.DefaultFocusPointU), 2f)
                      && Near(p0.Y, ey + wb * MathF.Sin(Stroke.DefaultFocusPointU), 2f),
                      $"P ({p0.X:F0},{p0.Y:F0})（期望 ({ex + wa * MathF.Cos(Stroke.DefaultFocusPointU):F0},"
                      + $"{ey + wb * MathF.Sin(Stroke.DefaultFocusPointU):F0})）");
                Check("带焦点椭圆：默认的 P 不跟两个焦点共线（三角形不会退化成一条线段）",
                      MathF.Abs(p0.Y - ey) > 1f && MathF.Abs(p0.X - ex) > 1f,
                      $"P 相对中心 ({p0.X - ex:F0},{p0.Y - ey:F0})，焦点在 y = {ey:F0} 这条线上");
                Check("带焦点椭圆：默认档 = **有焦点三角形**",
                      ce.FocusTriangle, $"FocusTriangle = {ce.FocusTriangle}");

                // ---- ⑤ 两档：折线笔数（① 椭圆 ②③ 三角形的两条边 ④⑤ 两个焦点），且都不走辅助槽 ----
                int Pieces() => ce.InkPieces().Count(pc => pc.Pts.Count >= 2);
                int AuxPieces() => ce.InkPieces().Count(pc => pc.Aux);
                int piecesWithTri = Pieces();
                Check("带焦点椭圆·有三角形档：画出来 5 笔（椭圆 ＋ 两条边 ＋ 两个焦点小圆点）",
                      piecesWithTri == 5, $"{piecesWithTri} 笔（期望 5）");
                Check("带焦点椭圆：**一笔都不走虚线辅助槽**（焦点三角形是主体，不是辅助线）",
                      AuxPieces() == 0, $"{AuxPieces()} 笔是 Aux（期望 0）");

                ce.SetFocusTriangle(false);
                int piecesNoTri = Pieces();
                Check("带焦点椭圆·无三角形档：少一笔（椭圆 ＋ 两个焦点小圆点 = 3 笔）、焦点还在",
                      piecesNoTri == 3 && AuxPieces() == 0, $"{piecesNoTri} 笔（期望 3）");
                ce.SetFocusTriangle(true);                     // 后面的断言接着按"有"那一档走

                // ---- ④ 拖 P：模型里的角变了、"和"照样 2a、一步撤销回得去 ----
                Doc.SelectOnly(new[] { ce });
                SettleFrames(300);
                var pHandleFrom = SelectionHandles.ShapeHandleCanvasPosition(ce, ShapeHandle.FocusPoint);
                // 目标：把 P 拖到"参数角 45°"那个方向上的点（椭圆上那一点：
                // center + (a·cos45°, b·sin45°) —— 注意**拖到哪儿都行**，模型会把方向折成角）。
                var pTarget = new Vector2(ex + wa * 0.70711f, ey + wb * 0.70711f);
                bool tookP = SelectionGestureForTest(pHandleFrom.X, pHandleFrom.Y);
                UpdateSelectionGestureForTest(pTarget.X, pTarget.Y);
                SettleFrames(140);
                EndSelectionGestureForTest();
                SettleFrames(250);

                Check("带焦点椭圆·拖 P：真的抓住了那个圆点（手柄在 P 上）",
                      tookP, $"接住 = {tookP}");
                Check("带焦点椭圆·拖 P：角变成 45°（±0.03 弧度）",
                      !float.IsNaN(ce.FocusPointU) && Near(ce.FocusPointU, MathF.PI / 4f, .03f),
                      $"u = {(float.IsNaN(ce.FocusPointU) ? "NaN（没写进去）" : ce.FocusPointU.ToString("F4"))}"
                      + $"（期望 {MathF.PI / 4f:F4}）");
                var p1 = ce.ConicEllipsePointLocal();
                Check($"带焦点椭圆·拖 P 之后：P **还在椭圆上**（|PF₁|+|PF₂| = 2a = {2 * wa:F0}）（±1）",
                      Near(SumOfDists(p1), 2f * wa, 1f),
                      $"P ({p1.X:F0},{p1.Y:F0})，和 = {SumOfDists(p1):F1}");
                Check("带焦点椭圆·拖 P：**椭圆本身一动没动**（只有那个角变了）",
                      Near(ce.SemiAxisALocal, wa, 2f) && Near(ce.SemiAxisBLocal, wb, 2f),
                      $"a {ce.SemiAxisALocal:F0}、b {ce.SemiAxisBLocal:F0}");

                Doc.Undo();
                SettleFrames(200);
                Check("带焦点椭圆·拖 P：一步撤销回到「还没拖过」的状态（P 回默认那一端）",
                      float.IsNaN(ce.FocusPointU)
                      || Near(ce.ConicEllipsePointLocal().X, p0.X, 2f)
                      && Near(ce.ConicEllipsePointLocal().Y, p0.Y, 2f),
                      $"FocusPointU = {(float.IsNaN(ce.FocusPointU) ? "NaN（自动）" : ce.FocusPointU.ToString("F4"))}"
                      + $"，P = ({ce.ConicEllipsePointLocal().X:F0},{ce.ConicEllipsePointLocal().Y:F0})"
                      + $"（默认 ({p0.X:F0},{p0.Y:F0})）");
                Doc.Selected.Clear();
                SettleFrames(120);
            }
        }

        // ================= ⑥ 存档：往返 ＋ 真 v11 老文件 =================
        Doc.Clear();
        Doc.ClearHistory();
        var saveMe = NewCurve(Tool.Parabola, StrokeKind.Parabola, 700f, 700f);
        saveMe.CurveAxis = CurveAxis.OpenLeft;                             // 选：开口向左
        saveMe.SetParabolaVertex(700f, 700f);
        saveMe.SetParabolaThroughPoint(560f, 420f);                        // s = 140、t = 280 → p = 280
        var saveHy = NewCurve(Tool.Hyperbola, StrokeKind.Hyperbola, 1400f, 700f);
        // 两步：第一步拖出**渐近线框**（A = 160、B = 320 → 斜率 2），
        // 第二步拖一个更竖的点 → 焦点在 y 轴（上下双曲线）。
        saveHy.SetHyperbolaFromAsymptote(1400f, 700f, 1560f, 1020f, minAxis);
        saveHy.SetHyperbolaThroughPoint(1400f + 100f, 700f + 250f);
        var saveSin = NewCurve(Tool.Sine, StrokeKind.Sine, 300f, 700f);
        saveSin.SetWaveBox(300f, 700f, 780f, 600f, minAxis);
        // 正切（v21 新增的取值）：一笔，存的就是"原点 ＋ 那个角"，形状全由这两个点派生。
        // ⚠ 存的是**拖出来的那个角**（180），画的时候半高会被下限顶到 480 —— 两个都要读回来。
        var saveTan = NewCurve(Tool.Tangent, StrokeKind.Tangent, 900f, 1200f);
        saveTan.SetTangentBox(900f, 1200f, 1060f, 1380f, minAxis);          // 半支长 160、拖的半高 180
        // 波浪线（v22 新增的取值）：和正弦同一套"起点 ＋ 终点"，差别只是**这一拖管什么**。
        var saveWave = NewCurve(Tool.Wave, StrokeKind.Wave, 900f, 1700f);
        saveWave.SetWaveBox(900f, 1700f, 1200f, 1600f, minAxis);            // A = 100 → 3 个周期
        // 椭圆（带焦点）（v23 新增的取值 ＋ 两个新字段）：存"**无焦点三角形**那一档 ＋
        // 一个**拖过的 P**"，这样两个字段都被真正走到（不是靠默认值蒙过去）。
        var saveCe = NewCurve(Tool.ConicEllipse, StrokeKind.ConicEllipse, 400f, 1200f);
        saveCe.SetEnd(660f, 1320f);                                        // a = 260、b = 120
        saveCe.FocusTriangle = false;
        saveCe.SetConicEllipsePointAngle(MathF.PI / 3f);                    // 60°（不用默认值）
        Doc.AddStroke(saveMe);
        Doc.AddStroke(saveHy);
        Doc.AddStroke(saveSin);
        Doc.AddStroke(saveTan);
        Doc.AddStroke(saveWave);
        Doc.AddStroke(saveCe);

        var blob = InkSerializer.Save(Doc);
        var back = new InkDocument();
        InkSerializer.LoadInto(back, blob);
        bool roundTrip = back.Strokes.Count == 6
                         && back.Strokes[0].Kind == StrokeKind.Parabola
                         && Near(back.Strokes[0].ParabolaDirLocal().X, -1f, .01f)
                         && back.Strokes[1].Kind == StrokeKind.Hyperbola
                         && back.Strokes[1].CurveAxis == CurveAxis.TransverseY
                         && back.Strokes[1].ShowAsymptotes
                         && back.Strokes[2].Kind == StrokeKind.Sine
                         && back.Strokes[3].Kind == StrokeKind.Tangent
                         && Near(back.Strokes[3].TangentHalfSpanLocal(), 160f, .5f)
                         && Near(back.Strokes[3].TangentHalfHeightLocal(), 3f * 160f, .5f)
                         && back.Strokes[4].Kind == StrokeKind.Wave
                         && Near(back.Strokes[4].WaveCyclesLocal(), 3f, .02f)
                         && back.Strokes[5].Kind == StrokeKind.ConicEllipse
                          && Near(back.Strokes[5].SemiAxisALocal, 260f, .5f)
                          && Near(back.Strokes[5].SemiAxisBLocal, 120f, .5f)
                          && !back.Strokes[5].FocusTriangle
                          && Near(back.Strokes[5].FocusPointU, MathF.PI / 3f, .001f);
        Check("存档：五种曲线 ＋ 椭圆（带焦点）＋ 朝向 ＋ 渐近线开关都回来了（含 v21 正切 / v22 波浪线 / v23 椭圆）",
              roundTrip,
              back.Strokes.Count == 5
                  ? $"{back.Strokes[0].Kind}/方向 {back.Strokes[0].ParabolaDirLocal()}、"
                    + $"{back.Strokes[1].Kind}/{back.Strokes[1].CurveAxis}/渐近线 {back.Strokes[1].ShowAsymptotes}、"
                    + $"{back.Strokes[2].Kind}、"
                    + $"{back.Strokes[3].Kind}（半支长 {back.Strokes[3].TangentHalfSpanLocal():F0}）、"
                    + $"{back.Strokes[4].Kind}（周期数 {back.Strokes[4].WaveCyclesLocal():F2}）"
                  : back.Strokes.Count == 6
                    ? $"{back.Strokes[5].Kind}（焦点三角形 {back.Strokes[5].FocusTriangle}、"
                      + $"P 的角 {back.Strokes[5].FocusPointU:F4} —— 期望 False / {MathF.PI / 3f:F4}）"
                    : $"只读回 {back.Strokes.Count} 条");

        // 真·v22 老文件：**一条带焦点椭圆**的末尾少 5 个字节（v23 新增的那两位：
        // 1 字节开关 ＋ 4 字节 float）。读端必须退到"画三角形 ＋ P 还没定过（NaN）"。
        // `MakeLegacyFile` 是"从整个文件末尾砍 N 个字节"，所以这里只能是**单条对象**的文件。
        var legacyCeDoc = new InkDocument();
        var legacyCe = NewCurve(Tool.ConicEllipse, StrokeKind.ConicEllipse, 600f, 900f);
        legacyCe.SetEnd(860f, 1020f);
        legacyCeDoc.AddStroke(legacyCe);
        var oldCe = new InkDocument();
        InkSerializer.LoadInto(oldCe, MakeLegacyFile(legacyCeDoc, 22, 5));
        Check("存档：真 v22 老文件读得进来（1 条对象）", oldCe.Strokes.Count == 1, $"{oldCe.Strokes.Count} 条");
        if (oldCe.Strokes.Count == 1)
        {
            var oc = oldCe.Strokes[0];
            Check("存档：v22 老文件里没有那两位 → 焦点三角形退到默认（画）、P 退到「还没定过」",
                  oc.Kind == StrokeKind.ConicEllipse && oc.FocusTriangle && float.IsNaN(oc.FocusPointU),
                  $"Kind {oc.Kind}、FocusTriangle {oc.FocusTriangle}、"
                  + $"FocusPointU {(float.IsNaN(oc.FocusPointU) ? "NaN（= 自动摆）" : oc.FocusPointU.ToString())}");
        }


        // 真·v11 老文件：**一条对象**的那条笔画末尾少 1 个字节（就是 v12 的"渐近线"那一位）。
        // 注意 `MakeLegacyFile` 是"从整个文件末尾砍 N 个字节"，所以它只对**单条笔画**成立
        // （多条时只有最后一条被砍到，中间几条会整体错位）——这是那个工具的用法约定。
        var legacyDoc = new InkDocument();
        var legacyHy = NewCurve(Tool.Hyperbola, StrokeKind.Hyperbola, 1400f, 700f);
        // **故意按 v13 及以前的语义造**：那时双曲线只有**两个**控制点，第二个点同时是
        // "渐近线框"和"曲线半轴"（渐近线画到 ±2a、±2b）——这正是老文件里的样子。
        // 读端那条迁移（`version <= 13`）必须能从它恢复出**形状不变**的新表示。
        // 这里塞的是老算法下的"角点"：(1400,700) → (1475,850)，于是半轴 a = 75、b = 150、斜率 2。
        legacyHy.SetHyperbolaFromAsymptote(1400f, 700f, 1400f + 75f, 700f + 150f, minAxis);
        legacyHy.CurveAxis = CurveAxis.TransverseY;                              // 老文件里朝向是存的
        // 迁移后应当是：渐近线框 A = 150、B = 300，曲线经过 `u = 1` 那个点 → **实半轴还是 150**。
        legacyDoc.AddStroke(legacyHy);
        var old = new InkDocument();
        InkSerializer.LoadInto(old, MakeLegacyFile(legacyDoc, 11, 1));
        Check("存档：真 v11 老文件读得进来（1 条对象）", old.Strokes.Count == 1, $"{old.Strokes.Count} 条");
        if (old.Strokes.Count == 1)
        {
            Check("存档：老文件里朝向照旧（实轴沿 y）、渐近线退到默认（画）",
                  old.Strokes[0].CurveAxis == CurveAxis.TransverseY
                  && old.Strokes[0].ShowAsymptotes
                  && Near(old.Strokes[0].HyperbolaRealLocal(), 150f, .5f),
                  $"{old.Strokes[0].CurveAxis}，渐近线 {old.Strokes[0].ShowAsymptotes}"
                  + $"，实半轴 {old.Strokes[0].HyperbolaRealLocal():F1}（期望 150）");
        }

        // 真·v12 老文件里的**抛物线**：这一条专盯 v13 那次"换含义"的迁移。
        // v12 存的是"顶点 + **张口点**（落在对称轴上、离顶点 p/2）"，新读端必须把它换成
        // "曲线上的一个点"，否则反解不出张口、曲线会缩到最小——而且**不报错**，
        // 只是"一存一读就瘪了"。
        //
        // 注意这里是**故意**用一个"落在对称轴上"的点来模拟老文件：
        // 新写法 `SetParabolaThroughPoint` 本来是要放曲线上的点，但老文件的第二位就是张口点，
        // 只有这么造才是货真价实的 v12 语义（p = 2 × |顶点→张口点| = 280）。
        var legacyPara = NewCurve(Tool.Parabola, StrokeKind.Parabola, 700f, 700f);
        legacyPara.CurveAxis = CurveAxis.OpenLeft;             // 开口向左：方向 = (−1, 0)
        legacyPara.SetParabolaVertex(700f, 700f);
        legacyPara.SetParabolaThroughPoint(560f, 700f);        // 张口点 = 顶点 − (140, 0) → p = 280
        var legacyParaDoc = new InkDocument();
        legacyParaDoc.AddStroke(legacyPara);
        var oldPara = new InkDocument();
        // 砍 0 位：**v13 没往笔画后面加字节**，v12 的文件和它一样长（只差版本号）。
        InkSerializer.LoadInto(oldPara, MakeLegacyFile(legacyParaDoc, 12, 0));
        Check("存档：真 v12 老文件里的抛物线**读回来还是 p = 280**（迁移过去、形状不变）（±0.5）",
              oldPara.Strokes.Count == 1 && Near(oldPara.Strokes[0].ParabolaPLocal(), 280f, .5f)
              && oldPara.Strokes[0].CurveAxis == CurveAxis.OpenLeft,
              oldPara.Strokes.Count == 1
                  ? $"p {oldPara.Strokes[0].ParabolaPLocal():F1}（期望 280）、"
                    + $"朝向 {oldPara.Strokes[0].CurveAxis}"
                  : $"只读回 {oldPara.Strokes.Count} 条");
        // 迁移之后那个点必须**真的落在曲线上**（不是随便挪一个）：
        // `t ≠ 0` 才有信息定张口，而且代进参数方程应当能对上。
        if (oldPara.Strokes.Count == 1)
        {
            var op = oldPara.Strokes[0];
            var (odir, operp) = Stroke.ParabolaBasis(op.EffectiveAxis);
            var od = op.CurvePointLocal(1) - op.CurvePointLocal(0);
            float os = Vector2.Dot(od, odir), ot = Vector2.Dot(od, operp);
            Check("存档：迁移后那个点在**曲线该在的地方**（s = p/2、t = p = 280）（±0.5）",
                  Near(os, 140f, .5f) && Near(ot, 280f, .5f), $"s {os:F1}、t {ot:F1}（期望 140 / 280）");
        }

        // ============ ⑦ 删除 / 换方向之后不留残影（用户 2026-09-20 报的）============
        //
        // 用户原话："抛物线删除会留残影"。残影这一类 bug 的特点是**自检全绿也可能有**
        // （字段、包围盒全对，只是屏幕上没擦干净），所以只能**数屏幕上的像素**：
        // 画一条抛物线 → 量那块墨 → 删掉 → 再量同一块，必须一个像素都不剩。
        // 两条路都要走一遍：
        //   ① 直接画完就删；
        //   ② **改过一次形状之后再删**——改几何走的是另一条动作路径
        //      （见 SetStrokeGeometryAction：它必须顺手重算 Bounds，
        //       否则 WorldBounds 会拿旧框去套新曲线、擦不干净）。
        Console.WriteLine("  -- G. 删除之后不留残影（数屏幕像素）--");
        {
            var ink2 = new Color4(1f, 0f, 1f, 1f);
            Host.Commands.SetColor(ink2);
            // 量"这条曲线墨迹框再往外 60 像素"那一块里的品红像素。
            // 多留 60 是因为操作条就挂在框下方——那条残影也在这一块里。
            int InkAround(Stroke s)
            {
                var b = s.PaddedBounds;
                return ScreenProbe.CountMagenta((int)b.MinX - 12, (int)b.MinY - 12,
                                                (int)(b.MaxX - b.MinX) + 24,
                                                (int)(b.MaxY - b.MinY) + 84);
            }
            // 抛物线是**一笔拖**（顶点 = 按下那个点，照 InkClass 的 `case 20/21`）：
            // 按住顶点拖到"曲线经过的点"，松手就成。
            // 经过点取右上方 `(gw, −gw)`：`s = t = gw` → `p = gw²/(2gw) = gw/2`。
            void DragParabola(float gx, float gy, float gw)
            {
                SendMouse((int)gx, (int)gy, 0);                             SettleFrames(60);
                SendMouse((int)gx, (int)gy, Native.MOUSEEVENTF_LEFTDOWN);   SettleFrames(60);
                SendMouse((int)(gx + gw), (int)(gy - gw), 0);               SettleFrames(240);
                SendMouse((int)(gx + gw), (int)(gy - gw), Native.MOUSEEVENTF_LEFTUP);
                SettleFrames(240);
            }

            for (int round = 0; round < 2; round++)
            {
                bool flipFirst = round == 1;
                Doc.Clear();
                Doc.ClearHistory();
                SetToolFromUi(Tool.Parabola);
                float gx = _virtualX + 700f, gy = _virtualY + 1250f;
                DragParabola(gx, gy, 400f);             // p = 200（曲线半宽 300、沿轴 225）
                var g = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
                if (g == null) { Check("⑦ 抛物线没画出来（后面两项没法验）", false, "对象 0 个"); break; }

                // ② 那一轮：先**改一下这条曲线**再撤销——走一遍和"画完就删"不同的动作路径。
                //
                // ⚠ 这里原来是"拖抛物线的 Rim 手柄改 p"，**2026-09-20 第六批把四种曲线的
                //   特殊手柄全砍了**（改走通用框），那个手柄名当场失效、这一轮就静默退化成
                //   round 0 的复制品（断言照样绿）——正是"写死的手柄名会随功能移位而失效"
                //   那条教训。现在改拖**通用框的右下角**（缩放）：它改的是 `Transform`，
                //   走 `SetStrokeTransformAction`，不是几何那条路。
                //   哪天真把曲线手柄加回来，这里也该跟着改回来。
                if (flipFirst)
                {
                    Doc.SelectOnly(new[] { g });
                    SettleFrames(60);
                    var gf = SelectionHandles.FrameOf(Doc.Selected);
                    var gc = SelectionHandles.CanvasPosition(SelHandle.BottomRight, gf, DpiScale);
                    bool got = SelectionGestureForTest(gc.X, gc.Y);
                    UpdateSelectionGestureForTest(gc.X + 120f, gc.Y + 80f);
                    SettleFrames(80);
                    EndSelectionGestureForTest();
                    SettleFrames(140);
                    // 先证明"真的改了"——不然下面那条"改过形状之后删除"是假的
                    Check("⑦ 第二轮：拖通用框真的动了这条抛物线（不然下面那条断言是假的）",
                          got && !g.Transform.IsIdentity,
                          $"接住={got}，变换={(g.Transform.IsIdentity ? "单位（没动）" : "变了")}");
                    Doc.Undo();                     // 撤销那一次改动（再走一遍写回路径）
                    SettleFrames(140);
                    Doc.SelectOnly(new[] { g });
                    SettleFrames(120);
                }

                Doc.SelectOnly(new[] { g });
                SettleFrames(120);
                int before = InkAround(g);
                RunBarActionForTest((int)SelBarButton.Delete);
                SettleFrames(300);
                int after = InkAround(g);
                Check(flipFirst
                        ? "⑦ 改过形状之后删除：那块地方一个墨点都不剩（残影）"
                        : "⑦ 直接删除：那块地方一个墨点都不剩（残影）",
                      before > 200 && after == 0,
                      $"删前 {before} 像素 → 删后 {after}（方向 {(flipFirst ? "换过" : "没换")}）");
            }
        }

        // ============ ⑧ 双曲线**两笔拖动式** ============
        //
        // 口径（用户 2026-09-20 定："他的双曲线是拖动两次吗？按照他的这个规则复刻"）：
        // **一笔 = 按下-拖-松手，松手推进下一笔**——照 InkClass 的
        // `drawMultiStepShapeCurrentStep` ＋ MouseUp 推进（`MW_ShapeDrawing.cs:1814-1822`）：
        //   第 1 笔 → **从中心拖出渐近线**（拖到哪就是哪）→ 松手**锁住**，此后不再变；
        //   第 2 笔 → **再拖一下**：拖到哪、**曲线就经过哪**（中心沿用第 1 笔那个，
        //             InkClass 的第二笔刻意不重设 `iniP`，`:1971-1977`）；
        // 中途松手**不进文档**（半成品留在 ActiveStroke），两笔合起来**只有一条撤销记录**。
        //
        // 和上一版（三下点击 + 中间悬停）的区别：**几何只在按住拖动时更新**，指针不按键时
        // 半成品一动不动（InkClass 就是这样）——这也是触摸屏能用的根子：手指没有"悬停"，
        // 而每一步本来就是"按住拖-松手"，笔 / 鼠标 / 手指走的是同一条路。
        Console.WriteLine("  -- H. 双曲线两笔拖动式（从中心拖出渐近线 → 再拖一下定曲线）--");
        {
            Doc.Clear();
            Doc.ClearHistory();
            SetToolFromUi(Tool.Hyperbola);
            float hpx = _virtualX + 900f, hpy = _virtualY + 1300f;

            // 一次"按住拖"：按下 → 挪到目标 → 抬起。
            void Drag(float x0, float y0, float x1, float y1)
            {
                SendMouse((int)x0, (int)y0, 0);                            SettleFrames(60);
                SendMouse((int)x0, (int)y0, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
                SendMouse((int)x1, (int)y1, 0);                            SettleFrames(240);
                SendMouse((int)x1, (int)y1, Native.MOUSEEVENTF_LEFTUP);    SettleFrames(180);
            }

            // 第 1 笔：从中心 (hpx,hpy) 拖到右下方 (hpx+400, hpy+160) → 渐近线框 A = 400、B = 160
            //（斜率 0.4，和 InkClass 的 `k = |dy/dx|` 同一个）。
            SendMouse((int)hpx, (int)hpy, 0);                            SettleFrames(60);
            SendMouse((int)hpx, (int)hpy, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
            Check("两笔式：第 1 笔按下之后**还没提交**（半成品不进文档）",
                  Doc.Strokes.Count == 0, $"对象 {Doc.Strokes.Count} 条（期望 0）");

            SendMouse((int)(hpx + 200f), (int)(hpy + 80f), 0);   SettleFrames(60);
            SendMouse((int)(hpx + 400f), (int)(hpy + 160f), 0);  SettleFrames(240);
            Check("两笔式：第 1 笔拖动中是**只画渐近线**的阶段（状态）",
                  HyperAsymptotePreviewOnly && ActiveStroke != null,
                  $"只画渐近线={HyperAsymptotePreviewOnly}，半成品={(ActiveStroke != null)}");
            // 并且要在屏幕上看得见这条差别：曲线上有一小块**渐近线根本不会经过**的地方
            //（中心右下方 205..260 × 30..70，渐近线在那儿是 y = 0.4x ∈ [82, 104]）。
            int inkAux = ScreenProbe.CountMagenta((int)hpx + 205, (int)hpy + 30, 55, 40);

            // 松手 = **第 1 笔完成**：渐近线锁住，但对象**还不进文档**（还有第 2 笔）。
            SendMouse((int)(hpx + 400f), (int)(hpy + 160f), Native.MOUSEEVENTF_LEFTUP); SettleFrames(180);
            Check("两笔式：第 1 笔松手之后**仍然没提交**（还有第 2 笔）",
                  Doc.Strokes.Count == 0, $"对象 {Doc.Strokes.Count} 条（期望 0）");

            // **松手后晃鼠标（不按键）：半成品一动不动**——这是这一版和上一版最大的手感差别，
            // 也是触摸屏上"没有悬停"这件事能成立的原因。
            SendMouse((int)(hpx + 900f), (int)(hpy + 600f), 0);   SettleFrames(240);
            Check("两笔式：松手后**晃鼠标不按键**，渐近线框一动不动（A 400、B 160）（±0.5）",
                  ActiveStroke != null
                  && Near(ActiveStroke.HyperbolaALocal(), 400f, .5f)
                  && Near(ActiveStroke.HyperbolaBLocal(), 160f, .5f),
                  ActiveStroke == null ? "半成品没了"
                      : $"A {ActiveStroke.HyperbolaALocal():F1}  B {ActiveStroke.HyperbolaBLocal():F1}");

            // 第 2 笔：**再拖一下**——先掠过一个"能证明曲线出来了"的位置 (220, 37)，
            // 再拖到最终落点 (500, 150)（中心右下方、比渐近线更横）
            // → 曲线**正好经过这个点**，朝向 = 焦点在 x 轴（左右双曲线）。
            SendMouse((int)hpx, (int)hpy, 0);                            SettleFrames(60);
            SendMouse((int)hpx, (int)hpy, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
            // 先停在 (220,37)：曲线此刻正好穿过那一小块（a 由这个点反解 ≈ 200），
            // 于是"同一块地方"的墨从 0 变成"有曲线"——证明曲线是**第 2 笔才出来**的。
            SendMouse((int)(hpx + 220f), (int)(hpy + 37f), 0);           SettleFrames(240);
            int inkCurve = ScreenProbe.CountMagenta((int)hpx + 205, (int)hpy + 30, 55, 40);
            Check("两笔式：曲线是**第 2 笔拖动时才出现**的（同一块地方：0 墨 → 有曲线）",
                  inkAux == 0 && inkCurve > 50, $"只出渐近线时 {inkAux} 像素 → 出曲线后 {inkCurve} 像素");
            // 再拖到最终落点；挪到一半时曲线也跟着走（否则松手会跳）。
            SendMouse((int)(hpx + 500f), (int)(hpy + 150f), 0);          SettleFrames(240);
            Check("两笔式：第 2 笔拖动中**仍然没提交**（松手才算完）",
                  Doc.Strokes.Count == 0, $"对象 {Doc.Strokes.Count} 条（期望 0）");

            // 第 2 笔松手 = 定稿：a 由那个点反解 —— a² = 500² − 150²/0.4² = 109375。
            float k3 = 0.4f, dx3 = 500f, dy3 = 150f;
            float wantA = MathF.Sqrt(dx3 * dx3 - dy3 * dy3 / (k3 * k3));    // ≈ 330.72
            float wantB = wantA * k3;                                       // ≈ 132.29
            SendMouse((int)(hpx + dx3), (int)(hpy + dy3), Native.MOUSEEVENTF_LEFTUP); SettleFrames(180);

            var hyp = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
            Check("两笔式：第 2 笔松手之后对象才出来（一条双曲线、实轴沿 x）",
                  hyp != null && hyp.Kind == StrokeKind.Hyperbola
                  && hyp.CurveAxis == CurveAxis.TransverseX,
                  hyp == null ? $"对象 {Doc.Strokes.Count} 条（期望 1）"
                              : $"Kind={hyp.Kind} 朝向={hyp.CurveAxis}");
            if (hyp == null) { Console.WriteLine("  （后面几项没法验）"); }
            else
            {
                Check("两笔式：半轴由那个点反解 —— 实半轴 330.7、虚半轴 132.3（±2）",
                      Near(hyp.HyperbolaRealLocal(), wantA, 2f)
                      && Near(hyp.HyperbolaImagLocal(), wantB, 2f),
                      $"实半轴 {hyp.HyperbolaRealLocal():F1}（期望 {wantA:F1}）、"
                      + $"虚半轴 {hyp.HyperbolaImagLocal():F1}（期望 {wantB:F1}）");
                // 这一步的**核心断言**：把那个点代进标准式，必须**正好等于 1**（曲线穿过它）。
                // 式子里要用**曲线自己的** x / y 方向系数（`HyperbolaCurveALocal/BLocal`），
                // **不是**渐近线框的 `HyperbolaALocal/BLocal`（那两个是框，曲线随时可能比它小）。
                float fit = dx3 * dx3 / (hyp.HyperbolaCurveALocal() * hyp.HyperbolaCurveALocal())
                          - dy3 * dy3 / (hyp.HyperbolaCurveBLocal() * hyp.HyperbolaCurveBLocal());
                Check("两笔式：曲线**正好经过那个点**（x²/a² − y²/b² = 1）（±0.01）",
                      Near(fit, 1f, .01f), $"代入得 {fit:F4}（期望 1）");
                Check("两笔式：**渐近线斜率没动**（还是 0.4）（±0.005）",
                      Near(hyp.HyperbolaBLocal() / hyp.HyperbolaALocal(), k3, .005f),
                      $"{hyp.HyperbolaBLocal() / hyp.HyperbolaALocal():F4}（期望 {k3:F4}）");
                // **这一版的正题**：第 2 笔"定曲线"不许碰第 1 笔锁住的那个框
                //（用户原话："渐近线画好以后大小完全不动，长度也不动"）。
                Check("两笔式：**渐近线框一动都没动**（A 400、B 160 —— 就是第 1 笔拖出来的那个）（±0.5）",
                      Near(hyp.HyperbolaALocal(), 400f, .5f) && Near(hyp.HyperbolaBLocal(), 160f, .5f),
                      $"A {hyp.HyperbolaALocal():F1}（期望 400）  B {hyp.HyperbolaBLocal():F1}（期望 160）");
                Check("两笔式：两笔 = **一条**撤销记录（不是两条）",
                      Doc.UndoDepth == 1, $"撤销栈 {Doc.UndoDepth} 步");
                Doc.Undo();
                Check("两笔式：撤销一步 → 整条消失",
                      Doc.Strokes.Count == 0, $"对象 {Doc.Strokes.Count} 条（期望 0）");
            }

            // ---- 换工具 = 半成品作废：那条画了一半的必须**当场丢掉** ----
            //
            // 为什么值得单独验：那半条双曲线**不在文档里**，却一直被渲染（ActiveStroke 是
            // 无条件画的）。不丢的话它会永远挂在屏幕上，而且**橡皮也擦不掉**——它根本不是
            // 文档里的对象。所以这里用"数屏幕上的墨"来验，而不是数对象个数。
            SetToolFromUi(Tool.Hyperbola);
            float qx = _virtualX + 1500f, qy = _virtualY + 1300f;
            // 第 1 笔拖到 (200, 80)：渐近线框 A = 200、B = 80（虚线就画到 ±A、±B）。
            SendMouse((int)qx, (int)qy, 0);                            SettleFrames(60);
            SendMouse((int)qx, (int)qy, Native.MOUSEEVENTF_LEFTDOWN);  SettleFrames(60);
            SendMouse((int)(qx + 200f), (int)(qy + 80f), 0);           SettleFrames(240);
            int inkBefore = ScreenProbe.CountMagenta((int)qx - 260, (int)qy - 110, 520, 220);
            SendMouse((int)(qx + 200f), (int)(qy + 80f), Native.MOUSEEVENTF_LEFTUP); SettleFrames(180);
            SetToolFromUi(Tool.Line);                             // 换工具 → 作废
            SettleFrames(360);
            int inkAfter = ScreenProbe.CountMagenta((int)qx - 260, (int)qy - 110, 520, 220);
            Check("两笔式：换工具把半成品**丢掉**（屏幕上不留痕）",
                  inkBefore > 200 && inkAfter == 0,
                  $"换工具前 {inkBefore} 像素 → 后 {inkAfter}");
            SetToolFromUi(Tool.Hyperbola);

            // ---- 换工具之后重新画 = **新的一条**（不是接着上一条的大小改）----
            // 第 1 笔：从 (qx,qy) 拖出渐近线框（A = 200、B = 80）；
            // 第 2 笔：拖到 (300, 0)（**在框内**、且在实轴上）→ 实半轴就正好是 300。
            Doc.ClearHistory();
            Drag(qx, qy, qx + 200f, qy + 80f);                    // 第 1 笔：渐近线
            Drag(qx, qy, qx + 300f, qy);                          // 第 2 笔：曲线过 (300,0)
            Check("两笔式：换过工具之后，再画一条是**新对象**（不是改上一条）",
                  Doc.Strokes.Count == 1 && Near(Doc.Strokes[0].HyperbolaRealLocal(), 300f, 6f),
                  $"对象 {Doc.Strokes.Count} 条，实半轴 "
                  + $"{(Doc.Strokes.Count > 0 ? Doc.Strokes[0].HyperbolaRealLocal() : -1f):F1}（期望 1 条 / 300）");

            // ---- 第 2 笔拖到"更竖"的位置 → **上下双曲线**（焦点在 y 轴）----
            //
            // 这一条正是用户说的"如果我选的是左右，就是左右；如果是上下，就是上下"：
            // 渐近线斜率 m = 480/240 = 2，第 2 笔拖到 (200, 500) 比渐近线**更竖**
            //（m·|dx| = 400 < 500）→ 焦点落在 y 轴；实半轴用**实轴沿 y**的式子反解：
            // a = √(500²·(240/480)² − 200²) = √(62500 − 40000) = 150、b = a × 2 = 300。
            // 报出来的"实半轴"就是 b = 300（实轴沿 y 时实半轴是纵向那个，见 HyperbolaRealLocal）。
            Doc.Clear();
            Doc.ClearHistory();
            SetToolFromUi(Tool.Hyperbola);
            float ux = _virtualX + 1500f, uy = _virtualY + 1300f;
            Drag(ux, uy, ux + 240f, uy + 480f);                   // 第 1 笔：渐近线（m = 2）
            Drag(ux, uy, ux + 200f, uy + 500f);                   // 第 2 笔：更竖 → 焦点在 y 轴

            var hypY = Doc.Strokes.Count == 1 ? Doc.Strokes[0] : null;
            Check("两笔式：第 2 笔拖到更竖的位置 → **上下双曲线**（实轴沿 y），半轴 300 / 150（±2）",
                  hypY != null && hypY.CurveAxis == CurveAxis.TransverseY
                  && Near(hypY.HyperbolaRealLocal(), 300f, 2f)
                  && Near(hypY.HyperbolaImagLocal(), 150f, 2f),
                  hypY == null ? $"对象 {Doc.Strokes.Count} 条（期望 1）"
                               : $"{hypY.CurveAxis}，实半轴 {hypY.HyperbolaRealLocal():F1}、"
                                 + $"虚半轴 {hypY.HyperbolaImagLocal():F1}");
            if (hypY != null)
            {
                // 同样要用**曲线的** x / y 方向系数（不是渐近线框的 A / B）。
                float fitY = 500f * 500f / (hypY.HyperbolaCurveBLocal() * hypY.HyperbolaCurveBLocal())
                           - 200f * 200f / (hypY.HyperbolaCurveALocal() * hypY.HyperbolaCurveALocal());
                // 容差比上面那条宽：鼠标坐标是**取整**的，一个像素的偏差在 a 只有 150 时
                // 相对误差是 a=330 时的两倍多（上面那条 ±0.01 就够，这条要放宽到 ±0.05）。
                Check("两笔式：上下双曲线也**正好经过那个点**（y²/b² − x²/a² = 1）（±0.05）",
                      Near(fitY, 1f, .05f), $"代入得 {fitY:F4}（期望 1）");
            }
        }

        Console.WriteLine();
        Console.WriteLine($"  合计 {pass + fail} 项：通过 {pass}，失败 {fail}");
        Console.WriteLine();
        _quit = true;
    }

    private void DashTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 线型自检（实线 / 虚线 / 点线）===");
        Console.WriteLine($"  本机 DPI 缩放 {DpiScale:F2}");

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-30} {detail}");
        }

        var ink = new Color4(1f, 0f, 1f, 1f);        // 品红：便于在屏幕上数像素
        float w = 6f * DpiScale;
        float len = 1000f;
        float rowGap = 150f;
        float x0 = _virtualX + 240f;
        float yTop = _virtualY + 240f;

        Stroke MakeLine(float y, StrokeDash dash)
        {
            var s = new Stroke
            {
                Tool = Tool.Line, Kind = StrokeKind.Line, Color = ink, Width = w, Dash = dash,
            };
            s.AddPoint(x0, y, 1f, NowMs);
            s.AddPoint(x0 + len, y, 1f, NowMs);
            return s;
        }

        bool SameBox(Stroke p, Stroke q)
        {
            var a = p.PaddedBounds; var b = q.PaddedBounds;
            // 只比**大小**不比位置：三条线故意画在不同的行上（同一行会互相盖住，
            // 屏幕上就数不出各自的墨量了），位置本来就该不一样。
            return MathF.Abs((a.MaxX - a.MinX) - (b.MaxX - b.MinX)) < 0.5f
                && MathF.Abs((a.MaxY - a.MinY) - (b.MaxY - b.MinY)) < 0.5f;
        }

        // ================= ① 屏幕层：三种线型上屏后的墨量 =================
        Doc.Clear();
        var solid = MakeLine(yTop, StrokeDash.Solid);
        var dashed = MakeLine(yTop + rowGap, StrokeDash.Dashed);
        var dotted = MakeLine(yTop + rowGap * 2f, StrokeDash.Dotted);
        Doc.AddStroke(solid);
        Doc.AddStroke(dashed);
        Doc.AddStroke(dotted);
        Doc.InvalidateAll();
        SettleFrames(700);

        float full = len * w;                        // 实线的"满墨量"基准
        int bandH = (int)MathF.Max(6f, w * 3f);
        int pxSolid = ScreenProbe.CountMagenta((int)x0, (int)(yTop - bandH * 0.5f), (int)len, bandH);
        int pxDashed = ScreenProbe.CountMagenta((int)x0, (int)(yTop + rowGap - bandH * 0.5f), (int)len, bandH);
        int pxDotted = ScreenProbe.CountMagenta((int)x0, (int)(yTop + rowGap * 2f - bandH * 0.5f), (int)len, bandH);

        Console.WriteLine();
        Console.WriteLine("  线型 | 屏幕墨量 | 占实线比例");
        Console.WriteLine("  -----|----------|-----------");
        Console.WriteLine($"  实线 | {pxSolid,8} | {pxSolid / full,9:P0}");
        Console.WriteLine($"  虚线 | {pxDashed,8} | {pxDashed / full,9:P0}");
        Console.WriteLine($"  点线 | {pxDotted,8} | {pxDotted / full,9:P0}");
        Console.WriteLine();

        Check("实线上屏：墨量接近满（≥85%）", pxSolid >= full * 0.85f,
              $"{pxSolid} / 理论 {full:F0}");
        Check("虚线上屏：出墨四到八成", pxDashed >= full * 0.40f && pxDashed <= full * 0.80f,
              $"{pxDashed / full:P0}（图案设计值 ~60%）");
        Check("点线上屏：出墨一成二到六成，且明显少于虚线",
              pxDotted >= full * 0.12f && pxDotted <= full * 0.60f && pxDotted < pxDashed * 0.8f,
              $"{pxDotted / full:P0} vs 虚线 {pxDashed / full:P0}");
        Check("三种线型的包围盒一模一样（线型是样式，不改形状）",
              SameBox(solid, dashed) && SameBox(solid, dotted),
              $"{solid.PaddedBounds.MaxX - solid.PaddedBounds.MinX:F0}×"
              + $"{solid.PaddedBounds.MaxY - solid.PaddedBounds.MinY:F0}");

        string shot = Path.Combine("reports", "线型-三种.bmp");
        bool saved = ScreenProbe.SaveBmp(shot, (int)(x0 - 60f), (int)(yTop - 60f), (int)(len + 120f), (int)(rowGap * 2f + 120f));
        Console.WriteLine(saved ? $"  （已导出 {shot}：实线 / 虚线 / 点线）" : "  导出失败");
        Console.WriteLine();

        // ================= ② 交互层：面板那一行真的能改、该跳过的会跳过 =================
        Doc.Clear();
        var shape = MakeLine(_virtualY + 400f, StrokeDash.Solid);
        var hand = new Stroke { Tool = Tool.Pen, Color = ink, Width = w };
        hand.AddPoint(x0, _virtualY + 560f, 0.5f, NowMs);
        hand.AddPoint(x0 + 300f, _virtualY + 560f, 0.5f, NowMs);
        var pic = new Stroke
        {
            Tool = Tool.Capture, Kind = StrokeKind.Image, Color = ink, Width = w,
            Image = ImageData.Adopt(8, 8, new byte[8 * 8 * 4], hasAlpha: true),
        };
        pic.AddPoint(x0, _virtualY + 700f, 1f, NowMs);
        pic.AddPoint(x0 + 80f, _virtualY + 780f, 1f, NowMs);
        Doc.AddStroke(shape);
        Doc.AddStroke(hand);
        Doc.AddStroke(pic);
        Doc.SelectOnly(new[] { shape, hand, pic });
        // ⚠ **必须切到框选工具**：操作条（和它下面那个线型面板）只在
        // `SelectionBarShown` 时画、也只在它时吃点击，而那个条件是
        // `有选中 && (框选工具 || 图形工具 || 刚停顿成型)`。
        // 这里以前是直接 `SelectOnly` 造出的选中、工具还停在笔上 → 面板画都不画，
        // 后面几次"打格子中心"当然全部接不住（2026-09-28 查"点线型那三格没反应"查到的）。
        // 真实用户的手法是"先框选"，所以测试也得先摆成那个状态。
        Tool = Tool.Marquee;
        Doc.InvalidateAll();
        SettleFrames(300);

        var aabb = LiveSelectionFrame.CanvasAabb;
        int sc = SelectionHandles.SwatchCount;
        var c0 = SelectionHandles.StyleCellRect(0, aabb, DpiScale, ViewportCanvas, sc);
        var c1 = SelectionHandles.StyleCellRect(1, aabb, DpiScale, ViewportCanvas, sc);
        var c2 = SelectionHandles.StyleCellRect(2, aabb, DpiScale, ViewportCanvas, sc);
        var panel = SelectionHandles.PanelRect(aabb, DpiScale, ViewportCanvas, sc);

        Check("线型那一行是 3 格", SelectionHandles.StyleCellCount == 3,
              $"格数 = {SelectionHandles.StyleCellCount}");
        Check("3 格从左到右排、互不重叠",
              c0.MaxX <= c1.MinX && c1.MaxX <= c2.MinX,
              $"{c0.MinX:F0}..{c0.MaxX:F0} | {c1.MinX:F0}..{c1.MaxX:F0} | {c2.MinX:F0}..{c2.MaxX:F0}");
        Check("3 格都落在面板里（四边都留了内边距）",
              c0.MinX >= panel.MinX && c2.MaxX <= panel.MaxX
              && c0.MinY >= panel.MinY && c0.MaxY <= panel.MaxY,
              $"面板 {panel.MinX:F0}..{panel.MaxX:F0}，格子 {c0.MinX:F0}..{c2.MaxX:F0}");

        // ---- 点那一行：**全程走真路** ----
        //
        // 早先这里直接调 `RunStyleClickForTest`（引擎里的测试钩子），**绕过了两层**：
        //   ① 「这一点算不算落在面板上」（`PanelContains`）——不在的话点击会被当成
        //      "点面板外面"，反手把面板关掉，用户看到的就是"点了没反应"；
        //   ② 「操作条那一格点了会不会开面板」。
        // 用户报"实线和虚线好像不能选中"时，这两层正是嫌疑最大的地方（引擎里那一层
        // 是连通的，所以只能靠真路把它钉死或抓出来）。现在按用户的手法走一遍：
        // 点操作条「颜色」→ 面板开 → 手势打格子中心。
        RunBarActionForTest((int)SelBarButton.Color);
        SettleFrames(200);
        Check("操作条「颜色」那一格能把线型面板打开",
              SelPanelOpen == SelPanel.Ink, $"面板 = {SelPanelOpen}");

        for (int i = 0; i < SelectionHandles.StyleCellCount; i++)
        {
            var cellI = SelectionHandles.StyleCellRect(i, aabb, DpiScale, ViewportCanvas, sc);
            float mx = (cellI.MinX + cellI.MaxX) * 0.5f, my = (cellI.MinY + cellI.MaxY) * 0.5f;
            Check($"第 {i + 1} 格的中心算「落在面板上」（命中那一层过得去）",
                  SelectionHandles.PanelContains(mx, my, aabb, DpiScale, ViewportCanvas,
                                                 SelPanelOpen, sc),
                  $"({mx:F0},{my:F0})，面板 {panel.MinX:F0}..{panel.MaxX:F0}"
                  + $" × {panel.MinY:F0}..{panel.MaxY:F0}");
        }

        bool StyleClick(int i)
        {
            var cell = SelectionHandles.StyleCellRect(i, aabb, DpiScale, ViewportCanvas, sc);
            bool took = SelectionGestureForTest((cell.MinX + cell.MaxX) * 0.5f,
                                                (cell.MinY + cell.MaxY) * 0.5f);
            EndSelectionGestureForTest();
            SettleFrames(160);
            return took;
        }

        var boxBefore = shape.PaddedBounds;
        bool tookDashed = StyleClick(1);
        Check("点第 2 格（虚线）：这一下被吞掉了（面板没被关掉）",
              tookDashed && SelPanelOpen == SelPanel.Ink,
              $"接住 = {tookDashed}，面板 = {SelPanelOpen}");
        Check("点第 2 格 → 直线变虚线", shape.Dash == StrokeDash.Dashed, $"实际 = {shape.Dash}");
        Check("同一次里：**自由笔迹也跟着改**（用户 2026-09-19 改的口径）",
              hand.Dash == StrokeDash.Dashed, $"实际 = {hand.Dash}");
        Check("同一次里：图像**没有**被改", pic.Dash == StrokeDash.Solid, $"实际 = {pic.Dash}");

        bool tookDotted = StyleClick(2);
        Check("点第 3 格（点线）：被吞掉且生效",
              tookDotted && shape.Dash == StrokeDash.Dotted,
              $"接住 = {tookDotted}，线型 = {shape.Dash}");

        var boxAfter = shape.PaddedBounds;
        Check("改线型不动包围盒",
              MathF.Abs(boxBefore.MinX - boxAfter.MinX) < 0.01f
              && MathF.Abs(boxBefore.MinY - boxAfter.MinY) < 0.01f
              && MathF.Abs(boxBefore.MaxX - boxAfter.MaxX) < 0.01f
              && MathF.Abs(boxBefore.MaxY - boxAfter.MaxY) < 0.01f,
              $"{boxBefore.MinX:F1},{boxBefore.MinY:F1} .. {boxBefore.MaxX:F1},{boxBefore.MaxY:F1} 未变");

        // 回到实线：**这一格最容易被当成"点了没反应"**——对象本来就是实线时点它是空操作，
        // 所以下面除了"线型真的回到 Solid"，还额外断言"格子的当前档真的跟着回去了"
        // （面板上要看得出来，不然用户只会觉得这一格坏了）。
        bool tookSolid = StyleClick(0);
        Check("点第 1 格（实线）：被吞掉、线型回到实线",
              tookSolid && shape.Dash == StrokeDash.Solid,
              $"接住 = {tookSolid}，线型 = {shape.Dash}");
        Check("面板认得出「现在是实线」（当前档读的是选中的那一条）",
              SelectionHandles.DashOfSelection(Doc.Selected) == StrokeDash.Solid,
              $"当前档 = {SelectionHandles.DashOfSelection(Doc.Selected)}");

        StyleClick(1);                                 // 再变虚线，留给下一条撤销用
        bool undoOk = Doc.Undo();
        Check("撤销一步 → 回到上一步的线型（改线型一步可撤）",
              undoOk && shape.Dash == StrokeDash.Solid, $"撤销 = {undoOk}，线型 = {shape.Dash}");
        Console.WriteLine();

        // ---- ②b 画布上点一条线能不能选中（实线 / 虚线都试）----
        //
        // 这一条**以前没有任何自检覆盖**（别的自检都是用 `Doc.SelectOnly` 直接给选中的）。
        // 用户说的"不能选中"如果是"画布上点不中"，就会在这里露出来。
        foreach (var (dash, name) in new[] { (StrokeDash.Solid, "实线"), (StrokeDash.Dashed, "虚线") })
        {
            Doc.Selected.Clear();
            SelPanelOpen = SelPanel.None;
            var ln = MakeLine(_virtualY + 400f, dash);
            Doc.Clear();
            Doc.AddStroke(ln);
            Doc.InvalidateAll();
            Tool = Tool.Marquee;
            SettleFrames(300);

            float midX = x0 + len * 0.5f, midY = _virtualY + 400f;
            bool tookPick = SelectionGestureForTest(midX, midY);
            EndSelectionGestureForTest();
            SettleFrames(200);
            Check($"画布上点一条{name}：能选中它",
                  tookPick && Doc.Selected.Count == 1 && Doc.Selected[0] == ln,
                  $"接住 = {tookPick}，选中 {Doc.Selected.Count} 个");
        }
        Console.WriteLine();

        // ============ ②c 笔的线型开关：画之前选 vs 画之后改 ============
        //
        // 用户 2026-09-19 第 2 件要的那个"笔的色带条上的虚实线切换"。引擎这一头只验一件事：
        // **开关切到哪一档，新画出来的笔迹就是哪一档**，而且**不碰已经画好的**。
        // 界面那一格本身（画在哪、点得到、三档轮回、极简档没有）在 `--paneltest` 里验——
        // "引擎吃不吃这个值"和"界面上有没有这个入口"是两件事，混在一起验的话
        // 坏了一处也看不出是哪一处。
        {
            Doc.Clear();
            Doc.ClearHistory();
            SetToolFromUi(Tool.Pen);
            SetDashFromUi(StrokeDash.Dashed);

            // 真机画一笔（合成鼠标按下 → 移动 → 抬起），返回刚画出来的那一条。
            Stroke DrawOne(float y)
            {
                float px = _virtualX + 600f;
                SendMouse((int)px, (int)y, 0);                                     SettleFrames(40);
                SendMouse((int)px, (int)y, Native.MOUSEEVENTF_LEFTDOWN);           SettleFrames(40);
                for (int i = 1; i <= 4; i++)
                {
                    SendMouse((int)(px + 60f * i), (int)y, 0);
                    SettleFrames(20);
                }
                SendMouse((int)(px + 240f), (int)y, Native.MOUSEEVENTF_LEFTUP);    SettleFrames(200);
                return Doc.Strokes.Count > 0 ? Doc.Strokes[^1] : null;
            }

            var first = DrawOne(_virtualY + 560f);
            Check("笔的线型：切到虚线之后，新画的一笔就是虚线",
                  first != null && first.Kind == StrokeKind.Freehand
                  && first.Dash == StrokeDash.Dashed,
                  first == null ? "没有对象" : $"{first.Kind}，线型 = {first.Dash}");

            SetDashFromUi(StrokeDash.Solid);
            var second = DrawOne(_virtualY + 700f);
            Check("笔的线型：开关只管以后——切回实线之后，**先画的那一笔还是虚线**",
                  first != null && first.Dash == StrokeDash.Dashed
                  && second != null && second.Dash == StrokeDash.Solid,
                  $"第一笔 {first?.Dash}，第二笔 {second?.Dash}");

            SetDashFromUi(StrokeDash.Solid);       // 收尾：别把开关留在非默认值上
        }
        Console.WriteLine();

        // ================= ③ 存档层：写文件读回来线型还在 =================
        Doc.Clear();
        var sa = MakeLine(_virtualY + 300f, StrokeDash.Dashed);
        var sb = MakeLine(_virtualY + 400f, StrokeDash.Dotted);
        var scLine = MakeLine(_virtualY + 500f, StrokeDash.Solid);
        Doc.AddStroke(sa);
        Doc.AddStroke(sb);
        Doc.AddStroke(scLine);

        byte[] blob = InkSerializer.Save(Doc);
        var back = new InkDocument();
        InkSerializer.LoadInto(back, blob);

        Check("存档读回 3 条都在", back.Strokes.Count == 3, $"读回 {back.Strokes.Count} 条");
        Check("虚线读回来还是虚线",
              back.Strokes.Count > 0 && back.Strokes[0].Dash == StrokeDash.Dashed,
              back.Strokes.Count > 0 ? $"实际 = {back.Strokes[0].Dash}" : "条数不对");
        Check("点线读回来还是点线",
              back.Strokes.Count > 1 && back.Strokes[1].Dash == StrokeDash.Dotted,
              back.Strokes.Count > 1 ? $"实际 = {back.Strokes[1].Dash}" : "条数不对");
        Check("**第二条**的几何也对（读端少读一位会在这里整体错位）",
              back.Strokes.Count > 1 && back.Strokes[1].Points.Count == 2
              && MathF.Abs(back.Strokes[1].Points[1].X - (x0 + len)) < 0.5f,
              back.Strokes.Count > 1
                  ? $"第二条第 2 点 X = {back.Strokes[1].Points[1].X:F1}（应 {(x0 + len):F1}）"
                  : "条数不对");

        // 真·v7 老文件（见 MakeLegacyFile）：这一条同时钉住两件事——
        // 老文件读得进、且读进来是实线（老文件本来的样子）。
        // 砍 5 位 = v8 线型 ＋ v9 网格 ＋ v10 压感 ＋ v11 朝向 ＋ v12 渐近线。
        var one = new InkDocument();
        one.AddStroke(MakeLine(_virtualY + 300f, StrokeDash.Dotted));
        byte[] v7 = MakeLegacyFile(one, 7, 5);
        var old = new InkDocument();
        bool oldOk = true;
        try { InkSerializer.LoadInto(old, v7); } catch (Exception ex) { oldOk = false; Console.WriteLine("    " + ex.Message); }
        Check("真·v7 老文件读得进，线型是实线",
              oldOk && old.Strokes.Count == 1 && old.Strokes[0].Dash == StrokeDash.Solid,
              oldOk ? $"{old.Strokes.Count} 条，线型 = {(old.Strokes.Count > 0 ? old.Strokes[0].Dash.ToString() : "?")}"
                    : "读取抛异常");

        Console.WriteLine();
        Console.WriteLine($"  合计 {pass + fail} 项：通过 {pass}，失败 {fail}");
        Console.WriteLine();
        _quit = true;
    }

    private void WidthTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 笔迹粗细渲染测试（填充带子会不会在粗笔画上出洞）===");
        Console.WriteLine($"  本机 DPI 缩放 {DpiScale:F2}");
        Console.WriteLine();
        Console.WriteLine("  逻辑宽度 | 物理宽度 | 理论墨量 | 实测墨量 | 覆盖率");
        Console.WriteLine("  ---------|----------|----------|----------|--------");

        Doc.Clear();
        int i = 0;
        foreach (float wLogical in WidthPresets)
        {
            float wPhys = wLogical * DpiScale;
            float y = _virtualY + 140 + i * 150;
            float x0 = _virtualX + 200;
            float x1 = _virtualX + 1600;

            var s = new Stroke { Tool = Tool.Pen, Color = new Color4(1f, 0f, 1f, 1f), Width = wPhys };
            for (int k = 0; k <= 120; k++)
            {
                float t = k / 120f;
                s.AddPoint(x0 + (x1 - x0) * t, y + MathF.Sin(t * 9f) * 40f, 1f, NowMs);
            }
            Doc.AddStroke(s);
            i++;
        }
        Doc.InvalidateAll();
        SettleFrames(700);

        i = 0;
        int bad = 0;
        foreach (float wLogical in WidthPresets)
        {
            float wPhys = wLogical * DpiScale;
            float y = _virtualY + 140 + i * 150;
            // The wavy path is ~1480 px of x plus the wiggle.
            float pathLen = 1560f;
            // 墨是"中心线 + 等宽描边"：宽度就是名义笔宽（压感不再影响粗细）。
            float expected = pathLen * wPhys;
            int actual = ScreenProbe.CountMagenta((int)(_virtualX + 190), (int)(y - 90), 1430, 180);
            Console.WriteLine($"  {wLogical,8:F1} | {wPhys,8:F0} | {expected,8:F0} | {actual,8} | {(actual / expected):F2}");
            // 判据：填充带子的墨量要落在理论值的合理区间里。明显偏小 = 自交处
            // 被挖空了（洞），明显偏大 = 重复填充。这条以前只有数字没有结论，
            // 于是"填充出洞"这种事必须靠人看图，现在它自己会红。
            float ratio = actual / expected;
            if (ratio < 0.75f || ratio > 1.15f) bad++;
            i++;
        }

        Console.WriteLine();
        Console.WriteLine(bad == 0
            ? "  PASS: 各档粗细的墨量都在理论值的 0.75~1.15 倍之间（填充没有出洞）"
            : $"  FAIL: 有 {bad} 档墨量偏离理论值（<0.75 或 >1.15）");
        _quit = true;
    }

    /// <summary>
    /// 脏区渲染特有的风险测试：双缓冲里躺着的是两帧前的画面，如果脏区没覆盖到
    /// 上一帧临时图元的位置，快速移动的橡皮光标/激光就会留下"残影"。
    /// 这里用大跨度快速移动橡皮光标，最后停在远处，然后数屏幕上还剩下多少
    /// 光标颜色的像素——只剩停住那一圈才算通过。
    /// </summary>
    /// <summary>
    /// 验证微软的委托墨迹轨迹是否真的在画：把自己那一笔关掉，
    /// 拖动过程中按住不放截图——如果还能看到笔迹，那就是系统合成器画的。
    /// </summary>
    /// <summary>
    /// 长跑测试：模拟"上一节课"的连续使用，看内存是否稳定、帧耗时是否劣化。
    /// 每轮画一批笔画，再做擦除/撤销/清空，并周期性记录状态。
    /// </summary>
    /// <summary>
    /// A/B 实测：几何实现缓存到底能省多少。
    /// A = 每次都让 Direct2D 重新细分几何（现状）
    /// B = 先把细分结果缓存下来，之后只提交三角形
    /// </summary>
    /// <summary>
    /// 分辨率实测：同样的笔画工作量，放到不同尺寸的离屏内容层上跑，
    /// 看哪些开销随像素数增长、哪些不增长。用来回答"4K 教室里够不够用"。
    /// </summary>
    private void ResolutionTest(int strokeCount)
    {
        Console.WriteLine();
        Console.WriteLine($"=== 分辨率实测（{strokeCount} 笔）===");
        Console.WriteLine("  内容层尺寸 | 图层内存 | 整层清屏+重画 | 20 次脏区补丁 | 每次补丁");
        Console.WriteLine("  -----------|----------|---------------|----------------|----------");

        GenerateStrokes(strokeCount);
        var ctx = _windows[0].Context;
        var pf = new Vortice.DCommon.PixelFormat(
            Vortice.DXGI.Format.B8G8R8A8_UNorm, Vortice.DCommon.AlphaMode.Premultiplied);

        (int w, int h, string label)[] sizes =
        {
            (1920, 1080, "1920x1080"),
            (2560, 1440, "2560x1440"),
            (2880, 1800, "2880x1800 当前屏"),
            (3840, 2160, "3840x2160 4K"),
        };

        foreach (var (w, h, label) in sizes)
        {
            double before = Mem.Priv();
            var bmp = ctx.CreateBitmap(new SizeI(w, h), IntPtr.Zero, 0,
                new BitmapProperties1(pf, 96f, 96f, BitmapOptions.Target | BitmapOptions.CannotDraw));

            // 先画一遍让缓存/显存真正落地
            RenderInto(bmp, strokeCount);
            double after = Mem.Priv();

            // 整层：清屏 + 画全部笔画
            var sw = Stopwatch.StartNew();
            RenderInto(bmp, strokeCount);
            sw.Stop();
            double full = sw.Elapsed.TotalMilliseconds;

            // 脏区补丁：取 20 个 300x300 的方块，清掉并重画落在里面的笔画
            var rnd = new Random(7);
            var swPatch = Stopwatch.StartNew();
            for (int i = 0; i < 20; i++)
            {
                var r = new RectF
                {
                    MinX = _virtualX + (float)rnd.NextDouble() * (w - 400),
                    MinY = _virtualY + (float)rnd.NextDouble() * (h - 400),
                    MaxX = 0, MaxY = 0,
                };
                r.MaxX = r.MinX + 300; r.MaxY = r.MinY + 300;
                PatchInto(bmp, r);
            }
            swPatch.Stop();
            double patch = swPatch.Elapsed.TotalMilliseconds;

            Console.WriteLine($"  {label,-12} | {after - before,6:F1}M | {full,11:F1}ms | {patch,12:F1}ms | {patch / 20,6:F2}ms");

            bmp.Dispose();
            Mem.TrimWorkingSet();
        }
        _quit = true;
    }

    private void RenderInto(ID2D1Bitmap1 target, int strokeCount)
    {
        var ctx = _windows[0].Context;
        ctx.Target = target;
        ctx.BeginDraw();
        ctx.Clear(new Vortice.Mathematics.Color4(0, 0, 0, 0));
        ctx.Transform = System.Numerics.Matrix3x2.CreateTranslation(-_virtualX, -_virtualY);
        int n = 0;
        foreach (var s in Doc.Strokes)
        {
            if (n++ >= strokeCount) break;
            _windows[0].DrawStrokeForTest(s);
        }
        ctx.Transform = System.Numerics.Matrix3x2.Identity;
        var hr = ctx.EndDraw();
        if (hr.Failure) Console.WriteLine("  RenderInto EndDraw 失败: " + hr.Description);
        try { ctx.Flush(out _, out _); } catch { /* 见报告说明：CreateBitmap 目标上 Flush 会报状态错误，四种分辨率一致，不影响横向对比 */ }
        ctx.Target = null;
    }

    private void PatchInto(ID2D1Bitmap1 target, RectF r)
    {
        var ctx = _windows[0].Context;
        ctx.Target = target;
        ctx.BeginDraw();
        ctx.Transform = System.Numerics.Matrix3x2.CreateTranslation(-_virtualX, -_virtualY);
        ctx.PushAxisAlignedClip(new Vortice.RawRectF(r.MinX, r.MinY, r.MaxX, r.MaxY),
            Vortice.Direct2D1.AntialiasMode.Aliased);
        _windows[0].ClearRectForTest(r);
        int n = 0;
        foreach (var s in Doc.Strokes)
        {
            if (!s.IntersectsRect(r)) continue;
            _windows[0].DrawStrokeForTest(s);
            if (++n > 400) break;
        }
        ctx.PopAxisAlignedClip();
        ctx.Transform = System.Numerics.Matrix3x2.Identity;
        var hr2 = ctx.EndDraw();
        if (hr2.Failure) Console.WriteLine("  PatchInto EndDraw 失败: " + hr2.Description);
        try { ctx.Flush(out _, out _); } catch { }
        ctx.Target = null;
    }


    private void LongRunTest(double seconds)
    {
        Console.WriteLine();
        Console.WriteLine($"=== 长跑测试（{seconds:F0} 秒，模拟连续上课使用）===");
        Console.WriteLine("  每轮：画 24 笔 → 擦掉几笔 → 撤销几次 → 偶尔清空");
        Console.WriteLine();
        Console.WriteLine("   时间 | 工作集 | 提交   | 笔画数 | 平均记录 | 平均上屏 | 最慢帧");
        Console.WriteLine("  ------|--------|--------|--------|----------|----------|--------");

        var started = _clock.Elapsed.TotalMilliseconds;
        double nextReport = 0;
        int round = 0;
        double worstFrame = 0;
        var recordSum = new List<double>();

        float cx = _virtualX + _virtualW * 0.5f;
        float cy = _virtualY + _virtualH * 0.5f;
        var rnd = new Random(4242);

        while (_clock.Elapsed.TotalMilliseconds - started < seconds * 1000)
        {
            round++;
            // 画 24 笔（直接构造笔画，省掉合成鼠标的等待时间，把 CPU 全留给渲染）
            var batch = new List<Stroke>();
            for (int i = 0; i < 24; i++)
            {
                var s = new Stroke { Tool = Tool.Pen, Color = PenColor, Width = 3f * DpiScale };
                float x = _virtualX + (float)rnd.NextDouble() * _virtualW;
                float y = _virtualY + (float)rnd.NextDouble() * _virtualH;
                float ang = (float)(rnd.NextDouble() * Math.PI * 2);
                for (int k = 0; k < 24; k++)
                {
                    ang += (float)((rnd.NextDouble() - 0.5) * 0.7);
                    x += MathF.Cos(ang) * 12f;
                    y += MathF.Sin(ang) * 12f;
                    s.AddPoint(x, y, 0.8f, NowMs);
                }
                Doc.AddStroke(s);
                batch.Add(s);
            }
            NowMs = _clock.Elapsed.TotalMilliseconds;
            RenderAll();

            // 擦掉几笔
            for (int i = 0; i < 6 && batch.Count > 0; i++)
            {
                var s = batch[rnd.Next(batch.Count)];
                Doc.EraseAt(s.Bounds.MinX + 1, s.Bounds.MinY + 1, 20f);
            }
            NowMs = _clock.Elapsed.TotalMilliseconds;
            RenderAll();

            // 撤销几次
            for (int i = 0; i < 8; i++) Doc.Undo();
            NowMs = _clock.Elapsed.TotalMilliseconds;
            RenderAll();

            // 每 8 轮清空一次，模拟换一页
            if (round % 8 == 0) { Doc.Clear(); RenderAll(); }

            recordSum.Add(_windows[0].LastRecordMs);
            if (_windows[0].LastRecordMs > worstFrame) worstFrame = _windows[0].LastRecordMs;
            if (recordSum.Count > 60) recordSum.RemoveAt(0);

            double elapsed = (_clock.Elapsed.TotalMilliseconds - started) / 1000.0;
            if (elapsed >= nextReport)
            {
                nextReport += 15;
                double avg = 0;
                foreach (var v in recordSum) avg += v;
                avg = recordSum.Count > 0 ? avg / recordSum.Count : 0;
                Console.WriteLine($"  {elapsed,5:F0}s | {Mem.Ws(),5:F1}M | {Mem.Priv(),5:F1}M | {Doc.Strokes.Count,6} | {avg,7:F2}ms | {_windows[0].LastPresentMs,7:F2}ms | {worstFrame,5:F2}ms");
            }
        }

        Console.WriteLine();
        Console.WriteLine($"  结束：工作集 {Mem.Ws():F1} MB，提交 {Mem.Priv():F1} MB，笔画 {Doc.Strokes.Count}，共 {round} 轮");
        Console.WriteLine($"  最慢单帧记录耗时：{worstFrame:F2} ms");
        _quit = true;
    }

    private void InkTrailTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 委托墨迹轨迹测试（关掉自己画的湿墨）===");
        Console.WriteLine($"  接口状态: {OverlayWindow.InkTrailNote}");

        Doc.Clear();
        Doc.InvalidateAll();
        Tool = Tool.Pen;
        SuppressActiveStroke = true;

        SettleFrames(300);

        float cx = _virtualX + _virtualW * 0.5f;
        float cy = _virtualY + _virtualH * 0.5f;
        int bandX = (int)(cx - 500);
        int bandY = (int)(cy - 140);

        // 按住不放，慢慢画一段，然后**在按住的状态下**截图
        SendMouse((int)(cx - 400), (int)cy, 0);
        SettleFrames(120);
        SendMouse((int)(cx - 400), (int)cy, Native.MOUSEEVENTF_LEFTDOWN);
        SettleFrames(100);
        for (int i = 1; i <= 40; i++)
        {
            float t = i / 40f;
            SendMouse((int)(cx - 400 + t * 800), (int)(cy + MathF.Sin(t * 6.28f) * 80), 0);
            SettleFrames(18);
        }
        SettleFrames(250);   // 仍然按着

        int whileDown = ScreenProbe.CountRed(bandX, bandY, 1000, 280);
        string shot1 = Path.Combine("reports", "shots", "trail-while-down.bmp");
        Directory.CreateDirectory(Path.GetDirectoryName(shot1));
        ScreenProbe.SaveBmp(shot1, _virtualX, _virtualY, _virtualW, _virtualH);

        SendMouse((int)(cx + 400), (int)cy, Native.MOUSEEVENTF_LEFTUP);
        SettleFrames(600);
        int afterUp = ScreenProbe.CountRed(bandX, bandY, 1000, 280);

        Console.WriteLine($"  按住不放时笔迹像素: {whileDown}（这些只能是系统合成器画的）");
        Console.WriteLine($"  松手之后笔迹像素  : {afterUp}（我们自己的笔画接管）");
        Console.WriteLine($"  轨迹调试          : {OverlayWindow.InkTrailDebug}");
        Console.WriteLine($"  截图: {Path.GetFullPath(shot1)}");

        bool ok = whileDown > 800;
        // 委托墨迹轨迹**只对真笔（PT_PEN）生效**（鼠标下系统根本不接这条通道）。
        // 这个用例是用合成鼠标事件跑的，所以鼠标下量不到轨迹是预期结果，
        // 不该报成失败——原来这里一直红着，害得"全套自检"里有一条永远修不掉。
        bool mouseRun = LastPointerType != Native.PT_PEN;
        Console.WriteLine(ok ? "  PASS: 委托墨迹轨迹生效"
                        : mouseRun
                            ? "  SKIP: 当前是鼠标（轨迹只对真笔生效），这一项不适用"
                            : "  FAIL: 手上是真笔却没看到系统画的轨迹");
        _quit = true;
    }

    // =====================================================================
    //  压感采集与笔迹预测的自检
    // =====================================================================

    /// <summary>
    /// 笔迹预测自检（**纯算法**：不需要真笔、不需要屏幕、不画东西）。
    /// 把 `调研-压感与预测-原理.md` 第三节里那些"别甩墨"的约束逐条变成断言。
    /// </summary>
    private void PredictorTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 笔迹预测自检（纯算法）===");
        int pass = 0, fail = 0;
        void Check(string what, bool ok, string detail)
        {
            Console.WriteLine($"  {(ok ? "PASS" : "FAIL")}: {what,-36} {detail}");
            if (ok) pass++; else fail++;
        }

        var pred = new PredictedPoint[8];
        static InkPredictor New(double horizonMs = 10.0)
        {
            var p = new InkPredictor { HorizonMs = horizonMs };
            p.ClampHorizon();
            return p;
        }

        // 1) 直线匀速：v = 1 px/ms，地平线 10 ms，阻尼 0.7 → 最远点应在 7 px 处
        {
            var p = New();
            p.Damping = 0.70f;                                  // 显式给值，别跟默认值耦合
            p.Add(0, 0, 0); p.Add(5, 0, 5); p.Add(10, 0, 10);
            int n = p.Predict(pred);
            float dx = n > 0 ? pred[n - 1].X - 10f : float.NaN;
            Check("直线匀速：给出预测点且在前方", n >= 1 && dx > 0, $"点数 {n}，位移 {dx:F2} px");
            Check("直线匀速：位移 = v·τ·阻尼", n >= 1 && MathF.Abs(dx - 7f) < 0.5f, $"期望 7.00，实得 {dx:F2}");
            Check("直线匀速：时间单调递增且不超过地平线",
                  n >= 2 && pred[0].TimeMs > 10 && pred[n - 1].TimeMs <= 20.01 &&
                  pred[1].TimeMs > pred[0].TimeMs,
                  n >= 2 ? $"{pred[0].TimeMs:F1} → {pred[n - 1].TimeMs:F1} ms（最后一点 = 起点 + 10）" : "点不够");
            Check("默认阻尼就是数据扫出来的 0.80", MathF.Abs(new InkPredictor().Damping - 0.80f) < 1e-6f,
                  $"{new InkPredictor().Damping:F2}");
        }

        // 2) 匀加速：二阶项应让它比"只用速度"更远（但被 AccelDamping 收着）
        {
            var p = New();
            p.Add(0, 0, 0); p.Add(5, 0, 5); p.Add(11, 0, 10);   // v: 1 → 1.2，a = 0.04 px/ms²
            int n = p.Predict(pred);
            float dx = n > 0 ? pred[n - 1].X - 11f : float.NaN;
            float firstOrder = 1.2f * 10f * 0.7f;               // 只算速度项
            Check("匀加速：比一阶更远（加速度项生效）", n >= 1 && dx > firstOrder + 0.2f,
                  $"二阶 {dx:F2} > 一阶 {firstOrder:F2}");
            Check("匀加速：加速度被衰减，不会失控", n >= 1 && dx < firstOrder + 3f, $"二阶 {dx:F2}");
        }

        // 3) 慢速不预测：速度低于阈值时返回 0 个点（慢写时预测只有抖动没有收益）
        {
            var p = New();
            p.Add(0, 0, 0); p.Add(0.05f, 0, 5);                 // v = 0.01 px/ms < 0.02
            int n = p.Predict(pred);
            Check("慢速：不预测", n == 0, $"速度 {p.Speed:F3} px/ms → 点数 {n}");
        }

        // 4) 断笔重置：相邻采样间隔 > 20 ms 就当新的一笔（Chromium 的 kMaxTimeDelta）
        {
            var p = New();
            p.Add(0, 0, 0); p.Add(5, 0, 5);
            p.Add(100, 0, 105);                                 // 间隔 100 ms
            int n = p.Predict(pred);
            Check("断笔：间隔 100 ms 后重置", p.Count == 1 && n == 0, $"队列长度 {p.Count}，点数 {n}");
        }

        // 5) 反向/急转：新点与当前速度反向 → 丢掉速度，这一帧不预测（拐弯处最容易甩墨）
        {
            var p = New();
            p.Add(0, 0, 0); p.Add(10, 0, 10);                   // v = +1
            p.Add(-1, 0, 20);                                   // 立刻反向
            int n = p.Predict(pred);
            Check("急转：反向时丢掉速度", MathF.Abs(p.Speed) < 0.001f && n == 0,
                  $"速度 {p.Speed:F3} px/ms，点数 {n}");
        }

        // 6) 限幅：极快速度下，预测段长度被 MaxDistance 截住（兜底，防长尾）
        {
            var p = New();
            p.Add(0, 0, 0); p.Add(500, 0, 5);                   // v = 100 px/ms
            int n = p.Predict(pred);
            float dx = n > 0 ? pred[n - 1].X - 500f : float.NaN;
            Check("限幅：位移不超过 MaxDistance", n >= 1 && dx <= p.MaxDistance + 0.01f,
                  $"位移 {dx:F2} px（上限 {p.MaxDistance}）");
        }

        // 7) 地平线夹取：命令行传进来的值会被收进 8~硬上限。
        //    **别把推荐区间（8~15）当夹取区间**：真机调手感时要能把地平线调到远超推荐值，
        //    否则"过头有多难受"这件事根本看不出来（2026-09-22 用户要 --predictms 100 时才拆开）。
        {
            var lo = New(1.0); var hi = New(100.0); var over = New(1e6);
            Check("地平线：低于 8 ms 收到 8", Math.Abs(lo.HorizonMs - 8) < 0.001, $"{lo.HorizonMs}");
            Check("地平线：100 ms 照收（推荐区间之外仍然可调）",
                  Math.Abs(hi.HorizonMs - 100) < 0.001, $"{hi.HorizonMs}");
            Check($"地平线：超过硬上限 {InkPredictor.HardMaxHorizonMs:F0} ms 才收住",
                  Math.Abs(over.HorizonMs - InkPredictor.HardMaxHorizonMs) < 0.001, $"{over.HorizonMs}");
        }

        // 8) 点数与上限：按采样间隔铺满地平线；**最后一点必须落在正地平线上**
        //    （实测教训：只铺到"离地平线最近的那个整数倍"，5 ms 采样 + 8 ms 地平线会少补 3 ms）
        {
            var p = New(10);
            p.Add(0, 0, 0); p.Add(3, 0, 3); p.Add(6, 0, 6);      // 间隔 3 ms
            int n = p.Predict(pred);
            Check("点数：3 ms 间隔 + 10 ms 地平线 → 铺到地平线",
                  n == 4 && Math.Abs(pred[n - 1].TimeMs - 16.0) < 1e-6,
                  $"点数 {n}，最后一点 {pred[n - 1].TimeMs:F1} ms（应 = 6 + 10）");

            var p8 = New(8);
            p8.Add(0, 0, 0); p8.Add(5, 0, 5); p8.Add(10, 0, 10); // 间隔 5 ms
            int n8 = p8.Predict(pred);
            Check("地平线不被采样间隔截短（8 ms + 5 ms 采样）",
                  n8 == 2 && Math.Abs(pred[n8 - 1].TimeMs - 18.0) < 1e-6,
                  $"点数 {n8}，最后一点 {pred[n8 - 1].TimeMs:F1} ms（应 = 10 + 8）");

            var p2 = New(15);
            p2.MaxPoints = 4;
            for (int i = 0; i < 8; i++) p2.Add(i * 1.0f, 0, i * 1.0);   // 1 ms 间隔
            int n2 = p2.Predict(pred);
            Check("点数：不超过 MaxPoints", n2 <= p2.MaxPoints, $"点数 {n2}（上限 {p2.MaxPoints}）");
        }

        // 9) 成本：预测必须是"顺手就做了"，不能进性能预算
        {
            var p = New();
            const int N = 200_000;
            p.Add(0, 0, 0); p.Add(5, 0, 5); p.Add(10, 0, 10);
            var sw = Stopwatch.StartNew();
            int acc = 0;
            for (int i = 0; i < N; i++)
            {
                p.Add(10 + i * 0.001f, 0, 10 + i * 0.005);
                acc += p.Predict(pred);
            }
            sw.Stop();
            double us = sw.Elapsed.TotalMilliseconds * 1000.0 / N;
            Check("成本：每次 < 5 µs", us < 5.0, $"{us:F3} µs/次（累计预测 {acc} 个点）");
        }

        Console.WriteLine($"  合计：{pass} 项通过，{fail} 项失败");
        Console.WriteLine(fail == 0 ? "  PASS: 预测器自检全部通过" : "  FAIL: 预测器自检有失败项");
        _quit = true;
    }

    // ---- 预测尾（鼠标 / 触摸那条路）--------------------------------------
    /// <summary>
    /// 预测尾自检：验"鼠标 / 触摸写出来的墨，末端回到了现在"这条链路的四件事。
    ///
    ///   ① 几何层：尾巴真的接进了几何；**清掉之后几何要回到原样**——这一条专门盯
    ///      几何缓存的键（键里少了"尾版本"，清尾之后会把带尾的旧几何还回来）；
    ///   ② 模型层：尾不进点数、不进包围盒，收笔后也不留在文档里（存档/导出都看不见它）；
    ///   ③ **压感变宽那条渲染路（ID2D1Ink）也要带上尾**：真笔必报压感，走的正是这一路。
    ///      这一条是 2026-09-22 补的——原来只测了"无压感 → 等宽描边"那条，结果
    ///      "鼠标甩得出来、手写板毫无反应"这个 bug 全绿通过（漏的就是这里）；
    ///   ④ 引擎层：真实鼠标拖一笔，`POINTER_INFO` 那条新分支真的在跑，读到的点一个不丢；
    ///   ⑤ 屏幕层：同一位置做"开预测 / 关预测"的 A/B——开着时前方那一带的墨明显更多，
    ///      多出来的就是尾巴（顺便证明尾收掉之后那几个像素被擦干净了）。
    ///
    /// 为什么用 SendInput 的真鼠标、而不是合成笔：这条路的用户场景就是"手写板没开
    /// Windows Ink（设备以 `PT_MOUSE` 上报）"和"触摸屏"，而合成笔走的是 `PT_PEN` 分支，
    /// 验不到这里。真鼠标还会真的产生合并点（一批连发、中间不抽消息），这正是 ③ 要的。
    /// </summary>
    private void PredictTailTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 预测尾自检（鼠标 / 触摸那条路）===");
        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-40} {detail}");
        }

        Doc.Clear();
        Doc.ClearHistory();
        Doc.InvalidateAll();
        // 相机归零：屏幕层的像素判据要按"画布 → 屏幕"换算，相机不动才换得准。
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        Tool = Tool.Pen;
        SettleFrames(150);

        // ---- ① / ② 几何与模型：不依赖任何输入设备 ----
        {
            var s = new Stroke
            {
                Tool = Tool.Pen,
                Kind = StrokeKind.Freehand,
                Color = new Color4(1f, 0f, 0f, 1f),
                Width = 6f,
            };
            s.AddPoint(100, 100, 0.5f, 0);
            s.AddPoint(200, 100, 0.5f, 1);

            var b0 = s.BuildGeometry(Gfx.D2DFactory).GetWidenedBounds(6f, Gfx.Round, 0.25f);

            var tail = new List<Vector2> { new(240f, 100f) };
            s.SetRenderTail(tail);
            var b1 = s.BuildGeometry(Gfx.D2DFactory).GetWidenedBounds(6f, Gfx.Round, 0.25f);
            Check("渲染尾接进了几何（右边界往外长了约 40 px）",
                  b1.Right > b0.Right + 30f,
                  $"无尾 {b0.Right:F1} → 有尾 {b1.Right:F1}");

            s.SetRenderTail(null);
            var b2 = s.BuildGeometry(Gfx.D2DFactory).GetWidenedBounds(6f, Gfx.Round, 0.25f);
            Check("尾清掉之后几何回到原样（几何缓存的键带了尾版本，不会还回旧几何）",
                  MathF.Abs(b2.Right - b0.Right) < 0.5f,
                  $"清掉后 {b2.Right:F1}，原本 {b0.Right:F1}");

            Check("渲染尾不进模型：点数还是 2、最后一个点还在 200",
                  s.Points.Count == 2 && MathF.Abs(s.Points[^1].X - 200f) < 0.01f,
                  $"点数 {s.Points.Count}，末点 x {s.Points[^1].X:F2}");
        }

        // ---- ③ 压感变宽那条渲染路（ID2D1Ink）也要带上尾 ----
        //
        // 为什么单开这一条：**真笔必然报压感**，于是一定走 DrawPressureInk 那条路，
        // 而它当初只按 `s.Points` 建 ink 对象——尾被整个丢掉。上面 ① 走的是
        // "无压感 → 等宽描边"，所以照不出这个漏（2026-09-22 用户实测抓到的原话：
        // "还是鼠标甩，手写板不甩"，而两边的 [笔画] 都报"预测尾=有（最多 100 px）"）。
        {
            var probe = new Stroke
            {
                Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                Color = new Color4(1f, 0f, 0f, 1f), Width = 12f,
                HasPressure = true,                       // ← 关键：这一位决定走哪条渲染路
            };
            probe.AddPoint(0f, 0f, 0.3f, 0);
            probe.AddPoint(40f, 0f, 0.6f, 8);
            probe.AddPoint(80f, 0f, 0.9f, 16);
            probe.SetRenderTail(new List<Vector2> { new(120f, 0f), new(160f, 0f) });

            // 离屏渲染（和导出/剪贴板同一条 DrawStroke），取景框把尾那一段包进来。
            var reg = new RectF { MinX = -30, MinY = -30, MaxX = 190, MaxY = 30 };
            int draws0 = OverlayWindow.PressureInkDraws;
            var bgra = _windows.Count > 0
                ? _windows[0].RenderStrokesToBgra(new[] { probe }, reg, 220, 60) : null;
            Check("有压感的笔迹确实走了变宽那条路（ID2D1Ink）",
                  OverlayWindow.PressureInkDraws > draws0,
                  $"变宽绘制次数 {draws0} → {OverlayWindow.PressureInkDraws}");

            // 取景框 1:1 → 像素 x = 画布 x + 30。只数"最后一个真实点(80)之外"那一段：
            // 从像素 130（画布 100，已经越过末点的圆头）到 215。
            int tailRed = 0;
            if (bgra != null)
                for (int y = 0; y < 60; y++)
                    for (int x = 130; x < 215; x++)
                    {
                        int i = (y * 220 + x) * 4;
                        if (i + 3 < bgra.Length && bgra[i + 2] > 170 && bgra[i + 1] < 110 && bgra[i] < 110)
                            tailRed++;
                    }
            Check("有压感的笔迹，预测尾也画得出来（这条以前漏掉了）",
                  tailRed > 0,
                  $"末点之外那一段红像素 {tailRed} 个（漏掉时是 0）");
        }

        // ---- ④ / ⑤ 真鼠标拖一笔 ----
        {
            var oldColor = CurrentColor;
            CurrentColor = new Color4(1f, 0f, 1f, 1f);      // 品红：屏幕上好数
            int msg0 = PtrMessages, samp0 = PtrSamples;

            float x0 = _virtualX + _virtualW * 0.34f;
            float y0 = _virtualY + _virtualH * 0.34f;
            const int Burst = 40;                            // 一口气连发的点数
            float stepX = 8f;

            SendMouse((int)x0, (int)y0, 0);
            SettleFrames(80);
            SendMouse((int)x0, (int)y0, Native.MOUSEEVENTF_LEFTDOWN);
            SettleFrames(40);

            // 一批连发、**中间一次消息都不抽**，看这条新分支收到多少点。
            for (int i = 1; i <= Burst; i++) SendMouse((int)(x0 + stepX * i), (int)y0, 0);
            SettleFrames(30);
            int msg1 = PtrMessages, samp1 = PtrSamples;
            int moves = _cntMove;                  // 引擎自己记的"收到几条移动消息"

            // 判据只说我们自己的代码该保证的事：**这条新分支真的在跑，而且读到的点一个不丢**。
            //
            // 这里刻意**不**拿"采样点数 > 消息数"当判据：鼠标几乎不产生合并点——系统对
            // 鼠标输入只保留最新位置（实测连发 40 个点，应用只收到 2 条消息），
            // 合并点是触摸与笔才有的现象。触摸屏上能拿到多少合并点，在真机上跑
            // `--penlive` 看 `[笔画] ... 合并(N 条消息 → M 个采样点)` 那一行即可。
            Check("鼠标这条路在读 POINTER_INFO（新分支真的在跑）",
                  samp1 - samp0 > 0,
                  $"{msg1 - msg0} 条消息 → {samp1 - samp0} 个采样点（系统只投递了 {moves} 条移动）");

            var live = ActiveStroke;
            Check("读到的采样点一个不丢地进了这一笔",
                  live != null && live.Points.Count >= samp1 - samp0 && samp1 - samp0 > 0,
                  $"笔画点数 {live?.Points.Count ?? 0}，读到采样点 {samp1 - samp0}");

            // **A 组之前显式把预测打开**：2026-09-29 起预测默认关（自绘尾会"突突"跳），
            // 自检不能依赖启动默认值——B 组会显式关掉、再复原成开。
            PredictEnabled = true;

            // 再走几小批，让"帧与帧之间"有速度 → 预测器才肯出点（慢速它会主动不给）。
            //
            // **必须"等到这一刻模型里真的有尾"再量像素**：指针偶尔会送来一个"没动"的
            // 采样点，速度掉到 MinSpeed 之下 → 预测器主动收尾（那是正确行为）。
            // 第一次写这段时就撞上了：尾长量到 0、A 组红像素 0 个，看着像"功能没生效"。
            int tailMax = 0;
            float leadMax = 0;
            float x1 = x0 + stepX * Burst;
            int inkOn = -1, ax = 0, ay = 0;
            float leadOn = 0;
            for (int b = 1; b <= 30 && inkOn < 0; b++)
            {
                for (int k = 1; k <= 4; k++)
                    SendMouse((int)(x1 + 10f * ((b - 1) * 4 + k)), (int)(y0 + 3f * b), 0);
                SettleFrames(17);
                if (RenderTailPoints > tailMax) { tailMax = RenderTailPoints; leadMax = PredictedTailLead; }
                if (RenderTailPoints > 0)
                {
                    leadOn = PredictedTailLead;
                    inkOn = MagentaAhead(out ax, out ay);   // A 组：这一刻屏上"末点前方"有多少墨
                }
            }
            Check("拖动过程中预测尾真的产生了", tailMax > 0,
                  $"尾最多 {tailMax} 个点、最长 {leadMax:F1} px");

            // ⑤ 屏幕层。麻烦在于"最后一个真实点前方 5~15 px"那一带**不止尾巴**：
            //    落点反馈圆环也画在指针那儿。所以这里做 **A/B**：
            //       A = 开着预测（那一带有圆环 + 尾巴）
            //       B = 关掉预测再走一小批（那一带只剩圆环）
            //    A 明显多于 B，多出来的就只能是尾巴。顺带把脏区扩边也测了：
            //    尾收掉之后旧尾巴那几个像素必须被擦干净，擦不掉的话 B 会跟 A 一样多。
            int MagentaAhead(out int ox, out int oy)
            {
                ox = oy = 0;
                var st = ActiveStroke;
                if (st == null || st.Points.Count < 2) return -1;
                var a = st.Points[^2];
                var b = st.Points[^1];
                float dx = b.X - a.X, dy = b.Y - a.Y;
                float len = MathF.Sqrt(dx * dx + dy * dy);
                if (len < 0.01f) return -1;
                // 沿运动方向往前 11 px：真实采样点最远只到 0，这一段只可能是画出来的东西。
                ox = (int)(b.X + dx / len * 11f);
                oy = (int)(b.Y + dy / len * 11f + ViewOffsetY);
                var buf = ScreenProbe.CaptureRegion(ox - 5, oy - 5, 11, 11);
                int ink = 0;
                for (int i = 0; i + 3 < buf.Length; i += 4)
                    if (buf[i + 2] > 190 && buf[i + 1] < 90 && buf[i] > 190) ink++;   // BGRA 里的品红
                return ink;
            }

            // ---- B 组：关掉预测，同一套动作再来一次 ----
            PredictEnabled = false;
            int inkOff = -1, bx = 0, by = 0;
            for (int b = 1; b <= 12 && inkOff < 0; b++)
            {
                for (int k = 1; k <= 4; k++)
                    SendMouse((int)(x1 + 400f + 10f * ((b - 1) * 4 + k)), (int)(y0 + 34f), 0);
                SettleFrames(17);
                if (RenderTailPoints == 0) inkOff = MagentaAhead(out bx, out by);
            }
            PredictEnabled = true;                        // ---- 复原 ----

            Check("最后一个真实点的前方有墨，而且关掉预测就没那么多 = 那些墨就是尾巴",
                  inkOn > 0 && inkOff >= 0 && inkOn > inkOff + 8,
                  $"开预测 ({ax},{ay}) {inkOn} 个 → 关预测 ({bx},{by}) {inkOff} 个；尾长 {leadOn:F1} px");

            SendMouse((int)(x1 + 400f), (int)(y0 + 40f), Native.MOUSEEVENTF_LEFTUP);
            SettleFrames(250);

            var committed = Doc.Strokes.Count > 0 ? Doc.Strokes[^1] : null;
            Check("收笔后这一条没有渲染尾（尾不会留在文档里）",
                  committed != null && committed.RenderTail == null,
                  committed == null ? "文档里没有笔画" : $"尾点数 {committed.RenderTail?.Count ?? 0}");

            CurrentColor = oldColor;
        }

        Console.WriteLine();
        Console.WriteLine($"  合计：{pass} 项通过，{fail} 项失败");
        Console.WriteLine(fail == 0 ? "  PASS: 预测尾自检全部通过" : "  FAIL: 预测尾自检有失败项");
        Doc.Clear();
        Doc.ClearHistory();
        Doc.InvalidateAll();
        SettleFrames(120);
        _quit = true;
    }

    /// <summary>
    /// 触摸自检（合成触摸注入）。单开这一条的理由：**触摸这条路只有触摸踩得到**——
    /// 鼠标和笔一次只有一个指针，于是"多指 / 掌根"那一类分支从来没被任何自检走到过。
    /// 2026-09-22 就是在这一片里抓到"第二根手指抢走正在写的那一笔"（写一半的字凭空消失）。
    ///
    /// 四件事：
    ///   ① 合成触摸以 `PT_TOUCH` 真进来（不是被当成鼠标）；
    ///   ② 触摸这一笔建得起来、点收得下；
    ///   ③ 触摸照样有预测尾（触摸没压感 → 走等宽描边那条渲染路，与真笔的 ink 那条不同）；
    ///   ④ **第二根手指按下时，正在写的那一笔不能被换掉**，而且第一根手指还能接着写。
    /// </summary>
    private void TouchGuardTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 触摸自检（合成触摸注入）===");
        if (!EnsureSyntheticTouch())
        {
            Console.WriteLine("  SKIP: 拿不到合成触摸设备（CreateSyntheticPointerDevice(PT_TOUCH) 失败）");
            Console.WriteLine("        这条只能在真触摸屏上手工验：写一笔的同时用另一根手指碰屏，"
                              + "正在写的字不许消失、笔也不许被抢走。");
            _quit = true;
            return;
        }

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-40} {detail}");
        }

        Doc.Clear();
        Doc.ClearHistory();
        Doc.InvalidateAll();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        Tool = Tool.Pen;
        var oldColor = CurrentColor;
        CurrentColor = new Color4(1f, 0f, 1f, 1f);
        SettleFrames(150);

        float x0 = _virtualX + _virtualW * 0.34f;
        float y0 = _virtualY + _virtualH * 0.45f;

        // ---- ① 单指按下，看它是不是以 PT_TOUCH 进来 ----
        SendTouches(true, (x0, y0));
        SettleFrames(30);
        Check("合成触摸以 PT_TOUCH 进来", LastPointerType == Native.PT_TOUCH,
              $"LastPointerType = {DeviceName(LastPointerType)}");

        // ---- ② 走一段，让速度和预测器都活起来；③ 看有没有尾 ----
        int tailMax = 0;
        float cx = x0;
        for (int i = 1; i <= 14; i++)
        {
            cx = x0 + 14f * i;
            SendTouches(true, (cx, y0));
            SettleFrames(17);
            if (RenderTailPoints > tailMax) tailMax = RenderTailPoints;
        }
        var live = ActiveStroke;
        Check("触摸这一笔建起来了、点在往里进",
              live != null && live.Points.Count > 5,
              live == null ? "ActiveStroke 为 null" : $"笔画点数 {live.Points.Count}");
        Check("触摸这一笔照样有预测尾（走等宽描边那条渲染路）", tailMax > 0,
              $"尾最多 {tailMax} 个点、当前 {RenderTailPoints} 个、前带量 {PredictedTailLead:F1} px");

        // ---- ④ 第二根手指按下：正在写的那一笔不许被换掉 ----
        var before = ActiveStroke;
        int downBefore = _cntDown;
        int ptsBefore = before?.Points.Count ?? 0;
        SendTouches(true, (cx, y0), (x0, y0 + 200f));      // ← 第二根手指落屏
        SettleFrames(30);

        Check("第二根手指的按下真的到了引擎（不然下一条会假绿）",
              _cntDown > downBefore, $"_cntDown {downBefore} → {_cntDown}");
        Check("第二根手指不许抢走正在写的那一笔",
              ReferenceEquals(ActiveStroke, before), "ActiveStroke 被换成了新对象就是抢走了");
        Check("那一笔已经写下的点一个都没丢",
              before != null && before.Points.Count >= ptsBefore,
              $"{ptsBefore} → {before?.Points.Count ?? 0}");

        // 第一根手指还得能接着写（指针没被抢走）
        cx += 14f;
        SendTouches(true, (cx, y0), (x0, y0 + 200f));
        SettleFrames(30);
        Check("第二根手指按着的时候，第一根手指还能接着写",
              ReferenceEquals(ActiveStroke, before) && before != null && before.Points.Count > ptsBefore,
              $"{ptsBefore} → {before?.Points.Count ?? 0}");

        // ---- 收尾：两根一起抬，交进文档 ----
        SendTouches(false, (cx, y0), (x0, y0 + 200f));
        SettleFrames(250);
        var committed = Doc.Strokes.Count > 0 ? Doc.Strokes[^1] : null;
        Check("松手后这一笔进了文档，而且没带渲染尾",
              committed != null && committed.RenderTail == null,
              committed == null ? "文档里没有笔画" : $"点数 {committed.Points.Count}");

        CurrentColor = oldColor;
        Console.WriteLine();
        Console.WriteLine($"  合计：{pass} 项通过，{fail} 项失败");
        Console.WriteLine(fail == 0 ? "  PASS: 触摸自检全部通过" : "  FAIL: 触摸自检有失败项");
        Doc.Clear();
        Doc.ClearHistory();
        Doc.InvalidateAll();
        SettleFrames(120);
        _quit = true;
    }

    /// <summary>
    /// 书写期间 GC 低延迟档自检（见 GcLatency.cs）。
    ///
    /// 为什么单开一条：这是**新机制，而且它的失效方式是"悄悄没生效"**——设置被系统拒绝，
    /// 或者后台 GC 被关掉的时候，它只是不工作，屏幕上一点异常都看不出来。
    /// 所以要验三件眼睛看不见的事：
    ///   ① 写一笔的时候真的处于 SustainedLowLatency；
    ///   ② 这一笔期间**没有第 2 代回收**（那正是低配机上"卡一下"的元凶）；
    ///   ③ 超过保持窗口之后**真的退得回来**（不退的话堆一直不压缩，内存越用越多）。
    /// 顺带验分配 / GC 仪表本身有没有在记数——仪表坏了，后面所有低配优化都没有依据。
    /// </summary>
    private void GcLatencyTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 书写期间 GC 低延迟档自检 ===");
        if (!GcLatency.Enabled)
        {
            Console.WriteLine("  SKIP: --nogclatency 关掉了它（那是做「开/不开」对照测量用的，不是失败）");
            _quit = true;
            return;
        }

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-46} {detail}");
        }

        var oldHold = GcLatency.HoldMs;
        GcLatency.HoldMs = 150;                 // 自检里不用等 5 秒
        GcLatency.EnterCount = GcLatency.ExitCount = 0;
        StrokesMeasured = StrokesWithGc2 = 0;

        Doc.Clear();
        Doc.ClearHistory();
        Doc.InvalidateAll();
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        Tool = Tool.Pen;
        SettleFrames(150);

        // ---- 真拖一笔（和 --predicttailtest 同一套注入）----
        float x0 = _virtualX + _virtualW * 0.30f;
        float y0 = _virtualY + _virtualH * 0.50f;
        SendMouse((int)x0, (int)y0, Native.MOUSEEVENTF_LEFTDOWN);
        bool sawOn = false;
        for (int i = 1; i <= 10; i++)
        {
            SendMouse((int)(x0 + 16f * i), (int)(y0 + 2f * i), 0);
            SettleFrames(17);
            if (GcLatency.On) sawOn = true;
        }
        // **笔画尽头也必须还在低延迟档里**：第一版只在"按下"那一刻刷新保持窗口，
        // 一笔拖得比窗口长就会在**笔画中途**退出来（越写越容易卡，正好相反）。
        // 这一条就是钉住那个 bug 的。
        bool onAtEnd = GcLatency.On;
        Check("整笔（含笔画末端）都处于低延迟档", sawOn && onAtEnd,
              $"中途见到={(sawOn ? "是" : "否")}、末端={(onAtEnd ? "是" : "否")}；{GcLatency.Describe()}");
        SendMouse((int)(x0 + 160f), (int)y0, Native.MOUSEEVENTF_LEFTUP);
        SettleFrames(200);

        Check("低延迟档至少进去过一次", GcLatency.EnterCount > 0, GcLatency.Describe());
        Check("这一笔期间没有第 2 代回收", StrokesWithGc2 == 0,
              $"第 2 代出现在 {StrokesWithGc2} 笔里；这一笔 GC {StrokeGc0}/{StrokeGc1}/{StrokeGc2}");
        Check("分配仪表真的在记数", StrokeAllocBytes > 0,
              $"这一笔分配 {StrokeAllocBytes / 1024.0:F1} KB"
              + "（阈值等有了低配基线再定，这一条只验仪表通了）");
        if (GcLatency.FailNote != null)
            Console.WriteLine($"  注意：这台机器上低延迟档不可用——{GcLatency.FailNote}");

        // ---- ③ 超时退回：等过保持窗口，并持续渲染（Tick 挂在每帧渲染里）----
        var sw = System.Diagnostics.Stopwatch.StartNew();
        while (sw.Elapsed.TotalMilliseconds < GcLatency.HoldMs + 80) SettleFrames(20);
        Check("超过保持窗口后退回默认档", !GcLatency.On && GcLatency.ExitCount > 0, GcLatency.Describe());

        GcLatency.HoldMs = oldHold;
        Console.WriteLine();
        Console.WriteLine($"  合计：{pass} 项通过，{fail} 项失败");
        Console.WriteLine(fail == 0 ? "  PASS: GC 低延迟档自检全部通过" : "  FAIL: GC 低延迟档自检有失败项");
        Doc.Clear();
        Doc.ClearHistory();
        Doc.InvalidateAll();
        SettleFrames(120);
        _quit = true;
    }

    // ---- 合成笔（自检注入用）--------------------------------------------
    private IntPtr _syntheticPen;

    // ---- 合成触摸（自检注入用）------------------------------------------
    //
    // 为什么触摸需要单独一份：**POINTER_TYPE_INFO 的 union 里最大的是
    // POINTER_TOUCH_INFO（136 字节）**，而我们那个结构体只声明了 pen 分支（120 字节）
    // 加 24 字节填充，总长 148 —— 够放，而且两个分支的**开头都是同一份 POINTER_INFO**，
    // 所以按 pen 的字段名填、把 type 设成 PT_TOUCH 就能造出一个触摸触点。
    private IntPtr _syntheticTouch;

    private bool EnsureSyntheticTouch()
    {
        if (_syntheticTouch != IntPtr.Zero) return true;
        // maxCount = 2：触摸**可以同时有两个触点**，这正是"多指守卫"要用的。
        _syntheticTouch = Native.CreateSyntheticPointerDevice(
            Native.PT_TOUCH, 2, Native.POINTER_FEEDBACK_DEFAULT);
        return _syntheticTouch != IntPtr.Zero;
    }

    /// <summary>
    /// 注入合成触摸。`points` 是"这一刻**所有**按在屏上的触点"，下标就是触点序号
    /// （系统按 pointerId 跟踪，所以每次调用都要把还按着的触点一起带上）。
    /// `contact=false` 表示全部抬起。
    ///
    /// 触摸没有压感，所以 penMask / pressure 一律不给——与真实触摸一致。
    /// </summary>
    private void SendTouches(bool contact, params (float x, float y)[] points)
    {
        var arr = new Native.POINTER_TYPE_INFO[points.Length];
        for (int i = 0; i < points.Length; i++)
        {
            arr[i].type = Native.PT_TOUCH;
            arr[i].pen.pointerInfo.pointerType = Native.PT_TOUCH;
            arr[i].pen.pointerInfo.pointerId = (uint)(i + 1);
            arr[i].pen.pointerInfo.pointerFlags =
                Native.POINTER_FLAG_INRANGE | Native.POINTER_FLAG_CONFIDENCE
                | (contact ? Native.POINTER_FLAG_INCONTACT : 0u)
                | (i == 0 ? Native.POINTER_FLAG_PRIMARY : 0u);
            arr[i].pen.pointerInfo.ptPixelLocationX = (int)points[i].x;
            arr[i].pen.pointerInfo.ptPixelLocationY = (int)points[i].y;
            arr[i].pen.pointerInfo.hwndTarget = _windows.Count > 0 ? _windows[0].Hwnd : IntPtr.Zero;
        }
        Native.InjectSyntheticPointerInput(_syntheticTouch, arr, (uint)arr.Length);
    }

    private bool EnsureSyntheticPen()
    {
        if (_syntheticPen != IntPtr.Zero) return true;
        _syntheticPen = Native.CreateSyntheticPointerDevice(Native.PT_PEN, 1, Native.POINTER_FEEDBACK_DEFAULT);
        return _syntheticPen != IntPtr.Zero;
    }

    /// <summary>注入一个合成笔采样点，走的是和真笔同一条 WM_POINTER 路径。</summary>
    private void SendPenPoint(float x, float y, uint pressure, bool contact, bool first)
    {
        var arr = new Native.POINTER_TYPE_INFO[1];
        uint flags = Native.POINTER_FLAG_INRANGE | Native.POINTER_FLAG_CONFIDENCE;
        if (contact) flags |= Native.POINTER_FLAG_INCONTACT;
        if (first) flags |= Native.POINTER_FLAG_NEW | Native.POINTER_FLAG_PRIMARY | Native.POINTER_FLAG_FIRSTBUTTON;

        arr[0].type = Native.PT_PEN;
        arr[0].pen.pointerInfo.pointerType = Native.PT_PEN;
        arr[0].pen.pointerInfo.pointerFlags = flags;
        arr[0].pen.pointerInfo.ptPixelLocationX = (int)x;
        arr[0].pen.pointerInfo.ptPixelLocationY = (int)y;
        arr[0].pen.pointerInfo.hwndTarget = _windows.Count > 0 ? _windows[0].Hwnd : IntPtr.Zero;
        arr[0].pen.penFlags = 0;
        arr[0].pen.penMask = Native.PEN_MASK_PRESSURE;
        arr[0].pen.pressure = pressure;
        Native.InjectSyntheticPointerInput(_syntheticPen, arr, 1);
    }

    /// <summary>
    /// 压感采集诊断：用合成笔注入一条**已知**的轨迹（点数、节奏、压力都已知），
    /// 然后看引擎收下了多少点、合并点有没有读全、压感有效位判得对不对。
    ///
    /// 这个用例的价值在于它**不依赖真笔**：注入 160 个点、每帧塞 4 个，
    /// 系统必然把其中几条合并成一条消息——如果合并点没读全，笔画的点数会明显少于 160。
    /// </summary>
    private void PressureDiagTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 压感采集诊断（合成笔注入）===");
        if (!EnsureSyntheticPen())
        {
            Console.WriteLine("  SKIP: 拿不到合成笔设备（CreateSyntheticPointerDevice 失败）");
            _quit = true; return;
        }

        Doc.Clear();
        Doc.InvalidateAll();
        Tool = Tool.Pen;
        SettleFrames(120);

        float cx = _virtualX + _virtualW * 0.5f;
        float cy = _virtualY + _virtualH * 0.5f;
        const int PerFrame = 4;
        const int Frames = 40;
        int injected = 0;

        SendPenPoint(cx - 300, cy, 200, contact: true, first: true);
        injected++;

        for (int f = 0; f < Frames; f++)
        {
            // 每帧塞 PerFrame 个点：系统会把它们合并进同一条消息（这正是要测的）
            for (int k = 0; k < PerFrame; k++)
            {
                float t = (f * PerFrame + k) / (float)(Frames * PerFrame);
                SendPenPoint(cx - 300 + t * 600, cy + MathF.Sin(t * 6.28f) * 40,
                             (uint)(200 + t * 700), contact: true, first: false);
                injected++;
            }
            SettleFrames(1);        // 抽一次消息：这一帧应该把合并的几个点一起读进来
        }

        SendPenPoint(cx + 300, cy, 400, contact: false, first: false);   // 抬笔
        SettleFrames(60);

        int strokePoints = 0, withPressure = 0;
        float pMin = 9f, pMax = -1f;
        if (Doc.Strokes.Count > 0)
        {
            var s = Doc.Strokes[^1];
            strokePoints = s.Points.Count;
            foreach (var pt in s.Points)
            {
                if (pt.P > 0f && MathF.Abs(pt.P - 0.5f) > 0.001f) withPressure++;
                pMin = MathF.Min(pMin, pt.P);
                pMax = MathF.Max(pMax, pt.P);
            }
        }

        double ratio = LastCoalescedMessages > 0 ? LastCoalescedSamples / (double)LastCoalescedMessages : 0;
        Console.WriteLine($"  注入采样点            : {injected}");
        Console.WriteLine($"  引擎收到的消息 / 采样点: {LastCoalescedMessages} / {LastCoalescedSamples}（每条消息平均 {ratio:F2} 个点）");
        Console.WriteLine($"  本笔判定有无压感       : {(ActiveStrokeHasPressure ? "有" : "无")}");
        Console.WriteLine($"  落到笔画里的点数       : {strokePoints}（其中带压感的 {withPressure} 个）");
        Console.WriteLine($"  压力范围              : {(pMax >= 0 ? $"{pMin:F3} ~ {pMax:F3}" : "（没有点）")}");
        Console.WriteLine($"  设备                  : {DeviceName(LastPointerType)}");
        Console.WriteLine($"  湿墨轨迹              : 开关={(OverlayWindow.InkTrailEnabled ? "开" : "关")}"
                          + $"，预测={(PredictEnabled ? $"开（{PredictHorizonMs:F0} ms）" : "关")}"
                          + $"，最后一次调用={OverlayWindow.InkTrailDebug}");

        bool readAll = strokePoints >= injected * 0.8;
        bool coalesced = ratio > 1.3;
        bool pressureOk = ActiveStrokeHasPressure && pMax - pMin > 0.3f;

        Console.WriteLine(readAll
            ? $"  PASS: 合并点读全了（{strokePoints} ≥ 注入 {injected} 的 80%）"
            : $"  FAIL: 点数明显少于注入（{strokePoints} vs {injected}）——合并点没读全");
        Console.WriteLine(coalesced
            ? $"  PASS: 确实发生了合并（每条消息 {ratio:F2} 个点）"
            : $"  WARN: 这次没观察到合并（每条消息 {ratio:F2} 个点），用例的说服力打折");
        Console.WriteLine(pressureOk
            ? "  PASS: 压感有效位与压力数值都对"
            : $"  FAIL: 压感判定不对（有压感={ActiveStrokeHasPressure}，范围 {pMin:F3}~{pMax:F3}）");

        _quit = true;
    }

    /// <summary>
    /// 压感自检（2026-09-20 加：用户有了手写笔之后要"和人家一样、手感正常"）。
    ///
    /// 四层判据，缺一层都可能"看着绿其实没做"：
    ///   ① **映射**（纯函数）：0 压 = 最小倍、满压 = 最大倍、单调、gamma 真的起作用；
    ///   ② **上屏**（真机路径）：合成笔注入**从用户那张三线图反推回来的**几个力度
    ///      （鼠标参照 / 轻描 0.17 / 半压 0.50 / 重压 0.86 / 满压 1.00），量出来的**墨量比**
    ///      必须对得上那张图（0.33× / 1.00× / 1.72× / 2.00×）——只看 `HasPressure` 那一位的话，
    ///      渲染没接上也会是绿的；
    ///   ③ **回退**：鼠标画的（没有压感）与**虚线**笔迹必须仍然**等宽**（老路一个字没改）；
    ///   ④ **存档**：v10 往返把"有压感"这一位带回来；再造一个**真·v9 老文件**，
    ///      读进来必须是"没有压感"（老文件本来就没这一位）——版本闸写错时唯一会炸的地方。
    ///   ⑤ **离屏那条路**（导出 / 剪贴板那张图）：换的是渲染目标，同一条 DrawStroke，
    ///      但"同一个入口"这种事只有真画一遍、数一遍像素才算数。
    ///
    /// 顺带断言"最粗那一处**点得中**"：命中按最粗处算，否则重压的地方看得见、点不着。
    /// </summary>
    private void PressureTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 压感自检（映射 / 上屏粗细 / 回退 / 存档）===");
        Console.WriteLine($"  本机 DPI 缩放 {DpiScale:F2}；变宽通道: {OverlayWindow.InkNote}");

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-38} {detail}");
        }

        // ================= ① 映射：纯函数先钉死 =================
        {
            float f0 = PressureWidth.Factor(0f), f1 = PressureWidth.Factor(1f), fh = PressureWidth.Factor(0.5f);
            Check("映射：0 压 = 最小倍、满压 = 最大倍、中点居中",
                  MathF.Abs(f0 - PressureWidth.Min) < 1e-4f && MathF.Abs(f1 - PressureWidth.Max) < 1e-4f
                  && fh > f0 && fh < f1,
                  $"{f0:F3} / {fh:F3} / {f1:F3}（配置 {PressureWidth.Min:F2}~{PressureWidth.Max:F2}）");

            bool mono = true;
            float prev = -1f;
            for (int i = 0; i <= 20; i++)
            {
                float f = PressureWidth.Factor(i / 20f);
                if (f < prev - 1e-5f) mono = false;
                prev = f;
            }
            Check("映射：整条曲线单调不减", mono, "0 → 1 走一遍");

            float linear = PressureWidth.Factor(0.25f);
            PressureWidth.Gamma = 2f;
            float curved = PressureWidth.Factor(0.25f);
            PressureWidth.Gamma = 1f;
            Check("映射：gamma 真的起作用（>1 把轻压区间压低）",
                  curved < linear - 1e-4f, $"线性 {linear:F3} → gamma=2 {curved:F3}");
        }

        if (!EnsureSyntheticPen())
        {
            Console.WriteLine("  SKIP: 拿不到合成笔设备（CreateSyntheticPointerDevice 失败），②③④ 没法验");
            Console.WriteLine($"  合计 {pass + fail} 项：通过 {pass}，失败 {fail}");
            _quit = true; return;
        }

        // 画面要干净：开白板（底色不透明）、关掉委托湿墨（免得系统画的那条轨迹混进探针）。
        bool oldBoard = BoardOn, oldTrail = OverlayWindow.InkTrailEnabled;
        float oldPenWidth = PenWidthLogical;
        var oldColor = CurrentColor;
        BoardOn = true;
        OverlayWindow.InkTrailEnabled = false;
        PenWidthLogical = 6f;                        // 粗一点：粗细差在像素上更稳
        SetColorFromUi(new Color4(1f, 0f, 0f, 1f));  // 纯红：探针数红像素
        Doc.Clear();
        Doc.ClearHistory();
        Tool = Tool.Pen;
        ViewOffsetY = 0f;                            // 画布坐标 == 屏幕坐标，探针才好对位
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }
        SettleFrames(300);

        float cx = _virtualX + _virtualW * 0.5f;
        float cy = _virtualY + _virtualH * 0.5f;
        const float halfLen = 260f;

        void PenLine(float y, uint pressure)
        {
            SendPenPoint(cx - halfLen, y, pressure, contact: true, first: true);
            for (int i = 1; i <= 24; i++)
            {
                SendPenPoint(cx - halfLen + i * (halfLen * 2f / 24f), y, pressure, contact: true, first: false);
                SettleFrames(2);
            }
            SendPenPoint(cx + halfLen, y, pressure, contact: false, first: false);
            SettleFrames(200);
        }

        // ================= ② 上屏：对齐用户在 WPF 里画的那三条线 =================
        //
        // 用户在同一台机上画了三条横线（鼠标 / 笔轻轻描 / 笔重重压），我们逐像素量出来
        // 18.0 / 6.0 / 31.0 px，并且 WPF 官方文档写明"无压感设备的 PressureFactor 默认 0.5"，
        // 于是反推出那张图的口径：**鼠标 = 0.5 压力处 = 档位宽度；满压 = 2 倍**。
        //
        // 所以下面每条笔迹的压力都是**从那三条线反推回来的值**，判据直接对着它们比：
        //   鼠标（参照 1.00×）→ 轻描 0.17（图里 0.33×）→ 半压 0.50（应当和鼠标一样粗）
        //   → 重压 0.86（图里 1.72×）→ 满压 1.00（外推 2.00×）→ 虚线（回退等宽的对照）
        float yMouse = cy - 300f, yLight = cy - 210f, yHalf = cy - 120f;
        float yHeavy = cy - 30f, yFull = cy + 60f, yDash = cy + 150f;

        // ① 鼠标：没有压感那一路。**它是整段的参照物**（WPF 里那支笔的"中值压力"）。
        SendMouse((int)(cx - halfLen), (int)yMouse, 0);
        SendMouse((int)(cx - halfLen), (int)yMouse, Native.MOUSEEVENTF_LEFTDOWN);
        for (int i = 1; i <= 12; i++)
        {
            SendMouse((int)(cx - halfLen + i * (halfLen * 2f / 12f)), (int)yMouse, 0);
            SettleFrames(3);
        }
        SendMouse((int)(cx + halfLen), (int)yMouse, Native.MOUSEEVENTF_LEFTUP);
        SettleFrames(250);

        PenLine(yLight, 174);      // 0.17 轻轻描
        PenLine(yHalf, 512);       // 0.50 半压（应当和鼠标那条一样粗）
        PenLine(yHeavy, 881);      // 0.86 重重压
        PenLine(yFull, 1024);      // 1.00 满压

        // 虚线 + 满压：**本该最粗**，但 ink 通道不吃 dash 图案，必须回退等宽。
        SetDashFromUi(StrokeDash.Dashed);
        SettleFrames(120);
        PenLine(yDash, 1024);
        SetDashFromUi(StrokeDash.Solid);

        // 墨量 = 在笔迹正上方量一块固定大小的框，**按覆盖率求和**（面积 ∝ 线宽）。
        //
        // 为什么不用"数红像素"：抗锯齿会把细线的两侧边缘渲成"半红的过渡色"，
        // 严格按红色阈值数就会漏掉它们——2.8 像素宽的线只数到 2 像素（−29%），
        // 而 12 像素宽的只少 8%。这个**偏置随线宽变化**，会把比值整体放大
        // （实测：真实 3.71 倍量出来是 5.00 倍，2026-09-20 就是这么假红了一条）。
        // 覆盖率是**线性叠加**的：红墨 g=0、白板 g=255，所以每个像素的墨覆盖 = (255−g)/255。
        double Area(float y)
        {
            var px = ScreenProbe.CaptureRegion((int)cx - 200, (int)y - 30, 400, 60);
            double sum = 0;
            for (int i = 0; i + 3 < px.Length; i += 4)
            {
                int g = px[i + 1], r = px[i + 2];             // BGRA
                if (r > g + 30) sum += (255.0 - g) / 255.0;   // 只算偏红的像素，免得把底纹算进去
            }
            return sum;
        }
        // 粗细（竖直游程）= 虚线那种"有缝"的笔迹要看最粗的地方，所以横向多切几刀取最大。
        int MaxThick(float y)
        {
            int best = 0;
            for (int dx = -120; dx <= 120; dx += 20)
                best = Math.Max(best, ScreenProbe.CountRed((int)cx + dx - 1, (int)y - 40, 2, 80));
            return best;
        }

        double aMouse = Area(yMouse), aLight = Area(yLight), aHalf = Area(yHalf);
        double aHeavy = Area(yHeavy), aFull = Area(yFull), aDash = Area(yDash);

        Check("上屏：六条笔迹都真的画出来了",
              aMouse > 0 && aLight > 0 && aHalf > 0 && aHeavy > 0 && aFull > 0 && aDash > 0,
              $"鼠标 {aMouse:F0} / 轻 {aLight:F0} / 半 {aHalf:F0} / 重 {aHeavy:F0} / 满 {aFull:F0} / 虚线 {aDash:F0}");
        Check("上屏：压力越大墨越多（单调）",
              aLight < aHalf && aHalf < aHeavy && aHeavy < aFull,
              $"{aLight:F0} < {aHalf:F0} < {aHeavy:F0} < {aFull:F0}");

        // ---- 下面四条是**对着用户那三条线**比的（这就是"和 Windows Ink 对齐了没有"）----
        double rHalf = aMouse > 0 ? aHalf / aMouse : 0;
        Check("上屏：半压（0.50）那条 = 鼠标那条（±10%）——「无压感设备压力 0.5」这条前提的验证",
              rHalf >= 0.90 && rHalf <= 1.10, $"半压/鼠标 = {rHalf:F2}");

        double rLight = aMouse > 0 ? aLight / aMouse : 0;
        Check("上屏：轻描（0.17）= 鼠标的 0.33 倍（图里 6.0/18.0 = 0.333）",
              rLight >= 0.28 && rLight <= 0.42, $"轻描/鼠标 = {rLight:F2}");

        double rHeavy = aMouse > 0 ? aHeavy / aMouse : 0;
        Check("上屏：重压（0.86）= 鼠标的 1.72 倍（图里 31.0/18.0 = 1.72）",
              rHeavy >= 1.55 && rHeavy <= 1.90, $"重压/鼠标 = {rHeavy:F2}");

        double rFull = aMouse > 0 ? aFull / aMouse : 0;
        Check("上屏：满压 = 鼠标的 2.00 倍（图上外推值）",
              rFull >= 1.85 && rFull <= 2.15, $"满压/鼠标 = {rFull:F2}");

        // 诊断：分清"没走变宽那条路"和"走了但屏幕上没画出来"（后者是一种可能的失败形态：
        // API 全部返回成功、却一个像素都没有——2026-09-20 就是这么踩到 NibTransform 那个坑的）。
        int wholeScreenRed = ScreenProbe.CountRed(_virtualX, _virtualY, _virtualW, _virtualH);
        Console.WriteLine($"    [诊断] 变宽墨迹绘制次数 = {OverlayWindow.PressureInkDraws}；"
                          + $"全屏红像素 = {wholeScreenRed}；"
                          + $"六条笔迹 y = {yMouse:F0}/{yLight:F0}/{yHalf:F0}/{yHeavy:F0}/{yFull:F0}/{yDash:F0}，"
                          + $"画布偏移 {ViewOffsetY:F0}");

        // 离屏那条路（导出 / 剪贴板给外部程序的那张图）也要画得出变宽墨——它换的是渲染目标，
        // 代码上同一条 DrawStroke，但"同一个入口"这种事只有真画一遍才算数。
        {
            var probe = new Stroke
            {
                Tool = Tool.Pen, Color = new Color4(1f, 0f, 0f, 1f), Width = 12f, HasPressure = true,
            };
            probe.AddPoint(0f, 0f, 0.2f, 0);
            probe.AddPoint(100f, 0f, 0.9f, 8);
            var reg = new RectF { MinX = -40, MinY = -40, MaxX = 140, MaxY = 40 };
            var bgra = _windows.Count > 0 ? _windows[0].RenderStrokesToBgra(new[] { probe }, reg, 180, 80) : null;
            int offRed = 0;
            if (bgra != null)
                for (int i = 0; i + 3 < bgra.Length; i += 4)
                    if (bgra[i + 2] > 170 && bgra[i + 1] < 110 && bgra[i] < 110) offRed++;
            Check("离屏那条路（导出 / 剪贴板那张图）也画得出变宽墨",
                  offRed > 0, $"离屏位图里红像素 {offRed}（位图 {bgra?.Length ?? 0} 字节）");
        }

        // ================= ③ 命中与回退：按"这一笔自己的最粗处"算 =================
        {
            // 按压力**找**两条笔迹（不按索引——自检里写死下标会随功能移位而静默失效）。
            Stroke Light() => Doc.Strokes.FirstOrDefault(
                s => s.Kind == StrokeKind.Freehand && !s.IsImage && s.HasPressure
                     && s.Points.Count > 0 && s.Points[0].P < 0.3f);
            Stroke Full() => Doc.Strokes.FirstOrDefault(
                s => s.Kind == StrokeKind.Freehand && !s.IsImage && s.HasPressure
                     && s.Points.Count > 0 && s.Points[0].P > 0.95f);
            var light = Light();
            var full = Full();

            Check("命中：轻写那条按**它自己**的最粗处算（比档位半宽窄）",
                  light != null && light.MaxHalfWidth < light.Width * 0.5f - 0.5f,
                  light == null ? "没找到轻写那条"
                                : $"最粗半宽 {light.MaxHalfWidth:F2} vs 档位半宽 {light.Width * 0.5f:F2}");
            Check("命中：满压那条 = 档位宽（半宽 = 档位宽本身，因为满压是 2 倍）",
                  full != null && MathF.Abs(full.MaxHalfWidth - full.Width) < 0.3f,
                  full == null ? "没找到满压那条"
                               : $"最粗半宽 {full.MaxHalfWidth:F2} vs 档位宽 {full.Width:F2}");
            float edgeY = yFull + full.Width - 1f;      // 满压边缘往里 1 像素
            Check("命中：满压那条在最粗边缘点得中",
                  full != null && full.HitTestExact(cx, edgeY, 0f),
                  $"点 ({cx:F0},{edgeY:F0})");
        }

        {
            var ms = Doc.Strokes.FirstOrDefault(s => !s.IsImage && !s.HasPressure);
            Check("回退：鼠标画的这一条没有压感标志",
                  ms != null && !ms.HasPressure, ms == null ? "没找到鼠标那条" : "HasPressure = False");
            // 没有压感 → 等宽 = 档位宽度；虚线也一样（ink 通道不吃 dash 图案）。
            // 三条都用同一个探针量**粗细**（虚线有缝，取横向最大值），所以可以直接比。
            int tm = MaxThick(yMouse), td = MaxThick(yDash), tf = MaxThick(yFull);
            Check("回退：虚线笔迹仍然是等宽（粗细 = 档位宽，不随压力变）",
                  td > 0 && td <= tm * 1.25f,
                  $"虚线 {td} 像素 vs 档位 {tm} 像素");
            Check("回退：满压那条确实画粗了（≈ 2 × 档位，证明它没走回退那条路）",
                  tf > 0 && tf >= tm * 1.6f,
                  $"满压 {tf} 像素 vs 档位 {tm} 像素");
            var ds = Doc.Strokes.FirstOrDefault(s => s.Dash == StrokeDash.Dashed);
            Check("回退：虚线笔迹**确实带压感**（不是没压感才等宽）",
                  ds != null && ds.HasPressure, ds == null ? "没找到虚线那条" : $"HasPressure = {ds.HasPressure}");
        }

        // 荧光笔不吃压感（对齐官方示例的 IgnorePressure = true）：拿合成笔写一条荧光笔，
        // 断言它**不带压感标志**（也就是会走等宽那条路）。
        {
            Host.Commands.SetTool(Tool.Highlighter);
            SetColorFromUi(new Color4(1f, 0.6f, 0f, 1f));
            SettleFrames(120);
            PenLine(yDash + 90f, 1024);
            var hl = Doc.Strokes.FirstOrDefault(s => s.Tool == Tool.Highlighter);
            Check("荧光笔不吃压感（官方示例的 IgnorePressure = true 同款）",
                  hl != null && !hl.HasPressure,
                  hl == null ? "没找到荧光笔那条" : $"HasPressure = {hl.HasPressure}");
            Host.Commands.SetTool(Tool.Pen);
            SetColorFromUi(new Color4(1f, 0f, 0f, 1f));
            SettleFrames(120);
        }
        Doc.Clear();
        Doc.ClearHistory();
        SettleFrames(150);

        // ================= ④ 存档：v10 往返 + 真·v9 老文件 =================
        {
            var s = new Stroke { Tool = Tool.Pen, Color = new Color4(0f, 0f, 0f, 1f), Width = 12f, HasPressure = true };
            s.AddPoint(10f, 10f, 0.2f, 0);
            s.AddPoint(60f, 10f, 0.9f, 8);
            var d1 = new InkDocument();
            d1.AddStroke(s);
            var back = new InkDocument();
            InkSerializer.LoadInto(back, InkSerializer.Save(d1));
            Check("存档：v10 往返把「有压感」带回来",
                  back.Strokes.Count == 1 && back.Strokes[0].HasPressure,
                  back.Strokes.Count == 1 ? $"HasPressure = {back.Strokes[0].HasPressure}" : "条数不对");

            // 真·v9 老文件（见 MakeLegacyFile）：读进来必须是"没有压感"。
            var d2 = new InkDocument();
            d2.AddStroke(new Stroke { Tool = Tool.Pen, Color = new Color4(0f, 0f, 0f, 1f), Width = 12f, HasPressure = true });
            d2.Strokes[0].AddPoint(10f, 10f, 0.5f, 0);
            d2.Strokes[0].AddPoint(60f, 10f, 0.5f, 8);
            // 砍 3 位 = v10 压感 ＋ v11 朝向 ＋ v12 渐近线（v13 没加字段）。
            byte[] v9 = MakeLegacyFile(d2, 9, 3);
            var old = new InkDocument();
            bool ok = true;
            try { InkSerializer.LoadInto(old, v9); }
            catch (Exception ex) { ok = false; Console.WriteLine("    " + ex.Message); }
            Check("存档：真·v9 老文件读得进、且是「没有压感」",
                  ok && old.Strokes.Count == 1 && !old.Strokes[0].HasPressure,
                  ok ? $"读回 {old.Strokes.Count} 条，HasPressure = {(old.Strokes.Count > 0 ? old.Strokes[0].HasPressure.ToString() : "?")}"
                     : "读取抛异常");
        }

        // 收尾：把状态还回去（自检不该改坏后面要用的东西）。
        BoardOn = oldBoard;
        OverlayWindow.InkTrailEnabled = oldTrail;
        PenWidthLogical = oldPenWidth;
        SetColorFromUi(oldColor);
        SetDashFromUi(StrokeDash.Solid);
        Doc.Clear();
        Doc.ClearHistory();
        SettleFrames(120);

        Console.WriteLine();
        Console.WriteLine($"  合计 {pass + fail} 项：通过 {pass}，失败 {fail}");
        Console.WriteLine();
        _quit = true;
    }

    /// <summary>
    /// 湿墨轨迹（委托墨迹）实测：**只让系统画**（`SuppressActiveStroke`），用合成笔走一遍，
    /// 再从屏幕上数墨色像素。
    ///
    /// 为什么必须测这一条：预测**只喂这条通道**——它画的是"正在写的这一笔"的最后一小段。
    /// 如果这条通道在某台机器上根本没上屏（API 调用成功、返回了 generationId，
    /// 不等于 DWM 真的画出来），那预测就不可能有任何可见效果，
    /// "开/关都一样"就会有完全不同的解释。
    /// </summary>
    private void WetInkTest(bool activate = false)
    {
        Console.WriteLine();
        Console.WriteLine("=== 湿墨轨迹实测：只让系统画（自己不画）===");
        Console.WriteLine($"  变体：{(activate ? "把覆盖层强制激活（去掉 NOACTIVATE + 抢前台）" : "按产品原样（置顶 + 不抢焦点）")}");
        if (!EnsureSyntheticPen())
        {
            Console.WriteLine("  SKIP: 拿不到合成笔设备");
            _quit = true; return;
        }

        if (activate && _windows.Count > 0)
        {
            // 假设：DWM 可能只给"前台窗口"画委托湿墨。这里把 NOACTIVATE 摘掉并抢一次前台，
            // 看轨迹会不会突然出现——纯粹是对照实验，产品形态不会这么做。
            var w0 = _windows[0];
            long ex = (long)Native.GetWindowLongPtr(w0.Hwnd, Native.GWL_EXSTYLE);
            Native.SetWindowLongPtr(w0.Hwnd, Native.GWL_EXSTYLE, (IntPtr)(ex & ~(long)Native.WS_EX_NOACTIVATE));
            Native.SetForegroundWindow(w0.Hwnd);
            Console.WriteLine($"  已激活：{w0.Hwnd}");
        }

        Doc.Clear();
        Doc.InvalidateAll();
        Tool = Tool.Pen;
        SuppressActiveStroke = true;      // 我们自己那一笔不画，屏幕上留的就只能是系统画的
        SettleFrames(200);

        float cx = _virtualX + _virtualW * 0.5f;
        float cy = _virtualY + _virtualH * 0.5f;
        int boxX = (int)(cx - 400), boxY = (int)(cy - 160);

        SendPenPoint(cx - 300, cy, 400, contact: true, first: true);
        for (int i = 1; i <= 30; i++)
        {
            SendPenPoint(cx - 300 + i * 20, cy + MathF.Sin(i / 30f * 6.28f) * 60,
                         400, contact: true, first: false);
            SettleFrames(4);
        }
        SettleFrames(60);                 // 笔仍然按着

        int whileDown = ScreenProbe.CountRed(boxX, boxY, 800, 320);
        int whileDownFull = ScreenProbe.CountRed(_virtualX, _virtualY, _virtualW, _virtualH);
        string shot = Path.Combine("reports", "shots", "wetink-down.bmp");
        Directory.CreateDirectory(Path.GetDirectoryName(shot));
        ScreenProbe.SaveBmp(shot, boxX, boxY, 800, 320);
        string shotFull = Path.Combine("reports", "shots", "wetink-down-full.bmp");
        ScreenProbe.SaveBmp(shotFull, _virtualX, _virtualY, _virtualW, _virtualH);

        SendPenPoint(cx + 300, cy, 400, contact: false, first: false);
        SettleFrames(300);
        int afterUp = ScreenProbe.CountRed(boxX, boxY, 800, 320);

        SuppressActiveStroke = false;
        Console.WriteLine($"  按住不放时墨色像素：{whileDown}（这一笔我们自己没画，只能是系统画的）");
        Console.WriteLine($"  同上但扫全屏      ：{whileDownFull}（排除「画在别处」）");
        Console.WriteLine($"  抬笔之后墨色像素  ：{afterUp}（委托轨迹应当被收回）");
        Console.WriteLine($"  轨迹调试          ：{OverlayWindow.InkTrailDebug}");
        Console.WriteLine($"  截图              ：{Path.GetFullPath(shot)}");
        Console.WriteLine($"  全屏截图          ：{Path.GetFullPath(shotFull)}");
        // 重要教训：**合成笔不被 DWM 认**（实测：合成笔下按住时 0 个墨色像素，
        // 换成真笔同样流程是 1.4 万个）。所以合成分支只能判"我们的 API 调用成不成功"，
        // 判不了"系统画没画"——真笔要用 --wetinktest --live N（人来写）。
        Console.WriteLine(whileDown > 500
            ? "  PASS: 委托墨迹轨迹确实上了屏 —— 预测有可见通道"
            : "  不可判定：合成笔不会被 DWM 画成湿墨（实测如此）。要判这一条请用真笔：--wetinktest --live 15");
        Console.WriteLine($"  抬笔后的墨是我们自己提交进文档的那一笔（与轨迹无关），这里只作记录：{afterUp} 像素");
        _quit = true;
    }

    /// <summary>
    /// 湿墨轨迹「真笔 + 自己不画」实测：你写 N 秒，我每 100 ms 采一次屏，
    /// 记下**最多**看到多少墨色像素。
    ///
    /// 为什么要人写：合成笔走的是同一条 WM_POINTER 路径，但 DWM 可能只认真实数字化仪的
    /// 指针（上一轮合成笔下轨迹一个像素都没有）。这一轮就是用来判这一条的。
    /// </summary>
    private void WetInkLiveTest(double seconds)
    {
        Console.WriteLine();
        Console.WriteLine("=== 湿墨轨迹实测（真笔 · 只让系统画）===");
        Console.WriteLine("  注意：这一轮你自己写的时候屏幕上**不会**出现笔画（我们自己那层关掉了），");
        Console.WriteLine("        抬笔之后那一笔才会出现。屏幕上中途出现的任何墨，都只能是系统画的委托轨迹。");
        Console.WriteLine($"  现在开始写 {seconds:F0} 秒……");
        Console.WriteLine();

        Doc.Clear();
        Doc.InvalidateAll();
        Tool = Tool.Pen;
        SuppressActiveStroke = true;
        SettleFrames(120);

        float cx = _virtualX + _virtualW * 0.5f;
        float cy = _virtualY + _virtualH * 0.5f;
        int boxX = (int)(cx - 700), boxY = (int)(cy - 350);
        int maxBand = 0, maxFull = 0, samples = 0;
        int beforePoints = PenTotalPoints;

        double t0 = NowMs;
        double nextSampleAt = t0;
        int tick = 0;
        while (!_quit && NowMs - t0 < seconds * 1000)
        {
            DrainMessages();
            if (_dirty || _drawing) { if (OverlayWindow.VBlankPaced) Native.DwmFlush(); RenderAll(); _dirty = false; }
            else Native.MsgWaitForMultipleObjectsEx(0, IntPtr.Zero, 20, Native.QS_ALLINPUT, 0);
            NowMs = _clock.Elapsed.TotalMilliseconds;

            if (NowMs >= nextSampleAt)
            {
                nextSampleAt = NowMs + 100;
                samples++;
                int band = ScreenProbe.CountRed(boxX, boxY, 1400, 700);
                if (band > maxBand) maxBand = band;
                if (++tick % 10 == 0)              // 全屏每秒一次，排除"画在别处"
                {
                    int full = ScreenProbe.CountRed(_virtualX, _virtualY, _virtualW, _virtualH);
                    if (full > maxFull) maxFull = full;
                }
            }
        }

        SuppressActiveStroke = false;
        int penSamples = PenTotalPoints - beforePoints;
        Console.WriteLine();
        Console.WriteLine($"  这 {seconds:F0} 秒里收到真笔采样点：{penSamples}（0 说明没写进来）");
        Console.WriteLine($"  屏幕中央区域的最大墨色像素：{maxBand}（共采 {samples} 次）");
        Console.WriteLine($"  全屏的最大墨色像素        ：{maxFull}");
        Console.WriteLine($"  轨迹调试                  ：{OverlayWindow.InkTrailDebug}");
        Console.WriteLine(maxBand > 200
            ? "  PASS: 真笔下系统确实在画委托轨迹 —— 预测有可见通道"
            : "  FAIL: 真笔下系统也没画（这一轮屏幕上不该有别的墨）—— 委托轨迹这台机器上不生效");
        SettleFrames(120);
        _quit = true;
    }

    private void GhostTest(bool scrolled = false)
    {
        Console.WriteLine();
        Console.WriteLine("=== 残影测试（大跨度快速移动橡皮光标，看会不会拖尾）===");

        if (SkipIfNoSyntheticInput("残影检测（需要合成鼠标移动光标）")) { _quit = true; return; }

        Doc.Clear();
        Doc.InvalidateAll();
        Tool = Tool.Eraser;
        if (scrolled)
        {
            ViewOffsetY = -_virtualH * 0.5f;      // 把相机挪开：画布坐标 ≠ 屏幕坐标
            Console.WriteLine($"  （滚动过：ViewOffsetY = {ViewOffsetY:F0}，画布坐标与屏幕坐标不再相等）");
        }
        SettleFrames(300);

        // 先把光标停在远处（在测试带之外），拍一张"干净"的基准图
        float parkX = _virtualX + 150, parkY = _virtualY + _virtualH - 200;
        SendMouse((int)parkX, (int)parkY, 0);
        SettleFrames(500);

        int bandX = _virtualX + 400, bandY = _virtualY + 780;
        int bandW = 2000, bandH = 200;

        // 先量一遍"环境噪声"：光标停着不动，连拍两张。
        // 桌面上的别的程序（聊天窗口、光标闪烁）本来就会自己变化，
        // 不先量这个底噪，就会把它当成我们的残影。这一步让测试有自证能力。
        byte[] noise1 = ScreenProbe.CaptureRegion(bandX, bandY, bandW, bandH);
        SettleFrames(500);
        byte[] noise2 = ScreenProbe.CaptureRegion(bandX, bandY, bandW, bandH);
        int noise = ScreenProbe.DiffCount(noise1, noise2);

        byte[] before = ScreenProbe.CaptureRegion(bandX, bandY, bandW, bandH);

        float y = _virtualY + _virtualH * 0.5f;
        float x0 = _virtualX + 450;
        SendMouse((int)x0, (int)y, 0);
        SettleFrames(200);

        // 每次跳 300 像素、间隔很短：模拟快速划动
        const int hops = 6;
        byte[] during = null;
        double dirtyPercent = -1;
        var perHop = new List<string>();
        for (int i = 1; i <= hops; i++)
        {
            SendMouse((int)(x0 + i * 300f), (int)y, 0);
            SettleFrames(20);
            if (_windows.Count > 0)
                perHop.Add($"{i}:{_windows[0].LastPresentRectCount}块/{_windows[0].LastPresentAreaPercent:F1}%");
            if (i == 3)
            {
                // 扫到一半时停下拍一张：用来证明"光标确实画出来了"。
                // 少了这一步，光标因为脏区算错而**根本没画**的情况也会被判成
                // "没有残影"——测试就成了永远通过摆设。
                SettleFrames(300);
                during = ScreenProbe.CaptureRegion(bandX, bandY, bandW, bandH);
                dirtyPercent = _windows.Count > 0 ? _windows[0].LastPresentAreaPercent : -1;
            }
        }

        // 光标回到原处，等脏区排空，再拍一张
        SendMouse((int)parkX, (int)parkY, 0);
        SettleFrames(500);
        byte[] after = ScreenProbe.CaptureRegion(bandX, bandY, bandW, bandH);

        int diff = ScreenProbe.DiffCount(before, after);
        int visible = during != null ? ScreenProbe.DiffCount(before, during) : -1;
        Console.WriteLine($"  光标扫过区域前后逐像素差异: {diff} 像素（共 {bandW * bandH} 像素）");
        Console.WriteLine($"  对照：同一区域静置两帧的差异: {noise} 像素（环境噪声）");
        Console.WriteLine($"  扫过途中光标是否真的画出来了: {visible} 像素（应当 > 1000）");
        // 顺带记一下上屏面积：光标只是一小块，这里却是"光标 ∪ 滚动条那条竖带"的
        // 并集，所以数值偏大是正常的——只作为观察，不作判据。
        Console.WriteLine($"  扫过途中的上屏脏区: {dirtyPercent:F1}%（含滚动条竖带的并集，仅作观察）");
        Console.WriteLine("  每跳一格的脏区: " + string.Join("  ", perHop));

        string shot = Path.Combine("reports", "shots", "ghosttest.bmp");
        Directory.CreateDirectory(Path.GetDirectoryName(shot));
        ScreenProbe.SaveBmp(shot, _virtualX, _virtualY, _virtualW, _virtualH);
        Console.WriteLine($"  截图: {Path.GetFullPath(shot)}");

        // 光标已经离开这块区域，像素应当复原。
        //
        // 判据用"我们造成的差异"而不是绝对差异：这块区域里别的程序自己也会变
        // （实测聊天窗口刷文字能刷出上千个像素），所以要先减掉环境噪声。
        // 容差 200 像素留给抗锯齿和噪声本身的抖动。
        int ours = Math.Max(0, diff - noise);
        bool drew = visible > 1000;
        bool ok = ours < 200 && drew;
        Console.WriteLine(ok
            ? $"  PASS: 光标画出来了，且没有残影（扣掉环境噪声后仅剩 {ours} 像素）"
            : !drew
                ? $"  FAIL: 光标压根没画出来（只差 {visible} 像素）——脏区算错了"
                : $"  FAIL: 出现拖尾残影（扣掉环境噪声后仍有 {ours} 像素）");
        _quit = true;
    }

    /// <summary>
    /// **分块缓存自检**：接缝、内容正确性、滚动复用、内存上界。
    ///
    /// 分块缓存有一类特别难查的 bug——**接缝**：笔画跨在块边界上时，如果
    /// 有一边的块没把这条笔画画进去，就会缺一条边；而"平时看着好好的、
    /// 只有粗笔画压在边界上才露出来"，靠肉眼很难碰到。
    ///
    /// 这里用"同一支笔，摆在块边界上 vs 摆在块正中间"做对照：墨量必须一样。
    /// 边界上少墨 = 接缝，多墨 = 重复绘制。
    /// </summary>
    private void TileTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 分块缓存自检 ===");
        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"    {name,-30}{(ok ? "PASS" : "FAIL")}  {detail}");
        }

        const int T = 256;                                  // 块边长，和 CanvasTileCache 一致
        ViewOffsetY = 0f;
        foreach (var w in _windows) { w.ViewOffsetX = 0f; w.ViewOffsetY = 0f; }

        // ---- 1) 粗横线压在横向块边界上 ----------------------------------
        // 边界取 y = 3T = 768（画布坐标 = 屏幕坐标，因为相机为 0、原点为 0）。
        float w2 = 40f;
        int onSeam = DrawAndCountHorizontal(_virtualX + 300, 3 * T, 1200, w2);
        int midTile = DrawAndCountHorizontal(_virtualX + 300, 3 * T + T / 2, 1200, w2);
        int diffY = Math.Abs(onSeam - midTile);
        Check("横线压在块边界上不缺墨", onSeam > 40000 && diffY < midTile * 0.03,
              $"边界 {onSeam} vs 块中间 {midTile}（差 {diffY}，允许 {midTile * 0.03:F0}）");

        // ---- 2) 粗竖线压在纵向块边界上 ----------------------------------
        int onSeamX = DrawAndCountVertical(4 * T, _virtualY + 300, 1200, w2);
        int midTileX = DrawAndCountVertical(4 * T + T / 2, _virtualY + 300, 1200, w2);
        int diffX = Math.Abs(onSeamX - midTileX);
        Check("竖线压在块边界上不缺墨", onSeamX > 40000 && diffX < midTileX * 0.03,
              $"边界 {onSeamX} vs 块中间 {midTileX}（差 {diffX}，允许 {midTileX * 0.03:F0}）");

        // ---- 3) 跨块的长笔画：一整条都得在 ------------------------------
        // 从画面左上角一路斜到右下角，横跨十几个块。
        Doc.Clear();
        Doc.ClearHistory();
        var longStroke = new Stroke
        {
            Tool = Tool.Pen, Kind = StrokeKind.Freehand,
            Color = new Color4(1f, 0f, 1f, 1f), Width = 2f * DpiScale,
        };
        for (int i = 0; i <= 40; i++)
        {
            float t = i / 40f;
            longStroke.AddPoint(_virtualX + 200 + t * 2400, _virtualY + 200 + t * 1400, 1f, i);
        }
        Doc.AddStroke(longStroke);
        SettleFrames(500);
        // 沿线取 6 段采样，每段都得有墨（中间任何一块漏画，就会有一段是空的）
        int emptySpots = 0;
        for (int k = 0; k < 6; k++)
        {
            float t = (k + 0.5f) / 6f;
            int n = ScreenProbe.CountMagenta(
                (int)(_virtualX + 200 + t * 2400) - 60, (int)(_virtualY + 200 + t * 1400) - 60, 120, 120);
            if (n < 50) emptySpots++;
        }
        Check("跨十几个块的长笔画不断线", emptySpots == 0, $"6 段采样里有 {emptySpots} 段是空的");

        // ---- 4) 滚下去再滚回来：墨量必须一模一样，而且回程不重画 -------
        int before = ScreenProbe.CountMagenta(_virtualX, _virtualY, _virtualW, _virtualH);
        var w0 = _windows[0];
        int rasterDown = 0, rasterUp = 0;
        for (int k = 0; k < 4; k++) { HandleWheel(Wheel(-120)); RenderAll(); rasterDown += w0.LastPatchCount; }
        for (int k = 0; k < 4; k++) { HandleWheel(Wheel(120)); RenderAll(); rasterUp += w0.LastPatchCount; }
        SettleFrames(300);
        int after = ScreenProbe.CountMagenta(_virtualX, _virtualY, _virtualW, _virtualH);

        Check("滚下去再滚回来画面一致", Math.Abs(after - before) <= before * 0.005 && before > 5000,
              $"{before} -> {after}");
        Check("回程复用了块缓存（没有重画）", rasterUp == 0,
              $"去程光栅 {rasterDown} 块，回程 {rasterUp} 块");

        // ---- 5) 常驻块数不超过预算 --------------------------------------
        Check("常驻分块不超预算", w0.LastTileCount <= Math.Max(w0.LastTileBudget, 1),
              $"{w0.LastTileCount} 块 / 预算 {w0.LastTileBudget}（每块 256KB）");

        Console.WriteLine();
        Console.WriteLine($"  {(fail == 0 ? "PASS" : "FAIL")}：块边界无缝、跨块笔画完整、回程免重画、内存有上界");
        Console.WriteLine();
        Doc.Clear();
        Doc.ClearHistory();
        _quit = true;
    }

    // 分块测试的滚轮构造（和 WheelTest 一致：delta 在高 16 位）
    private static IntPtr Wheel(int delta) => new((long)(ushort)(short)delta << 16);

    /// <summary>画一条粗横线并数它的墨像素。横线的**中心线**画在 y 上。</summary>
    private int DrawAndCountHorizontal(float x, float y, float len, float width)
    {
        Doc.Clear();
        Doc.ClearHistory();
        var s = new Stroke
        {
            Tool = Tool.Pen, Kind = StrokeKind.Freehand,
            Color = new Color4(1f, 0f, 1f, 1f), Width = width,
        };
        s.AddPoint(x, y, 1f, 0);
        s.AddPoint(x + len, y, 1f, 1);
        Doc.AddStroke(s);
        Doc.InvalidateAll();
        SettleFrames(350);
        return ScreenProbe.CountMagenta((int)x, (int)(y - width), (int)len, (int)(width * 2f));
    }

    /// <summary>画一条粗竖线并数它的墨像素。竖线的**中心线**画在 x 上。</summary>
    private int DrawAndCountVertical(float x, float y, float len, float width)
    {
        Doc.Clear();
        Doc.ClearHistory();
        var s = new Stroke
        {
            Tool = Tool.Pen, Kind = StrokeKind.Freehand,
            Color = new Color4(1f, 0f, 1f, 1f), Width = width,
        };
        s.AddPoint(x, y, 1f, 0);
        s.AddPoint(x, y + len, 1f, 1);
        Doc.AddStroke(s);
        Doc.InvalidateAll();
        SettleFrames(350);
        return ScreenProbe.CountMagenta((int)(x - width), (int)y, (int)(width * 2f), (int)len);
    }

    private void EraserTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 橡皮擦测试（用稀疏采样快速划过，看会不会漏）===");

        if (SkipIfNoSyntheticInput("稀疏采样快划那一组")) { _quit = true; return; }

        float cx = _virtualX + _virtualW * 0.5f;
        float cy = _virtualY + _virtualH * 0.5f;

        for (int k = -1; k <= 1; k++)
        {
            var s = new Stroke
            {
                Tool = Tool.Pen,
                Color = new Color4(1f, 0f, 1f, 1f),
                Width = 10f * DpiScale,
            };
            for (int i = 0; i <= 80; i++)
                s.AddPoint(cx - 500 + i * 12, cy + k * 60, 0.9f, NowMs);
            Doc.AddStroke(s);
        }
        Doc.InvalidateAll();
        SettleFrames(400);

        int before = Doc.Strokes.Count;
        int undoBefore = Doc.UndoDepth;
        Console.WriteLine($"  先画了 {before} 条横线（间隔 60 px），橡皮擦半径 {EraserRadius:F0} px");

        Tool = Tool.Eraser;
        float y0 = cy - 200, y1 = cy + 200;
        SendMouse((int)cx, (int)y0, 0);
        SettleFrames(60);
        SendMouse((int)cx, (int)y0, Native.MOUSEEVENTF_LEFTDOWN);
        SettleFrames(60);

        // Only four samples over 400 px: a fast flick.
        const int coarse = 4;
        for (int i = 1; i <= coarse; i++)
        {
            SendMouse((int)cx, (int)(y0 + (y1 - y0) * i / coarse), 0);
            SettleFrames(10);
        }
        SendMouse((int)cx, (int)y1, Native.MOUSEEVENTF_LEFTUP);
        SettleFrames(400);

        int after = Doc.Strokes.Count;
        int undoAfter = Doc.UndoDepth;
        int leftover = ScreenProbe.CountMagenta((int)(cx - 520), (int)(cy - 260), 1040, 520);

        Console.WriteLine($"  笔画数 {before} -> {after}   期望 0");
        Console.WriteLine($"  撤销步数增加 {undoAfter - undoBefore}   期望 1（整段拖拽算一步）");
        Console.WriteLine($"  屏幕上残留品红像素 {leftover}   期望接近 0");

        bool ok = after == 0 && undoAfter - undoBefore == 1 && leftover < 200;
        Console.WriteLine(ok ? "  PASS" : "  FAIL");
        _quit = true;
    }

    /// <summary>
    /// 像素橡皮自检（--pixelerasetest）。
    ///
    /// 判据全是"看得见的行为"，不是内部状态：
    ///   ① 一条横线被竖着抹一下 → 变成**两段**，切口正好停在橡皮边界外（框里不留墨）；
    ///   ② 整条落在橡皮里的 → 消失，撤销回来还是原来那一条；
    ///   ③ 没碰到的 → 原样不动（**引用相等**：重建一遍看不出来，但白扔几何缓存）；
    ///   ④ 图形要"轮廓真的碰到"才删——橡皮从一个大图形正中间划过不能把整个图形吃掉；
    ///   ⑤ 一次拖拽扫过多个位置 = **一步**撤销，撤销后文档逐条回到拖之前；
    ///   ⑥ 上屏像素：框里的墨归零、框外还在。
    /// 外加两条结构判据：默认落点是**竖着的黄金比矩形**；这个工具的落点反馈画的是矩形。
    /// </summary>
    private void PixelEraserTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 像素橡皮自检（切段 / 框里无墨 / 一步撤销）===");

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-36} {detail}");
        }

        float cx = _virtualX + _virtualW * 0.5f;
        float cy = _virtualY + _virtualH * 0.5f;
        const float halfW = 30f, halfH = 60f;     // 测试用的小块（默认那块 93×150 太大）
        const float penW = 16f;
        const float reach = penW * 0.5f;          // 半笔宽：切口要停在框外这么远

        // --- 0. 形状与落点反馈 -------------------------------------------------
        Check("落点是竖着的黄金比例矩形",
              PixelEraserWidthLogical > 0f && PixelEraserHeightLogical > PixelEraserWidthLogical
              && MathF.Abs(PixelEraserHeightLogical / PixelEraserWidthLogical - GoldenRatio) < 0.002f,
              $"{PixelEraserWidthLogical:F0}×{PixelEraserHeightLogical:F0} 逻辑像素，"
              + $"高:宽 = {PixelEraserHeightLogical / PixelEraserWidthLogical:F3}");

        var savedTool = Tool;
        bool savedInside = PointerInside;
        var savedDevice = LastPointerType;
        Tool = Tool.PixelEraser;
        PointerInside = true;                  // 落点反馈只在"指针在窗口里"时才画
        LastPointerType = Native.PT_MOUSE;
        Check("落点反馈是矩形 + 系统光标藏起来",
              DrawnCursor == ToolCursorShape.Rect && ComputeCursorKind() == CursorKind.Hidden,
              $"{DrawnCursor} / {ComputeCursorKind()}");
        Tool = savedTool;
        PointerInside = savedInside;
        LastPointerType = savedDevice;

        // --- 1. 一条横线抹一下：应该变成两段，切口停在框外 ----------------------
        Doc.Clear();
        Doc.ClearHistory();

        var line = new Stroke { Tool = Tool.Pen, Color = new Color4(1f, 0f, 1f, 1f), Width = penW };
        for (int i = 0; i <= 80; i++) line.AddPoint(cx - 400 + i * 10, cy, 0.9f, i);
        Doc.AddStroke(line);

        int undoBefore = Doc.UndoDepth;
        Doc.BeginEraseRect();
        Doc.EraseRectAt(cx, cy, halfW, halfH);
        Doc.EndErase();

        var pieces = Doc.Strokes.ToArray();
        Check("擦断 → **两条独立对象**（原件不再在文档里）",
              pieces.Length == 2 && !Doc.Strokes.Contains(line),
              $"对象数 {pieces.Length}，原件 {(Doc.Strokes.Contains(line) ? "还在" : "已换成两段")}");
        Check("一次擦除只算一步撤销", Doc.UndoDepth == undoBefore + 1,
              $"撤销栈 {undoBefore} → {Doc.UndoDepth}");
        Check("两段各自是一个完整对象（没有残留区间表）",
              pieces.Length == 2 && pieces[0].Erased.Count == 0 && pieces[1].Erased.Count == 0
              && pieces[0].Points.Count + pieces[1].Points.Count >= 60,
              pieces.Length == 2
                ? $"点数 {pieces[0].Points.Count}/{pieces[1].Points.Count}（原 81 点）"
                : "没拆成两段");

        float leftEnd = pieces.Length == 2 ? pieces[0].Bounds.MaxX : float.NaN;
        float rightStart = pieces.Length == 2 ? pieces[1].Bounds.MinX : float.NaN;
        float bandLeft = cx - halfW - reach, bandRight = cx + halfW + reach;
        Check("框里不留墨（切口在边界外）",
              pieces.Length == 2 && leftEnd <= bandLeft + 0.5f && rightStart >= bandRight - 0.5f,
              $"左段到 {leftEnd:F1}（该 ≤ {bandLeft:F1}），右段从 {rightStart:F1}（该 ≥ {bandRight:F1}）");

        bool anyInside = false;
        foreach (var p in pieces)
            foreach (var q in p.Points)
                if (MathF.Abs(q.Y - cy) < halfH && MathF.Abs(q.X - cx) < halfW + reach - 0.5f)
                    anyInside = true;
        Check("剩下的墨没有一点伸进框里", !anyInside,
              anyInside ? "有采样点落在框内" : "两段的采样点都在框外");

        // --- 2. 撤销 / 重做：同一个对象，区间表清空 / 回来 ----------------------
        bool undone = Doc.Undo();
        Check("撤销：同一个对象、擦除区间清空",
              undone && Doc.Strokes.Count == 1 && ReferenceEquals(Doc.Strokes[0], line)
              && line.Erased.Count == 0 && line.RemainingRuns().Count == 1 && line.Points.Count == 81,
              $"笔画数 {Doc.Strokes.Count}，区间 {line.Erased.Count} 段，点数 {line.Points.Count}");

        bool redone = Doc.Redo();
        Check("重做：又变回两条独立对象",
              redone && Doc.Strokes.Count == 2 && !Doc.Strokes.Contains(line)
              && Doc.Strokes[0].Erased.Count == 0,
              $"对象数 {Doc.Strokes.Count}");

        // --- 2b. 同一笔擦两刀 / 重复擦已经擦过的地方 ---------------------------
        Doc.Clear();
        Doc.ClearHistory();
        var longLine = new Stroke { Tool = Tool.Pen, Color = new Color4(1f, 0f, 1f, 1f), Width = penW };
        for (int i = 0; i <= 120; i++) longLine.AddPoint(cx - 600 + i * 10, cy, 0.9f, i);
        Doc.AddStroke(longLine);
        int undo2 = Doc.UndoDepth;

        Doc.BeginEraseRect();
        Doc.EraseRectAt(cx - 200, cy, 20f, 30f);
        Doc.EraseRectAt(cx + 200, cy, 20f, 30f);
        Doc.EndErase();
        Check("同一笔擦两刀 → **三段独立对象**、一步撤销",
              Doc.Strokes.Count == 3 && !Doc.Strokes.Contains(longLine)
              && Doc.UndoDepth == undo2 + 1,
              $"对象 {Doc.Strokes.Count}、撤销栈 +{Doc.UndoDepth - undo2}");

        // 再擦一次"落在已经擦掉的地方"：不能多出撤销步，也不能把表搞乱
        int undo3 = Doc.UndoDepth;
        Doc.BeginEraseRect();
        Doc.EraseRectAt(cx - 200, cy, 20f, 30f);
        Doc.EndErase();
        Check("重复擦已经擦过的地方 → 不多出撤销步",
              Doc.UndoDepth == undo3 && Doc.Strokes.Count == 3,
              $"撤销栈 +{Doc.UndoDepth - undo3}，对象还是 {Doc.Strokes.Count} 条");

        // 撤销回到"擦之前那一条"（而不是把两刀拆成两步）
        Doc.Undo();
        Check("一步撤销回到擦之前（原来那一条、点数不变）",
              Doc.Strokes.Count == 1 && ReferenceEquals(Doc.Strokes[0], longLine)
              && longLine.Erased.Count == 0 && longLine.Points.Count == 121,
              $"对象 {Doc.Strokes.Count}，区间 {longLine.Erased.Count} 段，点数 {longLine.Points.Count}");

        // --- 3. 整条在框里 / 完全没碰到 ----------------------------------------
        Doc.Clear();
        Doc.ClearHistory();
        var inside = new Stroke { Tool = Tool.Pen, Color = new Color4(1f, 0f, 1f, 1f), Width = penW };
        for (int i = 0; i <= 10; i++) inside.AddPoint(cx - 10 + i * 2, cy - 10 + i * 2, 0.9f, i);
        var faraway = new Stroke { Tool = Tool.Pen, Color = new Color4(1f, 0f, 1f, 1f), Width = penW };
        for (int i = 0; i <= 40; i++) faraway.AddPoint(cx - 700 + i * 10, cy, 0.9f, i);
        Doc.AddStroke(inside);
        Doc.AddStroke(faraway);

        Doc.BeginEraseRect();
        Doc.EraseRectAt(cx, cy, halfW, halfH);
        Doc.EndErase();
        Check("框里的整条被擦掉、框外的不动",
              Doc.Strokes.Count == 1 && ReferenceEquals(Doc.Strokes[0], faraway),
              $"剩下 {Doc.Strokes.Count} 条"
              + (Doc.Strokes.Count == 1 && ReferenceEquals(Doc.Strokes[0], faraway)
                 ? "（框外那条，引用没变）" : "（不是框外那条！）"));

        Doc.Undo();
        Check("撤销把整条放回来（含原顺序）",
              Doc.Strokes.Count == 2 && ReferenceEquals(Doc.Strokes[0], inside)
              && ReferenceEquals(Doc.Strokes[1], faraway),
              $"笔画数 {Doc.Strokes.Count}");

        // --- 4. 图形：碰到就**熔成笔迹再切**（用户 2026-09-15 定：断开也要单独算）---------
        Doc.Clear();
        Doc.ClearHistory();
        var crossed = new Stroke
        {
            Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
            Color = new Color4(0.95f, 0.18f, 0.18f, 1f), Width = 4f,
        };
        crossed.AddPoint(cx - 10, cy - 200, 1f, 0);      // 两条竖边正好穿过橡皮
        crossed.AddPoint(cx + 10, cy + 200, 1f, 0);

        var bigShape = new Stroke
        {
            Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
            Color = new Color4(0.95f, 0.18f, 0.18f, 1f), Width = 4f,
        };
        bigShape.AddPoint(cx - 400, cy - 400, 1f, 0);    // 外框很大，轮廓离橡皮很远
        bigShape.AddPoint(cx + 400, cy + 400, 1f, 0);

        Doc.AddStroke(crossed);
        Doc.AddStroke(bigShape);
        Doc.BeginEraseRect();
        Doc.EraseRectAt(cx, cy, halfW, halfH);
        Doc.EndErase();
        bool allFreehand = true;
        foreach (var s in Doc.Strokes)
            if (!ReferenceEquals(s, bigShape) && s.Kind != StrokeKind.Freehand) allFreehand = false;
        Check("图形被擦到 → 熔成笔迹并切开（剩下的段各自独立）",
              !Doc.Strokes.Contains(crossed) && allFreehand && Doc.Strokes.Count >= 3,
              $"剩下 {Doc.Strokes.Count} 条，全是普通笔迹={allFreehand}（原图形已不在）");
        Check("橡皮从大图形正中间划过 → 不删", Doc.Strokes.Contains(bigShape),
              "外框和橡皮相交，但轮廓离橡皮 370 像素（按外框判就会误删）");

        // 图形的撤销：**一步回到原来那个图形**（熔是内部的，不该让用户多撤一步）
        Doc.Undo();
        Check("图形熔成笔迹后，一步撤销回到原图形",
              Doc.Strokes.Count == 2 && Doc.Strokes.Contains(crossed)
              && crossed.Kind == StrokeKind.Rectangle,
              $"对象 {Doc.Strokes.Count}，原图形 {(Doc.Strokes.Contains(crossed) ? "回来了" : "没回来")}");

        // --- 4b. 图形的"熔"必须是**一整组、外形逐笔不变** --------------------------
        // 用户 2026-09-20 反馈："面积橡皮擦图形，擦掉一部分剩下的会发生很奇怪的变化，
        // 比如虚线变实线，或者多出来线"。根因：熔的时候把轮廓（含抬笔标记）压成一条、
        // 辅助线（渐近线 / 被挡的棱）又不在轮廓里。下面逐条钉住修好之后的样子。
        Doc.Clear();
        Doc.ClearHistory();

        // 长方体（两笔画的）：正面 (cx−300, cy−200)..(cx+100, cy+100)，深度 = 80
        var cube = new Stroke
        {
            Tool = Tool.Cuboid, Kind = StrokeKind.Cuboid,
            Color = new Color4(0.95f, 0.18f, 0.18f, 1f), Width = 4f,
        };
        cube.SetCuboidFront(cx - 300, cy - 200, cx + 100, cy + 100);
        cube.SetCuboidDepth(cx - 220, cy - 120);          // d = |cy−200 − (cy−120)| = 80
        Doc.AddStroke(cube);

        Doc.BeginEraseRect();
        Doc.EraseRectAt(cx + 100, cy - 50, halfW, halfH);  // 只切正面右边那条竖棱
        Doc.EndErase();

        int cubeParts = 0, cubeDashed = 0, cubeMaxPts = 0;
        bool cubeThinDash = true;
        foreach (var s in Doc.Strokes)
        {
            if (s.Kind != StrokeKind.Freehand) continue;
            cubeParts++;
            if (s.Dash == StrokeDash.Dashed)
            {
                cubeDashed++;
                if (s.Width > 3f) cubeThinDash = false;   // 辅助线是 0.6 倍细（4 × 0.6 = 2.4）
            }
            cubeMaxPts = Math.Max(cubeMaxPts, s.Points.Count);
        }
        Check("长方体被擦到 → 熔成**一条棱一段**（不再是压成一条的 24 点折线）",
              cubeParts >= 12 && cubeMaxPts <= 4,
              $"熔出 {cubeParts} 条、最长 {cubeMaxPts} 点（压成一条会是 1 条 24 点＋横穿的假线）");
        Check("长方体被挡住的三条棱熔完**还是虚线、还是细的**",
              cubeDashed == 3 && cubeThinDash,
              $"虚线 {cubeDashed} 条（期望 3），细的={cubeThinDash}");

        Doc.Undo();
        Check("长方体熔成墨之后，一步撤销回到原图形",
              Doc.Strokes.Count == 1 && Doc.Strokes.Contains(cube) && cube.Kind == StrokeKind.Cuboid,
              $"对象 {Doc.Strokes.Count}（期望 1 个长方体）");

        // --- 4c. 双曲线：两支之间**不许连出假线**，渐近线熔完还是虚线 -----------------
        Doc.Clear();
        Doc.ClearHistory();
        var hyp = new Stroke
        {
            Tool = Tool.Hyperbola, Kind = StrokeKind.Hyperbola,
            Color = new Color4(0.95f, 0.18f, 0.18f, 1f), Width = 4f,
        };
        hyp.SetHyperbolaFromAsymptote(cx, cy, cx + 300, cy + 200, 8f);
        // 经过点挑得离顶点远一点，右支才有足够长（曲线**只画到老师拖到的那个点为止**）
        hyp.SetHyperbolaThroughPoint(cx + 250, cy + 130);
        Doc.AddStroke(hyp);

        Doc.BeginEraseRect();
        // 落点挑在**右支的顶点附近**（x = a ≈ 156 处，该支的 y = 0）：那里离渐近线最远
        //（渐近线在 x = 126..186 这一段是 y = 84..124，全在橡皮的 [−60,60] 之外），
        // 于是"只切曲线、不碰渐近线"，两条渐近线正好整条保留。
        Doc.EraseRectAt(cx + 156, cy, halfW, halfH);
        Doc.EndErase();

        int hyParts = 0, hyDashed = 0;
        bool noBridge = true;
        foreach (var s in Doc.Strokes)
        {
            if (s.Kind != StrokeKind.Freehand) continue;
            hyParts++;
            if (s.Dash == StrokeDash.Dashed) hyDashed++;
            // 一支曲线整个在中心的一侧（实轴沿 x 时：右支 x ≥ cx，左支 x ≤ cx）。
            // 熔成一条的话，这个对象会**同时**跨到两侧——那正是"多出来一条横穿的长线"。
            if (s.Points.Count > 4)
            {
                float lo = float.MaxValue, hi = float.MinValue;
                foreach (var p in s.Points) { lo = MathF.Min(lo, p.X); hi = MathF.Max(hi, p.X); }
                if (lo < cx - 10 && hi > cx + 10) noBridge = false;
            }
        }
        Check("双曲线被擦到 → 熔成好几笔，两支之间**没有横穿的假线**",
              hyParts >= 4 && noBridge,
              $"熔出 {hyParts} 笔（两支＋两条渐近线，被切的会再拆），跨中心的长笔={(noBridge ? "没有" : "有！")}");
        Check("双曲线熔完，两条渐近线**还是虚线**", hyDashed == 2, $"虚线 {hyDashed} 条（期望 2）");

        // --- 4d. 圆柱：熔出来是 5 笔（顶圈 / 下半圈 / 两条母线 / 虚线半圈）------------
        Doc.Clear();
        Doc.ClearHistory();
        var cyl = new Stroke
        {
            Tool = Tool.Cylinder, Kind = StrokeKind.Cylinder,
            Color = new Color4(0.95f, 0.18f, 0.18f, 1f), Width = 4f,
        };
        cyl.SetSolidBox(cx - 200, cy - 250, cx + 200, cy + 250);
        Doc.AddStroke(cyl);

        Doc.BeginEraseRect();
        Doc.EraseRectAt(cx - 200, cy, halfW, halfH);       // 擦左边那条母线
        Doc.EndErase();

        int cylParts = 0, cylDashed = 0;
        foreach (var s in Doc.Strokes)
        {
            if (s.Kind != StrokeKind.Freehand) continue;
            cylParts++;
            if (s.Dash == StrokeDash.Dashed) cylDashed++;
        }
        Check("圆柱被擦到 → 熔成 5 笔以上（母线被切会再拆），其中虚线半圈仍是虚线",
              cylParts >= 5 && cylDashed == 1,
              $"熔出 {cylParts} 笔、虚线 {cylDashed} 条（顶圈＋下半圈＋两母线＋被挡的半圈）");

        // --- 4e. 擦在**空白处**（轮廓够不着）→ 图形原封不动，连熔都不熔 ---------------
        Doc.Clear();
        Doc.ClearHistory();
        var co = new Stroke
        {
            Tool = Tool.Coordinate, Kind = StrokeKind.Coordinate,
            Color = new Color4(0.2f, 0.2f, 0.2f, 1f), Width = 3f,
        };
        co.SetAxisBox(cx - 400, cy - 300, cx + 400, cy + 300);
        Doc.AddStroke(co);

        Doc.BeginEraseRect();
        // 落点在一根**网格线**上（离两条轴各一步远）：网格不在"碰到没有"那份轮廓里，
        // 所以这里够不着这个坐标系 —— 结论应是"什么都没发生"（而不是整个坐标系被熔）。
        int touched = Doc.EraseRectAt(cx + 200, cy + 150, halfW, halfH);
        Doc.EndErase();
        Check("橡皮落在坐标系的网格线上 → 不碰它（网格不是可擦对象，也不该把坐标系熔掉）",
              touched == 0 && Doc.Strokes.Count == 1 && Doc.Strokes.Contains(co),
              $"受影响 {touched} 条，对象 {Doc.Strokes.Count}（期望 0 / 1）");

        // --- 4b. **双曲线的渐近线：橡皮必须擦得到**（用户 2026-09-21 报的 bug）----------
        // 症状："双曲线的渐近线好像擦不掉"——判定"碰到没有"的那一份里**没有辅助线**
        //（轮廓只含两支曲线），所以橡皮从虚线上掠过时判定"没碰上"、那一刀什么也没擦。
        //
        // 判据要挑得准：**沿渐近线找一个"离曲线足够远（> 10 像素）"的点**再擦 ——
        // 只有这样才排除"其实是擦到曲线了"，老写法在这儿必然一条都碰不到。
        Doc.Clear();
        Doc.ClearHistory();
        var hb = new Stroke
        {
            Tool = Tool.Hyperbola, Kind = StrokeKind.Hyperbola,
            Color = new Color4(0f, 0f, 1f, 1f), Width = 4f * DpiScale,
            ShowAsymptotes = true,
        };
        hb.AddPoint(cx, cy, 1f, 0);                  // 中心
        hb.AddPoint(cx + 150f, cy + 100f, 1f, 0);    // 渐近线框的角点
        hb.AddPoint(cx + 200f, cy + 60f, 1f, 0);     // 曲线经过的一点
        Doc.AddStroke(hb);

        Vector2 pickOnAsym = default;
        bool foundAsym = false;
        var hbOutline = hb.ShapeOutline();
        for (int side = -1; side <= 1 && !foundAsym; side += 2)
        {
            var (from, to) = hb.HyperbolaAsymptoteLocal(side);
            for (int k = 1; k < 20 && !foundAsym; k++)
            {
                var q = Vector2.Lerp(from, to, k / 20f);
                float d = float.MaxValue;
                for (int m = 0; m < hbOutline.Count; m++)
                    if (!Stroke.IsOutlineBreak(hbOutline[m])) d = MathF.Min(d, Vector2.Distance(q, hbOutline[m]));
                if (d > 10f) { pickOnAsym = q; foundAsym = true; }
            }
        }
        Doc.BeginEraseRect();
        int asymHit = foundAsym ? Doc.EraseRectAt(pickOnAsym.X, pickOnAsym.Y, 10f, 10f) : -1;
        Doc.EndErase();
        Check("双曲线的**渐近线**：橡皮从虚线上擦过去必须算碰到（老写法：这一刀什么也没擦）",
              foundAsym && asymHit >= 1,
              foundAsym
                  ? $"在离曲线 {10f:F0} 像素以上的虚线上擦 → 受影响 {asymHit} 条"
                  : "没找到「离曲线足够远」的渐近线取样点（几何变了？）");

        // --- 5. 一次拖拽扫过 5 条 = 一步撤销 -----------------------------------
        Doc.Clear();
        Doc.ClearHistory();
        for (int k = 0; k < 5; k++)
        {
            var s = new Stroke { Tool = Tool.Pen, Color = new Color4(1f, 0f, 1f, 1f), Width = penW };
            for (int i = 0; i <= 80; i++) s.AddPoint(cx - 400 + i * 10, cy - 200 + k * 100, 0.9f, i);
            Doc.AddStroke(s);
        }
        var before = Doc.Strokes.ToArray();
        int undo0 = Doc.UndoDepth;

        Doc.BeginEraseRect();
        for (int k = 0; k < 5; k++) Doc.EraseRectAt(cx, cy - 200 + k * 100, halfW, halfH);
        Doc.EndErase();
        int cutCount = 0;
        foreach (var s in Doc.Strokes) if (s.Kind == StrokeKind.Freehand) cutCount++;
        Check("拖拽扫过 5 条 = 一步撤销，每条都断成两截",
              Doc.UndoDepth == undo0 + 1 && Doc.Strokes.Count == 10 && cutCount == 10,
              $"撤销栈 +{Doc.UndoDepth - undo0}，笔画数 {before.Length} → {Doc.Strokes.Count}");

        Doc.Undo();
        bool restored = Doc.Strokes.Count == before.Length;
        for (int i = 0; restored && i < before.Length; i++)
            restored = ReferenceEquals(Doc.Strokes[i], before[i]) && Doc.Strokes[i].Erased.Count == 0;
        Check("撤销后逐条回到拖之前（对象 + 顺序 + 区间清空）", restored,
              $"笔画数 {Doc.Strokes.Count}，逐条比对 {(restored ? "全部一致" : "有出入")}");

        // --- 6. 上屏像素 -------------------------------------------------------
        // --- 6. 擦断之后是两条独立对象（**已知取舍：自交处会叠色**）--------------
        //
        // 用户 2026-09-15 定的语义：擦断了就要"结构上分开、单独算"。
        // 代价是：半透明荧光笔的两截互相穿过时，会**各画一次** → 交叠处变深
        // （这条笔迹没被擦到的地方颜色也变了）。这一条不再判红绿，只把数字量出来，
        // 免得以后有人以为是新 bug——取舍写在 调研-橡皮擦.md 第八节。
        Doc.Clear();
        Doc.ClearHistory();
        // 自交图小，单独摆在位图左上角那一块（800×800 的离屏位图装不下屏幕中心）
        float lx = _virtualX + 500f, ly = _virtualY + 500f;
        var loop = MakeSelfCrossingHighlight(lx, ly, 40f);
        Doc.AddStroke(loop);

        var (offTarget, offCpu) = MakeOffscreen(800, 800);
        var bufA = RenderAndRead(offTarget, offCpu, 800, 800, _virtualX, _virtualY);
        int crossPx = (int)(lx + 161.7f - _virtualX) - 8, crossPy = (int)(ly + 20.9f - _virtualY) - 8;
        int plainPx = (int)(lx + 60f - _virtualX) - 8, plainPy = (int)(ly - _virtualY) - 8;
        int diffBefore = ColorDiff(AvgPatch(bufA, 800, crossPx, crossPy, 17),
                                   AvgPatch(bufA, 800, plainPx, plainPy, 17));

        Doc.BeginEraseRect();
        Doc.EraseRectAt(lx + 240, ly + 140, 20f, 30f);      // 离交点 240 像素以上
        Doc.EndErase();

        var bufB = RenderAndRead(offTarget, offCpu, 800, 800, _virtualX, _virtualY);
        var crossB = AvgPatch(bufB, 800, crossPx, crossPy, 17);
        var plainB = AvgPatch(bufB, 800, plainPx, plainPy, 17);
        int diffAfter = ColorDiff(crossB, plainB);
        offTarget.Dispose();
        offCpu.Dispose();

        Check("半透明荧光笔擦断 → 两条独立对象（代价：交叠处会叠色）",
              Doc.Strokes.Count == 2 && !Doc.Strokes.Contains(loop),
              $"切之前差 {diffBefore}，切之后差 {diffAfter}（已知取舍，不判红绿）；"
              + $"对象数 {Doc.Strokes.Count}，"
              + $"交叠处 ({crossB.r},{crossB.g},{crossB.b}) vs 普通处 ({plainB.r},{plainB.g},{plainB.b})");

        // --- 7. 上屏像素（抓屏拍不到我们这层时会跳过）---------------------------
        Doc.Clear();
        Doc.ClearHistory();
        var onScreen = new Stroke
        {
            Tool = Tool.Pen, Color = new Color4(1f, 0f, 1f, 1f), Width = penW * DpiScale,
        };
        for (int i = 0; i <= 80; i++) onScreen.AddPoint(cx - 400 + i * 10, cy, 0.9f, i);
        Doc.AddStroke(onScreen);
        Doc.InvalidateAll();
        PointerInside = false;                 // 别让自绘光标进像素统计
        SettleFrames(500);

        int inkBefore = ScreenProbe.CountMagenta((int)(cx - 500), (int)(cy - 40), 1000, 80);
        // 先确认抓屏真的能看到我们的墨：锁屏 / 远程会话 / 被别的窗口盖住时，
        // 拍到的是桌面壁纸，那时"框里的墨归零"会假红、"框外的还在"会假绿。
        // 看不见就明确跳过这一条（前面十几条模型判据照样算数）。
        if (inkBefore < 500)
        {
            Console.WriteLine($"  环境：抓屏看不到我们的墨（拍到的大概是桌面或别的窗口）"
                            + $" → SKIP: 上屏那一条跳过（该有一千多品红像素，拍到 {inkBefore}）");
            Console.WriteLine($"  合计：通过 {pass}，失败 {fail}（上屏一条未验）");
            _quit = true;
            return;
        }
        Doc.BeginEraseRect();
        Doc.EraseRectAt(cx, cy, halfW, halfH);
        Doc.EndErase();
        SettleFrames(500);

        int inBox = ScreenProbe.CountMagenta((int)(cx - halfW + 3), (int)(cy - 30), (int)(halfW * 2 - 6), 60);
        int outside = ScreenProbe.CountMagenta((int)(cx - 500), (int)(cy - 30), 300, 60);
        int inkAfter = ScreenProbe.CountMagenta((int)(cx - 500), (int)(cy - 40), 1000, 80);
        Check("上屏：框里的墨归零、框外的还在",
              inkBefore > 500 && inBox < 20 && outside > 300 && inkAfter > inkBefore * 0.8,
              $"画上 {inkBefore} 像素 → 框里 {inBox}、框外 {outside}，全带 {inkAfter}"
              + $"（应 ≈ {inkBefore} 减去被擦的那一段，不掉远处的墨）");

        // --- 8. 手测台（--eraserlab）的记录链路：写进去的必须是"能算的数" -------------
        // 这条不是在验橡皮，是在验"我事后拿到的数据靠得住"——列数、单位、落盘时机。
        string labCsv = Path.Combine(Path.GetTempPath(), "inklab-smoke.csv");
        string labTxt = Path.Combine(Path.GetTempPath(), "inklab-smoke.txt");
        try { File.Delete(labCsv); File.Delete(labTxt); } catch { /* 删不掉就覆盖 */ }
        var lab = new EraserTelemetry(labCsv, labTxt, NowMs);
        lab.BeginDrag(Tool.PixelEraser, cx - 200, cy, NowMs);
        lab.Step(3, Doc.TotalIntervals, Doc.Strokes.Count, 0.42, cx - 200, cy, NowMs);
        lab.Step(2, Doc.TotalIntervals, Doc.Strokes.Count, 0.31, cx - 150, cy + 10, NowMs + 20);
        lab.Frame(1.5, 8.0);
        lab.Note("撤销", NowMs + 30);
        lab.EndDrag(Doc, Doc.UndoDepth, NowMs + 40);
        lab.Close(Doc, NowMs + 50);
        var labLines = File.Exists(labCsv) ? File.ReadAllLines(labCsv) : Array.Empty<string>();
        var labCols = labLines.Length >= 2 ? labLines[1].Split(',') : Array.Empty<string>();
        Check("手测台：CSV 落盘、列数与数值都对",
              labLines.Length == 2 && labCols.Length == 26 && labCols[1] == "像素橡皮"
              && Math.Abs(double.Parse(labCols[3]) - 40) < 0.6 && labCols[4] == "2",
              labLines.Length >= 2
                ? $"{labLines.Length - 1} 条拖拽、{labCols.Length} 列；工具 {labCols[1]}、"
                  + $"时长 {labCols[3]}ms、采样 {labCols[4]}、擦到 {labCols[8]} 笔"
                : "没有写出 CSV");
        Check("手测台：退出时的汇总也写了", File.Exists(labTxt),
              File.Exists(labTxt) ? Path.GetFileName(labTxt) : "缺汇总文件");

        // --- 9. 擦断之后"两截各自独立"（用户 2026-09-15 定的语义）------------------
        //
        // "橡皮擦中墨迹或者图形，如果断开了结构，选中分开以后单独算"：擦完就是两条**独立对象**，
        // 能分别选中、分别搬。带变换的笔迹拆出来的段要**继承原变换**（点仍是局部坐标）。
        Doc.Clear();
        Doc.ClearHistory();

        var longLine2 = new Stroke
        {
            Tool = Tool.Pen, Color = new Color4(1f, 0f, 1f, 1f), Width = penW,
            // 带一点旋转 + 非等比缩放：拆段时**变换必须原样继承**（点还是局部坐标）
            // 注意变换要在 AddStroke **之前**设好：空间网格按添加时的包围盒索引，
            // 加进去之后再改变换，网格就过期了（擦除会擦不到——这里踩过一次）。
            Transform = Matrix3x2.CreateRotation(0.3f)
                      * Matrix3x2.CreateScale(1.4f, 0.8f)
                      * Matrix3x2.CreateTranslation(cx - 600, cy),
        };
        for (int i = 0; i <= 120; i++) longLine2.AddPoint(60 + i * 10, 200, 0.9f, i);
        Doc.AddStroke(longLine2);
        Doc.InvalidateAll();

        var wp = longLine2.PointAtParam(60);                 // 参数 60 处的画布坐标
        Vector2 canvasMid = Vector2.Transform(wp, longLine2.Transform);
        Doc.BeginEraseRect();
        Doc.EraseRectAt(canvasMid.X, canvasMid.Y, 30f, 60f);
        Doc.EndErase();
        var cut2 = Doc.Strokes.ToArray();
        bool gotTwo = cut2.Length == 2 && !Doc.Strokes.Contains(longLine2);
        bool transformKept = gotTwo
                          && cut2[0].Transform.Equals(longLine2.Transform)
                          && cut2[1].Transform.Equals(longLine2.Transform)
                          && cut2[0].Erased.Count == 0 && cut2[1].Erased.Count == 0;
        Check("带变换的长笔擦断 → 两条独立对象、变换原样继承",
              gotTwo && transformKept,
              gotTwo ? $"对象 {cut2.Length}，变换继承 {(transformKept ? "是" : "否")}，"
                     + $"点数 {cut2[0].Points.Count}/{cut2[1].Points.Count}"
                     : $"对象 {cut2.Length}（应 2）");

        // **每一截能单独选中**（这就是"分开以后单独算"）：框住其中一段，只该选中那一段
        Doc.Selected.Clear();
        var onePiece = cut2[0].WorldBounds.Inflate(10f);
        Doc.ApplyMarquee(onePiece);
        Check("框住其中一段 → 只选中那一段（不再整条一起选）",
              Doc.Selected.Count == 1 && ReferenceEquals(Doc.Selected[0], cut2[0]),
              $"选中 {Doc.Selected.Count} 条");

        // SplitErasedSelection（Ctrl+Alt+8）现在只服务"老存档里带区间的笔迹"，本轮该返回 0
        Doc.SelectOnly(new[] { cut2[0] });
        Check("已经拆断的笔迹再按'拆开' → 无事可做",
              Doc.SplitErasedSelection() == 0, "返回 0");

        Doc.Undo();
        Check("撤销擦断：回到原来那一条（同一个对象、变换不变）",
              Doc.Strokes.Count == 1 && ReferenceEquals(Doc.Strokes[0], longLine2)
              && longLine2.Erased.Count == 0,
              $"对象 {Doc.Strokes.Count}，区间 {longLine2.Erased.Count} 段");

        Doc.Redo();
        Check("重做：又变回两条独立对象",
              Doc.Strokes.Count == 2 && !Doc.Strokes.Contains(longLine2),
              $"对象 {Doc.Strokes.Count}");

        // --- 10. 图像：两种橡皮都不碰（原则：图像是"内容"，不是笔画）-----------------
        Doc.Clear();
        Doc.ClearHistory();
        var pic = Doc.AddImage(MakeTestImage(400, 300), cx - 200, cy - 150, 1f);
        Doc.EraseRectAt(cx, cy, 40f, 40f);          // 像素橡皮的调用
        bool picIntact = Doc.Strokes.Contains(pic) && Doc.Strokes.Count == 1;
        Doc.EraseAt(cx, cy, 40f);                   // 整笔橡皮的调用
        picIntact &= Doc.Strokes.Contains(pic) && Doc.Strokes.Count == 1;
        Check("图像：两种橡皮都不碰（要删它用框选 + Delete）", picIntact,
              $"试了像素橡皮和整笔橡皮各一下，对象数 {Doc.Strokes.Count}，"
              + $"图 {(Doc.Strokes.Contains(pic) ? "还在" : "**被删掉了**")}");

        Console.WriteLine($"  合计：通过 {pass}，失败 {fail}");
        Console.WriteLine(fail == 0 ? "PASS" : "FAIL");
        _quit = true;
    }

    /// <summary>
    /// 剪贴板**对象通道**自检（--clipboardtest）。
    ///
    /// 验的是"复制一段板书 → 粘到别处 → 还是可编辑对象"这条链，分四段：
    ///   ① 写进去的对象字节读回来**逐字段一致**（点数 / 粗细 / 颜色 / 变换 / 擦除区间 /
    ///      图像像素），差一个字段就是"粘回来少了一块"；
    ///   ② 身份必须**重新发**（Id 归零）：文件里的 Id 是原对象的，直接插进同一个文档
    ///      会和原件撞号，撤销 / 多选就会指错对象；
    ///   ③ 同一次复制里还夹着一张**图**（Word / PPT / 微信粘得到），尺寸 = 选区包围盒
    ///      两边各留 4 逻辑像素，背景**全透明**（粘到别处不该带我们的白底）；
    ///   ④ 粘贴是**智能**的：有对象格式就粘对象（落视口左上角、自动选中、一步撤销），
    ///      只剩一张图才退回"当图粘"——两条分支都要真的走一遍。
    ///
    /// **这个用例会覆盖系统剪贴板**（和 --capturetest 一样）：跑之前先存好要粘的东西。
    /// 剪贴板被别的程序占着时会明确报出来并跳过，那是环境问题，不是 bug。
    /// </summary>
    private void ClipboardTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 剪贴板对象通道自检（复制 → 粘回来仍是对象）===");
        Console.WriteLine("  注意：本用例会覆盖系统剪贴板（跑之前先存好要粘的东西）");

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-32} {detail}");
        }

        // 逐字段比对：任何一处不同都回报"差在哪"，不靠肉眼看数字。
        static bool SameStroke(Stroke a, Stroke b, out string why)
        {
            why = "";
            if (a.Tool != b.Tool) { why = "工具不同"; return false; }
            if (a.Kind != b.Kind) { why = "类型不同"; return false; }
            if (a.Width != b.Width) { why = $"粗细 {a.Width} → {b.Width}"; return false; }
            if (a.Color.R != b.Color.R || a.Color.G != b.Color.G
                || a.Color.B != b.Color.B || a.Color.A != b.Color.A)
            { why = $"颜色 {a.Color} → {b.Color}"; return false; }
            if (!a.Transform.Equals(b.Transform)) { why = "变换不同"; return false; }
            if (a.IsImage != b.IsImage) { why = "一个像是一个不是"; return false; }
            if (a.IsImage)
            {
                if (a.Image.Width != b.Image.Width || a.Image.Height != b.Image.Height)
                { why = $"图 {a.Image.Width}×{a.Image.Height} → {b.Image.Width}×{b.Image.Height}"; return false; }
                if (a.Image.Bgra.Length != b.Image.Bgra.Length) { why = "图像字节数不同"; return false; }
                for (int i = 0; i < a.Image.Bgra.Length; i++)
                    if (a.Image.Bgra[i] != b.Image.Bgra[i]) { why = $"图像第 {i} 个字节"; return false; }
            }
            if (a.Points.Count != b.Points.Count)
            { why = $"点数 {a.Points.Count} → {b.Points.Count}"; return false; }
            for (int i = 0; i < a.Points.Count; i++)
            {
                var p = a.Points[i]; var q = b.Points[i];
                // 时间戳是"绝对量 + float 偏移"，会有浮点截断，给 0.05ms 容差（同存档自检）。
                if (p.X != q.X || p.Y != q.Y || p.P != q.P || Math.Abs(p.T - q.T) > 0.05)
                { why = $"第 {i} 个点"; return false; }
            }
            if (a.Erased.Count != b.Erased.Count)
            { why = $"擦除区间 {a.Erased.Count} 段 → {b.Erased.Count} 段"; return false; }
            for (int i = 0; i < a.Erased.Count; i++)
                if (a.Erased[i] != b.Erased[i]) { why = $"第 {i} 段擦除区间"; return false; }
            return true;
        }

        float cx = _virtualX + _virtualW * 0.5f, cy = _virtualY + _virtualH * 0.5f;

        // --- 0. 没选中时不该动剪贴板 -------------------------------------------
        Doc.Clear();
        Doc.ClearHistory();
        Check("没选中任何东西 → 不写剪贴板", !CopySelectionToClipboard(),
              "返回 false，剪贴板里原来的东西不动");

        // --- 1. 造三条要复制的东西 ---------------------------------------------
        var plain = new Stroke
        {
            Tool = Tool.Pen, Color = new Color4(0.1f, 0.35f, 0.95f, 1f), Width = 7.5f,
        };
        for (int i = 0; i <= 40; i++) plain.AddPoint(cx - 320 + i * 8, cy - 60, 0.9f, 1000 + i * 8);

        var turned = new Stroke
        {
            Tool = Tool.Pen, Color = new Color4(1f, 0f, 1f, 1f), Width = 12f,
            // 变换要在 AddStroke **之前**设好（空间网格按添加时的包围盒索引，见像素橡皮自检）
            Transform = Matrix3x2.CreateRotation(0.37f)
                      * Matrix3x2.CreateScale(1.3f, 0.7f)
                      * Matrix3x2.CreateTranslation(cx - 160, cy + 120),
        };
        for (int i = 0; i <= 60; i++) turned.AddPoint(i * 6, 40, 0.7f, 2000 + i * 4);
        turned.AddErased(12f, 20f);                 // 假装被像素橡皮擦掉两段
        turned.AddErased(30.5f, 33f);

        Doc.AddStroke(plain);
        Doc.AddStroke(turned);
        var picture = Doc.AddImage(MakeTestImage(48, 32), cx + 120, cy + 60, 1f);

        Doc.SelectOnly(new[] { plain, turned, picture });
        var expect = new[] { plain, turned, picture };
        var box = EditRegion.Of(expect);

        // --- 2. 复制 → 读回对象 ------------------------------------------------
        bool copied = CopySelectionToClipboard();
        if (!copied)
        {
            Console.WriteLine("  环境：剪贴板被别的程序占着 → SKIP: 剪贴板相关的几项跳过"
                            + "（关掉占用剪贴板的程序再跑）");
            Console.WriteLine($"  合计：通过 {pass}，失败 {fail}（剪贴板相关未验）");
            _quit = true;
            return;
        }

        bool gotObjects = ClipboardInk.TryGetObjects(out var back);
        Check("读回来的是**对象**（不是图）", gotObjects && back.Count == expect.Length,
              gotObjects ? $"{back.Count} 个对象（期望 {expect.Length}）" : "读不到我们的对象格式，只剩图了");

        bool same = gotObjects && back.Count == expect.Length;
        string diff = "";
        if (same)
            for (int i = 0; i < expect.Length; i++)
                if (!SameStroke(expect[i], back[i], out diff))
                { same = false; diff = $"第 {i} 个对象：{diff}"; break; }
        Check("逐字段一致（含变换 / 擦除区间 / 图像像素）",
              same,
              same ? $"3 个对象全对上（擦除区间 {turned.Erased.Count} 段、图 48×32 逐字节）" : diff);

        bool idsCleared = gotObjects && back.Count > 0;
        if (idsCleared)
            foreach (var s in back) if (s.Id != 0) idsCleared = false;
        Check("身份重新发（Id 归零）", idsCleared,
              idsCleared ? "读回来的都是 0，粘进文档时由文档发新号"
                         : $"还带着原 Id：{string.Join(",", back.ConvertAll(s => s.Id))}");

        // --- 3. 同一份剪贴板里那张图（给外部程序的兜底）-------------------------
        // 期望尺寸用**和复制那条路完全一样的算式**（先 Inflate 再相减），
        // 换成"宽度 + 两边留白"会和它在浮点上差一丢丢，跨整数边界就成了假失败。
        float margin = 4f * DpiScale;
        var boxIn = box.Inflate(margin);
        int expW = Math.Max(1, (int)MathF.Ceiling(boxIn.MaxX - boxIn.MinX));
        int expH = Math.Max(1, (int)MathF.Ceiling(boxIn.MaxY - boxIn.MinY));
        bool gotImg = ClipboardImage.TryGetImage(out var dib, out int bw, out int bh, out _);
        Check("同一份剪贴板里还有一张图", gotImg && bw == expW && bh == expH,
              gotImg ? $"{bw}×{bh}，期望 {expW}×{expH}"
                     : "没读到 CF_DIB（外部程序粘不到了）");

        if (gotImg && bw > 0 && bh > 0)
        {
            // 背景必须透明：粘到 PPT 上不该压一块白底。
            int corner = 3;                                  // 左上角那个像素的 alpha
            int opaque = 0;
            for (int i = 3; i < dib.Length; i += 4) if (dib[i] > 8) opaque++;
            Check("那张图背景透明、内容非空",
                  dib[corner] < 8 && opaque > 100,
                  $"左上角 alpha {dib[corner]}（期望 0），不透明像素 {opaque} 个");
        }

        // --- 4. 智能粘贴：有对象 → 粘成对象 ------------------------------------
        Doc.Clear();
        Doc.ClearHistory();
        int undos0 = Doc.UndoDepth;
        bool pasted = PasteFromClipboard();
        bool asObjects = pasted && Doc.Strokes.Count == expect.Length
                      && Doc.Selected.Count == expect.Length;
        Check("粘贴：有对象格式就粘成**对象**（不是一张图）", asObjects,
              asObjects ? $"{Doc.Strokes.Count} 个对象、全选中"
                        : $"对象数 {Doc.Strokes.Count}、选中 {Doc.Selected.Count}（期望 3 / 3）");

        var vp = ViewportCanvas;
        float m = CaptureMarginLogical * DpiScale;
        var pastedBox = EditRegion.Of(Doc.Strokes);
        Check("粘到视口左上角（含留白）",
              Math.Abs(pastedBox.MinX - (vp.MinX + m)) < 0.6f
              && Math.Abs(pastedBox.MinY - (vp.MinY + m)) < 0.6f,
              $"落在 ({pastedBox.MinX:F0},{pastedBox.MinY:F0})，期望 ({vp.MinX + m:F0},{vp.MinY + m:F0})");

        bool newIds = Doc.Strokes.Count > 0;
        foreach (var s in Doc.Strokes) if (s.Id == 0) newIds = false;
        Check("粘进来的对象拿到了新身份", newIds,
              newIds ? $"Id {Doc.Strokes[0].Id}…（不是 0，也不和原件相等）" : "有对象的 Id 还是 0");

        bool erasedKept = Doc.Strokes.Count == 3;
        if (erasedKept)
        {
            var backTurned = Doc.Strokes.Find(s => s.Erased.Count > 0);
            erasedKept = backTurned != null && backTurned.Erased.Count == turned.Erased.Count;
        }
        Check("粘回来的笔迹还带着擦除区间（擦掉的墨不会画回来）", erasedKept,
              erasedKept ? $"区间 {Doc.Strokes.Find(s => s.Erased.Count > 0).Erased.Count} 段"
                         : "区间丢了");

        Doc.Undo();
        Check("粘贴算一步撤销（3 个对象一起回去）",
              Doc.Strokes.Count == 0 && Doc.UndoDepth == undos0,
              $"撤销后对象 {Doc.Strokes.Count}，撤销栈回到 {Doc.UndoDepth}");

        // --- 5. 只有图（没有对象格式）→ 退回"当图粘" ---------------------------
        var little = MakeTestImage(64, 48);
        bool wroteImg = ClipboardImage.SetImage(little.Bgra, little.Width, little.Height);
        Check("准备：把剪贴板换成一张纯图（对象格式没了）", wroteImg,
              wroteImg ? "写进去 64×48" : "写不进去（被别的程序占着？）");
        if (wroteImg)
        {
            bool hadObjects = ClipboardInk.TryGetObjects(out _);
            Check("这时候剪贴板里确实没有对象了", !hadObjects,
                  hadObjects ? "居然还读得到对象" : "只剩 CF_DIB");

            Doc.Clear();
            Doc.ClearHistory();
            bool pasted2 = PasteFromClipboard();
            bool asImage = pasted2 && Doc.Strokes.Count == 1 && Doc.Strokes[0].IsImage
                        && Doc.Strokes[0].Image.Width == 64 && Doc.Strokes[0].Image.Height == 48;
            Check("只有图时退回当图粘（老行为不变）", asImage,
                  asImage ? "粘成一个 64×48 的图像对象、自动选中"
                          : $"对象数 {Doc.Strokes.Count}，"
                            + (Doc.Strokes.Count > 0 ? $"Kind={Doc.Strokes[0].Kind}" : "什么都没有"));

            int diff2 = -1;
            if (asImage)
            {
                diff2 = 0;
                var got = Doc.Strokes[0].Image.Bgra;
                for (int i = 0; i < got.Length; i++) if (got[i] != little.Bgra[i]) diff2++;
            }
            Check("粘回来的图逐字节一致", diff2 == 0,
                  diff2 < 0 ? "上一条没过，这条没验" : $"差异 {diff2} 字节");
        }

        Doc.Clear();
        Console.WriteLine("  剪贴板里现在留着自检那张 64×48 的图（退出不会恢复你原来的内容）");
        Console.WriteLine($"  合计：通过 {pass}，失败 {fail}");
        Console.WriteLine(fail == 0 ? "PASS" : "FAIL");
        _quit = true;
    }

    /// <summary>
    /// 套索自检（--lassotest）。判据全是能算出来的数，不看屏幕。
    ///
    /// 七条：
    ///   ① `Ctrl+Alt+9` 真的在切方式（默认矩形）；
    ///   ② **80% 边界**：代表点 79% 在圈里 → 不选，81% → 选（WPF 的 _percentIntersectForInk）；
    ///   ③ **贴边＝无限延伸**：同一条半个身子在屏幕外的长笔迹，圈贴左边 → 选中；
    ///      圈不贴边（只有可见的那一小段在圈里）→ 不选。这一对**必须成对验**，
    ///      只验"贴边选中"看不出延伸是不是把什么都选进来了；
    ///   ④ **图形按轮廓判**：矩形只差右下角没圈住（4/5 轮廓点）→ 选；
    ///      再少一个角（3/5）→ 不选。用"两个端点"当代表点的话前者会漏选；
    ///   ⑤ **图像按四个角判**：四角全在圈里 → 选；少一个角（3/4 = 75%）→ 不选；
    ///   ⑥ **被擦掉的那一段不算墨**：圈住一条笔迹"被擦掉的那半截"，不该选中它；
    ///   ⑦ 引擎那条路（按下→拖→松手）真的会用这条判据；路径太短＝单击空白＝取消选中。
    /// </summary>
    private void LassoTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 套索自检（80% 判据 / 贴边无限延伸 / 加选减选）===");

        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"  {(ok ? "通过" : "失败")}  {name,-30} {detail}");
        }

        static List<Vector2> Box(float x0, float y0, float x1, float y1) => new()
        {
            new Vector2(x0, y0), new Vector2(x1, y0),
            new Vector2(x1, y1), new Vector2(x0, y1),
        };

        float cx = _virtualX + _virtualW * 0.5f, cy = _virtualY + _virtualH * 0.5f;
        var vp = ViewportCanvas;
        float snap = LassoEdgeSnapLogical * DpiScale;
        var realOut = Console.Out;                    // 掐掉 ApplyLasso 与手势里的控制台输出
        void Quiet(Action a) { Console.SetOut(TextWriter.Null); try { a(); } finally { Console.SetOut(realOut); } }

        // --- 0. 切换方式 --------------------------------------------------------
        Check("默认是矩形框", SelMode == SelectMode.Rect, SelMode.ToString());
        SelMode = SelectMode.Rect;
        ToggleSelectModeForTest();
        bool toLasso = SelMode == SelectMode.Lasso;
        ToggleSelectModeForTest();
        Check("Ctrl+Alt+9 在两种方式之间切", toLasso && SelMode == SelectMode.Rect,
              $"矩形 → {(toLasso ? "套索" : "?")} → {SelMode}");

        // --- 1. 80% 边界（79% 不选 / 81% 选）------------------------------------
        Doc.Clear();
        Doc.ClearHistory();
        var boxPath = Box(cx - 150, cy - 150, cx + 150, cy + 150);

        Stroke MakeRow(int insideCount)
        {
            var s = new Stroke { Tool = Tool.Pen, Color = new Color4(0f, 0f, 0f, 1f), Width = 3f };
            for (int i = 0; i < 100; i++)
            {
                if (i < insideCount)
                    s.AddPoint(cx - 100 + (i % 10) * 22, cy - 100 + (i / 10) * 25, 1f, i);   // 圈里
                else
                    s.AddPoint(cx + 400 + (i % 20) * 5, cy - 100 + (i / 20) * 25, 1f, i);    // 圈外
            }
            return s;
        }

        // 两条**分开测**：放一个文档里的话，81% 那条本来就会被选中，
        // "79% 没被选中"这件事就看不出来了（第一版就是这么写错的）。
        var s79 = MakeRow(79);
        Doc.AddStroke(s79);
        int n79 = Doc.ApplyLasso(boxPath, vp, snap);
        Check("79% 在圈里 → 不选", n79 == 0 && Doc.Selected.Count == 0,
              $"判中 {n79} 条（80% 是门槛，79/100 必须落空）");

        Doc.Clear();
        Doc.ClearHistory();
        var s81 = MakeRow(81);
        Doc.AddStroke(s81);
        int n81 = Doc.ApplyLasso(boxPath, vp, snap);
        Check("81% 在圈里 → 选中",
              n81 == 1 && Doc.Selected.Count == 1 && ReferenceEquals(Doc.Selected[0], s81),
              $"判中 {n81} 条（81/100 ≥ 80%）");

        // --- 2. 贴边＝无限延伸 --------------------------------------------------
        Doc.Clear();
        Doc.ClearHistory();
        var longLine = new Stroke { Tool = Tool.Pen, Color = new Color4(0f, 0f, 0f, 1f), Width = 6f };
        for (int i = 0; i < 120; i++) longLine.AddPoint(vp.MinX - 800 + i * 10, cy, 1f, i);
        Doc.AddStroke(longLine);
        int total = longLine.Points.Count;                 // 120
        int visibleInside = 110;                           // x < vp.MinX + 300 的那些

        var awayFromEdge = Box(vp.MinX + 50, cy - 100, vp.MinX + 300, cy + 100);
        int nAway = Doc.ApplyLasso(awayFromEdge, vp, snap);
        Check("圈不贴边 → 屏幕外那半截不算（不选）", nAway == 0 && Doc.Selected.Count == 0,
              $"判中 {nAway} 条（圈里只有约 25/{total} 个点，{(25 * 100 / total)}%）");

        var touchEdge = Box(vp.MinX, cy - 100, vp.MinX + 300, cy + 100);
        int nEdge = Doc.ApplyLasso(touchEdge, vp, snap);
        Check("圈贴着屏幕左边 → 当作圈到无限远（选中）",
              nEdge == 1 && Doc.Selected.Count == 1 && ReferenceEquals(Doc.Selected[0], longLine),
              $"判中 {nEdge} 条（延伸后圈里 {visibleInside}/{total} 个点 = "
              + $"{visibleInside * 100 / total}% ≥ 80%）");

        // --- 3. 图形按**轮廓**判，不按两个端点 ----------------------------------
        Doc.Clear();
        Doc.ClearHistory();
        var bigRect = new Stroke
        {
            Tool = Tool.Rectangle, Kind = StrokeKind.Rectangle,
            Color = new Color4(0.9f, 0.2f, 0.2f, 1f), Width = 4f,
        };
        bigRect.AddPoint(cx - 600, cy - 400, 1f, 0);
        bigRect.AddPoint(cx + 600, cy + 400, 1f, 0);        // 端点是那条斜对角线
        Doc.AddStroke(bigRect);

        // 只把右下角切掉一点：轮廓 5 个点里 4 个在圈里（= 80%），两个端点里只有 1 个
        var cutCorner = new List<Vector2>
        {
            new(cx - 700, cy - 500), new(cx + 700, cy - 500), new(cx + 700, cy + 300),
            new(cx + 560, cy + 420), new(cx - 700, cy + 420),
        };
        int nRect = Doc.ApplyLasso(cutCorner, vp, snap);
        Check("矩形：4/5 个轮廓点在圈里 → 选中", nRect == 1,
              $"判中 {nRect} 条（轮廓 5 点里 4 点在内 = 80%；按两个端点算只有 50%，会漏选）");

        var noBottom = Box(cx - 700, cy - 500, cx + 700, cy + 300);
        int nRect2 = Doc.ApplyLasso(noBottom, vp, snap);
        Check("矩形：只有 3/5 个轮廓点在圈里 → 不选", nRect2 == 0,
              $"判中 {nRect2} 条（60% < 80%）");

        // --- 4. 图像按四个角判 --------------------------------------------------
        Doc.Clear();
        Doc.ClearHistory();
        var pic = Doc.AddImage(MakeTestImage(300, 200), cx - 500, cy - 300, 1f);
        int nPicAll = Doc.ApplyLasso(Box(cx - 600, cy - 400, cx - 100, cy), vp, snap);
        Check("图像：四个角都在圈里 → 选中", nPicAll == 1,
              $"判中 {nPicAll} 条（角点 4/4 = 100%）");

        int nPic3 = Doc.ApplyLasso(Box(cx - 600, cy - 400, cx - 200, cy), vp, snap);
        Check("图像：只圈住三个角 → 不选", nPic3 == 0,
              $"判中 {nPic3} 条（3/4 = 75% < 80%）");

        // --- 5. 被擦掉的那一段不算墨 --------------------------------------------
        Doc.Clear();
        Doc.ClearHistory();
        var erasedMost = new Stroke { Tool = Tool.Pen, Color = new Color4(0f, 0f, 0f, 1f), Width = 6f };
        for (int i = 0; i < 20; i++) erasedMost.AddPoint(cx, cy - 190 + i * 20, 1f, i);
        erasedMost.AddErased(0f, 16f);                      // 上面 17 个点那一段被擦掉
        Doc.AddStroke(erasedMost);
        int remaining = 0;
        for (int i = 0; i < erasedMost.Points.Count; i++)
            if (!erasedMost.IsParamErased(i)) remaining++;
        int nErased = Doc.ApplyLasso(Box(cx - 100, cy - 200, cx + 100, cy + 100), vp, snap);
        Check("圈住被擦掉的那半截 → 不选", nErased == 0 && Doc.Selected.Count == 0,
              $"判中 {nErased} 条（圈里还剩 {remaining} 个没被擦的点 = "
              + $"{remaining * 100 / erasedMost.Points.Count}%；把擦掉的也算上就是 85%，会误选）");

        // --- 6. Shift 加选 / Alt 减选 -------------------------------------------
        Doc.Clear();
        Doc.ClearHistory();
        var left = MakeRow(100);                            // 全在圈里
        var right = Doc.AddImage(MakeTestImage(80, 80), cx + 400, cy + 400, 1f);
        Doc.AddStroke(left);
        Doc.SelectOnly(new[] { right });
        int nAdd = Doc.ApplyLasso(boxPath, vp, snap, additive: true);
        bool added = Doc.Selected.Count == 2 && Doc.Selected.Contains(left) && Doc.Selected.Contains(right);
        Check("Shift 加选：原有的不丢", nAdd == 1 && added,
              $"判中 {nAdd} 条，选区 {Doc.Selected.Count} 条（图像 + 笔迹）");

        int nSub = Doc.ApplyLasso(boxPath, vp, snap, subtractive: true);
        bool removed = Doc.Selected.Count == 1 && Doc.Selected.Contains(right) && !Doc.Selected.Contains(left);
        Check("Alt 减选：只把它移出去", nSub == 1 && removed,
              $"判中 {nSub} 条，选区剩 {Doc.Selected.Count} 条（图像还在）");

        // --- 7. 引擎那条路（按下 → 拖 → 松手）-----------------------------------
        Doc.Clear();
        Doc.ClearHistory();
        var target = MakeRow(100);
        Doc.AddStroke(target);
        Doc.Selected.Clear();
        SelMode = SelectMode.Lasso;
        Quiet(() => MarqueeDragForTest(boxPath));
        Check("引擎：走一次完整套索手势 → 选中", Doc.Selected.Count == 1 && Doc.Selected.Contains(target),
              $"选中 {Doc.Selected.Count} 条，路径已清空={LassoPath.Count == 0}");

        Quiet(() => MarqueeDragForTest(new[] { new Vector2(cx, cy), new Vector2(cx + 1, cy + 1) }));
        Check("引擎：路径太短＝单击空白 → 取消选中", Doc.Selected.Count == 0,
              $"选中 {Doc.Selected.Count} 条（和框选那条规则一致）");

        // --- 8. 拽着不放时屏幕上真有那根线（差分判据，抓屏拍不到就跳过）----------
        // 预览画的是自由折线，和矩形框不是同一段代码；不验的话"套索拖起来什么都看不见"
        // 这种问题要等人肉测才发现。
        Doc.Clear();
        Doc.ClearHistory();
        SelMode = SelectMode.Lasso;
        MarqueeActive = false;
        LassoPath.Clear();
        Doc.InvalidateAll();
        SettleFrames(400);

        int bandX = (int)(cx - 220), bandY = (int)(cy - 190);
        int bandYpx = (int)(cy - 190 + ViewOffsetY);
        const int bandW = 440, bandH = 70;
        var sight = new Stroke { Tool = Tool.Pen, Color = new Color4(1f, 0f, 1f, 1f), Width = 10f };
        for (int i = 0; i <= 20; i++) sight.AddPoint(cx - 200 + i * 20, cy - 150, 1f, i);
        Doc.AddStroke(sight);
        Doc.InvalidateAll();
        SettleFrames(400);
        int canSee = ScreenProbe.CountMagenta(bandX, bandYpx, bandW, bandH);
        Doc.Clear();
        Doc.InvalidateAll();
        SettleFrames(400);

        if (canSee < 200)
        {
            Console.WriteLine($"  环境：抓屏看不到我们的层（拍到的是桌面/别的窗口，{canSee} 像素）"
                            + " → SKIP: 预览那一条跳过");
        }
        else
        {
            var before = ScreenProbe.CaptureRegion(bandX, bandYpx, bandW, bandH);
            MarqueeActive = true;
            LassoPath.AddRange(boxPath);
            LassoLive = boxPath[boxPath.Count - 1];      // 线头画在指针位置（这里就是最后一个点）
            MqMinX = boxPath[0].X; MqMinY = boxPath[0].Y;
            MqMaxX = boxPath[2].X; MqMaxY = boxPath[2].Y;
            Doc.InvalidateAll();
            SettleFrames(400);
            var after = ScreenProbe.CaptureRegion(bandX, bandYpx, bandW, bandH);

            int changed = 0;
            for (int i = 0; i + 3 < Math.Min(before.Length, after.Length); i += 4)
            {
                int d = Math.Abs(before[i] - after[i]) + Math.Abs(before[i + 1] - after[i + 1])
                      + Math.Abs(before[i + 2] - after[i + 2]);
                if (d > 40) changed++;
            }
            // 圈的上边正好横穿这条带子：300 逻辑像素长 × 1.6 宽（DPI 2 → 约 3 像素）
            Check("拽着不放时屏幕上真画出了那条线", changed > 200,
                  $"这条带子里变了 {changed} 个像素（上边线横穿过去，应该上千）");

            MarqueeActive = false;
            LassoPath.Clear();
            Doc.InvalidateAll();
            SettleFrames(200);
        }

        // --- 9. 切回矩形：同一个手势变成"碰到就选" -----------------------------
        Doc.Clear();
        Doc.ClearHistory();
        var rectTarget = MakeRow(100);
        Doc.AddStroke(rectTarget);
        Doc.Selected.Clear();
        SelMode = SelectMode.Rect;
        // 矩形模式喂**两个点**（锚点 → 对角）就够：矩形是按"锚点 ↔ 当前点"算的，
        // 喂一圈闭合路径的话锚点和终点会重合，等于拉出一个零面积的框。
        Quiet(() => MarqueeDragForTest(new[]
        {
            new Vector2(cx - 150f, cy - 150f),
            new Vector2(cx + 150f, cy + 150f),
        }));
        Check("切回矩形：同一个手势变成'碰到就选'",
              SelMode == SelectMode.Rect && Doc.Selected.Count == 1 && Doc.Selected.Contains(rectTarget),
              $"矩形模式下选中 {Doc.Selected.Count} 条（同一个矩形范围，换了一套判据）");

        Doc.Clear();
        Console.WriteLine($"  合计：通过 {pass}，失败 {fail}");
        Console.WriteLine(fail == 0 ? "PASS" : "FAIL");
        _quit = true;
    }

    /// <summary>
    /// 图形与**顶点拖动**自检。
    ///
    /// 关键在最后两条：顶点手柄和选中框的角手柄在屏幕上重合，所以"到底拖到了
    /// 哪一个"必须验；以及**旋转过的图形，顶点必须拖动在它自己的坐标系里**
    /// （否则一转，矩形就不再是矩形了——这类 bug 肉眼一看才发现，且很晚）。
    /// </summary>
    /// <summary>
    /// 合成输入探针：往屏幕中间划一小段，看窗口到底收不收到消息。
    /// 返回 true = 输入通。**它只回答环境问题**，不判功能对错。
    /// </summary>
    /// <summary>
    /// 合成输入不可用时，把依赖真机拖动的自检标成"跳过"而不是"失败"。
    ///
    /// 为什么要这一层：覆盖层是置顶的，但这不代表消息一定送得到——
    /// 别的程序占着鼠标捕获时，我们的窗口一条消息都收不到（实测遇到过）。
    /// 那种情况下判 FAIL，会让人去查完全无关的功能代码。
    /// </summary>
    private bool SkipIfNoSyntheticInput(string what)
    {
        if (ProbeSyntheticInput(_virtualX + _virtualW * 0.5f, _virtualY + _virtualH * 0.4f)) return false;
        Console.WriteLine($"  环境：合成输入不可用 → SKIP: {what}跳过（多半是别的程序正占着鼠标；松开后重跑即可）");
        return true;
    }

    private bool ProbeSyntheticInput(float cx, float cy)
    {
        Tool = Tool.Pen;
        int before = Doc.Strokes.Count;
        SendMouse((int)cx, (int)cy, 0);
        SettleFrames(120);
        SendMouse((int)cx, (int)cy, Native.MOUSEEVENTF_LEFTDOWN);
        SettleFrames(60);
        SendMouse((int)(cx + 60), (int)(cy + 30), 0);
        SettleFrames(80);
        SendMouse((int)(cx + 60), (int)(cy + 30), Native.MOUSEEVENTF_LEFTUP);
        SettleFrames(200);

        // **先数再清**：下面那个 Clear() 会把刚画出来的这一笔也清掉，
        // 以前在这里直接 `return Doc.Strokes.Count > before`，于是永远返回 false
        // ——所有靠它把关的用例（残影、橡皮、截图……）其实一直在静默 SKIP，
        // 而屏幕上的日志却写着"合成输入不可用"，把锅推给了环境。
        // 判据必须取 Clear 之前的值。
        int after = Doc.Strokes.Count;
        Doc.Clear();
        Doc.ClearHistory();
        return after > before;
    }

    /// <summary>
    /// 图像对象自检：造图 → 命中 → 上屏 → 走通用操作（复制/翻转/删除）
    /// → 存档往返 → 剪贴板往返。
    ///
    /// 最后两项是重点：图像像素**必须**进得了文件、进得了剪贴板，
    /// 否则"截图发给学生"这件事就是断的。
    /// </summary>
    private void ImageTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 图像对象自检（截图 / 粘贴的图）===");
        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"    {name,-30}{(ok ? "PASS" : "FAIL")}  {detail}");
        }

        float cx = _virtualX + _virtualW * 0.4f, cy = _virtualY + _virtualH * 0.4f;
        const int W = 64, H = 64;
        byte[] pix = new byte[W * H * 4];
        for (int y = 0; y < H; y++)
            for (int x = 0; x < W; x++)
            {
                int i = (y * W + x) * 4;
                bool left = x < W / 2;
                pix[i + 0] = left ? (byte)255 : (byte)0;     // B
                pix[i + 1] = 0;                              // G
                pix[i + 2] = left ? (byte)255 : (byte)0;     // R（左半品红、右半黑）
                pix[i + 3] = 255;
            }

        Doc.Clear();
        Doc.ClearHistory();
        var img = ImageData.Adopt(W, H, pix, true);
        var placed = Doc.AddImage(img, cx, cy, 1f);
        Check("落地：对象是图像类型", placed != null && placed.IsImage, $"{placed?.Kind}");
        Check("落地：包围盒 = 像素尺寸 × 缩放",
              Math.Abs(placed.Bounds.MaxX - W) < 0.01f && Math.Abs(placed.Bounds.MaxY - H) < 0.01f,
              $"{placed.Bounds.MaxX:F0}×{placed.Bounds.MaxY:F0}");
        Check("落地：变换里带平移", Math.Abs(placed.Transform.M31 - cx) < 0.01f
                                  && Math.Abs(placed.Transform.M32 - cy) < 0.01f,
              $"({placed.Transform.M31:F0},{placed.Transform.M32:F0})");
        Check("命中：压在图上算命中", placed.HitTestExact(cx + 4, cy + 4), "");
        Check("命中：图外面不算", !placed.HitTestExact(cx - 40, cy - 40), "");

        // 真的画上去了吗：左边像素应该是品红
        Doc.InvalidateAll();
        SettleFrames(400);
        int leftPixels = ScreenProbe.CountMagenta((int)cx + 2, (int)cy + 2, W / 2 - 4, H - 4);
        Check("上屏：左半张画出来了（品红像素 > 500）", leftPixels > 500, $"{leftPixels} 像素");

        // 通用操作：复制 / 翻转 / 删除都走同一套（因为图像就是一个对象）
        Doc.Selected.Clear();
        Doc.Selected.Add(placed);
        Doc.DuplicateSelected(30f, 30f);
        Check("复制：图像也能复制（通用操作）", Doc.Strokes.Count == 2, $"{Doc.Strokes.Count} 个对象");
        var copy = Doc.Strokes[1];
        Check("复制：副本是新身份、像素共享",
              copy.Id != placed.Id && ReferenceEquals(copy.Image, placed.Image), $"id {copy.Id}");
        Doc.ApplyTransform(SelectionHandles.MirrorMatrix(placed.Bounds, horizontal: true));
        Check("翻转：图像也能翻（走同一条变换）", Math.Abs(copy.Transform.M11 + 1f) < 0.01f
                                              || Math.Abs(copy.Transform.M11 - 1f) > 0.5f,
              $"M11={copy.Transform.M11:F2}");

        // 存档往返
        Doc.Clear();
        Doc.ClearHistory();
        var img2 = ImageData.Adopt(W, H, (byte[])pix.Clone(), true);
        Doc.AddImage(img2, cx, cy, 1f);
        byte[] blob = InkSerializer.Save(Doc);
        var doc2 = new InkDocument();
        InkSerializer.LoadInto(doc2, blob);
        Check("存档：对象数对上", doc2.Strokes.Count == 1, $"{doc2.Strokes.Count} 个");
        bool samePixels = doc2.Strokes.Count == 1 && doc2.Strokes[0].Image != null
            && doc2.Strokes[0].Image.Width == W && doc2.Strokes[0].Image.Height == H;
        if (samePixels)
        {
            var a = doc2.Strokes[0].Image.Bgra;
            int diff = 0;
            for (int i = 0; i < a.Length; i++) if (a[i] != pix[i]) diff++;
            samePixels = diff == 0;
            Check("存档：像素逐字节一致", samePixels, $"差异 {diff} 字节");
        }
        else Check("存档：像素逐字节一致", false, "图像没读回来");
        Console.WriteLine($"    存档体积：{blob.Length / 1024.0:F1} KB（{W}×{H} 原始像素）");

        // 剪贴板往返（别的程序占着剪贴板时会失败，那是环境问题，不是 bug）
        var clipPix = (byte[])pix.Clone();
        bool wrote = ClipboardImage.SetImage(clipPix, W, H);
        if (!wrote)
        {
            Console.WriteLine("    剪贴板：写不进去（被别的程序占着？）——这项跳过");
        }
        else if (!ClipboardImage.TryGetImage(out var back, out int bw, out int bh, out _))
        {
            Check("剪贴板：读回来", false, "写成功但读不回来");
        }
        else
        {
            Check("剪贴板：尺寸一致", bw == W && bh == H, $"{bw}×{bh}");
            int diff = 0;
            for (int i = 0; i < Math.Min(back.Length, pix.Length); i++) if (back[i] != pix[i]) diff++;
            Check("剪贴板：像素一致", diff == 0, $"差异 {diff} 字节");
        }

        Console.WriteLine();
        Console.WriteLine(fail == 0 ? $"  PASS: 图像对象全通（{pass} 项）" : $"  FAIL: {fail} 项不对");
        _quit = true;
    }

    /// <summary>
    /// 截图自检（真机）：合成鼠标拖一个框，然后验三件事——
    ///   1. 生成了一个**图像对象**，尺寸等于拖出来的框（按 DPI 折成画布尺寸）；
    ///   2. 它落在**视口左上角**并自动选中（用户下一步就是拖它）；
    ///   3. **没有把自己的批注拍进去**（抓之前覆盖层藏起来了）——
    ///      这一条最重要：先在框里画一大片品红，抓到的图里品红必须≈0。
    /// </summary>
    private void CaptureTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 截图自检（拖框 → 左上角 → 剪贴板）===");
        int pass = 0, fail = 0;
        void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine($"    {name,-30}{(ok ? "PASS" : "FAIL")}  {detail}");
        }

        float cx = _virtualX + _virtualW * 0.5f, cy = _virtualY + _virtualH * 0.5f;
        float dpi = DpiScale;

        if (SkipIfNoSyntheticInput("截图全流程（需要拖框）")) { _quit = true; return; }

        // 先在要抓的这一块上涂满自己的墨（品红），用来验证"抓的时候墨不在图里"
        Doc.Clear();
        Doc.ClearHistory();
        for (int k = 0; k < 12; k++)
        {
            var s = new Stroke
            {
                Tool = Tool.Pen, Kind = StrokeKind.Freehand,
                Color = new Color4(1f, 0f, 1f, 1f), Width = 40f * dpi,
            };
            float y = cy - 110 + k * 20;
            for (int i = 0; i <= 20; i++) s.AddPoint(cx - 200 + i * 20, y, 0.9f, i);
            Doc.AddStroke(s);
        }
        Doc.InvalidateAll();
        SettleFrames(500);
        int onScreenInk = ScreenProbe.CountMagenta((int)(cx - 200), (int)(cy - 120), 400, 260);
        Check("准备：框里已经有一片墨", onScreenInk > 5000, $"{onScreenInk} 像素");

        // 换截图工具，拖一个 300×200 的框（两种模式各抓一次，所以抽成函数）
        Tool = Tool.Capture;
        int x0 = (int)(cx - 150), y0 = (int)(cy - 100);
        int x1 = (int)(cx + 150), y1 = (int)(cy + 100);
        int midReadoutDark = 0;                 // 拖动中"尺寸读数"那块有多深（见下面的量法）
        void DragCapture()
        {
            Tool = Tool.Capture;
            SendMouse(x0, y0, 0);
            SettleFrames(40);
            SendMouse(x0, y0, Native.MOUSEEVENTF_LEFTDOWN);
            SettleFrames(60);
            SendMouse((x0 + x1) / 2, y0 + 20, 0);
            SettleFrames(40);
            SendMouse(x1, y1, 0);
            SettleFrames(60);
            // **拖动中要有尺寸读数**（用户 2026-09-17："截图使用不顺手，光标配合也感觉不好"）：
            // 框的左下角外 6 逻辑像素处会画一个深色胶囊写着 "宽 × 高"。
            // 这里趁还没松手，量那块地方有没有深色像素（读数画出来了）。
            {
                int lx = (int)(Math.Min(x0, x1) * 1), ly = (int)(Math.Max(y0, y1) + 6 * DpiScale);
                int lw = (int)(96 * DpiScale), lh = (int)(26 * DpiScale);
                int dark = ScreenProbe.CountDark(lx, ly, lw, lh);
                midReadoutDark = dark;
            }
            SendMouse(x1, y1, Native.MOUSEEVENTF_LEFTUP);
            SettleFrames(900);                 // 截图里含一次"藏窗口 / 藏框 + 抓屏 + 恢复"
        }
        DragCapture();

        var shot = Doc.Strokes.FindLast(s => s.IsImage);
        Check("截图：生成了图像对象", shot != null, shot == null ? "没有" : $"{shot.Image.Width}×{shot.Image.Height} 物理像素");
        if (shot == null)
        {
            Console.WriteLine();
            Console.WriteLine("  FAIL: 截图没生成对象");
            _quit = true;
            return;
        }

        Check("截图：物理尺寸 = 拖出来的框", Math.Abs(shot.Image.Width - 300) <= 2
                                          && Math.Abs(shot.Image.Height - 200) <= 2,
              $"{shot.Image.Width}×{shot.Image.Height}，期望 300×200");
        Check("截图：画布尺寸按 DPI 折算",
              Math.Abs((shot.Transform.M11 * shot.Image.Width) - 300f / dpi) < 3f,
              $"画布宽 {(shot.Transform.M11 * shot.Image.Width):F0}，期望 {300f / dpi:F0}（dpi={dpi:F2}）");

        var vp = ViewportCanvas;
        float margin = CaptureMarginLogical * dpi;
        Check("截图：落在视口左上角（带一点边距）",
              Math.Abs(shot.WorldBounds.MinX - (vp.MinX + margin)) < 3f
              && Math.Abs(shot.WorldBounds.MinY - (vp.MinY + margin)) < 3f,
              $"({shot.WorldBounds.MinX:F0},{shot.WorldBounds.MinY:F0})，期望 ({vp.MinX + margin:F0},{vp.MinY + margin:F0})");
        Check("截图：自动选中、并切回框选工具",
              Doc.Selected.Count == 1 && ReferenceEquals(Doc.Selected[0], shot) && Tool == Tool.Marquee,
              $"选中 {Doc.Selected.Count} 个，工具 {Tool}");

        // 核心一条：抓到的图里不该有自己的墨
        int shotInk = 0;
        var px = shot.Image.Bgra;
        for (int i = 0; i + 3 < px.Length; i += 4)
            if (px[i + 2] > 200 && px[i + 1] < 90 && px[i] > 200) shotInk++;
        Check("截图：自己的批注没被拍进去（品红≈0）", shotInk < 200, $"{shotInk} 像素");

        // 剪贴板：截图必须同时进剪贴板
        if (ClipboardImage.TryGetImage(out var clip, out int cw, out int ch, out _))
        Check("截图：同时进了剪贴板", cw == shot.Image.Width && ch == shot.Image.Height, $"{cw}×{ch}");
        else
            Console.WriteLine("    剪贴板：读不出来（可能被别的程序占着）——这项跳过");

        Check("拖动中显示了尺寸读数（框下面那块有深色胶囊）", midReadoutDark > 800,
              $"{midReadoutDark} 像素（读数是 {300 / dpi:F0}×{200 / dpi:F0} 的一个深色胶囊）");

        // 覆盖层藏过又显示：屏幕上不该留残影（墨应该还在原处）
        int afterInk = ScreenProbe.CountMagenta((int)(cx - 200), (int)(cy - 120), 400, 260);
        Check("截图后屏幕恢复正常（批注还在，没有残影）", afterInk > 5000,
              $"截前 {onScreenInk} 像素，截后 {afterInk} 像素");

        // ---- ② 第二种模式：**直接截取**（连板书一起拍）----
        //
        // 用户 2026-09-17："截图功能是不是也应该对接了，也可以参考 inkclass"。
        // InkClass 给的是两项菜单（快速截图 / 隐藏界面截图），我们把这两项放进
        // **截图那一格的上带**：[直接截取][隐藏批注截取]（照我们假面板里定的那两段）。
        Host.Commands.SetCaptureHideInk(false);
        SettleFrames(250);
        Check("模式切到「直接截取」", !Host.State.CaptureHideInk,
              $"hideInk = {Host.State.CaptureHideInk}");

        DragCapture();
        var shot2 = Doc.Strokes.FindLast(s => s.IsImage);
        Check("直接截取：又生成了一个图像对象", shot2 != null && !ReferenceEquals(shot2, shot),
              shot2 == null ? "没有" : $"{shot2.Image.Width}×{shot2.Image.Height}");
        if (shot2 != null)
        {
            var q = shot2.Image.Bgra;
            int ink2 = 0, frame = 0;
            for (int y = 0; y < shot2.Image.Height; y++)
                for (int x = 0; x < shot2.Image.Width; x++)
                {
                    int i = (y * shot2.Image.Width + x) * 4;
                    byte b = q[i], g = q[i + 1], r = q[i + 2];
                    if (r > 200 && g < 90 && b > 200) ink2++;                       // 品红 = 板书
                    // 取景框是琥珀色（1, 0.68, 0.10）：只查图片最外 3 像素那一圈——
                    // 框就画在抓取矩形的边上，真被拍进去必然落在这里
                    if ((x < 3 || y < 3 || x >= shot2.Image.Width - 3 || y >= shot2.Image.Height - 3)
                        && r > 200 && g > 140 && g < 215 && b < 90) frame++;
                }
            Check("直接截取：**板书在图里**（品红 > 2000）", ink2 > 2000, $"{ink2} 像素");
            Check("直接截取：取景框没被拍进去（最外一圈没有琥珀色）", frame == 0, $"{frame} 像素");
        }

        // 收尾：模式还原成默认的"隐藏批注截取"
        Host.Commands.SetCaptureHideInk(true);
        SettleFrames(150);
        Check("收尾：模式还原成「隐藏批注截取」", Host.State.CaptureHideInk,
              $"hideInk = {Host.State.CaptureHideInk}");

        Console.WriteLine();
        Console.WriteLine(fail == 0 ? $"  PASS: 截图全通（{pass} 项）" : $"  FAIL: {fail} 项不对");
        _quit = true;
    }

    private void InputPathTest()
    {
        Console.WriteLine();
        Console.WriteLine("=== 输入路径测试（会自动移动鼠标画一笔）===");

        float cx = _virtualX + _virtualW * 0.5f;
        float cy = _virtualY + _virtualH * 0.4f;
        int before = Doc.Strokes.Count;

        if (SkipIfNoSyntheticInput("输入路径自检")) { _quit = true; return; }

        SendMouse((int)(cx - 400), (int)cy, 0);
        SettleFrames(120);
        SendMouse((int)(cx - 400), (int)cy, Native.MOUSEEVENTF_LEFTDOWN);
        SettleFrames(60);

        const int steps = 60;
        for (int i = 1; i <= steps; i++)
        {
            float px = cx - 400 + i * 13f;
            float py = cy + MathF.Sin(i * 0.18f) * 70f;
            SendMouse((int)px, (int)py, 0);
            SettleFrames(8);
        }

        SendMouse((int)(cx - 400 + steps * 13f), (int)(cy + MathF.Sin(steps * 0.18f) * 70f),
                  Native.MOUSEEVENTF_LEFTUP);
        SettleFrames(300);

        Console.WriteLine("  笔画报告: " + (_lastStrokeReport ?? "（没有笔画被提交）"));
        Console.WriteLine($"  文档笔画数: {before} -> {Doc.Strokes.Count}");

        bool gotStroke = Doc.Strokes.Count > before;
        int points = gotStroke ? Doc.Strokes[^1].Points.Count : 0;
        Console.WriteLine($"  采集点数: {points}");

        // A dot would only paint a small blob where the press happened. Sample
        // along the whole path: every sample must have ink, not just the start.
        Console.WriteLine("  沿路径采样（屏幕上的红色像素数）：");
        int hits = 0;
        for (int s = 0; s <= 6; s++)
        {
            int i = s * steps / 6;
            float px = cx - 400 + i * 13f;
            float py = cy + MathF.Sin(i * 0.18f) * 70f;
            int n = ScreenProbe.CountRed((int)(px - 40), (int)(py - 40), 80, 80);
            Console.WriteLine($"    第{i,3}步 ({px,6:F0},{py,6:F0}) : {n,5} 像素");
            if (n > 30) hits++;
        }
        int whole = ScreenProbe.CountRed((int)(cx - 430), (int)(cy - 130), 860, 260);
        Console.WriteLine($"  整条路径范围内红色像素合计: {whole}");

        if (gotStroke && Doc.Strokes[^1].Points.Count > 1)
        {
            var st = Doc.Strokes[^1];
            float sum = 0;
            for (int k = 1; k < st.Points.Count; k++)
                sum += Vector2.Distance(
                    new Vector2(st.Points[k - 1].X, st.Points[k - 1].Y),
                    new Vector2(st.Points[k].X, st.Points[k].Y));
            float avg = sum / (st.Points.Count - 1);
            Console.WriteLine($"  轮廓平滑度: 折线拐点平均间距 {avg:F1} 物理像素"
                              + $"（拟合后按 1.6 像素重采样，所以实际轮廓精度是 1.6）");
        }

        bool ok = points > 10 && hits == 7;
        Console.WriteLine(ok
            ? "  PASS: 路径上处处有墨，画出来的是线不是点"
            : $"  FAIL: 路径上有 {7 - hits} 处没有墨");
        _quit = true;
    }

    // =====================================================================
    //  延时实测：笔尖动 → 像素亮
    // =====================================================================
    //
    // 为什么要一个专门的模式：性能面板上的"输入到上屏"是一个 EMA，看得见趋势
    // 但看不到分布，也分不清是哪一段慢。延时是**分布**问题——平均值好看、
    // 偶尔一帧慢，手感就是"偶尔一顿"。所以这里采每条样本的四个分段，出分位数。
    //
    // 各段归属（哪一段该由谁负责）见 Latency.cs 的注释。

    /// <summary>
    /// 起一个后台线程按**固定频率**喂合成指针输入。
    ///
    /// 必须独立成线程：如果在主线程上"发一个点、渲染一帧、再发一个点"，
    /// 输入节奏就被渲染节奏绑死了，量到的是自己设计的模式，而不是真实的排队
    /// 行为。真笔是按自己的采样率一直发，应用爱怎么画怎么画——只有把两者分开，
    /// 才能量到"Present 阻塞期间输入排了多久的队"。
    /// </summary>
    private Thread StartInjector(float x0, float y0, float x1, float y1, double hz, double ms)
    {
        var th = new Thread(() =>
        {
            SendMouse((int)x0, (int)y0, 0);
            Thread.Sleep(80);
            SendMouse((int)x0, (int)y0, Native.MOUSEEVENTF_LEFTDOWN);
            var sw = Stopwatch.StartNew();
            double period = 1000.0 / hz;
            int i = 1;
            while (true)
            {
                double target = i * period;
                if (target > ms) break;
                // 睡到接近、再自旋到点：Sleep 的抖动是 1~15ms，直接用来配速
                // 会让"注入时刻"本身变得比被测量的延时还抖。
                while (true)
                {
                    double remain = target - sw.Elapsed.TotalMilliseconds;
                    if (remain <= 0) break;
                    if (remain > 2) Thread.Sleep((int)(remain - 1));
                    else Thread.SpinWait(200);
                }
                float u = (float)(target / ms);
                float px = x0 + (x1 - x0) * u;
                float py = y0 + (y1 - y0) * u + MathF.Sin(u * 9f) * 70f;
                SendMouse((int)px, (int)py, 0);
                i++;
            }
            SendMouse((int)x1, (int)y1, Native.MOUSEEVENTF_LEFTUP);
        })
        { IsBackground = true };
        th.Start();
        return th;
    }

    /// <summary>
    /// 边抽消息边渲染，直到注入线程收笔。
    ///
    /// **顺序必须和主循环 Loop() 完全一致**：先抽、等到合成边界（配速模式）、
    /// 再抽一次、然后画。第一版把 DwmFlush 放在抽消息之后，量出来的
    /// "收到 → 调 Present" 是 16.2ms——那不是渲染慢，那是测量循环自己排的队。
    /// 测量代码和被测代码的时序不一致，量出来的就是测量方法的问题。
    /// </summary>
    private void PumpUntilDone(Thread injector)
    {
        while (injector.IsAlive)
        {
            DrainMessages();
            if (_dirty || _drawing)
            {
                if (OverlayWindow.VBlankPaced) { Native.DwmFlush(); DrainMessages(); }
                RenderAll();
                _dirty = false;
            }
            else Native.MsgWaitForMultipleObjectsEx(0, IntPtr.Zero, 50, Native.QS_ALLINPUT, 0);
        }
        DrainMessages();
        RenderAll();
    }

    private string PresentModeName()
    {
        if (OverlayWindow.VBlankPaced) return "合成边界配速 + Present(0)";
        if (OverlayWindow.LatencyWaitEnabled) return "帧延迟等待对象 + Present(0)（不限速）";
        return "Present(1) 阻塞在垂直同步";
    }

    /// <summary>把一个场景跑完：清空采样 → 注入 → 收数据 → 打印 + 落 CSV。</summary>
    private void RunLatencyScenario(string tag, string csvPath, string note,
                                    float x0, float y0, float x1, float y1, double hz, double ms)
    {
        Console.WriteLine();
        Console.WriteLine($"--- 场景 {tag}：{note}");
        Console.WriteLine($"    注入 {hz:F0} Hz，{ms / 1000.0:F1} 秒，路径 ({x0:F0},{y0:F0}) → ({x1:F0},{y1:F0})");

        Latency.Scenario = tag;
        Latency.Clear();
        ResetLatencyProbe();
        LatencyRecording = true;

        long frames0 = FrameCounter;
        double wall0 = _clock.Elapsed.TotalMilliseconds;
        var th = StartInjector(x0, y0, x1, y1, hz, ms);
        PumpUntilDone(th);
        double wall = _clock.Elapsed.TotalMilliseconds - wall0;
        long frames = FrameCounter - frames0;

        LatencyRecording = false;
        Console.WriteLine($"    采到 {Latency.Count} 条样本，渲染 {frames} 帧 / {wall / 1000.0:F1} 秒"
                          + $" = {frames * 1000.0 / wall:F1} fps（笔画数 {Doc.Strokes.Count}）");
        Console.Write(Latency.Report());
        Latency.WriteCsv(csvPath, tag);
    }

    /// <summary>把页面写满，用来量"同一页墨迹很多时"的延时。</summary>
    private void FillDensePage(int strokes, float cx, float cy)
    {
        Doc.Clear();
        var rnd = new Random(7);
        for (int i = 0; i < strokes; i++)
        {
            var s = new Stroke
            {
                Tool = Tool.Pen,
                Color = new Color4(0.2f, 0.3f, 0.9f, 1f),
                Width = 3f * DpiScale,
            };
            float bx = cx - 420 + (float)rnd.NextDouble() * 840;
            float by = cy - 260 + (float)rnd.NextDouble() * 520;
            for (int k = 0; k <= 14; k++)
                s.AddPoint(bx + k * 3.5f, by + MathF.Sin(k * 0.7f) * 5f, 0.6f, NowMs);
            Doc.AddStroke(s);
        }
        Doc.InvalidateAll();
        SettleFrames(700);
    }

    /// <summary>
    /// 测"Present 返回 → 屏幕真的变色"这一段——DWM 合成 + 扫描输出 + 面板。
    ///
    /// 为什么必须盯着屏幕看：进程内的 API 拿不到这一段的准确时刻。前面四段
    /// 我们都能自己打时标，唯独"像素什么时候亮"只有屏幕自己知道。
    ///
    /// 做法：白板底色按 8 帧一个周期黑白交替（4 帧白、4 帧黑），后台线程用 GDI
    /// 一直读屏幕上固定的一个点，记下每次变色的时刻；主线程每帧记下
    /// (Present 返回时刻, 这一帧的颜色)。周期 8 帧 ≈133ms，远大于任何可能的
    /// 管线延时，所以每次变色都能唯一对上"是哪一帧先变的"。
    /// delta = 变色时刻 − 那一帧 Present 返回的时刻。
    ///
    /// 这个尺子自身的偏差要说清楚：GDI 抓的是 DWM 合成后的桌面，读取本身也可能
    /// 按垂直同步对齐，所以绝对值可能整体偏大几毫秒。**两种呈现方式用同一把
    /// 尺子量出来的差值（差几个刷新周期）才是这条数据真正的价值。**
    /// </summary>
    private void RunPhotonProbe(string csvPath, int cycles)
    {
        Console.WriteLine();
        Console.WriteLine("--- 场景 photon：Present 返回 → 屏幕真的变色（DWM 合成 + 扫描输出）");
        Console.WriteLine("    白板按 8 帧黑白交替，另起一个线程盯着屏幕上一个点看什么时候变");

        Doc.Clear();
        BoardOn = true;
        _dirty = true;
        RenderAll();
        _dirty = false;

        int probeX = _virtualX + 40, probeY = _virtualY + 40;
        var flips = new List<(ulong qpc, int color)>();
        bool stop = false;

        var th = new Thread(() =>
        {
            IntPtr screenDc = Native.GetDC(IntPtr.Zero);
            IntPtr memDc = Native.CreateCompatibleDC(screenDc);
            var bi = new Native.BITMAPINFO
            {
                bmiHeader = new Native.BITMAPINFOHEADER
                {
                    biSize = Marshal.SizeOf<Native.BITMAPINFOHEADER>(),
                    biWidth = 1, biHeight = -1, biPlanes = 1, biBitCount = 32,
                    biCompression = (int)Native.BI_RGB,
                }
            };
            IntPtr dib = Native.CreateDIBSection(memDc, ref bi, Native.DIB_RGB_COLORS,
                                                 out IntPtr bits, IntPtr.Zero, 0);
            IntPtr old = Native.SelectObject(memDc, dib);
            int last = -1;
            while (!stop)
            {
                Native.BitBlt(memDc, 0, 0, 1, 1, screenDc, probeX, probeY, Native.SRCCOPY);
                int c = Marshal.ReadByte(bits, 0) > 128 ? 1 : 0;   // B 通道
                if (last >= 0 && c != last) flips.Add((Qpc.Now, c));
                last = c;
                Thread.SpinWait(150);
            }
            Native.SelectObject(memDc, old);
            Native.DeleteObject(dib);
            Native.DeleteDC(memDc);
            Native.ReleaseDC(IntPtr.Zero, screenDc);
        })
        { IsBackground = true };
        th.Start();
        Thread.Sleep(200);

        var frames = new List<(ulong qpc, int color)>();
        int total = cycles * 8;
        for (int i = 0; i < total; i++)
        {
            int color = (i / 4) % 2 == 0 ? 1 : 0;      // 1 = 白，0 = 黑
            BoardColor = color == 1 ? new Color4(1f, 1f, 1f, 1f) : new Color4(0f, 0f, 0f, 1f);
            _dirty = true;
            if (OverlayWindow.VBlankPaced) { Native.DwmFlush(); DrainMessages(); }
            RenderAll();
            _dirty = false;
            frames.Add((_windows[0].LastPresentEndQpc, color));
        }

        stop = true;
        th.Join(2000);
        BoardOn = false;
        BoardColor = new Color4(0.99f, 0.99f, 0.98f, 1f);
        _dirty = true;
        RenderAll();
        _dirty = false;

        // 把每次变色对上"这一段的头一帧"。同一颜色的帧是连续 4 帧一段，
        // 屏幕上变色对应的是这一段的第 1 帧上屏。
        var deltas = new List<double>();
        int searchFrom = 0;
        foreach (var (qpc, color) in flips)
        {
            int match = -1;
            for (int k = searchFrom; k < frames.Count; k++)
            {
                if (frames[k].color != color) continue;
                if (k > 0 && frames[k - 1].color == color) continue;   // 只要段首
                if (frames[k].qpc <= qpc) { match = k; searchFrom = k + 1; }
                else break;
            }
            if (match < 0) continue;
            deltas.Add(Qpc.Ms(frames[match].qpc, qpc));
        }

        double refresh = _windows[0].RefreshPeriodMs;
        if (deltas.Count == 0)
        {
            Console.WriteLine("    没对上（屏幕抓取可能被别的窗口挡住，或抓取本身失败）");
            return;
        }
        var d = new Dist(deltas);
        Console.WriteLine($"    抓到 {deltas.Count} 次变色，本机交换链报告的刷新周期 {refresh:F2} ms");
        Console.WriteLine($"    Present 返回 → 屏幕变色：{d}");
        Console.WriteLine($"    折合 {(d.Mean / refresh):F2} 个刷新周期（均值）、"
                          + $"{(d.P50 / refresh):F2} 个（中位）");
        _photonDeltaMs = d.Mean;
        _photonDeltaFrames = d.Mean / refresh;
    }

    /// <summary>上机测得的上屏段（毫秒 / 刷新周期数），给报告拼"端到端"用。</summary>
    private double _photonDeltaMs;
    private double _photonDeltaFrames;

    private void LatencyBench(string csvPath)
    {
        Console.WriteLine();
        Console.WriteLine("=== 延时实测（笔尖动 → 像素亮）===");
        Console.WriteLine($"  呈现方式      ：{PresentModeName()}");
        Console.WriteLine($"  交换链后缓冲  ：{OverlayWindow.BufferCount}");
        Console.WriteLine($"  性能面板 HUD  ：{(ShowHud ? "开" : "关")}");
        Console.WriteLine($"  委托墨迹轨迹  ：{OverlayWindow.InkTrailNote}"
                          + (OverlayWindow.InkTrailEnabled ? "，已启用" : "，未启用"));
        Console.WriteLine($"  说明          ：注入的是合成鼠标，走的是和真笔同一条 WM_POINTER 路径；"
                          + "“输入 → 收到消息”那一段在合成输入上可能不可得（报告里会标）。");

        float cx = _virtualX + _virtualW * 0.5f;
        float cy = _virtualY + _virtualH * 0.45f;

        // 1) 空白页，正常书写速度。
        Doc.Clear();
        Doc.InvalidateAll();
        SettleFrames(300);
        RunLatencyScenario("empty-slow", csvPath, "空白页，正常书写速度",
            cx - 380, cy, cx + 380, cy, 140, 3000);

        // 2) 空白页，快速划线。点的间距大、单位时间覆盖面积大，
        //    量的是"同样一帧要光栅化的墨更多"时的表现。
        Doc.Clear();
        Doc.InvalidateAll();
        SettleFrames(300);
        RunLatencyScenario("empty-fast", csvPath, "空白页，快速划线",
            cx - 600, cy, cx + 600, cy, 200, 2500);

        // 3) 密集页：同一小块里已经有 3000 笔。
        FillDensePage(3000, cx, cy);
        RunLatencyScenario("dense", csvPath, "密集页（同区域已有 3000 笔）",
            cx - 380, cy, cx + 380, cy, 140, 3000);

        // 4) 长跑：连续写 12 秒，专门看"越写越慢"和抖动分布。
        Doc.Clear();
        Doc.InvalidateAll();
        SettleFrames(300);
        RunLatencyScenario("long-12s", csvPath, "连续书写 12 秒（稳定性）",
            cx - 380, cy, cx + 380, cy, 140, 12000);

        // 5) 上屏段：唯一必须"看屏幕"才知道的一段。
        RunPhotonProbe(csvPath, 20);
        if (_photonDeltaMs > 0)
        {
            Console.WriteLine();
            Console.WriteLine($"  端到端估计（最新一笔 → 像素亮）：");
            Console.WriteLine($"    阻塞式 : 16.5（到 Present 返回）+ {_photonDeltaMs:F1}（上屏）"
                              + $" ≈ {16.5 + _photonDeltaMs:F0} ms");
        }

        Console.WriteLine();
        Console.WriteLine($"CSV 已写入 {csvPath}");
        _quit = true;
    }

    /// <summary>
    /// 真笔实测：把探针挂上，请用户用手写笔在屏幕上写，结束后出报告。
    ///
    /// 这个模式同时回答一个关键问题：**手写板到底是以"笔"报进来的，还是以
    /// "鼠标"报进来的**。前者能拿到硬件时标和压感，后者连"笔尖什么时候动"
    /// 都只能靠轮询猜——很多手写板的"迟滞感"就出在这里，跟应用代码无关。
    /// </summary>
    private void LatencyLive(double seconds)
    {
        Console.WriteLine();
        Console.WriteLine("=== 真笔延时实测 ===");
        Console.WriteLine($"  呈现方式：{PresentModeName()}，交换链后缓冲 {OverlayWindow.BufferCount}");
        Console.WriteLine($"  请用手写笔画线，持续 {seconds:F0} 秒（或按 Ctrl+Alt+X 提前结束）……");
        Console.WriteLine();

        Latency.Scenario = "真笔手写";
        Latency.Clear();
        ResetLatencyProbe();
        LatencyRecording = true;

        var seen = new Dictionary<uint, int>();
        double t0 = NowMs;
        double nextTick = t0 + 2000;
        while (!_quit && NowMs - t0 < seconds * 1000)
        {
            DrainMessages();
            seen[LastPointerType] = seen.GetValueOrDefault(LastPointerType) + 1;
            if (_dirty || _drawing)
            {
                if (OverlayWindow.VBlankPaced) { Native.DwmFlush(); DrainMessages(); }
                RenderAll();
                _dirty = false;
            }
            else Native.MsgWaitForMultipleObjectsEx(0, IntPtr.Zero, 50, Native.QS_ALLINPUT, 0);
            NowMs = _clock.Elapsed.TotalMilliseconds;

            if (NowMs >= nextTick)
            {
                nextTick = NowMs + 2000;
                Console.WriteLine($"  [{NowMs / 1000:F0}s] 已采 {Latency.Count} 帧，"
                                  + $"当前设备 {DeviceName(LastPointerType)}，"
                                  + $"笔画 {Doc.Strokes.Count}");
            }
        }

        LatencyRecording = false;
        Console.WriteLine();
        Console.WriteLine("设备使用统计（每帧采到的最新型号）："
                          + string.Join("，", seen.OrderByDescending(kv => kv.Value)
                                                  .Select(kv => $"{DeviceName(kv.Key)} {kv.Value} 帧")));
        Console.WriteLine("  笔 = PT_PEN 才是真笔通道（有压感、有硬件时标）；"
                          + "鼠标 = 手写板工作在兼容模式，单这一项就够造成迟滞感。");

        // 真笔的"数据质量"汇总：这次要不要相信压感、合并点收全了没有、
        // 以及预测在什么档位（这些在 调研-压感与预测-原理.md 与 测试-压感与预测.md 里都有判据）。
        Console.WriteLine();
        Console.WriteLine("=== 真笔数据质量汇总 ===");
        Console.WriteLine($"  合并点：{PenMessages} 条消息 → {PenSamples} 个采样点"
                          + (PenMessages > 0 ? $"（每条 {PenSamples / (double)PenMessages:F2} 个）" : ""));
        // 非笔指针（鼠标 / 触摸）也报一份：手写板没开 Windows Ink、以及触摸屏，
        // 走的就是这条路——"合并率"这一项以前只有笔有数，现在两边都有。
        if (PtrMessages > 0)
            Console.WriteLine($"  非笔指针（鼠标/触摸）：{PtrMessages} 条消息 → {PtrSamples} 个采样点"
                              + $"（每条 {PtrSamples / (double)PtrMessages:F2} 个）"
                              + $"，收下 {PtrTotalPoints} 个点");
        Console.WriteLine($"  压感：{PenPressurePoints}/{PenTotalPoints} 个点带有效压感；"
                          + $"设备报 pressure 位={Yes(PenSawPressureMask)}，"
                          + $"倾角位={Yes(PenSawTiltMask)}，旋转位={Yes(PenSawRotationMask)}");
        Console.WriteLine($"  预测：{(PredictEnabled ? $"开（{PredictHorizonMs:F0} ms）" : "关")}；"
                          + $"湿墨轨迹：{(OverlayWindow.InkTrailEnabled ? "开" : "关")}"
                          + $"（{OverlayWindow.InkTrailNote}）");
        if (PredictEnabled)
            Console.WriteLine("  预测尾：鼠标/触摸那条路开着——正在写的那一笔末端会比真实采样点"
                              + $"超前一点（上限 {PredictLeadCap:F0} px）；嫌超前就 --predictlead 调小");
        if (PredLeadCount > 0)
            Console.WriteLine($"  预测实际把墨往前带：平均 {PredLeadSum / PredLeadCount:F2} px，"
                              + $"最大 {PredLeadMax:F2} px（上限 {PredictLeadCap:F0} px，共 {PredLeadCount} 次）");
        else if (PredictEnabled)
            Console.WriteLine("  预测实际把墨往前带：一次都没有触发（速度太低或全是急转/断笔）");

        // 书写期间的分配与 GC：低配机排查"偶发卡顿"的依据。
        // 每笔分配越大越容易触发回收；**第 2 代回收出现在书写期间 = 那一下就卡了几十毫秒**。
        if (StrokesMeasured > 0)
            Console.WriteLine($"  书写期间：{StrokesMeasured} 笔，每笔分配 平均 {AllocKbSum / StrokesMeasured:F1} KB"
                              + $" / 最大 {AllocBytesMax / 1024.0:F1} KB；"
                              + (StrokesWithGc2 == 0
                                  ? "第 2 代 GC 一次都没出现在书写期间（好）"
                                  : $"⚠ 第 2 代 GC 出现在 {StrokesWithGc2} 笔里（低配机上就是可见卡顿，要查）"));
        Console.WriteLine($"  GC 低延迟档：{GcLatency.Describe()}");

        Console.WriteLine(PenTotalPoints == 0
            ? "  注意：这一轮一个真笔采样点都没有——写的时候用的是鼠标/触摸，或者笔工作在兼容模式"
            : PenSawPressureMask
                ? "  压感可用：这台机器/这支笔确实在报压力"
                : "  压感不可用：设备没报 pressure 位（先查驱动的 Windows Ink 开关）");

        Console.Write(Latency.Report());
        string csv = "reports/latency-live.csv";
        Latency.WriteCsv(csv, "real-pen");
        Console.WriteLine($"CSV 已写入 {csv}");
        _quit = true;
    }

    /// <summary>汇总行里用的小写法。</summary>
    private static string Yes(bool v) => v ? "有" : "无";

    private static string DeviceName(uint t) => t switch
    {
        Native.PT_PEN => "笔",
        Native.PT_TOUCH => "触摸",
        Native.PT_MOUSE => "鼠标",
        _ => $"未知({t})",
    };

    /// <summary>
    /// Draws one long stroke, checks it is on screen, erases its middle, then
    /// checks the middle went away and the ends survived. Correctness of the
    /// region patch is not something you can eyeball from inside the process.
    /// </summary>
    private void EraseCheck(out bool correct, out string detail)
    {
        float cx = _virtualX + _virtualW * 0.5f;
        float cy = _virtualY + _virtualH * 0.5f;

        // Magenta horizontal stroke, wiped at its left third.
        var target = new Stroke { Tool = Tool.Pen, Color = new Color4(1f, 0f, 1f, 1f), Width = 16f };
        for (int i = 0; i <= 80; i++)
        {
            float t = i / 80f;
            target.AddPoint(cx - 400 + t * 800, cy, 0.9f, NowMs);
        }

        // Green vertical stroke crossing the magenta one, far from the erase
        // point. It must survive untouched *including* where it passes through
        // the rectangle that gets cleared and re-rasterised.
        float vx = cx + 200;
        var bystander = new Stroke { Tool = Tool.Pen, Color = new Color4(0f, 1f, 0f, 1f), Width = 16f };
        for (int i = 0; i <= 60; i++)
        {
            float t = i / 60f;
            bystander.AddPoint(vx, cy - 300 + t * 600, 0.9f, NowMs);
        }

        Doc.Clear();
        Doc.AddStroke(target);
        Doc.AddStroke(bystander);
        Doc.InvalidateAll();
        SettleFrames(500);

        int targetBefore = ScreenProbe.CountMagenta((int)(cx - 360), (int)(cy - 30), 120, 60);
        int bystanderBefore = ScreenProbe.CountGreen((int)(vx - 30), (int)(cy - 30), 60, 60);

        int removed = Doc.EraseAt(cx - 300, cy, 30f);
        SettleFrames(500);

        int targetAfter = ScreenProbe.CountMagenta((int)(cx - 360), (int)(cy - 30), 120, 60);
        // Sample the bystander *inside* the patched band, not above it.
        int bystanderAfter = ScreenProbe.CountGreen((int)(vx - 30), (int)(cy - 30), 60, 60);

        correct = targetBefore > 200 && targetAfter < 40 && removed == 1
                  && bystanderBefore > 200 && bystanderAfter > bystanderBefore * 0.8;
        detail = $"被擦笔画 {targetBefore}→{targetAfter} 像素（应归零），"
               + $"同区域另一笔 {bystanderBefore}→{bystanderAfter} 像素（应保留），删除 {removed} 笔";
    }

    // =====================================================================
    //  Teardown
    // =====================================================================

}

internal static class ScreenProbe
{
    /// <summary>Grabs the whole virtual desktop into a 32-bit BMP. Used for
    /// eyeballing what another app actually looks like while it is measured.</summary>
    public static bool SaveBmp(string path, int x, int y, int w, int h)
    {
        IntPtr screenDc = Native.GetDC(IntPtr.Zero);
        IntPtr memDc = Native.CreateCompatibleDC(screenDc);

        var bi = new Native.BITMAPINFO
        {
            bmiHeader = new Native.BITMAPINFOHEADER
            {
                biSize = Marshal.SizeOf<Native.BITMAPINFOHEADER>(),
                biWidth = w,
                biHeight = -h,
                biPlanes = 1,
                biBitCount = 32,
                biCompression = (int)Native.BI_RGB,
            }
        };

        IntPtr bits = IntPtr.Zero;
        IntPtr dib = Native.CreateDIBSection(memDc, ref bi, Native.DIB_RGB_COLORS, out bits, IntPtr.Zero, 0);
        if (dib == IntPtr.Zero || bits == IntPtr.Zero)
        {
            Native.DeleteDC(memDc);
            Native.ReleaseDC(IntPtr.Zero, screenDc);
            return false;
        }

        IntPtr old = Native.SelectObject(memDc, dib);
        Native.BitBlt(memDc, 0, 0, w, h, screenDc, x, y, Native.SRCCOPY);

        var pixels = new byte[w * h * 4];
        Marshal.Copy(bits, pixels, 0, pixels.Length);

        Native.SelectObject(memDc, old);
        Native.DeleteObject(dib);
        Native.DeleteDC(memDc);
        Native.ReleaseDC(IntPtr.Zero, screenDc);
        return WriteBmp(path, pixels, w, h);
    }

    /// <summary>把 BGRA 像素写成 32 位 BMP 文件。</summary>
    private static bool WriteBmp(string path, byte[] pixels, int w, int h)
    {
        try
        {
            var dir = System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath(path));
            if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);

            int imageBytes = w * h * 4;
            using var fs = File.Create(path);
            using var bw = new BinaryWriter(fs);

            // BITMAPFILEHEADER
            bw.Write((ushort)0x4D42);          // 'BM'
            bw.Write(14 + 40 + imageBytes);    // 文件大小
            bw.Write(0);
            bw.Write(14 + 40);                 // 像素数据偏移

            // BITMAPINFOHEADER
            bw.Write(40);
            bw.Write(w);
            bw.Write(h);
            bw.Write((ushort)1);
            bw.Write((ushort)32);
            bw.Write(0);                       // BI_RGB
            bw.Write(imageBytes);
            bw.Write(2835);                    // 分辨率
            bw.Write(2835);
            bw.Write(0);
            bw.Write(0);

            // BMP 是自下而上存储的，抓到的像素是自上而下的，逐行倒序写。
            for (int row = h - 1; row >= 0; row--)
                bw.Write(pixels, row * w * 4, w * 4);
            return true;
        }
        catch
        {
            return false;
        }
    }

    public static int CountNear(int x, int y, int w, int h, int r, int g, int b, int tol)
    {
        var box = new Box(r, g, b, tol);
        return Capture(x, y, w, h, (bb, gg, rr) =>
            Math.Abs(rr - box.R) <= box.Tol
            && Math.Abs(gg - box.G) <= box.Tol
            && Math.Abs(bb - box.B) <= box.Tol);
    }

    private readonly struct Box
    {
        public readonly int R, G, B, Tol;
        public Box(int r, int g, int b, int tol) { R = r; G = g; B = b; Tol = tol; }
    }

    public static int CountMagenta(int x, int y, int w, int h) => Capture(x, y, w, h, IsMagenta);
    public static int CountGreen(int x, int y, int w, int h) => Capture(x, y, w, h, IsGreen);
    public static int CountRed(int x, int y, int w, int h) => Capture(x, y, w, h, IsRed);
    public static int CountCursor(int x, int y, int w, int h) => Capture(x, y, w, h, IsCursor);

    /// <summary>深色像素数（找"深色胶囊"那种东西：截图时的尺寸读数）。</summary>
    public static int CountDark(int x, int y, int w, int h) => Capture(x, y, w, h, IsDark);
    private static bool IsDark(byte b, byte g, byte r) => r < 90 && g < 90 && b < 90;

    // 判定用色。像素是 BGRA 顺序，所以参数名按 (b, g, r)。
    private static bool IsMagenta(byte b, byte g, byte r) => b > 200 && g < 90 && r > 200;
    private static bool IsGreen(byte b, byte g, byte r) => g > 180 && r < 90 && b < 90;
    private static bool IsRed(byte b, byte g, byte r) => r > 170 && g < 110 && b < 110;
    private static bool IsCursor(byte b, byte g, byte r)
        => r > 180 && g > 70 && g < 190 && b > 70 && b < 190;

    /// <summary>抓一块区域的原始 BGRA 像素，用于前后差分。</summary>
    public static byte[] CaptureRegion(int x, int y, int w, int h)
    {
        if (w <= 0 || h <= 0) return Array.Empty<byte>();
        var buf = new byte[w * h * 4];
        return CaptureRegionInto(buf, x, y, w, h) ? buf : Array.Empty<byte>();
    }

    /// <summary>把一份 BGRA 缓冲原样写成 32 位 BMP（**不经屏幕**：抓过的那一帧要能留档）。</summary>
    public static bool SaveBuffer(string path, byte[] bgra, int w, int h) => WriteBmp(path, bgra, w, h);

    /// <summary>同 <see cref="CaptureRegion"/>，但把像素写进调用方给的缓冲。**逐帧抓屏的测量必须用它**：
    /// 每帧 new 一个 1400×360×4 ≈ 2MB 的数组会直接进 LOH，实测能把**一次笔画**刷出
    /// 64 次第 2 代 GC / 378 MB 分配——那量到的是测量工具自己，不是产品。
    /// （2026-09-28 拿 `--wetdrytest` 踩的，记在这里免得再犯。）
    /// </summary>
    public static bool CaptureRegionInto(byte[] dst, int x, int y, int w, int h)
    {
        if (dst == null || w <= 0 || h <= 0 || dst.Length < w * h * 4) return false;
        IntPtr screenDc = Native.GetDC(IntPtr.Zero);
        IntPtr memDc = Native.CreateCompatibleDC(screenDc);
        IntPtr bits = IntPtr.Zero;

        var bi = new Native.BITMAPINFO
        {
            bmiHeader = new Native.BITMAPINFOHEADER
            {
                biSize = Marshal.SizeOf<Native.BITMAPINFOHEADER>(),
                biWidth = w,
                biHeight = -h,
                biPlanes = 1,
                biBitCount = 32,
                biCompression = (int)Native.BI_RGB,
            }
        };

        IntPtr dib = Native.CreateDIBSection(memDc, ref bi, Native.DIB_RGB_COLORS, out bits, IntPtr.Zero, 0);
        if (dib == IntPtr.Zero || bits == IntPtr.Zero)
        {
            Native.DeleteDC(memDc);
            Native.ReleaseDC(IntPtr.Zero, screenDc);
            return false;
        }

        IntPtr old = Native.SelectObject(memDc, dib);
        Native.BitBlt(memDc, 0, 0, w, h, screenDc, x, y, Native.SRCCOPY);
        Marshal.Copy(bits, dst, 0, w * h * 4);

        Native.SelectObject(memDc, old);
        Native.DeleteObject(dib);
        Native.DeleteDC(memDc);
        Native.ReleaseDC(IntPtr.Zero, screenDc);
        return true;
    }

    /// <summary>两张同尺寸截图的逐像素差异数（容忍轻微抗锯齿抖动）。</summary>
    public static int DiffCount(byte[] a, byte[] b, int tolerance = 12)
    {
        if (a == null || b == null || a.Length != b.Length) return int.MaxValue;
        int n = 0;
        for (int i = 0; i < a.Length; i += 4)
        {
            int dr = Math.Abs(a[i] - b[i]);
            int dg = Math.Abs(a[i + 1] - b[i + 1]);
            int db = Math.Abs(a[i + 2] - b[i + 2]);
            if (dr > tolerance || dg > tolerance || db > tolerance) n++;
        }
        return n;
    }

    /// <summary>Grabs a screen region with GDI and counts pixels of one colour.
    /// This is how the prototype proves that what the GPU drew really landed on
    /// the display, instead of trusting that the code "should" work.</summary>
    public static bool TryFindMagenta(int x, int y, int w, int h, out int hits)
    {
        hits = Capture(x, y, w, h, IsMagenta);
        return hits > 500;
    }

    private static int Capture(int x, int y, int w, int h, Func<byte, byte, byte, bool> match)
    {
        int hits = 0;
        if (w <= 0 || h <= 0) return 0;
        IntPtr screenDc = Native.GetDC(IntPtr.Zero);
        IntPtr memDc = Native.CreateCompatibleDC(screenDc);
        IntPtr bits = IntPtr.Zero;

        var bi = new Native.BITMAPINFO
        {
            bmiHeader = new Native.BITMAPINFOHEADER
            {
                biSize = Marshal.SizeOf<Native.BITMAPINFOHEADER>(),
                biWidth = w,
                biHeight = -h,          // top-down
                biPlanes = 1,
                biBitCount = 32,
                biCompression = (int)Native.BI_RGB,
            }
        };

        IntPtr dib = Native.CreateDIBSection(memDc, ref bi, Native.DIB_RGB_COLORS, out bits, IntPtr.Zero, 0);
        if (dib == IntPtr.Zero || bits == IntPtr.Zero)
        {
            Native.DeleteDC(memDc);
            Native.ReleaseDC(IntPtr.Zero, screenDc);
            return 0;
        }

        IntPtr old = Native.SelectObject(memDc, dib);
        Native.BitBlt(memDc, 0, 0, w, h, screenDc, x, y, Native.SRCCOPY);

        var buffer = new byte[w * h * 4];
        Marshal.Copy(bits, buffer, 0, buffer.Length);
        for (int i = 0; i < buffer.Length; i += 4)
        {
            // Buffer is BGRA order.
            if (match(buffer[i], buffer[i + 1], buffer[i + 2])) hits++;
        }

        Native.SelectObject(memDc, old);
        Native.DeleteObject(dib);
        Native.DeleteDC(memDc);
        Native.ReleaseDC(IntPtr.Zero, screenDc);

        return hits;
    }
}

internal static class Program
{
    /// <summary>
    /// 单实例用的命名互斥体。**必须是静态字段**：句柄一释放，"已经在跑"这个判断就没了。
    /// 进程退出时由系统自动放弃（不需要手动 ReleaseMutex）。
    /// </summary>
    private static System.Threading.Mutex s_single;

    [STAThread]
    private static int Main(string[] args)
    {
        // **WinExe 默认不带控制台**（双击时不该弹黑框），但自检 / 出图几乎全是从命令行跑的，
        // 那些 `Console.WriteLine` 不能一起丢掉。两边兼顾：**有参数时**试着接上父进程的控制台
        //（接不上说明是从资源管理器双击出来的，那正好——安静启动）。
        if (args.Length > 0) TryAttachParentConsole();

        // **单实例**：这个程序是一层全屏置顶的覆盖层。开两个的后果不是"多一个窗口"，
        // 而是：两层叠在一起（写字落到哪一层看运气）、第二个实例的热键注册不上、
        // **PPT 联动两边都在做**（互相抢着翻页、抢着往同一个文件写批注）。
        //
        // ⚠ 自检里的 `--clicktarget` 是**故意再起一个进程**当"下层窗口"用的
        //   （`--passtest` / `--uitest` 都靠它），那不是产品实例、也不能被拦——
        //   拦了那两条用例就没法跑了。所以它单独放行。
        //
        // **整段都放进 try 里**：单实例判断曾经写在 try 外面，它一旦抛异常（见
        // AcquireSingleInstance 里 abandoned 那段）就绕过了下面的 ReportFatal，
        // GUI 版（没有控制台）直接静默消失。
        try
        {
            bool isHelper = Array.IndexOf(args, "--clicktarget") >= 0;
            if (!isHelper && !AcquireSingleInstance()) return 0;
            return new App().Run(args);
        }
        catch (Exception ex)
        {
            // 没有控制台时，"FATAL: ..."这句话等于没写——落到盘上 + 弹一句，
            // 至少让用户知道"它出错了、详情在哪"（从命令行跑时控制台也照旧有）。
            Console.WriteLine("FATAL: " + ex);
            ReportFatal(ex);
            return 1;
        }
    }

    /// <summary>接上父进程的控制台并重开 stdout（见 Main 里那一段）。</summary>
    private static void TryAttachParentConsole()
    {
        try
        {
            if (!Native.AttachConsole(Native.ATTACH_PARENT_PROCESS)) return;
            Console.SetOut(new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = true });
            Console.SetError(new StreamWriter(Console.OpenStandardError()) { AutoFlush = true });
        }
        catch { /* 接不上就算了：不影响功能，只是看不到日志 */ }
    }

    /// <summary>
    /// 抢"唯一实例"。已经在跑 → 把那个实例的覆盖层窗口提到前面，返回 false。
    /// 用 `Local\` 前缀：**每个登录会话一个**（同一台机器两个用户各开一个互不打扰）。
    /// </summary>
    private static bool AcquireSingleInstance()
    {
        System.Threading.Mutex mutex;
        try
        {
            mutex = new System.Threading.Mutex(true, @"Local\InkTeach.SingleInstance", out bool first);
            if (first) { s_single = mutex; return true; }
        }
        catch (Exception ex)
        {
            // 互斥体本身建不出来（极少见）不该把软件拦死：按"没有别的实例"继续。
            Console.WriteLine("单实例互斥体创建失败，按“没有别的实例”继续：" + ex.Message);
            return true;
        }

        // 抢不到时**先等一小会儿再判**——"界面上的重启"那条路是"先起新进程、
        // 老进程随后才退"（见 Engine.RestartSelf：它 `_quit = true` 之后才走 Shutdown）。
        // 不等的话新进程一上来就看见互斥体还在老进程手里，直接退出——
        // 表现是"点了重启，软件没了"，而这是这类单实例保护最常见的坑。
        // 2 秒（每 50ms 试一次）对"老进程正在退"足够了；真的是"用户又双击了一次"，
        // 也就晚 2 秒看到那句提示，不影响什么。
        for (int i = 0; i < 40; i++)
        {
            try
            {
                if (mutex.WaitOne(50)) { s_single = mutex; return true; }
            }
            catch (System.Threading.AbandonedMutexException)
            {
                // **这一条就是"点了重启不回来"的真凶**（2026-09-28 修）：
                // 老进程退出时还攥着这个互斥体，内核把互斥体标记成 "abandoned"，
                // 于是这里的 WaitOne 不是返回 false，而是**抛 AbandonedMutexException**。
                // 抛异常 ≠ 没抢到：按 MSDN，异常抛出时等待已经满足、所有权已经转过来了
                // （"the wait is satisfied"）——所以当成"抢到了"继续启动才是对的。
                //
                // 之前没接这个异常：它一路冒到 Main 外面（那时单实例判断写在 try 之外），
                // GUI 版没有控制台、也没有 crash 日志，表现就是"老窗口关了、新窗口再也不出来"。
                s_single = mutex;
                return true;
            }
            catch (Exception ex)
            {
                // 其它意外也别把软件拦死（比如权限/句柄问题）。
                Console.WriteLine("单实例判断出错，按“没有别的实例”继续：" + ex.Message);
                return true;
            }
        }

        mutex.Dispose();
        Console.WriteLine("已经有 InkTeach 在运行了（单实例保护）：把它的窗口提到前面，这一个退出。");
        BringExistingToFront();
        return false;
    }

    /// <summary>
    /// 找到已经在跑的那个实例的窗口，把它激活。找不到就提示一句
    /// （覆盖层是透明的、还可能被贴边隐藏收成底部一条，用户多半以为"双击没反应"）。
    ///
    /// **认窗口靠"窗口类名前缀"，不靠标题**：实测从别的进程读这几个窗口的标题，
    /// 拿到的是 `"I"`（建窗口时那个名字被截成了一个字符，原因没深究——
    /// 那几个窗口都是 WS_EX_TOOLWINDOW，不进 Alt+Tab，标题本来也没人看），
    /// 而**类名读出来是完整的** `InkTeachOverlay_<guid>`（见 OverlayWindow 注册窗口类）。
    /// 同一批里还有两个"接输入小窗"（`Engine` 里建的界面面板 / PPT 条），
    /// 它们不算"实例的窗口"，所以按**面积挑最大的那张**——覆盖层是整块屏幕那块。
    /// </summary>
    private static void BringExistingToFront()
    {
        IntPtr found = IntPtr.Zero;
        long bestArea = 0;
        Native.EnumWindows((h, _) =>
        {
            var sb = new System.Text.StringBuilder(128);
            if (Native.GetClassNameW(h, sb, sb.Capacity) <= 0) return true;
            if (!sb.ToString().StartsWith("InkTeachOverlay_", StringComparison.Ordinal)) return true;

            if (!Native.GetWindowRect(h, out var r)) return true;
            long area = (long)Math.Max(0, r.Right - r.Left) * Math.Max(0, r.Bottom - r.Top);
            if (area > bestArea) { bestArea = area; found = h; }
            return true;
        }, IntPtr.Zero);

        if (found != IntPtr.Zero)
        {
            Native.SetForegroundWindow(found);
            return;
        }
        Native.MessageBoxW(IntPtr.Zero,
            "InkTeach 已经在运行了。\n\n它是一层透明的覆盖层，看屏幕底部中间那条工具条。",
            "InkTeach", Native.MB_OK);
    }

    /// <summary>崩溃时把详情写到盘上并弹一句（WinExe 双击启动时没有控制台可看）。</summary>
    private static void ReportFatal(Exception ex)
    {
        string path = "";
        try
        {
            path = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                "InkTeach", "last-crash.txt");
            Directory.CreateDirectory(Path.GetDirectoryName(path));
            File.WriteAllText(path, $"{DateTime.Now:yyyy-MM-dd HH:mm:ss}\n{ex}\n");
        }
        catch { }

        Native.MessageBoxW(IntPtr.Zero,
            "InkTeach 启动失败，已经退出。\n\n详情：" + (path.Length > 0 ? path : "（写日志也失败了）"),
            "InkTeach", Native.MB_OK | Native.MB_ICONERROR);
    }
}
